-- Consolidated Memoir baseline, including private games and scoped strategy rollout.
-- Apply only to a fresh/reset Supabase database.
-- Supabase supplies auth/storage schemas and anon/authenticated/service_role roles.
-- No historical imports or data backfills. Runtime RPCs contain their normal writes.
-- Tables use singular snake_case; user_ marks private, owner-scoped data.

begin;
set local check_function_bodies = false;
set local search_path = public;

revoke create on schema public from public;
grant usage on schema public to anon, authenticated, service_role;


-- Tables


CREATE TABLE public.user_memory_event (
    user_id uuid NOT NULL,
    project_id text NOT NULL,
    id text DEFAULT (gen_random_uuid())::text NOT NULL,
    revision bigint DEFAULT 1 NOT NULL,
    kind text NOT NULL,
    life_stage text DEFAULT 'unplaced'::text NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    data jsonb NOT NULL,
    change_sequence bigint NOT NULL,
    CONSTRAINT user_memory_event_kind_check CHECK ((kind = ANY (ARRAY['event'::text, 'period'::text]))),
    CONSTRAINT user_memory_event_life_stage_check CHECK ((life_stage = ANY (ARRAY['baby'::text, 'childhood'::text, 'adolescence'::text, 'young_adulthood'::text, 'midlife'::text, 'later_life'::text, 'unplaced'::text]))),
    CONSTRAINT user_memory_event_status_check CHECK ((status = ANY (ARRAY['active'::text, 'unresolved'::text, 'withdrawn'::text])))
);

CREATE TABLE public.user_formal_memoir_run (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    project_id text NOT NULL,
    conversation_id uuid NOT NULL,
    request_id uuid NOT NULL,
    locale text NOT NULL,
    base_revision bigint NOT NULL,
    phase_revision bigint NOT NULL,
    policy_epoch bigint NOT NULL,
    preference_revision bigint NOT NULL,
    source_revision bigint NOT NULL,
    event_revision bigint NOT NULL,
    plan_digest text DEFAULT ''::text NOT NULL,
    chapter_count integer DEFAULT 0 NOT NULL,
    state text DEFAULT 'pending'::text NOT NULL,
    token uuid,
    fence bigint DEFAULT 0 NOT NULL,
    lease_until timestamp with time zone,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT user_formal_memoir_run_state_check CHECK ((state = ANY (ARRAY['pending'::text, 'running'::text, 'completed'::text, 'stale'::text])))
);

CREATE TABLE public.user_interview_photo (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    project_id text NOT NULL,
    upload_key uuid,
    content_sha256 text,
    object_path text NOT NULL,
    content_type text NOT NULL,
    byte_size bigint NOT NULL,
    width integer NOT NULL,
    height integer NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT user_interview_photo_byte_size_check CHECK (((byte_size >= 1) AND (byte_size <= 10485760))),
    CONSTRAINT user_interview_photo_check CHECK (((width > 0) AND (height > 0) AND (((width)::bigint * height) <= 36000000))),
    CONSTRAINT user_interview_photo_content_type_check CHECK ((content_type = ANY (ARRAY['image/jpeg'::text, 'image/png'::text, 'image/webp'::text]))),
    CONSTRAINT user_interview_photo_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'ready'::text, 'deleted'::text])))
);

CREATE TABLE public.user_interview_turn (
    user_id uuid NOT NULL,
    project_id text NOT NULL,
    client_turn_id uuid NOT NULL,
    sequence bigint NOT NULL,
    source_id uuid,
    source_version bigint,
    source_sequence bigint NOT NULL,
    input_hash text NOT NULL,
    kind text NOT NULL,
    collector jsonb,
    interview_guidance_snapshot jsonb,
    guidance_plan_revision_seen bigint,
    photo_context jsonb DEFAULT '[]'::jsonb NOT NULL,
    consumed_photo_key text,
    consumed_photo_revision text,
    policy_epoch bigint NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    phase_revision bigint,
    CONSTRAINT user_interview_turn_phase_revision_check CHECK ((phase_revision >= 0))
);

CREATE TABLE public.user_memory_event_place (
    user_id uuid NOT NULL,
    project_id text NOT NULL,
    event_id text NOT NULL,
    source_id uuid NOT NULL,
    source_version bigint NOT NULL,
    char_start integer NOT NULL,
    char_end integer NOT NULL,
    role text NOT NULL,
    place jsonb NOT NULL,
    place_key text GENERATED ALWAYS AS (md5((place)::text)) STORED NOT NULL,
    CONSTRAINT user_memory_event_place_role_check CHECK ((role = ANY (ARRAY['setting'::text, 'origin'::text, 'destination'::text])))
);

CREATE TABLE public.user_lifetime_memory_obligation (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    conversation_id uuid NOT NULL,
    project_id text NOT NULL,
    kind text NOT NULL,
    dedup_key text NOT NULL,
    origin_id uuid NOT NULL,
    origin_hash text,
    source_id uuid,
    source_version bigint,
    policy_epoch bigint NOT NULL,
    source_revision bigint NOT NULL,
    execution_generation bigint NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    next_attempt_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    claim_token uuid,
    claim_expires_at timestamp with time zone,
    fence jsonb,
    error_code text,
    projection jsonb,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT user_lifetime_memory_obligation_attempts_check CHECK (((attempts >= 0) AND (attempts <= 5))),
    CONSTRAINT user_lifetime_memory_obligation_dedup_key_check CHECK (((length(dedup_key) >= 1) AND (length(dedup_key) <= 200))),
    CONSTRAINT user_lifetime_memory_obligation_error_code_check CHECK ((error_code = ANY (ARRAY['projection_failed'::text, 'storage_unavailable'::text, 'manifest_incomplete'::text, 'retry_exhausted'::text, 'stale_origin'::text]))),
    CONSTRAINT user_lifetime_memory_obligation_kind_check CHECK ((kind = ANY (ARRAY['source_projection'::text, 'reply_projection'::text]))),
    CONSTRAINT user_lifetime_memory_obligation_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'running'::text, 'retryable'::text, 'succeeded'::text, 'failed'::text, 'cancelled'::text, 'superseded'::text])))
);

CREATE TABLE public.user_lifetime_collection_job (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    snapshot_id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    project_id text NOT NULL,
    conversation_id uuid NOT NULL,
    kind text NOT NULL,
    title text NOT NULL,
    locale text NOT NULL,
    policy_epoch bigint NOT NULL,
    preference_revision bigint NOT NULL,
    collection_revision bigint NOT NULL,
    source_count integer NOT NULL,
    source_pages integer NOT NULL,
    next_page integer DEFAULT 0 NOT NULL,
    manifest_digest text NOT NULL,
    root_digest text NOT NULL,
    dedup_key text NOT NULL,
    state text DEFAULT 'QUEUED'::text NOT NULL,
    token uuid,
    lease_until timestamp with time zone,
    attempts integer DEFAULT 0 NOT NULL,
    error text,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT user_lifetime_collection_job_kind_check CHECK ((kind = ANY (ARRAY['BuildFreePreview'::text, 'BuildSourceExport'::text, 'BuildOutline'::text]))),
    CONSTRAINT user_lifetime_collection_job_state_check CHECK ((state = ANY (ARRAY['QUEUED'::text, 'RUNNING'::text, 'SUCCEEDED'::text, 'FAILED'::text, 'STALE'::text]))),
    CONSTRAINT user_lifetime_collection_job_title_check CHECK (((length(title) >= 1) AND (length(title) <= 200)))
);

CREATE TABLE public.user_lifetime_lane_snapshot (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
