    project_id text NOT NULL,
    conversation_id uuid NOT NULL,
    policy_epoch bigint NOT NULL,
    preference_revision bigint NOT NULL,
    privacy_digest text NOT NULL,
    locale text NOT NULL,
    source_high_water bigint NOT NULL,
    event_high_water bigint NOT NULL,
    round_high_water bigint NOT NULL,
    milestone bigint NOT NULL,
    base_revision bigint NOT NULL,
    predecessor uuid,
    base_event bigint DEFAULT 0 NOT NULL,
    last_source bigint DEFAULT 0 NOT NULL,
    next_offset integer DEFAULT 0 NOT NULL,
    last_event bigint DEFAULT 0 NOT NULL,
    last_event_id text DEFAULT ''::text NOT NULL,
    last_ref text DEFAULT ''::text NOT NULL,
    page_number bigint DEFAULT 0 NOT NULL,
    root_digest text NOT NULL,
    state text DEFAULT 'pending'::text NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    summary_source bigint DEFAULT 0 NOT NULL,
    summary_offset integer DEFAULT 0 NOT NULL,
    guidance_revision bigint DEFAULT 0 NOT NULL,
    guidance_news jsonb DEFAULT '{}'::jsonb NOT NULL,
    source_decision jsonb,
    CONSTRAINT user_lifetime_lane_snapshot_state_check CHECK ((state = ANY (ARRAY['pending'::text, 'completed'::text, 'proposed'::text, 'stale'::text])))
);

CREATE TABLE public.user_memoir_lane (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    project_id text NOT NULL,
    skill text NOT NULL,
    pending boolean DEFAULT true NOT NULL,
    target_source bigint DEFAULT 0 NOT NULL,
    target_event bigint DEFAULT 0 NOT NULL,
    target_milestone bigint DEFAULT 0 NOT NULL,
    successful_source bigint DEFAULT 0 NOT NULL,
    successful_event bigint DEFAULT 0 NOT NULL,
    successful_round bigint DEFAULT 0 NOT NULL,
    token uuid,
    lease_until timestamp with time zone,
    run_deadline timestamp with time zone,
    active_manifest jsonb DEFAULT '[]'::jsonb NOT NULL,
    active_through bigint,
    active_event bigint,
    active_round bigint,
    active_policy bigint,
    active_events jsonb DEFAULT '[]'::jsonb NOT NULL,
    active_milestone bigint,
    active_locale text,
    active_manuscript_revision bigint DEFAULT 0 NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    available_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    error text,
    guidance_revision bigint DEFAULT 0 NOT NULL,
    locale text DEFAULT 'en-AU'::text NOT NULL,
    CONSTRAINT user_memoir_lane_skill_check CHECK ((skill = ANY (ARRAY['timeline'::text, 'composer'::text, 'guidance'::text])))
);

CREATE TABLE public.user_narrator_source (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    project_id text NOT NULL,
    client_turn_id uuid NOT NULL,
    sequence bigint NOT NULL,
    version bigint DEFAULT 1 NOT NULL,
