    kind text NOT NULL,
    language text NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    processing_status text DEFAULT 'pending'::text NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT user_narrator_source_kind_check CHECK ((kind = ANY (ARRAY['narrator_chat'::text, 'narrator_transcript'::text]))),
    CONSTRAINT user_narrator_source_language_check CHECK ((language = ANY (ARRAY['en-AU'::text, 'zh-CN'::text]))),
    CONSTRAINT user_narrator_source_processing_status_check CHECK ((processing_status = ANY (ARRAY['pending'::text, 'succeeded'::text, 'retry'::text]))),
    CONSTRAINT user_narrator_source_status_check CHECK ((status = ANY (ARRAY['active'::text, 'withdrawn'::text]))),
    CONSTRAINT user_narrator_source_text_check CHECK (((length(text) >= 1) AND (length(text) <= 100000)))
);

CREATE TABLE public.user_original_recording (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid,
    project_id text,
    upload_project_id text,
    upload_key uuid NOT NULL,
    object_path text NOT NULL,
    content_type text NOT NULL,
    codec text NOT NULL,
    byte_size bigint NOT NULL,
    duration_seconds double precision NOT NULL,
    content_sha256 text NOT NULL,
    storage_status text DEFAULT 'pending'::text NOT NULL,
    transcription_status text DEFAULT 'not_started'::text NOT NULL,
    asr_result jsonb,
    lifecycle text DEFAULT 'draft'::text NOT NULL,
    cleanup_status text DEFAULT 'not_requested'::text NOT NULL,
    write_revision bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT user_original_recording_byte_size_check CHECK (((byte_size >= 1) AND (byte_size <= 10485760))),
    CONSTRAINT user_original_recording_cleanup_status_check CHECK ((cleanup_status = ANY (ARRAY['not_requested'::text, 'pending'::text, 'complete'::text]))),
    CONSTRAINT user_original_recording_content_sha256_check CHECK ((content_sha256 ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT user_original_recording_content_type_check CHECK ((content_type = ANY (ARRAY['audio/webm'::text, 'audio/mp4'::text, 'audio/ogg'::text, 'audio/wav'::text]))),
    CONSTRAINT user_original_recording_duration_seconds_check CHECK (((duration_seconds > (0)::double precision) AND (duration_seconds <= (300)::double precision))),
    CONSTRAINT user_original_recording_lifecycle_check CHECK ((lifecycle = ANY (ARRAY['draft'::text, 'attached'::text, 'deleted'::text]))),
    CONSTRAINT user_original_recording_storage_status_check CHECK ((storage_status = ANY (ARRAY['pending'::text, 'ready'::text, 'deleted'::text]))),
    CONSTRAINT user_original_recording_transcription_status_check CHECK ((transcription_status = ANY (ARRAY['not_started'::text, 'failed'::text, 'succeeded'::text])))
);

