    initial_rounds bigint[] DEFAULT ARRAY[(1)::bigint, (5)::bigint] NOT NULL,
    interval_rounds integer DEFAULT 10 NOT NULL,
    CONSTRAINT lifetime_profile_cadence_initial_rounds_check CHECK ((((array_length(initial_rounds, 1) >= 1) AND (array_length(initial_rounds, 1) <= 16)) AND (0 < ALL (initial_rounds)))),
    CONSTRAINT lifetime_profile_cadence_interval_rounds_check CHECK (((interval_rounds >= 1) AND (interval_rounds <= 1000))),
    CONSTRAINT lifetime_profile_cadence_singleton_check CHECK (singleton)
);

CREATE TABLE public.lifetime_two_lane_rollout (
    singleton boolean DEFAULT true NOT NULL,
