    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    stripe_price_id text,
    CONSTRAINT story_entitlement_amount_minor_check CHECK ((amount_minor >= 0)),
    CONSTRAINT story_entitlement_book_count_check CHECK ((book_count >= 0)),
    CONSTRAINT story_entitlement_status_check CHECK ((status = ANY (ARRAY['paid'::text, 'revoked'::text])))
);

