    CONSTRAINT user_family_context_document_check CHECK ((jsonb_typeof(document) = 'object'::text)),
    CONSTRAINT user_family_context_project_id_check CHECK (((char_length(project_id) >= 1) AND (char_length(project_id) <= 128))),
    CONSTRAINT user_family_context_revision_check CHECK ((revision >= 0))
);

