    CONSTRAINT user_lifetime_artifact_file_byte_count_check CHECK (((byte_count >= 0) AND (byte_count <= 134217728)))
);

CREATE TABLE public.user_lifetime_artifact_head (
    user_id uuid NOT NULL,
    conversation_id uuid NOT NULL,
    manifest_id text NOT NULL
);

CREATE TABLE public.user_lifetime_checkpoint (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    conversation_id uuid NOT NULL,
    predecessor_id uuid,
    fence jsonb NOT NULL,
    coverage_end bigint NOT NULL,
    model text NOT NULL,
    prompt_version text NOT NULL,
    pinned jsonb NOT NULL,
    manifest jsonb NOT NULL,
    evidence jsonb NOT NULL,
    published boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    coverage_proof_id uuid,
    lossless boolean DEFAULT false NOT NULL,
    memory_summary jsonb,
    CONSTRAINT user_lifetime_checkpoint_coverage_end_check CHECK ((coverage_end > 0)),
    CONSTRAINT user_lifetime_checkpoint_model_check CHECK (((length(model) >= 1) AND (length(model) <= 200))),
    CONSTRAINT user_lifetime_checkpoint_prompt_version_check CHECK (((length(prompt_version) >= 1) AND (length(prompt_version) <= 100)))
);

CREATE TABLE public.user_lifetime_chosen_name (
    user_id uuid NOT NULL,
    conversation_id uuid NOT NULL,
    project_id text NOT NULL,
    source_id uuid,
    source_version bigint,
    chosen_name text,
    authority text NOT NULL,
    CONSTRAINT user_lifetime_chosen_name_authority_check CHECK ((authority = ANY (ARRAY['generated'::text, 'invalidated'::text, 'explicit'::text]))),
    CONSTRAINT user_lifetime_chosen_name_check CHECK (((authority <> 'generated'::text) OR ((source_id IS NOT NULL) AND (source_version IS NOT NULL) AND (chosen_name IS NOT NULL)))),
    CONSTRAINT user_lifetime_chosen_name_check1 CHECK (((authority <> 'invalidated'::text) OR (chosen_name IS NULL))),
    CONSTRAINT user_lifetime_chosen_name_check2 CHECK (((authority <> 'explicit'::text) OR ((source_id IS NULL) AND (source_version IS NULL)))),
    CONSTRAINT user_lifetime_chosen_name_chosen_name_check CHECK (((chosen_name IS NULL) OR ((length(chosen_name) >= 1) AND (length(chosen_name) <= 120)))),
    CONSTRAINT user_lifetime_chosen_name_source_version_check CHECK ((source_version > 0))
);

CREATE TABLE public.user_lifetime_collection (
    user_id uuid NOT NULL,
    project_id text NOT NULL,
    revision bigint DEFAULT 0 NOT NULL,
    periods jsonb DEFAULT '{}'::jsonb NOT NULL,
    ready boolean DEFAULT false NOT NULL,
    source_revision bigint DEFAULT 0 NOT NULL,
    policy_epoch bigint NOT NULL,
    preference_revision bigint NOT NULL,
    source_fingerprint text
);

CREATE TABLE public.user_lifetime_collection_job_cursor (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    job_id uuid NOT NULL,
    user_id uuid NOT NULL,
    root_digest text NOT NULL,
    next_page integer NOT NULL,
    expires_at timestamp with time zone DEFAULT (clock_timestamp() + '01:00:00'::interval) NOT NULL
);

CREATE TABLE public.user_lifetime_collection_job_edge (
    job_id uuid NOT NULL,
    parent_node uuid NOT NULL,
    parent_section integer NOT NULL,
    child_node uuid NOT NULL,
    child_section integer NOT NULL
);

CREATE TABLE public.user_lifetime_collection_job_node (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    job_id uuid NOT NULL,
    ordinal integer NOT NULL,
    level integer NOT NULL,
    parent_id uuid,
    metadata jsonb NOT NULL,
    result jsonb NOT NULL,
    digest text NOT NULL,
    children uuid[] DEFAULT '{}'::uuid[] NOT NULL
);

CREATE TABLE public.user_lifetime_collection_job_page (
    job_id uuid NOT NULL,
    page_number integer NOT NULL,
    source_id uuid NOT NULL,
    source_version bigint NOT NULL,
    char_start integer NOT NULL,
    char_end integer NOT NULL,
    page_digest text NOT NULL,
    result jsonb
);

CREATE TABLE public.user_lifetime_collection_job_source (
    job_id uuid NOT NULL,
    ordinal integer NOT NULL,
    source_id uuid NOT NULL,
    source_version bigint NOT NULL,
    source_hash text NOT NULL,
    original_length integer NOT NULL,
    first_page integer NOT NULL,
    page_count integer NOT NULL
);

CREATE TABLE public.user_lifetime_collection_selection (
    user_id uuid NOT NULL,
    project_id text NOT NULL,
    source_id uuid NOT NULL,
    source_version bigint NOT NULL,
    source_hash text NOT NULL,
    ordinal integer NOT NULL
);

CREATE TABLE public.user_lifetime_compaction (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    conversation_id uuid NOT NULL,
    fence jsonb NOT NULL,
    predecessor_id uuid,
    starting_after bigint NOT NULL,
    through_sequence bigint NOT NULL,
    last_sequence bigint NOT NULL,
    last_offset integer DEFAULT '-1'::integer NOT NULL,
    revision bigint DEFAULT 0 NOT NULL,
    item_count bigint DEFAULT 0 NOT NULL,
    digest text DEFAULT ''::text NOT NULL,
    complete boolean DEFAULT false NOT NULL,
    pinned jsonb NOT NULL,
    summary_required boolean DEFAULT false NOT NULL,
    summary_initialized boolean DEFAULT false NOT NULL,
    summary_data jsonb DEFAULT '{"items": []}'::jsonb NOT NULL,
    summary_sequence bigint DEFAULT 0 NOT NULL,
    summary_offset integer DEFAULT '-1'::integer NOT NULL,
    summary_revision bigint DEFAULT 0 NOT NULL,
    summary_windows bigint DEFAULT 0 NOT NULL,
    summary_complete boolean DEFAULT false NOT NULL,
    summary_model text,
    CHECK (NOT summary_required OR coalesce(length(btrim(summary_model)),0)>0)
);

CREATE TABLE public.user_lifetime_continuity (
    user_id uuid NOT NULL,
    conversation_id uuid NOT NULL,
    record_id text NOT NULL,
    kind text NOT NULL,
    revision bigint NOT NULL,
    last_source_sequence bigint DEFAULT 0 NOT NULL,
    policy_epoch bigint NOT NULL,
    data jsonb NOT NULL,
    CONSTRAINT user_lifetime_continuity_data_check CHECK ((jsonb_typeof(data) = 'object'::text)),
    CONSTRAINT user_lifetime_continuity_kind_check CHECK ((kind = ANY (ARRAY['chosen_name'::text, 'language'::text, 'active_question'::text, 'unresolved_reference'::text, 'paused_topic'::text, 'excluded_topic'::text, 'commitment'::text, 'person'::text]))),
    CONSTRAINT user_lifetime_continuity_last_source_sequence_check CHECK ((last_source_sequence >= 0)),
    CONSTRAINT user_lifetime_continuity_policy_epoch_check CHECK ((policy_epoch > 0)),
    CONSTRAINT user_lifetime_continuity_record_id_check CHECK (((length(record_id) >= 1) AND (length(record_id) <= 128))),
    CONSTRAINT user_lifetime_continuity_revision_check CHECK ((revision > 0))
);

CREATE TABLE public.user_lifetime_conversation (
    conversation_id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    product text DEFAULT 'memoir'::text NOT NULL,
    project_id text NOT NULL,
    execution_generation bigint DEFAULT 1 NOT NULL,
    preference_revision bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    thread_id text,
    thread_policy_epoch bigint,
    thread_schema_version integer,
    thread_prompt_version text,
    thread_model text,
    checkpoint_id uuid,
    CONSTRAINT user_lifetime_conversation_execution_generation_check CHECK ((execution_generation > 0)),
    CONSTRAINT user_lifetime_conversation_preference_revision_check CHECK ((preference_revision >= 0)),
    CONSTRAINT user_lifetime_conversation_product_check CHECK ((product = 'memoir'::text))
);

CREATE TABLE public.user_lifetime_covered_evidence (
    maintenance_id uuid NOT NULL,
    sequence bigint NOT NULL,
    source_id uuid NOT NULL,
    version bigint NOT NULL,
    char_start integer NOT NULL,
    char_end integer NOT NULL,
    status text NOT NULL,
    content_sha256 text,
    kind text DEFAULT 'covered_evidence'::text NOT NULL,
    CONSTRAINT user_lifetime_covered_evidence_kind_check CHECK ((kind = 'covered_evidence'::text)),
    CONSTRAINT user_lifetime_covered_evidence_status_check CHECK ((status = ANY (ARRAY['active'::text, 'withdrawn'::text, 'superseded'::text])))
);

CREATE TABLE public.user_lifetime_draft_cursor (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    snapshot_id uuid NOT NULL,
    last_source bigint NOT NULL,
    last_offset integer NOT NULL,
    last_round bigint NOT NULL,
    sources_complete boolean NOT NULL
);

CREATE TABLE public.user_lifetime_draft_snapshot (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    event_id uuid NOT NULL,
    user_id uuid NOT NULL,
    project_id text NOT NULL,
    conversation_id uuid NOT NULL,
    policy_epoch bigint NOT NULL,
    preference_revision bigint NOT NULL,
    source_revision bigint NOT NULL,
    event_revision bigint NOT NULL,
    round_high_water bigint NOT NULL,
    completed bigint NOT NULL,
    locale text NOT NULL,
    coverage_schema_version integer DEFAULT 0 NOT NULL,
    base_snapshot_id uuid,
    source_after bigint DEFAULT 0 NOT NULL,
    round_after bigint DEFAULT 0 NOT NULL,
    round_revision bigint DEFAULT 0 NOT NULL,
    scan_complete boolean DEFAULT false NOT NULL,
    CONSTRAINT lifetime_draft_coverage_bounds CHECK ((((source_after >= 0) AND (source_after <= source_revision)) AND ((round_after >= 0) AND (round_after <= round_high_water)) AND (round_revision >= 0) AND ((base_snapshot_id IS NULL) = ((source_after = 0) AND (round_after = 0))) AND (base_snapshot_id IS DISTINCT FROM id))),
    CONSTRAINT user_lifetime_draft_snapshot_coverage_schema_version_check CHECK ((coverage_schema_version = ANY (ARRAY[0, 1])))
);

CREATE TABLE public.user_lifetime_interview_strategy (
    user_id uuid NOT NULL,
    project_id text NOT NULL,
    plan_revision bigint NOT NULL,
    shadow boolean NOT NULL,
    source_id uuid NOT NULL,
    source_version bigint NOT NULL,
    based_on_sequence bigint NOT NULL,
    policy_epoch bigint NOT NULL,
    preference_revision bigint NOT NULL,
    execution_generation bigint NOT NULL,
    phase_revision bigint NOT NULL,
    event_manifest jsonb NOT NULL,
    data jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL
);

CREATE TABLE public.user_lifetime_lane_output (
    snapshot_id uuid NOT NULL,
    page_number bigint NOT NULL,
    phase text NOT NULL,
    digest text NOT NULL,
    input_digest text NOT NULL,
    CONSTRAINT user_lifetime_lane_output_digest_check CHECK ((digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT user_lifetime_lane_output_input_digest_check CHECK ((input_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT user_lifetime_lane_output_phase_check CHECK ((phase = ANY (ARRAY['extract'::text, 'prepare'::text, 'index'::text, 'draft'::text, 'review'::text])))
);

CREATE TABLE public.user_lifetime_lane_page_receipt (
    snapshot_id uuid NOT NULL,
    page_number bigint NOT NULL,
    page_digest text NOT NULL,
    result_digest text NOT NULL,
    root_digest text NOT NULL,
    disposition text NOT NULL,
    continuity_digest text,
    CONSTRAINT user_lifetime_lane_continuity_digest_check CHECK
      (continuity_digest IS NULL OR continuity_digest ~ '^[a-f0-9]{64}$')
);

CREATE TABLE public.user_lifetime_memoir_cursor (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    snapshot_id uuid NOT NULL,
    user_id uuid NOT NULL,
