    CONSTRAINT user_lifetime_milestone_cursor_cadence_check CHECK (((cadence >= 1) AND (cadence <= 1000000))),
    CONSTRAINT user_lifetime_milestone_cursor_covered_milestone_check CHECK ((covered_milestone >= 0))
);

