    CONSTRAINT user_lifetime_place_journey_journeys_check CHECK (((jsonb_typeof(journeys) = 'array'::text) AND (jsonb_array_length(journeys) <= 8) AND (octet_length((journeys)::text) <= 8192)))
);

CREATE TABLE public.user_lifetime_policy_inventory_pending (
    user_id uuid NOT NULL,
    project_id text NOT NULL,
    conversation_id uuid NOT NULL,
    parser_version text NOT NULL,
    CONSTRAINT user_lifetime_policy_inventory_pending_parser_version_check CHECK ((parser_version = 'semantic-v1'::text))
);

