    CONSTRAINT user_lifetime_profile_dependency_field_check CHECK ((field = ANY (ARRAY['name'::text, 'birth_year'::text, 'birth_date_expression'::text, 'birth_place'::text, 'childhood_place'::text, 'avatar_style'::text])))
);

