    expires_at timestamp with time zone DEFAULT (clock_timestamp() + '1 day'::interval) NOT NULL
);

CREATE TABLE public.user_lifetime_source_extraction (
    user_id uuid NOT NULL,
    project_id text NOT NULL,
    source_id uuid NOT NULL,
    source_version bigint NOT NULL,
    next_offset integer NOT NULL
);

CREATE TABLE public.user_lifetime_source_inventory (
    user_id uuid NOT NULL,
    project_id text NOT NULL,
    record_count bigint NOT NULL,
    max_sequence bigint NOT NULL,
    CONSTRAINT user_lifetime_source_inventory_max_sequence_check CHECK ((max_sequence >= 0)),
    CONSTRAINT user_lifetime_source_inventory_record_count_check CHECK ((record_count >= 0))
);

CREATE TABLE public.user_lifetime_source_policy_receipt (
    user_id uuid NOT NULL,
    project_id text NOT NULL,
    conversation_id uuid NOT NULL,
    source_id uuid NOT NULL,
    source_version bigint NOT NULL,
    parser_version text NOT NULL,
    review jsonb NOT NULL,
    CONSTRAINT user_lifetime_source_policy_receipt_parser_version_check CHECK ((parser_version = 'semantic-v1'::text)),
    CONSTRAINT user_lifetime_source_policy_receipt_source_version_check CHECK ((source_version > 0))
);

CREATE TABLE public.user_lifetime_source_position (
