    source_manifest jsonb NOT NULL,
    event_manifest jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    lifetime_snapshot_id uuid,
    lifetime_page bigint,
    lifetime_policy bigint,
    lifetime_preference bigint,
    lifetime_input_digest text,
    CONSTRAINT user_memoir_checkpoint_kind_check CHECK ((kind = ANY (ARRAY['prepare'::text, 'compose'::text])))
);

CREATE TABLE public.user_memoir_edition (
    user_id uuid NOT NULL,
    project_id text NOT NULL,
    locale text NOT NULL,
    revision bigint DEFAULT 0 NOT NULL,
    covered_round bigint DEFAULT 0 NOT NULL,
    source_sequence bigint DEFAULT 0 NOT NULL,
    event_sequence bigint DEFAULT 0 NOT NULL,
    completed_milestone bigint DEFAULT 0 NOT NULL,
    human_locked boolean DEFAULT false NOT NULL
);

CREATE TABLE public.user_memoir_milestone (
    user_id uuid NOT NULL,
    project_id text NOT NULL,
    locale text NOT NULL,
    milestone bigint NOT NULL,
    state text DEFAULT 'pending'::text NOT NULL,
    covered_round bigint,
    manuscript_revision bigint,
    CONSTRAINT user_memoir_milestone_milestone_check CHECK ((milestone > 0)),
    CONSTRAINT user_memoir_milestone_state_check CHECK ((state = ANY (ARRAY['pending'::text, 'completed'::text, 'proposed'::text])))
);

CREATE TABLE public.user_memoir_project (
    user_id uuid NOT NULL,
    project_id text NOT NULL,
    source_sequence bigint DEFAULT 0 NOT NULL,
    event_sequence bigint DEFAULT 0 NOT NULL,
    extraction_cursor bigint DEFAULT 0 NOT NULL,
    policy_epoch bigint DEFAULT 1 NOT NULL,
    interview_sequence bigint DEFAULT 0 NOT NULL,
    draft_revision bigint DEFAULT 0 NOT NULL,
    draft_round_epoch bigint DEFAULT 0 NOT NULL,
    attribution_revision bigint DEFAULT 0 NOT NULL,
    CONSTRAINT user_memoir_project_project_id_check CHECK ((project_id ~ '^[A-Za-z0-9][A-Za-z0-9_-]{0,127}$'::text))
);

CREATE TABLE public.user_memory (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    kind text NOT NULL,
    content text NOT NULL,
    source_paths text[] DEFAULT '{}'::text[] NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    source_sequence bigint DEFAULT 0 NOT NULL,
    project_id text,
    client_turn_id uuid,
    life_stage text DEFAULT 'unplaced'::text NOT NULL,
    life_stage_order smallint GENERATED ALWAYS AS (
CASE life_stage
    WHEN 'baby'::text THEN 0
    WHEN 'childhood'::text THEN 1
    WHEN 'adolescence'::text THEN 2
    WHEN 'young_adulthood'::text THEN 3
    WHEN 'midlife'::text THEN 4
    WHEN 'later_life'::text THEN 5
    ELSE 6
END) STORED,
    CONSTRAINT user_memory_kind_check CHECK ((kind = ANY (ARRAY['agent'::text, 'memoir'::text, 'agent_greeting'::text]))),
    CONSTRAINT user_memory_life_stage_check CHECK ((life_stage = ANY (ARRAY['baby'::text, 'childhood'::text, 'adolescence'::text, 'young_adulthood'::text, 'midlife'::text, 'later_life'::text, 'unplaced'::text])))
);

CREATE TABLE public.user_memory_attribution_receipt (
    snapshot_id uuid NOT NULL,
    page_number bigint NOT NULL,
    page_digest text NOT NULL,
    result_digest text NOT NULL
);

CREATE TABLE public.user_memory_attribution_window (
    user_id uuid NOT NULL,
    project_id text NOT NULL,
    source_id uuid NOT NULL,
    source_version bigint NOT NULL,
    char_start integer NOT NULL,
    char_end integer NOT NULL,
    policy_epoch bigint NOT NULL,
    disposition text NOT NULL,
    reason text NOT NULL,
    method text DEFAULT 'model'::text NOT NULL,
    CONSTRAINT user_memory_attribution_window_char_start_check CHECK ((char_start >= 0)),
    CONSTRAINT user_memory_attribution_window_check CHECK ((char_end > char_start)),
    CONSTRAINT user_memory_attribution_window_disposition_check CHECK ((disposition = ANY (ARRAY['unresolved'::text, 'non_story'::text, 'withheld'::text]))),
    CONSTRAINT user_memory_attribution_window_method_check CHECK ((method = ANY (ARRAY['model'::text, 'rule'::text])))
);

CREATE TABLE public.user_memory_delivered_context (
    user_id uuid NOT NULL,
    project_id text NOT NULL,
    source_id uuid NOT NULL,
    source_version bigint NOT NULL,
    client_turn_id uuid NOT NULL,
    reply_id uuid NOT NULL,
    policy_epoch bigint NOT NULL,
    execution_generation bigint NOT NULL,
    preference_revision bigint NOT NULL,
    event_id text,
    event_revision bigint
);

