    user_id uuid NOT NULL,
    project_id text NOT NULL,
    sequence bigint NOT NULL,
    event_id text NOT NULL,
    old_group jsonb,
    new_group jsonb NOT NULL,
    revision bigint NOT NULL
);

CREATE TABLE public.user_memory_event_revision (
    user_id uuid NOT NULL,
    project_id text NOT NULL,
    event_id text NOT NULL,
    revision bigint NOT NULL,
    record jsonb NOT NULL,
    actor text NOT NULL,
    origin text NOT NULL
);

CREATE TABLE public.user_memory_event_source (
    user_id uuid NOT NULL,
    project_id text NOT NULL,
    event_id text NOT NULL,
    source_id uuid NOT NULL,
    source_version bigint NOT NULL,
    evidence_hash text NOT NULL,
    evidence jsonb NOT NULL,
    stage_progress_role text DEFAULT 'dependency'::text NOT NULL,
    CONSTRAINT user_memory_event_source_stage_progress_role_check CHECK ((stage_progress_role = ANY (ARRAY['legacy'::text, 'legacy_primary'::text, 'legacy_stage'::text, 'primary'::text, 'stage'::text, 'dependency'::text])))
);

CREATE TABLE public.user_memory_event_source_exclusion (
    user_id uuid NOT NULL,
    project_id text NOT NULL,
    event_id text NOT NULL,
    source_id uuid NOT NULL,
    actor uuid NOT NULL,
    statement text NOT NULL,
    expected_revision bigint NOT NULL
);

CREATE TABLE public.user_memory_reply_context (
