    source_id uuid NOT NULL,
    source_version bigint NOT NULL,
    prior_source_id uuid NOT NULL
);

CREATE TABLE public.user_narrator_source_version (
    user_id uuid NOT NULL,
    project_id text NOT NULL,
    source_id uuid NOT NULL,
    version bigint NOT NULL,
    text text NOT NULL,
    language text NOT NULL,
    attribution jsonb DEFAULT '{"role": "storyteller"}'::jsonb NOT NULL
);

CREATE TABLE public.user_original_recording_cancel (
    user_id uuid NOT NULL,
    upload_key uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL
);

CREATE TABLE public.user_original_recording_transfer (
    attachment_id uuid NOT NULL,
    user_id uuid NOT NULL
);

CREATE TABLE public.user_original_recording_upload (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    recording_id uuid NOT NULL,
    finished_at timestamp with time zone
);

CREATE TABLE public.user_place_journey (
    user_id uuid NOT NULL,
    schema_version integer DEFAULT 1 NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    revision bigint DEFAULT 1 NOT NULL,
    place text NOT NULL,
    hierarchy jsonb NOT NULL,
    granularity text NOT NULL,
    latitude double precision,
    longitude double precision,
    duration_ms integer DEFAULT 5200 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    source_sequence bigint DEFAULT 0 NOT NULL,
    CONSTRAINT user_place_journey_check CHECK ((((latitude IS NULL) AND (longitude IS NULL)) OR ((latitude IS NOT NULL) AND (longitude IS NOT NULL)))),
    CONSTRAINT user_place_journey_duration_ms_check CHECK (((duration_ms >= 2800) AND (duration_ms <= 9000))),
    CONSTRAINT user_place_journey_granularity_check CHECK ((granularity = ANY (ARRAY['country'::text, 'region'::text, 'city'::text, 'suburb'::text, 'landmark'::text]))),
    CONSTRAINT user_place_journey_hierarchy_check CHECK (((jsonb_typeof(hierarchy) = 'array'::text) AND ((jsonb_array_length(hierarchy) >= 1) AND (jsonb_array_length(hierarchy) <= 6)) AND ((hierarchy ->> 0) = 'Earth'::text))),
    CONSTRAINT user_place_journey_latitude_check CHECK (((latitude IS NULL) OR ((latitude >= ('-90'::integer)::double precision) AND (latitude <= (90)::double precision)))),
    CONSTRAINT user_place_journey_longitude_check CHECK (((longitude IS NULL) OR ((longitude >= ('-180'::integer)::double precision) AND (longitude <= (180)::double precision)))),
    CONSTRAINT user_place_journey_place_check CHECK (((char_length(btrim(place)) >= 1) AND (char_length(btrim(place)) <= 120))),
    CONSTRAINT user_place_journey_revision_check CHECK ((revision > 0)),
    CONSTRAINT user_place_journey_schema_version_check CHECK ((schema_version = 1)),
    CONSTRAINT user_place_journey_status_check CHECK ((status = 'active'::text))
);

CREATE TABLE public.user_private_draft_outbox (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    project_id text NOT NULL,
    memory_id uuid,
    change_kind text NOT NULL,
    delivered boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT user_private_draft_outbox_change_kind_check CHECK ((change_kind = ANY (ARRAY['round'::text, 'edit'::text, 'delete'::text, 'assignment'::text, 'accepted'::text, 'events'::text, 'correction'::text, 'revocation'::text])))
);

CREATE TABLE public.user_profile (
    user_id uuid NOT NULL,
    profile jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    agent_source_sequences jsonb DEFAULT '{}'::jsonb NOT NULL
);

CREATE TABLE public.user_recall_usage (
    user_id uuid NOT NULL,
    rounds_completed bigint DEFAULT 0 NOT NULL,
    CONSTRAINT user_recall_usage_rounds_completed_check CHECK ((rounds_completed >= 0))
);

CREATE TABLE public.user_shared_memoir_transfer (
    conversation_id uuid NOT NULL,
    user_id uuid NOT NULL,
    project_id text NOT NULL,
    event_id_map jsonb NOT NULL,
    source_id_map jsonb NOT NULL
);

CREATE TABLE public.user_source_recording (
    user_id uuid NOT NULL,
    project_id text NOT NULL,
    source_id uuid NOT NULL,
    source_version bigint NOT NULL,
    client_turn_id uuid NOT NULL,
    recording_id uuid NOT NULL,
    "position" integer NOT NULL,
    CONSTRAINT user_source_recording_position_check CHECK ((("position" >= 0) AND ("position" <= 19)))
);

CREATE TABLE public.user_story_game_consent (
    edition_id uuid NOT NULL,
    user_id uuid NOT NULL,
    project_id text NOT NULL,
    revision bigint NOT NULL,
    status text NOT NULL,
    policy_epoch bigint NOT NULL,
    purpose text DEFAULT 'game_adaptation'::text NOT NULL,
    audience text DEFAULT 'private'::text NOT NULL,
    CONSTRAINT user_story_game_consent_audience_check CHECK ((audience = 'private'::text)),
    CONSTRAINT user_story_game_consent_purpose_check CHECK ((purpose = 'game_adaptation'::text)),
    CONSTRAINT user_story_game_consent_status_check CHECK ((status = ANY (ARRAY['active'::text, 'revoked'::text])))
);

CREATE TABLE public.user_ui_locale_preference (
    user_id uuid NOT NULL,
    locale text NOT NULL,
    source text NOT NULL,
    revision bigint DEFAULT 1 NOT NULL,
    CONSTRAINT user_ui_locale_preference_locale_check CHECK ((locale = ANY (ARRAY['en-AU'::text, 'zh-CN'::text]))),
    CONSTRAINT user_ui_locale_preference_revision_check CHECK ((revision > 0)),
    CONSTRAINT user_ui_locale_preference_source_check CHECK ((source = ANY (ARRAY['manual'::text, 'first_reply'::text])))
);


