-- Functions


CREATE FUNCTION public.accept_recorded_interview_turn(p_two_lane boolean, p_project_id text, p_client_turn_id uuid, p_text text, p_kind text, p_language text, p_uploaded_photo_ids jsonb, p_photo_selection jsonb, p_recording_ids jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb; r public.user_original_recording%rowtype; identifier text; index integer:=0; saved jsonb; prior public.user_interview_turn%rowtype;
begin
 if jsonb_typeof(p_recording_ids) is distinct from 'array' or jsonb_array_length(p_recording_ids)>20 then raise exception 'invalid recording list';end if;
 if (select count(*)<>count(distinct value) from jsonb_array_elements_text(p_recording_ids)) then raise exception 'duplicate recording reference';end if;
 if jsonb_array_length(p_recording_ids)>0 then
   perform 1 from auth.users where id=auth.uid() for share;
 end if;
 perform 1 from public.user_memoir_project where user_id=auth.uid() and project_id=p_project_id for update;
 select * into prior from public.user_interview_turn where user_id=auth.uid() and project_id=p_project_id and client_turn_id=p_client_turn_id;
 if found then
   select coalesce(jsonb_agg(recording_id::text order by position),'[]') into saved from public.user_source_recording
     where user_id=auth.uid() and project_id=p_project_id and client_turn_id=p_client_turn_id;
   if saved is distinct from p_recording_ids or prior.input_hash is distinct from md5(p_text) or prior.kind is distinct from p_kind then
     raise exception 'input revision conflict' using errcode='40001';end if;
   -- Replaying the same accepted input still wakes B at the latest project
   -- frontier. Do not attach/revalidate deleted audio or allocate a source.
   if p_two_lane and exists(select 1 from public.lifetime_two_lane_rollout where singleton and enabled) then
     insert into public.user_memoir_lane(user_id,project_id,skill,pending,target_source,target_event)
     select auth.uid(),p_project_id,'timeline',true,source_sequence,event_sequence from public.user_memoir_project
       where user_id=auth.uid() and project_id=p_project_id
     on conflict(user_id,project_id,skill) do update set pending=true,
       target_source=greatest(user_memoir_lane.target_source,excluded.target_source),
       target_event=greatest(user_memoir_lane.target_event,excluded.target_event),
       attempts=case when excluded.target_source>user_memoir_lane.target_source then 0 else user_memoir_lane.attempts end;
   end if;
   return public.read_user_interview_turn(p_project_id,p_client_turn_id);
 end if;
 if jsonb_array_length(p_recording_ids)>0 then
   if p_kind<>'narrator_transcript' or length(btrim(p_text))=0 then raise exception 'recorded narration required';end if;
   for identifier in select value from jsonb_array_elements_text(p_recording_ids) loop
     select * into r from public.user_original_recording where id=identifier::uuid for update;
     if not found or not public.original_recording_visible(r,auth.uid()) or r.storage_status<>'ready'
       or r.lifecycle<>'draft' or r.project_id is not null and r.project_id<>p_project_id then
       raise exception 'recording unavailable' using errcode='42501';end if;
   end loop;
   if (select sum(duration_seconds) from public.user_original_recording
     where id in (select value::uuid from jsonb_array_elements_text(p_recording_ids)))>300 then
     raise exception 'combined recording duration exceeds five minutes' using errcode='PT413';end if;
 end if;
 if p_two_lane then result:=public.accept_two_lane_interview_turn_before_recordings(p_project_id,p_client_turn_id,p_text,p_kind,p_language,p_uploaded_photo_ids,p_photo_selection);
 else result:=public.accept_user_interview_turn_before_recordings(p_project_id,p_client_turn_id,p_text,p_kind,p_language,p_uploaded_photo_ids,p_photo_selection);end if;
 for identifier in select value from jsonb_array_elements_text(p_recording_ids) loop
   insert into public.user_source_recording values(auth.uid(),p_project_id,(result->'source'->>'id')::uuid,
     (result->'source'->>'version')::bigint,p_client_turn_id,identifier::uuid,index);
   update public.user_original_recording set project_id=p_project_id,lifecycle='attached' where id=identifier::uuid;
   index:=index+1;
 end loop;
 return public.read_user_interview_turn(p_project_id,p_client_turn_id);
end $$;

CREATE FUNCTION public.accept_two_lane_interview_turn(p_project_id text, p_client_turn_id uuid, p_text text, p_kind text DEFAULT 'narrator_chat'::text, p_language text DEFAULT 'en-AU'::text, p_uploaded_photo_ids jsonb DEFAULT '[]'::jsonb, p_photo_selection jsonb DEFAULT NULL::jsonb, p_recording_ids jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select public.accept_recorded_interview_turn(true,p_project_id,p_client_turn_id,p_text,p_kind,p_language,p_uploaded_photo_ids,p_photo_selection,p_recording_ids)
$$;

CREATE FUNCTION public.accept_two_lane_interview_turn_before_recordings(p_project_id text, p_client_turn_id uuid, p_text text, p_kind text DEFAULT 'narrator_chat'::text, p_language text DEFAULT 'en-AU'::text, p_uploaded_photo_ids jsonb DEFAULT '[]'::jsonb, p_photo_selection jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare result jsonb; identity public.user_lifetime_conversation%rowtype;
begin
 perform 1 from public.lifetime_two_lane_rollout where singleton and enabled for share;
 if not found then raise exception 'two lane rollout is disabled' using errcode='55000';end if;
 select * into identity from public.user_lifetime_conversation where user_id=auth.uid() and project_id=p_project_id;
 if not found then raise exception 'canonical conversation required' using errcode='42501';end if;
 perform 1 from public.user_memoir_project where user_id=auth.uid() and project_id=p_project_id for update;
 -- A saved source is not a saved reply. Require reconciliation of an unfinished
 -- active turn; neither a disconnect nor a failed save permits a competing turn.
 if exists(select 1 from public.user_interview_turn t join public.user_narrator_source s
   on s.user_id=t.user_id and s.project_id=t.project_id and s.id=t.source_id and s.status='active'
   where t.user_id=auth.uid() and t.project_id=p_project_id and t.client_turn_id<>p_client_turn_id
   and not exists(select 1 from public.user_lifetime_reply r where r.user_id=t.user_id
     and r.conversation_id=identity.conversation_id and r.client_turn_id=t.client_turn_id)) then
   raise exception 'saved source has a pending reply; retry its original turn' using errcode='PT409';
 end if;
 result:=public.accept_user_interview_turn(p_project_id,p_client_turn_id,p_text,p_kind,p_language,p_uploaded_photo_ids,p_photo_selection);
 insert into public.user_lifetime_two_lane_source values(auth.uid(),p_project_id,(result->'source'->>'id')::uuid) on conflict do nothing;
 -- Intent is durable before any collector call. Existing receipt dispatch also
 -- schedules composition; this target only wakes the existing memory owner.
 insert into public.user_memoir_lane(user_id,project_id,skill,pending,target_source,target_event)
 select auth.uid(),p_project_id,'timeline',true,source_sequence,event_sequence from public.user_memoir_project
 where user_id=auth.uid() and project_id=p_project_id
 on conflict(user_id,project_id,skill) do update set pending=true,
   target_source=greatest(user_memoir_lane.target_source,excluded.target_source),
   target_event=greatest(user_memoir_lane.target_event,excluded.target_event),
   attempts=case when excluded.target_source>user_memoir_lane.target_source then 0 else user_memoir_lane.attempts end;
 return result;
end $$;

CREATE FUNCTION public.accept_user_interview_turn(p_project_id text, p_client_turn_id uuid, p_text text, p_kind text DEFAULT 'narrator_chat'::text, p_language text DEFAULT 'en-AU'::text, p_uploaded_photo_ids jsonb DEFAULT '[]'::jsonb, p_photo_selection jsonb DEFAULT NULL::jsonb, p_recording_ids jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select public.accept_recorded_interview_turn(false,p_project_id,p_client_turn_id,p_text,p_kind,p_language,p_uploaded_photo_ids,p_photo_selection,p_recording_ids)
$$;

CREATE FUNCTION public.accept_user_interview_turn_before_pending_guard(p_project_id text, p_client_turn_id uuid, p_text text, p_kind text DEFAULT 'narrator_chat'::text, p_language text DEFAULT 'en-AU'::text, p_uploaded_photo_ids jsonb DEFAULT '[]'::jsonb, p_photo_selection jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 return public.accept_user_interview_turn_before_phase(p_project_id,p_client_turn_id,p_text,p_kind,p_language,
   p_uploaded_photo_ids,p_photo_selection);
end
$$;

CREATE FUNCTION public.accept_user_interview_turn_before_phase(p_project_id text, p_client_turn_id uuid, p_text text, p_kind text DEFAULT 'narrator_chat'::text, p_language text DEFAULT 'en-AU'::text, p_uploaded_photo_ids jsonb DEFAULT '[]'::jsonb, p_photo_selection jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $memoir$
declare v_owner uuid:=auth.uid(); project public.user_memoir_project%rowtype; saved public.user_interview_turn%rowtype;
  source jsonb; v_profile jsonb; state jsonb; selected jsonb; context jsonb:='[]'; photo public.user_interview_photo%rowtype;
  identifier text; selected_key text; selected_revision text; next_sequence bigint;
begin
  if v_owner is null then raise exception 'authenticated user required' using errcode='42501'; end if;
  if p_project_id is null or p_project_id !~ '^[A-Za-z0-9][A-Za-z0-9_-]{0,127}$' or p_client_turn_id is null or
    p_text is null or length(p_text)>100000 or p_kind not in ('narrator_chat','narrator_transcript') or
    p_language not in ('en-AU','zh-CN') or jsonb_typeof(p_uploaded_photo_ids) is distinct from 'array' or
    jsonb_array_length(p_uploaded_photo_ids)>5 then raise exception 'invalid interview input' using errcode='22023'; end if;
  insert into public.user_memoir_project(user_id,project_id) values(v_owner,p_project_id) on conflict do nothing;
  select * into project from public.user_memoir_project where user_id=v_owner and project_id=p_project_id for update;
  select * into saved from public.user_interview_turn where user_id=v_owner and project_id=p_project_id and client_turn_id=p_client_turn_id;
  if found then
    if saved.input_hash is distinct from md5(p_text) or saved.kind is distinct from p_kind then
      raise exception 'input revision conflict; retry with the original input' using errcode='PT409'; end if;
    return public.interview_turn_record(saved);
  end if;
  select p.profile into v_profile from public.user_profile p where user_id=v_owner for update;
  state:=coalesce(v_profile->'photo_memories'->p_project_id,'{}');
  selected_key:=state->>'selected'; selected_revision:=state->>'selection_revision';
  -- Explicit null means no public cue. Never silently consume another tab's
  -- selection. A legacy missing revision is accepted only with matching null.
  if p_photo_selection is not null and p_photo_selection<>'null'::jsonb then
    if jsonb_typeof(p_photo_selection) is distinct from 'object' or
      p_photo_selection->>'key' is distinct from selected_key or
      p_photo_selection->>'revision' is distinct from selected_revision or selected_key is null then
      raise exception 'photo selection changed; reload the cue' using errcode='PT409'; end if;
    select value into selected from jsonb_array_elements(coalesce(state->'favorites','[]')) where value->>'key'=selected_key;
    if selected is null then raise exception 'photo selection changed; reload the cue' using errcode='PT409'; end if;
    context:=jsonb_build_array(selected || jsonb_build_object('kind','public_reference','photo_id','reference:' || md5(selected_key)));
    state:=jsonb_set(state,'{selected}','null');
    v_profile:=jsonb_set(v_profile,array['photo_memories',p_project_id],state);
    update public.user_profile p set profile=v_profile where p.user_id=v_owner;
  else selected_key:=null; selected_revision:=null;
  end if;
  for identifier in select distinct value from jsonb_array_elements_text(p_uploaded_photo_ids) loop
    select * into photo from public.user_interview_photo where user_id=v_owner and project_id=p_project_id and id=identifier::uuid and status='ready';
    if not found then raise exception 'photo unavailable' using errcode='42501'; end if;
    context:=context || jsonb_build_array(public.interview_photo_card(photo));
  end loop;
  if length(btrim(p_text))=0 and context='[]'::jsonb then raise exception 'a narrative or photo cue is required' using errcode='22023'; end if;
  if length(btrim(p_text))>0 then
    source:=public.accept_user_narrator_source(p_project_id,p_client_turn_id,p_text,p_kind,p_language);
  end if;
  update public.user_memoir_project set interview_sequence=interview_sequence+1
    where user_id=v_owner and project_id=p_project_id returning * into project;
  insert into public.user_interview_turn(user_id,project_id,client_turn_id,sequence,source_id,source_version,source_sequence,
    input_hash,kind,photo_context,consumed_photo_key,consumed_photo_revision,policy_epoch)
    values(v_owner,p_project_id,p_client_turn_id,project.interview_sequence,(source->>'id')::uuid,(source->>'version')::bigint,
      project.source_sequence,md5(p_text),p_kind,context,selected_key,selected_revision,project.policy_epoch) returning * into saved;
  return public.interview_turn_record(saved);
end $memoir$;

CREATE FUNCTION public.accept_user_interview_turn_before_recordings(p_project_id text, p_client_turn_id uuid, p_text text, p_kind text DEFAULT 'narrator_chat'::text, p_language text DEFAULT 'en-AU'::text, p_uploaded_photo_ids jsonb DEFAULT '[]'::jsonb, p_photo_selection jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare identity public.user_lifetime_conversation%rowtype;
begin
 select * into identity from public.user_lifetime_conversation where user_id=auth.uid() and project_id=p_project_id;
 if found then
   perform 1 from public.user_memoir_project where user_id=auth.uid() and project_id=p_project_id for update;
   if exists(select 1 from public.user_interview_turn t join public.user_narrator_source s
     on s.user_id=t.user_id and s.project_id=t.project_id and s.id=t.source_id and s.status='active'
     where t.user_id=auth.uid() and t.project_id=p_project_id and t.client_turn_id<>p_client_turn_id
       and not exists(select 1 from public.user_lifetime_reply r where r.user_id=t.user_id
         and r.conversation_id=identity.conversation_id and r.client_turn_id=t.client_turn_id)) then
     raise exception 'saved source has a pending reply; retry its original turn' using errcode='PT409';
   end if;
 end if;
 return public.accept_user_interview_turn_before_pending_guard(p_project_id,p_client_turn_id,p_text,p_kind,p_language,p_uploaded_photo_ids,p_photo_selection);
end $$;

CREATE FUNCTION public.accept_user_narrator_source(p_project_id text, p_client_turn_id uuid, p_text text, p_kind text DEFAULT 'narrator_chat'::text, p_language text DEFAULT 'en-AU'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb; prior text:=current_setting('memoir.news_source_accept',true);
begin
 perform set_config('memoir.news_source_accept','1',true);
 result:=public.accept_user_narrator_source_before_news(p_project_id,p_client_turn_id,p_text,p_kind,p_language);
 perform set_config('memoir.news_source_accept',coalesce(prior,''),true);
 return result;
exception when others then
 perform set_config('memoir.news_source_accept',coalesce(prior,''),true);
 raise;
end $$;

CREATE FUNCTION public.accept_user_narrator_source_record(p_project_id text, p_client_turn_id uuid, p_text text, p_kind text DEFAULT 'narrator_chat'::text, p_language text DEFAULT 'en-AU'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $memoir$
declare owner_id uuid:=auth.uid(); saved public.user_narrator_source%rowtype; next_sequence bigint;
begin
  if owner_id is null then raise exception 'authenticated user required' using errcode='42501'; end if;
  if p_project_id is null or p_project_id !~ '^[A-Za-z0-9][A-Za-z0-9_-]{0,127}$' or
     p_client_turn_id is null or p_text is null or length(pg_catalog.btrim(p_text))=0 or length(p_text)>100000 or
     p_kind not in ('narrator_chat','narrator_transcript') or p_language not in ('en-AU','zh-CN') then
    raise exception 'invalid narrator source' using errcode='22023';
  end if;
  insert into public.user_memoir_project(user_id,project_id) values(owner_id,p_project_id) on conflict do nothing;
  perform 1 from public.user_memoir_project where user_id=owner_id and project_id=p_project_id for update;
  select * into saved from public.user_narrator_source
    where user_id=owner_id and project_id=p_project_id and client_turn_id=p_client_turn_id;
  if found then
    if saved.text is distinct from p_text or saved.kind is distinct from p_kind then
      raise exception 'input revision conflict; retry with the original input' using errcode='PT409';
    end if;
    return public.narrator_source_record(saved);
  end if;
  if not exists(select 1 from public.user_lifetime_conversation where user_id=owner_id and project_id=p_project_id) then
  if (select count(*) from public.user_narrator_source where user_id=owner_id and project_id=p_project_id)>=1000 or
     (select coalesce(sum(length(text)),0) from public.user_narrator_source where user_id=owner_id and project_id=p_project_id)+length(p_text)>120000 then
    raise exception 'memoir evidence exceeds supported bounds' using errcode='22023';
  end if;
  end if;
  update public.user_memoir_project set source_sequence=source_sequence+1
    where user_id=owner_id and project_id=p_project_id returning source_sequence into next_sequence;
  insert into public.user_narrator_source(user_id,project_id,client_turn_id,sequence,text,kind,language)
    values(owner_id,p_project_id,p_client_turn_id,next_sequence,p_text,p_kind,p_language) returning * into saved;
  insert into public.user_narrator_source_version(user_id,project_id,source_id,version,text,language)
    values(owner_id,p_project_id,saved.id,saved.version,saved.text,saved.language);
  -- Acceptance and intent commit together, before optional assistant delivery.
  insert into public.user_private_draft_outbox(user_id,project_id,memory_id,change_kind)
    values(owner_id,p_project_id,saved.id,'accepted');
  return public.narrator_source_record(saved);
end $memoir$;

CREATE FUNCTION public.accept_user_narrator_source_before_news(p_project_id text, p_client_turn_id uuid, p_text text, p_kind text DEFAULT 'narrator_chat'::text, p_language text DEFAULT 'en-AU'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare source jsonb; existed boolean; owner uuid:=auth.uid();
begin
 -- Existing acceptance owns the project lock. Acquire it first when present,
 -- then profile before the policy writer can advance the identity revision.
 if exists(select 1 from public.user_lifetime_conversation where user_id=owner and project_id=p_project_id) then
   perform 1 from public.user_memoir_project where user_id=owner and project_id=p_project_id for update;
   insert into public.user_profile(user_id,profile) values(owner,'{}') on conflict do nothing;
   perform 1 from public.user_profile where user_id=owner for update;
 end if;
 select exists(select 1 from public.user_narrator_source where user_id=owner and project_id=p_project_id and client_turn_id=p_client_turn_id) into existed;
 source:=public.accept_user_narrator_source_record(p_project_id,p_client_turn_id,p_text,p_kind,p_language);
 -- The source trigger keeps private-context publication pending until semantic review.
 return source;
end $$;

CREATE FUNCTION public.acquire_user_agent_turn_lease(p_lease_token uuid, p_lease_seconds integer DEFAULT 300) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare
  current_user_id uuid := auth.uid();
  acquired boolean := false;
  duration_seconds integer := greatest(30, least(coalesce(p_lease_seconds, 300), 900));
begin
  if current_user_id is null then
    raise exception 'authenticated user required';
  end if;
  if p_lease_token is null then
    raise exception 'lease token required';
  end if;

  insert into public.user_agent_turn_lease(user_id, lease_token, expires_at)
    values (current_user_id, p_lease_token, now() + make_interval(secs => duration_seconds))
  on conflict (user_id) do update
    set lease_token = excluded.lease_token,
        expires_at = excluded.expires_at,
        updated_at = now()
    where public.user_agent_turn_lease.expires_at <= now()
  returning true into acquired;

  return coalesce(acquired, false);
end;
$$;

CREATE FUNCTION public.advance_lifetime_continuity_preferences() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if (tg_op<>'INSERT' and old.kind in ('excluded_topic','paused_topic')) or
    (tg_op<>'DELETE' and new.kind in ('excluded_topic','paused_topic')) then
   update public.user_lifetime_conversation set preference_revision=preference_revision+1
     where user_id=coalesce(new.user_id,old.user_id) and conversation_id=coalesce(new.conversation_id,old.conversation_id);
 end if;
 return coalesce(new,old);
end $$;

CREATE FUNCTION public.advance_lifetime_deleted_preferences() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.user_lifetime_conversation set preference_revision=preference_revision+1
    where user_id=old.user_id;
  return old;
end $$;

CREATE FUNCTION public.advance_lifetime_draft_publication() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
begin
 if tg_table_name='user_lifetime_lane_snapshot' then
   if not (coalesce(old.state,'') in ('completed','proposed') or coalesce(new.state,'') in ('completed','proposed')) then
     return coalesce(new,old);
   end if;
 end if;
 if tg_op<>'UPDATE' or old is distinct from new then
   update public.user_memoir_project set draft_revision=draft_revision+1
     where user_id=coalesce(new.user_id,old.user_id) and project_id=coalesce(new.project_id,old.project_id);
 end if;
 return coalesce(new,old);
end $$;

CREATE FUNCTION public.advance_lifetime_preferences() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op='INSERT' or old.profile is distinct from new.profile then
    -- The UPDATE already owns the profile row; never acquire project here.
    -- Publication takes project -> profile -> lease and then reads this revision.
    update public.user_lifetime_conversation set preference_revision=preference_revision+1 where user_id=new.user_id;
  end if;
  return new;
end $$;

CREATE FUNCTION public.advance_two_lane_checkpoint(p_lane_id uuid, p_token uuid, p_steps integer DEFAULT 1, p_model text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare snap public.user_lifetime_lane_snapshot%rowtype; identity public.user_lifetime_conversation%rowtype;
 project public.user_memoir_project%rowtype; saved public.user_lifetime_compaction%rowtype;
 predecessor uuid; start_sequence bigint:=0; end_sequence bigint; owner uuid; pins jsonb; checkpoint_fence jsonb;
 previous_owner text; candidate uuid; evidence jsonb:='[]'; manifest_sources jsonb:='[]'; item record;
 processed integer; fingerprint text; count_items bigint; chain text; last_seq bigint; last_start integer;
begin
 if p_steps is null or p_steps not between 1 and 4 or p_model is null or p_model not in
   ('gpt-5.6-luna-pooled','gpt-5.6-luna-memoir-low','gpt-5.6-luna-memoir-high','gpt-6.1-sol','memoir-luna-low','legal2ai-luna-low','synthetic-byte-bpe') then raise exception 'bounded checkpoint configuration required';end if;
 snap:=public.lock_lifetime_memoir_lane(p_lane_id,p_token);
 owner:=snap.user_id;
 if not exists(select 1 from public.user_memoir_lane where id=p_lane_id and skill='timeline') then
   raise exception 'timeline checkpoint owner required' using errcode='42501';end if;
 if not exists(select 1 from public.lifetime_two_lane_rollout where singleton and enabled)
   or not exists(select 1 from public.user_lifetime_two_lane_source where user_id=owner and project_id=snap.project_id) then
   return jsonb_build_object('complete',true,'coverage_end',0);
 end if;
 select * into project from public.user_memoir_project where user_id=owner and project_id=snap.project_id;
 select * into identity from public.user_lifetime_conversation where user_id=owner and conversation_id=snap.conversation_id;
 previous_owner:=current_setting('request.jwt.claim.sub',true);
 perform set_config('request.jwt.claim.sub',owner::text,true);
 pins:=public.read_lifetime_pinned(snap.conversation_id);
 if pins->'privacy_complete' is distinct from 'true'::jsonb then raise exception 'complete current privacy required' using errcode='PT409';end if;
 predecessor:=identity.checkpoint_id;
 select coverage_end into start_sequence from public.user_lifetime_checkpoint where id=predecessor and published and (lossless or memory_summary is not null);
 start_sequence:=coalesce(start_sequence,0);
 -- Never cover an in-flight current source. The next A consumes this accepted
 -- checkpoint plus every remaining canonical position, including tombstones.
 end_sequence:=snap.source_high_water-1;
 -- A newer canonical frontier belongs to a newer snapshot. Finish this old
 -- quantum without replacing it with a lower checkpoint, even across rollback.
 if exists(select 1 from public.user_lifetime_checkpoint c where c.id=predecessor and c.published and c.coverage_end>end_sequence) then
   perform set_config('request.jwt.claim.sub',coalesce(previous_owner,''),true);
   return jsonb_build_object('complete',true,'coverage_end',(select c.coverage_end from public.user_lifetime_checkpoint c where c.id=predecessor));
 end if;
 if end_sequence<=start_sequence then
   perform set_config('request.jwt.claim.sub',coalesce(previous_owner,''),true);
   return jsonb_build_object('complete',true,'coverage_end',start_sequence);
 end if;
 if not exists(select 1 from public.user_lifetime_source_inventory where user_id=owner and project_id=snap.project_id
   and record_count=project.source_sequence and max_sequence=project.source_sequence) then
   raise exception 'complete canonical source inventory required' using errcode='PT409';end if;
 checkpoint_fence:=jsonb_build_object('schema_version',1,'identity',jsonb_build_object('schema_version',1,'owner_id',owner,
   'conversation_id',snap.conversation_id,'project_id',snap.project_id,'product','memoir'),
   'policy_epoch',project.policy_epoch,'source_revision',project.source_sequence,'execution_generation',identity.execution_generation,
   'phase_revision',0,'preference_revision',identity.preference_revision,'lease_token',p_token);
 select c.* into saved from public.user_lifetime_compaction c where c.user_id=owner and c.conversation_id=snap.conversation_id
   and c.fence-'lease_token'=checkpoint_fence-'lease_token'
   and c.predecessor_id is not distinct from predecessor and c.starting_after=start_sequence and c.through_sequence=end_sequence
   and c.pinned=pins order by id limit 1;
 if not found then
   insert into public.user_lifetime_compaction(user_id,conversation_id,fence,predecessor_id,starting_after,through_sequence,last_sequence,pinned)
     values(owner,snap.conversation_id,checkpoint_fence,predecessor,start_sequence,end_sequence,start_sequence,pins) returning * into saved;
 end if;
 update public.user_lifetime_compaction set fence=checkpoint_fence where id=saved.id returning * into saved;
 for iteration in 1..p_steps loop
   exit when saved.complete;
  processed:=0;
  chain:=saved.digest;count_items:=saved.item_count;last_seq:=saved.last_sequence;last_start:=saved.last_offset;
  for item in
    select pos.sequence,pos.source_id,pos.version,chunk_start,
      case when src.version=pos.version and src.status='active' then least(chunk_start+2000,length(src.text)) else 0 end as chunk_end,
      case when src.id is null then 'withdrawn' when src.version<>pos.version then 'superseded' else src.status end as status,
      case when src.version=pos.version and src.status='active' then substring(src.text from chunk_start+1 for 2000) else null end as content
    from public.user_lifetime_source_position pos left join public.user_narrator_source src
      on src.user_id=pos.user_id and src.project_id=pos.project_id and src.id=pos.source_id
    cross join lateral generate_series(0,case when src.version=pos.version and src.status='active' then greatest(length(src.text)-1,0) else 0 end,2000) chunk_start
    where pos.user_id=owner and pos.project_id=snap.project_id and pos.sequence>saved.starting_after and pos.sequence<=saved.through_sequence
      and (pos.sequence>saved.last_sequence or (pos.sequence=saved.last_sequence and chunk_start>saved.last_offset))
    order by pos.sequence,chunk_start limit 32
  loop
    fingerprint:=case when item.content is not null then encode(sha256(convert_to(item.content,'UTF8')),'hex') else null end;
    insert into public.user_lifetime_covered_evidence(maintenance_id,sequence,source_id,version,char_start,char_end,status,content_sha256)
      values(saved.id,item.sequence,item.source_id,item.version,item.chunk_start,item.chunk_end,item.status,fingerprint);
    chain:=encode(sha256(convert_to(chain||':'||item.sequence||':'||item.source_id||':'||item.version||':'||item.chunk_start||':'||item.chunk_end||':'||item.status||':'||coalesce(fingerprint,''),'UTF8')),'hex');
    processed:=processed+1;count_items:=count_items+1;last_seq:=item.sequence;last_start:=item.chunk_start;
  end loop;
  update public.user_lifetime_compaction set revision=revision+1,item_count=count_items,digest=chain,last_sequence=last_seq,last_offset=last_start,
    complete=processed<32 where id=saved.id returning * into saved;

 end loop;
 if saved.complete then
   -- Publish only a complete lossless replacement. A raw inventory/hash is not
   -- a summary. Larger intervals retain mandatory raw context and fail closed
   -- on A budget overflow until an accepted bounded summary is available.
   if exists(select 1 from public.user_lifetime_checkpoint c where c.id=predecessor and c.memory_summary is not null)
     or (select coalesce(sum(octet_length(substring(s.text from e.char_start+1 for e.char_end-e.char_start))),0)
       from public.user_lifetime_covered_evidence e join public.user_narrator_source s on s.user_id=owner and s.project_id=snap.project_id
         and s.id=e.source_id and s.version=e.version where e.maintenance_id=saved.id and e.status='active')
       +coalesce((select octet_length(c.evidence::text) from public.user_lifetime_checkpoint c where c.id=predecessor),0)>12000
     or (select count(*) from public.user_lifetime_covered_evidence where maintenance_id=saved.id and status='active')
       + coalesce((select jsonb_array_length(c.evidence) from public.user_lifetime_checkpoint c where c.id=predecessor and c.lossless),0)>16 then
     update public.user_lifetime_compaction set summary_required=true,summary_model=p_model where id=saved.id;
     perform set_config('request.jwt.claim.sub',coalesce(previous_owner,''),true);
     return jsonb_build_object('complete',true,'coverage_end',start_sequence,'summary_pending',true,'checkpoint_published',false,'maintenance_id',saved.id);
   end if;
   select coalesce(c.evidence,'[]'),coalesce(c.manifest->'sources','[]') into evidence,manifest_sources
     from public.user_lifetime_checkpoint c where c.id=predecessor and c.lossless;
   evidence:=coalesce(evidence,'[]');manifest_sources:=coalesce(manifest_sources,'[]');
   -- The project lock and timeline admission remain held through predecessor
   -- CAS and every derived write. All exact windows/tombstones were scanned.
   if identity.checkpoint_id is distinct from saved.predecessor_id or
     saved.item_count<>(select count(*) from public.user_lifetime_covered_evidence where maintenance_id=saved.id) then
     raise exception 'checkpoint predecessor or coverage changed' using errcode='PT409';end if;
   for item in select c.*,s.language,substring(s.text from c.char_start+1 for c.char_end-c.char_start) original
     from public.user_lifetime_covered_evidence c join public.user_narrator_source s
       on s.user_id=owner and s.project_id=snap.project_id and s.id=c.source_id and s.version=c.version and s.status='active'
     where c.maintenance_id=saved.id and c.status='active' order by c.sequence,c.char_start loop
     evidence:=evidence||jsonb_build_array(jsonb_build_object('schema_version',1,'source_id',item.source_id,'version',item.version,
       'char_start',item.char_start,'char_end',item.char_end,'original',item.original,'language',item.language,
       'role','storyteller','assertion','asserted','allowed_use',jsonb_build_array('conversation'),'policy_epoch',project.policy_epoch));
     if not manifest_sources @> jsonb_build_array(jsonb_build_object('schema_version',1,'source_id',item.source_id,'version',item.version)) then
       manifest_sources:=manifest_sources||jsonb_build_array(jsonb_build_object('schema_version',1,'source_id',item.source_id,'version',item.version));
     end if;
   end loop;
   insert into public.user_lifetime_checkpoint(user_id,conversation_id,predecessor_id,fence,coverage_end,model,prompt_version,pinned,
     manifest,evidence,published,coverage_proof_id,lossless) values(owner,snap.conversation_id,predecessor,checkpoint_fence,end_sequence,p_model,'lifetime-v1',pins,
       jsonb_build_object('schema_version',1,'identity',checkpoint_fence->'identity','policy_epoch',project.policy_epoch,
         'source_revision',project.source_sequence,'sources',manifest_sources),evidence,true,saved.id,true) returning id into candidate;
   update public.user_lifetime_conversation set checkpoint_id=candidate where user_id=owner and conversation_id=snap.conversation_id
     and checkpoint_id is not distinct from predecessor;
   if not found then raise exception 'checkpoint CAS failed' using errcode='PT409';end if;
 end if;
 perform set_config('request.jwt.claim.sub',coalesce(previous_owner,''),true);
 return jsonb_build_object('complete',saved.complete,'coverage_end',case when saved.complete then end_sequence else start_sequence end,
   'proof_revision',saved.revision);
end $$;

CREATE FUNCTION public.read_lifetime_policy_review(p_fence jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$
declare result jsonb;
begin
 perform public.lock_lifetime_publication_scope(p_fence);
 select public.narrator_source_record(s)||jsonb_build_object('interview_language',
   (select profile->>'preferred_language' from public.user_profile where user_id=auth.uid())) into result
 from public.user_lifetime_pending_policy p join public.user_narrator_source s
   on s.user_id=p.user_id and s.project_id=p.project_id and s.id=p.source_id
   and s.version=p.source_version and s.status='active'
 where p.user_id=auth.uid() and p.conversation_id=(p_fence->'identity'->>'conversation_id')::uuid
 order by s.sequence limit 1;
 return result;
end $$;

CREATE FUNCTION public.lock_lifetime_policy_review(p_fence jsonb) RETURNS double precision
    LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$
declare remaining double precision;
begin
 remaining:=public.lock_lifetime_publication_scope(p_fence);
 if public.read_lifetime_policy_review(p_fence) is null then
   raise exception 'pending source policy review required' using errcode='PT409';
 end if;
 return remaining;
end $$;

CREATE FUNCTION public.complete_lifetime_policy_review(p_fence jsonb, p_source_id uuid, p_version bigint, p_review jsonb, p_receipt jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$
declare owner uuid:=(p_fence->'identity'->>'owner_id')::uuid;
 project text:=p_fence->'identity'->>'project_id'; conversation uuid:=(p_fence->'identity'->>'conversation_id')::uuid;
 source public.user_narrator_source%rowtype; item jsonb; data jsonb; identifier text; lo integer; hi integer;
begin
 -- Only the server-side service role can certify completion; narrator clients
 -- may accept sources but cannot bypass this pending-policy gate.
 perform set_config('request.jwt.claim.sub',owner::text,true);
 perform 1 from public.user_memoir_project where user_id=owner and project_id=project for update;
 perform 1 from public.user_profile where user_id=owner for update;
 perform public.lock_lifetime_publication_scope(p_fence);
 select * into source from public.user_narrator_source where user_id=owner and project_id=project
   and id=p_source_id and version=p_version and status='active';
 if not found then raise exception 'active exact review source required' using errcode='PT409';end if;
 if not exists(select 1 from public.user_lifetime_pending_policy where user_id=owner and project_id=project
   and source_id=p_source_id and source_version=p_version) then
   if exists(select 1 from public.user_lifetime_source_policy_receipt where user_id=owner and project_id=project
      and source_id=p_source_id and source_version=p_version and review=jsonb_build_object('output',p_review,'receipt',p_receipt)) then
     return public.capture_lifetime_fence(conversation,(p_fence->>'lease_token')::uuid);
   end if;
   raise exception 'pending exact policy review required' using errcode='PT409';
 end if;
 if jsonb_typeof(p_review) is distinct from 'object' or p_review->'complete' is distinct from 'true'::jsonb
   or exists(select 1 from jsonb_object_keys(p_review) k where k not in ('complete','restrictions'))
   or jsonb_typeof(p_review->'restrictions') is distinct from 'array' or jsonb_array_length(p_review->'restrictions')>8
   or jsonb_typeof(p_receipt) is distinct from 'object' or length(coalesce(p_receipt->>'response_id','')) not between 1 and 1024
   or octet_length(p_receipt::text)>32768 then raise exception 'complete bounded policy review required' using errcode='22023';end if;
 if (select count(*) from jsonb_array_elements(p_review->'restrictions')) <>
    (select count(distinct jsonb_build_array(x->'kind',x->'char_start',x->'char_end')) from jsonb_array_elements(p_review->'restrictions') x) then
   raise exception 'duplicate policy control' using errcode='22023'; end if;
 for item in select value from jsonb_array_elements(p_review->'restrictions') loop
   if jsonb_typeof(item) is distinct from 'object' or not(item ?& array['kind','quote','char_start','char_end'])
     or exists(select 1 from jsonb_object_keys(item) k where k not in ('kind','quote','char_start','char_end'))
     or coalesce(item->>'kind','') not in ('excluded_topic','paused_topic')
     or jsonb_typeof(item->'quote') is distinct from 'string' or length(item->>'quote') not between 1 and 500
     or jsonb_typeof(item->'char_start') is distinct from 'number' or item->>'char_start' !~ '^[0-9]+$'
     or jsonb_typeof(item->'char_end') is distinct from 'number' or item->>'char_end' !~ '^[1-9][0-9]*$'
     then raise exception 'typed restrictive source control required' using errcode='22023';end if;
   lo:=(item->>'char_start')::integer;hi:=(item->>'char_end')::integer;
   if hi<=lo or hi>length(source.text) or substring(source.text from lo+1 for hi-lo) is distinct from item->>'quote'
     then raise exception 'exact policy quote required' using errcode='22023';end if;
 end loop;
 insert into public.user_lifetime_source_policy_receipt(user_id,project_id,conversation_id,source_id,source_version,parser_version,review)
 values(owner,project,conversation,p_source_id,p_version,'semantic-v1',jsonb_build_object('output',p_review,'receipt',p_receipt))
 on conflict(user_id,project_id,source_id) do update set source_version=excluded.source_version,parser_version=excluded.parser_version,review=excluded.review;
 for item in select value from jsonb_array_elements(p_review->'restrictions') loop
   data:=jsonb_build_object('text',item->>'quote','assertion','asserted','uncertainty',null,
     'source_refs',jsonb_build_array(jsonb_build_object('source_id',source.id,'version',source.version,
       'quote',item->>'quote','char_start',item->'char_start','char_end',item->'char_end')));
   identifier:='semantic-v1:'||encode(sha256(convert_to('memoir:continuity:'||source.id::text||':'||source.version::text||':'||
     (item->>'kind')||':'||(item->>'char_start')||':'||(item->>'char_end'),'UTF8')),'hex');
   perform public.save_lifetime_continuity(conversation,identifier,item->>'kind',0,(p_fence->>'policy_epoch')::bigint,(p_fence->>'lease_token')::uuid,data);
 end loop;
 delete from public.user_lifetime_pending_policy where user_id=owner and project_id=project and source_id=p_source_id and source_version=p_version;
 -- The review may finish after the worker has already entered its backoff.
 if not exists(select 1 from public.user_lifetime_pending_policy where user_id=owner and project_id=project)
   and not exists(select 1 from public.user_lifetime_policy_inventory_pending where user_id=owner and project_id=project) then
   update public.user_memoir_lane set error=null,available_at=clock_timestamp()
     where user_id=owner and project_id=project and pending and token is null and error='LIFETIME_POLICY_PENDING';
 end if;
 return public.capture_lifetime_fence(conversation,(p_fence->>'lease_token')::uuid);
end $$;

CREATE FUNCTION public.apply_user_memory_events(p_project_id text, p_sources jsonb, p_events jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform public.apply_user_memory_events_before_photos(p_project_id,p_sources,p_events);
  perform public.reconcile_interview_photo_links(auth.uid(),p_project_id);
  return public.read_user_memory_events(p_project_id);
end $$;

CREATE FUNCTION public.apply_user_memory_events_before_photos(p_project_id text, p_sources jsonb, p_events jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner_id uuid:=auth.uid(); item jsonb; saved public.user_narrator_source%rowtype; updated integer;
  proposal jsonb; ref jsonb; relation jsonb; evidence public.user_narrator_source%rowtype;
  current_event public.user_memory_event%rowtype; event_id text; event_data jsonb; event_refs jsonb; event_stage text; next_change bigint;
begin
  if owner_id is null then raise exception 'authenticated user required' using errcode='42501'; end if;
  if pg_catalog.jsonb_typeof(p_sources) is distinct from 'array' or pg_catalog.jsonb_array_length(p_sources) not between 1 and 1000 or
     pg_catalog.jsonb_typeof(p_events) is distinct from 'array' or pg_catalog.jsonb_array_length(p_events)>100 then
    raise exception 'invalid extraction result' using errcode='22023';
  end if;
  perform 1 from public.user_memoir_project where user_id=owner_id and project_id=p_project_id for update;
  if not found then raise exception 'project unavailable' using errcode='42501'; end if;
  for item in select value from pg_catalog.jsonb_array_elements(p_sources) loop
    select * into saved from public.user_narrator_source where user_id=owner_id and project_id=p_project_id and id=(item->>'id')::uuid;
    if not found then raise exception 'source unavailable' using errcode='42501'; end if;
    if saved.version is distinct from (item->>'version')::bigint or saved.status<>'active' then
      raise exception 'source revision conflict' using errcode='PT409';
    end if;
  end loop;
  -- Replayed successful inputs cannot create a second set of identities.
  if not exists(select 1 from public.user_narrator_source where user_id=owner_id and project_id=p_project_id
    and processing_status<>'succeeded' and id in(select (value->>'id')::uuid from pg_catalog.jsonb_array_elements(p_sources))) then
    return public.read_user_memory_events(p_project_id);
  end if;
  for proposal in select value from pg_catalog.jsonb_array_elements(p_events) loop
    if pg_catalog.jsonb_typeof(proposal) is distinct from 'object' or
       exists(select 1 from pg_catalog.jsonb_object_keys(proposal) k where k not in
         ('id','existing_id','expected_revision','kind','title','life_stage','temporal','stage_evidence','source_refs','uncertainty','person_ids','visibility','include_in_print','attribution','candidate_ids','relations','correction',
          'location','location_basis','locationConfidenceScore','yearConfidenceScore')) or
       proposal->>'kind' not in ('event','period') or
       length(pg_catalog.btrim(coalesce(proposal->>'title',''))) not between 1 and 300 or
       pg_catalog.jsonb_typeof(proposal->'source_refs') is distinct from 'array' or
       pg_catalog.jsonb_array_length(proposal->'source_refs') not between 1 and 100 then
      raise exception 'invalid event proposal' using errcode='22023';
    end if;
    if exists(select 1 from unnest(array['locationConfidenceScore','yearConfidenceScore']) field
      where proposal ? field and (jsonb_typeof(proposal->field)<>'number' or (proposal->>field)::numeric not between 0 and 1)) then
      raise exception 'placement confidence must be between zero and one' using errcode='22023';end if;
    if proposal ? 'location_basis' and (jsonb_typeof(proposal->'location_basis') is distinct from 'array'
        or jsonb_array_length(proposal->'location_basis')>20) then
      raise exception 'bounded location evidence required' using errcode='22023';end if;
    if proposal ? 'location' and proposal->'location'<>'null'::jsonb then
      if not(proposal ? 'locationConfidenceScore') then
        raise exception 'location confidence required' using errcode='22023';end if;
      perform public.validate_two_lane_places((select string_agg(value->>'quote',E'\n')
        from jsonb_array_elements(coalesce(proposal->'location_basis','[]'))),
        jsonb_build_array(jsonb_build_object('schema_version',1)||(proposal->'location')));
      if not exists(select 1 from jsonb_array_elements(coalesce(proposal->'location_basis','[]')) basis_item
          where strpos(basis_item->>'quote',proposal->'location'->>'place')>0) then
        raise exception 'location requires original evidence' using errcode='22023';end if;
    end if;
    current_event:=null;
    if coalesce(pg_catalog.jsonb_array_length(proposal->'candidate_ids'),0)>0 and ((proposal ? 'existing_id') or exists(select 1 from pg_catalog.jsonb_array_elements_text(proposal->'candidate_ids') candidate
        where not exists(select 1 from public.user_memory_event where user_id=owner_id and project_id=p_project_id and id=candidate))) then
      raise exception 'ambiguous candidates must remain scoped and unresolved' using errcode='42501'; end if;
    if proposal ? 'person_ids' and exists(select 1 from pg_catalog.jsonb_array_elements_text(proposal->'person_ids') person_id
        where not exists(select 1 from public.user_family_context f,
          pg_catalog.jsonb_array_elements(coalesce(f.document->'people','[]')) person
          where f.user_id=owner_id and f.project_id=p_project_id and person->>'id'=person_id)) then
      raise exception 'person identity unavailable in this project' using errcode='42501'; end if;
    for relation in select value from pg_catalog.jsonb_array_elements(coalesce(proposal->'relations','[]')) loop
      if relation->>'kind' is null or relation->>'kind' not in ('before','after') or
         pg_catalog.jsonb_typeof(relation->'source_refs') is distinct from 'array' or pg_catalog.jsonb_array_length(relation->'source_refs')=0 or
         not exists(select 1 from public.user_memory_event where user_id=owner_id and project_id=p_project_id and id=relation->>'event_id') then
        raise exception 'chronology target unavailable in this project' using errcode='42501'; end if;
      for ref in select value from pg_catalog.jsonb_array_elements(relation->'source_refs') loop
        perform public.validate_memory_evidence(owner_id,p_project_id,ref);
      end loop;
    end loop;
    if proposal ? 'existing_id' then
      select * into current_event from public.user_memory_event
        where user_id=owner_id and project_id=p_project_id and id=proposal->>'existing_id' for update;
      if not found then raise exception 'event unavailable' using errcode='42501'; end if;
      if current_event.revision is distinct from (proposal->>'expected_revision')::bigint then
        raise exception 'event revision conflict' using errcode='PT409';
      end if;
      if current_event.kind is distinct from proposal->>'kind' then
        raise exception 'event kind cannot change' using errcode='22023';
      end if;
      event_id:=current_event.id;
    else event_id:=pg_catalog.gen_random_uuid()::text;
    end if;
    if proposal ? 'correction' then
      ref:=proposal->'correction';
      perform public.validate_memory_evidence(owner_id,p_project_id,ref);
      select * into evidence from public.user_narrator_source where user_id=owner_id and project_id=p_project_id and id=(ref->>'source_id')::uuid;
      if current_event.id is null or evidence.text is distinct from ref->>'quote' or
         not exists(select 1 from pg_catalog.jsonb_array_elements(p_sources) s where s->>'id'=ref->>'source_id' and s->>'version'=ref->>'version') or
         evidence.text !~* '(correct|actually|year was|i meant|should be|更正|纠正|应该|其实|不是)' then
        raise exception 'chat correction requires explicit current original testimony' using errcode='22023'; end if;
      select coalesce(pg_catalog.jsonb_object_agg(key,value),'{}') into event_data from pg_catalog.jsonb_each(proposal)
        where key in ('life_stage','temporal');
      perform public.correct_user_memory_event(p_project_id,event_id,current_event.revision,event_data,evidence.text,'chat',evidence.id);
      continue;
    end if;
    event_stage:=coalesce(proposal->>'life_stage',current_event.life_stage,'unplaced');
    if event_stage not in ('baby','childhood','adolescence','young_adulthood','midlife','later_life','unplaced') then
      raise exception 'invalid life stage' using errcode='22023';
    end if;
    event_data:=(coalesce(current_event.data,'{"temporal":{"expression":"unknown","precision":"unknown"},"visibility":"private","include_in_print":false}'::jsonb)-'reconciliation_source_ids') ||
      (proposal - array['id','existing_id','expected_revision','source_refs','kind','life_stage']);
    if proposal ? 'temporal' and not (coalesce(current_event.data->'user_overrides','{}') ? 'temporal') and
       (coalesce((current_event.data->>'timing_conflict')::boolean,false) or
        (current_event.data->'temporal'->>'year_start' is not null and proposal->'temporal'->>'year_start' is not null and
         (current_event.data->'temporal'->>'year_start' is distinct from proposal->'temporal'->>'year_start' or
          current_event.data->'temporal'->>'year_end' is distinct from proposal->'temporal'->>'year_end'))) then
      -- Replaying the unresolved summary or an existing attributed account
      -- does not add evidence. Keep the unresolved placement; new basis refs
      -- (including the same year from another narrator) still append an account.
      if current_event.data->'temporal' = proposal->'temporal' or exists(
        select 1 from pg_catalog.jsonb_array_elements(coalesce(current_event.data->'temporal_accounts','[]')) account
          where account->'temporal' = proposal->'temporal') then
        event_data:=pg_catalog.jsonb_set(event_data,'{temporal}',current_event.data->'temporal');
      else
        event_data:=event_data || pg_catalog.jsonb_build_object('timing_conflict',true,
          'temporal_accounts',coalesce(current_event.data->'temporal_accounts',pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('temporal',current_event.data->'temporal'))) ||
            pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('temporal',proposal->'temporal')),
          'temporal',pg_catalog.jsonb_build_object('expression','unknown','precision','unknown',
            'basis',coalesce(current_event.data->'temporal'->'basis','[]') || coalesce(proposal->'temporal'->'basis','[]')));
      end if;
    end if;
    if current_event.data->'user_overrides' ? 'life_stage' then event_stage:=current_event.life_stage; end if;
    if current_event.data->'user_overrides' ? 'temporal' then
      event_data:=pg_catalog.jsonb_set(event_data,'{temporal}',current_event.data->'temporal');
    end if;
    if coalesce(proposal->>'visibility','private')<>coalesce(current_event.data->>'visibility','private') or
       coalesce((proposal->>'include_in_print')::boolean,false)<>coalesce((current_event.data->>'include_in_print')::boolean,false) then
      if proposal ? 'visibility' or proposal ? 'include_in_print' then raise exception 'extraction cannot grant visibility or print rights' using errcode='42501'; end if;
    end if;
    event_data:=event_data || pg_catalog.jsonb_build_object('visibility',coalesce(current_event.data->>'visibility','private'),
      'include_in_print',coalesce((current_event.data->>'include_in_print')::boolean,false));
    perform public.validate_memory_temporal(owner_id,p_project_id,event_data->'temporal');
    for ref in select value from pg_catalog.jsonb_array_elements(coalesce(event_data->'stage_evidence','[]')) loop
      perform public.validate_memory_evidence(owner_id,p_project_id,ref);
    end loop;
    if pg_catalog.jsonb_typeof(event_data->'temporal') is distinct from 'object' or
       event_data->'temporal'->>'precision' not in ('unknown','day','month','year','range','approximate','age','season') or
       length(coalesce(event_data->'temporal'->>'expression','')) not between 1 and 500 then
      raise exception 'invalid temporal placement' using errcode='22023';
    end if;
    if event_stage<>'unplaced' and (pg_catalog.jsonb_typeof(event_data->'stage_evidence') is distinct from 'array' or pg_catalog.jsonb_array_length(event_data->'stage_evidence')=0) then
      raise exception 'life stage requires evidence' using errcode='22023';
    end if;
    -- Every retained fact is a dependency, even when a birth/stage/chronology
    -- statement is separate from the event's principal narrator statement.
    select coalesce(pg_catalog.jsonb_agg(value),'[]') into event_refs from (
      select value from pg_catalog.jsonb_array_elements(proposal->'source_refs')
      union select value from pg_catalog.jsonb_array_elements(coalesce(event_data->'location_basis','[]'))
      union select value from pg_catalog.jsonb_array_elements(coalesce(event_data->'temporal'->'basis','[]'))
      union select value from pg_catalog.jsonb_array_elements(coalesce(event_data->'stage_evidence','[]'))
      union select r.value from pg_catalog.jsonb_array_elements(coalesce(event_data->'relations','[]')) relation_ref,
        pg_catalog.jsonb_array_elements(relation_ref.value->'source_refs') r
      union select r.value from pg_catalog.jsonb_array_elements(coalesce(event_data->'temporal_accounts','[]')) account,
        pg_catalog.jsonb_array_elements(coalesce(account->'temporal'->'basis','[]')) r
    ) dependencies;
    for ref in select value from pg_catalog.jsonb_array_elements(event_refs) loop
      if exists(select 1 from public.user_memory_event_source_exclusion x where x.user_id=owner_id and x.project_id=p_project_id
        and x.event_id=current_event.id and x.source_id::text=ref->>'source_id') then
        raise exception 'removed source link requires an explicit author decision' using errcode='42501'; end if;
      perform public.validate_memory_evidence(owner_id,p_project_id,ref);
      select * into evidence from public.user_narrator_source where user_id=owner_id and project_id=p_project_id and id=(ref->>'source_id')::uuid;
      if not found then raise exception 'event source unavailable' using errcode='42501'; end if;
      if evidence.status<>'active' or evidence.version is distinct from (ref->>'version')::bigint then
        raise exception 'evidence revision conflict' using errcode='PT409';
      end if;
      if length(coalesce(ref->>'quote','')) not between 1 and 2000 or pg_catalog.strpos(evidence.text,ref->>'quote')=0 then
        raise exception 'evidence quote must match original testimony' using errcode='22023';
      end if;
    end loop;
    -- A primary-role promotion is a real attribution change, even when the
    -- same quote was previously retained only as a placement dependency.
    -- A validated echo of saved facts acknowledges the input without dirtying
    -- the event. New evidence links, placement or lifecycle still revise it.
    if current_event.id is not null and current_event.data = event_data and
       current_event.life_stage = event_stage and current_event.status =
         (case when coalesce(pg_catalog.jsonb_array_length(proposal->'candidate_ids'),0)>0 then 'unresolved' else 'active' end) and
       not exists(select 1 from pg_catalog.jsonb_array_elements(event_refs) proposed_ref where not exists(
         select 1 from public.user_memory_event_source s where s.user_id=owner_id and s.project_id=p_project_id
           and s.event_id=current_event.id and s.evidence=proposed_ref.value)) and
       not exists(select 1 from pg_catalog.jsonb_array_elements(proposal->'source_refs') primary_ref where not exists(
         select 1 from public.user_memory_event_source s where s.user_id=owner_id and s.project_id=p_project_id
           and s.event_id=current_event.id and s.evidence=primary_ref.value and s.stage_progress_role='primary')) then
      continue;
    end if;
    update public.user_memoir_project set event_sequence=event_sequence+1
      where user_id=owner_id and project_id=p_project_id returning event_sequence into next_change;
    insert into public.user_memory_event(user_id,project_id,id,revision,kind,life_stage,status,data,change_sequence)
      values(owner_id,p_project_id,event_id,coalesce(current_event.revision,0)+1,proposal->>'kind',event_stage,
        case when coalesce(pg_catalog.jsonb_array_length(proposal->'candidate_ids'),0)>0 then 'unresolved' else 'active' end,event_data,next_change)
      on conflict(user_id,project_id,id) do update set revision=excluded.revision,life_stage=excluded.life_stage,
        data=excluded.data,status=excluded.status,change_sequence=excluded.change_sequence;
    for ref in select value from pg_catalog.jsonb_array_elements(event_refs) loop
      insert into public.user_memory_event_source as saved_link(user_id,project_id,event_id,source_id,source_version,evidence_hash,evidence,stage_progress_role)
        values(owner_id,p_project_id,event_id,(ref->>'source_id')::uuid,(ref->>'version')::bigint,pg_catalog.md5(ref::text),ref,
          case when proposal->'source_refs' @> pg_catalog.jsonb_build_array(ref) then 'primary'
               when event_data->'stage_evidence' @> pg_catalog.jsonb_build_array(ref) then 'stage' else 'dependency' end)
        on conflict on constraint user_memory_event_source_pkey do update
          set stage_progress_role=case when excluded.stage_progress_role='primary' or saved_link.stage_progress_role='primary' then 'primary'
            when excluded.stage_progress_role='stage' or saved_link.stage_progress_role='stage' then 'stage' else saved_link.stage_progress_role end;
    end loop;
    select * into current_event from public.user_memory_event where user_id=owner_id and project_id=p_project_id and id=event_id;
    insert into public.user_memory_event_revision(user_id,project_id,event_id,revision,record,actor,origin)
      values(owner_id,p_project_id,event_id,current_event.revision,public.memory_event_record(current_event),'model','author_timeline');
  end loop;
  update public.user_narrator_source set processing_status='succeeded'
    where user_id=owner_id and project_id=p_project_id and processing_status<>'succeeded'
      and id in (select (value->>'id')::uuid from pg_catalog.jsonb_array_elements(p_sources));
  get diagnostics updated=ROW_COUNT;
  update public.user_memoir_project set extraction_cursor=coalesce(
      (select min(sequence)-1 from public.user_narrator_source where user_id=owner_id and project_id=p_project_id and processing_status<>'succeeded'),source_sequence)
    where user_id=owner_id and project_id=p_project_id;
  if updated>0 then
    insert into public.user_private_draft_outbox(user_id,project_id,change_kind) values(owner_id,p_project_id,'events');
  end if;
  return public.read_user_memory_events(p_project_id);
end $$;

CREATE FUNCTION public.assert_lifetime_draft_receipt_scope(p_receipt_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare receipt public.user_private_draft_outbox%rowtype; identity public.user_lifetime_conversation%rowtype;
 project public.user_memoir_project%rowtype;
begin
 select * into receipt from public.user_private_draft_outbox where id=p_receipt_id;
 select * into identity from public.user_lifetime_conversation where user_id=receipt.user_id and project_id=receipt.project_id;
 if not found then return;end if;
 select * into project from public.user_memoir_project where user_id=receipt.user_id and project_id=receipt.project_id for share;
 select * into identity from public.user_lifetime_conversation where conversation_id=identity.conversation_id for share;
 if not exists(select 1 from public.user_lifetime_draft_snapshot where event_id=p_receipt_id and scan_complete) then
   raise exception 'private draft receipt coverage incomplete' using errcode='PT409';
 end if;
 if not exists(select 1 from public.user_lifetime_draft_snapshot s where s.event_id=p_receipt_id and s.scan_complete
     and s.user_id=receipt.user_id and s.project_id=receipt.project_id and s.conversation_id=identity.conversation_id
     and s.policy_epoch=project.policy_epoch and s.preference_revision=identity.preference_revision
     and s.round_revision=project.draft_round_epoch) then
   raise exception 'private draft receipt scope stale' using errcode='PT409';
 end if;
end $$;

CREATE FUNCTION public.attach_guest_conversation(p_token text, p_guest_wins boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb; attachment public.user_conversation_attachment%rowtype; snapshot jsonb; live jsonb; guest uuid;
begin
 result:=public.attach_guest_conversation_before_recordings(p_token,p_guest_wins);
 select * into attachment from public.user_conversation_attachment where user_id=auth.uid() and id=(result->>'conversation_id')::uuid;
 if exists(select 1 from public.user_original_recording_transfer where attachment_id=attachment.id) then return result;end if;
 guest:=(result->>'guest_user_id')::uuid;
 snapshot:=attachment.workspace->'interview_photos';
 if snapshot ? 'user_original_recording' then
   live:=public.interview_transfer_snapshot(guest,attachment.project_id);
   if snapshot->'user_original_recording' is distinct from live->'user_original_recording'
     or snapshot->'user_source_recording' is distinct from live->'user_source_recording' then
     raise exception 'guest recording state changed' using errcode='40001';end if;
   update public.user_original_recording set user_id=auth.uid() where user_id=guest and project_id=attachment.project_id;
   update public.user_source_recording set user_id=auth.uid() where user_id=guest and project_id=attachment.project_id;
 end if;
 insert into public.user_original_recording_transfer values(attachment.id,auth.uid());
 return result;
end $$;

CREATE FUNCTION public.attach_guest_conversation_before_lifetime(p_token text, p_guest_wins boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 return public.attach_guest_conversation_before_phase(p_token,p_guest_wins);
end
$$;

CREATE FUNCTION public.attach_guest_conversation_before_memory_events(p_token text, p_guest_wins boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb; attachment public.user_conversation_attachment%rowtype; original jsonb;
begin
  result:=public.attach_guest_conversation_legacy(p_token,p_guest_wins);
  select * into attachment from public.user_conversation_attachment
    where id=(result->>'conversation_id')::uuid and user_id=auth.uid();
  for original in select value from pg_catalog.jsonb_array_elements(coalesce(attachment.workspace->'memories','[]'::jsonb)) loop
    update public.user_memory set project_id=coalesce(original->>'project_id',attachment.project_id),
      client_turn_id=coalesce((original->>'client_turn_id')::uuid,(original->>'id')::uuid),
      life_stage=original->>'life_stage'
      where user_id=auth.uid() and id=(result->'memory_id_map'->>(original->>'id'))::uuid
        and project_id is null and kind='agent';
  end loop;
  return result;
end $$;

CREATE FUNCTION public.attach_guest_conversation_before_news(p_token text, p_guest_wins boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $memoir$
declare result jsonb; attachment public.user_conversation_attachment%rowtype; snapshot jsonb; original jsonb;
  v_owner uuid:=auth.uid(); guest uuid; table_name text;
begin
  result:=public.attach_guest_conversation_before_photos(p_token,p_guest_wins);
  select * into attachment from public.user_conversation_attachment where user_id=v_owner and id=(result->>'conversation_id')::uuid;
  if exists(select 1 from public.user_interview_photo_transfer where conversation_id=attachment.id and user_id=v_owner) then return result; end if;
  snapshot:=attachment.workspace->'interview_photos';
  if snapshot is null then return result; end if;
  guest:=(result->>'guest_user_id')::uuid;
  if snapshot is distinct from public.interview_transfer_snapshot(guest,attachment.project_id) then
    raise exception 'guest photo context changed; prepare a new transfer' using errcode='PT409'; end if;
  -- The existing canonical transfer has created the destination project and
  -- preserved canonical source/event identities. Private byte paths stay put;
  -- authoritative owner records are rebound, revoking the old guest at once.
  update public.user_interview_photo set user_id=v_owner where user_id=guest and project_id=attachment.project_id;
  foreach table_name in array array['user_interview_turn','user_interview_photo_link','user_interview_plan'] loop
    for original in select value from jsonb_array_elements(coalesce(snapshot->table_name,'[]')) loop
      if original->>'user_id' is distinct from guest::text or original->>'project_id' is distinct from attachment.project_id then
        raise exception 'invalid photo transfer scope' using errcode='42501'; end if;
      original:=original || jsonb_build_object('user_id',v_owner);
      execute format('insert into public.%I select (jsonb_populate_record(null::public.%I,$1)).*',table_name,table_name) using original;
    end loop;
  end loop;
  delete from public.user_interview_plan where user_id=guest and project_id=attachment.project_id;
  delete from public.user_interview_photo_link where user_id=guest and project_id=attachment.project_id;
  delete from public.user_interview_turn where user_id=guest and project_id=attachment.project_id;
  perform public.invalidate_interview_photo_projection(guest,attachment.project_id);
  insert into public.user_interview_photo_transfer values(attachment.id,v_owner);
  return result;
end $memoir$;

CREATE FUNCTION public.attach_guest_conversation_before_phase(p_token text, p_guest_wins boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb; guest uuid; project text; target uuid:=auth.uid();
begin
 result:=public.attach_guest_conversation_before_news(p_token,p_guest_wins);
 guest:=(result->>'guest_user_id')::uuid;
 select project_id into project from public.user_conversation_attachment where user_id=target and id=(result->>'conversation_id')::uuid;
 if guest is null or project is null or guest=target then return result; end if;
 -- Never transfer a running capability. Public citations already saved with
 -- replies remain intact; private relevance must be recomputed for the owner.
 update public.user_historical_news_job set status='cancelled' where user_id=guest and project_id=project and status='running';
 insert into public.user_historical_news_state(user_id,project_id,enabled,revision)
 select target,project,enabled,revision+1 from public.user_historical_news_state where user_id=guest and project_id=project
 on conflict(user_id,project_id) do nothing;
 insert into public.user_historical_news_clue(user_id,project_id,id,context_revision,status,evidence,relevance)
 select target,project,id,'transferred',case when status='rejected' then 'rejected' else 'used' end,evidence,relevance
 from public.user_historical_news_clue where user_id=guest and project_id=project
 on conflict(user_id,project_id,id) do nothing;
 delete from public.user_historical_news_clue where user_id=guest and project_id=project;
 -- Revoked guest execution remains disabled even if it still holds an old
 -- authenticated request. Repeated attachment cannot reset target choices.
 insert into public.user_historical_news_state(user_id,project_id,enabled)
 select guest,project,false where exists(select 1 from public.user_memoir_project where user_id=guest and project_id=project)
 on conflict(user_id,project_id) do update set enabled=false,revision=public.user_historical_news_state.revision+1;
 return result;
end $$;

CREATE FUNCTION public.attach_guest_conversation_before_photos(p_token text, p_guest_wins boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $memoir$
declare result jsonb; attachment public.user_conversation_attachment%rowtype; snapshot jsonb; original jsonb; table_name text;
  project public.user_memoir_project%rowtype; owner_id uuid:=auth.uid(); event_map jsonb; source_map jsonb;
begin
  result:=public.attach_guest_conversation_before_memory_events(p_token,p_guest_wins);
  select * into attachment from public.user_conversation_attachment where user_id=owner_id and id=(result->>'conversation_id')::uuid;
  if exists(select 1 from public.user_shared_memoir_transfer where conversation_id=attachment.id and user_id=owner_id) then return result; end if;
  snapshot:=attachment.workspace->'shared_memoir';
  if snapshot->'project' is null then return result; end if;
  select * into project from public.user_memoir_project where user_id=(result->>'guest_user_id')::uuid and project_id=attachment.project_id for update;
  if not found or project.source_sequence is distinct from (snapshot->'project'->>'source_sequence')::bigint or
    project.event_sequence is distinct from (snapshot->'project'->>'event_sequence')::bigint or project.policy_epoch is distinct from (snapshot->'project'->>'policy_epoch')::bigint then
    raise exception 'guest evidence changed; prepare a new transfer' using errcode='PT409'; end if;
  if exists(select 1 from public.user_memoir_project where user_id=owner_id and project_id=attachment.project_id) then
    raise exception 'project transfer conflict; retain both authorised projects' using errcode='PT409'; end if;
  insert into public.user_memoir_project select (pg_catalog.jsonb_populate_record(null::public.user_memoir_project,snapshot->'project' || pg_catalog.jsonb_build_object('user_id',owner_id))).*;
  foreach table_name in array array['user_narrator_source','user_narrator_source_version','user_memory_event','user_memory_event_source',
    'user_memory_event_source_exclusion','user_memory_event_revision','user_memory_event_change',
    'user_memoir_edition','user_memoir_milestone','user_memoir_lane'] loop
    for original in select value from pg_catalog.jsonb_array_elements(snapshot->table_name) loop
      if original->>'user_id' is distinct from result->>'guest_user_id' or original->>'project_id' is distinct from attachment.project_id then
        raise exception 'invalid transfer scope' using errcode='42501'; end if;
      original:=original || pg_catalog.jsonb_build_object('user_id',owner_id);
      if table_name='user_memoir_lane' then
        original:=original || pg_catalog.jsonb_build_object('id',pg_catalog.gen_random_uuid(),'token',null,'lease_until',null,'run_deadline',null,
          'active_manifest','[]'::jsonb,'active_events','[]'::jsonb,'pending',coalesce((original->>'pending')::boolean,false) or original->'token'<>'null'::jsonb);
      end if;
      execute pg_catalog.format('insert into public.%I select (jsonb_populate_record(null::public.%I,$1)).* on conflict do nothing',table_name,table_name) using original;
    end loop;
  end loop;
  select coalesce(pg_catalog.jsonb_object_agg(e->>'id',e->>'id'),'{}') into event_map from pg_catalog.jsonb_array_elements(snapshot->'user_memory_event') e;
  select coalesce(pg_catalog.jsonb_object_agg(s->>'id',s->>'id'),'{}') into source_map from pg_catalog.jsonb_array_elements(snapshot->'user_narrator_source') s;
  insert into public.user_shared_memoir_transfer values(attachment.id,owner_id,attachment.project_id,event_map,source_map);
  return result;
end $memoir$;

CREATE FUNCTION public.attach_guest_conversation_before_recordings(p_token text, p_guest_wins boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  result jsonb;
  transferred_project text;
  canonical public.user_lifetime_conversation%rowtype;
  owner uuid := auth.uid();
begin
  -- The resolver locks this same owner row. Concurrent first-home resolution
  -- therefore sees the transferred history, or transfer sees the established
  -- canonical identity; neither ordering silently adopts the guest project.
  perform 1 from auth.users where id=owner for update;
  if not found then raise exception 'authenticated owner required' using errcode='42501'; end if;
  result := public.attach_guest_conversation_before_lifetime(p_token,p_guest_wins);
  select project_id into transferred_project from public.user_conversation_attachment
    where user_id=owner and id=(result->>'conversation_id')::uuid;
  select * into canonical from public.user_lifetime_conversation where user_id=owner and product='memoir';
  if found and transferred_project is not null and transferred_project<>canonical.project_id then
    result := result || pg_catalog.jsonb_build_object('lifetime_identity',pg_catalog.jsonb_build_object(
      'schema_version',1,'outcome','mapping_required',
      'transferred_project_id',transferred_project,'canonical_project_id',canonical.project_id,
      'conversation_id',canonical.conversation_id));
  end if;
  return result;
end $$;

CREATE FUNCTION public.attach_guest_conversation_legacy(p_token text, p_guest_wins boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $memoir$
declare
  owner_id uuid := auth.uid(); held public.guest_conversation_transfer%rowtype;
  saved_id uuid; existing_profile jsonb; merged_profile jsonb; locale text;
  m jsonb; f jsonb; file jsonb; new_memory_id uuid; paths text[];
  id_map jsonb := '{}'::jsonb; watermark bigint; context jsonb; response jsonb;
begin
  if owner_id is null or not exists(select 1 from auth.users where id = owner_id and is_anonymous is false) then
    raise exception 'permanent session required' using errcode = '42501';
  end if;
  if p_token is null or p_token !~ '^[a-f0-9]{64}$' then raise exception 'invalid transfer capability' using errcode = '22023'; end if;
  select * into held from public.guest_conversation_transfer
    where token_hash = encode(sha256(convert_to(p_token, 'UTF8')), 'hex') for update;
  if not found then raise exception 'transfer unavailable' using errcode = '42501'; end if;
  if held.target_user_id is not null and held.target_user_id <> owner_id then
    raise exception 'transfer already claimed' using errcode = '42501';
  end if;
  if held.target_user_id is null then
    if held.expires_at <= clock_timestamp() or held.guest_user_id = owner_id then
      raise exception 'transfer expired or invalid' using errcode = '42501';
    end if;
    -- Fence existing workspace enrichment as well as new agent turns.
    insert into public.user_agent_turn_lease(user_id, lease_token, expires_at)
      values(owner_id, gen_random_uuid(), clock_timestamp()) on conflict(user_id) do nothing;
    perform 1 from public.user_agent_turn_lease where user_id = owner_id for update;
    if exists(select 1 from public.user_agent_turn_lease where user_id = owner_id and expires_at > clock_timestamp()) then
      raise exception 'account reply in progress' using errcode = '55000';
    end if;
    select profile into existing_profile from public.user_profile where user_id = owner_id for update;
    existing_profile := coalesce(existing_profile, '{}'::jsonb);
    if exists(select 1 from public.user_place_journey where user_id = owner_id) then
      existing_profile := jsonb_set(existing_profile, '{memory_places}', public.merge_memoir_context(
        coalesce(existing_profile->'memory_places', '[]'::jsonb),
        (select jsonb_build_array(to_jsonb(j) - 'user_id') from public.user_place_journey j where user_id = owner_id), false));
    end if;
    for m in select value from jsonb_array_elements(held.memories) loop
      if m ? 'id' then id_map := id_map || jsonb_build_object(m->>'id', md5(owner_id::text || ':' || (m->>'id'))::uuid); end if;
    end loop;
    merged_profile := public.merge_memoir_context(existing_profile,
      public.rewrite_merged_context(held.workspace->'profile', held.guest_user_id, owner_id, id_map), p_guest_wins);
    merged_profile := coalesce(merged_profile, existing_profile);
    select coalesce(turn_sequence, 0) + 1 into watermark from public.user_agent_session where user_id = owner_id;
    watermark := coalesce(watermark, 1) + jsonb_array_length(held.memories);
    insert into public.user_profile(user_id, profile, agent_source_sequences)
      values(owner_id, merged_profile, (select coalesce(jsonb_object_agg(key, to_jsonb(watermark)), '{}'::jsonb) from jsonb_each(merged_profile)))
      on conflict(user_id) do update set profile = excluded.profile, agent_source_sequences = excluded.agent_source_sequences;
    update public.user_agent_session set turn_sequence = watermark where user_id = owner_id;
    select raw_user_meta_data->>'ui_locale' into locale from auth.users where id = owner_id;
    if p_guest_wins or locale is null then locale := coalesce(held.workspace->>'ui_locale', locale); end if;
    if locale in ('en-AU', 'zh-CN') then
      update auth.users set raw_user_meta_data = coalesce(raw_user_meta_data, '{}'::jsonb) || jsonb_build_object('ui_locale', locale) where id = owner_id;
    end if;
    for m in select value from jsonb_array_elements(held.memories) loop
      new_memory_id := case when m ? 'id' then md5(owner_id::text || ':' || (m->>'id'))::uuid else gen_random_uuid() end;
      if m ? 'id' then id_map := id_map || jsonb_build_object(m->>'id', new_memory_id); end if;
      select coalesce(array_agg(public.import_memoir_path(value, held.guest_user_id, owner_id, true)), '{}'::text[]) into paths
        from jsonb_array_elements_text(coalesce(m->'source_paths', '[]'::jsonb));
      insert into public.user_memory(id, user_id, kind, content, created_at, source_paths, source_sequence)
        values(new_memory_id, owner_id, m->>'kind', m->>'content', (m->>'created_at')::timestamptz, paths, watermark)
        on conflict(id) do nothing;
    end loop;
    for f in select value from jsonb_array_elements(coalesce(held.workspace->'family_context', '[]'::jsonb)) loop
      insert into public.user_family_context(user_id, project_id, document, revision)
        values(owner_id, f->>'project_id', public.rewrite_merged_context(f->'document', held.guest_user_id, owner_id, id_map)
          || jsonb_build_object('revision', coalesce((f->>'revision')::bigint, 0), 'source_sequence', watermark), coalesce((f->>'revision')::bigint, 0))
        on conflict(user_id, project_id) do update set
          document = public.merge_memoir_context(public.user_family_context.document, excluded.document, p_guest_wins)
            || jsonb_build_object('revision', public.user_family_context.revision + 1, 'source_sequence', watermark, 'updated_at', clock_timestamp()),
          revision = public.user_family_context.revision + 1;
    end loop;
    if jsonb_typeof(held.workspace->'place_journey') = 'object' then
      f := held.workspace->'place_journey';
      insert into public.user_place_journey(user_id, schema_version, status, revision, source_sequence, place, hierarchy,
        granularity, latitude, longitude, duration_ms)
      values(owner_id, 1, 'active', 1, watermark, f->>'place', f->'hierarchy', f->>'granularity',
        (f->>'latitude')::double precision, (f->>'longitude')::double precision, (f->>'duration_ms')::integer)
      on conflict(user_id) do nothing;
    end if;
    for file in select value from jsonb_array_elements(coalesce(held.workspace->'storage_objects', '[]'::jsonb)) loop
      insert into public.guest_merge_asset_access(user_id, source_name) values(owner_id, file->>'name') on conflict do nothing;
    end loop;
    context := held.workspace || jsonb_build_object('existing_profile', existing_profile, 'merged_profile', merged_profile,
      'memory_id_map', id_map, 'guest_user_id', held.guest_user_id, 'memories', held.memories);
    insert into public.user_conversation_attachment(user_id, project_id, messages, workspace)
      values(owner_id, held.project_id, held.messages, context) returning id into saved_id;
    update public.guest_conversation_transfer set target_user_id = owner_id, conversation_id = saved_id,
      memory_id_map = id_map, messages = '[]'::jsonb, memories = '[]'::jsonb
      where token_hash = held.token_hash;
  else saved_id := held.conversation_id; id_map := held.memory_id_map;
  end if;
  select profile into merged_profile from public.user_profile where user_id = owner_id;
  select raw_user_meta_data->>'ui_locale' into locale from auth.users where id = owner_id;
  return jsonb_build_object('conversation_id', saved_id, 'attached', true, 'guest_user_id', held.guest_user_id,
    'project_id', held.project_id, 'memory_id_map', id_map, 'profile', merged_profile, 'ui_locale', locale,
    'storage_objects', coalesce(held.workspace->'storage_objects', '[]'::jsonb));
end;
$memoir$;

CREATE FUNCTION public.attribute_historical_news_answer() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $memoir$
declare cue jsonb;
begin
 if new.version=1 and current_setting('memoir.news_source_accept',true)='1' then
   select t.collector->'historical_context' into cue from public.user_interview_turn t
    where t.user_id=new.user_id and t.project_id=new.project_id order by sequence desc limit 1;
   if btrim(new.text) ~* '^(please )?(stop historical clues|disable historical clues|pause|pause for now|先暂停|暂停|关闭历史线索|不要历史线索)[.!。！ ]*$' or btrim(new.text) ~* '^(I don.t want to discuss|do not discuss|我不想.*谈)' then
     perform public.set_user_historical_news(new.project_id,false,case when cue is not null then cue->>'id' else null end);
   elsif new.text ~* '(don.t remember|cannot remember|can.t remember|skip this clue|想不起来|不记得|跳过)' then
     if cue is not null then perform public.set_user_historical_news(new.project_id,
       coalesce((select enabled from public.user_historical_news_state where user_id=new.user_id and project_id=new.project_id),true),cue->>'id'); end if;
   elsif lower(btrim(new.text)) in ('let''s return to that historical clue.','let''s return to that historical clue','回到刚才那条历史线索。','回到刚才那条历史线索') then
     if cue is null or cue='null'::jsonb then
       select t.collector->'historical_context' into cue from public.user_interview_turn t where
         t.user_id=new.user_id and t.project_id=new.project_id and t.collector->'historical_context' is not null
         and t.collector->'historical_context'<>'null'::jsonb order by sequence desc limit 1;
     end if;
     perform public.set_user_historical_news(new.project_id,true);
     update public.user_historical_news_clue set status='ready',context_revision=public.historical_news_revision(new.user_id,new.project_id)
       where user_id=new.user_id and project_id=new.project_id and id=cue->>'id';
   end if;
   if cue is not null and cue<>'null'::jsonb then
     new.attribution:=new.attribution || jsonb_build_object('cue_context',jsonb_build_object(
       'kind','historical_context_presented','clue_id',cue->>'id'));
   end if;
 elsif new.version>1 then
   select v.attribution->'cue_context' into cue from public.user_narrator_source_version v
    where v.user_id=new.user_id and v.project_id=new.project_id and v.source_id=new.source_id and v.version<new.version
    order by v.version desc limit 1;
   if cue is not null then new.attribution:=new.attribution || jsonb_build_object('cue_context',cue); end if;
 end if;
 return new;
end $memoir$;

CREATE FUNCTION public.background_skill_id(p_page jsonb, p_phase text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 select md5(concat_ws(':',p_page->>'snapshot_id',p_page->>'page_number',p_phase,
   p_page->'source'->>'id',p_page->'source'->>'version',p_page->'source'->>'char_start',
   p_page->'profile_context'->>'target_round',p_page->'profile_context'->>'work_mode'))
$$;

CREATE FUNCTION public.background_skill_receipt(p_page jsonb, p_phase text, p_skill text, p_execution text, p_status text, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare source public.user_narrator_source%rowtype; first_source bigint;last_source bigint;
begin
 first_source:=coalesce((p_page->'source'->>'sequence')::bigint,(p_page->'profile_context'->>'source_frontier')::bigint,0);
 last_source:=first_source;
 if p_page ? 'batch' then
   select min((s->>'sequence')::bigint),max((s->>'sequence')::bigint) into first_source,last_source
   from jsonb_array_elements(coalesce(p_page->'batch'->'sources','[]')||coalesce(p_page->'batch'->'new_messages','[]')) s;
 end if;
 select * into source from public.user_narrator_source where user_id=(p_page->>'user_id')::uuid
   and project_id=p_page->>'project_id' and sequence=last_source and status='active';
 insert into public.user_background_skill_work(user_id,project_id,id,lane_id,snapshot_id,page_digest,phase,skill,execution,
   source_id,source_version,client_turn_id,coverage_start,coverage_end,status,reason,model_invoked,model_attempts,lease_token)
 values((p_page->>'user_id')::uuid,p_page->>'project_id',public.background_skill_id(p_page,p_phase),
   (p_page->>'lane_id')::uuid,(p_page->>'snapshot_id')::uuid,p_page->>'page_digest',p_phase,p_skill,p_execution,
   source.id,source.version,source.client_turn_id,coalesce(first_source,0),coalesce(last_source,0),p_status,p_reason,
   case when p_execution='model' and p_status='saved' then null else false end,
   case when p_execution='model' and p_status='saved' then null else 0 end,(p_page->>'token')::uuid)
 on conflict(user_id,project_id,id) do update set status=excluded.status,reason=excluded.reason,
   page_digest=excluded.page_digest,lease_token=excluded.lease_token,updated_at=clock_timestamp();
end $$;

CREATE FUNCTION public.begin_formal_memoir(p_project_id text, p_expected_phase_revision bigint, p_expected_revision bigint, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner uuid:=auth.uid(); context jsonb; run public.user_formal_memoir_run%rowtype; event record;
 ref record; refs jsonb; span jsonb; lo integer; hi integer; ordinal integer:=0; plan jsonb; current_revision bigint;
begin
 if owner is null then raise exception 'FORMAL_OWNER_REQUIRED' using errcode='42501';end if;
 context:=public.lock_formal_memoir_context(owner,p_project_id);
 if p_request_id is null or p_expected_phase_revision is distinct from (context->>'phase_revision')::bigint then
   raise exception 'FORMAL_PHASE_CHANGED' using errcode='PT409';end if;
 select * into run from public.user_formal_memoir_run where user_id=owner and project_id=p_project_id and request_id=p_request_id;
 if found then
   if run.base_revision is distinct from p_expected_revision or run.phase_revision is distinct from p_expected_phase_revision then
     raise exception 'FORMAL_REQUEST_CONFLICT' using errcode='PT409';end if;
   return public.formal_memoir_run_record(run);
 end if;
 insert into public.user_formal_memoir_head(user_id,project_id) values(owner,p_project_id) on conflict do nothing;
 select revision into current_revision from public.user_formal_memoir_head where user_id=owner and project_id=p_project_id for update;
 if current_revision is distinct from p_expected_revision then raise exception 'FORMAL_REVISION_CHANGED' using errcode='PT409';end if;
 if exists(select 1 from public.user_formal_memoir_run where user_id=owner and project_id=p_project_id and state in ('pending','running')) then
   raise exception 'FORMAL_RUN_PENDING' using errcode='PT409';end if;
 if exists(select 1 from public.user_narrator_source where user_id=owner and project_id=p_project_id and status='active' and processing_status<>'succeeded') then
   raise exception 'FORMAL_EXTRACTION_INCOMPLETE' using errcode='55000';end if;
 insert into public.user_formal_memoir_run(user_id,project_id,conversation_id,request_id,locale,base_revision,phase_revision,
   policy_epoch,preference_revision,source_revision,event_revision)
 values(owner,p_project_id,(context->>'conversation_id')::uuid,p_request_id,context->>'locale',p_expected_revision,p_expected_phase_revision,
   (context->>'policy_epoch')::bigint,(context->>'preference_revision')::bigint,(context->>'source_revision')::bigint,(context->>'event_revision')::bigint)
 returning * into run;
 for event in select * from public.user_memory_event where user_id=owner and project_id=p_project_id and status='active'
   order by change_sequence,id loop
   ordinal:=ordinal+1;
   if ordinal>128 then raise exception 'FORMAL_PLAN_CAPACITY_REQUIRED' using errcode='55000';end if;
   refs:='[]';
   for ref in select r.source_id,r.source_version,r.evidence,s.text,s.status,s.version from public.user_memory_event_source r
     left join public.user_narrator_source s on s.user_id=r.user_id and s.project_id=r.project_id and s.id=r.source_id
     where r.user_id=owner and r.project_id=p_project_id and r.event_id=event.id order by r.source_id,r.source_version,r.evidence_hash loop
     if ref.status is distinct from 'active' or ref.version is distinct from ref.source_version then
       raise exception 'FORMAL_EVIDENCE_UNAVAILABLE' using errcode='PT409';end if;
     lo:=coalesce((ref.evidence->>'char_start')::integer,strpos(ref.text,ref.evidence->>'quote')-1);
     hi:=coalesce((ref.evidence->>'char_end')::integer,lo+length(ref.evidence->>'quote'));
     if lo is null or hi is null or lo<0 or hi<=lo or hi>length(ref.text) or hi-lo>2000
       or substring(ref.text from lo+1 for hi-lo) is distinct from ref.evidence->>'quote'
       or ((ref.evidence->>'char_start' is null) <> (ref.evidence->>'char_end' is null))
       or (ref.evidence->>'char_start' is null and strpos(substring(ref.text from lo+2),ref.evidence->>'quote')>0) then
       raise exception 'FORMAL_EXACT_EVIDENCE_REQUIRED' using errcode='22023';end if;
     span:=jsonb_build_object('source_id',ref.source_id,'version',ref.source_version,'char_start',lo,'char_end',hi,'quote',ref.evidence->>'quote');
     refs:=refs||jsonb_build_array(span);
   end loop;
   if jsonb_array_length(refs) not between 1 and 8 then raise exception 'FORMAL_CHAPTER_CAPACITY_REQUIRED' using errcode='55000';end if;
   plan:=jsonb_build_object('ordinal',ordinal,'event_id',event.id,'event_revision',event.revision,'title','Chapter '||ordinal,'evidence',refs);
   insert into public.user_formal_memoir_plan(run_id,ordinal,event_id,event_revision,title,evidence,digest)
    values(run.id,ordinal,event.id,event.revision,'Chapter '||ordinal,refs,public.formal_memoir_digest(plan));
 end loop;
 if ordinal=0 then raise exception 'FORMAL_EVIDENCE_REQUIRED' using errcode='55000';end if;
 update public.user_formal_memoir_run set chapter_count=ordinal,plan_digest=public.formal_memoir_digest(
   (select jsonb_agg(jsonb_build_object('ordinal',p.ordinal,'chapter_id',p.chapter_id,'digest',p.digest) order by p.ordinal)
    from public.user_formal_memoir_plan p where p.run_id=run.id)) where id=run.id returning * into run;
 return public.formal_memoir_run_record(run);
end $$;

CREATE FUNCTION public.begin_lifetime_compaction(p_fence jsonb, p_through_sequence bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare owner uuid:=auth.uid(); conversation uuid:=(p_fence->'identity'->>'conversation_id')::uuid;
  project text; predecessor uuid; start_sequence bigint:=0; saved public.user_lifetime_compaction%rowtype;
begin
  select project_id,checkpoint_id into project,predecessor from public.user_lifetime_conversation where user_id=owner and conversation_id=conversation;
  if not found then raise exception 'conversation unavailable'; end if;
  perform 1 from public.user_memoir_project where user_id=owner and project_id=project for update;
  perform public.lock_lifetime_publication(p_fence);
  select checkpoint_id into predecessor from public.user_lifetime_conversation where user_id=owner and conversation_id=conversation;
  if predecessor is not null then select coverage_end into start_sequence from public.user_lifetime_checkpoint where id=predecessor and published; end if;
  start_sequence:=coalesce(start_sequence,0);
  if p_through_sequence is null or p_through_sequence<=start_sequence or p_through_sequence>(p_fence->>'source_revision')::bigint then raise exception 'invalid maintenance interval'; end if;
  if not exists(select 1 from public.user_lifetime_source_inventory where user_id=owner and project_id=project
      and record_count=(p_fence->>'source_revision')::bigint and max_sequence=(p_fence->>'source_revision')::bigint) then
    raise exception 'LIFETIME_INVENTORY_REQUIRED: historical position inventory is incomplete' using errcode='PT409';
  end if;
  -- One existing matching session is sufficient after an uncertain response.
  select * into saved from public.user_lifetime_compaction where user_id=owner and conversation_id=conversation
    and fence-'lease_token'=p_fence-'lease_token' and pinned=public.read_lifetime_pinned(conversation) and predecessor_id is not distinct from predecessor and starting_after=start_sequence and through_sequence=p_through_sequence
    order by id limit 1;
  if not found then
    insert into public.user_lifetime_compaction(user_id,conversation_id,fence,predecessor_id,starting_after,through_sequence,last_sequence,pinned)
      values(owner,conversation,p_fence,predecessor,start_sequence,p_through_sequence,start_sequence,public.read_lifetime_pinned(conversation)) returning * into saved;
  end if;
  if saved.fence is distinct from p_fence then
    update public.user_lifetime_compaction set fence=p_fence where id=saved.id returning * into saved;
  end if;
  return to_jsonb(saved)-'user_id'-'pinned';
end $$;

CREATE FUNCTION public.begin_user_historical_news(p_project_id text, p_hypothesis jsonb, p_snapshot jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare project public.user_memoir_project%rowtype; rev text; job public.user_historical_news_job%rowtype;
begin
 if auth.uid() is null then raise exception 'authenticated user required' using errcode='42501'; end if;
 perform 1 from public.user_agent_turn_lease where user_id=auth.uid() for share;
 if exists(select 1 from public.user_agent_turn_lease where user_id=auth.uid() and expires_at>clock_timestamp()) then return null; end if;
 select * into project from public.user_memoir_project where user_id=auth.uid() and project_id=p_project_id for update;
 if not found then raise exception 'project unavailable' using errcode='42501'; end if;
 if exists(select 1 from public.user_historical_news_state where user_id=auth.uid() and project_id=p_project_id and not enabled) then return null; end if;
 if jsonb_typeof(p_hypothesis) is distinct from 'object' or octet_length(p_hypothesis::text)>2000 or
   jsonb_typeof(p_hypothesis->'start') is distinct from 'number' or jsonb_typeof(p_hypothesis->'end') is distinct from 'number' or
   jsonb_typeof(p_hypothesis->'place') is distinct from 'string' or jsonb_typeof(p_hypothesis->'country') is distinct from 'string' or
   jsonb_typeof(p_hypothesis->'tentative') is distinct from 'boolean' or
   exists(select 1 from jsonb_object_keys(p_hypothesis) k where k not in ('start','end','place','country','granularity','tentative','time_basis','age_interval')) or
   not exists(select 1 from (values ('New York, USA','USA'),('New York City, USA','USA'),('New York State, USA','USA'),('Boston, USA','USA'),
     ('Sydney, Australia','Australia'),('Perth, Australia','Australia'),('Melbourne, Australia','Australia'),('Chengdu, China','China'),
     ('Kunming, China','China'),('Beijing, China','China'),('Chengde, China','China'),('承德, 中国','中国'),('成都, 中国','中国'),('昆明, 中国','中国'),('北京, 中国','中国'),
     ('纽约, 美国','美国'),('悉尼, 澳大利亚','澳大利亚')) public_place(place,country)
     where place=p_hypothesis->>'place' and country=p_hypothesis->>'country') or
   (p_hypothesis->>'end')::integer>extract(year from current_date)::integer or
   (p_hypothesis->>'start')::integer not between 1 and extract(year from current_date)::integer or
   (p_hypothesis->>'end')::integer < (p_hypothesis->>'start')::integer or
   (p_hypothesis->>'end')::integer-(p_hypothesis->>'start')::integer>15 then raise exception 'invalid news hypothesis'; end if;
 rev:=public.historical_news_revision(auth.uid(),p_project_id);
 if p_snapshot->>'context_revision' is distinct from rev or (p_snapshot->>'source_sequence')::bigint is distinct from project.source_sequence then return null; end if;
 update public.user_historical_news_job set status=case when context_revision=rev and hypothesis=p_hypothesis then 'unavailable' else 'cancelled' end where user_id=auth.uid() and project_id=p_project_id and status='running'
   and (expires_at<=clock_timestamp() or context_revision<>rev or hypothesis<>p_hypothesis);
 if exists(select 1 from public.user_historical_news_job where user_id=auth.uid() and project_id=p_project_id
   and context_revision=rev and hypothesis=p_hypothesis and (status='running' or status in ('ready','empty','unavailable') and expires_at>clock_timestamp()-interval '24 hours')) then return null; end if;
 insert into public.user_historical_news_job(user_id,project_id,context_revision,source_sequence,status,expires_at,hypothesis)
 -- Keep the 45-second search budget separate from claim/progress I/O and result commit time.
 values(auth.uid(),p_project_id,rev,project.source_sequence,'running',clock_timestamp()+interval '90 seconds',p_hypothesis) returning * into job;
 return to_jsonb(job)-'user_id';
end $$;

CREATE FUNCTION public.begin_user_interview_photo(p_project_id text, p_metadata jsonb, p_upload_key uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $memoir$
declare v_owner uuid:=auth.uid(); v_id uuid:=gen_random_uuid(); saved public.user_interview_photo%rowtype; suffix text;
begin
  if v_owner is null then raise exception 'authenticated user required' using errcode='42501'; end if;
  if p_project_id is null or p_project_id !~ '^[A-Za-z0-9][A-Za-z0-9_-]{0,127}$' or
    jsonb_typeof(p_metadata) is distinct from 'object' or
    p_metadata->>'content_type' not in ('image/jpeg','image/png','image/webp') then
    raise exception 'invalid private photo' using errcode='22023'; end if;
  insert into public.user_memoir_project(user_id,project_id) values(v_owner,p_project_id) on conflict do nothing;
  perform 1 from public.user_memoir_project where user_id=v_owner and project_id=p_project_id for update;
  if p_upload_key is not null then
    select * into saved from public.user_interview_photo where user_id=v_owner and project_id=p_project_id and upload_key=p_upload_key;
    if found then
      if saved.status='deleted' or saved.content_sha256 is distinct from p_metadata->>'content_sha256' or
        saved.content_type is distinct from p_metadata->>'content_type' or saved.byte_size is distinct from (p_metadata->>'byte_size')::bigint then
        raise exception 'upload retry identity conflict' using errcode='PT409'; end if;
      if saved.status='pending' and exists(select 1 from storage.objects where bucket_id='memoir-private-photos' and name=saved.object_path) then
        update public.user_interview_photo set status='ready' where user_id=v_owner and project_id=p_project_id and id=saved.id returning * into saved;
      end if;
      return to_jsonb(saved)-'user_id';
    end if;
  end if;
  if (select count(*) from public.user_interview_photo where user_id=v_owner and project_id=p_project_id and status<>'deleted')>=200 then
    raise exception 'photo collection exceeds supported bound' using errcode='22023'; end if;
  suffix:=case p_metadata->>'content_type' when 'image/jpeg' then 'jpg' when 'image/png' then 'png' else 'webp' end;
  insert into public.user_interview_photo(id,user_id,project_id,object_path,content_type,byte_size,width,height,upload_key,content_sha256)
    values(v_id,v_owner,p_project_id,v_owner::text || '/private-photo/' || v_id::text || '.' || suffix,
      p_metadata->>'content_type',(p_metadata->>'byte_size')::bigint,(p_metadata->>'width')::integer,(p_metadata->>'height')::integer,p_upload_key,p_metadata->>'content_sha256')
    returning * into saved;
  return to_jsonb(saved)-'user_id';
end $memoir$;




CREATE FUNCTION public.bounded_lifetime_event_record(e public.user_memory_event) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $memoir$
declare refs jsonb; more boolean; result jsonb;
begin
 select coalesce(jsonb_agg(item order by key),'[]') into refs from (
   select s.source_id::text||':'||s.source_version::text||':'||s.evidence_hash key,
     jsonb_build_object('source_id',s.source_id,'version',s.source_version,
       'char_start',s.evidence->'char_start','char_end',s.evidence->'char_end') item
   from public.user_memory_event_source s join public.user_narrator_source n
     on n.user_id=s.user_id and n.project_id=s.project_id and n.id=s.source_id and n.version=s.source_version and n.status='active'
   where s.user_id=e.user_id and s.project_id=e.project_id and s.event_id=e.id
   order by key limit 9) bounded;
 more:=jsonb_array_length(refs)>8;
 if more then refs:=refs-8;end if;
 result:=jsonb_build_object('id',e.id,'revision',e.revision,'kind',e.kind,'status',e.status,'life_stage',e.life_stage,
   'change_sequence',e.change_sequence,'title',left(e.data->>'title',300),
   'title_complete',length(coalesce(e.data->>'title',''))<=300,
   'temporal',jsonb_build_object('expression',left(e.data->'temporal'->>'expression',500),
     'precision',left(e.data->'temporal'->>'precision',20),
     'year_start',case when e.data->'temporal'->>'year_start'~'^[0-9]{1,4}$' then e.data->'temporal'->'year_start' else null end,
     'year_end',case when e.data->'temporal'->>'year_end'~'^[0-9]{1,4}$' then e.data->'temporal'->'year_end' else null end),
   'temporal_complete',length(coalesce(e.data->'temporal'->>'expression',''))<=500,
   'uncertainty',left(e.data->>'uncertainty',1000),'uncertainty_complete',length(coalesce(e.data->>'uncertainty',''))<=1000,
   'location',e.data->'location',
   'locationConfidenceScore',coalesce((e.data->>'locationConfidenceScore')::numeric,
     case when exists(select 1 from public.lifetime_event_place_rows(e.user_id,e.project_id,e.id)) then 1 else 0 end),
   'yearConfidenceScore',coalesce((e.data->>'yearConfidenceScore')::numeric,
     case when e.data->'temporal'->>'year_start' is not null then 1 else 0 end),
   'needs_confirmation',jsonb_build_object(
     'location',coalesce((e.data->>'locationConfidenceScore')::numeric,
       case when exists(select 1 from public.lifetime_event_place_rows(e.user_id,e.project_id,e.id)) then 1 else 0 end)<0.85,
     'year',not(coalesce(e.data->'user_overrides','{}') ? 'temporal') and
       coalesce((e.data->>'yearConfidenceScore')::numeric,case when e.data->'temporal'->>'year_start' is not null then 1 else 0 end)<0.85),
   'assertion',case when e.data->>'assertion' in ('asserted','inferred') then e.data->>'assertion' else 'unspecified' end,
   'timing_conflict',e.data->'timing_conflict'='true'::jsonb,
   'source_refs',refs,'reference_identity_complete',not more,'evidence_complete',jsonb_array_length(refs)=0,
   'evidence_retrieval','read_lifetime_collection_page:event_sources',
   'details_complete',not exists(select 1 from unnest(array['temporal_accounts','relations','candidate_ids','supersedes','contradicts']) k
     where jsonb_typeof(e.data->k)='array' and jsonb_array_length(e.data->k)>0),
   'details_retrieval','read_lifetime_collection_page:event_details');
 return result;
end $memoir$;

CREATE FUNCTION public.cancel_lifetime_memory_obligation(p_fence jsonb, p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare saved public.user_lifetime_memory_obligation%rowtype;
begin
  select * into saved from public.user_lifetime_memory_obligation where id=p_id and user_id=auth.uid();
  if not found then raise exception 'obligation unavailable'; end if;
  perform 1 from public.user_memoir_project where user_id=auth.uid() and project_id=saved.project_id for update;
  perform public.lock_lifetime_publication(p_fence);
  if saved.conversation_id is distinct from (p_fence->'identity'->>'conversation_id')::uuid then raise exception 'obligation conversation mismatch'; end if;
  update public.user_lifetime_memory_obligation set status='cancelled',projection=null,claim_token=null,claim_expires_at=null,
    updated_at=clock_timestamp() where id=p_id returning * into saved;
  return public.lifetime_obligation_record(saved);
end $$;

CREATE FUNCTION public.capture_lifetime_fence(p_conversation_id uuid, p_lease_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare owner uuid:=auth.uid(); identity public.user_lifetime_conversation%rowtype;
  project public.user_memoir_project%rowtype; phase_revision bigint:=0;
begin
  select * into identity from public.user_lifetime_conversation where user_id=owner and conversation_id=p_conversation_id;
  if not found then raise exception 'conversation unavailable'; end if;
  -- Shared project lock conflicts with every correction/preference writer.
  select * into project from public.user_memoir_project where user_id=owner and project_id=identity.project_id for share;
  -- Ensure there is a lockable preference authority even for a new account.
  insert into public.user_profile(user_id,profile) values(owner,'{}') on conflict do nothing;
  perform 1 from public.user_profile where user_id=owner for share;
  -- Refresh after obtaining ordering locks; the first identity read is not a fence.
  select * into identity from public.user_lifetime_conversation where user_id=owner and conversation_id=p_conversation_id;
  perform 1 from public.user_agent_turn_lease where user_id=owner and lease_token=p_lease_token
    and expires_at>clock_timestamp() for share;
  if not found then raise exception 'valid turn lease required' using errcode='PT409'; end if;
  return jsonb_build_object('schema_version',1,'identity',jsonb_build_object('schema_version',1,
    'owner_id',owner,'conversation_id',identity.conversation_id,'product','memoir','project_id',identity.project_id),
    'policy_epoch',project.policy_epoch,'source_revision',project.source_sequence,
    'execution_generation',identity.execution_generation,'phase_revision',phase_revision,
    'preference_revision',identity.preference_revision,'lease_token',p_lease_token);
end $$;

CREATE FUNCTION public.capture_lifetime_read_fence(p_project_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare fence jsonb;
begin
 fence:=public.capture_lifetime_read_fence_before_drafts(p_project_id);
 return fence||(select jsonb_build_object('draft_revision',draft_revision,'event_revision',event_sequence)
   from public.user_memoir_project where user_id=auth.uid() and project_id=p_project_id);
end $$;

CREATE FUNCTION public.capture_lifetime_read_fence_before_drafts(p_project_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '2s'
    AS $$
declare owner uuid:=auth.uid(); identity public.user_lifetime_conversation%rowtype;
  project public.user_memoir_project%rowtype; phase_revision bigint:=0;
begin
  if owner is null then raise exception 'authenticated owner required' using errcode='42501'; end if;
  select * into identity from public.user_lifetime_conversation
    where user_id=owner and project_id=p_project_id and product='memoir';
  if not found then raise exception 'lifetime conversation unavailable' using errcode='42501'; end if;
  -- Same ordering as generation publication, but never lock or claim its lease.
  select * into project from public.user_memoir_project
    where user_id=owner and project_id=p_project_id for share;
  if not found then raise exception 'project unavailable' using errcode='42501'; end if;
  perform 1 from public.user_profile where user_id=owner for share;
  if not found then
    -- A missing row cannot be row-locked. Block only this owner's first INSERT
    -- without creating data from a GET or blocking other tenants' profile writes.
    perform pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtextextended('memoir-profile:'||owner::text,0));
    perform 1 from public.user_profile where user_id=owner for share;
  end if;
  select * into identity from public.user_lifetime_conversation
    where user_id=owner and project_id=p_project_id and product='memoir';
  if not found then raise exception 'lifetime conversation unavailable' using errcode='42501'; end if;
  return jsonb_build_object('schema_version',1,'identity',jsonb_build_object('schema_version',1,
    'owner_id',owner,'conversation_id',identity.conversation_id,'product','memoir','project_id',p_project_id),
    'policy_epoch',project.policy_epoch,'source_revision',project.source_sequence,
    'execution_generation',identity.execution_generation,'phase_revision',phase_revision,
    'preference_revision',identity.preference_revision,
    'captured_at_ms',floor(extract(epoch from clock_timestamp())*1000)::bigint);
end $$;

CREATE FUNCTION public.capture_memory_reply_context() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare prior uuid;
begin
 if not exists(select 1 from public.lifetime_two_lane_rollout where singleton and enabled) then return new;end if;
 select id into prior from public.user_narrator_source where user_id=new.user_id and project_id=new.project_id
   and sequence<new.sequence order by sequence desc limit 1;
 insert into public.user_memory_reply_context
 select new.user_id,new.project_id,new.id,new.version,d.source_id from public.user_memory_delivered_context d
 where d.user_id=new.user_id and d.project_id=new.project_id and d.source_id=prior
 on conflict do nothing;
 return new;
end $$;

CREATE FUNCTION public.change_user_narrator_source(p_project_id text, p_source_id uuid, p_expected_version bigint, p_action text, p_text text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb; owner uuid:=auth.uid();
begin
 if exists(select 1 from public.user_lifetime_conversation where user_id=owner and project_id=p_project_id) then
   perform 1 from public.user_memoir_project where user_id=owner and project_id=p_project_id for update;
   insert into public.user_profile(user_id,profile) values(owner,'{}') on conflict do nothing;
   perform 1 from public.user_profile where user_id=owner for update;
 end if;
 result:=public.change_user_narrator_source_record(p_project_id,p_source_id,p_expected_version,p_action,p_text);
 -- Edited narration requires a new semantic policy review before publication.
 return result;
end $$;

CREATE FUNCTION public.change_user_narrator_source_record(p_project_id text, p_source_id uuid, p_expected_version bigint, p_action text, p_text text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner_id uuid:=auth.uid(); saved public.user_narrator_source%rowtype; affected text[]; affected_event_id text;
  next_sequence bigint; next_change bigint; previous_sync text;
begin
  if owner_id is null then raise exception 'authenticated user required' using errcode='42501'; end if;
  if p_action not in ('edit','withdraw') or (p_action='edit' and length(pg_catalog.btrim(coalesce(p_text,''))) not between 1 and 100000) then
    raise exception 'invalid source change' using errcode='22023';
  end if;
  perform 1 from public.user_memoir_project where user_id=owner_id and project_id=p_project_id for update;
  select * into saved from public.user_narrator_source where user_id=owner_id and project_id=p_project_id and id=p_source_id for update;
  if not found then raise exception 'source unavailable' using errcode='42501'; end if;
  if saved.version is distinct from p_expected_version or saved.status<>'active' then
    raise exception 'source revision conflict; reload the source' using errcode='PT409';
  end if;
  if not exists(select 1 from public.user_lifetime_conversation where user_id=owner_id and project_id=p_project_id) then
  if p_action='edit' and (select coalesce(sum(length(text)),0) from public.user_narrator_source
     where user_id=owner_id and project_id=p_project_id and id<>p_source_id)+length(p_text)>120000 then
    raise exception 'memoir evidence exceeds supported bounds' using errcode='22023';
  end if;
  end if;
  select array_agg(distinct s.event_id) into affected from public.user_memory_event_source s
    where user_id=owner_id and project_id=p_project_id and source_id=p_source_id;
  if p_action='withdraw' then
    -- Existing deletion policy removes restricted original and derived bytes.
    update public.user_narrator_source_version set text='[withdrawn]' where user_id=owner_id and project_id=p_project_id and source_id=p_source_id;
    delete from public.user_memory_event_revision where user_id=owner_id and project_id=p_project_id and event_id=any(affected);
    -- Retired views can contain the original in their saved request as well as
    -- generated prose. Scope their removal to this owner's affected project.
    update public.user_memory set content='[Evidence withdrawn; rebuild from surviving originals.]'
      where user_id=owner_id and kind='memoir' and
        (project_id=p_project_id or ('memoir-preview:' || p_project_id)=any(source_paths));
    update public.user_family_context f set document=pg_catalog.jsonb_set(f.document,'{timeline}',
      coalesce((select pg_catalog.jsonb_agg(item) from pg_catalog.jsonb_array_elements(coalesce(f.document->'timeline','[]')) item
        where not (item->>'id'=any(coalesce(affected,array[]::text[])) or
          exists(select 1 from pg_catalog.jsonb_array_elements(coalesce(item->'source_refs','[]')) ref
            where ref->>'source_id'=p_source_id::text))),'[]')),
      revision=f.revision+1 where f.user_id=owner_id and f.project_id=p_project_id;
  end if;
  delete from public.user_memory_event_source where user_id=owner_id and project_id=p_project_id and source_id=p_source_id;
  foreach affected_event_id in array coalesce(affected,array[]::text[]) loop
    update public.user_memoir_project set event_sequence=event_sequence+1 where user_id=owner_id and project_id=p_project_id returning event_sequence into next_change;
    update public.user_memory_event e set revision=revision+1,change_sequence=next_change,
      status=case when p_action='edit' or exists(select 1 from public.user_memory_event_source s where s.user_id=owner_id and s.project_id=p_project_id and s.event_id=e.id) then 'unresolved' else 'withdrawn' end,
      life_stage=case when data->'user_overrides' ? 'life_stage' and data->'user_overrides'->'life_stage'->>'source_id' is distinct from p_source_id::text then life_stage else 'unplaced' end,
      data=pg_catalog.jsonb_build_object('title','Evidence changed; awaiting extraction','temporal',
        case when data->'user_overrides' ? 'temporal' and data->'user_overrides'->'temporal'->>'source_id' is distinct from p_source_id::text
          then data->'temporal' else pg_catalog.jsonb_build_object('expression','unknown','precision','unknown') end,
        'stage_evidence',case when data->'user_overrides' ? 'life_stage' and data->'user_overrides'->'life_stage'->>'source_id' is distinct from p_source_id::text
          then coalesce(data->'stage_evidence','[]') else '[]'::jsonb end,
        'user_overrides',coalesce((select pg_catalog.jsonb_object_agg(key,value) from pg_catalog.jsonb_each(coalesce(data->'user_overrides','{}'))
          where value->>'source_id' is distinct from p_source_id::text),'{}'),
        'visibility',coalesce(data->>'visibility','private'),'include_in_print',coalesce((data->>'include_in_print')::boolean,false),
        'reconciliation_source_ids',case when p_action='edit' then pg_catalog.jsonb_build_array(p_source_id) else '[]'::jsonb end)
      where user_id=owner_id and project_id=p_project_id and id=affected_event_id;
  end loop;
  -- Surviving testimony needs reconciliation too: a withdrawal is not a
  -- successful extraction of the facts formerly supported by that source.
  update public.user_narrator_source original set processing_status='pending'
    where user_id=owner_id and project_id=p_project_id and status='active' and id<>p_source_id
      and exists(select 1 from public.user_memory_event_source link where link.user_id=owner_id
        and link.project_id=p_project_id and link.event_id=any(affected) and link.source_id=original.id);
  update public.user_memoir_project set source_sequence=source_sequence+1,policy_epoch=policy_epoch+1
    where user_id=owner_id and project_id=p_project_id returning source_sequence into next_sequence;
  update public.user_narrator_source set version=version+1,sequence=next_sequence,
    text=case when p_action='withdraw' then '[withdrawn]' else p_text end,
    status=case when p_action='withdraw' then 'withdrawn' else 'active' end,
    processing_status=case when p_action='withdraw' then 'succeeded' else 'pending' end
    where user_id=owner_id and project_id=p_project_id and id=p_source_id returning * into saved;
  insert into public.user_narrator_source_version(user_id,project_id,source_id,version,text,language)
    values(owner_id,p_project_id,p_source_id,saved.version,saved.text,saved.language);
  -- Conversation memory is a disposable context view. Withdrawn originals and
  -- assistant-derived repetitions cannot remain available through that view.
  previous_sync:=pg_catalog.current_setting('memoir.sync_source',true);
  perform pg_catalog.set_config('memoir.sync_source','true',true);
  update public.user_memory set content='Storyteller: ' || saved.text || E'\nMemory Spark: [source changed]'
    where user_id=owner_id and project_id=p_project_id and kind='agent' and
      client_turn_id=saved.client_turn_id;
  perform pg_catalog.set_config('memoir.sync_source',coalesce(previous_sync,''),true);
  update public.user_memoir_project set extraction_cursor=coalesce((select min(sequence)-1 from public.user_narrator_source
      where user_id=owner_id and project_id=p_project_id and status='active' and processing_status<>'succeeded'),source_sequence)
    where user_id=owner_id and project_id=p_project_id;
  insert into public.user_private_draft_outbox(user_id,project_id,memory_id,change_kind)
    values(owner_id,p_project_id,p_source_id,case when p_action='withdraw' then 'revocation' else 'edit' end);
  return public.narrator_source_record(saved);
end $$;

CREATE FUNCTION public.claim_formal_memoir(p_run_id uuid, p_lease_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare run public.user_formal_memoir_run%rowtype; next_ordinal integer;
begin
 if p_lease_seconds is null or p_lease_seconds not between 1 and 900 then raise exception 'FORMAL_LEASE_BOUNDS' using errcode='22023';end if;
 run:=public.lock_formal_memoir_run(p_run_id,null,false);
 if run.state='completed' then return (select result from public.user_formal_memoir_edition where run_id=run.id and active);end if;
 if run.token is not null and run.lease_until>clock_timestamp() then return jsonb_build_object('status','busy','run_id',run.id);end if;
 update public.user_formal_memoir_run set state='running',token=gen_random_uuid(),fence=fence+1,
   lease_until=clock_timestamp()+make_interval(secs=>p_lease_seconds) where id=run.id returning * into run;
 select coalesce(min(p.ordinal),run.chapter_count+1) into next_ordinal from public.user_formal_memoir_plan p
   where p.run_id=run.id and not exists(select 1 from public.user_formal_memoir_chapter c where c.run_id=p.run_id and c.ordinal=p.ordinal);
 return public.formal_memoir_run_record(run)||jsonb_build_object('token',run.token,'fence',run.fence,'lease_until',run.lease_until,'next_ordinal',next_ordinal);
end $$;

CREATE FUNCTION public.claim_lifetime_collection_job(p_job_id uuid, p_run_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare job public.user_lifetime_collection_job%rowtype; claim_token uuid:=gen_random_uuid();
begin
 if p_run_seconds is null or p_run_seconds not between 1 and 600 then raise exception 'invalid job duration';end if;
 begin
  job:=public.lock_lifetime_collection_job(p_job_id);
 exception when serialization_failure then
  update public.user_lifetime_collection_job set state='STALE',token=null,lease_until=null,error='SOURCE_OR_COLLECTION_CHANGED' where id=p_job_id;
  return null;
 end;
 if job.state='SUCCEEDED' or job.token is not null and job.lease_until>clock_timestamp() then return null;end if;
 if job.attempts>=3 then
  update public.user_lifetime_collection_job set state='FAILED',token=null,lease_until=null,error='BOUNDED_JOB_RETRY' where id=p_job_id;
  return null;
 end if;
 update public.user_lifetime_collection_job set state='RUNNING',token=claim_token,lease_until=clock_timestamp()+make_interval(secs=>p_run_seconds),attempts=attempts+1,error=null
  where id=p_job_id returning * into job;
 return jsonb_build_object('id',job.id,'token',job.token,'user_id',job.user_id,'project_id',job.project_id,'kind',job.kind);
end $$;

CREATE FUNCTION public.claim_lifetime_memory_obligation(p_fence jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare owner uuid:=auth.uid(); conversation uuid:=(p_fence->'identity'->>'conversation_id')::uuid;
  project text; saved public.user_lifetime_memory_obligation%rowtype;
begin
  select project_id into project from public.user_lifetime_conversation where user_id=owner and conversation_id=conversation;
  if not found then raise exception 'conversation unavailable'; end if;
  perform 1 from public.user_memoir_project where user_id=owner and project_id=project for update;
  perform public.lock_lifetime_publication(p_fence);
  -- Inspect/retire at most 32 obsolete or exhausted entries per bounded claim.
  for saved in select * from public.user_lifetime_memory_obligation where user_id=owner and conversation_id=conversation
    and (status in ('pending','retryable') and next_attempt_at<=clock_timestamp()
      or status='running' and claim_expires_at<=clock_timestamp()) order by created_at,id limit 32 for update skip locked
  loop
    if saved.policy_epoch<>(p_fence->>'policy_epoch')::bigint or saved.execution_generation<>(p_fence->>'execution_generation')::bigint
      or not public.lifetime_obligation_origin_current(saved) then
      update public.user_lifetime_memory_obligation set status='superseded',projection=null,claim_token=null,claim_expires_at=null,
        error_code='stale_origin',updated_at=clock_timestamp() where id=saved.id;
      continue;
    end if;
    if saved.attempts>=5 then
      update public.user_lifetime_memory_obligation set status='failed',error_code='retry_exhausted',claim_token=null,claim_expires_at=null,
        updated_at=clock_timestamp() where id=saved.id;
      continue;
    end if;
    update public.user_lifetime_memory_obligation set status='running',attempts=attempts+1,claim_token=gen_random_uuid(),
      claim_expires_at=least(clock_timestamp()+interval '60 seconds',(select expires_at from public.user_agent_turn_lease where user_id=owner)),
      fence=p_fence,error_code=null,updated_at=clock_timestamp() where id=saved.id returning * into saved;
    return public.lifetime_obligation_record(saved);
  end loop;
  if exists(select 1 from public.user_lifetime_memory_obligation where user_id=owner and conversation_id=conversation
    and status in ('pending','running','retryable','failed')) then
    return jsonb_build_object('status','not_ready','backup_complete',false);
  end if;
  return null;
end $$;

CREATE FUNCTION public.claim_memoir_lane(p_lane_id uuid, p_run_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare lane public.user_memoir_lane%rowtype; identity public.user_lifetime_conversation%rowtype;
 project public.user_memoir_project%rowtype; snap public.user_lifetime_lane_snapshot%rowtype;
 previous public.user_lifetime_lane_snapshot%rowtype; run_token uuid:=gen_random_uuid(); rounds bigint; seed text; pins jsonb; news jsonb; news_manifest jsonb; privacy_hash text; previous_owner text;
begin
 if p_run_seconds is null or p_run_seconds not between 1 and 1800 then raise exception 'invalid run duration';end if;
 select * into lane from public.user_memoir_lane where id=p_lane_id;
 if not found then return null;end if;
 select * into identity from public.user_lifetime_conversation where user_id=lane.user_id and project_id=lane.project_id;
 if not found then return null;end if;
 select * into project from public.user_memoir_project where user_id=lane.user_id and project_id=lane.project_id for update;
 perform 1 from public.user_profile where user_id=lane.user_id for share;
 select * into identity from public.user_lifetime_conversation where user_id=lane.user_id and project_id=lane.project_id for share;
 select * into lane from public.user_memoir_lane where id=p_lane_id for update;
 if lane.token is not null and lane.lease_until>clock_timestamp() and lane.run_deadline>clock_timestamp() then return null;end if;
 if not lane.pending and lane.token is null or lane.available_at>clock_timestamp() or lane.attempts>=3 then return null;end if;
 previous_owner:=current_setting('request.jwt.claim.sub',true);
 perform set_config('request.jwt.claim.sub',lane.user_id::text,true);
 pins:=public.read_lifetime_pinned(identity.conversation_id);
 if lane.skill='guidance' then
   news:=public.read_user_historical_news(lane.project_id);
   news_manifest:=jsonb_build_object('context_revision',news->>'context_revision',
     'settings_revision',coalesce((select revision from public.user_historical_news_state where user_id=lane.user_id and project_id=lane.project_id),1),
     'enabled',news->'enabled','clues',(select coalesce(jsonb_agg(jsonb_build_object('id',c->>'id',
       'digest',encode(sha256(convert_to(c::text,'UTF8')),'hex'))),'[]') from jsonb_array_elements(news->'clues') c));
 end if;
 perform set_config('request.jwt.claim.sub',coalesce(previous_owner,''),true);
 privacy_hash:=encode(sha256(convert_to(jsonb_build_object('excluded_topics',pins->'excluded_topics',
   'paused_topics',pins->'paused_topics','privacy_complete',pins->'privacy_complete')::text,'UTF8')),'hex');
 select coalesce(max(ordinal),0) into rounds from public.user_completed_round where user_id=lane.user_id and project_id=lane.project_id;
 if lane.skill='composer' and (rounds<lane.target_milestone or lane.target_milestone=0 or exists(select 1 from public.user_narrator_source
   where user_id=lane.user_id and project_id=lane.project_id and status='active' and processing_status<>'succeeded')) then return null;end if;
 if lane.skill='guidance' and (not exists(select 1 from public.lifetime_two_lane_rollout where singleton and enabled)
   or exists(select 1 from public.user_agent_turn_lease where user_id=lane.user_id and expires_at>clock_timestamp())
   or exists(select 1 from public.user_narrator_source where user_id=lane.user_id and project_id=lane.project_id
     and status='active' and processing_status<>'succeeded')) then return null;end if;
 update public.user_lifetime_lane_snapshot set state='stale' where lane_id=lane.id and state='pending' and
   (policy_epoch<>project.policy_epoch or preference_revision<>identity.preference_revision or locale<>lane.locale
    or (lane.skill='composer' and event_high_water<>project.event_sequence)
    or (lane.skill='guidance' and (event_high_water<>project.event_sequence or source_high_water<>project.source_sequence or guidance_revision<>lane.guidance_revision)));
 select * into snap from public.user_lifetime_lane_snapshot where lane_id=lane.id and state='pending' order by created_at desc limit 1;
 if not found then
   select * into previous from public.user_lifetime_lane_snapshot where lane_id=lane.id and locale=lane.locale and state='completed' order by created_at desc limit 1;
   seed:=jsonb_build_object('owner',lane.user_id,'project',lane.project_id,'conversation',identity.conversation_id,
     'policy',project.policy_epoch,'preferences',identity.preference_revision,'privacy_digest',privacy_hash,'source',project.source_sequence,
     'events',project.event_sequence,'predecessor',previous.id,'predecessor_digest',previous.root_digest)::text;
   insert into public.user_lifetime_lane_snapshot(lane_id,user_id,project_id,conversation_id,policy_epoch,preference_revision,privacy_digest,locale,
     source_high_water,event_high_water,round_high_water,milestone,base_revision,predecessor,base_event,last_event,root_digest,guidance_revision,guidance_news)
   values(lane.id,lane.user_id,lane.project_id,identity.conversation_id,project.policy_epoch,identity.preference_revision,privacy_hash,lane.locale,
     project.source_sequence,project.event_sequence,rounds,lane.target_milestone,
     coalesce((select revision from public.user_memoir_edition where user_id=lane.user_id and project_id=lane.project_id and locale=lane.locale),0),
     previous.id,case when previous.preference_revision=identity.preference_revision and previous.policy_epoch=project.policy_epoch and previous.locale=lane.locale then previous.event_high_water else 0 end,
     case when previous.preference_revision=identity.preference_revision and previous.policy_epoch=project.policy_epoch and previous.locale=lane.locale then previous.event_high_water else 0 end,
     encode(sha256(convert_to(seed,'UTF8')),'hex'),lane.guidance_revision,coalesce(news_manifest,'{}')) returning * into snap;
 end if;
 update public.user_memoir_lane set token=run_token,lease_until=least(clock_timestamp()+interval '60 seconds',clock_timestamp()+make_interval(secs=>p_run_seconds)),
   run_deadline=clock_timestamp()+make_interval(secs=>p_run_seconds),pending=false,active_manifest='[]',active_events='[]',
   active_policy=snap.policy_epoch,active_through=snap.source_high_water,active_event=snap.event_high_water,
   active_round=snap.round_high_water,active_milestone=snap.milestone,active_locale=snap.locale,
   active_manuscript_revision=snap.base_revision,attempts=attempts+1,error=null where id=lane.id;
 return public.read_lifetime_memoir_lane_page(lane.id,run_token);
end $$;

CREATE FUNCTION public.clear_deleted_lifetime_name() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 update public.user_lifetime_chosen_name set authority='invalidated',chosen_name=null where user_id=old.user_id;
 return old;
end $$;

CREATE FUNCTION public.commit_lifetime_attribution_delivery(p_fence jsonb, p_client_turn_id uuid, p_reply_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare source public.user_narrator_source%rowtype; turn public.user_interview_turn%rowtype;
 question jsonb; event public.user_memory_event%rowtype; project text:=p_fence->'identity'->>'project_id';
begin
 perform public.lock_lifetime_publication(p_fence);
 select * into turn from public.user_interview_turn where user_id=auth.uid() and project_id=project and client_turn_id=p_client_turn_id;
 select * into source from public.user_narrator_source where user_id=auth.uid() and project_id=project
   and id=turn.source_id and version=turn.source_version and status='active';
 if not found or not exists(select 1 from public.user_lifetime_reply r where r.user_id=auth.uid()
   and r.conversation_id=(p_fence->'identity'->>'conversation_id')::uuid and r.client_turn_id=p_client_turn_id and r.memory_id=p_reply_id
   and r.policy_epoch=(p_fence->>'policy_epoch')::bigint and r.execution_generation=(p_fence->>'execution_generation')::bigint
   and r.preference_revision=(p_fence->>'preference_revision')::bigint) then return false;end if;
 select q into question from jsonb_array_elements(turn.collector->'plan'->'candidates') q
   where q->>'id'=turn.collector->'plan'->>'chosen_id';
 if question->'context'->>'event_id'=turn.collector->'plan'->>'active_event_id'
   and length(coalesce(question->>'question',''))>0 and strpos(turn.collector->>'reply',question->>'question')>0 then
   select * into event from public.user_memory_event where user_id=auth.uid() and project_id=project
     and id=question->'context'->>'event_id' and status='active';
 end if;
 insert into public.user_memory_delivered_context values(auth.uid(),project,source.id,source.version,p_client_turn_id,p_reply_id,
   (p_fence->>'policy_epoch')::bigint,(p_fence->>'execution_generation')::bigint,(p_fence->>'preference_revision')::bigint,event.id,event.revision)
 on conflict do nothing;
 perform public.prune_lifetime_question_pool(auth.uid(),project);
 return true;
end $$;

CREATE FUNCTION public.commit_lifetime_collection_job_page(p_fence jsonb, p_result jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare job public.user_lifetime_collection_job%rowtype; current_page jsonb; evidence jsonb; output_digest text;
 node_id uuid:=gen_random_uuid(); node_meta jsonb; section record; child record; refs text[]; expected text[];
 child_ids uuid[]:='{}'; node_level integer:=0; finished boolean; new_digest text; sections jsonb:='[]';
begin
 job:=public.lock_lifetime_collection_job((p_fence->>'job_id')::uuid,(p_fence->>'token')::uuid);
 current_page:=public.read_lifetime_collection_job_page(job.id,job.token);
 if current_page-'complete' is distinct from p_fence-'complete' then raise exception 'stale collection page commit' using errcode='PT409';end if;
 if job.kind='BuildOutline' then
  if jsonb_typeof(p_result) is distinct from 'object' or p_result-array['title','sections']<>'{}'::jsonb
   or jsonb_typeof(p_result->'title') is distinct from 'string' or length(p_result->>'title') not between 1 and 200
   or jsonb_typeof(p_result->'sections') is distinct from 'array' or jsonb_array_length(p_result->'sections') not between 1 and 100
   or octet_length(p_result::text)>65536 then raise exception 'invalid outline result';end if;
  for section in select v,n from jsonb_array_elements(p_result->'sections') with ordinality a(v,n) loop
   if jsonb_typeof(section.v) is distinct from 'object' or jsonb_typeof(section.v->'title') is distinct from 'string'
    or length(section.v->>'title') not between 1 and 200 then raise exception 'invalid outline section';end if;
   if current_page->>'phase'='leaf' then
    if section.v-array['title','memory_ids']<>'{}'::jsonb or jsonb_typeof(section.v->'memory_ids') is distinct from 'array'
     or jsonb_array_length(section.v->'memory_ids')<>1 then raise exception 'invalid leaf coverage';end if;
    refs:=array_append(refs,section.v->'memory_ids'->>0);
   else
    if section.v-array['title','section_ids']<>'{}'::jsonb or jsonb_typeof(section.v->'section_ids') is distinct from 'array'
     or jsonb_array_length(section.v->'section_ids')<1 then raise exception 'invalid merge coverage';end if;
    refs:=refs||array(select jsonb_array_elements_text(section.v->'section_ids'));
   end if;
   sections:=sections||jsonb_build_array(jsonb_build_object('id',node_id::text||':'||section.n::text,'title',section.v->>'title'));
  end loop;
  if current_page->>'phase'='leaf' then
   expected:=array[current_page->'sources'->0->>'id'];
  else
   select array_agg(s->>'id' order by s->>'id') into expected from jsonb_array_elements(current_page->'child_groups')c
    cross join lateral jsonb_array_elements(c->'sections')s;
   select array_agg((v->>'id')::uuid) into child_ids from jsonb_array_elements(current_page->'child_groups')v;
   select max(level)+1 into node_level from public.user_lifetime_collection_job_node where id=any(child_ids) and job_id=job.id;
  end if;
  if (select array_agg(x order by x) from unnest(refs)x) is distinct from expected
   or cardinality(refs)<>(select count(distinct x) from unnest(refs)x) then raise exception 'outline omitted duplicated or invented coverage';end if;
  new_digest:=encode(sha256(convert_to(jsonb_build_object('job',job.id,'owner',job.user_id,'snapshot',job.snapshot_id,
   'policy',job.policy_epoch,'preferences',job.preference_revision,'page',current_page->>'page_digest','output',p_result)::text,'UTF8')),'hex');
  node_meta:=jsonb_build_object('id',node_id,'digest',new_digest,'title',p_result->>'title','sections',sections);
  if octet_length(node_meta::text)>12000 then raise exception 'outline title metadata budget exceeded' using errcode='54000';end if;
  insert into public.user_lifetime_collection_job_node(id,job_id,ordinal,level,metadata,result,digest,children)
   values(node_id,job.id,job.next_page,node_level,node_meta,p_result,new_digest,child_ids);
  if current_page->>'phase'='merge' then
   for section in select v,n from jsonb_array_elements(p_result->'sections') with ordinality a(v,n) loop
    for child in select value from jsonb_array_elements_text(section.v->'section_ids') loop
     insert into public.user_lifetime_collection_job_edge(job_id,parent_node,parent_section,child_node,child_section)
      values(job.id,node_id,section.n,(split_part(child.value,':',1))::uuid,(split_part(child.value,':',2))::integer);
    end loop;
   end loop;
   update public.user_lifetime_collection_job_node set parent_id=node_id where job_id=job.id and id=any(child_ids) and parent_id is null;
  end if;
 else
  if p_result is not null then raise exception 'deterministic task cannot accept generated content';end if;
 end if;
 if current_page->>'phase'='leaf' then
  evidence:=current_page->'sources'->0;
  insert into public.user_lifetime_collection_job_page(job_id,page_number,source_id,source_version,char_start,char_end,page_digest)
  values(job.id,job.next_page,(evidence->>'id')::uuid,(evidence->>'version')::bigint,(evidence->>'char_start')::integer,
   (evidence->>'char_end')::integer,current_page->>'page_digest');
 end if;
 output_digest:=encode(sha256(convert_to(job.root_digest||':'||(current_page->>'page_digest')||':'||coalesce(new_digest,''),'UTF8')),'hex');
 finished:=job.next_page+1>=job.source_pages and (job.kind<>'BuildOutline' or
  (select count(*)=1 from public.user_lifetime_collection_job_node where job_id=job.id and parent_id is null));
 update public.user_lifetime_collection_job set next_page=next_page+1,root_digest=output_digest,
  state=case when finished then 'SUCCEEDED' else 'RUNNING' end where id=job.id;
 return jsonb_build_object('complete',finished,'next_page',job.next_page+1,'root_digest',output_digest);
end $$;

CREATE FUNCTION public.commit_lifetime_interview_memory(p_snapshot_fence jsonb, p_lease_token uuid, p_thread_id text, p_content text, p_source_paths text[] DEFAULT '{}'::text[], p_source_sequence bigint DEFAULT NULL::bigint, p_project_id text DEFAULT NULL::text, p_client_turn_id uuid DEFAULT NULL::uuid, p_user_response boolean DEFAULT true, p_life_stage text DEFAULT 'unplaced'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_owner uuid:=auth.uid(); turn public.user_interview_turn%rowtype; project public.user_memoir_project%rowtype;
  suffix text; prefix text:='Storyteller: ';
begin
  if v_owner is null then raise exception 'authenticated user required' using errcode='42501'; end if;
  select * into project from public.user_memoir_project where user_id=v_owner and project_id=p_project_id for update;
  if p_snapshot_fence is not null then
    if p_snapshot_fence->'identity'->>'project_id' is distinct from p_project_id
      or p_snapshot_fence->'identity'->>'owner_id' is distinct from v_owner::text
      or p_snapshot_fence->>'lease_token' is distinct from p_lease_token::text then
      raise exception 'canonical reply scope mismatch' using errcode='42501';end if;
    perform public.lock_lifetime_publication(p_snapshot_fence);
  end if;

  select * into turn from public.user_interview_turn where user_id=v_owner and project_id=p_project_id and client_turn_id=p_client_turn_id;
  if found and not exists(select 1 from public.user_memory where user_id=v_owner and project_id=p_project_id and client_turn_id=p_client_turn_id) then
    if turn.sequence is distinct from project.interview_sequence or (p_snapshot_fence is null and turn.source_sequence is distinct from project.source_sequence) or
      (p_snapshot_fence is null and turn.policy_epoch is distinct from project.policy_epoch) or turn.collector is null or
      (turn.source_id is not null and not exists(select 1 from public.user_narrator_source where user_id=v_owner and project_id=p_project_id
        and id=turn.source_id and version=turn.source_version and status='active')) then
      raise exception 'stale interview publication' using errcode='PT409'; end if;
    suffix:=E'\nMemory Spark: ' || (turn.collector->>'reply');
    if p_content is null or length(p_content)<length(prefix)+length(suffix) or left(p_content,length(prefix))<>prefix or
      right(p_content,length(suffix))<>suffix or
      md5(substr(p_content,length(prefix)+1,length(p_content)-length(prefix)-length(suffix))) is distinct from turn.input_hash or
      p_thread_id is distinct from turn.collector->>'thread_id' or p_user_response is distinct from (turn.source_id is not null) then
      raise exception 'interview publication does not match accepted collector' using errcode='22023'; end if;
  end if;
  return public.commit_user_agent_turn_before_photos(p_lease_token,p_thread_id,p_content,p_source_paths,
    p_source_sequence,p_project_id,p_client_turn_id,p_user_response,p_life_stage);
end $$;

CREATE FUNCTION public.commit_lifetime_memoir_lane_page(p_lane_id uuid, p_token uuid, p_page_number bigint, p_result jsonb, p_page_digest text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare page jsonb; result jsonb; snap public.user_lifetime_lane_snapshot%rowtype;
  prior public.user_lifetime_lane_page_receipt%rowtype; original public.user_narrator_source%rowtype;
  existing public.user_lifetime_continuity%rowtype; item jsonb; data jsonb; ref jsonb; fingerprint text;
  delegated boolean; epoch bigint;
begin
  snap:=public.lock_lifetime_memoir_lane(p_lane_id,p_token);
  fingerprint:=encode(sha256(convert_to(p_result::text,'UTF8')),'hex');
  select * into prior from public.user_lifetime_lane_page_receipt
    where snapshot_id=snap.id and page_number=p_page_number;
  if prior.continuity_digest is not null then
    if prior.continuity_digest is distinct from fingerprint or prior.page_digest is distinct from p_page_digest then
      raise exception 'background continuity replay conflict' using errcode='PT409';end if;
    return jsonb_build_object('status','page_saved','replayed',true);
  end if;
  page:=public.read_lifetime_memoir_lane_page(p_lane_id,p_token);
  delegated:=page->'two_lane'->>'reply_contract'='reply-v2' and page->>'skill'='timeline';
  if delegated then
    if p_page_number is distinct from snap.page_number or p_page_digest is distinct from page->>'page_digest'
      or jsonb_typeof(p_result) is distinct from 'object'
      or jsonb_typeof(p_result->'continuity_updates') is distinct from 'array'
      or jsonb_array_length(p_result->'continuity_updates')>8 or octet_length(p_result::text)>131072 then
      raise exception 'bounded current background continuity required' using errcode='22023';end if;
    if page->'two_lane'->>'work_mode'='reply_only' and jsonb_array_length(p_result->'continuity_updates')>0 then
      raise exception 'reply only work cannot create continuity' using errcode='22023';end if;
    select * into original from public.user_narrator_source where user_id=snap.user_id and project_id=snap.project_id
      and id=(page->'source'->>'id')::uuid and version=(page->'source'->>'version')::bigint and status='active';
    if not found then raise exception 'current background original required' using errcode='PT409';end if;
    for item in select value from jsonb_array_elements(p_result->'continuity_updates') loop
      if jsonb_typeof(item) is distinct from 'object' or not(item ?& array['record_id','kind','data'])
        or exists(select 1 from jsonb_object_keys(item) k where k not in ('record_id','kind','data'))
        or coalesce(item->>'kind','') not in ('person','unresolved_reference','commitment')
        or jsonb_typeof(item->'record_id') is distinct from 'string' or length(item->>'record_id') not between 1 and 128 then
        raise exception 'descriptive background continuity required' using errcode='22023';end if;
      data:=item->'data';ref:=data->'source_refs'->0;
      if jsonb_typeof(data) is distinct from 'object' or not(data ?& array['text','assertion','uncertainty','source_refs'])
        or exists(select 1 from jsonb_object_keys(data) k where k not in ('text','assertion','uncertainty','source_refs'))
        or jsonb_typeof(data->'text') is distinct from 'string' or length(data->>'text') not between 1 and 500
        or length(btrim(data->>'text'))=0
        or coalesce(data->>'assertion','') not in ('asserted','inferred')
        or jsonb_typeof(data->'uncertainty') not in ('string','null') or length(coalesce(data->>'uncertainty',''))>500
        or (data->>'assertion'='inferred' and length(btrim(coalesce(data->>'uncertainty','')))=0)
        or jsonb_typeof(data->'source_refs') is distinct from 'array' or jsonb_array_length(data->'source_refs')<>1
        or jsonb_typeof(ref) is distinct from 'object' or not(ref ?& array['source_id','version','char_start','char_end','quote'])
        or exists(select 1 from jsonb_object_keys(ref) k where k not in ('source_id','version','char_start','char_end','quote'))
        or ref->>'source_id' is distinct from original.id::text or ref->>'version' is distinct from original.version::text
        or jsonb_typeof(ref->'source_id') is distinct from 'string' or jsonb_typeof(ref->'version') is distinct from 'number'
        or coalesce(ref->>'version','') !~ '^[1-9][0-9]*$'
        or jsonb_typeof(ref->'char_start') is distinct from 'number' or coalesce(ref->>'char_start','') !~ '^[0-9]+$'
        or jsonb_typeof(ref->'char_end') is distinct from 'number' or coalesce(ref->>'char_end','') !~ '^[1-9][0-9]*$'
        or (ref->>'char_start')::integer<(page->'source'->>'char_start')::integer
        or (ref->>'char_end')::integer>(page->'source'->>'char_end')::integer
        or (ref->>'char_end')::integer<=(ref->>'char_start')::integer
        or jsonb_typeof(ref->'quote') is distinct from 'string' or data->>'text' is distinct from ref->>'quote'
        or substring(original.text from (ref->>'char_start')::integer+1 for
          (ref->>'char_end')::integer-(ref->>'char_start')::integer) is distinct from ref->>'quote' then
        raise exception 'exact admitted background continuity evidence required' using errcode='22023';end if;
    end loop;
  elsif p_result ? 'continuity_updates' then
    raise exception 'background continuity requires a saved reply v2 handoff' using errcode='22023';
  end if;
  result:=public.commit_lifetime_memoir_lane_page_before_place_progress(
    p_lane_id,p_token,p_page_number,case when delegated then p_result-'continuity_updates' else p_result end,p_page_digest);
  if delegated then
    if result->>'status' is distinct from 'page_saved' then raise exception 'atomic background continuity commit required';end if;
    -- Keep the model's input digest unchanged until the canonical page has committed.
    select policy_epoch into epoch from public.user_memoir_project where user_id=snap.user_id and project_id=snap.project_id;
    if not exists(select 1 from public.user_narrator_source where user_id=original.user_id and project_id=original.project_id
      and id=original.id and version=original.version and status='active') then
      raise exception 'background original changed during canonical commit' using errcode='PT409';end if;
    for item in select value from jsonb_array_elements(p_result->'continuity_updates') loop
      data:=item->'data';
      select * into existing from public.user_lifetime_continuity where user_id=snap.user_id
        and conversation_id=snap.conversation_id and record_id=item->>'record_id';
      if found then
        if existing.kind is distinct from item->>'kind' or existing.data is distinct from data
          or existing.policy_epoch is distinct from epoch then
          raise exception 'background continuity identity conflict' using errcode='PT409';end if;
      else
        insert into public.user_lifetime_continuity(user_id,conversation_id,record_id,kind,revision,policy_epoch,data,last_source_sequence)
          values(snap.user_id,snap.conversation_id,item->>'record_id',item->>'kind',1,epoch,data,original.sequence);
      end if;
    end loop;
    update public.user_lifetime_lane_page_receipt set continuity_digest=fingerprint
      where snapshot_id=snap.id and page_number=p_page_number;
    if not found then raise exception 'background continuity commit receipt required';end if;
  end if;
  if result->>'status'='page_saved' and result->>'replayed' is distinct from 'true'
      and page->>'skill'='timeline' and page ? 'two_lane'
      and page->'two_lane'->>'work_mode'='extract'
      and (not(page->'two_lane' ? 'selected_skills') or page->'two_lane'->'selected_skills' ?& array['memoir-author-timeline','memoir-place-journey'])
      and jsonb_array_length(coalesce(p_result->'place_journeys','[]'::jsonb))=0 then
    perform public.background_skill_receipt(
      page,'place','memoir-place-journey','embedded','skipped','no_place_cue');
  end if;
  return result;
end $$;

CREATE FUNCTION public.commit_lifetime_memoir_lane_page_before_attribution(p_lane_id uuid, p_token uuid, p_page_number bigint, p_result jsonb, p_page_digest text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
begin
 if not (p_result ? 'strategy_proposal') and not exists(select 1 from public.lifetime_two_lane_rollout where singleton and enabled) then
   return public.commit_lifetime_memoir_lane_page_before_two_lanes(p_lane_id,p_token,p_page_number,p_result,p_page_digest);
 end if;
 if exists(select 1 from public.lifetime_two_lane_rollout where singleton and enabled)
   and public.read_lifetime_memoir_lane_page(p_lane_id,p_token) ? 'memory_summary' then
   raise exception 'semantic page requires its canonical writer' using errcode='PT409';end if;
 return public.commit_lifetime_memoir_lane_page_before_semantic(p_lane_id,p_token,p_page_number,p_result,p_page_digest);
end $$;

CREATE FUNCTION public.commit_lifetime_memoir_lane_page_before_batches(p_lane_id uuid, p_token uuid, p_page_number bigint, p_result jsonb, p_page_digest text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare page jsonb; result jsonb;
begin
 page:=public.read_lifetime_memoir_lane_page(p_lane_id,p_token);
 result:=public.commit_lifetime_memoir_lane_page_before_rework(p_lane_id,p_token,p_page_number,p_result,p_page_digest);
 if p_page_number=(page->>'page_number')::bigint and page->'editorial_request'<>'null'::jsonb then
   update public.user_workspace_section_rework set composed_snapshot_id=(page->>'snapshot_id')::uuid where user_id=(page->>'user_id')::uuid
     and project_id=page->>'project_id' and request_id=(page->'editorial_request'->>'request_id')::uuid;
 end if;
 return result;
end $$;

CREATE FUNCTION public.commit_lifetime_memoir_lane_page_before_place_progress(p_lane_id uuid, p_token uuid, p_page_number bigint, p_result jsonb, p_page_digest text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb; page jsonb;
begin
 page:=public.read_lifetime_memoir_lane_page(p_lane_id,p_token);
 result:=public.commit_lifetime_memoir_lane_page_before_skills(p_lane_id,p_token,p_page_number,p_result,p_page_digest);
 if result->>'status'='page_saved' and result->>'replayed' is distinct from 'true' then
   update public.user_background_skill_work set status='saved',reason=null,page_digest=p_page_digest,
     lease_token=(page->>'token')::uuid,updated_at=clock_timestamp()
   where lane_id=p_lane_id and snapshot_id=(page->>'snapshot_id')::uuid
     and id=public.background_skill_id(page,phase) and status in ('completed','failed') and model_invoked;
   if not exists(select 1 from public.user_background_skill_work where lane_id=p_lane_id and page_digest=p_page_digest and status='saved')
     and page->'two_lane'->>'work_mode' is distinct from 'reply_only' then
     perform public.background_skill_receipt(page,case when page->>'skill'='composer' then 'commit' else 'extract' end,
       case when page->>'skill'='composer' then 'memoir-composer'
         when page->'two_lane' ? 'selected_skills' and not(page->'two_lane'->'selected_skills' ? 'memoir-author-timeline')
           then 'memoir-place-journey' else 'memoir-author-timeline' end,
       'model','saved','invocation_receipt_unavailable');
   end if;
   if page->'two_lane'->>'work_mode'='reply_only' then
     perform public.background_skill_receipt(page,'extract','memoir-author-timeline','model','skipped','reply_only');
   end if;
   if page->>'skill'='timeline' and page ? 'two_lane' and jsonb_array_length(coalesce(p_result->'place_journeys','[]'))>0
     and (not(page->'two_lane' ? 'selected_skills') or page->'two_lane'->'selected_skills' ? 'memoir-author-timeline') then
     perform public.background_skill_receipt(page,'place','memoir-place-journey','embedded','saved');
   end if;
 end if;
 return result;
end $$;

CREATE FUNCTION public.commit_lifetime_memoir_lane_page_before_progressive_rework(p_lane_id uuid, p_token uuid, p_page_number bigint, p_result jsonb, p_page_digest text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare snap public.user_lifetime_lane_snapshot%rowtype; page jsonb; result jsonb; last_message jsonb;
begin
  snap:=public.lock_lifetime_memoir_lane(p_lane_id,p_token);
  page:=public.read_lifetime_memoir_lane_page(p_lane_id,p_token);
  result:=public.commit_lifetime_memoir_lane_page_before_summary_windows(p_lane_id,p_token,p_page_number,p_result,p_page_digest);
  if p_page_number=snap.page_number and jsonb_array_length(page->'batch'->'new_messages')>0 then
    last_message:=page->'batch'->'new_messages'->-1;
    update public.user_lifetime_lane_snapshot set summary_source=(last_message->>'sequence')::bigint,
      summary_offset=case when last_message->>'char_end'=last_message->>'original_length' then 100000
        else (last_message->>'char_end')::integer end where id=snap.id;
  end if;
  return result;
end $$;

CREATE FUNCTION public.memoir_review_ready(p_review jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 select case when jsonb_typeof(p_review) is distinct from 'object'
   or p_review->'ready_for_user_review' is distinct from 'true'::jsonb
   or p_review->'publication_approved' is distinct from 'false'::jsonb
   or jsonb_typeof(p_review->'findings') is distinct from 'array' then false
 else not exists(select 1 from jsonb_array_elements(p_review->'findings') f
   where jsonb_typeof(f) is distinct from 'object'
     or coalesce(f->>'severity','') not in ('blocking','warning','info')
     or coalesce(f->>'verdict','') not in ('supported','editorial')
     or f->>'severity'='blocking'
     or jsonb_typeof(f->'explanation') is distinct from 'string'
     or length(btrim(f->>'explanation'))=0) end;
$$;

CREATE FUNCTION public.memoir_craft_review_covers(p_craft jsonb, p_units jsonb, p_originals jsonb, p_followups_allowed boolean) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare rating jsonb; evidence jsonb; original jsonb; unit jsonb; ref jsonb; criterion text; matches integer;
 spaces text:=U&'\0009\000A\000B\000C\000D\001C\001D\001E\001F\0020\0085\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000';
begin
 if jsonb_typeof(p_craft) is distinct from 'object' then return false;end if;
 if p_craft->>'rubric_id' is distinct from 'memoir-craft-v1'
   or p_craft-array['rubric_id','ratings']<>'{}'::jsonb
   or jsonb_typeof(p_craft->'ratings') is distinct from 'array' then return false;end if;
 if jsonb_array_length(p_craft->'ratings')<>8 then return false;end if;
 foreach criterion in array array['focus','scene_craft','voice','supported_vulnerability',
     'retrospective_reflection','transformation','reader_resonance','fairness'] loop
   select count(*) into matches from jsonb_array_elements(p_craft->'ratings') r where r->>'criterion'=criterion;
   if matches<>1 then return false;end if;
 end loop;
 for rating in select value from jsonb_array_elements(p_craft->'ratings') loop
   if jsonb_typeof(rating) is distinct from 'object' then return false;end if;
   if not (rating ?& array['criterion','applicability','score','confidence','confidence_basis','reason',
       'source_evidence','prose_evidence','suggested_follow_up'])
     or rating-array['criterion','applicability','score','confidence','confidence_basis','reason',
       'source_evidence','prose_evidence','suggested_follow_up']<>'{}'::jsonb
     or coalesce(rating->>'applicability','') not in ('applicable','not_applicable','insufficient_evidence')
     or coalesce(rating->>'confidence','') not in ('high','medium','low')
     or jsonb_typeof(rating->'reason') is distinct from 'string'
     or jsonb_typeof(rating->'confidence_basis') is distinct from 'string'
     or length(btrim(rating->>'reason',spaces))=0 or length(rating->>'reason')>300
     or length(btrim(rating->>'confidence_basis',spaces))=0 or length(rating->>'confidence_basis')>200
     or jsonb_typeof(rating->'source_evidence') is distinct from 'array'
     or jsonb_typeof(rating->'prose_evidence') is distinct from 'array' then return false;end if;
   if jsonb_array_length(rating->'source_evidence')>2 or jsonb_array_length(rating->'prose_evidence')>2 then return false;end if;
   if rating->>'applicability'='applicable' then
     if jsonb_typeof(rating->'score') is distinct from 'number' or rating->>'score' not in ('0','1','2','3')
       or jsonb_array_length(rating->'source_evidence')=0 or jsonb_array_length(rating->'prose_evidence')=0 then return false;end if;
   elsif rating->'score' is distinct from 'null'::jsonb then return false;end if;
   if rating->'suggested_follow_up' is distinct from 'null'::jsonb then
     if p_followups_allowed is distinct from true or rating->>'applicability'<>'insufficient_evidence'
       or jsonb_typeof(rating->'suggested_follow_up') is distinct from 'string'
       or length(btrim(rating->>'suggested_follow_up',spaces))=0
       or length(rating->>'suggested_follow_up')>240 then return false;end if;
   end if;
   for evidence in select value from jsonb_array_elements(rating->'source_evidence') loop
     if jsonb_typeof(evidence) is distinct from 'object' then return false;end if;
     if evidence-array['source_ref','excerpt']<>'{}'::jsonb
       or jsonb_typeof(evidence->'excerpt') is distinct from 'string'
       or length(btrim(evidence->>'excerpt',spaces))=0 or length(evidence->>'excerpt')>160 then return false;end if;
     select value into original from jsonb_array_elements(p_originals) o where o->'source_ref'=evidence->'source_ref';
     if original is null or strpos(original->>'quote',evidence->>'excerpt')=0 then return false;end if;
   end loop;
   for evidence in select value from jsonb_array_elements(rating->'prose_evidence') loop
     if jsonb_typeof(evidence) is distinct from 'object' then return false;end if;
     if evidence-array['section_id','field','excerpt']<>'{}'::jsonb
       or jsonb_typeof(evidence->'excerpt') is distinct from 'string'
       or length(btrim(evidence->>'excerpt',spaces))=0 or length(evidence->>'excerpt')>160 then return false;end if;
     select value into unit from jsonb_array_elements(p_units) u
       where u->>'section_id'=evidence->>'section_id' and u->>'field'=evidence->>'field';
     if unit is null or strpos(unit->>'excerpt',evidence->>'excerpt')=0 then return false;end if;
     if jsonb_array_length(rating->'source_evidence')>0 and not exists(
       select 1 from jsonb_array_elements(unit->'source_refs') r,jsonb_array_elements(rating->'source_evidence') s
       where r->>'source_id'=s->'source_ref'->>'source_id' and r->>'version'=s->'source_ref'->>'version'
         and r->'char_start'=s->'source_ref'->'char_start' and r->'char_end'=s->'source_ref'->'char_end') then return false;end if;
   end loop;
 end loop;
 return true;
end $$;

CREATE FUNCTION public.memoir_review_covers(p_page jsonb, p_result jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare review jsonb:=p_result->'review'; units jsonb:='[]'; originals jsonb:='[]'; sections jsonb;
 section jsonb; unit jsonb; check_item jsonb; contribution jsonb; witness jsonb; event jsonb; ref jsonb;
 source jsonb; normalized jsonb; field_name text; body jsonb; quote text; matches integer;
begin
 if not public.memoir_review_ready(review) or review->'contract_version' is distinct from '3'::jsonb
   or jsonb_typeof(review->'prose_checks') is distinct from 'array'
   or jsonb_typeof(review->'contributions') is distinct from 'array'
   or jsonb_typeof(p_result->'sections') is distinct from 'array'
   or jsonb_array_length(review->'prose_checks')>1024 or jsonb_array_length(review->'contributions')>128 then return false;end if;
 sections:=p_result->'sections';
 if jsonb_typeof(p_result->'draft'->'title')='string' and length(p_result->'draft'->>'title')>0 then
   sections:=sections||jsonb_build_array(jsonb_build_object('id','__draft_title',
     'heading',jsonb_build_object('title',p_result->'draft'->>'title'),
     'source_refs',p_result->'draft'->'title_source_refs'));
 end if;
 for section in select value from jsonb_array_elements(sections) loop
   foreach field_name in array array['text','caption','alt','title','subtitle'] loop
     body:=case when field_name in ('title','subtitle') then section->'heading' else section->'block' end;
     if jsonb_typeof(body->field_name)='string' and length(body->>field_name)>0 then
       units:=units||jsonb_build_array(jsonb_build_object('section_id',section->>'id','field',field_name,
         'excerpt',body->>field_name,'source_refs',section->'source_refs'));
     end if;
   end loop;
 end loop;
 if jsonb_array_length(units)<>jsonb_array_length(review->'prose_checks') then return false;end if;
 for unit in select value from jsonb_array_elements(units) loop
   select count(*) into matches from jsonb_array_elements(review->'prose_checks') c
     where c->>'section_id'=unit->>'section_id' and c->>'field'=unit->>'field';
   if matches<>1 then return false;end if;
   select value into check_item from jsonb_array_elements(review->'prose_checks')
     where value->>'section_id'=unit->>'section_id' and value->>'field'=unit->>'field';
   if check_item->'excerpt' is distinct from unit->'excerpt' or check_item->>'verdict' is distinct from 'supported'
     or jsonb_typeof(check_item->'explanation') is distinct from 'string'
     or not (check_item->>'explanation' ~ '[^[:space:]]')
     or jsonb_typeof(check_item->'source_refs') is distinct from 'array' then return false;end if;
   if jsonb_array_length(check_item->'source_refs') not between 1 and 64 then return false;end if;
   for ref in select value from jsonb_array_elements(check_item->'source_refs') loop
     if not exists(select 1 from jsonb_array_elements(unit->'source_refs') r
       where r->>'source_id'=ref->>'source_id' and r->>'version'=ref->>'version'
         and r->'char_start'=ref->'char_start' and r->'char_end'=ref->'char_end') then return false;end if;
   end loop;
 end loop;
 for event in select value from jsonb_array_elements(case when p_page ? 'batch' then p_page->'batch'->'events'
     else jsonb_build_array(p_page->'partition') end) loop
   for ref in select value from jsonb_array_elements(event->'source_refs') loop
     normalized:=jsonb_build_object('source_id',ref->>'source_id','version',ref->>'version',
       'char_start',ref->'char_start','char_end',ref->'char_end');
     if originals @> jsonb_build_array(jsonb_build_object('source_ref',normalized)) then continue;end if;
     select value into source from jsonb_array_elements(case when p_page ? 'batch' then p_page->'batch'->'sources'
       else jsonb_build_array(p_page->'source') end) where value->>'id'=ref->>'source_id' and value->>'version'=ref->>'version';
     if source is null then return false;end if;
     quote:=substring(source->>'text' from (ref->>'char_start')::integer-coalesce((source->>'char_start')::integer,0)+1
       for (ref->>'char_end')::integer-(ref->>'char_start')::integer);
     if quote is null or length(quote)=0 then return false;end if;
     originals:=originals||jsonb_build_array(jsonb_build_object('source_ref',normalized,'quote',quote));
   end loop;
 end loop;
 if jsonb_array_length(originals)<>jsonb_array_length(review->'contributions') then return false;end if;
 for body in select value from jsonb_array_elements(originals) loop
   select count(*) into matches from jsonb_array_elements(review->'contributions') c where c->'source_ref'=body->'source_ref';
   if matches<>1 then return false;end if;
   select value into contribution from jsonb_array_elements(review->'contributions') where value->'source_ref'=body->'source_ref';
   if contribution->'quote' is distinct from body->'quote' or jsonb_typeof(contribution->'reason') is distinct from 'string'
     or not (contribution->>'reason' ~ '[^[:space:]]')
     or coalesce(contribution->>'disposition','') not in ('represented','deferred')
     or jsonb_typeof(contribution->'prose') is distinct from 'array' then return false;end if;
   if contribution->>'disposition'='deferred' then
     if jsonb_array_length(contribution->'prose')<>0 then return false;end if;
     continue;
   end if;
   if jsonb_array_length(contribution->'prose') not between 1 and 64 then return false;end if;
   for witness in select value from jsonb_array_elements(contribution->'prose') loop
     select value into unit from jsonb_array_elements(units) where value->>'section_id'=witness->>'section_id' and value->>'field'=witness->>'field';
     ref:=contribution->'source_ref';
     -- Use the same Unicode whitespace set as Python str.strip(), independent
     -- of the database locale. This predicate never rewrites stored prose.
     if unit is null or jsonb_typeof(witness->'excerpt') is distinct from 'string'
       or length(btrim(witness->>'excerpt',U&'\0009\000A\000B\000C\000D\001C\001D\001E\001F\0020\0085\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000'))=0
       or strpos(unit->>'excerpt',witness->>'excerpt')=0 then return false;end if;
     if not exists(select 1 from jsonb_array_elements(unit->'source_refs') r
       where r->>'source_id'=ref->>'source_id' and r->>'version'=ref->>'version'
         and (r->>'char_start')::integer<(ref->>'char_end')::integer and (r->>'char_end')::integer>(ref->>'char_start')::integer) then return false;end if;
   end loop;
 end loop;
 -- Canonical composition currently permits no interview follow-ups. Advisory
 -- suggestions remain private and cannot bypass that host-owned policy.
 return public.memoir_craft_review_covers(review->'craft',units,originals,false);
end $$;

CREATE FUNCTION public.commit_lifetime_memoir_lane_page_before_rework(p_lane_id uuid, p_token uuid, p_page_number bigint, p_result jsonb, p_page_digest text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $memoir$
declare snap public.user_lifetime_lane_snapshot%rowtype; lane public.user_memoir_lane%rowtype;
 page jsonb; ref jsonb; section jsonb; item jsonb; result_hash text; new_root text; disposition text;
 prior public.user_lifetime_lane_page_receipt%rowtype; protected public.user_lifetime_memoir_section%rowtype; protected_safe boolean; manuscript_locked boolean:=false; source_id uuid; event_id text; current_source_version bigint;
 previous_setting text; previous_owner text;
begin
 snap:=public.lock_lifetime_memoir_lane(p_lane_id,p_token);
 select * into lane from public.user_memoir_lane where id=p_lane_id;
 if jsonb_typeof(p_result) is distinct from 'object' or octet_length(p_result::text)>131072 then
   raise exception 'bounded page result required' using errcode='22023';end if;
 result_hash:=encode(sha256(convert_to(p_result::text,'UTF8')),'hex');
 if p_page_number<snap.page_number then
   select * into prior from public.user_lifetime_lane_page_receipt where snapshot_id=snap.id and page_number=p_page_number;
   if found and prior.result_digest=result_hash and prior.page_digest=p_page_digest then return jsonb_build_object('status','page_saved','replayed',true);end if;
   raise exception 'canonical page replay conflict' using errcode='PT409';
 end if;
 if p_page_number is distinct from snap.page_number then raise exception 'canonical page order conflict' using errcode='PT409';end if;
 page:=public.read_lifetime_memoir_lane_page(lane.id,p_token);
 if p_page_digest is distinct from page->>'page_digest' then raise exception 'stale canonical page digest' using errcode='PT409';end if;
 if (page->>'complete')::boolean then raise exception 'snapshot completion requires root commit';end if;
 source_id:=(page->'source'->>'id')::uuid;current_source_version:=(page->'source'->>'version')::bigint;
 if lane.skill='timeline' then
   if jsonb_typeof(p_result->'events') is distinct from 'array' or jsonb_array_length(p_result->'events')>100 then
     raise exception 'bounded event proposals required';end if;
   for item in select value from jsonb_array_elements(p_result->'events') loop
     if exists(select 1 from jsonb_array_elements(item->'source_refs') primary_ref
         where primary_ref->>'source_id'<>source_id::text or primary_ref->>'version'<>current_source_version::text) then
       raise exception 'primary testimony requires current source' using errcode='22023';end if;
     if item ? 'existing_id' and not exists(select 1 from jsonb_array_elements(page->'events') e
       where e->>'id'=item->>'existing_id' and e->>'revision'=item->>'expected_revision') then
       raise exception 'canonical event identity outside current page';end if;
   end loop;
   for ref in select value from jsonb_path_query(p_result->'events','$.** ? (exists(@.source_id) && exists(@.version))') value loop
     if not exists(select 1 from (
         select page->'source' original
         union all select value from jsonb_path_query(page->'timeline_context','$.conversation_history[*].source') value
         union all select value from jsonb_path_query(page->'timeline_context','$.last_event.original_passages[*]') value
       ) admitted where original->>'id'=ref->>'source_id' and original->>'version'=ref->>'version'
         and (ref->>'char_start')::integer>=(original->>'char_start')::integer
         and (ref->>'char_end')::integer<=(original->>'char_end')::integer)
       or jsonb_typeof(ref->'char_start') is distinct from 'number' or jsonb_typeof(ref->'char_end') is distinct from 'number'
       or (ref->>'char_end')::integer<=(ref->>'char_start')::integer then
       raise exception 'evidence outside claimed original window';end if;
   end loop;
   previous_setting:=current_setting('memoir.lifetime_lane',true);previous_owner:=current_setting('request.jwt.claim.sub',true);
   perform set_config('memoir.lifetime_lane',lane.id::text,true);perform set_config('request.jwt.claim.sub',lane.user_id::text,true);
   perform public.apply_user_memory_events(lane.project_id,jsonb_build_array(jsonb_build_object('id',source_id,'version',current_source_version)),p_result->'events');
   perform set_config('memoir.lifetime_lane',coalesce(previous_setting,''),true);perform set_config('request.jwt.claim.sub',coalesce(previous_owner,''),true);
   if (page->>'core_end')::integer<(page->'source'->>'original_length')::integer then
     update public.user_narrator_source set processing_status='pending' where user_id=lane.user_id and project_id=lane.project_id and id=source_id;
     update public.user_memoir_project set extraction_cursor=coalesce((select min(sequence)-1 from public.user_narrator_source
       where user_id=lane.user_id and project_id=lane.project_id and status='active' and processing_status<>'succeeded'),source_sequence)
       where user_id=lane.user_id and project_id=lane.project_id;
   end if;
   insert into public.user_lifetime_source_extraction(user_id,project_id,source_id,source_version,next_offset)
     values(lane.user_id,lane.project_id,source_id,current_source_version,(page->>'core_end')::integer)
     on conflict on constraint user_lifetime_source_extraction_pkey do update set next_offset=excluded.next_offset;
   update public.user_lifetime_lane_snapshot set last_source=(page->'source'->>'sequence')::bigint,next_offset=(page->>'core_end')::integer,
     event_high_water=(select event_sequence from public.user_memoir_project where user_id=lane.user_id and project_id=lane.project_id) where id=snap.id;
   disposition:='extracted';
 else
   event_id:=page->'partition'->>'id';
   if (p_result->>'reuse')::boolean is true then
     if (page->>'reuse')::boolean is distinct from true then raise exception 'unavailable reusable section';end if;
     disposition:='reused';
   elsif source_id is null or page->'partition'->>'status'<>'active' then
     if p_result->>'status' is distinct from 'no_authorized_evidence' then raise exception 'unsupported canonical partition';end if;
     disposition:='no_authorized_evidence';
   else
     if p_result->>'status' is distinct from 'ready' or (p_result->'validation'->>'ok')::boolean is distinct from true
       or not public.memoir_review_covers(page,p_result)
       or jsonb_typeof(p_result->'sections') is distinct from 'array' or jsonb_array_length(p_result->'sections') not between 1 and 256
       or jsonb_typeof(p_result->'preview') is distinct from 'object' or p_result->'preview'->>'locale' is distinct from snap.locale
       then
       raise exception 'canonical partition review failed';end if;
     for section in select value from jsonb_array_elements(p_result->'sections') loop
       if section->'event_ids' is distinct from jsonb_build_array(event_id) or jsonb_array_length(section->'source_refs')=0 then
         raise exception 'canonical section event identity mismatch';end if;
       for ref in select value from jsonb_array_elements(section->'source_refs') loop
         if ref->>'source_id' is distinct from source_id::text or ref->>'version' is distinct from current_source_version::text
           or (ref->>'char_start')::integer is distinct from (page->'source'->>'char_start')::integer
           or (ref->>'char_end')::integer is distinct from (page->'source'->>'char_end')::integer then
           raise exception 'canonical section span mismatch';end if;
       end loop;
     end loop;
     select coalesce(human_locked,false) into manuscript_locked from public.user_memoir_edition
       where user_id=lane.user_id and project_id=lane.project_id and locale=snap.locale;
     manuscript_locked:=coalesce(manuscript_locked,false);
     select s.* into protected from public.user_lifetime_memoir_section s join public.user_lifetime_lane_snapshot prior_root on prior_root.id=s.snapshot_id
       where s.user_id=lane.user_id and s.project_id=lane.project_id and s.locale=snap.locale and s.partition_key=page->>'partition_key'
         and s.source_version=current_source_version
         and (s.approved or s.human_locked or manuscript_locked) and prior_root.state in ('completed','proposed')
       order by prior_root.created_at desc limit 1;
     protected_safe:=protected.snapshot_id is not null and exists(select 1 from public.user_lifetime_lane_snapshot prior_root
       where prior_root.id=protected.snapshot_id and prior_root.policy_epoch=snap.policy_epoch and prior_root.privacy_digest=snap.privacy_digest);
     insert into public.user_lifetime_memoir_section(user_id,project_id,locale,partition_key,event_id,event_revision,source_id,source_version,
       char_start,char_end,evidence_hash,snapshot_id,bundle,approved,human_locked,proposal)
     values(lane.user_id,lane.project_id,snap.locale,page->>'partition_key',event_id,(page->'partition'->>'revision')::bigint,
       source_id,current_source_version,(page->'source'->>'char_start')::integer,(page->'source'->>'char_end')::integer,
       page->>'ref_key',snap.id,case when protected.snapshot_id is null and not manuscript_locked then p_result-'request' when protected_safe then protected.bundle else '{}'::jsonb end,
       coalesce(protected.approved,false),coalesce(protected.human_locked,false) or manuscript_locked,
       case when protected.snapshot_id is not null or manuscript_locked then p_result-'request' else null end)
     on conflict(user_id,project_id,locale,partition_key,snapshot_id) do update set
       proposal=case when user_lifetime_memoir_section.approved or user_lifetime_memoir_section.human_locked then excluded.bundle else null end,
       bundle=case when user_lifetime_memoir_section.approved or user_lifetime_memoir_section.human_locked then user_lifetime_memoir_section.bundle else excluded.bundle end,
       snapshot_id=excluded.snapshot_id;
     disposition:='composed';
   end if;
   update public.user_lifetime_lane_snapshot set last_event=(page->'partition'->>'change_sequence')::bigint,
     last_event_id=event_id,last_ref=page->>'ref_key' where id=snap.id;
 end if;
 new_root:=encode(sha256(convert_to(jsonb_build_object('predecessor_digest',snap.root_digest,'page_digest',page->>'page_digest',
   'result_digest',result_hash,'source_high_water',snap.source_high_water,'event_high_water',
   (select event_high_water from public.user_lifetime_lane_snapshot where id=snap.id))::text,'UTF8')),'hex');
 insert into public.user_lifetime_lane_page_receipt(snapshot_id,page_number,page_digest,result_digest,root_digest,disposition)
   values(snap.id,snap.page_number,page->>'page_digest',result_hash,new_root,disposition);
 update public.user_lifetime_lane_snapshot set page_number=page_number+1,root_digest=new_root where id=snap.id;
 if lane.lease_until<=clock_timestamp() or lane.run_deadline<=clock_timestamp() then raise exception 'canonical page lease expired' using errcode='PT409';end if;
 return jsonb_build_object('status','page_saved','root_digest',new_root,'page_number',snap.page_number+1);
end $memoir$;

CREATE FUNCTION public.commit_lifetime_memoir_lane_page_before_semantic(p_lane_id uuid, p_token uuid, p_page_number bigint, p_result jsonb, p_page_digest text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
begin
 return public.commit_lifetime_memoir_lane_page_before_strategy(p_lane_id,p_token,p_page_number,p_result,p_page_digest);
end $$;

CREATE FUNCTION public.commit_lifetime_memoir_lane_page_before_skills(p_lane_id uuid, p_token uuid, p_page_number bigint, p_result jsonb, p_page_digest text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $memoir$
declare snap public.user_lifetime_lane_snapshot%rowtype; page jsonb; result jsonb; hash text; item jsonb; ref jsonb;
 proposal jsonb; selected_event text; matches integer; current_source public.user_narrator_source%rowtype; base boolean;
 changed text[]:='{}'; inserted integer; next_change bigint; event_row public.user_memory_event%rowtype;
begin
 snap:=public.lock_lifetime_memoir_lane(p_lane_id,p_token);
 hash:=encode(sha256(convert_to(p_result::text,'UTF8')),'hex');
 if exists(select 1 from public.user_memory_attribution_receipt where snapshot_id=snap.id and page_number=p_page_number) then
   if exists(select 1 from public.user_memory_attribution_receipt where snapshot_id=snap.id and page_number=p_page_number
     and page_digest=p_page_digest and result_digest=hash) then return jsonb_build_object('status','page_saved','replayed',true);end if;
   raise exception 'attribution replay conflict' using errcode='40001';
 end if;
 page:=public.read_lifetime_memoir_lane_page(p_lane_id,p_token);
 base:=p_page_number=snap.page_number and page ? 'attribution_context';
 if not base then
   return public.commit_lifetime_memoir_lane_page_before_attribution(p_lane_id,p_token,p_page_number,p_result,p_page_digest);
 end if;
 if octet_length(p_result::text)>131072 then raise exception 'bounded attribution result required' using errcode='22023';end if;
 if jsonb_typeof(coalesce(p_result->'event_places','[]'))<>'array' or jsonb_array_length(coalesce(p_result->'event_places','[]'))>32
   or jsonb_typeof(coalesce(p_result->'passage_dispositions','[]'))<>'array'
   or jsonb_array_length(coalesce(p_result->'passage_dispositions','[]'))>64 then
   raise exception 'bounded attribution proposals required' using errcode='22023';end if;
 if page->'attribution_context'->>'decision'<>'extract' and
   (jsonb_array_length(coalesce(p_result->'event_places','[]'))>0 or jsonb_array_length(coalesce(p_result->'passage_dispositions','[]'))>0) then
   raise exception 'rule handling cannot add model attribution' using errcode='22023';end if;
 select * into current_source from public.user_narrator_source where user_id=snap.user_id and project_id=snap.project_id
   and id=(page->'source'->>'id')::uuid and version=(page->'source'->>'version')::bigint and status='active';
 for item in select value from jsonb_array_elements(coalesce(p_result->'event_places','[]')||coalesce(p_result->'passage_dispositions','[]')) loop
   ref:=item->'source_ref';
   proposal:=case when item ? 'event_index' then p_result->'events'->((item->>'event_index')::integer) end;
   if not exists(select 1 from (
       select page->'source' original
       union all select value from jsonb_path_query(page->'timeline_context','$.conversation_history[*].source') value where item ? 'event_index'
       union all select value from jsonb_path_query(page->'timeline_context','$.last_event.original_passages[*]') value where item ? 'event_index'
     ) admitted where original->>'id'=ref->>'source_id' and original->>'version'=ref->>'version'
       and (ref->>'char_start')::integer>=(original->>'char_start')::integer
       and (ref->>'char_end')::integer<=(original->>'char_end')::integer)
     or (ref->>'source_id'<>current_source.id::text and not(coalesce((proposal->>'locationConfidenceScore')::numeric,0)>=0.85
       and proposal->'location'=item->'place' and proposal->'location_basis' @> jsonb_build_array(ref)))
     or jsonb_typeof(ref->'char_start') is distinct from 'number' or jsonb_typeof(ref->'char_end') is distinct from 'number'
     or (ref->>'char_end')::integer<=(ref->>'char_start')::integer
     or not exists(select 1 from public.user_narrator_source s where s.user_id=snap.user_id and s.project_id=snap.project_id
       and s.id::text=ref->>'source_id' and s.version::text=ref->>'version' and s.status='active'
       and substring(s.text from (ref->>'char_start')::integer+1 for
         (ref->>'char_end')::integer-(ref->>'char_start')::integer)=ref->>'quote') then
     raise exception 'exact current attribution evidence required' using errcode='22023';end if;
 end loop;
 result:=public.commit_lifetime_memoir_lane_page_before_attribution(p_lane_id,p_token,p_page_number,
   p_result-array['event_places','passage_dispositions'],p_page_digest);
 if result->>'status'='page_saved' then
   insert into public.user_memory_attribution_window(user_id,project_id,source_id,source_version,char_start,char_end,policy_epoch,disposition,reason)
   values(snap.user_id,snap.project_id,(page->'source'->>'id')::uuid,(page->'source'->>'version')::bigint,
     (page->>'core_start')::integer,(page->>'core_end')::integer,snap.policy_epoch,
     case when page->'attribution_context'->>'decision' in ('non_story','withheld') then page->'attribution_context'->>'decision' else 'unresolved' end,
     case when page->'attribution_context'->>'decision'='extract' then 'no_supported_event' else page->'attribution_context'->>'reason' end)
   on conflict(user_id,project_id,source_id,source_version,char_start,char_end) do update set
     policy_epoch=excluded.policy_epoch,disposition=excluded.disposition,reason=excluded.reason;
   update public.user_memory_attribution_window set method=case when page->'attribution_context'->>'decision'='extract' then 'model' else 'rule' end
     where user_id=snap.user_id and project_id=snap.project_id and source_id=current_source.id and source_version=current_source.version
       and char_start=(page->>'core_start')::integer and char_end=(page->>'core_end')::integer;
   for item in select value from jsonb_array_elements(coalesce(p_result->'passage_dispositions','[]')) loop
     ref:=item->'source_ref';
     if exists(select 1 from jsonb_object_keys(item) k where k not in ('disposition','reason','source_ref'))
       or coalesce(item->>'disposition','') not in ('non_story','unresolved','withheld')
       or coalesce(item->>'reason','') not in ('conversation_control','profile_introduction','ambiguous_context','no_supported_event',
         'uncertain_identity','uncertain_attribution','privacy_withheld') then raise exception 'invalid passage disposition' using errcode='22023';end if;
     if item->>'disposition' in ('non_story','withheld') and exists(select 1 from public.user_memory_event_source r
       where r.user_id=snap.user_id and r.project_id=snap.project_id and r.source_id=current_source.id
         and r.source_version=current_source.version and r.stage_progress_role='primary'
         and (r.evidence->>'char_start')::integer<(ref->>'char_end')::integer
         and (r.evidence->>'char_end')::integer>(ref->>'char_start')::integer) then
       raise exception 'non-story disposition conflicts with direct testimony' using errcode='22023';end if;
     insert into public.user_memory_attribution_window(user_id,project_id,source_id,source_version,char_start,char_end,policy_epoch,disposition,reason)
     values(snap.user_id,snap.project_id,current_source.id,current_source.version,(ref->>'char_start')::integer,
       (ref->>'char_end')::integer,snap.policy_epoch,item->>'disposition',item->>'reason')
     on conflict(user_id,project_id,source_id,source_version,char_start,char_end) do update set
       policy_epoch=excluded.policy_epoch,disposition=excluded.disposition,reason=excluded.reason,method='model';
   end loop;
   for item in select value from jsonb_array_elements(coalesce(p_result->'event_places','[]')) loop
     if jsonb_typeof(item->'event_index') is distinct from 'number' or item->>'event_index' !~ '^[0-9]{1,2}$' then
       raise exception 'bounded event proposal index required' using errcode='22023';end if;
     ref:=item->'source_ref';proposal:=p_result->'events'->((item->>'event_index')::integer);
     if coalesce((proposal->>'locationConfidenceScore')::numeric,1)<0.85 then
       raise exception 'event location requires confirmation' using errcode='22023';end if;
     if exists(select 1 from jsonb_object_keys(item) k where k not in ('event_index','role','place','source_ref'))
       or proposal is null or coalesce(item->>'role','') not in ('setting','origin','destination')
       or exists(select 1 from jsonb_object_keys(item->'place') k where k not in ('place','hierarchy','granularity')) then
       raise exception 'invalid selective event place' using errcode='22023';end if;
     perform public.validate_two_lane_places(ref->>'quote',jsonb_build_array(item->'place'||'{"schema_version":1}'),coalesce((ref->>'char_start')::integer,0));
     if exists(select 1 from jsonb_array_elements_text(item->'place'->'hierarchy') label where
       label ~* '(医院|学校|大学|学院|车站|家属院|小区|大厦|大楼|街|路|巷)([0-9]+号)?$|\m(hospital|school|university|college|station|street|road|lane|avenue|building|compound)\M(\s+[0-9]+)?$') then
       raise exception 'public coarse geography required' using errcode='22023';end if;
     select min(e.id),count(*) into selected_event,matches from public.user_memory_event e
     where e.user_id=snap.user_id and e.project_id=snap.project_id and e.status='active'
       and ((proposal ? 'existing_id' and e.id=proposal->>'existing_id') or (not(proposal ? 'existing_id')
         and e.change_sequence>snap.event_high_water and e.kind=proposal->>'kind' and e.data->>'title'=proposal->>'title'))
       and exists(select 1 from public.user_memory_event_source r where r.user_id=e.user_id and r.project_id=e.project_id
         and r.event_id=e.id and r.source_id=current_source.id and r.source_version=current_source.version and r.stage_progress_role='primary'
         and proposal->'source_refs' @> jsonb_build_array(r.evidence))
       and exists(select 1 from public.user_memory_event_source r where r.user_id=e.user_id and r.project_id=e.project_id
         and r.event_id=e.id and r.source_id::text=ref->>'source_id' and r.source_version::text=ref->>'version'
         and (r.evidence->>'char_start')::integer<=(ref->>'char_start')::integer
         and (r.evidence->>'char_end')::integer>=(ref->>'char_end')::integer);
     if matches<>1 then raise exception 'place requires one exact event passage' using errcode='22023';end if;
     insert into public.user_memory_event_place(user_id,project_id,event_id,source_id,source_version,char_start,char_end,role,place)
     values(snap.user_id,snap.project_id,selected_event,(ref->>'source_id')::uuid,(ref->>'version')::bigint,
       (ref->>'char_start')::integer,(ref->>'char_end')::integer,item->>'role',item->'place')
     on conflict(user_id,project_id,event_id,source_id,source_version,char_start,char_end,role,place_key) do nothing;
     get diagnostics inserted=ROW_COUNT;
     if inserted>0 then changed:=array_append(changed,selected_event);end if;
   end loop;
   for selected_event in select distinct v from unnest(changed) v loop
     update public.user_memoir_project set event_sequence=event_sequence+1 where user_id=snap.user_id and project_id=snap.project_id
       returning event_sequence into next_change;
     update public.user_memory_event set revision=revision+1,change_sequence=next_change,
       data=data||jsonb_build_object('place_revision',coalesce((data->>'place_revision')::bigint,0)+1)
     where user_id=snap.user_id and project_id=snap.project_id and id=selected_event returning * into event_row;
     insert into public.user_memory_event_revision(user_id,project_id,event_id,revision,record,actor,origin)
       values(snap.user_id,snap.project_id,selected_event,event_row.revision,public.memory_event_record(event_row),'model','author_timeline');
   end loop;
   if cardinality(changed)>0 then update public.user_lifetime_lane_snapshot set event_high_water=(select event_sequence
     from public.user_memoir_project where user_id=snap.user_id and project_id=snap.project_id) where id=snap.id;end if;
   update public.user_memoir_project set attribution_revision=attribution_revision+1 where user_id=snap.user_id and project_id=snap.project_id;
   insert into public.user_memory_attribution_receipt values(snap.id,p_page_number,p_page_digest,hash);
   result:=result||jsonb_build_object('attribution',public.lifetime_source_attribution_summary(snap.user_id,snap.project_id,current_source.id)
     ||jsonb_build_object('timeline_method',case when page->'attribution_context'->>'decision'='extract' then 'model' else 'rule' end));
 end if;
 return result;
end $memoir$;

CREATE FUNCTION public.commit_lifetime_memoir_lane_page_before_strategy(p_lane_id uuid, p_token uuid, p_page_number bigint, p_result jsonb, p_page_digest text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare snap public.user_lifetime_lane_snapshot%rowtype; page jsonb; result jsonb;
begin
 -- Preserve the canonical disabled path without duplicate page preparation.
 -- Its own lock/digest/receipt checks still fence every commit and replay.
 if not exists(select 1 from public.lifetime_two_lane_rollout where singleton and enabled) then
   return public.commit_lifetime_memoir_lane_page_before_two_lanes(p_lane_id,p_token,p_page_number,p_result,p_page_digest);
 end if;
 snap:=public.lock_lifetime_memoir_lane(p_lane_id,p_token);
 -- The canonical receipt verifies identical retries before any repeated effect.
 if p_page_number<snap.page_number then
   return public.commit_lifetime_memoir_lane_page_before_two_lanes(p_lane_id,p_token,p_page_number,p_result,p_page_digest);
 end if;
 page:=public.read_lifetime_memoir_lane_page(p_lane_id,p_token);
 if page ? 'two_lane' then
   if p_page_digest is distinct from page->>'page_digest' then raise exception 'stale derived page' using errcode='PT409';end if;
   if exists(select 1 from jsonb_object_keys(p_result) k where k not in ('events','place_journeys')) then
     raise exception 'timeline output cannot contain interview guidance' using errcode='22023';end if;
   perform public.validate_two_lane_places(page->'source'->>'text',p_result->'place_journeys',coalesce((page->'source'->>'char_start')::integer,0));
   if page->'two_lane'->>'work_mode'='reply_only' and (jsonb_array_length(p_result->'events')>0
     or jsonb_array_length(p_result->'place_journeys')>0) then
     raise exception 'reply only work cannot create derived facts' using errcode='22023';end if;
 end if;
 result:=public.commit_lifetime_memoir_lane_page_before_two_lanes(p_lane_id,p_token,p_page_number,p_result,p_page_digest);
 if page ? 'two_lane' and result->>'status'='page_saved' and exists(select 1 from public.user_memoir_project
   where user_id=snap.user_id and project_id=snap.project_id and policy_epoch<>snap.policy_epoch) then
   return result||jsonb_build_object('policy_changed',true);end if;
 if page ? 'two_lane' and result->>'status'='page_saved' then
   -- Empty or failed B never erases a previously valid activated workspace.
   if jsonb_array_length(p_result->'place_journeys')>0 then
     insert into public.user_lifetime_place_journey(user_id,project_id,source_id,source_version,journeys,derived_fence) values(snap.user_id,snap.project_id,(page->'source'->>'id')::uuid,
       (page->'source'->>'version')::bigint,p_result->'place_journeys',jsonb_build_object('policy_epoch',snap.policy_epoch,
         'preference_revision',snap.preference_revision,'execution_generation',(page->'two_lane'->>'execution_generation')::bigint,'privacy_digest',snap.privacy_digest))
     on conflict(user_id,project_id,source_id) do update set source_version=excluded.source_version,derived_fence=excluded.derived_fence,
       journeys=(select coalesce(jsonb_agg(distinct j),'[]') from jsonb_array_elements(
         case when user_lifetime_place_journey.source_version=excluded.source_version then user_lifetime_place_journey.journeys else '[]' end||excluded.journeys) j);
   end if;

 end if;
 return result;
end $$;

CREATE FUNCTION public.commit_lifetime_memoir_lane_page_before_summary_windows(p_lane_id uuid, p_token uuid, p_page_number bigint, p_result jsonb, p_page_digest text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare snap public.user_lifetime_lane_snapshot%rowtype; page jsonb;batch jsonb;item jsonb;ref jsonb;e jsonb;s jsonb;deps jsonb;
 result_hash text;new_root text;key text;source_deps jsonb;event_deps jsonb; prior public.user_lifetime_lane_page_receipt%rowtype;
 title text; preview jsonb; protected public.user_lifetime_memoir_section%rowtype;locked boolean;protected_safe boolean;
begin
 snap:=public.lock_lifetime_memoir_lane(p_lane_id,p_token);
 page:=public.read_lifetime_memoir_lane_page(p_lane_id,p_token);batch:=page->'batch';
 if batch is null then return public.commit_lifetime_memoir_lane_page_before_batches(p_lane_id,p_token,p_page_number,p_result,p_page_digest);end if;
 if jsonb_typeof(p_result)<>'object' or octet_length(p_result::text)>131072 then raise exception 'bounded progressive result required';end if;
 result_hash:=encode(sha256(convert_to(p_result::text,'UTF8')),'hex');
 if p_page_number<snap.page_number then
  select * into prior from public.user_lifetime_lane_page_receipt where snapshot_id=snap.id and page_number=p_page_number;
  if found and prior.page_digest=p_page_digest and prior.result_digest=result_hash then return jsonb_build_object('status','page_saved','replayed',true);end if;
  raise exception 'progressive replay conflict' using errcode='PT409';
 end if;
 if p_page_number<>snap.page_number or p_page_digest is distinct from page->>'page_digest' then raise exception 'stale progressive batch' using errcode='PT409';end if;
 if jsonb_array_length(batch->'new_messages')>0 and not exists(select 1 from public.user_lifetime_lane_output where snapshot_id=snap.id
  and page_number=snap.page_number and phase='prepare' and input_digest=page->>'input_digest') then raise exception 'new messages require a saved background summary';end if;
 if p_result->>'status' not in ('ready','insufficient_context') then raise exception 'progressive composition failed';end if;
 if p_result->>'status'='ready' then
  if not exists(select 1 from public.user_lifetime_lane_output where snapshot_id=snap.id and page_number=snap.page_number and phase='draft' and input_digest=page->>'input_digest')
    or not exists(select 1 from public.user_lifetime_lane_output where snapshot_id=snap.id and page_number=snap.page_number and phase='review' and input_digest=page->>'input_digest') then
   raise exception 'progressive model draft and review evidence required';end if;
  if (p_result->'validation'->>'ok')::boolean is distinct from true or not public.memoir_review_covers(page,p_result)
   or jsonb_typeof(p_result->'sections') is distinct from 'array' or jsonb_array_length(p_result->'sections') not between 1 and 256 then raise exception 'progressive review required';end if;
  for item in select value from jsonb_array_elements(p_result->'sections') loop
   if not item ? 'block' then continue;end if;
   if jsonb_array_length(item->'source_refs')=0 or jsonb_array_length(item->'event_ids')=0 then raise exception 'progressive original evidence required';end if;
   for ref in select value from jsonb_array_elements(item->'source_refs') loop
    if not exists(select 1 from jsonb_array_elements(batch->'events') ev,jsonb_array_elements(ev->'source_refs') evidence
      where item->'event_ids' ? (ev->>'id') and evidence->>'source_id'=ref->>'source_id' and evidence->>'version'=ref->>'version'
       and (evidence->>'char_start')::integer<=(ref->>'char_start')::integer and (evidence->>'char_end')::integer>=(ref->>'char_end')::integer) then
     raise exception 'progressive evidence outside current canonical events';end if;
   end loop;
   select value into e from jsonb_array_elements(batch->'events') where value->>'id'=item->'event_ids'->>0;
   ref:=item->'source_refs'->0;
   select coalesce(jsonb_agg(distinct jsonb_build_object('id',r->'source_id','version',(r->>'version')::bigint)),'[]') into source_deps from (
    select value r from jsonb_array_elements(item->'source_refs') union all
    select r from jsonb_array_elements(p_result->'sections') h,jsonb_array_elements(h->'source_refs') r
      where h ? 'heading' and h->>'chapter_id'=item->>'chapter_id') dependencies;
   select coalesce(jsonb_agg(jsonb_build_object('id',v->'id','revision',v->'revision')),'[]') into event_deps from jsonb_array_elements(batch->'events') v where item->'event_ids' ? (v->>'id')
    or exists(select 1 from jsonb_array_elements(p_result->'sections') h where h ? 'heading' and h->>'chapter_id'=item->>'chapter_id' and h->'event_ids' ? (v->>'id'));
   select coalesce(human_locked,false) into locked from public.user_memoir_edition where user_id=snap.user_id and project_id=snap.project_id and locale=snap.locale;
   -- Model-local IDs alone collide across independent message batches. Anchor
   -- a passage to its canonical event as well as its stable writing ID.
   key:=case when page->'editorial_request'<>'null'::jsonb and page->>'partition_key' like 'progressive:%'
     then page->>'partition_key' else 'progressive:'||(e->>'id')||':'||(item->>'id') end;
   select section.* into protected from public.user_lifetime_memoir_section section join public.user_lifetime_lane_snapshot root on root.id=section.snapshot_id
    where section.user_id=snap.user_id and section.project_id=snap.project_id and section.locale=snap.locale and section.partition_key=key
      and (section.approved or section.human_locked or coalesce(locked,false)) and root.state in ('completed','proposed')
    order by root.created_at desc limit 1;
   protected_safe:=protected.snapshot_id is not null and exists(select 1 from public.user_lifetime_lane_snapshot root
     where root.id=protected.snapshot_id and root.policy_epoch=snap.policy_epoch and root.privacy_digest=snap.privacy_digest);
   locked:=coalesce(locked,false) or protected.snapshot_id is not null;
   -- A bounded packet may omit older writing it cannot safely reconstruct.
   -- Such writing must never be replaced by a model that did not receive it.
   if not locked and not exists(select 1 from jsonb_array_elements(coalesce(batch->'previous'->'sections','[]')) previous_item
     where previous_item->>'id'=item->>'id') and exists(select 1 from public.user_lifetime_memoir_section section
     where section.user_id=snap.user_id and section.project_id=snap.project_id and section.locale=snap.locale and section.partition_key=key) then
    key:=key||':delta:'||snap.id::text;
   end if;
   title:=coalesce(item->'heading'->>'title',(select value->'heading'->>'title' from jsonb_array_elements(p_result->'sections') where value->>'chapter_id'=item->>'chapter_id' and value ? 'heading' limit 1),'Memories');
   preview:=jsonb_build_object('id',item->>'id','title',title,'text',coalesce(item->'block'->>'text',''),'locale',snap.locale);
   insert into public.user_lifetime_memoir_section(user_id,project_id,locale,partition_key,event_id,event_revision,source_id,source_version,char_start,char_end,evidence_hash,snapshot_id,
     bundle,approved,human_locked,proposal,source_dependencies,event_dependencies,composition_config)
   values(snap.user_id,snap.project_id,snap.locale,key,e->>'id',(e->>'revision')::bigint,(ref->>'source_id')::uuid,(ref->>'version')::bigint,
     (ref->>'char_start')::integer,(ref->>'char_end')::integer,encode(sha256(convert_to((item->'source_refs')::text,'UTF8')),'hex'),snap.id,
     case when locked then case when protected_safe then protected.bundle else '{}'::jsonb end else jsonb_build_object('kind',p_result->'manuscript'->>'kind','preview',preview,'source_refs',item->'source_refs',
       'photo_association_manifest',coalesce(p_result->'photo_association_manifest','{}'::jsonb),
       'sections',jsonb_build_array(item)||(select coalesce(jsonb_agg(value),'[]') from jsonb_array_elements(p_result->'sections') where value ? 'heading' and value->>'chapter_id'=item->>'chapter_id')) end,
     coalesce(protected.approved,false),locked,case when locked then jsonb_build_object('kind',p_result->'manuscript'->>'kind','preview',preview,'source_refs',item->'source_refs','sections',jsonb_build_array(item)) else null end,
     source_deps,event_deps,p_result->>'content_config')
   on conflict(user_id,project_id,locale,partition_key,snapshot_id) do nothing;
  end loop;
 end if;
 new_root:=encode(sha256(convert_to(jsonb_build_object('predecessor_digest',snap.root_digest,'page_digest',p_page_digest,'result_digest',result_hash)::text,'UTF8')),'hex');
 insert into public.user_lifetime_lane_page_receipt values(snap.id,snap.page_number,p_page_digest,result_hash,new_root,'composed');
 update public.user_lifetime_lane_snapshot set page_number=page_number+1,root_digest=new_root,
  last_source=(batch->>'through_source')::bigint,next_offset=(batch->>'next_offset')::integer,
  last_event=(batch->'cursor'->>0)::bigint,last_event_id=batch->'cursor'->>1,last_ref=batch->'cursor'->>2 where id=snap.id;
 return jsonb_build_object('status','page_saved','root_digest',new_root,'page_number',snap.page_number+1);
end $$;

CREATE FUNCTION public.commit_lifetime_memoir_lane_page_before_two_lanes(p_lane_id uuid, p_token uuid, p_page_number bigint, p_result jsonb, p_page_digest text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare page jsonb; result jsonb; block jsonb; original jsonb; ref jsonb;
begin
 page:=public.read_lifetime_memoir_lane_page(p_lane_id,p_token);
 if p_page_number=(page->>'page_number')::bigint and page->'editorial_request'<>'null'::jsonb
   and page->>'partition_key' like 'progressive:%' then
   if (select count(*) from jsonb_array_elements(p_result->'sections') item where item ? 'block')<>1 then
     raise exception 'editorial result must contain only the selected writing';end if;
   select value into block from jsonb_array_elements(p_result->'sections') where value ? 'block';
   select value into original from jsonb_array_elements(page->'batch'->'previous'->'sections') where value ? 'block';
   if block->'event_ids'->>0 is distinct from page->'partition'->>'id' or exists(
      select 1 from jsonb_array_elements_text(block->'event_ids') id where not(original->'event_ids' ? id)) then
     raise exception 'editorial result changes the selected event scope';end if;
   for ref in select value from jsonb_array_elements(block->'source_refs') loop
     if not exists(select 1 from jsonb_array_elements(original->'source_refs') prior
        where prior->>'source_id'=ref->>'source_id' and prior->>'version'=ref->>'version'
          and (prior->>'char_start')::integer<=(ref->>'char_start')::integer
          and (prior->>'char_end')::integer>=(ref->>'char_end')::integer) then
       raise exception 'editorial result widens the selected original evidence';end if;
   end loop;
 end if;
 result:=public.commit_lifetime_memoir_lane_page_before_progressive_rework(p_lane_id,p_token,p_page_number,p_result,p_page_digest);
 if p_page_number=(page->>'page_number')::bigint and page->'editorial_request'<>'null'::jsonb then
   update public.user_workspace_section_rework set composed_snapshot_id=(page->>'snapshot_id')::uuid
     where user_id=(page->>'user_id')::uuid and project_id=page->>'project_id'
       and request_id=(page->'editorial_request'->>'request_id')::uuid;
 end if;
 return result;
end $$;

CREATE FUNCTION public.commit_lifetime_memory_summary_page(p_lane_id uuid, p_token uuid, p_revision bigint, p_result jsonb, p_page_digest text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb;
begin
 result:=public.commit_lifetime_memory_summary_page_before_skills(p_lane_id,p_token,p_revision,p_result,p_page_digest);
 if result->>'status'='page_saved' and result->>'replayed' is distinct from 'true' then
   update public.user_background_skill_work set status='saved',updated_at=clock_timestamp()
   where lane_id=p_lane_id and page_digest=p_page_digest and phase='summarize' and status in ('completed','failed') and model_invoked;
 end if;
 return result;
end $$;

CREATE FUNCTION public.commit_lifetime_memory_summary_page_before_skills(p_lane_id uuid, p_token uuid, p_revision bigint, p_result jsonb, p_page_digest text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $memoir$
declare snap public.user_lifetime_lane_snapshot%rowtype; proof public.user_lifetime_compaction%rowtype; page jsonb;
 item jsonb; ref jsonb; original public.user_narrator_source%rowtype; fingerprint text;
begin
 snap:=public.lock_lifetime_memoir_lane(p_lane_id,p_token);
 fingerprint:=encode(sha256(convert_to(p_result::text,'UTF8')),'hex');
 select p.* into proof from public.user_lifetime_compaction p join public.user_lifetime_summary_receipt r on r.maintenance_id=p.id
   where p.user_id=snap.user_id and p.conversation_id=snap.conversation_id and r.revision=p_revision and r.page_digest=p_page_digest;
 if found then
   if not exists(select 1 from public.user_lifetime_summary_receipt r where r.maintenance_id=proof.id and r.revision=p_revision and r.result_digest=fingerprint) then
     raise exception 'summary replay conflict' using errcode='PT409';end if;
   return jsonb_build_object('status','page_saved','replayed',true);
 end if;
 page:=public.read_lifetime_memoir_lane_page(p_lane_id,p_token);
 if page->'memory_summary' is null or p_page_digest is distinct from page->>'page_digest'
   or p_revision is distinct from (page->'memory_summary'->>'revision')::bigint then raise exception 'stale summary page' using errcode='PT409';end if;
 select * into proof from public.user_lifetime_compaction where id=(page->'memory_summary'->>'maintenance_id')::uuid for update;
 if jsonb_typeof(p_result) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_result) k where k<>'items')
   or jsonb_typeof(p_result->'items') is distinct from 'array' or jsonb_array_length(p_result->'items')>16
   or octet_length(p_result::text)>8192 then raise exception 'bounded semantic summary required' using errcode='22023';end if;
 if page->'memory_summary'->>'work_mode'='reply_only' and p_result is distinct from proof.summary_data then
   raise exception 'fact-free summary step must preserve prior context' using errcode='22023';end if;
 for item in select value from jsonb_array_elements(p_result->'items') loop
   if jsonb_typeof(item) is distinct from 'object' or exists(select 1 from jsonb_object_keys(item) k where k not in ('text','uncertainty','source_refs'))
     or jsonb_typeof(item->'text') is distinct from 'string' or length(item->>'text') not between 1 and 500
     or jsonb_typeof(item->'uncertainty') is distinct from 'string' or length(item->>'uncertainty') not between 1 and 500
     or jsonb_typeof(item->'source_refs') is distinct from 'array' or jsonb_array_length(item->'source_refs') not between 1 and 4 then
     raise exception 'typed derived summary item required' using errcode='22023';end if;
   for ref in select value from jsonb_array_elements(item->'source_refs') loop
     if jsonb_typeof(ref) is distinct from 'object' or exists(select 1 from jsonb_object_keys(ref) k where k not in ('source_id','version','quote','char_start','char_end'))
       or not(ref ?& array['source_id','version','quote','char_start','char_end']) or jsonb_typeof(ref->'quote') is distinct from 'string'
       or length(ref->>'quote') not between 1 and 500 or coalesce(ref->>'version','')!~'^[1-9][0-9]*$'
       or coalesce(ref->>'char_start','')!~'^[0-9]+$' or coalesce(ref->>'char_end','')!~'^[1-9][0-9]*$' then
       raise exception 'exact summary evidence required' using errcode='22023';end if;
     select * into original from public.user_narrator_source where user_id=snap.user_id and project_id=snap.project_id
       and id=(ref->>'source_id')::uuid and version=(ref->>'version')::bigint and status='active';
     if not found or (ref->>'char_end')::integer-(ref->>'char_start')::integer<>length(ref->>'quote')
       or substring(original.text from (ref->>'char_start')::integer+1 for length(ref->>'quote')) is distinct from ref->>'quote'
       or not ((page->'source'->>'id'=ref->>'source_id' and page->'source'->>'version'=ref->>'version'
         and (ref->>'char_start')::integer>=(page->'source'->>'char_start')::integer
         and (ref->>'char_end')::integer<=(page->'source'->>'char_end')::integer)
         or exists(select 1 from jsonb_array_elements(proof.summary_data->'items') old
           cross join lateral jsonb_array_elements(old->'source_refs') r
           where r->>'source_id'=ref->>'source_id' and r->>'version'=ref->>'version'
             and (ref->>'char_start')::integer>=(r->>'char_start')::integer
             and (ref->>'char_end')::integer<=(r->>'char_end')::integer
             and substring(r->>'quote' from (ref->>'char_start')::integer-(r->>'char_start')::integer+1
               for length(ref->>'quote'))=ref->>'quote')) then
       raise exception 'summary evidence outside accepted inputs' using errcode='22023';end if;
   end loop;
 end loop;
 update public.user_lifetime_compaction set summary_data=p_result,summary_sequence=(page->'memory_summary'->>'sequence')::bigint,
   summary_offset=(page->'memory_summary'->>'char_start')::integer,summary_revision=summary_revision+1,summary_windows=summary_windows+1
   where id=proof.id and summary_revision=p_revision;
 if not found then raise exception 'summary CAS failed' using errcode='PT409';end if;
 insert into public.user_lifetime_summary_receipt values(proof.id,p_revision,p_page_digest,fingerprint);
 return jsonb_build_object('status','page_saved');
end $memoir$;

CREATE FUNCTION public.commit_lifetime_profile_page(p_lane_id uuid, p_token uuid, p_page_digest text, p_result jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb; page jsonb; reason text;
begin
 page:=public.read_lifetime_profile_page(p_lane_id,p_token);
 result:=public.commit_lifetime_profile_page_before_skills(p_lane_id,p_token,p_page_digest,p_result);
 if result->>'status'='page_saved' and result->>'replayed' is distinct from 'true' then
   update public.user_background_skill_work set status='saved',updated_at=clock_timestamp()
   where lane_id=p_lane_id and page_digest=p_page_digest and status in ('completed','failed') and model_invoked;
   if page->'profile_context'->>'work_mode'='extract' and not exists(select 1 from public.user_background_skill_work
     where lane_id=p_lane_id and page_digest=p_page_digest and status='saved') then
     perform public.background_skill_receipt(page,'profile','memoir-memory-context','model','saved','invocation_receipt_unavailable');
   end if;
   if page->'profile_context'->>'work_mode' in ('skip','reply_only') then
     select case when not a.auto_enabled then 'automatic_stopped' when a.manual_complete then 'manually_confirmed' else 'no_targets' end into reason
       from public.user_lifetime_profile_authority a where a.user_id=(page->>'user_id')::uuid;
     perform public.background_skill_receipt(page,'profile','memoir-memory-context','model','skipped',
       case when page->'profile_context'->>'work_mode'='skip' then reason
         when page->'source'='null'::jsonb then 'no_evidence' else 'reply_only' end);
   end if;
 end if;
 return result;
end $$;

CREATE FUNCTION public.commit_lifetime_profile_page_before_skills(p_lane_id uuid, p_token uuid, p_page_digest text, p_result jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $memoir$
#variable_conflict use_column
declare snap public.user_lifetime_lane_snapshot%rowtype; page jsonb; context jsonb; item jsonb; ref jsonb;
 current_profile jsonb; field text; val jsonb; source public.user_narrator_source%rowtype;
 receipt public.user_lifetime_profile_receipt%rowtype; result_digest text; skipped boolean; previous_owner text;
 cursor_data jsonb; target bigint; frontier bigint;
begin
 perform 1 from public.lifetime_two_lane_rollout where singleton and enabled for share;
 if not found then raise exception 'profile rollout disabled' using errcode='PT409';end if;
 -- Upgrade profile before the canonical identity SHARE lock: writes must not
 -- deadlock with another admission holding identity while waiting for profile.
 select l.user_id into snap.user_id from public.user_memoir_lane l where l.id=p_lane_id and l.skill='timeline';
 if not found then raise exception 'timeline owner required' using errcode='42501';end if;
 perform 1 from public.user_memoir_project p join public.user_memoir_lane l on l.user_id=p.user_id and l.project_id=p.project_id
   where l.id=p_lane_id for update of p;
 perform 1 from public.user_profile where user_id=snap.user_id for update;
 snap:=public.lock_lifetime_memoir_lane(p_lane_id,p_token);
 perform 1 from public.user_agent_turn_lease where user_id=snap.user_id for share;
 if exists(select 1 from public.user_agent_turn_lease where user_id=snap.user_id and expires_at>clock_timestamp()) then
   raise exception 'profile commit deferred during interactive turn' using errcode='PT409';end if;
 if jsonb_typeof(p_result) is distinct from 'object' or octet_length(p_result::text)>16384
   or exists(select 1 from jsonb_object_keys(p_result) k where k not in ('profile_patch','skipped'))
   or jsonb_typeof(p_result->'profile_patch') is distinct from 'array'
   or jsonb_array_length(p_result->'profile_patch')>6
   or (p_result ? 'skipped' and jsonb_typeof(p_result->'skipped') is distinct from 'boolean') then
   raise exception 'bounded profile patch required' using errcode='22023';end if;
 result_digest:=encode(sha256(convert_to(p_result::text,'UTF8')),'hex');
 select * into receipt from public.user_lifetime_profile_receipt where user_id=snap.user_id
   and project_id=snap.project_id and page_digest=p_page_digest;
 if found then
   if receipt.result_digest<>result_digest then raise exception 'profile retry body changed' using errcode='PT409';end if;
   return jsonb_build_object('status','page_saved','replayed',true);
 end if;
 page:=public.read_lifetime_profile_page(p_lane_id,p_token);
 if page is null or page->>'page_digest' is distinct from p_page_digest then
   raise exception 'stale profile page' using errcode='PT409';end if;
 context:=page->'profile_context';cursor_data:=context->'cursor';
 target:=(context->>'target_round')::bigint;frontier:=(context->>'source_frontier')::bigint;
 skipped:=coalesce((p_result->>'skipped')::boolean,false);
 if skipped is distinct from (context->>'work_mode'='skip')
   or (context->>'work_mode'<>'extract' and jsonb_array_length(p_result->'profile_patch')<>0)
   or (select count(*)<>count(distinct p->>'field') from jsonb_array_elements(p_result->'profile_patch') p) then
   raise exception 'profile disposition differs from admitted work' using errcode='22023';end if;
 select p.profile into current_profile from public.user_profile p where p.user_id=snap.user_id;
 select s.* into source from public.user_narrator_source s where s.user_id=snap.user_id and s.project_id=snap.project_id
   and s.id=(page->'source'->>'id')::uuid and s.version=(page->'source'->>'version')::bigint and s.status='active';
 for item in select value from jsonb_array_elements(p_result->'profile_patch') loop
   if jsonb_typeof(item) is distinct from 'object' or exists(select 1 from jsonb_object_keys(item) k
     where k not in ('field','value','source_refs')) or not(item ?& array['field','value','source_refs'])
     or jsonb_typeof(item->'field') is distinct from 'string' or not(context->'targets' ? (item->>'field'))
     or jsonb_typeof(item->'source_refs') is distinct from 'array' or jsonb_array_length(item->'source_refs') not between 1 and 4 then
     raise exception 'auto eligible profile field and original evidence required' using errcode='22023';end if;
   field:=item->>'field';val:=item->'value';
   if field='birth_year' then
     if jsonb_typeof(val) is distinct from 'number' or val::text !~ '^[0-9]{4}$'
       or val::text::integer not between 1800 and extract(year from current_date) then
       raise exception 'invalid profile birth year' using errcode='22023';end if;
   elsif jsonb_typeof(val) is distinct from 'string' or length(btrim(val#>>'{}')) not between 1 and
     (case when field in ('name','birth_date_expression') then 120 else 160 end) or val#>>'{}'<>btrim(val#>>'{}')
     or (field='avatar_style' and val#>>'{}' not in ('male','female')) then
     raise exception 'invalid profile value' using errcode='22023';
   end if;
   for ref in select value from jsonb_array_elements(item->'source_refs') loop
     if jsonb_typeof(ref) is distinct from 'object' or exists(select 1 from jsonb_object_keys(ref) k where k not in
       ('source_id','version','quote','char_start','char_end')) or not(ref ?& array['source_id','version','quote','char_start','char_end'])
       or ref->>'source_id' is distinct from source.id::text or ref->'version' is distinct from to_jsonb(source.version)
       or jsonb_typeof(ref->'quote') is distinct from 'string' or length(ref->>'quote') not between 1 and 2304
       or jsonb_typeof(ref->'char_start') is distinct from 'number' or coalesce(ref->>'char_start','') !~ '^[0-9]{1,6}$'
       or jsonb_typeof(ref->'char_end') is distinct from 'number' or coalesce(ref->>'char_end','') !~ '^[0-9]{1,6}$'
       or (ref->>'char_start')::integer<(page->'source'->>'char_start')::integer
       or (ref->>'char_end')::integer>(page->'source'->>'char_end')::integer
       or (ref->>'char_end')::integer-(ref->>'char_start')::integer<>length(ref->>'quote')
       or substring(source.text from (ref->>'char_start')::integer+1
         for (ref->>'char_end')::integer-(ref->>'char_start')::integer) is distinct from ref->>'quote' then
       raise exception 'exact current profile evidence required' using errcode='22023';end if;
   end loop;
   update public.user_lifetime_profile_authority set invalidated_fields=array_remove(invalidated_fields,field) where user_id=snap.user_id;
   if field='name' then
     if not exists(select 1 from jsonb_array_elements(item->'source_refs') r where strpos(r->>'quote',val#>>'{}')>0)
       or exists(select 1 from public.user_lifetime_chosen_name n join public.user_narrator_source s
         on s.user_id=n.user_id and s.project_id=n.project_id and s.id=n.source_id
         where n.user_id=snap.user_id and s.sequence>source.sequence) then
       raise exception 'newer chosen name authority' using errcode='PT409';end if;
     previous_owner:=current_setting('request.jwt.claim.sub',true);
     perform set_config('request.jwt.claim.sub',snap.user_id::text,true);
     perform public.persist_lifetime_chosen_name(snap.conversation_id,source.id,source.version,val#>>'{}');
     perform set_config('request.jwt.claim.sub',coalesce(previous_owner,''),true);
     if not exists(select 1 from public.user_lifetime_chosen_name where user_id=snap.user_id
       and authority='generated' and source_id=source.id and source_version=source.version and chosen_name=val#>>'{}') then
       raise exception 'chosen name authority changed' using errcode='PT409';end if;
   end if;
   current_profile:=jsonb_set(current_profile,array[field],val);
   delete from public.user_lifetime_profile_dependency d where d.user_id=snap.user_id and d.field=item->>'field';
   insert into public.user_lifetime_profile_dependency(user_id,field,project_id,source_id,source_version,char_start,char_end)
   select distinct snap.user_id,field,snap.project_id,source.id,source.version,(r->>'char_start')::integer,(r->>'char_end')::integer
   from jsonb_array_elements(item->'source_refs') r;
 end loop;
 if not skipped then
   update public.user_profile p set profile=current_profile where p.user_id=snap.user_id;
   if source.id is not null then
     insert into public.user_lifetime_profile_coverage values(snap.user_id,snap.project_id,source.id,source.version,
       (page->'source'->>'char_end')::integer)
     on conflict(user_id,project_id,source_id,source_version) do update set next_offset=excluded.next_offset;
   end if;
 end if;
 insert into public.user_lifetime_profile_receipt values(snap.user_id,snap.project_id,p_page_digest,snap.id,result_digest,target,
   (cursor_data->>'source_id')::uuid,(cursor_data->>'version')::bigint,(cursor_data->>'char_start')::integer,
   (cursor_data->>'char_end')::integer,skipped);
 if skipped then
   update public.user_lifetime_profile_progress set skipped_round=greatest(skipped_round,target),active_round=0
   where user_id=snap.user_id and project_id=snap.project_id;
 elsif snap.source_decision->'skills' ? 'memoir-memory-context' or not exists(select 1 from public.user_narrator_source s left join public.user_lifetime_profile_coverage c
   on c.user_id=s.user_id and c.project_id=s.project_id and c.source_id=s.id and c.source_version=s.version
   where s.user_id=snap.user_id and s.project_id=snap.project_id and s.status='active' and s.sequence<=frontier
     and coalesce(c.next_offset,0)<length(s.text)) then
   update public.user_lifetime_profile_progress set covered_round=greatest(covered_round,target),
     covered_frontier=greatest(covered_frontier,frontier),active_round=0
   where user_id=snap.user_id and project_id=snap.project_id;
 end if;
 -- Only this writer's own preference change may advance its existing snapshot.
 update public.user_lifetime_lane_snapshot s set preference_revision=c.preference_revision,state='pending'
 from public.user_lifetime_conversation c where s.id=snap.id and c.user_id=snap.user_id and c.conversation_id=snap.conversation_id;
 return jsonb_build_object('status','page_saved','replayed',false,'skipped',skipped);
end $memoir$;

CREATE FUNCTION public.commit_lifetime_strategy_delivery(p_fence jsonb, p_client_turn_id uuid, p_reply_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
begin
 perform public.lock_lifetime_publication(p_fence);
 update public.user_lifetime_strategy_outcome o set delivered=true where o.user_id=auth.uid()
   and o.project_id=p_fence->'identity'->>'project_id' and o.client_turn_id=p_client_turn_id and o.reply_id=p_reply_id
   and exists(select 1 from public.user_lifetime_reply r where r.user_id=o.user_id and r.client_turn_id=o.client_turn_id
     and r.memory_id=o.reply_id and r.conversation_id=(p_fence->'identity'->>'conversation_id')::uuid
     and r.policy_epoch=(p_fence->>'policy_epoch')::bigint and r.execution_generation=(p_fence->>'execution_generation')::bigint);
 return found;
end $$;

CREATE FUNCTION public.commit_lifetime_strategy_turn(p_fence jsonb, p_client_turn_id uuid, p_plan jsonb, p_associations jsonb, p_reply text, p_response_photo_ids jsonb, p_thread_id text, p_prompt_version text, p_model text, p_continuity_updates jsonb, p_outcome jsonb, p_name_update text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare result jsonb; context jsonb; candidate jsonb; chosen jsonb; accepted public.user_interview_turn%rowtype;
 project text; question text; prior public.user_lifetime_strategy_outcome%rowtype;
begin
 perform public.lock_lifetime_publication(p_fence);
 project:=p_fence->'identity'->>'project_id';
 select * into accepted from public.user_interview_turn where user_id=auth.uid() and project_id=project and client_turn_id=p_client_turn_id;
 if not found then raise exception 'accepted exact source required' using errcode='PT409';end if;
 if jsonb_typeof(p_outcome) is distinct from 'object' or not(p_outcome ?& array['schema_version','plan_revision_seen','selected_candidate_id',
   'selection_reason','used_strategy','question_delivered','work_hint']) or exists(select 1 from jsonb_object_keys(p_outcome) k
     where k not in ('schema_version','plan_revision_seen','selected_candidate_id','selection_reason','used_strategy','question_delivered','work_hint'))
   or p_outcome->>'schema_version'<>'1' or coalesce(p_outcome->>'used_strategy','') not in ('comfort','explore','shape')
   or coalesce(p_outcome->>'selection_reason','') not in ('prepared_candidate','adapted_candidate','latest_story','user_redirect','current_correction',
     'pacing','recall_limit','pause','direct_answer','safe_fallback','stale_plan','no_plan','return_context')
   or p_outcome->>'work_hint' is distinct from p_plan->'work'->>'mode'
   or jsonb_typeof(p_outcome->'question_delivered') not in ('string','null') then raise exception 'invalid immediate outcome' using errcode='22023';end if;
 select q into chosen from jsonb_array_elements(p_plan->'candidates') q where q->>'id'=p_plan->>'chosen_id';
 question:=chosen->>'question';
 if question is distinct from p_outcome->>'question_delivered' or (question is null and p_outcome->>'selection_reason' not in ('pause','direct_answer','current_correction'))
   or (question is not null and (length(question)>800 or length(public.lifetime_question_text(question))=0
     or strpos(p_reply,public.lifetime_question_text(question))=0))
   or jsonb_array_length(p_plan->'candidates')>1 then raise exception 'outcome must match the saved immediate question' using errcode='22023';end if;
 select * into prior from public.user_lifetime_strategy_outcome where user_id=auth.uid() and project_id=project and client_turn_id=p_client_turn_id;
 if found then
   if prior.plan_revision_seen is distinct from (p_outcome->>'plan_revision_seen')::bigint
     or prior.selected_candidate_id is distinct from p_outcome->>'selected_candidate_id'
     or prior.selection_reason is distinct from p_outcome->>'selection_reason' or prior.used_strategy is distinct from p_outcome->>'used_strategy'
     or prior.question_delivered is distinct from question or prior.work_hint is distinct from p_outcome->>'work_hint' then
     raise exception 'saved outcome identity conflict' using errcode='PT409';end if;
 elsif p_prompt_version='reply-v2' and p_outcome->>'plan_revision_seen' is null
   and p_outcome->>'selected_candidate_id' is null then
   -- Mira's current interviewing decision has no background strategy dependency.
   null;
 else
   -- A validates its pinned revision, not the newest optional B result.
   -- The publication fence still owns current policy/source authority. A
   -- fallback that used no candidate cannot depend on a later B plan.
   context:=public.read_lifetime_strategy_context_at((p_fence->'identity'->>'conversation_id')::uuid,
     (p_outcome->>'plan_revision_seen')::bigint);
   if context->>'mode'<>'active' then raise exception 'strategy is disabled' using errcode='PT409';end if;
   if p_outcome->>'plan_revision_seen' is not null and not exists(select 1 from public.user_lifetime_interview_strategy p
     where p.user_id=auth.uid() and p.project_id=project and not p.shadow and p.plan_revision=(p_outcome->>'plan_revision_seen')::bigint) then
     raise exception 'pinned strategy unavailable' using errcode='PT409';end if;
   if p_outcome->>'selected_candidate_id' is not null then
     select q into candidate from jsonb_array_elements(public.read_lifetime_prepared_questions(
       (p_fence->'identity'->>'conversation_id')::uuid)) q
       where q->>'id'=p_outcome->>'selected_candidate_id';
     if candidate->>'historical_clue_id' is not null then
       if chosen->'context'->>'historical_clue_id' is distinct from candidate->>'historical_clue_id' then
         raise exception 'historical candidate identity changed' using errcode='22023';end if;
       candidate:=jsonb_set(candidate,'{question}',to_jsonb(case when public.read_lifetime_pinned(
         (p_fence->'identity'->>'conversation_id')::uuid)->>'language'='zh-CN'
         then '这条公开历史线索会让您想起当时的什么吗？' else 'Does this bring any memory of that time to mind?' end));
     end if;
     -- Public news has its own current authority; it need not belong to a B strategy plan.
     if candidate is null and chosen->'context'->>'historical_clue_id'=p_outcome->>'selected_candidate_id' then
       select jsonb_build_object('question',case when public.read_lifetime_pinned(
         (p_fence->'identity'->>'conversation_id')::uuid)->>'language'='zh-CN'
         then '这条公开历史线索会让您想起当时的什么吗？' else 'Does this bring any memory of that time to mind?' end)
       into candidate from jsonb_array_elements(public.read_user_historical_news(project)->'clues') clue
       where clue->>'id'=p_outcome->>'selected_candidate_id';
       if candidate is not null and candidate->>'question' is distinct from question then
         raise exception 'historical invitation must remain neutral' using errcode='22023';end if;
     end if;
     if candidate is null then
       if p_outcome->>'plan_revision_seen' is null or context->'plan'->>'plan_revision' is distinct from p_outcome->>'plan_revision_seen' then
         raise exception 'pinned candidate dependencies changed' using errcode='PT409';end if;
       select q into candidate from jsonb_array_elements(context->'plan'->'candidates') q where q->>'id'=p_outcome->>'selected_candidate_id';
     end if;
     if candidate is null or p_outcome->>'selection_reason' not in ('prepared_candidate','adapted_candidate','recall_limit') then
       raise exception 'candidate unavailable' using errcode='PT409';end if;
     if p_outcome->>'selection_reason'='recall_limit' and chosen->'context'->>'historical_clue_id' is null
       and candidate->>'scope' is distinct from 'broader' then
       raise exception 'recall limits require a broader candidate' using errcode='22023';end if;
     if p_outcome->>'selection_reason' in ('prepared_candidate','recall_limit')
       and public.lifetime_question_text(candidate->>'question') is distinct from public.lifetime_question_text(question) then
       raise exception 'prepared candidate text changed' using errcode='22023';end if;
   elsif p_outcome->>'selection_reason' in ('prepared_candidate','adapted_candidate') then raise exception 'candidate identity required' using errcode='22023';end if;
 end if;
 result:=public.commit_lifetime_turn(p_fence,p_client_turn_id,p_plan,p_associations,p_reply,p_response_photo_ids,p_thread_id,p_prompt_version,p_model,p_continuity_updates,
   (p_outcome->>'plan_revision_seen')::bigint,p_name_update);
 insert into public.user_lifetime_strategy_outcome(user_id,project_id,client_turn_id,reply_id,source_id,source_sequence,
   plan_revision_seen,selected_candidate_id,selection_reason,used_strategy,question_delivered,work_hint)
 values(auth.uid(),project,p_client_turn_id,(result->'memory'->0->>'id')::uuid,accepted.source_id,
   (select sequence from public.user_narrator_source where user_id=auth.uid() and project_id=project and id=accepted.source_id),
   (p_outcome->>'plan_revision_seen')::bigint,p_outcome->>'selected_candidate_id',p_outcome->>'selection_reason',p_outcome->>'used_strategy',question,p_outcome->>'work_hint')
 on conflict do nothing;
 return result||jsonb_build_object('strategy_metrics',jsonb_build_object('repeated_question_count',
   (select count(*) from public.user_lifetime_strategy_outcome o where o.user_id=auth.uid() and o.project_id=project
     and o.delivered and o.client_turn_id<>p_client_turn_id
     and lower(public.lifetime_question_text(o.question_delivered))=lower(public.lifetime_question_text(question))),
   'previous_delivered_question_count',(select count(*) from public.user_lifetime_strategy_outcome o
     where o.user_id=auth.uid() and o.project_id=project and o.delivered and o.client_turn_id<>p_client_turn_id and o.question_delivered is not null)));
end $$;

CREATE FUNCTION public.commit_lifetime_turn(p_fence jsonb, p_client_turn_id uuid, p_plan jsonb, p_associations jsonb, p_reply text, p_response_photo_ids jsonb, p_thread_id text, p_prompt_version text, p_model text, p_continuity_updates jsonb DEFAULT '[]'::jsonb, p_plan_revision bigint DEFAULT NULL::bigint, p_name_update text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare owner uuid:=auth.uid(); conversation uuid:=(p_fence->'identity'->>'conversation_id')::uuid;
 project text; accepted public.user_interview_turn%rowtype; source public.user_narrator_source%rowtype;
 interview jsonb; memory jsonb; plan_fence jsonb; next_fence jsonb; pins jsonb; prior public.user_lifetime_reply%rowtype;
begin
 select project_id into project from public.user_lifetime_conversation where user_id=owner and conversation_id=conversation;
 if not found then raise exception 'conversation unavailable'; end if;
 perform 1 from public.user_memoir_project where user_id=owner and project_id=project for update;
 perform public.lock_lifetime_publication(p_fence);
 if length(coalesce(p_model,'')) not between 1 and 200 or length(coalesce(p_prompt_version,'')) not between 1 and 100 then raise exception 'execution compatibility required'; end if;
 select * into accepted from public.user_interview_turn where user_id=owner and project_id=project and client_turn_id=p_client_turn_id;
 if not found then raise exception 'accepted narrator turn required'; end if;
 select * into prior from public.user_lifetime_reply where user_id=owner and conversation_id=conversation and client_turn_id=p_client_turn_id;
 if found then
   if accepted.collector->>'thread_id' is distinct from p_thread_id or accepted.collector->>'reply' is distinct from p_reply
     or prior.model is distinct from p_model or prior.prompt_version is distinct from p_prompt_version
     or (p_prompt_version='reply-v2' and accepted.collector->>'immediate_name' is distinct from p_name_update) then
     raise exception 'saved execution identity conflict'; end if;
   select jsonb_build_array(to_jsonb(m)) into memory from public.user_memory m where m.user_id=owner and m.id=prior.memory_id;
   return jsonb_build_object('memory',memory,'interview',public.read_user_interview_turn(project,p_client_turn_id),'fence',p_fence);
 end if;
 select * into source from public.user_narrator_source where user_id=owner and project_id=project and id=accepted.source_id
   and version=accepted.source_version and status='active';
 if not found then raise exception 'active exact narrator source required'; end if;
 interview:=public.save_lifetime_interview_plan(p_fence,project,p_client_turn_id,p_plan,p_associations,(p_fence->>'lease_token')::uuid,
   p_reply,p_response_photo_ids,p_thread_id,p_plan_revision);
 -- Validated photo links invalidate projections inside this locked save.
 -- Each epoch bump also advances execution generation and may revoke derived
 -- preferences. Bind that trigger effect; keep source, identity and lease exact.
 plan_fence:=public.capture_lifetime_fence(conversation,(p_fence->>'lease_token')::uuid);
 if plan_fence-'policy_epoch'-'execution_generation'-'preference_revision' is distinct from p_fence-'policy_epoch'-'execution_generation'-'preference_revision'
   or (plan_fence->>'policy_epoch')::bigint<(p_fence->>'policy_epoch')::bigint
   or (plan_fence->>'execution_generation')::bigint-(p_fence->>'execution_generation')::bigint
      is distinct from (plan_fence->>'policy_epoch')::bigint-(p_fence->>'policy_epoch')::bigint
   or (plan_fence->'policy_epoch'=p_fence->'policy_epoch' and plan_fence->'preference_revision' is distinct from p_fence->'preference_revision') then
   raise exception 'unexpected plan mutation'; end if;
 if p_name_update is not null then
   if p_prompt_version<>'reply-v2' then raise exception 'immediate name requires reply v2';end if;
   perform public.persist_lifetime_chosen_name(conversation,source.id,source.version,p_name_update);
 elsif p_plan->'work'->>'mode'='reply_only' and p_plan->'work'->>'name' is not null then
   -- Retain exact source/version authority and preserve independent settings.
   perform public.persist_lifetime_chosen_name(conversation,source.id,source.version,p_plan->'work'->>'name');
 end if;
 next_fence:=public.capture_lifetime_fence(conversation,(p_fence->>'lease_token')::uuid);
 next_fence:=public.persist_lifetime_continuity_updates(next_fence,p_continuity_updates,false);
 -- Only validated phase/name/continuity changes may follow the plan's photo save.
 -- All locks stay held, so no external correction/preference/source can intervene.
 next_fence:=public.capture_lifetime_fence(conversation,(p_fence->>'lease_token')::uuid);
 if next_fence-'phase_revision'-'preference_revision' is distinct from plan_fence-'phase_revision'-'preference_revision' then raise exception 'unexpected execution mutation'; end if;
 pins:=public.read_lifetime_pinned(conversation);
 update public.user_interview_turn set collector=collector||jsonb_build_object('history_privacy_digest',
   encode(sha256(convert_to(jsonb_build_object('excluded_topics',pins->'excluded_topics','paused_topics',pins->'paused_topics',
     'privacy_complete',pins->'privacy_complete')::text,'UTF8')),'hex'))
   where user_id=owner and project_id=project and client_turn_id=p_client_turn_id;
 if p_prompt_version='reply-v2' then
   update public.user_interview_turn set collector=collector||jsonb_build_object('immediate_name',p_name_update)
     where user_id=owner and project_id=project and client_turn_id=p_client_turn_id;
 end if;
 memory:=public.commit_lifetime_interview_memory(next_fence,(p_fence->>'lease_token')::uuid,p_thread_id,
   'Storyteller: '||source.text||E'\nMemory Spark: '||p_reply,'{}'::text[],null,project,p_client_turn_id,true,'unplaced');
 insert into public.user_lifetime_reply values(owner,conversation,p_client_turn_id,(memory->0->>'id')::uuid,
   (next_fence->>'policy_epoch')::bigint,(next_fence->>'source_revision')::bigint,(next_fence->>'execution_generation')::bigint,
   (next_fence->>'phase_revision')::bigint,(next_fence->>'preference_revision')::bigint,p_model,p_prompt_version)
   on conflict do nothing;
 perform public.prune_lifetime_question_pool(owner,project);
 update public.user_lifetime_conversation set thread_schema_version=1,thread_id=p_thread_id,thread_model=p_model,thread_prompt_version=p_prompt_version,
   thread_policy_epoch=(next_fence->>'policy_epoch')::bigint where user_id=owner and conversation_id=conversation;
 return jsonb_build_object('memory',memory,'interview',interview,'fence',next_fence);
end $$;

CREATE FUNCTION public.commit_user_agent_turn(p_lease_token uuid, p_thread_id text, p_content text, p_source_paths text[] DEFAULT '{}'::text[], p_source_sequence bigint DEFAULT NULL::bigint, p_project_id text DEFAULT NULL::text, p_client_turn_id uuid DEFAULT NULL::uuid, p_user_response boolean DEFAULT true, p_life_stage text DEFAULT 'unplaced'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 raise exception 'governed atomic commit required' using errcode='42501';
end $$;

CREATE FUNCTION public.commit_user_agent_turn_before_photos(p_lease_token uuid, p_thread_id text, p_content text, p_source_paths text[] DEFAULT '{}'::text[], p_source_sequence bigint DEFAULT NULL::bigint, p_project_id text DEFAULT NULL::text, p_client_turn_id uuid DEFAULT NULL::uuid, p_user_response boolean DEFAULT true, p_life_stage text DEFAULT 'unplaced'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $memoir$
declare owner_id uuid:=auth.uid(); saved public.user_memory%rowtype; result jsonb;
begin
  if owner_id is null then raise exception 'authenticated user required' using errcode='42501'; end if;
  if p_project_id is not null and p_project_id !~ '^[A-Za-z0-9][A-Za-z0-9_-]{0,127}$' then
    raise exception 'invalid project' using errcode='22023'; end if;
  if p_client_turn_id is not null then
    select * into saved from public.user_memory where user_id=owner_id and client_turn_id=p_client_turn_id
      and project_id is not distinct from p_project_id;
    if found then return pg_catalog.jsonb_build_array(pg_catalog.to_jsonb(saved)); end if;
  end if;
  result:=public.commit_user_agent_turn_legacy(p_lease_token,p_thread_id,p_content,p_source_paths,p_source_sequence);
  update public.user_memory set project_id=p_project_id,client_turn_id=p_client_turn_id,
      life_stage=coalesce(p_life_stage,'unplaced'),
      kind=case when p_user_response then 'agent' else 'agent_greeting' end
    where id=(result->0->>'id')::uuid and user_id=owner_id returning * into saved;
  if not p_user_response then
    update public.user_recall_usage set rounds_completed=greatest(rounds_completed-1,0) where user_id=owner_id;
  end if;
  return pg_catalog.jsonb_build_array(pg_catalog.to_jsonb(saved));
end $memoir$;

CREATE FUNCTION public.commit_user_agent_turn_legacy(p_lease_token uuid, p_thread_id text, p_content text, p_source_paths text[] DEFAULT '{}'::text[], p_source_sequence bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  owner_id uuid := auth.uid();
  held public.user_agent_turn_lease%rowtype;
  saved public.user_memory%rowtype;
  next_sequence bigint;
begin
  if owner_id is null then
    raise exception 'authenticated user required' using errcode = '42501';
  end if;
  select * into held from public.user_agent_turn_lease
    where user_id = owner_id for update;
  if not found or held.lease_token is distinct from p_lease_token
      or held.expires_at <= pg_catalog.clock_timestamp() then
    raise exception 'Codex turn lease lost' using errcode = '42501';
  end if;
  if p_thread_id is null or pg_catalog.btrim(p_thread_id) = '' or p_content is null then
    raise exception 'thread and content required' using errcode = '22023';
  end if;
  if exists (
    select 1 from pg_catalog.unnest(p_source_paths) as source(path)
    where path is null or path !~
      ('^(sessions|archived_sessions|memories)/turns/' || p_lease_token::text || '/[^.].*')
      or path ~ '(^|/)\.'
  ) then
    raise exception 'invalid turn artifact path' using errcode = '22023';
  end if;

  insert into public.user_agent_session(user_id, codex_thread_id, status, turn_sequence, updated_at)
    values (owner_id, p_thread_id, 'active', 1, pg_catalog.clock_timestamp())
    on conflict (user_id) do update set
      codex_thread_id = excluded.codex_thread_id,
      status = excluded.status,
      turn_sequence = public.user_agent_session.turn_sequence + 1,
      updated_at = excluded.updated_at
    returning turn_sequence into next_sequence;

  insert into public.user_memory(user_id, kind, content, source_paths, source_sequence)
    values (owner_id, 'agent', p_content, coalesce(p_source_paths, '{}'), next_sequence)
    returning * into saved;
  return pg_catalog.jsonb_build_array(pg_catalog.to_jsonb(saved));
end;
$$;

CREATE FUNCTION public.complete_formal_memoir(p_run_id uuid, p_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare run public.user_formal_memoir_run%rowtype; current_revision bigint; coverage jsonb; edition uuid:=gen_random_uuid();
 manuscript_digest text; receipt jsonb; result jsonb;
begin
 run:=public.lock_formal_memoir_run(p_run_id,null,false);
 if run.state='completed' then
   if p_token is distinct from run.token then raise exception 'FORMAL_LEASE_STALE' using errcode='PT409';end if;
   return (select e.result from public.user_formal_memoir_edition e where e.run_id=run.id and e.active);
 end if;
 run:=public.lock_formal_memoir_run(p_run_id,p_token);
 select revision into current_revision from public.user_formal_memoir_head where user_id=run.user_id and project_id=run.project_id for update;
 if current_revision is distinct from run.base_revision then raise exception 'FORMAL_REVISION_CHANGED' using errcode='PT409';end if;
 if (select count(*) from public.user_formal_memoir_chapter where run_id=run.id)<>run.chapter_count
   or (select count(*) from public.user_formal_memoir_plan where run_id=run.id)<>run.chapter_count then
   raise exception 'FORMAL_COVERAGE_INCOMPLETE' using errcode='PT409';end if;
 select jsonb_agg(jsonb_build_object('chapter_id',p.chapter_id,'revision',1,'digest',c.digest) order by p.ordinal)
 into coverage from public.user_formal_memoir_plan p join public.user_formal_memoir_chapter c using(run_id,ordinal) where p.run_id=run.id;
 manuscript_digest:=public.formal_memoir_digest(coverage);
 receipt:=jsonb_build_object('schema_version',1,'receipt_id',gen_random_uuid(),'run_id',run.id,'edition_id',edition,
   'owner_id',run.user_id,'project_id',run.project_id,'conversation_id',run.conversation_id,'locale',run.locale,
   'revision',current_revision+1,'manuscript_digest',manuscript_digest,'chapter_coverage',coverage,'plan_digest',run.plan_digest,
   'policy_epoch',run.policy_epoch,'preference_revision',run.preference_revision,'phase_revision',run.phase_revision,
   'source_revision',run.source_revision,'event_revision',run.event_revision,'pending_count',0,'blocking_count',0,
   'scope','all_active_canonical_events_at_initiation','assembly','extractive-v1','manuscript_kind','formal_memoir','manuscript_status','draft','publication_approved',false,
   'source_manifest_digest',public.formal_memoir_digest((select jsonb_agg(p.evidence order by p.ordinal) from public.user_formal_memoir_plan p where p.run_id=run.id)),
   'validation_digest',public.formal_memoir_digest((select jsonb_agg(c.validation_digest order by c.ordinal) from public.user_formal_memoir_chapter c where c.run_id=run.id)));
 result:=jsonb_build_object('status','completed','edition_id',edition,'revision',current_revision+1,'manuscript_digest',manuscript_digest,'receipt',receipt);
 update public.user_formal_memoir_edition set active=false where user_id=run.user_id and project_id=run.project_id;
 insert into public.user_formal_memoir_edition(id,run_id,user_id,project_id,revision,digest,result)
 values(edition,run.id,run.user_id,run.project_id,current_revision+1,manuscript_digest,result);
 update public.user_formal_memoir_head set revision=current_revision+1,edition_id=edition,consent_revision=consent_revision+1
 where user_id=run.user_id and project_id=run.project_id;
 update public.user_formal_memoir_run set state='completed',lease_until=null where id=run.id;
 return result;
end $$;

CREATE FUNCTION public.complete_lifetime_memoir_lane(p_lane_id uuid, p_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare result jsonb; next_locale text;
begin
 result:=public.complete_lifetime_memoir_lane_before_rework(p_lane_id,p_token);
 -- A saved page is not yet a readable proposal. Keep its request pending until
 -- the complete root is published, so stale/yielded snapshots can be retried.
 update public.user_workspace_section_rework set status='composed'
   where composed_snapshot_id=(result->>'snapshot_id')::uuid and status='pending';
 -- Never reschedule a request whose canonical partition no longer exists.
 delete from public.user_workspace_section_rework request using public.user_memoir_lane lane
   where lane.id=p_lane_id and lane.user_id=request.user_id and lane.project_id=request.project_id and lane.skill='composer'
     and request.status='pending' and not public.workspace_rework_partition_current(request.user_id,request.project_id,request.event_id,request.partition_key);
 select request.locale into next_locale from public.user_workspace_section_rework request join public.user_memoir_lane lane
   on lane.user_id=request.user_id and lane.project_id=request.project_id and lane.skill='composer'
   where lane.id=p_lane_id and request.status='pending' order by request.created_at,request.request_id limit 1;
 if found then
   update public.user_memoir_lane set locale=next_locale,pending=true,attempts=0,error=null,available_at=clock_timestamp() where id=p_lane_id;
 end if;
 return result;
end $$;

CREATE FUNCTION public.complete_lifetime_memoir_lane_before_rework(p_lane_id uuid, p_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare snap public.user_lifetime_lane_snapshot%rowtype; lane public.user_memoir_lane%rowtype; page jsonb; locked boolean:=false;
begin
 snap:=public.lock_lifetime_memoir_lane(p_lane_id,p_token);
 select * into lane from public.user_memoir_lane where id=p_lane_id;
 page:=public.read_lifetime_memoir_lane_page(lane.id,p_token);
 if (page->>'complete')::boolean is distinct from true then raise exception 'canonical coverage remains incomplete';end if;
 if lane.skill='composer' then
   insert into public.user_memoir_edition(user_id,project_id,locale) values(lane.user_id,lane.project_id,snap.locale) on conflict do nothing;
   select human_locked into locked from public.user_memoir_edition where user_id=lane.user_id and project_id=lane.project_id and locale=snap.locale for update;
   locked:=locked or exists(select 1 from public.user_lifetime_memoir_section where user_id=lane.user_id and project_id=lane.project_id and locale=snap.locale and snapshot_id=snap.id and proposal is not null);
   if (select revision from public.user_memoir_edition where user_id=lane.user_id and project_id=lane.project_id and locale=snap.locale)<>snap.base_revision then
     raise exception 'canonical manuscript revision changed' using errcode='PT409';end if;
   if not locked then
     update public.user_memoir_edition set revision=revision+1,covered_round=snap.round_high_water,
       source_sequence=snap.source_high_water,event_sequence=snap.event_high_water,completed_milestone=snap.milestone
       where user_id=lane.user_id and project_id=lane.project_id and locale=snap.locale;
   end if;
   update public.user_memoir_milestone set state=case when locked then 'proposed' else 'completed' end,
     covered_round=snap.round_high_water,manuscript_revision=snap.base_revision+case when locked then 0 else 1 end
     where user_id=lane.user_id and project_id=lane.project_id and locale=snap.locale and milestone<=snap.milestone and state='pending';
 end if;
 update public.user_lifetime_lane_snapshot set state=case when locked then 'proposed' else 'completed' end where id=snap.id;
 update public.user_memoir_lane set token=null,lease_until=null,run_deadline=null,successful_source=snap.source_high_water,
   successful_event=case when skill='composer' then snap.event_high_water else successful_event end,successful_round=snap.round_high_water,
   pending=pending or target_source>snap.source_high_water or (skill='composer' and target_event>snap.event_high_water),attempts=0,error=null,
   active_manifest='[]',active_events='[]' where id=lane.id;
 return jsonb_build_object('status',case when locked then 'proposed' else 'saved' end,'snapshot_id',snap.id,
   'root_digest',snap.root_digest,'retrieval_complete',true,'pages',snap.page_number,'publication_approved',false);
end $$;

CREATE FUNCTION public.complete_lifetime_memory_obligation(p_fence jsonb, p_id uuid, p_claim_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare saved public.user_lifetime_memory_obligation%rowtype; refs jsonb; source public.user_narrator_source%rowtype;
begin
  select * into saved from public.user_lifetime_memory_obligation where id=p_id and user_id=auth.uid();
  if not found then raise exception 'obligation unavailable'; end if;
  perform 1 from public.user_memoir_project where user_id=auth.uid() and project_id=saved.project_id for update;
  perform public.lock_lifetime_publication(p_fence);
  select * into saved from public.user_lifetime_memory_obligation where id=p_id and user_id=auth.uid() for update;
  if saved.fence is distinct from p_fence or saved.claim_token is distinct from p_claim_token or p_claim_token is null
    or saved.status not in ('running','succeeded') or saved.claim_expires_at<=clock_timestamp()
    or not public.lifetime_obligation_origin_current(saved) then raise exception 'stale obligation claim' using errcode='PT409'; end if;
  if saved.status='succeeded' then return public.lifetime_obligation_record(saved); end if;
  select * into source from public.user_narrator_source where user_id=saved.user_id and project_id=saved.project_id
    and id=saved.source_id and version=saved.source_version and status='active';
  refs:='[]';
  if found then
    select jsonb_agg(jsonb_build_object('source_id',source.id,'version',source.version,'char_start',offset_value,
      'char_end',least(offset_value+2048,length(source.text))) order by offset_value) into refs
      from generate_series(0,length(source.text)-1,2048) offset_value;
  end if;
  update public.user_lifetime_memory_obligation set status='succeeded',error_code=null,updated_at=clock_timestamp(),
    projection=jsonb_build_object('schema_version',1,'kind','canonical_references','origin_id',saved.origin_id,
      'policy_epoch',saved.policy_epoch,'sources',coalesce(refs,'[]'),'canonical_recovery_required',false)
    where id=p_id returning * into saved;
  return public.lifetime_obligation_record(saved);
end $$;

CREATE FUNCTION public.conversation_has_narration(p_owner uuid, p_project text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select exists(select 1 from public.user_narrator_source n where n.user_id=p_owner
   and n.project_id=p_project and n.status='active' and not exists(select 1 from public.user_interview_turn t
     where t.user_id=n.user_id and t.project_id=n.project_id and t.source_id=n.id
     and (t.collector is null or t.collector->'plan'->'work'->>'mode'='reply_only')))
 or exists(select 1 from public.user_memory m where m.user_id=p_owner and m.project_id=p_project
   and m.kind='agent' and m.content like 'Storyteller: %' and position(E'\nMemory Spark: ' in m.content)>0
   and not exists(select 1 from public.user_interview_turn t where t.user_id=m.user_id
     and t.project_id=m.project_id and t.client_turn_id=m.client_turn_id));
$$;

CREATE FUNCTION public.correct_user_memory_event(p_project_id text, p_event_id text, p_expected_revision bigint, p_patch jsonb, p_statement text, p_origin text DEFAULT 'workspace'::text, p_source_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb;
begin
  result:=public.correct_user_memory_event_before_stage_progress(
    p_project_id,p_event_id,p_expected_revision,p_patch,p_statement,p_origin,p_source_id);
  update public.user_memory_event_source s
    set stage_progress_role=case when s.stage_progress_role='primary' then 'primary' else 'stage' end
    from public.user_memory_event e
    where e.user_id=auth.uid() and e.project_id=p_project_id and e.id=p_event_id
      and s.user_id=e.user_id and s.project_id=e.project_id and s.event_id=e.id
      and coalesce(e.data->'stage_evidence','[]'::jsonb) @> jsonb_build_array(s.evidence);
  return result;
end $$;

CREATE FUNCTION public.correct_user_memory_event_before_stage_progress(p_project_id text, p_event_id text, p_expected_revision bigint, p_patch jsonb, p_statement text, p_origin text DEFAULT 'workspace'::text, p_source_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner_id uuid:=auth.uid(); saved public.user_memory_event%rowtype; patch_key text; overrides jsonb; next_change bigint;
  correction_source jsonb; correction_ref jsonb;
begin
  if owner_id is null then raise exception 'authenticated user required' using errcode='42501'; end if;
  if p_origin not in ('workspace','chat') or (p_origin='workspace' and p_source_id is not null) then
    raise exception 'invalid correction origin' using errcode='22023'; end if;
  if pg_catalog.jsonb_typeof(p_patch) is distinct from 'object' or p_patch='{}'::jsonb or
     exists(select 1 from pg_catalog.jsonb_object_keys(p_patch) k where k not in ('life_stage','temporal','visibility','include_in_print')) or
     length(pg_catalog.btrim(coalesce(p_statement,''))) not between 1 and 2000 then
    raise exception 'invalid explicit correction' using errcode='22023';
  end if;
  perform 1 from public.user_memoir_project where user_id=owner_id and project_id=p_project_id for update;
  select * into saved from public.user_memory_event where user_id=owner_id and project_id=p_project_id and id=p_event_id for update;
  if not found then raise exception 'event unavailable' using errcode='42501'; end if;
  if saved.revision is distinct from p_expected_revision then
    raise exception 'event revision conflict; reload the event' using errcode='PT409';
  end if;
  if p_patch ? 'life_stage' and (p_patch->>'life_stage' is null or p_patch->>'life_stage' not in
    ('baby','childhood','adolescence','young_adulthood','midlife','later_life','unplaced')) then
    raise exception 'invalid life stage' using errcode='22023';
  end if;
  if p_patch ? 'temporal' and (pg_catalog.jsonb_typeof(p_patch->'temporal') is distinct from 'object' or
    p_patch->'temporal'->>'precision' is null or p_patch->'temporal'->>'precision' not in ('unknown','day','month','year','range','approximate','age','season') or
    length(coalesce(p_patch->'temporal'->>'expression','')) not between 1 and 500) then
    raise exception 'invalid temporal correction' using errcode='22023';
  end if;
  overrides:=coalesce(saved.data->'user_overrides','{}'::jsonb);
  if p_origin='chat' then
    select public.narrator_source_record(s) into correction_source from public.user_narrator_source s
      where user_id=owner_id and project_id=p_project_id and id=p_source_id and status='active' and text=p_statement;
    if correction_source is null or p_statement !~* '(correct|actually|year was|i meant|should be|更正|纠正|应该|其实|不是)' then
      raise exception 'explicit chat correction source unavailable' using errcode='42501'; end if;
  else
    correction_source:=public.accept_user_narrator_source(p_project_id,pg_catalog.gen_random_uuid(),p_statement,'narrator_chat',
      case when p_statement ~ '[一-鿿]' then 'zh-CN' else 'en-AU' end);
  end if;
  update public.user_narrator_source set processing_status='succeeded' where user_id=owner_id and project_id=p_project_id and id=(correction_source->>'id')::uuid;
  correction_ref:=pg_catalog.jsonb_build_object('source_id',correction_source->>'id','version',correction_source->'version','quote',p_statement,'attribution',owner_id::text);
  if p_patch ? 'temporal' then p_patch:=pg_catalog.jsonb_set(p_patch,'{temporal,basis}',pg_catalog.jsonb_build_array(correction_ref)); end if;
  if p_patch ? 'temporal' then perform public.validate_memory_temporal(owner_id,p_project_id,p_patch->'temporal'); end if;
  if p_patch ? 'life_stage' then
    p_patch:=p_patch || pg_catalog.jsonb_build_object('stage_evidence',pg_catalog.jsonb_build_array(correction_ref));
  end if;
  insert into public.user_memory_event_source(user_id,project_id,event_id,source_id,source_version,evidence_hash,evidence)
    values(owner_id,p_project_id,p_event_id,(correction_source->>'id')::uuid,(correction_source->>'version')::bigint,pg_catalog.md5(correction_ref::text),correction_ref) on conflict do nothing;
  for patch_key in select pg_catalog.jsonb_object_keys(p_patch) loop
    overrides:=overrides || pg_catalog.jsonb_build_object(patch_key,pg_catalog.jsonb_build_object(
      'actor',owner_id,'origin',p_origin,'statement',p_statement,'expected_revision',p_expected_revision,
      'source_id',correction_source->>'id','source_version',correction_source->'version'));
  end loop;
  update public.user_memoir_project set event_sequence=event_sequence+1,policy_epoch=policy_epoch+1
    where user_id=owner_id and project_id=p_project_id returning event_sequence into next_change;
  update public.user_memory_event set data=(data || (p_patch-'life_stage')) || pg_catalog.jsonb_build_object('user_overrides',overrides),
    life_stage=coalesce(p_patch->>'life_stage',life_stage),revision=revision+1,change_sequence=next_change
    where user_id=owner_id and project_id=p_project_id and id=p_event_id returning * into saved;
  if p_patch ? 'temporal' then
    update public.user_memory_event set data=data || '{"timing_conflict":false}'::jsonb
      where user_id=owner_id and project_id=p_project_id and id=p_event_id returning * into saved;
  end if;
  insert into public.user_memory_event_revision(user_id,project_id,event_id,revision,record,actor,origin)
    values(owner_id,p_project_id,p_event_id,saved.revision,public.memory_event_record(saved),owner_id::text,p_origin);
  insert into public.user_private_draft_outbox(user_id,project_id,change_kind) values(owner_id,p_project_id,'correction');
  update public.user_memoir_project set extraction_cursor=coalesce((select min(sequence)-1 from public.user_narrator_source
    where user_id=owner_id and project_id=p_project_id and status='active' and processing_status<>'succeeded'),source_sequence)
    where user_id=owner_id and project_id=p_project_id;
  return public.memory_event_record(saved);
end $$;

CREATE FUNCTION public.count_recall_reply() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.kind = 'agent' then
    insert into public.user_recall_usage(user_id, rounds_completed) values(new.user_id, 1)
      on conflict(user_id) do update set rounds_completed = public.user_recall_usage.rounds_completed + 1;
  end if;
  return new;
end;
$$;

CREATE FUNCTION public.create_lifetime_checkpoint(p_fence jsonb, p_coverage_end bigint, p_model text, p_prompt_version text, p_evidence jsonb DEFAULT '[]'::jsonb, p_coverage_proof uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
begin
 perform public.lock_lifetime_publication(p_fence);
 if exists(select 1 from public.user_lifetime_conversation l join public.user_lifetime_checkpoint c on c.id=l.checkpoint_id
   where l.user_id=auth.uid() and l.conversation_id=(p_fence->'identity'->>'conversation_id')::uuid and c.memory_summary is not null) then
   raise exception 'LIFETIME_SEMANTIC_MAINTENANCE_REQUIRED: accepted summary requires bounded B maintenance' using errcode='PT409';
 end if;
 return public.create_lifetime_checkpoint_before_semantic(p_fence,p_coverage_end,p_model,p_prompt_version,p_evidence,p_coverage_proof);
end $$;

CREATE FUNCTION public.create_lifetime_checkpoint_before_proof(p_fence jsonb, p_coverage_end bigint, p_model text, p_prompt_version text, p_evidence jsonb DEFAULT '[]'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $memoir$
declare owner uuid:=auth.uid(); conversation uuid:=(p_fence->'identity'->>'conversation_id')::uuid;
  project text; predecessor uuid; prior_end bigint:=0; claim jsonb; source public.user_narrator_source%rowtype;
  manifest_sources jsonb:='[]'; candidate uuid; pins jsonb;
begin
  -- UPDATE lock first so candidates/publication use the same project-first order.
  select project_id into project from public.user_lifetime_conversation where user_id=owner and conversation_id=conversation;
  if not found then raise exception 'conversation unavailable'; end if;
  perform 1 from public.user_memoir_project where user_id=owner and project_id=project for update;
  perform public.lock_lifetime_publication(p_fence);
  if p_coverage_end is null or p_coverage_end<1 or p_coverage_end>(p_fence->>'source_revision')::bigint then raise exception 'invalid checkpoint coverage'; end if;
  select checkpoint_id into predecessor from public.user_lifetime_conversation where user_id=owner and conversation_id=conversation;
  if predecessor is not null then select coverage_end into prior_end from public.user_lifetime_checkpoint where id=predecessor and published; end if;
  if p_coverage_end<=coalesce(prior_end,0) then raise exception 'checkpoint must advance coverage'; end if;
  if jsonb_typeof(p_evidence) is distinct from 'array' or jsonb_array_length(p_evidence)>16 then raise exception 'bounded checkpoint evidence required'; end if;
  for claim in select value from jsonb_array_elements(p_evidence) loop
    if jsonb_typeof(claim) is distinct from 'object' then raise exception 'evidence object required'; end if;
    if exists(select 1 from jsonb_object_keys(claim) k where k not in
      ('schema_version','source_id','version','char_start','char_end','original','language','role','assertion','uncertainty',
       'time_meaning','translation','translation_attribution','supersedes','contradicts','allowed_use','policy_epoch'))
      or jsonb_typeof(claim->'schema_version') is distinct from 'number'
      or jsonb_typeof(claim->'policy_epoch') is distinct from 'number'
      or jsonb_typeof(claim->'allowed_use') is distinct from 'array' then raise exception 'typed checkpoint envelope required'; end if;
    if jsonb_array_length(claim->'allowed_use') not between 1 and 3 or exists(
      select 1 from jsonb_array_elements(claim->'allowed_use') u where jsonb_typeof(u)<>'string' or u#>>'{}' not in ('conversation','extraction','composition'))
      then raise exception 'invalid checkpoint uses'; end if;
    if exists(select 1 from (values('uncertainty',2000),('time_meaning',500),('translation',2000),('translation_attribution',200)) bounds(k,n)
      where claim->k is not null and claim->k<>'null'::jsonb and (jsonb_typeof(claim->k)<>'string' or length(claim->>k)>n))
      or ((claim->>'translation') is null)<>((claim->>'translation_attribution') is null) then raise exception 'invalid attributed checkpoint metadata'; end if;
    if exists(select 1 from (values('supersedes'),('contradicts')) fields(k)
      where claim->k is not null and jsonb_typeof(claim->k)<>'array') then raise exception 'invalid checkpoint relations'; end if;
    if jsonb_array_length(coalesce(claim->'supersedes','[]'))>100 or jsonb_array_length(coalesce(claim->'contradicts','[]'))>100
      or exists(select 1 from jsonb_array_elements(coalesce(claim->'supersedes','[]')||coalesce(claim->'contradicts','[]')) relation
        where jsonb_typeof(relation)<>'string' or length(relation#>>'{}') not between 1 and 128) then raise exception 'unbounded checkpoint relations'; end if;
    if not (claim ?& array['source_id','version','char_start','char_end','original','policy_epoch','allowed_use'])
      or jsonb_typeof(claim->'source_id') is distinct from 'string'
      or jsonb_typeof(claim->'version') is distinct from 'number' or coalesce(claim->>'version','')!~'^[1-9][0-9]*$'
      or jsonb_typeof(claim->'char_start') is distinct from 'number' or coalesce(claim->>'char_start','')!~'^[0-9]+$'
      or jsonb_typeof(claim->'char_end') is distinct from 'number' or coalesce(claim->>'char_end','')!~'^[1-9][0-9]*$'
      or jsonb_typeof(claim->'original') is distinct from 'string' or length(claim->>'original') not between 1 and 2000
      or claim->>'policy_epoch' is distinct from p_fence->>'policy_epoch'
      or not coalesce(claim->'allowed_use' @> '["conversation"]',false)
      or coalesce(claim->>'role','')<>'storyteller' or claim->>'schema_version' is distinct from '1'
      or coalesce(claim->>'assertion','') not in ('asserted','inferred') then raise exception 'invalid checkpoint evidence'; end if;
    select * into source from public.user_narrator_source where user_id=owner and project_id=project
      and id=(claim->>'source_id')::uuid and version=(claim->>'version')::bigint and status='active' and sequence<=p_coverage_end;
    if not found or claim->>'language' is distinct from source.language or (claim->>'char_end')::integer<=(claim->>'char_start')::integer
      or (claim->>'char_end')::integer>length(source.text)
      or substring(source.text from (claim->>'char_start')::integer+1 for (claim->>'char_end')::integer-(claim->>'char_start')::integer)
        is distinct from claim->>'original' then raise exception 'unsupported checkpoint quote'; end if;
    if not manifest_sources @> jsonb_build_array(jsonb_build_object('schema_version',1,'source_id',source.id,'version',source.version)) then
      manifest_sources:=manifest_sources || jsonb_build_array(jsonb_build_object('schema_version',1,'source_id',source.id,'version',source.version));
    end if;
  end loop;
  pins:=public.read_lifetime_pinned(conversation);
  insert into public.user_lifetime_checkpoint(user_id,conversation_id,predecessor_id,fence,coverage_end,model,prompt_version,pinned,manifest,evidence)
    values(owner,conversation,predecessor,p_fence,p_coverage_end,p_model,p_prompt_version,pins,
      jsonb_build_object('schema_version',1,'identity',p_fence->'identity','policy_epoch',(p_fence->>'policy_epoch')::bigint,
        'source_revision',(p_fence->>'source_revision')::bigint,'sources',manifest_sources),p_evidence) returning id into candidate;
  return candidate;
end $memoir$;

CREATE FUNCTION public.create_lifetime_checkpoint_before_semantic(p_fence jsonb, p_coverage_end bigint, p_model text, p_prompt_version text, p_evidence jsonb DEFAULT '[]'::jsonb, p_coverage_proof uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare proof public.user_lifetime_compaction%rowtype; project text; head uuid; candidate uuid;
begin
  select * into proof from public.user_lifetime_compaction where id=p_coverage_proof and user_id=auth.uid();
  if not found then raise exception 'complete coverage proof required'; end if;
  select project_id into project from public.user_lifetime_conversation where user_id=auth.uid() and conversation_id=proof.conversation_id;
  perform 1 from public.user_memoir_project where user_id=auth.uid() and project_id=project for update;
  perform public.lock_lifetime_publication(p_fence);
  select checkpoint_id into head from public.user_lifetime_conversation where user_id=auth.uid() and conversation_id=proof.conversation_id;
  if not proof.complete or proof.fence is distinct from p_fence or proof.through_sequence is distinct from p_coverage_end
    or proof.predecessor_id is distinct from head or proof.pinned is distinct from public.read_lifetime_pinned(proof.conversation_id)
    or proof.item_count<>(select count(*) from public.user_lifetime_covered_evidence where maintenance_id=proof.id) then
    raise exception 'incomplete or stale coverage proof' using errcode='PT409'; end if;
  candidate:=public.create_lifetime_checkpoint_before_proof(p_fence,p_coverage_end,p_model,p_prompt_version,p_evidence);
  update public.user_lifetime_checkpoint set coverage_proof_id=proof.id where id=candidate;
  return candidate;
end $$;

CREATE FUNCTION public.create_lifetime_collection_job(p_project_id text, p_kind text, p_title text, p_source_ids jsonb, p_expected_revision bigint DEFAULT NULL::bigint, p_locale text DEFAULT 'en-AU'::text, p_paused boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare owner uuid:=auth.uid(); project public.user_memoir_project%rowtype; identity public.user_lifetime_conversation%rowtype;
 doc public.user_lifetime_collection%rowtype; job public.user_lifetime_collection_job%rowtype; manifest jsonb; ids uuid[];
 digest text; dedup text; count_sources integer; count_pages integer;
begin
 if owner is null then raise exception 'authenticated owner required' using errcode='42501';end if;
 if p_kind='BuildOutline' then
  perform 1 from auth.users where id=owner and not is_anonymous for share;
  if not found then raise exception 'paid memoir entitlement required' using errcode='42501';end if;
 end if;
 if p_kind is null or p_kind not in ('BuildFreePreview','BuildSourceExport','BuildOutline') or p_locale is null or p_locale not in ('en-AU','zh-CN')
  or p_title is null or length(p_title) not between 1 and 200 then raise exception 'invalid collection job';end if;
 select * into project from public.user_memoir_project where user_id=owner and project_id=p_project_id for share;
 perform 1 from public.user_profile where user_id=owner for share;
 if not found then perform pg_advisory_xact_lock_shared(hashtextextended('memoir-profile:'||owner::text,0));end if;
 select * into identity from public.user_lifetime_conversation where user_id=owner and project_id=p_project_id for share;
 if not found then raise exception 'collection unavailable' using errcode='42501';end if;
 select * into doc from public.user_lifetime_collection where user_id=owner and project_id=p_project_id for share;
 if p_kind='BuildOutline' then
  if p_expected_revision is null or doc.revision is distinct from p_expected_revision or not coalesce(doc.ready,false)
   or doc.source_revision<>project.source_sequence or doc.policy_epoch<>project.policy_epoch or doc.preference_revision<>identity.preference_revision then
   raise exception 'confirm current collection before organising' using errcode='PT409';end if;
  perform 1 from public.story_entitlement where user_id=owner and status='paid' for share;
  if not found or exists(select 1 from auth.users where id=owner and is_anonymous) then raise exception 'paid memoir entitlement required' using errcode='42501';end if;
  select array_agg(source_id order by ordinal) into ids from public.user_lifetime_collection_selection where user_id=owner and project_id=p_project_id;
  if exists(select 1 from public.user_lifetime_collection_selection c left join public.user_narrator_source s on s.user_id=c.user_id and s.project_id=c.project_id and s.id=c.source_id
    where c.user_id=owner and c.project_id=p_project_id and (s.id is null or s.version<>c.source_version or s.status<>'active'
     or encode(sha256(convert_to(s.text,'UTF8')),'hex')<>c.source_hash)) then raise exception 'collection sources changed' using errcode='PT409';end if;
 else
  if jsonb_typeof(p_source_ids) is distinct from 'array' or jsonb_array_length(p_source_ids) not between 1 and 1000 then raise exception 'select 1 to 1000 sources';end if;
  select array_agg(value::uuid order by n) into ids from jsonb_array_elements_text(p_source_ids) with ordinality a(value,n);
  if cardinality(ids)<>(select count(distinct x) from unnest(ids)x) then raise exception 'duplicate source selection';end if;
 end if;
 if coalesce(cardinality(ids),0) not between 1 and 1000 then raise exception 'select 1 to 1000 sources';end if;
 if exists(select 1 from unnest(ids) selected where not exists(select 1 from public.user_narrator_source s
  where s.user_id=owner and s.project_id=p_project_id and s.id=selected and s.status='active' and s.kind in ('narrator_chat','narrator_transcript'))) then
  raise exception 'selected narrator source unavailable' using errcode='PT409';end if;
 select jsonb_agg(jsonb_build_object('id',s.id,'version',s.version,'hash',encode(sha256(convert_to(s.text,'UTF8')),'hex'),
  'length',length(s.text),'pages',(length(s.text)+2047)/2048) order by n),count(*),sum((length(s.text)+2047)/2048)
  into manifest,count_sources,count_pages from unnest(ids) with ordinality a(id,n) join public.user_narrator_source s
   on s.id=a.id and s.user_id=owner and s.project_id=p_project_id;
 digest:=encode(sha256(convert_to(manifest::text,'UTF8')),'hex');
 dedup:=encode(sha256(convert_to(jsonb_build_object('manifest',digest,'kind',p_kind,'title',p_title,'locale',p_locale,
  'policy',project.policy_epoch,'preferences',identity.preference_revision,'collection',case when p_kind='BuildOutline' then coalesce(doc.revision,0) else 0 end)::text,'UTF8')),'hex');
 if p_paused is distinct from false and not exists(select 1 from public.user_lifetime_collection_job where user_id=owner and project_id=p_project_id and dedup_key=dedup) then
  raise exception 'lifetime generation paused' using errcode='55000';end if;
 insert into public.user_lifetime_collection_job(user_id,project_id,conversation_id,kind,title,locale,policy_epoch,preference_revision,
  collection_revision,source_count,source_pages,manifest_digest,root_digest,dedup_key)
 values(owner,p_project_id,identity.conversation_id,p_kind,p_title,p_locale,project.policy_epoch,identity.preference_revision,
  case when p_kind='BuildOutline' then coalesce(doc.revision,0) else 0 end,count_sources,count_pages,digest,digest,dedup)
 on conflict(user_id,project_id,dedup_key) do nothing returning * into job;
 if job.id is null then select * into job from public.user_lifetime_collection_job where user_id=owner and project_id=p_project_id and dedup_key=dedup;
 else
  insert into public.user_lifetime_collection_job_source(job_id,ordinal,source_id,source_version,source_hash,original_length,first_page,page_count)
  select job.id,n::integer,(v->>'id')::uuid,(v->>'version')::bigint,v->>'hash',(v->>'length')::integer,
   (sum((v->>'pages')::integer) over(order by n)-(v->>'pages')::integer)::integer,(v->>'pages')::integer
  from jsonb_array_elements(manifest) with ordinality m(v,n);
 end if;
 return jsonb_build_object('id',job.id,'project_id',job.project_id,'kind',job.kind,'status',job.state,'attempts',job.attempts,
  'created_at',job.created_at,'result',null,'error',job.error,'source_count',job.source_count,'source_pages',job.source_pages);
end $$;

CREATE FUNCTION public.defer_lifetime_collection_job_policy(p_job_id uuid, p_token uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare job public.user_lifetime_collection_job%rowtype; conversation uuid;
begin
 if p_user_id is null or p_token is null then
  raise exception 'collection claim required' using errcode='42501';end if;
 -- Keep account/project/identity/job order, but do not read source content or
 -- invoke the policy-ready guard that intentionally blocked this worker.
 perform 1 from auth.users where id=p_user_id for share;
 if not found then raise exception 'collection owner unavailable' using errcode='42501';end if;
 select * into job from public.user_lifetime_collection_job where id=p_job_id and user_id=p_user_id;
 if not found then raise exception 'collection claim unavailable' using errcode='42501';end if;
 perform 1 from public.user_memoir_project where user_id=job.user_id and project_id=job.project_id for share;
 if not found then raise exception 'collection project unavailable' using errcode='42501';end if;
 select conversation_id into conversation from public.user_lifetime_conversation
  where user_id=job.user_id and project_id=job.project_id for share;
 if not found then raise exception 'collection identity unavailable' using errcode='42501';end if;
 select * into job from public.user_lifetime_collection_job where id=p_job_id and user_id=p_user_id for update;
 if not found or job.conversation_id is distinct from conversation or job.state<>'RUNNING'
  or job.token is distinct from p_token or job.lease_until is null or job.lease_until<=clock_timestamp() then
  raise exception 'stale collection claim' using errcode='PT409';end if;
 update public.user_lifetime_collection_job set state='QUEUED',token=null,lease_until=null,
  attempts=0,error='LIFETIME_POLICY_PENDING' where id=job.id;
 return true;
end $$;

CREATE FUNCTION public.defer_lifetime_memoir_lane(p_lane_id uuid, p_token uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
begin
 perform public.lock_lifetime_memoir_lane(p_lane_id,p_token);
 if p_reason not in ('LIFETIME_PRIVACY_MAINTENANCE_REQUIRED','LIFETIME_MODEL_BUDGET_REQUIRED',
   'LIFETIME_GENERATION_PAUSED','LIFETIME_PROVIDER_AUTHORITY_UNAVAILABLE') then
   raise exception 'invalid lane maintenance reason';end if;
 update public.user_memoir_lane set token=null,lease_until=null,run_deadline=null,pending=true,attempts=0,error=p_reason,
   available_at=clock_timestamp()+case when p_reason='LIFETIME_PROVIDER_AUTHORITY_UNAVAILABLE'
     then interval '15 seconds' else interval '5 minutes' end where id=p_lane_id;
 return jsonb_build_object('status','pending','error',p_reason,'retrieval_complete',false);
end $$;

CREATE FUNCTION public.defer_lifetime_memoir_lane_policy(p_lane_id uuid, p_token uuid, p_user_id uuid, p_project_id text, p_conversation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare lane public.user_memoir_lane%rowtype; policy_pending boolean;
begin
 select * into lane from public.user_memoir_lane
   where id=p_lane_id and user_id=p_user_id and project_id=p_project_id;
 if not found then raise exception 'canonical lane metadata authority unavailable' using errcode='42501';end if;
 perform 1 from public.user_memoir_project where user_id=p_user_id and project_id=p_project_id for update;
 if not found then raise exception 'canonical lane metadata authority unavailable' using errcode='42501';end if;
 perform 1 from public.user_profile where user_id=p_user_id for share;
 perform 1 from public.user_lifetime_conversation where user_id=p_user_id and project_id=p_project_id
   and conversation_id=p_conversation_id for share;
 if not found then raise exception 'canonical lane metadata authority unavailable' using errcode='42501';end if;
 select * into lane from public.user_memoir_lane where id=p_lane_id for update;
 if lane.id is null or lane.user_id is distinct from p_user_id or lane.project_id is distinct from p_project_id
   or lane.token is null or lane.token is distinct from p_token or lane.lease_until is null or lane.run_deadline is null
   or lane.lease_until<=clock_timestamp() or lane.run_deadline<=clock_timestamp() then
   raise exception 'stale canonical lane metadata lease' using errcode='PT409';end if;
 -- The page may already be stale and its contents remain inaccessible. This
 -- current owner/token can only relinquish its own lease and request a retry.
 -- The review may have finished while the policy error was in transit.
 policy_pending:=exists(select 1 from public.user_lifetime_pending_policy where user_id=p_user_id and project_id=p_project_id)
   or exists(select 1 from public.user_lifetime_policy_inventory_pending where user_id=p_user_id and project_id=p_project_id);
 update public.user_memoir_lane set token=null,lease_until=null,run_deadline=null,pending=true,attempts=0,
   error=case when policy_pending then 'LIFETIME_POLICY_PENDING' else null end,
   available_at=clock_timestamp()+case when policy_pending then interval '5 minutes' else interval '0 seconds' end
   where id=p_lane_id returning * into lane;
 return jsonb_build_object('status','pending','error',lane.error,'retrieval_complete',false);
end $$;

CREATE FUNCTION public.delete_user_interview_photo(p_project_id text, p_photo_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare saved public.user_interview_photo%rowtype; v_owner uuid:=auth.uid();
begin
  perform 1 from public.user_memoir_project where user_id=v_owner and project_id=p_project_id for update;
  select * into saved from public.user_interview_photo where user_id=v_owner and project_id=p_project_id and id=p_photo_id for update;
  if not found then return null; end if;
  if saved.status<>'deleted' then
    update public.user_interview_photo set status='deleted' where user_id=v_owner and project_id=p_project_id and id=p_photo_id;
    update public.user_interview_photo_link set status='invalidated',description='[photo deleted]',quote='[photo deleted:' || id::text || ']'
      where user_id=v_owner and project_id=p_project_id and photo_id='upload:' || p_photo_id::text;
    update public.user_interview_turn t set photo_context=coalesce((select jsonb_agg(p) from jsonb_array_elements(t.photo_context) p
      where p->>'photo_id'<>'upload:' || p_photo_id::text),'[]') where user_id=v_owner and project_id=p_project_id;
    perform public.invalidate_interview_photo_projection(v_owner,p_project_id);
  end if;
  return to_jsonb(saved)-'user_id';
end $$;

CREATE FUNCTION public.drain_lifetime_memory_obligations(p_limit integer DEFAULT 4) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare candidate record; token uuid; fence jsonb; claimed jsonb;
 processed integer:=0; failed integer:=0; busy integer:=0; deferred integer:=0;
 previous_owner text:=current_setting('request.jwt.claim.sub',true);
 previous_timeout text:=current_setting('lock_timeout');
begin
 if p_limit is null or p_limit not between 1 and 32 then raise exception 'invalid maintenance limit';end if;
 perform set_config('lock_timeout','250ms',true);
 for candidate in select o.user_id,o.conversation_id,o.project_id from public.user_lifetime_memory_obligation o
   join public.user_lifetime_conversation l on l.user_id=o.user_id and l.conversation_id=o.conversation_id and l.project_id=o.project_id
   where ((o.status in ('pending','retryable') and o.next_attempt_at<=clock_timestamp())
      or (o.status='running' and o.claim_expires_at<=clock_timestamp()))
     and not exists(select 1 from public.user_lifetime_pending_policy p where p.user_id=o.user_id and p.conversation_id=o.conversation_id)
     and not exists(select 1 from public.user_lifetime_policy_inventory_pending p where p.user_id=o.user_id and p.conversation_id=o.conversation_id)
   order by o.created_at,o.id limit p_limit
 loop
  begin
   -- Match foreground lock order before acquiring its short exclusive lease.
   perform 1 from public.user_memoir_project where user_id=candidate.user_id and project_id=candidate.project_id for update nowait;
   if not found then continue;end if;
   perform set_config('request.jwt.claim.sub',candidate.user_id::text,true);
   insert into public.user_profile(user_id,profile) values(candidate.user_id,'{}') on conflict do nothing;
   perform 1 from public.user_profile where user_id=candidate.user_id for update nowait;
   token:=gen_random_uuid();
   if not public.acquire_user_agent_turn_lease(token,30) then
    raise exception 'foreground lease busy' using errcode='55P03';
   end if;
   fence:=public.capture_lifetime_fence(candidate.conversation_id,token);
   claimed:=public.claim_lifetime_memory_obligation(fence);
   if claimed->>'status'='running' then
    begin
     perform public.complete_lifetime_memory_obligation(fence,(claimed->>'id')::uuid,(claimed->>'claim_token')::uuid);
     processed:=processed+1;
    exception when others then
     if sqlstate='55000' and sqlerrm='LIFETIME_POLICY_PENDING' then raise;end if;
     perform public.fail_lifetime_memory_obligation(fence,(claimed->>'id')::uuid,(claimed->>'claim_token')::uuid,'projection_failed');
     failed:=failed+1;
    end;
   end if;
   perform public.release_user_agent_turn_lease(token);
  exception when lock_not_available then
   busy:=busy+1;
  when object_not_in_prerequisite_state then
   if sqlerrm='LIFETIME_POLICY_PENDING' then deferred:=deferred+1;else raise;end if;
  end;
 end loop;
 perform set_config('request.jwt.claim.sub',coalesce(previous_owner,''),true);
 perform set_config('lock_timeout',previous_timeout,true);
 return jsonb_build_object('processed',processed,'failed',failed,'busy',busy,'deferred',deferred);
exception when others then
 perform set_config('request.jwt.claim.sub',coalesce(previous_owner,''),true);
 perform set_config('lock_timeout',previous_timeout,true);
 raise;
end $$;

CREATE FUNCTION public.enforce_lifetime_chosen_name() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare dependency public.user_lifetime_chosen_name%rowtype;
begin
 select * into dependency from public.user_lifetime_chosen_name where user_id=new.user_id;
 if found then
   if dependency.chosen_name is null then new.profile:=new.profile-'name';
   else new.profile:=pg_catalog.jsonb_set(new.profile,'{name}',pg_catalog.to_jsonb(dependency.chosen_name)); end if;
 end if;
 return new;
end $$;

CREATE FUNCTION public.enqueue_lifetime_reply_obligation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare identity public.user_lifetime_conversation%rowtype; project public.user_memoir_project%rowtype;
  source public.user_narrator_source%rowtype; fingerprint text;
begin
  if new.project_id is null or new.client_turn_id is null or new.kind not in ('agent','agent_greeting') then return new; end if;
  if tg_op='UPDATE' and old.project_id is not distinct from new.project_id and old.client_turn_id is not distinct from new.client_turn_id
    and old.content is not distinct from new.content then return new; end if;
  select * into identity from public.user_lifetime_conversation where user_id=new.user_id and project_id=new.project_id;
  if not found then return new; end if;
  select * into project from public.user_memoir_project where user_id=new.user_id and project_id=new.project_id;
  select * into source from public.user_narrator_source where user_id=new.user_id and project_id=new.project_id and client_turn_id=new.client_turn_id;
  fingerprint:=encode(sha256(convert_to(new.content,'UTF8')),'hex');
  update public.user_lifetime_memory_obligation set status='superseded',projection=null,claim_token=null,claim_expires_at=null,
    updated_at=clock_timestamp() where user_id=new.user_id and conversation_id=identity.conversation_id
    and kind='reply_projection' and origin_id=new.id and origin_hash is distinct from fingerprint;
  insert into public.user_lifetime_memory_obligation(user_id,conversation_id,project_id,kind,dedup_key,origin_id,origin_hash,
    source_id,source_version,policy_epoch,source_revision,execution_generation)
  values(new.user_id,identity.conversation_id,new.project_id,'reply_projection','reply:'||new.id||':'||fingerprint,new.id,fingerprint,
    source.id,source.version,project.policy_epoch,project.source_sequence,identity.execution_generation) on conflict do nothing;
  return new;
end $$;

CREATE FUNCTION public.enqueue_lifetime_source_obligation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare identity public.user_lifetime_conversation%rowtype; epoch bigint;
begin
  select * into identity from public.user_lifetime_conversation where user_id=new.user_id and project_id=new.project_id;
  if not found then return new; end if;
  if tg_op='UPDATE' and old.version=new.version and old.status=new.status then return new; end if;
  select policy_epoch into epoch from public.user_memoir_project where user_id=new.user_id and project_id=new.project_id;
  insert into public.user_lifetime_memory_obligation(user_id,conversation_id,project_id,kind,dedup_key,origin_id,
    source_id,source_version,policy_epoch,source_revision,execution_generation)
  values(new.user_id,identity.conversation_id,new.project_id,'source_projection','source:'||new.id||':'||new.version||':'||new.status,
    new.id,new.id,new.version,epoch,new.sequence,identity.execution_generation) on conflict do nothing;
  return new;
end $$;

CREATE FUNCTION public.ensure_lifetime_profile_authority(p_owner uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 insert into public.user_lifetime_profile_authority(user_id,conversation_id,field_locks)
 select c.user_id,c.conversation_id,coalesce((select jsonb_object_agg(k,case when k='name' and exists(
     select 1 from public.user_lifetime_chosen_name n where n.user_id=p_owner and n.authority='explicit') then 'manual' else 'preserved' end)
   from unnest(array['name','birth_year','birth_date_expression','birth_place','childhood_place','avatar_style']) k
   where ((p.profile->k is not null and p.profile->k<>'null'::jsonb and p.profile->>k<>'')
     or (k='name' and exists(select 1 from public.user_lifetime_chosen_name n where n.user_id=p_owner and n.authority='explicit')))
     and not(k='name' and exists(select 1 from public.user_lifetime_chosen_name n
       where n.user_id=p_owner and n.authority='generated' and n.chosen_name=p.profile->>'name'))),'{}')
 from public.user_lifetime_conversation c left join public.user_profile p on p.user_id=c.user_id
 where c.user_id=p_owner and c.product='memoir' on conflict do nothing;
end $$;

CREATE FUNCTION public.ensure_user_memoir_project(p_project_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $memoir$
begin
 if auth.uid() is null then
   raise exception 'authenticated user required' using errcode='42501';
 end if;
 if p_project_id is null or p_project_id !~ '^[A-Za-z0-9][A-Za-z0-9_-]{0,127}$' then
   raise exception 'invalid project' using errcode='22023';
 end if;
 if not public.lock_lifetime_legacy_worker_admission() then
   raise exception 'canonical conversation required' using errcode='42501';
 end if;
 insert into public.user_memoir_project(user_id,project_id)
   values(auth.uid(),p_project_id) on conflict do nothing;
end $memoir$;

CREATE FUNCTION public.fail_lifetime_memory_obligation(p_fence jsonb, p_id uuid, p_claim_token uuid, p_error_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare saved public.user_lifetime_memory_obligation%rowtype;
begin
  if p_error_code is null or p_error_code not in ('projection_failed','storage_unavailable','manifest_incomplete') then raise exception 'bounded error code required'; end if;
  select * into saved from public.user_lifetime_memory_obligation where id=p_id and user_id=auth.uid();
  if not found then raise exception 'obligation unavailable'; end if;
  perform 1 from public.user_memoir_project where user_id=auth.uid() and project_id=saved.project_id for update;
  perform public.lock_lifetime_publication(p_fence);
  select * into saved from public.user_lifetime_memory_obligation where id=p_id and user_id=auth.uid() for update;
  if saved.fence is distinct from p_fence or saved.claim_token is distinct from p_claim_token or p_claim_token is null
    or saved.status<>'running' or saved.claim_expires_at<=clock_timestamp() then raise exception 'stale obligation claim' using errcode='PT409'; end if;
  update public.user_lifetime_memory_obligation set status=case when attempts>=5 then 'failed' else 'retryable' end,
    next_attempt_at=clock_timestamp()+make_interval(secs=>least(3600,(5*power(2,attempts-1))::integer)),
    error_code=p_error_code,claim_token=null,claim_expires_at=null,updated_at=clock_timestamp() where id=p_id returning * into saved;
  return public.lifetime_obligation_record(saved);
end $$;

CREATE FUNCTION public.fail_memoir_lane(p_lane_id uuid, p_token uuid, p_error text, p_retryable boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb;
begin
 result:=public.fail_memoir_lane_before_skills(p_lane_id,p_token,p_error,p_retryable);
 if result->>'status' in ('retry','retry_required') then
   update public.user_background_skill_work set status='failed',reason='retry_required',updated_at=clock_timestamp()
   where lane_id=p_lane_id and status in ('running','completed');
 end if;
 return result;
end $$;

CREATE FUNCTION public.fail_memoir_lane_before_skills(p_lane_id uuid, p_token uuid, p_error text, p_retryable boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare lane public.user_memoir_lane%rowtype; retryable boolean;
begin
  if p_error not in ('MEMOIR_PROVIDER_UNAVAILABLE','MEMOIR_UNAVAILABLE','MEMOIR_CONFLICT','MEMOIR_REVIEW_FAILED') then
    raise exception 'invalid recoverable error code' using errcode='22023';
  end if;
  select * into lane from public.user_memoir_lane where id=p_lane_id for update;
  if not found or lane.token is null or lane.token is distinct from p_token or
      lane.run_deadline<=clock_timestamp() or lane.lease_until<=clock_timestamp() then
    return pg_catalog.jsonb_build_object('status','stale');
  end if;
  retryable:=p_retryable and lane.attempts<3;
  update public.user_memoir_lane set token=null,lease_until=null,run_deadline=null,pending=true,
    attempts=case when retryable then attempts else 3 end,error=p_error,
    available_at=clock_timestamp()+pg_catalog.make_interval(secs=>case when retryable then power(2,lane.attempts)::integer else 0 end)
    where id=p_lane_id;
  update public.user_narrator_source set processing_status='retry' where user_id=lane.user_id and project_id=lane.project_id
    and processing_status<>'succeeded' and id in(select (value->>'id')::uuid from pg_catalog.jsonb_array_elements(lane.active_manifest));
  return pg_catalog.jsonb_build_object('status',case when retryable then 'retry' else 'retry_required' end);
end $$;

CREATE FUNCTION public.fence_lifetime_draft_round_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if TG_OP='INSERT' then
   if exists(select 1 from public.user_lifetime_draft_snapshot s
       where s.user_id=new.user_id and s.project_id=new.project_id and s.round_high_water>=new.ordinal) then
     update public.user_memoir_project set draft_round_epoch=draft_round_epoch+1 where user_id=new.user_id and project_id=new.project_id;
   end if;
 elsif TG_OP='DELETE' or row(old.user_id,old.project_id,old.turn_id,old.ordinal,old.memory_id)
       is distinct from row(new.user_id,new.project_id,new.turn_id,new.ordinal,new.memory_id) then
   update public.user_memoir_project set draft_round_epoch=draft_round_epoch+1 where user_id=old.user_id and project_id=old.project_id;
   if TG_OP='UPDATE' and row(old.user_id,old.project_id) is distinct from row(new.user_id,new.project_id) then
     update public.user_memoir_project set draft_round_epoch=draft_round_epoch+1 where user_id=new.user_id and project_id=new.project_id;
   end if;
 end if;
 return null;
end $$;

CREATE FUNCTION public.finish_user_historical_news(p_project_id text, p_job_id uuid, p_result jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $memoir$
declare project public.user_memoir_project%rowtype; job public.user_historical_news_job%rowtype; c jsonb;
begin
 if auth.uid() is null then raise exception 'authenticated user required' using errcode='42501'; end if;
 select * into project from public.user_memoir_project where user_id=auth.uid() and project_id=p_project_id for update;
 select * into job from public.user_historical_news_job where user_id=auth.uid() and project_id=p_project_id and id=p_job_id for update;
 if not found or job.status<>'running' or job.expires_at<=clock_timestamp() or job.source_sequence<>project.source_sequence
   or job.context_revision is distinct from public.historical_news_revision(auth.uid(),p_project_id)
   or exists(select 1 from public.user_historical_news_state where user_id=auth.uid() and project_id=p_project_id and not enabled) then return false; end if;
 if p_result->>'status' not in ('ready','empty','unavailable') or jsonb_typeof(p_result->'clues') is distinct from 'array'
   or jsonb_array_length(p_result->'clues')>5 or octet_length(p_result::text)>50000 then raise exception 'invalid historical result'; end if;
 for c in select value from jsonb_array_elements(p_result->'clues') loop
   if jsonb_typeof(c) is distinct from 'object' or exists(select 1 from unnest(array[
      'id','title','summary','precision','place','category','source_url','source_title','publisher','excerpt','locator','retrieved_at','evidence_status']) k
      where jsonb_typeof(c->k) is distinct from 'string' or length(btrim(c->>k))=0)
      or jsonb_typeof(c->'event_start') is distinct from 'number' or jsonb_typeof(c->'event_end') is distinct from 'number'
      or jsonb_typeof(c->'receipt') is distinct from 'object' or jsonb_typeof(c->'receipt'->'urls') is distinct from 'array'
      or exists(select 1 from unnest(array['provider','response_id','tool_call_id','status']) k
         where jsonb_typeof(c->'receipt'->k) is distinct from 'string' or length(btrim(c->'receipt'->>k))=0)
      or c->>'source_url' !~ '^https?://[A-Za-z][A-Za-z0-9.-]*[.][A-Za-z]{2,}(/|$)'
      or c->>'source_url' ~* '(^https?://localhost[./]|[.]local/|[.]internal/|[.]localhost/|[?&](token|key|secret|password)=)'
      then raise exception 'malformed historical evidence' using errcode='22023'; end if;
   if c->>'id' !~ '^news-[a-f0-9]{24}$' or c->>'evidence_status' is distinct from 'inspected'
     or c->'receipt'->>'status' is distinct from 'completed' or length(coalesce(c->'receipt'->>'response_id',''))=0
     or length(coalesce(c->'receipt'->>'tool_call_id',''))=0 or not (c->'receipt'->'urls' ? (c->>'source_url'))
     or length(c->>'title')>200 or length(c->>'locator')>200 or length(c->>'retrieved_at')>40 or length(c->>'source_url')>8192
     or c->>'retrieved_at' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})$'
     or (c->>'retrieved_at')::timestamptz is null
     or (c->'publication_date' is not null and c->'publication_date'<>'null'::jsonb and
       (jsonb_typeof(c->'publication_date') is distinct from 'string' or c->>'publication_date' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
        or (c->>'publication_date')::date is null))
     or c->>'source_url' !~ '^https?://[^ /]+/' or length(coalesce(c->>'excerpt','')) not between 1 and 800
     or length(coalesce(c->>'source_title','')) not between 1 and 300 or length(coalesce(c->>'publisher','')) not between 1 and 200
     or length(coalesce(c->>'summary','')) not between 1 and 500 or position(c->>'summary' in c->>'excerpt')=0
     or concat_ws(' ',c->>'title',c->>'summary',c->>'excerpt') ~* '\m(war|battle|attack|massacre|kill(ed|ing)?|murder|assassin[[:alpha:]]*|terror[[:alpha:]]*|bomb[[:alpha:]]*|shoot[[:alpha:]]*|riot[[:alpha:]]*|violence|rape|abuse|discrimination|racis[[:alpha:]]*|slavery|genocide|election|campaign|politic[[:alpha:]]*|protest|coup|revolution|communis[[:alpha:]]*|nazi|holocaust|famine|disaster)\M|灾|战争|屠杀|杀害|袭击|枪击|炸弹|骚乱|暴力|强奸|虐待|歧视|种族|奴隶|选举|政治|抗议|政变|革命|文革|饥荒|死亡'
     or c->>'category' not in ('civic','culture','sport') or c->>'precision' not in ('year','range')
     or (c->>'event_start')::integer<(job.hypothesis->>'start')::integer or (c->>'event_end')::integer>(job.hypothesis->>'end')::integer
     or (c->>'event_start')::integer>(c->>'event_end')::integer
     or c->>'place' not in (job.hypothesis->>'place',job.hypothesis->>'country')
     then raise exception 'unsupported historical evidence' using errcode='22023'; end if;
   insert into public.user_historical_news_clue(user_id,project_id,id,context_revision,status,evidence,relevance)
   values(auth.uid(),p_project_id,c->>'id',job.context_revision,'ready',c,job.hypothesis)
   on conflict(user_id,project_id,id) do update set context_revision=excluded.context_revision,evidence=excluded.evidence,relevance=excluded.relevance
     where public.user_historical_news_clue.status='ready';
 end loop;
 update public.user_historical_news_job set status=p_result->>'status',accounting=jsonb_build_object(
 'discovery_requests',p_result->'accounting'->'discovery_requests','source_reads',p_result->'accounting'->'source_reads',
 'cache',p_result->'accounting'->'cache','cost',null,'cost_status','unavailable') where user_id=auth.uid() and project_id=p_project_id and id=p_job_id;
 return true;
end $memoir$;

CREATE FUNCTION public.finish_user_interview_photo(p_project_id text, p_photo_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare saved public.user_interview_photo%rowtype;
begin
  select * into saved from public.user_interview_photo where user_id=auth.uid() and project_id=p_project_id and id=p_photo_id for update;
  if not found or saved.status='deleted' then raise exception 'photo unavailable' using errcode='42501'; end if;
  if not exists(select 1 from storage.objects where bucket_id='memoir-private-photos' and name=saved.object_path) then
    raise exception 'photo upload incomplete' using errcode='55000'; end if;
  update public.user_interview_photo set status='ready' where user_id=auth.uid() and project_id=p_project_id and id=p_photo_id returning * into saved;
  return to_jsonb(saved)-'user_id';
end $$;

CREATE FUNCTION public.formal_memoir_digest(p_value jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 select encode(sha256(convert_to(p_value::text,'UTF8')),'hex')
$$;

CREATE FUNCTION public.formal_memoir_run_record(p_run public.user_formal_memoir_run) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 select jsonb_build_object('schema_version',1,'run_id',p_run.id,'status',p_run.state,'project_id',p_run.project_id,
  'locale',p_run.locale,'base_revision',p_run.base_revision,'phase_revision',p_run.phase_revision,
  'policy_epoch',p_run.policy_epoch,'preference_revision',p_run.preference_revision,'source_revision',p_run.source_revision,
  'event_revision',p_run.event_revision,'plan_digest',p_run.plan_digest,'chapter_count',p_run.chapter_count)
$$;

CREATE FUNCTION public.heartbeat_memoir_lane(p_lane_id uuid, p_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.user_memoir_lane set lease_until=least(run_deadline,clock_timestamp()+interval '60 seconds')
    where id=p_lane_id and token=p_token and lease_until>clock_timestamp() and run_deadline>clock_timestamp();
  return found;
end $$;

CREATE FUNCTION public.historical_news_public(p_evidence jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 select jsonb_object_agg(key,value) from jsonb_each(p_evidence) where key in
 ('id','title','summary','event_start','event_end','precision','place','source_url','source_title','publisher','publication_date')
$$;

CREATE FUNCTION public.historical_news_revision(p_owner uuid, p_project text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select p.policy_epoch::text || ':' || p.event_sequence::text || ':' || coalesce(s.revision,1)::text || ':' || p.source_sequence::text
 from public.user_memoir_project p left join public.user_historical_news_state s using(user_id,project_id)
 where p.user_id=p_owner and p.project_id=p_project
$$;

CREATE FUNCTION public.import_memoir_path(path text, guest_id uuid, owner_id uuid, relative_agent boolean DEFAULT false) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare tail text; root text;
begin
  if starts_with(path, guest_id::text || '/agent/') then
    tail := substr(path, length(guest_id::text || '/agent/') + 1);
    return owner_id::text || '/agent/' || public.import_memoir_path(tail, guest_id, owner_id, true);
  elsif starts_with(path, guest_id::text || '/attachment/') then
    return owner_id::text || '/attachment/imports/' || guest_id::text || '/' || substr(path, length(guest_id::text || '/attachment/') + 1);
  elsif relative_agent and split_part(path, '/', 1) in ('sessions', 'archived_sessions', 'memories') then
    root := split_part(path, '/', 1);
    return root || '/imports/' || guest_id::text || '/' || substr(path, length(root) + 2);
  end if;
  return path;
end;
$$;

CREATE FUNCTION public.interview_photo_available(p_owner uuid, p_project_id text, p_photo_id text, p_for_cue boolean DEFAULT false) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists(select 1 from public.user_interview_turn t, jsonb_array_elements(t.photo_context) p
    where t.user_id=p_owner and t.project_id=p_project_id and p->>'photo_id'=p_photo_id
      and (not p_for_cue or not exists(select 1 from public.user_interview_photo_link retired
        where retired.user_id=p_owner and retired.project_id=p_project_id and retired.photo_id=p_photo_id
          and retired.status='unlinked' and t.sequence<=coalesce(retired.retired_through_sequence,9223372036854775807)))
      and (t.source_id is null or exists(select 1 from public.user_narrator_source s where s.user_id=t.user_id
        and s.project_id=t.project_id and s.id=t.source_id and s.version=t.source_version and s.status='active')))
    and (p_photo_id not like 'upload:%' or exists(select 1 from public.user_interview_photo p
      where p.user_id=p_owner and p.project_id=p_project_id and 'upload:' || p.id::text=p_photo_id and p.status='ready'))
$$;

CREATE FUNCTION public.interview_photo_card(p public.user_interview_photo) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select jsonb_build_object('id',p.id,'photo_id','upload:' || p.id::text,'kind','private_upload',
    'title','Your private photo','content_type',p.content_type,'byte_size',p.byte_size,
    'content_url','/v1/agent/projects/' || p.project_id || '/photos/' || p.id::text || '/content')
$$;

CREATE FUNCTION public.interview_photo_links(p_owner uuid, p_project_id text, p_event_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(to_jsonb(l)-'user_id' order by l.id),'[]') from public.user_interview_photo_link l
    join public.user_narrator_source s on s.user_id=l.user_id and s.project_id=l.project_id and s.id=l.source_id
    where l.user_id=p_owner and l.project_id=p_project_id and l.status in ('pending','confirmed')
      and s.status='active' and s.version=l.source_version
      and (p_event_id is null or l.event_id=p_event_id and l.status='confirmed')
      and public.interview_photo_available(p_owner,p_project_id,l.photo_id)
$$;

CREATE FUNCTION public.interview_storage_operation_allowed(p_operations text[]) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $memoir$
declare allowed boolean;
begin
  if to_regprocedure('storage.allow_any_operation(text[])') is null then return false; end if;
  execute 'select storage.allow_any_operation($1)' into allowed using p_operations;
  return coalesce(allowed,false);
end $memoir$;

CREATE FUNCTION public.interview_transfer_snapshot(p_owner uuid, p_project_id text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select public.interview_transfer_snapshot_before_recordings(p_owner,p_project_id) || jsonb_build_object(
  'user_original_recording',coalesce((select jsonb_agg(to_jsonb(r) order by r.id) from public.user_original_recording r where user_id=p_owner and project_id=p_project_id),'[]'),
  'user_source_recording',coalesce((select jsonb_agg(to_jsonb(l) order by l.recording_id) from public.user_source_recording l where user_id=p_owner and project_id=p_project_id),'[]'))
$$;

CREATE FUNCTION public.interview_transfer_snapshot_before_recordings(p_owner uuid, p_project_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $memoir$
declare snapshot jsonb:='{}'; table_name text; rows jsonb;
begin
  foreach table_name in array array['user_interview_photo','user_interview_turn','user_interview_photo_link','user_interview_plan'] loop
    execute format('select coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text),''[]''::jsonb) from public.%I t where user_id=$1 and project_id=$2',table_name)
      into rows using p_owner,p_project_id;
    snapshot:=snapshot || jsonb_build_object(table_name,rows);
  end loop;
  return snapshot;
end $memoir$;

CREATE FUNCTION public.interview_turn_record(t public.user_interview_turn) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select jsonb_build_object('client_turn_id',t.client_turn_id,'sequence',t.sequence,
    'source',(select public.narrator_source_record(s) from public.user_narrator_source s
      where s.user_id=t.user_id and s.project_id=t.project_id and s.id=t.source_id),
    'source_version',t.source_version,'photo_context',case when t.source_id is null or exists(select 1 from public.user_narrator_source s
      where s.user_id=t.user_id and s.project_id=t.project_id and s.id=t.source_id and s.version=t.source_version and s.status='active')
      then coalesce((select jsonb_agg(p) from jsonb_array_elements(t.photo_context) p where p->>'kind'<>'private_upload' or
        exists(select 1 from public.user_interview_photo owned where owned.user_id=t.user_id and owned.project_id=t.project_id
          and 'upload:' || owned.id::text=p->>'photo_id' and owned.status='ready')),'[]') else '[]'::jsonb end,
    'plan',t.collector->'plan','reply',t.collector->>'reply','thread_id',t.collector->>'thread_id',
    'response_photos',coalesce(t.collector->'response_photos','[]'),
    'historical_context',t.collector->'historical_context',
    'consumed_photo_key',t.consumed_photo_key,'consumed_photo_revision',t.consumed_photo_revision,
    'photo_cue',jsonb_build_object('consumed',t.consumed_photo_key is not null or jsonb_array_length(t.photo_context)>0,
      'key',t.consumed_photo_key,'revision',t.consumed_photo_revision))
$$;

CREATE FUNCTION public.invalidate_changed_interview_evidence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare changed integer;
begin
  if old.version is distinct from new.version or old.status is distinct from new.status then
    update public.user_interview_turn set interview_guidance_snapshot=null where user_id=new.user_id and project_id=new.project_id;
    -- An event correction trigger may already have invalidated a link before
    -- this source trigger runs. Scrub those retired records too, so a later
    -- guest-transfer snapshot cannot carry the withdrawn original quote.
    update public.user_interview_photo_link set status=case when status='unlinked' then 'unlinked' else 'invalidated' end,
      description='[evidence changed]',quote='[evidence changed:' || id::text || ']'
      where user_id=new.user_id and project_id=new.project_id and source_id=new.id;
    get diagnostics changed=row_count;
    delete from public.user_interview_plan where user_id=new.user_id and project_id=new.project_id;
    if changed>0 then perform public.invalidate_interview_photo_projection(new.user_id,new.project_id); end if;
  end if;
  return new;
end $$;

CREATE FUNCTION public.invalidate_corrected_interview_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare changed integer;
begin
  if new.status<>'active' or new.data->'user_overrides' is distinct from old.data->'user_overrides' then
    update public.user_interview_photo_link set status='invalidated',description='[event changed]'
      where user_id=new.user_id and project_id=new.project_id and (event_id=new.id or intended_event_id=new.id) and status in ('pending','confirmed');
    get diagnostics changed=row_count;
    delete from public.user_interview_plan where user_id=new.user_id and project_id=new.project_id;
    if changed>0 then perform public.invalidate_interview_photo_projection(new.user_id,new.project_id); end if;
  end if;
  return new;
end $$;

CREATE FUNCTION public.invalidate_formal_memoir(p_owner uuid, p_project text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 -- The trigger owns the lifetime identity row before touching formal rows.
 -- Preference writers already hold profile -> identity and must never request
 -- project here. Other invalidators take project -> profile -> identity first.
 -- Retain metadata hashes, never stale prose; purge stays in the writer's txn.
 delete from public.user_formal_memoir_chapter c using public.user_formal_memoir_run r
   where c.run_id=r.id and r.user_id=p_owner and r.project_id=p_project;
 update public.user_formal_memoir_plan p set evidence='[]' from public.user_formal_memoir_run r
   where p.run_id=r.id and r.user_id=p_owner and r.project_id=p_project and p.evidence<>'[]'::jsonb;
 update public.user_formal_memoir_run set state='stale',token=null,lease_until=null,fence=fence+1
   where user_id=p_owner and project_id=p_project and state<>'stale';
 update public.user_formal_memoir_edition set active=false where user_id=p_owner and project_id=p_project and active;
end $$;

CREATE FUNCTION public.invalidate_formal_memoir_authority() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare changed boolean:=false; owner uuid; project text;
begin
 owner:=coalesce(new.user_id,old.user_id);project:=coalesce(new.project_id,old.project_id);
 if tg_table_name='user_memoir_project' then
   changed:=old.policy_epoch is distinct from new.policy_epoch or old.source_sequence is distinct from new.source_sequence
     or old.event_sequence is distinct from new.event_sequence;
 elsif tg_table_name='user_lifetime_conversation' then
   changed:=old.preference_revision is distinct from new.preference_revision;
 elsif tg_table_name='user_narrator_source' then
   changed:=tg_op='DELETE' or old.version is distinct from new.version or old.status is distinct from new.status or old.text is distinct from new.text;
 end if;
 if changed then
   if tg_table_name<>'user_lifetime_conversation' then
     -- Do not lock formal rows before profile/identity: a preference writer
     -- could otherwise hold profile while waiting for those formal rows.
     perform 1 from public.user_memoir_project where user_id=owner and project_id=project for update;
     perform 1 from public.user_profile where user_id=owner for share;
     perform 1 from public.user_lifetime_conversation where user_id=owner and project_id=project for share;
   end if;
   perform public.invalidate_formal_memoir(owner,project);
 end if;
 return coalesce(new,old);
end $$;

CREATE FUNCTION public.invalidate_interview_photo_projection(p_owner uuid, p_project_id text, p_retire boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.user_memoir_project set policy_epoch=policy_epoch+1 where user_id=p_owner and project_id=p_project_id;
  delete from public.user_memoir_checkpoint c using public.user_memoir_lane l where c.lane_id=l.id and l.user_id=p_owner and l.project_id=p_project_id;
  if not p_retire then
    update public.user_interview_turn t set policy_epoch=p.policy_epoch from public.user_memoir_project p
      where p.user_id=p_owner and p.project_id=p_project_id and t.user_id=p.user_id and t.project_id=p.project_id
        and t.sequence=p.interview_sequence and t.source_sequence=p.source_sequence;
  end if;
  if p_retire then
    delete from public.user_interview_plan where user_id=p_owner and project_id=p_project_id;
    update public.user_interview_turn set collector=null where user_id=p_owner and project_id=p_project_id;
  end if;
  insert into public.user_private_draft_outbox(user_id,project_id,change_kind) values(p_owner,p_project_id,'correction');
end $$;

CREATE FUNCTION public.invalidate_lifetime_chosen_name() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare dependency public.user_lifetime_chosen_name%rowtype;
begin
 if old.version is distinct from new.version or old.status is distinct from new.status then
   select * into dependency from public.user_lifetime_chosen_name where user_id=new.user_id
     and project_id=new.project_id and source_id=new.id and authority='generated';
   if found then
     update public.user_lifetime_chosen_name set authority='invalidated',chosen_name=null where user_id=new.user_id;
     update public.user_profile set profile=profile-'name' where user_id=new.user_id;
   end if;
 end if;
 return new;
end $$;

CREATE FUNCTION public.invalidate_lifetime_collection_authority() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
begin
 if tg_table_name='user_memoir_project' then
  if old.policy_epoch is distinct from new.policy_epoch then perform public.invalidate_lifetime_collection_scope(new.user_id,new.project_id);end if;
 elsif tg_table_name='user_lifetime_conversation' then
  if old.preference_revision is distinct from new.preference_revision then perform public.invalidate_lifetime_collection_scope(new.user_id,new.project_id);end if;
 elsif tg_table_name='user_lifetime_collection' then
  if old.revision is distinct from new.revision then perform public.invalidate_lifetime_collection_scope(new.user_id,new.project_id,true);end if;
 elsif tg_table_name='story_entitlement' then
  if tg_op='DELETE' or new.status is distinct from 'paid' then perform public.invalidate_lifetime_collection_scope(old.user_id,null,true);end if;
 elsif tg_table_name='users' then
  if old.is_anonymous is distinct from new.is_anonymous and new.is_anonymous then perform public.invalidate_lifetime_collection_scope(new.id,null,true);end if;
 end if;
 return coalesce(new,old);
end $$;

CREATE FUNCTION public.invalidate_lifetime_collection_scope(p_owner uuid, p_project text, p_outline_only boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
begin
 update public.user_lifetime_collection_job set state='STALE',token=null,lease_until=null,error='SOURCE_OR_COLLECTION_CHANGED'
  where user_id=p_owner and (p_project is null or project_id=p_project) and (not p_outline_only or kind='BuildOutline');
 delete from public.user_lifetime_collection_job_edge where job_id in (select id from public.user_lifetime_collection_job
  where user_id=p_owner and (p_project is null or project_id=p_project) and (not p_outline_only or kind='BuildOutline'));
 delete from public.user_lifetime_collection_job_node where job_id in (select id from public.user_lifetime_collection_job
  where user_id=p_owner and (p_project is null or project_id=p_project) and (not p_outline_only or kind='BuildOutline'));
 delete from public.user_lifetime_collection_job_cursor where job_id in (select id from public.user_lifetime_collection_job
  where user_id=p_owner and (p_project is null or project_id=p_project) and (not p_outline_only or kind='BuildOutline'));
end $$;

CREATE FUNCTION public.invalidate_lifetime_lane_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
begin
 if tg_op='DELETE' or new.status='withdrawn' then
   delete from public.user_lifetime_memoir_section where user_id=old.user_id and project_id=old.project_id and event_id=old.id;
 elsif old.revision is distinct from new.revision or old.status is distinct from new.status then
   -- Ordinary evidence additions do not revoke protected original prose.
   -- Policy-invalidated projections are discarded; the source trigger below
   -- independently covers source mutations before their policy epoch advances.
   delete from public.user_lifetime_memoir_section section using public.user_lifetime_lane_snapshot root,public.user_memoir_project project
     where section.snapshot_id=root.id and section.user_id=old.user_id and section.project_id=old.project_id and section.event_id=old.id
       and project.user_id=old.user_id and project.project_id=old.project_id and root.policy_epoch<>project.policy_epoch;
 end if;
 return coalesce(new,old);
end $$;

CREATE FUNCTION public.invalidate_lifetime_lane_fences() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
begin
 update public.user_interview_turn set interview_guidance_snapshot=null where user_id=new.user_id and project_id=new.project_id;
 if tg_table_name='user_memoir_project' then
  if old.policy_epoch is distinct from new.policy_epoch then
   update public.user_lifetime_lane_snapshot set state='stale' where user_id=new.user_id and project_id=new.project_id and state='pending';
   -- Phase requests can also contain bounded source-backed pinned continuity.
   -- Unknown derived dependencies are conservatively discarded on any fence change.
   delete from public.user_memoir_checkpoint c using public.user_memoir_lane l
     where c.lane_id=l.id and l.user_id=new.user_id and l.project_id=new.project_id and c.lifetime_snapshot_id is not null;
  end if;
 elsif tg_table_name='user_lifetime_conversation' then
  if old.preference_revision is distinct from new.preference_revision then
   update public.user_lifetime_lane_snapshot set state='stale' where user_id=new.user_id and conversation_id=new.conversation_id and state='pending';
   delete from public.user_memoir_checkpoint c using public.user_memoir_lane l
     where c.lane_id=l.id and l.user_id=new.user_id and l.project_id=new.project_id and c.lifetime_snapshot_id is not null;
  end if;
 end if;
 return new;
end $$;

CREATE FUNCTION public.invalidate_lifetime_lane_photo() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $memoir$
declare section public.user_lifetime_memoir_section%rowtype; original_text text;
 original_depends boolean; proposal_depends boolean;
begin
 if tg_op='INSERT' then return new;end if;
 if tg_op='UPDATE' and old is not distinct from new then return new;end if;
 select text into original_text from public.user_narrator_source where user_id=old.user_id
  and project_id=old.project_id and id=old.source_id and version=old.source_version;
 for section in select s.* from public.user_lifetime_memoir_section s
  where s.user_id=old.user_id and s.project_id=old.project_id
   and (s.event_id=old.event_id or s.event_dependencies @> jsonb_build_array(jsonb_build_object('id',old.event_id)))
   and ((s.partition_key not like 'progressive:%' and right(s.partition_key,37)=':'||old.id::text)
    or (old.status='confirmed' and old.provenance='narrator_metadata' and
     jsonb_path_exists(jsonb_build_array(s.bundle,s.proposal),
      '$.** ? (@.type == "image" && @.asset_id == $asset)',jsonb_build_object('asset',old.photo_id))))
  for update loop
  if section.partition_key not like 'progressive:%' and right(section.partition_key,37)=':'||old.id::text then
   delete from public.user_lifetime_memoir_section where user_id=section.user_id and project_id=section.project_id
    and locale=section.locale and partition_key=section.partition_key and snapshot_id=section.snapshot_id;
   continue;
  end if;
  select coalesce(bool_or(kind='original'),false),coalesce(bool_or(kind='proposal'),false)
   into original_depends,proposal_depends
   from (values ('original',section.bundle),('proposal',section.proposal)) bodies(kind,body),
    lateral jsonb_path_query(body,'$.** ? (@.type == "image" && exists(@.asset_id))') image,
    lateral jsonb_array_elements(coalesce(image->'source_refs','[]'::jsonb)) ref
   where image->>'asset_id'=old.photo_id and ref->>'source_id'=old.source_id::text
    and ref->>'version'=old.source_version::text
    and strpos(substring(original_text from (ref->>'char_start')::integer+1
      for (ref->>'char_end')::integer-(ref->>'char_start')::integer),old.quote)>0;
  if original_depends then
   delete from public.user_lifetime_memoir_section where user_id=section.user_id and project_id=section.project_id
    and locale=section.locale and partition_key=section.partition_key and snapshot_id=section.snapshot_id;
  elsif proposal_depends then
   -- A proposal-only image cannot revoke the independently eligible original.
   update public.user_lifetime_memoir_section set proposal=null where user_id=section.user_id and project_id=section.project_id
    and locale=section.locale and partition_key=section.partition_key and snapshot_id=section.snapshot_id;
  end if;
 end loop;
 return coalesce(new,old);
end $memoir$;

CREATE FUNCTION public.invalidate_lifetime_lane_source() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
begin
 if tg_op='DELETE' or old.version is distinct from new.version or old.status is distinct from new.status then
   delete from public.user_lifetime_memoir_section where user_id=old.user_id and project_id=old.project_id and source_id=old.id;
 end if;
 return coalesce(new,old);
end $$;

CREATE FUNCTION public.invalidate_lifetime_obligations() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.policy_epoch is distinct from new.policy_epoch then
    update public.user_lifetime_memory_obligation set status='superseded',projection=null,claim_token=null,claim_expires_at=null,
      updated_at=clock_timestamp() where user_id=new.user_id and project_id=new.project_id and policy_epoch<>new.policy_epoch;
    delete from public.user_lifetime_artifact_head h using public.user_lifetime_conversation l
      where h.user_id=l.user_id and h.conversation_id=l.conversation_id and l.user_id=new.user_id and l.project_id=new.project_id;
    update public.user_lifetime_optional_artifact a set linked=false,manifest_wire=null from public.user_lifetime_conversation l
      where a.user_id=l.user_id and a.conversation_id=l.conversation_id and l.user_id=new.user_id and l.project_id=new.project_id;
  end if;
  return new;
end $$;

CREATE FUNCTION public.invalidate_lifetime_profile_evidence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner uuid; project text; fields text[]; k text;
begin
 owner:=old.user_id;project:=old.project_id;
 if tg_table_name='user_narrator_source' then
   if tg_op='UPDATE' and old.version=new.version and old.status=new.status then return new;end if;
   select array_agg(distinct d.field) into fields from public.user_lifetime_profile_dependency d
   where d.user_id=owner and d.project_id=project and d.source_id=old.id;
 else
   if old.policy_epoch=new.policy_epoch then return new;end if;
   -- A source edit also advances policy before revising its source row. Its
   -- source trigger below revokes only the affected fields, preserving others.
   if old.source_sequence<>new.source_sequence then return new;end if;
   -- Privacy changes revoke derived facts immediately. Explicit UI facts have
   -- no source dependencies and remain independent of conversation policy.
   select array_agg(distinct d.field) into fields from public.user_lifetime_profile_dependency d
   where d.user_id=owner and d.project_id=project;
 end if;
 if fields is not null then
   foreach k in array fields loop
     if k='name' then update public.user_lifetime_chosen_name set chosen_name=null,authority='invalidated'
       where user_id=owner and authority='generated';end if;
   end loop;
   delete from public.user_lifetime_profile_dependency d where d.user_id=owner and d.field=any(fields);
   update public.user_lifetime_profile_authority set invalidated_fields=(select array_agg(distinct f)
     from unnest(invalidated_fields||fields) f) where user_id=owner;
   update public.user_profile p set profile=p.profile-fields where p.user_id=owner;
 end if;
 return coalesce(new,old);
end $$;

CREATE FUNCTION public.invalidate_lifetime_profile_privacy() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner uuid:=coalesce(new.user_id,old.user_id); fields text[];
begin
 if not((tg_op<>'INSERT' and old.kind in ('excluded_topic','paused_topic'))
   or (tg_op<>'DELETE' and new.kind in ('excluded_topic','paused_topic'))) then return coalesce(new,old);end if;
 if tg_op='UPDATE' and old.kind=new.kind and old.data=new.data then return new;end if;
 select array_agg(distinct d.field) into fields from public.user_lifetime_profile_dependency d
 join public.user_lifetime_conversation c on c.user_id=d.user_id and c.project_id=d.project_id
 where d.user_id=owner and c.conversation_id=coalesce(new.conversation_id,old.conversation_id);
 if fields is not null then
   update public.user_lifetime_chosen_name set authority='invalidated',chosen_name=null
     where user_id=owner and authority='generated' and 'name'=any(fields);
   delete from public.user_lifetime_profile_dependency d where d.user_id=owner and d.field=any(fields);
   update public.user_lifetime_profile_authority set invalidated_fields=(select array_agg(distinct f)
     from unnest(invalidated_fields||fields) f) where user_id=owner;
   update public.user_profile p set profile=p.profile-fields where p.user_id=owner;
 end if;
 return coalesce(new,old);
end $$;

CREATE FUNCTION public.invalidate_lifetime_projections() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.policy_epoch is distinct from new.policy_epoch then
    update public.user_lifetime_conversation set execution_generation=execution_generation+1,
      thread_id=null,thread_policy_epoch=null,thread_schema_version=null,thread_prompt_version=null,thread_model=null
      where user_id=new.user_id and project_id=new.project_id;
    -- Preserve independently supported typed state; erase invalid dependencies.
    delete from public.user_lifetime_continuity c using public.user_lifetime_conversation l
      where c.user_id=l.user_id and c.conversation_id=l.conversation_id
        and l.user_id=new.user_id and l.project_id=new.project_id and exists(
          select 1 from jsonb_array_elements(c.data->'source_refs') ref where not exists(
            select 1 from public.user_narrator_source s where s.user_id=new.user_id and s.project_id=new.project_id
              and s.id=(ref->>'source_id')::uuid and s.version=(ref->>'version')::bigint and s.status='active'));
    update public.user_lifetime_continuity c set policy_epoch=new.policy_epoch from public.user_lifetime_conversation l
      where c.user_id=l.user_id and c.conversation_id=l.conversation_id and l.user_id=new.user_id and l.project_id=new.project_id;
  end if;
  return new;
end $$;

CREATE FUNCTION public.invalidate_memory_attribution_source() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if old.version=new.version and old.status=new.status then return new;end if;
 delete from public.user_memory_attribution_window where user_id=old.user_id and project_id=old.project_id and source_id=old.id;
 delete from public.user_memory_event_place where user_id=old.user_id and project_id=old.project_id and source_id=old.id;
 delete from public.user_memory_delivered_context where user_id=old.user_id and project_id=old.project_id and source_id=old.id;
 delete from public.user_memory_reply_context where user_id=old.user_id and project_id=old.project_id and source_id=old.id;
 update public.user_memoir_project set attribution_revision=attribution_revision+1 where user_id=old.user_id and project_id=old.project_id;
 return new;
end $$;

CREATE FUNCTION public.invalidate_progressive_originals() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
begin
 if tg_op='UPDATE' and old is not distinct from new then return new;end if;
 if tg_table_name='user_narrator_source' then
  if tg_op='UPDATE' and new.version=old.version and new.status=old.status then return new;end if;
  delete from public.user_lifetime_memoir_section where user_id=old.user_id and project_id=old.project_id
    and source_dependencies @> jsonb_build_array(jsonb_build_object('id',old.id,'version',old.version));
 else
  if tg_op='UPDATE' and new.status=old.status then return new;end if;
  delete from public.user_lifetime_memoir_section where user_id=old.user_id and project_id=old.project_id
    and event_dependencies @> jsonb_build_array(jsonb_build_object('id',old.id,'revision',old.revision));
 end if;
 return coalesce(new,old);
end $$;

CREATE FUNCTION public.invalidate_workspace_rework() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
begin
 if tg_table_name='user_narrator_source' then
   if old.version is distinct from new.version or old.status is distinct from new.status then
     delete from public.user_workspace_section_rework where user_id=old.user_id and project_id=old.project_id and source_id=old.id;
   end if;
 elsif tg_table_name='user_memory_event' then
   if tg_op='DELETE' or old.revision is distinct from new.revision or old.status is distinct from new.status then
     delete from public.user_workspace_section_rework where user_id=old.user_id and project_id=old.project_id and event_id=old.id;
   end if;
 elsif tg_table_name='user_interview_photo_link' then
   if tg_op='UPDATE' and old is not distinct from new then return new;end if;
   if tg_op<>'INSERT' then
     -- The composer partition ends in its exact photo-link UUID. Retire its
     -- request in the same transaction as the prose, before completion can
     -- requeue an editorial task whose partition no longer exists.
     delete from public.user_workspace_section_rework where user_id=old.user_id and project_id=old.project_id
       and event_id=old.event_id and right(partition_key,37)=':'||old.id::text;
   end if;
   if tg_op<>'DELETE' and new.event_id is not null then
     -- Confirmation of the first qualifying photo removes its source-only
     -- partition. Keep other evidence spans and existing sibling photo tasks.
     delete from public.user_workspace_section_rework request where user_id=new.user_id and project_id=new.project_id
       and event_id=new.event_id and status='pending'
       and not public.workspace_rework_partition_current(request.user_id,request.project_id,request.event_id,request.partition_key);
   end if;
 end if;
 return coalesce(new,old);
end $$;

CREATE FUNCTION public.lifetime_attribution_decision(p_text text, p_name text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $memoir$
declare words text:=lower(btrim(regexp_replace(p_text,'[[:space:].!?。！？]+$','','g')));
begin
 if words in ('do not record this','don''t record this','do not record this event','不要记录这件事','这件事不要记下来') then
   return jsonb_build_object('schema_version',1,'decision','withheld','reason','privacy_withheld');
 end if;
 if words in ('hello','hi','thank you','thanks','你好','您好','谢谢','多谢','please stop','stop','pause',
   'skip','next question','please continue','go on','暂停','停一下','跳过','继续','下一个问题','what can you do','你能做什么') then
   return jsonb_build_object('schema_version',1,'decision','non_story','reason','conversation_control');
 end if;
 if words in ('yes','no','okay','ok','是','是的','对','嗯','好','there','then','那里','那时') then
   return jsonb_build_object('schema_version',1,'decision','unresolved','reason','ambiguous_context');
 end if;
 if p_name is not null and p_name !~* '([0-9.,;!?。！？，；]|\m(and|but|when|was|born|lived|grew|moved|worked|remember|I)\M|出生|小时候|长大|住在|但是|然后)'
   and (words=lower('my name is '||p_name) or words=lower('i am '||p_name)
   or words='我叫'||lower(p_name) or words='我的名字是'||lower(p_name)) then
   return jsonb_build_object('schema_version',1,'decision','non_story','reason','profile_introduction');
 end if;
 return jsonb_build_object('schema_version',1,'decision','extract','reason','new_testimony');
end $memoir$;

CREATE FUNCTION public.lifetime_attribution_event_context(p_owner uuid, p_project text, p_event text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 with conflicts as materialized (select public.lifetime_event_place_conflicts(p_owner,p_project,p_event) roles)
 select jsonb_build_object('id',e.id,'revision',e.revision,'life_stage',e.life_stage,
   'attribution',e.data->'attribution','uncertainty',e.data->'uncertainty',
   'temporal',jsonb_build_object('expression',e.data->'temporal'->'expression','precision',e.data->'temporal'->'precision',
     'year_start',e.data->'temporal'->'year_start','year_end',e.data->'temporal'->'year_end'),
   'places',coalesce((select jsonb_agg(to_jsonb(p)-array['user_id','project_id','event_id']) from
     (select * from public.lifetime_event_place_rows(p_owner,p_project,p_event) where not(role=any(conflicts.roles))
       order by source_id,char_start,role,place_key limit 2) p),'[]'),
   'place_conflicts',conflicts.roles,
   'places_complete',cardinality(conflicts.roles)=0 and
     (select count(*)<=2 from (select 1 from public.lifetime_event_place_rows(p_owner,p_project,p_event) limit 3) p),
   'places_retrieval','/v1/story/events/'||p_project||'/'||p_event||'/places')
 from public.user_memory_event e cross join conflicts
 where e.user_id=p_owner and e.project_id=p_project and e.id=p_event and e.status='active'
$$;

CREATE FUNCTION public.lifetime_collection_root_section(p_job_id uuid, p_page integer) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
 with recursive ancestry(node_id,section_number,depth) as (
  select id,1,0 from public.user_lifetime_collection_job_node where job_id=p_job_id and ordinal=p_page
  union all
  select e.parent_node,e.parent_section,a.depth+1 from ancestry a join public.user_lifetime_collection_job_edge e
   on e.job_id=p_job_id and e.child_node=a.node_id and e.child_section=a.section_number where a.depth<64
 ) select node_id::text||':'||section_number::text from ancestry order by depth desc limit 1;
$$;

CREATE FUNCTION public.lifetime_composer_source(p_owner uuid, p_project text, p_source uuid, p_version bigint, p_lo integer, p_hi integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare s public.user_narrator_source%rowtype;
begin
 select * into s from public.user_narrator_source where user_id=p_owner and project_id=p_project and id=p_source and version=p_version and status='active';
 if not found or p_lo<0 or p_hi<=p_lo or p_hi>length(s.text) or p_hi-p_lo>2304 then raise exception 'invalid progressive source window' using errcode='22023';end if;
 return jsonb_build_object('id',s.id,'project_id',s.project_id,'version',s.version,'sequence',s.sequence,
  'text',substring(s.text from p_lo+1 for p_hi-p_lo),'char_start',p_lo,'char_end',p_hi,'original_length',length(s.text),
  'kind',s.kind,'language',s.language,'status',s.status,'author_role','storyteller');
end $$;

CREATE FUNCTION public.lifetime_event_place_conflicts(p_owner uuid, p_project text, p_event text) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select coalesce(array_agg(role order by role),'{}'::text[]) from (
   select role from public.lifetime_event_place_rows(p_owner,p_project,p_event)
   group by role having min(place_key)<>max(place_key)
 ) conflicts
$$;

CREATE FUNCTION public.lifetime_event_place_rows(p_owner uuid, p_project text, p_event text) RETURNS SETOF public.user_memory_event_place
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select p.* from public.user_memory_event_place p join public.user_narrator_source s
   on s.user_id=p.user_id and s.project_id=p.project_id and s.id=p.source_id and s.version=p.source_version and s.status='active'
 join public.user_memory_event e on e.user_id=p.user_id and e.project_id=p.project_id and e.id=p.event_id and e.status='active'
 where p.user_id=p_owner and p.project_id=p_project and p.event_id=p_event
   and coalesce((e.data->>'locationConfidenceScore')::numeric,1)>=0.85
   and exists(select 1 from public.user_memory_event_source r where r.user_id=p.user_id and r.project_id=p.project_id
     and r.event_id=p.event_id and r.source_id=p.source_id and r.source_version=p.source_version
     and (r.stage_progress_role='primary' or coalesce((e.data->>'locationConfidenceScore')::numeric,0)>=0.85
       and coalesce(e.data->'location_basis','[]') @> jsonb_build_array(r.evidence))
     and (r.evidence->>'char_start')::integer<=p.char_start and (r.evidence->>'char_end')::integer>=p.char_end)
   and not exists(select 1 from public.user_memory_event_source_exclusion x where x.user_id=p.user_id
     and x.project_id=p.project_id and x.event_id=p.event_id and x.source_id=p.source_id)
$$;

CREATE FUNCTION public.lifetime_narrator_birth_basis(p_owner uuid, p_project text, p_ref jsonb) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select coalesce((select lower(coalesce(p_ref->>'attribution','narrator')) in ('narrator','storyteller','self','我','本人')
   and p_ref->>'quote' ~* '^(actually[,[:space:]]+)?(I[[:space:]]+(was[[:space:]]+)?born|my[[:space:]]+(birth year|year of birth)|我(是|于|在)?[0-9]{4}年?(出生|生于)|我(是)?(出生|生于))'
   and btrim(regexp_replace(left(s.text,coalesce((p_ref->>'char_start')::integer,strpos(s.text,p_ref->>'quote')-1)),
     E'^.*[.!?。！？\n]','','s'))=''
 from public.user_narrator_source s where s.user_id=p_owner and s.project_id=p_project and s.id::text=p_ref->>'source_id'
   and s.version::text=p_ref->>'version' and s.status='active'),false)
$$;

CREATE FUNCTION public.lifetime_narrator_word_equivalents(p_kind text, p_content text) RETURNS bigint
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $memoir$
declare narrator text; boundary integer; instruction text; cut integer; han text; total bigint;
begin
 if p_kind<>'agent' or p_content not like 'Storyteller: %' then return 0;end if;
 boundary:=strpos(substring(p_content from 14),E'\nMemory Spark: ');
 if boundary=0 or length(btrim(substring(substring(p_content from 14) from boundary+15)))=0 then return 0;end if;
 narrator:=substring(substring(p_content from 14) from 1 for boundary-1);
 if narrator like 'The storyteller said: %' then
   cut:=length(narrator)+1;
   foreach instruction in array array[
     'This is the storyteller''s first answer to the shared profile-intake opening.',
     'Acknowledge the storyteller naturally, then ask one gentle open-ended follow-up question.',
     'Acknowledge the storyteller briefly, then ask one gentle follow-up question about their memory.'] loop
     boundary:=strpos(narrator,E'\n'||instruction);
     if boundary>0 then cut:=least(cut,boundary);end if;
   end loop;
   if cut<=length(narrator) then narrator:=substring(narrator from 23 for cut-23);end if;
 end if;
 han:='[㐀-䶿一-鿿𠀀-𯨟]';
 select count(*) into total from pg_catalog.regexp_matches(narrator,han,'g');
