CREATE FUNCTION public.lifetime_obligation_origin_current(o public.user_lifetime_memory_obligation) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select (o.source_id is null or exists(select 1 from public.user_narrator_source s where s.user_id=o.user_id
   and s.project_id=o.project_id and s.id=o.source_id and s.version=o.source_version
   and (o.kind='source_projection' or s.status='active')))
 and (o.kind='source_projection' or exists(select 1 from public.user_memory m where m.user_id=o.user_id
   and m.project_id=o.project_id and m.id=o.origin_id and pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(m.content,'UTF8')),'hex')=o.origin_hash))
$$;

CREATE FUNCTION public.lifetime_obligation_record(o public.user_lifetime_memory_obligation) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 select pg_catalog.to_jsonb(o)-'user_id'-'origin_hash' || pg_catalog.jsonb_build_object('schema_version',1,'required',true,'backup_complete',false)
$$;

CREATE FUNCTION public.lifetime_profile_automation(p_owner uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select jsonb_build_object('schema_version',1,'revision',a.revision,'auto_enabled',a.auto_enabled,
   'stopped',not a.auto_enabled or a.manual_complete,'manual_complete',a.manual_complete,'field_locks',a.field_locks)
 from public.user_lifetime_profile_authority a where a.user_id=p_owner
$$;

CREATE FUNCTION public.lifetime_profile_due_round(p_round bigint) RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select greatest(coalesce((select max(r) from unnest(c.initial_rounds) r where r<=p_round),0),
   (greatest(p_round,0)/c.interval_rounds)*c.interval_rounds)
 from public.lifetime_profile_cadence c where singleton
$$;

CREATE FUNCTION public.lifetime_source_attribution_rows(p_owner uuid, p_project text, p_source uuid) RETURNS TABLE(char_start integer, char_end integer, disposition text, reason text, event_id text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $memoir$
 with source as materialized (
   select * from public.user_narrator_source where user_id=p_owner and project_id=p_project and id=p_source and status='active'
 ), windows as materialized (
   select w.* from public.user_memory_attribution_window w join source s on w.source_id=s.id and w.source_version=s.version
   -- Author corrections also advance the project epoch. Passage decisions belong
   -- to the original version; current policy is fenced at read/admission time.
   where w.user_id=p_owner and w.project_id=p_project
 ), links as materialized (
   select distinct (r.evidence->>'char_start')::integer lo,(r.evidence->>'char_end')::integer hi,e.id
   from source s join public.user_memory_event_source r on r.user_id=s.user_id and r.project_id=s.project_id
     and r.source_id=s.id and r.source_version=s.version
   join public.user_memory_event e on e.user_id=r.user_id and e.project_id=r.project_id and e.id=r.event_id and e.status='active'
   where r.stage_progress_role in ('primary','legacy_primary')
     and r.evidence->>'char_start' ~ '^[0-9]+$' and r.evidence->>'char_end' ~ '^[0-9]+$'
     and (r.evidence->>'char_end')::integer<=(select length(text) from source)
     and substring(s.text from (r.evidence->>'char_start')::integer+1 for
       (r.evidence->>'char_end')::integer-(r.evidence->>'char_start')::integer)=r.evidence->>'quote'
     and not exists(select 1 from public.user_memory_event_source_exclusion x where x.user_id=r.user_id
       and x.project_id=r.project_id and x.event_id=r.event_id and x.source_id=r.source_id)
 ), boundaries as (
   select 0 n union select length(text) from source
   union select char_start from windows union select char_end from windows
   union select lo from links union select hi from links
 ), segments as (select n lo,lead(n) over(order by n) hi from boundaries), classified as (
   select g.lo,g.hi,l.id,
     case when w.disposition='withheld' then 'withheld' when l.id is not null then 'linked'
       when w.disposition is not null then w.disposition
       when (select processing_status from source)='succeeded' then 'unresolved' else 'pending' end status,
     case when w.disposition='withheld' then w.reason when l.id is not null then 'direct_evidence'
       when w.reason is not null then w.reason
       when (select processing_status from source)='succeeded' then 'legacy_unresolved' else 'awaiting_reconciliation' end why
   from segments g left join links l on l.lo<=g.lo and l.hi>=g.hi
   left join lateral (select * from windows w where w.char_start<=g.lo and w.char_end>=g.hi
     order by (w.disposition='withheld') desc,w.char_end-w.char_start limit 1) w on true
   where g.hi>g.lo
 ) select distinct lo,hi,status,why,case when status='linked' then id else null end from classified
$memoir$;

CREATE FUNCTION public.lifetime_source_attribution_summary(p_owner uuid, p_project text, p_source uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select jsonb_build_object('source_id',p_source,'complete',coalesce(bool_and(disposition<>'pending'),false),
   'resolved',coalesce(bool_and(disposition in ('linked','non_story')),false),
   'pending_passages',count(*) filter(where disposition='pending'),
   'unresolved_passages',count(*) filter(where disposition='unresolved'),
   'linked_passages',count(*) filter(where disposition='linked'),
   'non_story_passages',count(*) filter(where disposition='non_story'),
   'withheld_passages',count(*) filter(where disposition='withheld'),
   'retrieval','/v1/story/sources/'||p_project||'/'||p_source||'/attribution')
 from (select distinct char_start,char_end,disposition from public.lifetime_source_attribution_rows(p_owner,p_project,p_source)) passages
$$;

-- Match the reply renderer's Python str.strip(); preserve internal whitespace and evidence.
CREATE FUNCTION public.lifetime_question_text(p_question text) RETURNS text
    LANGUAGE sql IMMUTABLE SET search_path TO '' AS $$
 select btrim(p_question, U&'\0009\000A\000B\000C\000D\001C\001D\001E\001F\0020\0085\00A0' ||
   U&'\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000')
$$;

CREATE FUNCTION public.lifetime_question_hint(p_source jsonb, p_hint jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE SET search_path TO '' AS $$
declare lo integer; hi integer; base integer:=coalesce((p_source->>'char_start')::integer,0);
 text text:=p_source->>'text'; quote text:=p_hint->>'quote'; position integer;
begin
 if jsonb_typeof(p_hint) is distinct from 'object'
   or exists(select 1 from jsonb_object_keys(p_hint) k where k not in ('question','topic','quote','requires_confirmation','char_start','char_end','scope'))
   or (p_hint ? 'scope' and coalesce(p_hint->>'scope','') not in ('detail','broader'))
   or (p_hint ? 'requires_confirmation' and jsonb_typeof(p_hint->'requires_confirmation') is distinct from 'boolean')
   or jsonb_typeof(p_hint->'question') is distinct from 'string' or length(p_hint->>'question') not between 1 and 800
   or length(public.lifetime_question_text(p_hint->>'question'))=0
   or jsonb_typeof(p_hint->'topic') is distinct from 'string' or length(p_hint->>'topic') not between 1 and 120
   or jsonb_typeof(p_hint->'quote') is distinct from 'string' or length(quote) not between 1 and 500
   or strpos(text,quote)=0 or length(regexp_replace(p_hint->>'question','[^?？]','','g'))>1 then
   raise exception 'grounded question hints required' using errcode='22023';end if;
 if coalesce(p_hint->'char_start','null')='null' and coalesce(p_hint->'char_end','null')='null' then
   position:=strpos(text,quote);
   if strpos(substring(text from position+1),quote)>0 then
     raise exception 'ambiguous question evidence requires exact offsets' using errcode='22023';end if;
   lo:=base+position-1;hi:=lo+length(quote);
 else
   if jsonb_typeof(p_hint->'char_start') is distinct from 'number' or jsonb_typeof(p_hint->'char_end') is distinct from 'number' then
     raise exception 'typed question evidence offsets required' using errcode='22023';end if;
   lo:=(p_hint->>'char_start')::integer;hi:=(p_hint->>'char_end')::integer;
   if lo<base or hi>base+length(text) or hi-lo<>length(quote)
     or substring(text from lo-base+1 for hi-lo) is distinct from quote then
     raise exception 'question evidence span must match the referenced passage' using errcode='22023';end if;
 end if;
 return p_hint||jsonb_build_object('char_start',lo,'char_end',hi);
end $$;

CREATE FUNCTION public.lifetime_question_id(p_source uuid, p_version bigint, p_hint jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE SET search_path TO '' AS $$
 select 'bq-'||encode(sha256(convert_to(jsonb_build_array(p_source,p_version,lower(public.lifetime_question_text(p_hint->>'question')),
   p_hint->'char_start',p_hint->'char_end',p_hint->>'quote')::text,'UTF8')),'hex')
$$;

-- Delivery owns asking; exact evidence owns identity, never wording or the delivery turn.
CREATE FUNCTION public.lifetime_delivered_questions(p_owner uuid, p_project text)
RETURNS TABLE(source_id uuid, source_version bigint, client_turn_id uuid, reply_id uuid,
              turn_sequence bigint, question_id text, question text, evidence jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select d.source_id,d.source_version,d.client_turn_id,d.reply_id,t.sequence,q->>'id',q->>'question',q->'context'->'evidence'
 from public.user_memory_delivered_context d
 join public.user_interview_turn t on t.user_id=d.user_id and t.project_id=d.project_id
   and t.client_turn_id=d.client_turn_id and t.source_id=d.source_id and t.source_version=d.source_version
 join public.user_narrator_source s on s.user_id=d.user_id and s.project_id=d.project_id
   and s.id=d.source_id and s.version=d.source_version and s.status='active'
 join public.user_lifetime_conversation c on c.user_id=d.user_id and c.project_id=d.project_id
   and c.execution_generation=d.execution_generation and c.preference_revision=d.preference_revision
 join public.user_memoir_project p on p.user_id=d.user_id and p.project_id=d.project_id and p.policy_epoch=d.policy_epoch
 join public.user_lifetime_reply r on r.user_id=d.user_id and r.conversation_id=c.conversation_id
   and r.client_turn_id=d.client_turn_id and r.memory_id=d.reply_id and r.policy_epoch=d.policy_epoch
   and r.execution_generation=d.execution_generation and r.preference_revision=d.preference_revision
 cross join lateral jsonb_array_elements(coalesce(t.collector->'plan'->'candidates','[]')) q
 where d.user_id=p_owner and d.project_id=p_project and q->>'id'=t.collector->'plan'->>'chosen_id'
   and length(public.lifetime_question_text(coalesce(q->>'question','')))>0
   and strpos(t.collector->>'reply',public.lifetime_question_text(q->>'question'))>0
$$;

CREATE FUNCTION public.lifetime_question_dialogue(p_owner uuid, p_project text, p_source uuid DEFAULT NULL::uuid,
                                                p_through_sequence bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select coalesce(jsonb_agg(item order by turn_sequence),'[]') from (
   select q.turn_sequence,jsonb_build_object('status',case when answer.id is null then 'asked' else 'responded' end,
     'question',jsonb_build_object('id',q.question_id,'text',q.question,'role','assistant','personal_testimony',false,
       'client_turn_id',q.client_turn_id,'reply_id',q.reply_id,'sequence',q.turn_sequence,'delivered',true,
       'source_id',q.source_id,'source_version',q.source_version,'evidence',q.evidence),
     'response',case when answer.id is null then null else jsonb_build_object('id',answer.id,'version',answer.version,
       'sequence',answer.sequence,'text',left(answer.text,512),'role','user','kind',answer.kind,
       'char_start',0,'char_end',least(length(answer.text),512),'complete',length(answer.text)<=512) end) item
   from public.lifetime_delivered_questions(p_owner,p_project) q
   join public.user_narrator_source question_source on question_source.user_id=p_owner and question_source.project_id=p_project
     and question_source.id=q.source_id and (p_through_sequence is null or question_source.sequence<=p_through_sequence)
   left join lateral (
     select s.* from public.user_memory_reply_context link
     join public.user_narrator_source s on s.user_id=link.user_id and s.project_id=link.project_id
       and s.id=link.source_id and s.version=link.source_version and s.status='active'
     where link.user_id=p_owner and link.project_id=p_project and link.prior_source_id=q.source_id
       and (p_through_sequence is null or s.sequence<=p_through_sequence)
     order by s.sequence limit 1
   ) answer on true
   where p_source is null or q.source_id=p_source or answer.id=p_source
   order by q.turn_sequence desc limit 8
 ) bounded
$$;

CREATE FUNCTION public.lifetime_resolved_questions(p_owner uuid, p_project text) RETURNS TABLE(question_id text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select distinct resolution->>'question_id'
 from public.user_interview_turn t
 join public.user_narrator_source original on original.user_id=t.user_id and original.project_id=t.project_id
   and original.id=t.source_id and original.version=t.source_version and original.status='active'
 join public.user_lifetime_conversation c on c.user_id=t.user_id and c.project_id=t.project_id
 join public.user_memoir_project p on p.user_id=t.user_id and p.project_id=t.project_id
 join public.user_lifetime_reply r on r.user_id=t.user_id and r.conversation_id=c.conversation_id
   and r.client_turn_id=t.client_turn_id and r.policy_epoch=p.policy_epoch
   and r.execution_generation=c.execution_generation and r.preference_revision=c.preference_revision
 cross join lateral jsonb_array_elements(coalesce(t.collector->'plan'->'resolved_questions','[]')) resolution
 join public.user_narrator_source answer on answer.user_id=t.user_id and answer.project_id=t.project_id
   and answer.id=(resolution->>'source_id')::uuid and answer.version=(resolution->>'source_version')::bigint
   and answer.status='active'
 where t.user_id=p_owner and t.project_id=p_project
$$;

CREATE FUNCTION public.lifetime_deferred_questions(p_owner uuid, p_project text) RETURNS TABLE(question_id text)
    LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO '' AS $$
 select distinct deferral->>'question_id'
 from public.user_interview_turn t
 join public.user_narrator_source original on original.user_id=t.user_id and original.project_id=t.project_id
   and original.id=t.source_id and original.version=t.source_version and original.status='active'
 join public.user_lifetime_conversation c on c.user_id=t.user_id and c.project_id=t.project_id
 join public.user_memoir_project p on p.user_id=t.user_id and p.project_id=t.project_id
 join public.user_lifetime_reply r on r.user_id=t.user_id and r.conversation_id=c.conversation_id
   and r.client_turn_id=t.client_turn_id and r.policy_epoch=p.policy_epoch
   and r.execution_generation=c.execution_generation and r.preference_revision=c.preference_revision
 cross join lateral jsonb_array_elements(coalesce(t.collector->'plan'->'deferred_questions','[]')) deferral
 join public.user_narrator_source evidence on evidence.user_id=t.user_id and evidence.project_id=t.project_id
   and evidence.id=(deferral->>'source_id')::uuid and evidence.version=(deferral->>'source_version')::bigint
   and evidence.status='active'
 where t.user_id=p_owner and t.project_id=p_project
$$;
revoke all on function public.lifetime_deferred_questions(uuid,text) from public,anon,authenticated,service_role;

CREATE FUNCTION public.lifetime_consumed_question_ids(p_owner uuid, p_project text) RETURNS TABLE(question_id text)
    LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO '' AS $$
 with delivered as materialized (select * from public.lifetime_delivered_questions(p_owner,p_project))
 select question_id from delivered
 union
 select public.lifetime_question_id(original.id,original.version,jsonb_build_object('question',d.question,
   'quote',d.evidence->>'quote','char_start',d.evidence->'char_start','char_end',d.evidence->'char_end'))
 from delivered d join public.user_narrator_source original on original.user_id=p_owner and original.project_id=p_project
   and original.id=(d.evidence->>'source_id')::uuid and original.version=(d.evidence->>'version')::bigint and original.status='active'
 where d.evidence->>'char_start' is not null and d.evidence->>'char_end' is not null
 union select question_id from public.lifetime_resolved_questions(p_owner,p_project)
 union select question_id from public.lifetime_deferred_questions(p_owner,p_project)
$$;

CREATE FUNCTION public.prune_lifetime_question_pool(p_owner uuid, p_project text, p_source uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
 with consumed as materialized (select * from public.lifetime_consumed_question_ids(p_owner,p_project))
 update public.user_lifetime_prepared_question pool set questions=(
   select coalesce(jsonb_agg(q order by position),'[]')
   from jsonb_array_elements(pool.questions) with ordinality pending(q,position)
   where not exists(select 1 from consumed
     where consumed.question_id=public.lifetime_question_id(pool.source_id,pool.source_version,q)))
 where pool.user_id=p_owner and pool.project_id=p_project and pool.questions<>'[]'::jsonb
   and (p_source is null or pool.source_id=p_source);
 with consumed as materialized (select * from public.lifetime_consumed_question_ids(p_owner,p_project))
 update public.user_lifetime_interview_strategy pool set data=jsonb_set(data,'{candidates}',(
   select coalesce(jsonb_agg(q order by position),'[]')
   from jsonb_array_elements(pool.data->'candidates') with ordinality pending(q,position)
   where not exists(select 1 from consumed where consumed.question_id=q->>'id')))
 where pool.user_id=p_owner and pool.project_id=p_project and not pool.shadow and pool.data->'candidates'<>'[]'::jsonb
   and (p_source is null or pool.source_id=p_source)
$$;

CREATE FUNCTION public.lifetime_source_context(p_owner uuid, p_project text, p_source uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select public.lifetime_attribution_event_context(p_owner,p_project,e.id)||jsonb_build_object('association','context_only',
   'reply_id',d.reply_id,'source_id',d.source_id,'source_version',d.source_version)
 from public.user_memory_reply_context c join public.user_narrator_source s
   on s.user_id=c.user_id and s.project_id=c.project_id and s.id=c.source_id and s.version=c.source_version and s.status='active'
 join public.user_memory_delivered_context d on d.user_id=c.user_id and d.project_id=c.project_id and d.source_id=c.prior_source_id
 join public.user_narrator_source prior on prior.user_id=d.user_id and prior.project_id=d.project_id
   and prior.id=d.source_id and prior.version=d.source_version and prior.status='active'
 join public.user_memory_event e on e.user_id=d.user_id and e.project_id=d.project_id and e.id=d.event_id and e.revision=d.event_revision and e.status='active'
 join public.user_memoir_project p on p.user_id=c.user_id and p.project_id=c.project_id and p.policy_epoch=d.policy_epoch
 join public.user_lifetime_conversation i on i.user_id=c.user_id and i.project_id=c.project_id
   and i.execution_generation=d.execution_generation and i.preference_revision=d.preference_revision
 where c.user_id=p_owner and c.project_id=p_project and c.source_id=p_source
$$;

CREATE FUNCTION public.link_lifetime_optional_artifact(p_fence jsonb, p_manifest_id text, p_manifest text DEFAULT NULL::text, p_authorized boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $memoir$
declare owner uuid:=auth.uid(); conversation uuid:=(p_fence->'identity'->>'conversation_id')::uuid; project text;
  manifest jsonb; file jsonb; chunk jsonb; artifact_path text; head text; covered_bytes bigint;
  saved public.user_lifetime_optional_artifact%rowtype;
begin
  if p_authorized is distinct from true then raise exception 'explicit optional artifact authorization required'; end if;
  select project_id into project from public.user_lifetime_conversation where user_id=owner and conversation_id=conversation;
  if not found then raise exception 'conversation unavailable'; end if;
  perform 1 from public.user_memoir_project where user_id=owner and project_id=project for update;
  perform public.lock_lifetime_publication(p_fence);
  if p_manifest_id is null or p_manifest_id!~'^[a-f0-9]{64}$' then raise exception 'invalid manifest digest'; end if;
  select manifest_id into head from public.user_lifetime_artifact_head where user_id=owner and conversation_id=conversation;
  select * into saved from public.user_lifetime_optional_artifact where user_id=owner and conversation_id=conversation and manifest_id=p_manifest_id;
  if p_manifest is null then
    if not found or head is distinct from p_manifest_id or not saved.linked or saved.fence->'identity' is distinct from p_fence->'identity'
      or saved.fence->'policy_epoch' is distinct from p_fence->'policy_epoch'
      or saved.fence->'execution_generation' is distinct from p_fence->'execution_generation' then raise exception 'accepted authorized artifact predecessor required'; end if;
    update public.user_lifetime_optional_artifact set fence=p_fence where user_id=owner and conversation_id=conversation and manifest_id=p_manifest_id;
  else
    if octet_length(p_manifest)>1048576 or encode(sha256(convert_to(p_manifest,'UTF8')),'hex') is distinct from p_manifest_id then raise exception 'manifest size or digest mismatch'; end if;
    manifest:=p_manifest::jsonb;
    if jsonb_typeof(manifest) is distinct from 'object' or exists(select 1 from jsonb_object_keys(manifest) k where k not in
      ('schema_version','owner_id','conversation_id','policy_epoch','execution_generation','snapshot_semantics','files','removed_paths','omissions','complete','canonical_recovery_required','status','predecessor'))
      or not (manifest ?& array['schema_version','owner_id','conversation_id','policy_epoch','execution_generation','snapshot_semantics','files','removed_paths','omissions','complete','canonical_recovery_required','status','predecessor'])
      or manifest->'schema_version' is distinct from '3'::jsonb or manifest->>'owner_id' is distinct from owner::text
      or manifest->>'conversation_id' is distinct from conversation::text or manifest->'policy_epoch' is distinct from p_fence->'policy_epoch'
      or manifest->'execution_generation' is distinct from p_fence->'execution_generation'
      or manifest->>'snapshot_semantics' is distinct from 'full_authorized_snapshot'
      or manifest->>'status' is distinct from 'unlinked_candidate' or manifest->'canonical_recovery_required' is distinct from 'false'::jsonb
      or jsonb_typeof(manifest->'complete') is distinct from 'boolean' or jsonb_typeof(manifest->'files') is distinct from 'array'
      or jsonb_typeof(manifest->'removed_paths') is distinct from 'array' or jsonb_typeof(manifest->'omissions') is distinct from 'array' then raise exception 'invalid artifact envelope'; end if;
    if jsonb_array_length(manifest->'files')>256 or jsonb_array_length(manifest->'removed_paths')>256 or jsonb_array_length(manifest->'omissions')>257
      or (manifest->'complete'='true'::jsonb and jsonb_array_length(manifest->'omissions')>0) then raise exception 'bounded honest artifact manifest required'; end if;
    if manifest->>'predecessor' is not null and not exists(select 1 from public.user_lifetime_optional_artifact a
      where a.user_id=owner and a.conversation_id=conversation and a.manifest_id=manifest->>'predecessor' and a.linked
      and a.fence->'identity'=p_fence->'identity' and a.fence->'policy_epoch'=p_fence->'policy_epoch'
      and a.fence->'execution_generation'=p_fence->'execution_generation') then
      raise exception 'accepted current artifact predecessor required'; end if;
    if (select count(*)<>count(distinct value->>'path') from jsonb_array_elements(manifest->'files'))
      or (select count(*)<>count(distinct value) from jsonb_array_elements(manifest->'removed_paths'))
      or exists(select 1 from jsonb_array_elements(manifest->'files') f where manifest->'removed_paths' @> jsonb_build_array(f->>'path')) then
      raise exception 'duplicate or conflicting artifact paths';
    end if;
    for file in select value from jsonb_array_elements(manifest->'files') loop
      if jsonb_typeof(file) is distinct from 'object' or exists(select 1 from jsonb_object_keys(file) k where k not in ('path','bytes','chunks'))
        or jsonb_typeof(file->'path') is distinct from 'string' or jsonb_typeof(file->'bytes') is distinct from 'number'
        or coalesce(file->>'bytes','')!~'^[0-9]+$' or (file->>'bytes')::bigint>134217728
        or jsonb_typeof(file->'chunks') is distinct from 'array' then raise exception 'invalid artifact file'; end if;
      artifact_path:=file->>'path';
      if artifact_path !~ '^(sessions|archived_sessions)/[^/]' or artifact_path ~ '(^|/)\.' or length(artifact_path)>1024 or jsonb_array_length(file->'chunks')>131072 then raise exception 'unsafe or unbounded artifact file'; end if;
      if (select count(*)<>count(distinct value->'offset') from jsonb_array_elements(file->'chunks')) then raise exception 'duplicate artifact chunk offset'; end if;
      for chunk in select value from jsonb_array_elements(file->'chunks') loop
        if jsonb_typeof(chunk) is distinct from 'object' or exists(select 1 from jsonb_object_keys(chunk) k where k not in ('key','sha256','offset','bytes'))
          or jsonb_typeof(chunk->'key') is distinct from 'string' or coalesce(chunk->>'key','') !~ ('^'||owner::text||'/agent/chunks/v1/[a-f0-9]{64}$')
          or jsonb_typeof(chunk->'sha256') is distinct from 'string' or coalesce(chunk->>'sha256','')!~'^[a-f0-9]{64}$'
          or jsonb_typeof(chunk->'offset') is distinct from 'number' or coalesce(chunk->>'offset','')!~'^[0-9]+$'
          or jsonb_typeof(chunk->'bytes') is distinct from 'number' or coalesce(chunk->>'bytes','')!~'^[1-9][0-9]*$'
          or (chunk->>'bytes')::bigint>1048576 or (chunk->>'offset')::bigint+(chunk->>'bytes')::bigint>(file->>'bytes')::bigint then raise exception 'invalid tenant artifact chunk'; end if;
      end loop;
    end loop;
    for file in select value from jsonb_array_elements(manifest->'removed_paths') loop
      if jsonb_typeof(file) is distinct from 'string' or file#>>'{}' !~ '^(sessions|archived_sessions)/[^/]' or file#>>'{}' ~ '(^|/)\.' or length(file#>>'{}')>1024 then raise exception 'unsafe removed artifact path'; end if;
    end loop;
    for file in select value from jsonb_array_elements(manifest->'omissions') loop
      if jsonb_typeof(file) is distinct from 'object' or exists(select 1 from jsonb_object_keys(file) k where k not in ('index','reason'))
        or jsonb_typeof(file->'index') is distinct from 'number' or coalesce(file->>'index','')!~'^[0-9]+$'
        or (file->>'index')::bigint>256 or coalesce(file->>'reason','') not in ('job_file_limit','unprovenanced','unsafe_path','duplicate_path','file_resource_limit','job_resource_limit') then raise exception 'invalid omission'; end if;
    end loop;
    if saved.manifest_id is not null and (saved.fence->'identity' is distinct from p_fence->'identity'
      or saved.fence->'policy_epoch' is distinct from p_fence->'policy_epoch'
      or saved.fence->'execution_generation' is distinct from p_fence->'execution_generation'
      or saved.manifest_wire is distinct from p_manifest or not saved.linked) then raise exception 'artifact identity conflict'; end if;
    if saved.manifest_id is not null and head is distinct from p_manifest_id then
      raise exception 'historical artifact replay cannot replace current head';
    end if;
    -- An exact retry of the current head reuses its already validated state.
    -- A delta cannot branch from a historical snapshot into the mutable head.
    if head is distinct from p_manifest_id then
      if manifest->>'predecessor' is not null and head is distinct from manifest->>'predecessor' then
        raise exception 'artifact delta must extend current head';
      end if;
      if manifest->>'predecessor' is null then
        delete from public.user_lifetime_artifact_head where user_id=owner and conversation_id=conversation;
        insert into public.user_lifetime_artifact_head values(owner,conversation,p_manifest_id);
      end if;
      delete from public.user_lifetime_artifact_file f where f.user_id=owner and f.conversation_id=conversation
        and manifest->'removed_paths' @> jsonb_build_array(f.path);
      for file in select value from jsonb_array_elements(manifest->'files') loop
        artifact_path:=file->>'path';
        insert into public.user_lifetime_artifact_file(user_id,conversation_id,path,byte_count)
          values(owner,conversation,artifact_path,(file->>'bytes')::bigint)
          on conflict(user_id,conversation_id,path) do update set byte_count=excluded.byte_count;
        -- Drop a truncated suffix and replace only explicitly changed offsets.
        -- A retained partial chunk must be replaced; it may never be clipped
        -- silently because its hash names the original, longer content object.
        delete from public.user_lifetime_artifact_chunk c where c.user_id=owner and c.conversation_id=conversation and c.path=artifact_path
          and (c.chunk_offset>=(file->>'bytes')::bigint or exists(select 1 from jsonb_array_elements(file->'chunks') changed
            where (changed->>'offset')::bigint=c.chunk_offset));
        insert into public.user_lifetime_artifact_chunk(user_id,conversation_id,path,chunk_offset,byte_count,object_key,content_sha256)
          select owner,conversation,artifact_path,(value->>'offset')::bigint,(value->>'bytes')::bigint,value->>'key',value->>'sha256'
          from jsonb_array_elements(file->'chunks');
        select coalesce(sum(c.byte_count),0) into covered_bytes from public.user_lifetime_artifact_chunk c
          where c.user_id=owner and c.conversation_id=conversation and c.path=artifact_path;
        if covered_bytes<>(file->>'bytes')::bigint or exists(
          select 1 from (select chunk_offset,coalesce(sum(c.byte_count) over(order by chunk_offset rows between unbounded preceding and 1 preceding),0) expected_offset
            from public.user_lifetime_artifact_chunk c where c.user_id=owner and c.conversation_id=conversation and c.path=artifact_path) checked
          where chunk_offset<>expected_offset) then raise exception 'incomplete or overlapping effective artifact coverage'; end if;
      end loop;
      if (select count(*)>256 or coalesce(sum(byte_count),0)>268435456 from public.user_lifetime_artifact_file where user_id=owner and conversation_id=conversation)
        or (select count(*)>131072 from public.user_lifetime_artifact_chunk where user_id=owner and conversation_id=conversation) then
        raise exception 'effective artifact resource bound exceeded';
      end if;
      update public.user_lifetime_artifact_head set manifest_id=p_manifest_id where user_id=owner and conversation_id=conversation;
    end if;
    insert into public.user_lifetime_optional_artifact(user_id,conversation_id,manifest_id,fence,manifest_wire,complete)
      values(owner,conversation,p_manifest_id,p_fence,p_manifest,(manifest->>'complete')::boolean)
      on conflict(user_id,conversation_id,manifest_id) do update set fence=excluded.fence;
    select * into saved from public.user_lifetime_optional_artifact where user_id=owner and conversation_id=conversation and manifest_id=p_manifest_id;
  end if;
  return jsonb_build_object('schema_version',1,'manifest_id',saved.manifest_id,'optional',true,'manifest_complete',saved.complete,
    'backup_complete',false,'canonical_recovery_required',false,'status','linked');
end $memoir$;

CREATE FUNCTION public.lock_formal_memoir_context(p_owner uuid, p_project text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare project public.user_memoir_project%rowtype; identity public.user_lifetime_conversation%rowtype;
 pins jsonb; old_owner text;
begin
 select * into project from public.user_memoir_project where user_id=p_owner and project_id=p_project for update;
 if not found then raise exception 'FORMAL_PROJECT_UNAVAILABLE' using errcode='42501';end if;
 perform 1 from public.user_profile where user_id=p_owner for share;
 select * into identity from public.user_lifetime_conversation where user_id=p_owner and project_id=p_project for share;
 if not found or exists(select 1 from auth.users where id=p_owner and is_anonymous) then
   raise exception 'FORMAL_OWNER_REQUIRED' using errcode='42501';end if;
 perform public.require_lifetime_policy_ready(p_owner,p_project);
 old_owner:=current_setting('request.jwt.claim.sub',true);
 perform set_config('request.jwt.claim.sub',p_owner::text,true);
 pins:=public.read_lifetime_pinned(identity.conversation_id);
 perform set_config('request.jwt.claim.sub',coalesce(old_owner,''),true);
 if (pins->>'privacy_complete')::boolean is distinct from true
   or jsonb_array_length(pins->'excluded_topics')>0 or jsonb_array_length(pins->'paused_topics')>0 then
   raise exception 'FORMAL_PRIVACY_REVIEW_REQUIRED' using errcode='55000';end if;
 return jsonb_build_object('conversation_id',identity.conversation_id,'locale',pins->>'language',
   'phase_revision',0,'policy_epoch',project.policy_epoch,'preference_revision',identity.preference_revision,
   'source_revision',project.source_sequence,'event_revision',project.event_sequence);
end $$;

CREATE FUNCTION public.lock_formal_memoir_run(p_run_id uuid, p_token uuid DEFAULT NULL::uuid, p_require_token boolean DEFAULT true) RETURNS public.user_formal_memoir_run
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare run public.user_formal_memoir_run%rowtype; context jsonb; key text;
begin
 select * into run from public.user_formal_memoir_run where id=p_run_id;
 if not found then raise exception 'FORMAL_RUN_UNAVAILABLE' using errcode='42501';end if;
 context:=public.lock_formal_memoir_context(run.user_id,run.project_id);
 select * into run from public.user_formal_memoir_run where id=p_run_id for update;
 if run.state='stale' then raise exception 'FORMAL_AUTHORITY_STALE' using errcode='PT409';end if;
 foreach key in array array['conversation_id','locale','phase_revision','policy_epoch','preference_revision','source_revision','event_revision'] loop
   if to_jsonb(run)->key is distinct from context->key then raise exception 'FORMAL_AUTHORITY_STALE' using errcode='PT409';end if;
 end loop;
 if run.state='completed' and not exists(select 1 from public.user_formal_memoir_edition e
   join public.user_formal_memoir_head h on h.user_id=e.user_id and h.project_id=e.project_id and h.edition_id=e.id
   where e.run_id=run.id and e.active) then
   raise exception 'FORMAL_EDITION_STALE' using errcode='PT409';end if;
 if p_require_token and (p_token is null or run.token is distinct from p_token or run.state<>'running' or run.lease_until<=clock_timestamp()) then
   raise exception 'FORMAL_LEASE_STALE' using errcode='PT409';end if;
 return run;
end $$;

CREATE FUNCTION public.lock_lifetime_collection_job(p_job_id uuid, p_token uuid DEFAULT NULL::uuid) RETURNS public.user_lifetime_collection_job
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare job public.user_lifetime_collection_job%rowtype;
begin
 job:=public.lock_lifetime_collection_job_scope(p_job_id,p_token);
 perform public.require_lifetime_policy_ready(job.user_id,job.project_id);
 return job;
end $$;

CREATE FUNCTION public.lock_lifetime_collection_job_scope(p_job_id uuid, p_token uuid DEFAULT NULL::uuid) RETURNS public.user_lifetime_collection_job
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare job public.user_lifetime_collection_job%rowtype; project public.user_memoir_project%rowtype;
 identity public.user_lifetime_conversation%rowtype; doc public.user_lifetime_collection%rowtype;
begin
 select * into job from public.user_lifetime_collection_job where id=p_job_id;
 if not found then raise exception 'collection job unavailable' using errcode='42501';end if;
 if job.kind='BuildOutline' then
  perform 1 from auth.users where id=job.user_id and not is_anonymous for share;
  if not found then raise exception 'paid memoir entitlement required' using errcode='42501';end if;
 end if;
 select * into project from public.user_memoir_project where user_id=job.user_id and project_id=job.project_id for share;
 perform 1 from public.user_profile where user_id=job.user_id for share;
 if not found then perform pg_advisory_xact_lock_shared(hashtextextended('memoir-profile:'||job.user_id::text,0));end if;
 select * into identity from public.user_lifetime_conversation where user_id=job.user_id and project_id=job.project_id for share;
 select * into doc from public.user_lifetime_collection where user_id=job.user_id and project_id=job.project_id for share;
 if job.kind='BuildOutline' then
  perform 1 from public.story_entitlement where user_id=job.user_id and status='paid' for share;
  if not found then raise exception 'paid memoir entitlement required' using errcode='42501';end if;
 end if;
 select * into job from public.user_lifetime_collection_job where id=p_job_id for update;
 if identity.conversation_id is distinct from job.conversation_id or project.policy_epoch is distinct from job.policy_epoch
  or identity.preference_revision is distinct from job.preference_revision or (job.kind='BuildOutline' and coalesce(doc.revision,0)<>job.collection_revision)
  or job.state='STALE' or (p_token is not null and (job.token is distinct from p_token or job.lease_until<=clock_timestamp() or job.state<>'RUNNING')) then
  raise exception 'stale collection job' using errcode='PT409';end if;
 if exists(select 1 from public.user_lifetime_collection_job_source j left join public.user_narrator_source s
  on s.id=j.source_id and s.user_id=job.user_id and s.project_id=job.project_id
  where j.job_id=job.id and (s.id is null or s.version<>j.source_version or s.status<>'active'
   or s.kind not in ('narrator_chat','narrator_transcript') or length(s.text)<>j.original_length)) then
  raise exception 'stale collection source manifest' using errcode='PT409';end if;
 if job.kind='BuildOutline' then
  if not coalesce(doc.ready,false) or doc.policy_epoch<>job.policy_epoch or doc.preference_revision<>job.preference_revision then
   raise exception 'collection confirmation changed' using errcode='PT409';end if;
 end if;
 return job;
end $$;

CREATE FUNCTION public.lock_lifetime_collection_job_publication(p_fence jsonb) RETURNS double precision
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare current_page jsonb; remaining double precision;
begin
 if jsonb_typeof(p_fence) is distinct from 'object' or (p_fence->>'user_id')::uuid is distinct from auth.uid() then
  raise exception 'collection publication owner mismatch' using errcode='42501';end if;
 current_page:=public.read_lifetime_collection_job_page((p_fence->>'job_id')::uuid,(p_fence->>'token')::uuid);
 if current_page-'complete' is distinct from p_fence or current_page->>'complete'<>'false' then
  raise exception 'stale collection publication' using errcode='PT409';end if;
 select extract(epoch from lease_until-clock_timestamp()) into remaining from public.user_lifetime_collection_job where id=(p_fence->>'job_id')::uuid;
 return remaining;
end $$;

CREATE FUNCTION public.lock_lifetime_collection_result_publication(p_fence jsonb, p_job_id uuid, p_root_digest text) RETURNS double precision
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare remaining double precision; job public.user_lifetime_collection_job%rowtype;
begin
 -- One transaction: the account lock precedes generic project/profile reads,
 -- matching guest attachment's existing auth-user -> project/profile order.
 select * into job from public.user_lifetime_collection_job where id=p_job_id and user_id=auth.uid();
 if not found or job.project_id is distinct from p_fence->'identity'->>'project_id' then raise exception 'collection result owner mismatch' using errcode='42501';end if;
 if job.kind='BuildOutline' then perform 1 from auth.users where id=job.user_id for share;end if;
 remaining:=public.lock_lifetime_read_publication(p_fence);
 job:=public.lock_lifetime_collection_job(job.id);
 if job.root_digest is distinct from p_root_digest then raise exception 'collection result changed' using errcode='PT409';end if;
 return remaining;
end $$;

CREATE FUNCTION public.lock_lifetime_legacy_worker_admission() RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 raise exception 'canonical execution required' using errcode='42501';
end $$;

CREATE FUNCTION public.lock_lifetime_memoir_lane(p_lane_id uuid, p_token uuid) RETURNS public.user_lifetime_lane_snapshot
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare snapshot public.user_lifetime_lane_snapshot%rowtype;
begin
 snapshot:=public.lock_lifetime_memoir_lane_scope(p_lane_id,p_token);
 perform public.require_lifetime_policy_ready(snapshot.user_id,snapshot.project_id);
 return snapshot;
end $$;

CREATE FUNCTION public.lock_lifetime_memoir_lane_scope(p_lane_id uuid, p_token uuid) RETURNS public.user_lifetime_lane_snapshot
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare lane public.user_memoir_lane%rowtype; snapshot public.user_lifetime_lane_snapshot%rowtype;
 identity public.user_lifetime_conversation%rowtype; project public.user_memoir_project%rowtype;
begin
 select * into lane from public.user_memoir_lane where id=p_lane_id;
 if not found then raise exception 'canonical lane unavailable' using errcode='PT409';end if;
 select * into project from public.user_memoir_project where user_id=lane.user_id and project_id=lane.project_id for update;
 perform 1 from public.user_profile where user_id=lane.user_id for share;
 select * into identity from public.user_lifetime_conversation where user_id=lane.user_id and project_id=lane.project_id for share;
 select * into lane from public.user_memoir_lane where id=p_lane_id for update;
 select * into snapshot from public.user_lifetime_lane_snapshot where lane_id=lane.id and state='pending' order by created_at desc limit 1 for update;
 if snapshot.id is null or lane.token is null or lane.token is distinct from p_token or lane.lease_until<=clock_timestamp()
   or lane.run_deadline<=clock_timestamp() or snapshot.policy_epoch<>project.policy_epoch
   or snapshot.preference_revision<>identity.preference_revision or snapshot.locale<>lane.active_locale
   or (lane.skill='composer' and snapshot.event_high_water<>project.event_sequence) then
   raise exception 'stale canonical lane page' using errcode='PT409';
 end if;
 return snapshot;
end $$;

CREATE FUNCTION public.lock_lifetime_memoir_lane_publication(p_fence jsonb) RETURNS double precision
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare remaining double precision; page jsonb;
begin
 remaining:=public.lock_lifetime_memoir_lane_publication_before_attribution(p_fence);
 if p_fence ? 'profile_context' then return remaining;end if;
 page:=public.read_lifetime_memoir_lane_page((p_fence->>'lane_id')::uuid,(p_fence->>'token')::uuid);
 if coalesce(p_fence->'guidance_context','null') is distinct from coalesce(page->'guidance_context','null') then
   raise exception 'guidance context changed' using errcode='40001';end if;
 if coalesce(p_fence->'timeline_context','null') is distinct from coalesce(page->'timeline_context','null') then
   raise exception 'timeline context changed' using errcode='40001';end if;
 if coalesce(p_fence->'attribution_context','null') is distinct from coalesce(page->'attribution_context','null')
   or coalesce(p_fence->'attribution_coverage','null') is distinct from coalesce(page->'attribution_coverage','null') then
   raise exception 'attribution context changed' using errcode='40001';end if;
 return remaining;
end $$;

CREATE FUNCTION public.lock_lifetime_memoir_lane_publication_before_attribution(p_fence jsonb) RETURNS double precision
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare page jsonb; k text; lane public.user_memoir_lane%rowtype;
begin
 if p_fence->'profile_context' is null or p_fence->'profile_context'='null'::jsonb then
   return public.lock_lifetime_memoir_lane_publication_before_background_profile(p_fence);
 end if;
 if octet_length(p_fence::text)>65536 or auth.uid() is null or auth.uid()::text is distinct from p_fence->>'user_id' then
   raise exception 'canonical profile owner required' using errcode='42501';end if;
 perform 1 from public.lifetime_two_lane_rollout where singleton and enabled for share;
 if not found then raise exception 'profile rollout disabled' using errcode='PT409';end if;
 page:=public.read_lifetime_profile_page((p_fence->>'lane_id')::uuid,(p_fence->>'token')::uuid);
 if page is null or page->'preferences'->'privacy_complete' is distinct from 'true'::jsonb
   or page->'profile_context'->>'work_mode'<>'extract' then
   raise exception 'profile admission deferred or stopped' using errcode='PT409';end if;
 foreach k in array array['schema_version','protocol','lane_id','token','snapshot_id','user_id','project_id','conversation_id',
   'skill','locale','policy_epoch','preference_revision','source_high_water','event_high_water','page_number','root_digest',
   'page_digest','input_digest','preferences','source','partition','events','coverage_round','base_revision',
   'profile_context','two_lane','batch','memory_summary','editorial_request'] loop
   if coalesce(p_fence->k,'null'::jsonb) is distinct from coalesce(page->k,'null'::jsonb) then
     raise exception 'stale canonical profile admission' using errcode='40001';end if;
 end loop;
 if p_fence->'prior_outputs' is distinct from '[]'::jsonb then
   raise exception 'profile cannot reuse timeline outputs' using errcode='22023';end if;
 select * into lane from public.user_memoir_lane where id=(p_fence->>'lane_id')::uuid;
 return greatest(0,extract(epoch from least(lane.lease_until,lane.run_deadline)-clock_timestamp()));
end $$;

CREATE FUNCTION public.lock_lifetime_memoir_lane_publication_before_background_profile(p_fence jsonb) RETURNS double precision
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare remaining double precision; page jsonb;
begin
 remaining:=public.lock_lifetime_memoir_lane_publication_before_semantic(p_fence);
 if exists(select 1 from public.lifetime_two_lane_rollout where singleton and enabled) then
   page:=public.read_lifetime_memoir_lane_page((p_fence->>'lane_id')::uuid,(p_fence->>'token')::uuid);
   if coalesce(p_fence->'memory_summary','null') is distinct from coalesce(page->'memory_summary','null') then
     raise exception 'summary admission differs from canonical page' using errcode='PT409';end if;
 end if;
 return remaining;
end $$;

CREATE FUNCTION public.lock_lifetime_memoir_lane_publication_before_batches(p_fence jsonb) RETURNS double precision
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare remaining double precision; page jsonb;
begin
 remaining:=public.lock_lifetime_memoir_lane_publication_before_rework(p_fence);
 page:=public.read_lifetime_memoir_lane_page((p_fence->>'lane_id')::uuid,(p_fence->>'token')::uuid);
 if coalesce(p_fence->'editorial_request','null'::jsonb) is distinct from page->'editorial_request' then
   raise exception 'revision instruction changed' using errcode='PT409';end if;
 return remaining;
end $$;

CREATE FUNCTION public.lock_lifetime_memoir_lane_publication_before_rework(p_fence jsonb) RETURNS double precision
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare current_page jsonb; field text; proof jsonb; lane public.user_memoir_lane%rowtype;
begin
 if octet_length(p_fence::text)>(case when p_fence ? 'timeline_context' then 98304 else 65536 end) then
   raise exception 'bounded lane fence required';end if;
 if auth.uid() is null or auth.uid()::text is distinct from p_fence->>'user_id' then raise exception 'canonical lane owner mismatch' using errcode='42501';end if;
 current_page:=public.read_lifetime_memoir_lane_page((p_fence->>'lane_id')::uuid,(p_fence->>'token')::uuid);
 if (current_page->'preferences'->>'privacy_complete')::boolean is distinct from true then raise exception 'current privacy requires maintenance';end if;
 foreach field in array array['schema_version','protocol','lane_id','token','snapshot_id','user_id','project_id','conversation_id',
   'skill','locale','policy_epoch','preference_revision','source_high_water','event_high_water','page_number','root_digest','page_digest','input_digest','preferences','source','partition','events','coverage_round'] loop
   if p_fence->field is null or p_fence->field is distinct from current_page->field then
     raise exception 'stale canonical lane admission' using errcode='PT409';end if;
 end loop;
 if jsonb_typeof(p_fence->'prior_outputs') is distinct from 'array' or jsonb_array_length(p_fence->'prior_outputs')>16 then raise exception 'bounded prior output proofs required';end if;
 for proof in select value from jsonb_array_elements(p_fence->'prior_outputs') loop
   if not exists(select 1 from public.user_lifetime_lane_output where snapshot_id=(current_page->>'snapshot_id')::uuid
      and page_number=(current_page->>'page_number')::bigint and phase=proof->>'phase' and digest=proof->>'digest'
      and input_digest=(current_page->>'input_digest')) then
     raise exception 'derived lane output belongs to another page' using errcode='PT409';end if;
 end loop;
 select * into lane from public.user_memoir_lane where id=(p_fence->>'lane_id')::uuid;
 return greatest(0,extract(epoch from least(lane.lease_until,lane.run_deadline)-clock_timestamp()));
end $$;

CREATE FUNCTION public.lock_lifetime_memoir_lane_publication_before_semantic(p_fence jsonb) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare page jsonb;remaining numeric;
begin
 page:=public.read_lifetime_memoir_lane_page((p_fence->>'lane_id')::uuid,(p_fence->>'token')::uuid);
 if coalesce(p_fence->'batch','null'::jsonb) is distinct from coalesce(page->'batch','null'::jsonb)
   or coalesce((p_fence->>'base_revision')::bigint,0) is distinct from (page->>'base_revision')::bigint then
  raise exception 'stale progressive authority' using errcode='PT409';end if;
 remaining:=public.lock_lifetime_memoir_lane_publication_before_batches(p_fence);
 return remaining;
end $$;

CREATE FUNCTION public.lock_lifetime_policy_profile() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if old.policy_epoch is distinct from new.policy_epoch and exists(
   select 1 from public.user_lifetime_conversation where user_id=new.user_id and project_id=new.project_id) then
   perform 1 from public.user_profile where user_id=new.user_id for update;
 end if;
 return new;
end $$;

CREATE FUNCTION public.lock_lifetime_profile_creation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('memoir-profile:'||new.user_id::text,0));
  return new;
end $$;

CREATE FUNCTION public.lock_lifetime_provider_activation() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if auth.uid() is null or not exists(select 1 from auth.users where id=auth.uid()) then
   raise exception 'authenticated owner required' using errcode='42501';
 end if;
end $$;

CREATE FUNCTION public.lock_lifetime_publication(p_fence jsonb) RETURNS double precision
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare remaining double precision;
begin
 remaining:=public.lock_lifetime_publication_scope(p_fence);
 perform public.require_lifetime_policy_ready(auth.uid(),p_fence->'identity'->>'project_id');
 return remaining;
end $$;

CREATE FUNCTION public.lock_lifetime_publication_scope(p_fence jsonb) RETURNS double precision
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare current_fence jsonb; remaining double precision;
begin
  if (p_fence->'identity'->>'owner_id')::uuid is distinct from auth.uid() then raise exception 'owner mismatch'; end if;
  current_fence:=public.capture_lifetime_fence((p_fence->'identity'->>'conversation_id')::uuid,(p_fence->>'lease_token')::uuid);
  if current_fence is distinct from p_fence then raise exception 'stale lifetime fence' using errcode='PT409'; end if;
  select extract(epoch from expires_at-clock_timestamp()) into remaining from public.user_agent_turn_lease
    where user_id=auth.uid() and lease_token=(p_fence->>'lease_token')::uuid;
  if remaining is null or remaining<=0 then raise exception 'expired publication lease' using errcode='PT409'; end if;
  -- Caller must keep this transaction open through actual ASGI send, with a
  -- timeout shorter than remaining. An RPC call by itself is NOT a send fence.
  return remaining;
end $$;

CREATE FUNCTION public.lock_lifetime_draft_reply(p_fence jsonb) RETURNS double precision
    LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$
declare remaining double precision; owner uuid:=auth.uid(); project text:=p_fence->'identity'->>'project_id';
 source public.user_narrator_source%rowtype; pending_count integer;
begin
 remaining:=public.lock_lifetime_publication_scope(p_fence);
 if exists(select 1 from public.user_lifetime_policy_inventory_pending where user_id=owner and project_id=project) then
   raise exception 'LIFETIME_POLICY_PENDING' using errcode='55000';end if;
 select * into source from public.user_narrator_source where user_id=owner and project_id=project
   and sequence=(p_fence->>'source_revision')::bigint and status='active';
 if not found then raise exception 'active current draft source required' using errcode='PT409';end if;
 select count(*) into pending_count from public.user_lifetime_pending_policy where user_id=owner and project_id=project;
 if pending_count>0 then
   if pending_count<>1 or not exists(select 1 from public.user_lifetime_pending_policy
       where user_id=owner and project_id=project and source_id=source.id and source_version=source.version
         and conversation_id=(p_fence->'identity'->>'conversation_id')::uuid) then
     raise exception 'LIFETIME_POLICY_PENDING' using errcode='55000';end if;
 elsif not exists(select 1 from public.user_lifetime_source_policy_receipt
     where user_id=owner and project_id=project and source_id=source.id and source_version=source.version
       and review#>'{output,complete}'='true'::jsonb and review#>'{output,restrictions}'='[]'::jsonb) then
   raise exception 'LIFETIME_DRAFT_REPLACED' using errcode='PT409';
 end if;
 return remaining;
end $$;

CREATE FUNCTION public.lock_lifetime_read_publication(p_fence jsonb) RETURNS double precision
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare remaining double precision;
begin
 remaining:=public.lock_lifetime_read_publication_scope(p_fence);
 perform public.require_lifetime_policy_ready(auth.uid(),p_fence->'identity'->>'project_id');
 return remaining;
end $$;

CREATE FUNCTION public.lock_lifetime_read_publication_scope(p_fence jsonb) RETURNS double precision
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $memoir$
declare current_fence jsonb; captured bigint; remaining double precision;
begin
  if jsonb_typeof(p_fence) is distinct from 'object' or
    jsonb_typeof(p_fence->'identity') is distinct from 'object' or
    jsonb_typeof(p_fence->'captured_at_ms') is distinct from 'number' or
    p_fence->>'captured_at_ms' !~ '^[1-9][0-9]{0,18}$' then
    raise exception 'invalid read fence' using errcode='22023'; end if;
  if (p_fence->'identity'->>'owner_id')::uuid is distinct from auth.uid() then
    raise exception 'owner mismatch' using errcode='42501'; end if;
  captured:=(p_fence->>'captured_at_ms')::bigint;
  current_fence:=public.capture_lifetime_read_fence(p_fence->'identity'->>'project_id');
  -- Whole-object equality rejects missing fields, wrong identity, types, writer
  -- lease tokens and extra keys. Only the original capture time is retained.
  if current_fence-'captured_at_ms' is distinct from p_fence-'captured_at_ms' then
    raise exception 'stale lifetime read fence' using errcode='PT409'; end if;
  remaining:=30.0-(extract(epoch from clock_timestamp())-captured/1000.0);
  if remaining<=0 or remaining>30 then
    raise exception 'expired or future read fence' using errcode='PT409'; end if;
  -- This transaction MUST remain open through the actual bounded ASGI send.
  -- A completed PostgREST RPC alone is not a publication guard.
  return remaining;
end $memoir$;

CREATE FUNCTION public.mark_lifetime_mapping_policy_pending() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 -- An explicitly mapped/transferred historical source has no parser receipt.
 -- Inventory remains incomplete until a separate, reviewed migration resolves
 -- it. Merely editing the first source cannot clear unknown remaining history.
 if exists(select 1 from public.user_narrator_source where user_id=new.user_id and project_id=new.project_id) then
   insert into public.user_lifetime_policy_inventory_pending values(new.user_id,new.project_id,new.conversation_id,'semantic-v1') on conflict do nothing;
 end if;
 insert into public.user_lifetime_pending_policy
 select s.user_id,s.project_id,new.conversation_id,s.id,s.version,s.client_turn_id,'semantic-v1'
 from public.user_narrator_source s where s.user_id=new.user_id and s.project_id=new.project_id and s.status='active'
 order by s.sequence limit 1 on conflict do nothing;
 return new;
end $$;

CREATE FUNCTION public.mark_lifetime_source_policy_pending() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare conversation uuid;
begin
 select conversation_id into conversation from public.user_lifetime_conversation where user_id=new.user_id and project_id=new.project_id;
 if not found then return new;end if;
 -- Source mutators own project first; raw owner imports must obey the same order.
 perform 1 from public.user_memoir_project where user_id=new.user_id and project_id=new.project_id for update;
 if new.status<>'active' then
   delete from public.user_lifetime_pending_policy where user_id=new.user_id and project_id=new.project_id and source_id=new.id;
   delete from public.user_lifetime_source_policy_receipt where user_id=new.user_id and project_id=new.project_id and source_id=new.id;
 else
   insert into public.user_lifetime_pending_policy values(new.user_id,new.project_id,conversation,new.id,new.version,new.client_turn_id,'semantic-v1')
   on conflict(user_id,project_id,source_id) do update set source_version=excluded.source_version,parser_version=excluded.parser_version;
 end if;
 return new;
end $$;

CREATE FUNCTION public.memoir_lane_progress(p_lane public.user_memoir_lane) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select pg_catalog.jsonb_build_object('state',case
    when p_lane.token is not null and p_lane.lease_until>clock_timestamp() and p_lane.run_deadline>clock_timestamp() then 'running'
    when p_lane.attempts>=3 then 'retry_required'
    when p_lane.pending or p_lane.token is not null then 'pending' else 'finished' end,
    'pending',coalesce((p_lane.token is not null and p_lane.lease_until>clock_timestamp() and p_lane.run_deadline>clock_timestamp())
      or ((p_lane.pending or p_lane.token is not null) and p_lane.attempts<3),false),
    'successful_source',coalesce(p_lane.successful_source,0),'successful_event',coalesce(p_lane.successful_event,0),
    'covered_round',coalesce(p_lane.successful_round,0),'target_milestone',coalesce(p_lane.target_milestone,0),'error',p_lane.error)
$$;

CREATE FUNCTION public.memory_age_number(p_text text) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare matches text[]; word text; number integer; unit integer; tens integer;
  small text[]:=array['zero','one','two','three','four','five','six','seven','eight','nine','ten','eleven','twelve','thirteen','fourteen','fifteen','sixteen','seventeen','eighteen','nineteen'];
begin
  matches:=pg_catalog.regexp_match(p_text,'(?:at age |aged |age |when I was )([0-9]{1,3})','i');
  if matches is null then matches:=pg_catalog.regexp_match(p_text,'([0-9]{1,3})\s*(?:years old|岁)'); end if;
  if matches is not null then return matches[1]::integer; end if;
  matches:=pg_catalog.regexp_match(p_text,'(?:at age|aged|age|at|when I was)\s+([a-z]+)(?:[-\s]+([a-z]+))?','i');
  if matches is not null then
    number:=pg_catalog.array_position(small,pg_catalog.lower(matches[1]))-1;
    if number is not null then return number; end if;
    tens:=(pg_catalog.array_position(array['twenty','thirty','forty','fifty','sixty','seventy','eighty','ninety'],pg_catalog.lower(matches[1]))+1)*10;
    if tens is not null then
      unit:=pg_catalog.array_position(small,pg_catalog.lower(matches[2]))-1;
      return tens+case when unit between 1 and 9 then unit else 0 end;
    end if;
  end if;
  matches:=pg_catalog.regexp_match(p_text,'([一二三四五六七八九十两]{1,3})岁');
  if matches is not null then
    word:=pg_catalog.replace(matches[1],'两','二');
    if pg_catalog.strpos(word,'十')>0 then
      tens:=case when pg_catalog.left(word,1)='十' then 1 else pg_catalog.strpos('一二三四五六七八九',pg_catalog.left(word,1)) end;
      unit:=case when pg_catalog.right(word,1)='十' then 0 else pg_catalog.strpos('一二三四五六七八九',pg_catalog.right(word,1)) end;
      if tens>0 then return tens*10+unit; end if;
    elsif length(word)=1 then return nullif(pg_catalog.strpos('一二三四五六七八九',word),0); end if;
  end if;
  return null;
end $$;

CREATE FUNCTION public.memory_event_group(e public.user_memory_event) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select pg_catalog.jsonb_build_object('event_id',e.id,'life_stage',e.life_stage,
    'year_start',e.data->'temporal'->'year_start','year_end',e.data->'temporal'->'year_end',
    'precision',coalesce(e.data->'temporal'->>'precision','unknown'),'kind',e.kind)
$$;

CREATE FUNCTION public.memory_event_record(e public.user_memory_event) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select public.memory_event_record_before_photos(e) || jsonb_build_object('photo_associations',public.interview_photo_links(e.user_id,e.project_id,e.id))
$$;

CREATE FUNCTION public.memory_event_record_before_photos(e public.user_memory_event) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select e.data || pg_catalog.jsonb_build_object('id',e.id,'revision',e.revision,'kind',e.kind,
    'life_stage',e.life_stage,'status',e.status,'change_sequence',e.change_sequence,
    'source_refs',coalesce((select pg_catalog.jsonb_agg(s.evidence order by n.sequence,s.source_version,s.evidence_hash)
      from public.user_memory_event_source s join public.user_narrator_source n
        on n.user_id=s.user_id and n.project_id=s.project_id and n.id=s.source_id
      where s.user_id=e.user_id and s.project_id=e.project_id and s.event_id=e.id
        and n.status='active' and n.version=s.source_version),'[]'::jsonb))
$$;

CREATE FUNCTION public.merge_memoir_context(a jsonb, b jsonb, guest_wins boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  result jsonb := a;
  item record;
  incoming jsonb;
  identity text;
  position integer;
begin
  if a is null or a in ('null'::jsonb, '""'::jsonb, '{}'::jsonb, '[]'::jsonb) then return b; end if;
  if b is null or b in ('null'::jsonb, '""'::jsonb, '{}'::jsonb, '[]'::jsonb) then return a; end if;
  if jsonb_typeof(a) = 'object' and jsonb_typeof(b) = 'object' then
    for item in select key, value from jsonb_each(b) loop
      result := jsonb_set(result, array[item.key], public.merge_memoir_context(result->item.key, item.value, guest_wins), true);
    end loop;
    return result;
  end if;
  if jsonb_typeof(a) = 'array' and jsonb_typeof(b) = 'array' then
    for incoming in select value from jsonb_array_elements(b) loop
      identity := case when incoming ? 'place' then
        'place:' || lower(coalesce((incoming->'hierarchy')::text, '') || ':' || (incoming->>'place'))
        else coalesce(incoming->>'asset_id', incoming->>'id', incoming->>'source_url', incoming->>'image_url') end;
      select (ordinality - 1)::integer into position from jsonb_array_elements(result) with ordinality e(value, ordinality)
        where value = incoming or (identity is not null and identity = case when value ? 'place' then
          'place:' || lower(coalesce((value->'hierarchy')::text, '') || ':' || (value->>'place'))
          else coalesce(value->>'asset_id', value->>'id', value->>'source_url', value->>'image_url') end)
        limit 1;
      if position is null then result := result || jsonb_build_array(incoming);
      else result := jsonb_set(result, array[position::text], public.merge_memoir_context(result->position, incoming, guest_wins)); end if;
    end loop;
    return result;
  end if;
  return case when guest_wins then b else a end;
end;
$$;

CREATE FUNCTION public.narrator_source_record(s public.user_narrator_source) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 select jsonb_build_object('id',s.id,'project_id',s.project_id,'client_turn_id',s.client_turn_id,
 'sequence',s.sequence,'version',s.version,'text',s.text,'kind',s.kind,'language',s.language,
 'status',s.status,'author_role','storyteller','created_at',s.created_at) ||
 coalesce((select jsonb_build_object('cue_context',v.attribution->'cue_context')
   from public.user_narrator_source_version v where v.user_id=s.user_id and v.project_id=s.project_id
   and v.source_id=s.id and v.version=s.version and v.attribution ? 'cue_context'),'{}')
$$;

CREATE FUNCTION public.normalize_response_stage() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  new.life_stage:=coalesce(new.life_stage,'unplaced');
  return new;
end $$;

-- Consent is server-owned evidence, separate from the editable profile.
CREATE TABLE public.user_recording_consent (
 user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
 revision bigint NOT NULL CHECK (revision > 0),
 policy_version text NOT NULL,
 retain_originals boolean NOT NULL,
 ai_processing boolean NOT NULL,
 locale text NOT NULL CHECK (locale IN ('en-AU','zh-CN')),
 granted_at timestamptz NOT NULL DEFAULT now(),
 revoked_at timestamptz
);
ALTER TABLE public.user_recording_consent ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.user_recording_consent FROM public,anon,authenticated,service_role;

CREATE FUNCTION public.recording_identity_verified(p_owner uuid) RETURNS boolean
 LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO '' AS $$
 select exists(select 1 from auth.users u where u.id=p_owner and not u.is_anonymous
   and ((nullif(u.email,'') is not null and u.email_confirmed_at is not null)
     or (nullif(u.phone,'') is not null and u.phone_confirmed_at is not null)))
$$;
REVOKE ALL ON FUNCTION public.recording_identity_verified(uuid) FROM public,anon,authenticated,service_role;

CREATE FUNCTION public.original_recording_authorized(p_owner uuid, p_project_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$select public.recording_identity_verified(p_owner) and exists(
      select 1 from public.user_recording_consent c where c.user_id=p_owner
      and c.policy_version='original-recordings-v1' and c.retain_originals
      and c.ai_processing and c.revoked_at is null)$$;

CREATE FUNCTION public.recording_consent_operation(p_owner uuid, p_operation text, p_data jsonb) RETURNS jsonb
 LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$
declare consent public.user_recording_consent%rowtype; revision bigint; verified boolean;
begin
 -- Withdrawal waits for admitted original reads/provider calls holding this
 -- same owner row FOR SHARE; after commit no new operation can pass consent.
 if p_operation='consent_status' then
   perform 1 from auth.users where id=p_owner for share;
 else
   perform 1 from auth.users where id=p_owner for update;
 end if;
 if not found then raise exception 'recording owner unavailable' using errcode='42501';end if;
 select * into consent from public.user_recording_consent where user_id=p_owner;
 revision:=coalesce(consent.revision,0);
 verified:=public.recording_identity_verified(p_owner);
 if p_operation in ('consent_grant','consent_revoke') then
   if (p_data->>'expected_revision')::bigint is distinct from revision then
     raise exception 'recording consent changed' using errcode='40001';end if;
   if p_data->>'policy_version' is distinct from 'original-recordings-v1'
     or p_data->>'locale' is null or p_data->>'locale' not in ('en-AU','zh-CN') then
     raise exception 'invalid recording consent' using errcode='22023';end if;
   if p_operation='consent_grant' and (not verified
     or p_data->'retain_originals' is distinct from 'true'::jsonb
     or p_data->'ai_processing' is distinct from 'true'::jsonb
     or not exists(select 1 from public.original_recording_rollout where enabled)) then
     raise exception 'verified identity and explicit recording consent required' using errcode='42501';end if;
   insert into public.user_recording_consent(user_id,revision,policy_version,retain_originals,ai_processing,locale,revoked_at)
   values(p_owner,revision+1,'original-recordings-v1',p_operation='consent_grant',p_operation='consent_grant',
     p_data->>'locale',case when p_operation='consent_revoke' then now() end)
   on conflict(user_id) do update set revision=excluded.revision,policy_version=excluded.policy_version,
     retain_originals=excluded.retain_originals,ai_processing=excluded.ai_processing,locale=excluded.locale,
     granted_at=case when p_operation='consent_grant' then now() else user_recording_consent.granted_at end,
     revoked_at=excluded.revoked_at;
   revision:=revision+1;
 elsif p_operation<>'consent_status' then
   raise exception 'invalid recording consent operation' using errcode='22023';
 end if;
 return jsonb_build_object('policy_version','original-recordings-v1','revision',revision,
   'recoverable_identity',verified,'consented',exists(select 1 from public.user_recording_consent c
     where c.user_id=p_owner and c.policy_version='original-recordings-v1'
     and c.retain_originals and c.ai_processing and c.revoked_at is null),
   'rollout_enabled',exists(select 1 from public.original_recording_rollout where enabled));
end $$;
REVOKE ALL ON FUNCTION public.recording_consent_operation(uuid,text,jsonb) FROM public,anon,authenticated,service_role;

CREATE FUNCTION public.original_recording_descriptor(r public.user_original_recording) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 select jsonb_build_object('id',r.id,'content_type',r.content_type,'codec',r.codec,'byte_size',r.byte_size,
 'duration_seconds',r.duration_seconds,'content_sha256',r.content_sha256,'storage_status',r.storage_status,
 'transcription_status',r.transcription_status,'lifecycle',r.lifecycle,'created_at',r.created_at,
 'backend_saved',r.storage_status='ready' and r.lifecycle<>'deleted',
 'content_url','/api/v1/memoir/story/recordings/'||r.id::text||'/content')
$$;

CREATE FUNCTION public.original_recording_visible(r public.user_original_recording, p_owner uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select r.user_id=p_owner and r.lifecycle<>'deleted'
 and not exists(select 1 from public.user_original_recording_cancel where user_id=p_owner and upload_key=r.upload_key)
 and exists(select 1 from public.original_recording_rollout where enabled)
 and public.original_recording_authorized(p_owner,r.project_id)
 and (r.project_id is null or exists(select 1 from public.user_memoir_project p
   where p.user_id=p_owner and p.project_id=r.project_id))
 and not exists(select 1 from public.user_lifetime_pending_policy where user_id=p_owner and project_id=r.project_id)
 and not exists(select 1 from public.user_lifetime_policy_inventory_pending where user_id=p_owner and project_id=r.project_id)
 and (r.lifecycle='draft' or exists(select 1 from public.user_source_recording l
   join public.user_narrator_source s on s.user_id=l.user_id and s.project_id=l.project_id and s.id=l.source_id
   where l.recording_id=r.id and l.user_id=p_owner and s.status='active'))
$$;

CREATE FUNCTION public.pending_lifetime_collection_jobs(p_limit integer DEFAULT 8, p_include_outline boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if p_limit is null or p_limit not between 1 and 32 then raise exception 'invalid job limit';end if;
 return coalesce((select jsonb_agg(id order by created_at) from (
  select j.id,j.created_at from public.user_lifetime_collection_job j
  where (j.state='QUEUED' or j.state='RUNNING' and j.lease_until<=clock_timestamp())
   and (j.kind<>'BuildOutline' or p_include_outline is true)
   and not exists(select 1 from public.user_lifetime_pending_policy p where p.user_id=j.user_id and p.project_id=j.project_id)
   and not exists(select 1 from public.user_lifetime_policy_inventory_pending p where p.user_id=j.user_id and p.project_id=j.project_id)
  order by j.created_at limit p_limit) ready),'[]'::jsonb);
end $$;

CREATE FUNCTION public.pending_memoir_lanes(p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select coalesce(jsonb_agg(id),'[]'::jsonb) from (
   select l.id from public.user_memoir_lane l where l.skill in ('timeline','composer') and l.attempts<3 and l.available_at<=clock_timestamp()
     and exists(select 1 from public.user_lifetime_conversation c where c.user_id=l.user_id and c.project_id=l.project_id)
     and (l.pending or (l.token is not null and (l.lease_until<=clock_timestamp() or l.run_deadline<=clock_timestamp())))
     and not exists(select 1 from public.user_lifetime_pending_policy p where p.user_id=l.user_id and p.project_id=l.project_id)
     and not exists(select 1 from public.user_lifetime_policy_inventory_pending p where p.user_id=l.user_id and p.project_id=l.project_id)
   order by l.available_at,l.id limit least(greatest(p_limit,1),100)) ready;
$$;

CREATE FUNCTION public.pending_memoir_receipts(p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select coalesce(jsonb_agg(id),'[]'::jsonb) from (
   select r.id from public.user_private_draft_outbox r where not r.delivered
     and exists(select 1 from public.user_lifetime_conversation c where c.user_id=r.user_id and c.project_id=r.project_id)
     and not exists(select 1 from public.user_lifetime_pending_policy p where p.user_id=r.user_id and p.project_id=r.project_id)
     and not exists(select 1 from public.user_lifetime_policy_inventory_pending p where p.user_id=r.user_id and p.project_id=r.project_id)
   order by r.created_at,r.id limit least(greatest(p_limit,1),100)) ready;
$$;

CREATE FUNCTION public.persist_lifetime_chosen_name(p_conversation_id uuid, p_source_id uuid, p_source_version bigint, p_name text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner uuid:=auth.uid(); project text; current_name text; dependency public.user_lifetime_chosen_name%rowtype;
 released boolean; has_dependency boolean;
begin
 select project_id into project from public.user_lifetime_conversation where user_id=owner and conversation_id=p_conversation_id;
 if not found then raise exception 'conversation unavailable';end if;
 select p.profile->>'name' into current_name from public.user_profile p where p.user_id=owner for update;
 select * into dependency from public.user_lifetime_chosen_name where user_id=owner;
 has_dependency:=found;
 select name_released into released from public.user_lifetime_profile_authority where user_id=owner;
 if not coalesce(released,false) and (dependency.authority='explicit' or
   (current_name is not null and (not has_dependency or current_name is distinct from dependency.chosen_name))) then return;end if;
 if length(coalesce(p_name,'')) not between 1 and 120 or not exists(select 1 from public.user_narrator_source
   where user_id=owner and project_id=project and id=p_source_id and version=p_source_version and status='active'
     and position(p_name in text)>0) then raise exception 'exact active chosen-name evidence required';end if;
 insert into public.user_lifetime_chosen_name(user_id,conversation_id,project_id,source_id,source_version,chosen_name,authority)
 values(owner,p_conversation_id,project,p_source_id,p_source_version,p_name,'generated')
 on conflict(user_id) do update set conversation_id=excluded.conversation_id,project_id=excluded.project_id,
   source_id=excluded.source_id,source_version=excluded.source_version,chosen_name=excluded.chosen_name,authority='generated';
 delete from public.user_lifetime_profile_dependency where user_id=owner and field='name';
 update public.user_lifetime_profile_authority set name_released=false,invalidated_fields=array_remove(invalidated_fields,'name') where user_id=owner;
 update public.user_profile set profile=jsonb_set(profile,'{name}',to_jsonb(p_name)) where user_id=owner;
end $$;

CREATE FUNCTION public.persist_lifetime_continuity_updates(p_fence jsonb, p_updates jsonb, p_literal_only boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare owner uuid:=auth.uid(); conversation uuid:=(p_fence->'identity'->>'conversation_id')::uuid; project text;
 item jsonb; v_data jsonb; ref jsonb; existing public.user_lifetime_continuity%rowtype; source public.user_narrator_source%rowtype;
begin
 select project_id into project from public.user_lifetime_conversation where user_id=owner and conversation_id=conversation;
 if not found then raise exception 'conversation unavailable'; end if;
 perform 1 from public.user_memoir_project where user_id=owner and project_id=project for update;
 perform public.lock_lifetime_publication(p_fence);
 if jsonb_typeof(p_updates) is distinct from 'array' or jsonb_array_length(p_updates)>8 then raise exception 'bounded continuity updates required'; end if;
 for item in select value from jsonb_array_elements(p_updates) loop
   if jsonb_typeof(item)<>'object' or exists(select 1 from jsonb_object_keys(item) k where k not in ('record_id','kind','data'))
     or not (item ?& array['record_id','kind','data']) or item->>'kind' not in ('person','unresolved_reference','commitment','excluded_topic','paused_topic')
     then raise exception 'invalid continuity update'; end if;
   v_data:=item->'data';ref:=v_data->'source_refs'->0;
   if jsonb_typeof(v_data->'source_refs') is distinct from 'array' or jsonb_array_length(v_data->'source_refs')<>1
      or v_data->>'text' is distinct from ref->>'quote' then raise exception 'verbatim current continuity required'; end if;
   select * into source from public.user_narrator_source where user_id=owner and project_id=project and id=(ref->>'source_id')::uuid
     and version=(ref->>'version')::bigint and sequence=(p_fence->>'source_revision')::bigint and status='active';
   if not found then raise exception 'current source continuity required';end if;
   if p_literal_only and item->>'kind' not in ('excluded_topic','paused_topic') then raise exception 'only current literal privacy controls allowed'; end if;
   if item->>'kind' in ('excluded_topic','paused_topic') and
     (v_data->>'assertion'<>'asserted' or not exists(select 1 from public.user_lifetime_source_policy_receipt r,
       lateral jsonb_array_elements(r.review->'output'->'restrictions') reviewed
       where r.user_id=owner and r.project_id=project and r.source_id=source.id and r.source_version=source.version
         and reviewed->>'kind'=item->>'kind' and reviewed->>'quote'=v_data->>'text'
         and reviewed->'char_start'=ref->'char_start' and reviewed->'char_end'=ref->'char_end')) then
     raise exception 'reviewed current privacy restriction required';end if;
   select * into existing from public.user_lifetime_continuity where user_id=owner and conversation_id=conversation and record_id=item->>'record_id';
   if not found and item->>'kind' in ('excluded_topic','paused_topic') then
     -- Earlier UUID5 policy records remain opaque stable identities. Reuse an
     -- exact current-source record; do not duplicate it during final commit.
     select * into existing from public.user_lifetime_continuity c where c.user_id=owner and c.conversation_id=conversation
       and c.kind=item->>'kind' and c.kind in ('excluded_topic','paused_topic')
       and c.data->'source_refs'->0->>'source_id'=ref->>'source_id'
       and c.data->'source_refs'->0->>'version'=ref->>'version'
       and c.data->'source_refs'->0->>'char_start'=ref->>'char_start'
       and c.data->'source_refs'->0->>'char_end'=ref->>'char_end'
       and c.data=v_data and c.policy_epoch=(p_fence->>'policy_epoch')::bigint order by c.record_id limit 1;
   end if;
   if found then
     if existing.data is distinct from v_data or existing.kind is distinct from item->>'kind' then raise exception 'continuity identity conflict'; end if;
   else
     perform public.save_lifetime_continuity(conversation,item->>'record_id',item->>'kind',0,(p_fence->>'policy_epoch')::bigint,(p_fence->>'lease_token')::uuid,v_data);
   end if;
 end loop;
 return public.capture_lifetime_fence(conversation,(p_fence->>'lease_token')::uuid);
end $$;

CREATE FUNCTION public.persist_lifetime_place_journeys(p_fence jsonb, p_source_id uuid, p_source_version bigint, p_journeys jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner uuid:=auth.uid(); project text:=p_fence->'identity'->>'project_id';
 source public.user_narrator_source%rowtype; journey jsonb;
begin
 perform public.lock_lifetime_publication(p_fence);
 select * into source from public.user_narrator_source
   where user_id=owner and project_id=project and id=p_source_id and version=p_source_version and status='active';
 if not found then raise exception 'current narrator source required' using errcode='PT409'; end if;
 if jsonb_typeof(p_journeys) is distinct from 'array' or jsonb_array_length(p_journeys)>8
   or octet_length(p_journeys::text)>8192 then raise exception 'bounded place journeys required' using errcode='22023'; end if;
 perform public.validate_two_lane_places(source.text,p_journeys);
 insert into public.user_lifetime_place_journey(user_id,project_id,source_id,source_version,journeys) values(owner,project,p_source_id,p_source_version,p_journeys)
 on conflict(user_id,project_id,source_id) do update set source_version=excluded.source_version,journeys=excluded.journeys,derived_fence=null;
end $$;

CREATE FUNCTION public.prepare_guest_conversation_before_memory_events(p_token text, p_project_id text, p_messages jsonb, p_workspace_profile jsonb DEFAULT '{}'::jsonb, p_ui_locale text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $memoir$
declare
  v_authenticated_user_id uuid := auth.uid(); key_hash text; snapshot jsonb; context jsonb;
  source_profile jsonb; browser_profile jsonb; locale text;
begin
  if v_authenticated_user_id is null or not exists(select 1 from auth.users where id = v_authenticated_user_id and is_anonymous is true) then
    raise exception 'guest session required' using errcode = '42501';
  end if;
  if p_token is null or p_token !~ '^[a-f0-9]{64}$' or p_project_id is null
    or char_length(p_project_id) not between 1 and 128 or p_messages is null
    or jsonb_typeof(p_messages) <> 'array' or jsonb_array_length(p_messages) > 1000
    or octet_length(p_messages::text) > 2000000 or jsonb_typeof(p_workspace_profile) <> 'object'
    or octet_length(p_workspace_profile::text) > 2000000 then
    raise exception 'invalid conversation transfer' using errcode = '22023';
  end if;
  if exists(select 1 from jsonb_array_elements(p_messages) m where jsonb_typeof(m) <> 'object'
      or coalesce(m->>'role', '') not in ('user', 'assistant') or jsonb_typeof(m->'text') is distinct from 'string') then
    raise exception 'invalid conversation messages' using errcode = '22023';
  end if;
  if exists(select 1 from public.user_agent_turn_lease where user_id = v_authenticated_user_id and expires_at > clock_timestamp()) then
    raise exception 'conversation reply in progress' using errcode = '55000';
  end if;
  select coalesce(jsonb_agg(to_jsonb(m) - 'user_id' order by created_at, id), '[]'::jsonb)
    into snapshot from public.user_memory m where user_id = v_authenticated_user_id;
  if jsonb_array_length(snapshot) > 1000 then
    raise exception 'conversation exceeds transfer limit' using errcode = '22023';
  end if;
  select profile into source_profile from public.user_profile where user_id = v_authenticated_user_id;
  -- The browser keeps some generated place/photo data in its project adapter.
  -- Accept only product context, never client-supplied auth or payment claims.
  select coalesce(jsonb_object_agg(key, value), '{}'::jsonb) into browser_profile
    from jsonb_each(p_workspace_profile) where key in ('name', 'preferred_language', 'birth_year',
      'birth_date_expression', 'birth_place', 'childhood_place', 'story_focus',
      'dialect_preference', 'memory_places', 'avatar_style');
  source_profile := public.merge_memoir_context(coalesce(source_profile, '{}'::jsonb), browser_profile, true);
  if exists(select 1 from public.user_place_journey where user_id = v_authenticated_user_id) then
    source_profile := jsonb_set(source_profile, '{memory_places}', public.merge_memoir_context(
      coalesce(source_profile->'memory_places', '[]'::jsonb),
      (select jsonb_build_array(to_jsonb(j) - 'user_id') from public.user_place_journey j where user_id = v_authenticated_user_id), false));
  end if;
  select coalesce(p_ui_locale, raw_user_meta_data->>'ui_locale') into locale from auth.users where id = v_authenticated_user_id;
  if locale not in ('en-AU', 'zh-CN') then locale := null; end if;
  context := jsonb_build_object('profile', source_profile, 'ui_locale', locale,
    'place_journey', (select to_jsonb(j) - 'user_id' from public.user_place_journey j where user_id = v_authenticated_user_id),
    'family_context', (select coalesce(jsonb_agg(to_jsonb(f) - 'user_id'), '[]'::jsonb) from public.user_family_context f where user_id = v_authenticated_user_id),
    'agent_session', (select to_jsonb(s) - 'user_id' from public.user_agent_session s where user_id = v_authenticated_user_id),
    'storage_objects', (select coalesce(jsonb_agg(jsonb_build_object('name', name, 'metadata', metadata)), '[]'::jsonb)
      from storage.objects where bucket_id = 'memory-spark'
        and split_part(name, '/', 1) = v_authenticated_user_id::text));
  key_hash := encode(sha256(convert_to(p_token, 'UTF8')), 'hex');
  delete from public.guest_conversation_transfer where guest_user_id = v_authenticated_user_id and target_user_id is null and expires_at <= clock_timestamp();
  insert into public.guest_conversation_transfer(token_hash, guest_user_id, project_id, messages, memories, workspace)
    values(key_hash, v_authenticated_user_id, p_project_id, p_messages, snapshot, context)
    on conflict(token_hash) do update set project_id = excluded.project_id, messages = excluded.messages,
      memories = excluded.memories, workspace = excluded.workspace, expires_at = clock_timestamp() + interval '1 hour'
    where public.guest_conversation_transfer.guest_user_id = v_authenticated_user_id and public.guest_conversation_transfer.target_user_id is null;
  if not found then raise exception 'transfer already claimed' using errcode = '42501'; end if;
  return jsonb_build_object('prepared', true);
end;
$memoir$;

CREATE FUNCTION public.prepare_guest_conversation_before_photos(p_token text, p_project_id text, p_messages jsonb, p_workspace_profile jsonb DEFAULT '{}'::jsonb, p_ui_locale text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $memoir$
declare result jsonb; project public.user_memoir_project%rowtype; snapshot jsonb:='{}'; rows jsonb; table_name text;
begin
  result:=public.prepare_guest_conversation_before_memory_events(p_token,p_project_id,p_messages,p_workspace_profile,p_ui_locale);
  select * into project from public.user_memoir_project where user_id=auth.uid() and project_id=p_project_id for update;
  if found then
    snapshot:=pg_catalog.jsonb_build_object('project',pg_catalog.to_jsonb(project));
    foreach table_name in array array['user_narrator_source','user_narrator_source_version','user_memory_event','user_memory_event_source',
      'user_memory_event_source_exclusion','user_memory_event_revision','user_memory_event_change',
      'user_memoir_edition','user_memoir_milestone','user_memoir_lane'] loop
      execute pg_catalog.format('select coalesce(jsonb_agg(to_jsonb(t)),''[]''::jsonb) from public.%I t where user_id=$1 and project_id=$2',table_name)
        into rows using auth.uid(),p_project_id;
      snapshot:=snapshot || pg_catalog.jsonb_build_object(table_name,rows);
    end loop;
  end if;
  update public.guest_conversation_transfer set workspace=workspace || pg_catalog.jsonb_build_object('shared_memoir',snapshot)
    where token_hash=pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(p_token,'UTF8')),'hex') and guest_user_id=auth.uid() and target_user_id is null;
  return result;
end $memoir$;

CREATE FUNCTION public.prepare_guest_conversation_transfer(p_token text, p_project_id text, p_messages jsonb, p_workspace_profile jsonb DEFAULT '{}'::jsonb, p_ui_locale text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb;
begin
  result:=public.prepare_guest_conversation_before_photos(p_token,p_project_id,p_messages,p_workspace_profile,p_ui_locale);
  update public.guest_conversation_transfer set workspace=workspace || jsonb_build_object('interview_photos',public.interview_transfer_snapshot(auth.uid(),p_project_id))
    where token_hash=encode(sha256(convert_to(p_token,'UTF8')),'hex') and guest_user_id=auth.uid() and target_user_id is null;
  return result;
end $$;

CREATE FUNCTION public.private_draft_event_page(p_event_id uuid, p_cursor uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 32) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare receipt public.user_private_draft_outbox%rowtype; identity public.user_lifetime_conversation%rowtype;
 project public.user_memoir_project%rowtype; frozen public.user_lifetime_draft_snapshot%rowtype;
 position public.user_lifetime_draft_cursor%rowtype;
 records jsonb:='[]'; rounds jsonb:='[]'; last_row jsonb; next_cursor uuid;
 source_done boolean:=false; last_source bigint:=0; last_offset integer:=-1; last_round bigint:=0;
 remaining integer; has_more boolean; output_locale text; round_high bigint;
 prefix public.user_lifetime_draft_snapshot%rowtype; output jsonb;
begin
 if p_limit is null or p_limit not between 1 and 32 then raise exception 'invalid draft page bounds' using errcode='22023'; end if;
 select * into receipt from public.user_private_draft_outbox where id=p_event_id;
 if not found then return null; end if;
 select * into identity from public.user_lifetime_conversation where user_id=receipt.user_id and project_id=receipt.project_id;
 if not found then raise exception 'governed draft identity required' using errcode='22023'; end if;
 select * into project from public.user_memoir_project where user_id=receipt.user_id and project_id=receipt.project_id for share;
 select * into identity from public.user_lifetime_conversation where conversation_id=identity.conversation_id for share;
 select case when profile->>'preferred_language'='zh-CN' then 'zh-CN' else 'en-AU' end into output_locale
   from public.user_profile where user_id=receipt.user_id;
 output_locale:=coalesce(output_locale,'en-AU');
 if p_cursor is not null then
   select * into position from public.user_lifetime_draft_cursor where id=p_cursor;
   if not found then raise exception 'invalid draft cursor' using errcode='22023'; end if;
   select * into frozen from public.user_lifetime_draft_snapshot where id=position.snapshot_id
     and event_id=receipt.id and user_id=receipt.user_id and project_id=receipt.project_id and conversation_id=identity.conversation_id;
   if not found then raise exception 'draft cursor scope mismatch' using errcode='22023'; end if;
   if frozen.policy_epoch<>project.policy_epoch or frozen.preference_revision<>identity.preference_revision or frozen.locale<>output_locale or frozen.round_revision<>project.draft_round_epoch then
     raise exception 'stale private draft snapshot' using errcode='PT409'; end if;
   last_source:=position.last_source;last_offset:=position.last_offset;last_round:=position.last_round;source_done:=position.sources_complete;
 else
   select coalesce(max(ordinal),0) into round_high from public.user_completed_round
     where user_id=receipt.user_id and project_id=receipt.project_id;
   -- Prefixes are server-owned attestations, never client-selected offsets.
   -- Completed but unacknowledged work cannot be used to skip a required job.
   select s.* into prefix from public.user_lifetime_draft_snapshot s
     join public.user_private_draft_outbox r on r.id=s.event_id and r.delivered
     where s.user_id=receipt.user_id and s.project_id=receipt.project_id and s.conversation_id=identity.conversation_id
       and s.policy_epoch=project.policy_epoch and s.preference_revision=identity.preference_revision
       and s.locale=output_locale and s.round_revision=project.draft_round_epoch and s.scan_complete
       and s.source_revision<=project.source_sequence and s.round_high_water<=round_high
       and (s.source_revision>0 or s.round_high_water>0) and s.event_id<>receipt.id
     order by s.source_revision desc,s.round_high_water desc,s.id limit 1;
   insert into public.user_lifetime_draft_snapshot(event_id,user_id,project_id,conversation_id,policy_epoch,
      preference_revision,source_revision,event_revision,round_high_water,completed,locale,
      coverage_schema_version,base_snapshot_id,source_after,round_after,round_revision)
   values(receipt.id,receipt.user_id,receipt.project_id,identity.conversation_id,project.policy_epoch,
      identity.preference_revision,project.source_sequence,project.event_sequence,round_high,
      coalesce((select rounds_completed from public.user_recall_usage where user_id=receipt.user_id),0),output_locale,
      1,prefix.id,coalesce(prefix.source_revision,0),coalesce(prefix.round_high_water,0),project.draft_round_epoch)
   on conflict on constraint lifetime_draft_snapshot_scope do nothing;
   select * into frozen from public.user_lifetime_draft_snapshot where event_id=receipt.id and policy_epoch=project.policy_epoch
     and preference_revision=identity.preference_revision and locale=output_locale and round_revision=project.draft_round_epoch;
   last_source:=frozen.source_after;last_round:=frozen.round_after;
   last_offset:=case when last_source>0 then 2147483647 else -1 end;
   source_done:=last_source=frozen.source_revision;
 end if;
 if not source_done then
   select coalesce(jsonb_agg(r.data order by r.sequence,r.chunk_start),'[]') into records from (
     select s.sequence,chunk_start,jsonb_build_object('record_type','source','source_id',s.source_id,'version',s.version,
       'sequence',s.sequence,'char_start',chunk_start,'char_end',case when s.status='active' then least(chunk_start+2048,length(s.text)) else 0 end,
       'text',case when s.status='active' then substring(s.text from chunk_start+1 for 2048) else null end,
       'kind',coalesce(s.kind,'narrator_chat'),'language',coalesce(s.language,'en-AU'),'status',s.status) as data
     from (select pos.sequence,pos.source_id,pos.version,src.kind,src.language,
         case when src.id is null then 'withdrawn' when src.version<>pos.version then 'superseded' else src.status end as status,
         case when src.version=pos.version and src.status='active' then src.text else null end as text
       from (select * from public.user_lifetime_source_position where user_id=receipt.user_id and project_id=receipt.project_id
           and sequence>=last_source and sequence<=frozen.source_revision order by sequence limit p_limit+2) pos
       left join public.user_narrator_source src on src.user_id=pos.user_id and src.project_id=pos.project_id and src.id=pos.source_id) s
     cross join lateral generate_series(0,case when s.status='active' then greatest(length(s.text)-1,0) else 0 end,2048) chunk_start
     where s.sequence>last_source or chunk_start>last_offset
     order by s.sequence,chunk_start limit p_limit+1) r;
   source_done:=jsonb_array_length(records)<=p_limit;
   if not source_done then records:=records-p_limit; end if;
   -- Source positions are the append-only inventory, including tombstones.
   -- A missing historical position is an inventory/reconciliation gate, never
   -- permission to report an apparently complete highest-numbered record.
   for last_row in select value from jsonb_array_elements(records) loop
     if (last_row->>'sequence')::bigint not between last_source and last_source+1 then
       raise exception 'private draft source inventory incomplete' using errcode='PT409';
     end if;
     last_source:=(last_row->>'sequence')::bigint;last_offset:=(last_row->>'char_start')::integer;
   end loop;
 end if;
 remaining:=p_limit-jsonb_array_length(records);
 has_more:=not source_done;
 if source_done then
   select coalesce(jsonb_agg(r.data order by r.ordinal),'[]') into rounds from (
     select ordinal,jsonb_build_object('record_type','round','turn_id',turn_id,'ordinal',ordinal,'memory_id',memory_id) as data
     from public.user_completed_round where user_id=receipt.user_id and project_id=receipt.project_id
       and ordinal>last_round and ordinal<=frozen.round_high_water order by ordinal limit remaining+1) r;
   has_more:=jsonb_array_length(rounds)>remaining;
   if has_more then rounds:=rounds-remaining; end if;
   if jsonb_array_length(rounds)>0 then last_round:=(rounds->-1->>'ordinal')::bigint;end if;
   records:=records||rounds;
 end if;
 if has_more then
   insert into public.user_lifetime_draft_cursor(snapshot_id,last_source,last_offset,last_round,sources_complete)
    values(frozen.id,last_source,last_offset,last_round,source_done)
    on conflict on constraint lifetime_draft_cursor_scope do update set snapshot_id=excluded.snapshot_id
    returning id into next_cursor;
 end if;
 if not has_more then
   if last_source<>frozen.source_revision or last_round<>frozen.round_high_water then
     raise exception 'private draft coverage incomplete' using errcode='PT409';
   end if;
   update public.user_lifetime_draft_snapshot set scan_complete=true where id=frozen.id;
 end if;
 output:=to_jsonb(frozen)-'id'-'scan_complete';
 -- In-flight pre-upgrade cursors must replay byte-identical page envelopes.
 if frozen.coverage_schema_version=0 then
   output:=output-'coverage_schema_version'-'base_snapshot_id'-'source_after'-'round_after'-'round_revision';
 end if;
 return output || jsonb_build_object('schema_version',1,'protocol','lifetime_draft_pages',
   'snapshot_id',frozen.id,'cursor',p_cursor,'records',records,'complete',not has_more,'next_cursor',next_cursor);
end $$;

CREATE FUNCTION public.private_draft_event_snapshot(p_event_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
begin
 if exists(select 1 from public.user_private_draft_outbox r join public.user_lifetime_conversation c
     on c.user_id=r.user_id and c.project_id=r.project_id where r.id=p_event_id) then
   return public.private_draft_event_page(p_event_id);
 end if;
 return null;
end $$;

CREATE FUNCTION public.project_lifetime_profile_authority() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare fields text[];
begin
 perform public.ensure_lifetime_profile_authority(new.user_id);
 if tg_op='UPDATE' and (old.profile->'memory_preferences'->'excluded_topics' is distinct from new.profile->'memory_preferences'->'excluded_topics'
   or old.profile->'memory_preferences'->'paused_topics' is distinct from new.profile->'memory_preferences'->'paused_topics') then
   select array_agg(distinct d.field) into fields from public.user_lifetime_profile_dependency d where d.user_id=new.user_id;
   if fields is not null then
     update public.user_lifetime_chosen_name set authority='invalidated',chosen_name=null
       where user_id=new.user_id and authority='generated' and 'name'=any(fields);
     delete from public.user_lifetime_profile_dependency where user_id=new.user_id and field=any(fields);
     update public.user_lifetime_profile_authority set invalidated_fields=(select array_agg(distinct k)
       from unnest(invalidated_fields||fields) k) where user_id=new.user_id;
   end if;
 end if;
 select a.invalidated_fields into fields from public.user_lifetime_profile_authority a where a.user_id=new.user_id;
 new.profile:=new.profile-coalesce(fields,'{}');
 if tg_op='UPDATE' and exists(select 1 from unnest(array['name','birth_year','birth_date_expression',
   'birth_place','childhood_place','avatar_style']) k where old.profile->k is distinct from new.profile->k) then
   update public.user_lifetime_profile_authority set revision=revision+1 where user_id=new.user_id;
 end if;
 if exists(select 1 from public.user_lifetime_profile_authority where user_id=new.user_id) then
   new.profile:=jsonb_set(new.profile,'{profile_automation}',public.lifetime_profile_automation(new.user_id));
 else new.profile:=new.profile-'profile_automation';end if;
 return new;
end $$;

CREATE FUNCTION public.publish_lifetime_checkpoint(p_id uuid, p_fence jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare owner uuid:=auth.uid(); saved public.user_lifetime_checkpoint%rowtype; project text; head uuid;
begin
  select * into saved from public.user_lifetime_checkpoint where id=p_id and user_id=owner;
  if not found then raise exception 'checkpoint unavailable'; end if;
  select project_id into project from public.user_lifetime_conversation where user_id=owner and conversation_id=saved.conversation_id;
  perform 1 from public.user_memoir_project where user_id=owner and project_id=project for update;
  perform public.lock_lifetime_publication(p_fence);
  if saved.fence is distinct from p_fence or saved.pinned is distinct from public.read_lifetime_pinned(saved.conversation_id) then raise exception 'stale checkpoint' using errcode='PT409'; end if;
  select checkpoint_id into head from public.user_lifetime_conversation where user_id=owner and conversation_id=saved.conversation_id;
  if head=p_id and saved.published then return true; end if;
  if head is distinct from saved.predecessor_id then raise exception 'checkpoint predecessor changed' using errcode='PT409'; end if;
  update public.user_lifetime_checkpoint set published=true where id=p_id;
  update public.user_lifetime_conversation set checkpoint_id=p_id where user_id=owner and conversation_id=saved.conversation_id;
  return true;
end $$;

CREATE FUNCTION public.publish_lifetime_semantic_checkpoint(p_lane_id uuid, p_token uuid, p_maintenance_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare snap public.user_lifetime_lane_snapshot%rowtype; proof public.user_lifetime_compaction%rowtype;
 identity public.user_lifetime_conversation%rowtype; project public.user_memoir_project%rowtype; head public.user_lifetime_checkpoint%rowtype;
 manifest jsonb; data jsonb; candidate uuid; fence jsonb; page jsonb;
begin
 snap:=public.lock_lifetime_memoir_lane(p_lane_id,p_token);
 page:=public.read_lifetime_memoir_lane_page_before_semantic(p_lane_id,p_token);
 select * into proof from public.user_lifetime_compaction where id=p_maintenance_id and user_id=snap.user_id and conversation_id=snap.conversation_id for update;
 select * into identity from public.user_lifetime_conversation where user_id=snap.user_id and conversation_id=snap.conversation_id;
 select * into project from public.user_memoir_project where user_id=snap.user_id and project_id=snap.project_id;
 if not found or not proof.complete or not proof.summary_complete or not proof.summary_required
   or proof.predecessor_id is distinct from identity.checkpoint_id or proof.pinned-'active_question'-'known_continuity'-'known_continuity_complete' is distinct from (page->'preferences')-'active_question'-'known_continuity'-'known_continuity_complete'
   or proof.fence->>'policy_epoch' is distinct from project.policy_epoch::text
   or proof.fence->>'execution_generation' is distinct from identity.execution_generation::text
   or proof.through_sequence<>snap.source_high_water-1
   or exists(select 1 from public.user_lifetime_checkpoint c where c.id=identity.checkpoint_id and c.coverage_end>proof.through_sequence) then raise exception 'stale semantic checkpoint' using errcode='PT409';end if;
 select * into head from public.user_lifetime_checkpoint where id=proof.predecessor_id;
 if proof.summary_revision<>(select count(*) from public.user_lifetime_summary_receipt r where r.maintenance_id=proof.id)
   or proof.summary_windows<>proof.summary_revision+coalesce((head.memory_summary->>'processed_windows')::bigint,0) then
   raise exception 'incomplete accepted summary receipts' using errcode='PT409';end if;
 select coalesce(jsonb_agg(distinct jsonb_build_object('schema_version',1,'source_id',r->>'source_id','version',(r->>'version')::bigint)),'[]') into manifest
   from jsonb_array_elements(proof.summary_data->'items') i cross join lateral jsonb_array_elements(i->'source_refs') r;
 data:=jsonb_build_object('schema_version',1,'kind','selective_derived_context','maintenance_id',proof.id,
   'coverage_digest',proof.digest,'processed_windows',proof.summary_windows,'processed_through',proof.through_sequence,'items',proof.summary_data->'items');
 fence:=proof.fence||jsonb_build_object('source_revision',project.source_sequence,'lease_token',p_token);
 insert into public.user_lifetime_checkpoint(user_id,conversation_id,predecessor_id,fence,coverage_end,model,prompt_version,pinned,
   manifest,evidence,published,coverage_proof_id,lossless,memory_summary)
 values(snap.user_id,snap.conversation_id,proof.predecessor_id,fence,proof.through_sequence,
   proof.summary_model,'lifetime-v1',page->'preferences',
   jsonb_build_object('schema_version',1,'identity',fence->'identity','policy_epoch',project.policy_epoch,'source_revision',project.source_sequence,'sources',manifest),
   '[]',true,proof.id,false,data) returning id into candidate;
 update public.user_lifetime_conversation set checkpoint_id=candidate where user_id=snap.user_id and conversation_id=snap.conversation_id
   and checkpoint_id is not distinct from proof.predecessor_id;
 if not found then raise exception 'semantic checkpoint CAS failed' using errcode='PT409';end if;
end $$;

CREATE FUNCTION public.purge_lifetime_checkpoint_projections() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.policy_epoch is distinct from new.policy_epoch then
    update public.user_lifetime_conversation set checkpoint_id=null where user_id=new.user_id and project_id=new.project_id;
    delete from public.user_lifetime_checkpoint c using public.user_lifetime_conversation l
      where c.user_id=l.user_id and c.conversation_id=l.conversation_id and l.user_id=new.user_id and l.project_id=new.project_id;
  end if;
  return new;
end $$;

CREATE FUNCTION public.purge_lifetime_compaction() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.policy_epoch is distinct from new.policy_epoch then
    delete from public.user_lifetime_compaction c using public.user_lifetime_conversation l
      where c.user_id=l.user_id and c.conversation_id=l.conversation_id and l.user_id=new.user_id and l.project_id=new.project_id;
  end if;
  return new;
end $$;

CREATE FUNCTION public.purge_lifetime_strategy_projections() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
begin
 if old.policy_epoch is distinct from new.policy_epoch then
   delete from public.user_lifetime_interview_strategy where user_id=new.user_id and project_id=new.project_id;
   update public.user_lifetime_strategy_outcome set question_delivered=null,selected_candidate_id=null
     where user_id=new.user_id and project_id=new.project_id;
   update public.user_lifetime_strategy_frontier set revision=revision+1 where user_id=new.user_id and project_id=new.project_id;
 end if;
 return new;
end $$;

CREATE FUNCTION public.purge_memoir_source_checkpoints() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.version is distinct from new.version or old.status is distinct from new.status then
    delete from public.user_memoir_checkpoint c using public.user_memoir_lane l where c.lane_id=l.id
      and l.user_id=new.user_id and l.project_id=new.project_id and exists
        (select 1 from pg_catalog.jsonb_array_elements(c.source_manifest) ref where ref->>'id'=new.id::text);
  end if;
  return new;
end $$;

CREATE FUNCTION public.queue_memoir_receipt(p_receipt_id uuid, p_cadence integer DEFAULT 5) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare receipt public.user_private_draft_outbox%rowtype; project public.user_memoir_project%rowtype; lane_id uuid; composer_id uuid;
  completed_round bigint; milestone bigint; output_locale text;
  covered bigint; through_milestone bigint;
begin
  if p_cadence is null or p_cadence not between 1 and 1000000 then raise exception 'invalid cadence' using errcode='22023'; end if;
  select * into receipt from public.user_private_draft_outbox where id=p_receipt_id for update;
  if not found then return null; end if;
  if not exists(select 1 from public.user_lifetime_conversation where user_id=receipt.user_id and project_id=receipt.project_id) then
    raise exception 'canonical conversation required' using errcode='42501';
  end if;
  select * into project from public.user_memoir_project where user_id=receipt.user_id and project_id=receipt.project_id for update;
  if not found then return null; end if;
  perform public.assert_lifetime_draft_receipt_scope(receipt.id);
  select coalesce(max(ordinal),0) into completed_round from public.user_completed_round where user_id=receipt.user_id and project_id=receipt.project_id;
  milestone:=(completed_round/p_cadence)*p_cadence;
  select coalesce(profile->>'preferred_language','en-AU') into output_locale from public.user_profile where user_id=receipt.user_id;
  output_locale:=case when output_locale='zh-CN' then 'zh-CN' else 'en-AU' end;
  insert into public.user_lifetime_milestone_cursor(user_id,project_id,locale,cadence)
    values(receipt.user_id,receipt.project_id,output_locale,p_cadence) on conflict do nothing;
  select covered_milestone into covered from public.user_lifetime_milestone_cursor
    where user_id=receipt.user_id and project_id=receipt.project_id and locale=output_locale and cadence=p_cadence for update;
  through_milestone:=least(milestone,covered+128*p_cadence::bigint);
  if through_milestone>covered then
    insert into public.user_memoir_milestone(user_id,project_id,locale,milestone)
      select receipt.user_id,receipt.project_id,output_locale,checkpoint
        from pg_catalog.generate_series(covered+p_cadence::bigint,through_milestone,p_cadence::bigint) checkpoint
      on conflict do nothing;
    update public.user_lifetime_milestone_cursor set covered_milestone=through_milestone
      where user_id=receipt.user_id and project_id=receipt.project_id and locale=output_locale and cadence=p_cadence;
  end if;
  if through_milestone<milestone then
    return pg_catalog.jsonb_build_object('coverage_pending',true,'timeline_lane_id',null,'composer_lane_id',null);
  end if;
  insert into public.user_memoir_lane(user_id,project_id,skill,pending,target_source,target_event)
    values(receipt.user_id,receipt.project_id,'timeline',true,project.source_sequence,project.event_sequence)
    on conflict(user_id,project_id,skill) do update set
      pending=public.user_memoir_lane.pending or exists(select 1 from public.user_narrator_source
        where user_id=receipt.user_id and project_id=receipt.project_id and processing_status<>'succeeded' and status='active'),
      attempts=case when excluded.target_source>public.user_memoir_lane.target_source then 0 else public.user_memoir_lane.attempts end,
      error=case when excluded.target_source>public.user_memoir_lane.target_source then null else public.user_memoir_lane.error end,
      target_source=greatest(public.user_memoir_lane.target_source,excluded.target_source),target_event=excluded.target_event
    returning id into lane_id;
  if milestone>0 then
    insert into public.user_memoir_lane(user_id,project_id,skill,pending,target_source,target_event,target_milestone,locale)
      values(receipt.user_id,receipt.project_id,'composer',true,project.source_sequence,project.event_sequence,milestone,output_locale)
      on conflict(user_id,project_id,skill) do update set
        pending=public.user_memoir_lane.pending or excluded.locale<>public.user_memoir_lane.locale or excluded.target_milestone>public.user_memoir_lane.target_milestone or
          (receipt.change_kind in ('correction','revocation','edit','delete') and
            (excluded.target_event>public.user_memoir_lane.successful_event or excluded.target_source>public.user_memoir_lane.successful_source)),
        attempts=case when excluded.target_milestone>public.user_memoir_lane.target_milestone or excluded.target_event>public.user_memoir_lane.target_event then 0 else public.user_memoir_lane.attempts end,
        error=case when excluded.target_milestone>public.user_memoir_lane.target_milestone or excluded.target_event>public.user_memoir_lane.target_event then null else public.user_memoir_lane.error end,
        target_source=excluded.target_source,target_event=excluded.target_event,target_milestone=excluded.target_milestone,locale=excluded.locale
      returning id into composer_id;
  end if;
  update public.user_private_draft_outbox set delivered=true where id=p_receipt_id;
  return pg_catalog.jsonb_build_object('timeline_lane_id',lane_id,'composer_lane_id',composer_id);
end $$;

CREATE FUNCTION public.read_formal_memoir_chapter(p_run_id uuid, p_token uuid, p_ordinal integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare run public.user_formal_memoir_run%rowtype; plan public.user_formal_memoir_plan%rowtype;
begin
 run:=public.lock_formal_memoir_run(p_run_id,p_token);
 select * into plan from public.user_formal_memoir_plan where run_id=run.id and ordinal=p_ordinal;
 if not found then raise exception 'FORMAL_CHAPTER_UNAVAILABLE' using errcode='22023';end if;
 return jsonb_build_object('run_id',run.id,'token',run.token,'fence',run.fence,'plan_digest',run.plan_digest,
   'ordinal',plan.ordinal,'chapter_id',plan.chapter_id,'title',plan.title,'event_id',plan.event_id,
   'event_revision',plan.event_revision,'evidence',plan.evidence,'chapter_plan_digest',plan.digest);
end $$;

CREATE FUNCTION public.read_formal_memoir_status(p_project_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner uuid:=auth.uid(); run public.user_formal_memoir_run%rowtype; edition jsonb;
begin
 if owner is null or not exists(select 1 from public.user_lifetime_conversation where user_id=owner and project_id=p_project_id) then
   raise exception 'FORMAL_OWNER_REQUIRED' using errcode='42501';end if;
 perform 1 from public.user_memoir_project where user_id=owner and project_id=p_project_id for share;
 -- Preference invalidation owns identity without requesting project. Wait for
 -- that whole transaction before reading run and edition metadata together.
 perform 1 from public.user_lifetime_conversation where user_id=owner and project_id=p_project_id for share;
 select * into run from public.user_formal_memoir_run where user_id=owner and project_id=p_project_id order by created_at desc,id desc limit 1;
 select result into edition from public.user_formal_memoir_edition where user_id=owner and project_id=p_project_id and active;
 return jsonb_build_object('schema_version',1,'run',case when run.id is not null then public.formal_memoir_run_record(run) end,'edition',edition);
end $$;

CREATE FUNCTION public.read_lifetime_checkpoint(p_conversation_id uuid, p_policy_epoch bigint, p_model text, p_prompt_version text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare result jsonb; summary jsonb;
begin
 result:=public.read_lifetime_checkpoint_before_semantic(p_conversation_id,p_policy_epoch,p_model,p_prompt_version);
 if result is null then return null;end if;
 select c.memory_summary into summary from public.user_lifetime_checkpoint c where c.user_id=auth.uid() and c.id=(result->>'checkpoint_id')::uuid;
 if summary is not null then
   if not exists(select 1 from public.user_lifetime_compaction p where p.user_id=auth.uid()
     and p.id=(summary->>'maintenance_id')::uuid and p.complete and p.summary_complete
     and p.digest=summary->>'coverage_digest' and p.through_sequence=(result->>'coverage_end')::bigint)
     or exists(select 1 from jsonb_array_elements(summary->'items') i cross join lateral jsonb_array_elements(i->'source_refs') r
       where not exists(select 1 from public.user_narrator_source s join public.user_lifetime_conversation l
         on l.user_id=s.user_id and l.project_id=s.project_id and l.conversation_id=p_conversation_id
         where s.user_id=auth.uid() and s.id=(r->>'source_id')::uuid and s.version=(r->>'version')::bigint and s.status='active')) then return null;end if;
   result:=result||jsonb_build_object('memory_summary',summary);
 end if;
 return result;
end $$;

CREATE FUNCTION public.read_lifetime_checkpoint_before(p_conversation_id uuid, p_policy_epoch bigint, p_model text, p_prompt_version text, p_before_sequence bigint, p_require_accepted boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare saved public.user_lifetime_checkpoint%rowtype; result jsonb; summary jsonb;
begin
 -- Reuse canonical owner, current-policy and pending-policy admission guards.
 result:=public.read_lifetime_checkpoint(p_conversation_id,p_policy_epoch,p_model,p_prompt_version);
 if p_before_sequence is null or p_before_sequence<1 then raise exception 'current source position required';end if;
 if result is not null and (result->>'coverage_end')::bigint<p_before_sequence and
   (not p_require_accepted or exists(select 1 from public.user_lifetime_checkpoint c where c.id=(result->>'checkpoint_id')::uuid
     and (c.lossless or c.memory_summary is not null))) then return result;end if;
 select * into saved from public.user_lifetime_checkpoint c where c.user_id=auth.uid() and c.conversation_id=p_conversation_id
   and c.published and c.fence->>'policy_epoch'=p_policy_epoch::text and c.model=p_model and c.prompt_version=p_prompt_version
   and c.coverage_end<p_before_sequence and (not p_require_accepted or c.lossless or c.memory_summary is not null)
   order by c.coverage_end desc,c.created_at desc limit 1;
 if not found then return null;end if;
 summary:=saved.memory_summary;
 if summary is not null then
   if not exists(select 1 from public.user_lifetime_compaction p where p.user_id=auth.uid() and p.id=(summary->>'maintenance_id')::uuid
      and p.complete and p.summary_complete and p.digest=summary->>'coverage_digest' and p.through_sequence=saved.coverage_end)
      or exists(select 1 from jsonb_array_elements(summary->'items') i cross join lateral jsonb_array_elements(i->'source_refs') r
        where not exists(select 1 from public.user_narrator_source n join public.user_lifetime_conversation l
          on l.user_id=n.user_id and l.project_id=n.project_id and l.conversation_id=p_conversation_id
          where n.user_id=auth.uid() and n.id=(r->>'source_id')::uuid and n.version=(r->>'version')::bigint and n.status='active')) then return null;end if;
 end if;
 result:=jsonb_build_object('schema_version',1,'checkpoint_id',saved.id,'predecessor_id',saved.predecessor_id,
   'identity',saved.fence->'identity','policy_epoch',p_policy_epoch,'coverage_end',saved.coverage_end,'model',saved.model,
   'prompt_version',saved.prompt_version,'pinned',public.read_lifetime_pinned(p_conversation_id),'manifest',saved.manifest,'evidence',saved.evidence);
 if summary is not null then result:=result||jsonb_build_object('memory_summary',summary);end if;
 return result;
end $$;

CREATE FUNCTION public.read_lifetime_checkpoint_before_semantic(p_conversation_id uuid, p_policy_epoch bigint, p_model text, p_prompt_version text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare identity public.user_lifetime_conversation%rowtype; saved public.user_lifetime_checkpoint%rowtype; epoch bigint;
begin
  select * into identity from public.user_lifetime_conversation where user_id=auth.uid() and conversation_id=p_conversation_id;
  if not found then raise exception 'conversation unavailable'; end if;
  select policy_epoch into epoch from public.user_memoir_project where user_id=auth.uid() and project_id=identity.project_id for share;
  if epoch is distinct from p_policy_epoch then raise exception 'stale checkpoint policy' using errcode='PT409'; end if;
  select * into identity from public.user_lifetime_conversation where user_id=auth.uid() and conversation_id=p_conversation_id;
  select * into saved from public.user_lifetime_checkpoint where id=identity.checkpoint_id and published
    and fence->>'policy_epoch'=epoch::text and model=p_model and prompt_version=p_prompt_version;
  if not found then return null; end if;
  return jsonb_build_object('schema_version',1,'checkpoint_id',saved.id,'predecessor_id',saved.predecessor_id,
    'identity',saved.fence->'identity','policy_epoch',epoch,'coverage_end',saved.coverage_end,
    'model',saved.model,'prompt_version',saved.prompt_version,'pinned',public.read_lifetime_pinned(p_conversation_id),
    'manifest',saved.manifest,'evidence',saved.evidence);
end $$;

CREATE FUNCTION public.read_lifetime_collection_job(p_job_id uuid, p_cursor uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 8) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare job public.user_lifetime_collection_job%rowtype; cursor_row public.user_lifetime_collection_job_cursor%rowtype;
 after_page integer:=0; result_after integer; items jsonb; result jsonb; next_cursor uuid; complete boolean;
begin
 if p_limit is null or p_limit not between 1 and 8 then raise exception 'invalid result page limit';end if;
 select * into job from public.user_lifetime_collection_job where id=p_job_id and user_id=auth.uid();
 if not found then raise exception 'collection job unavailable' using errcode='42501';end if;
 job:=public.lock_lifetime_collection_job(p_job_id);
 if p_cursor is not null then
  select * into cursor_row from public.user_lifetime_collection_job_cursor where id=p_cursor and job_id=job.id and user_id=auth.uid();
  if not found or cursor_row.expires_at<=clock_timestamp() or cursor_row.root_digest<>job.root_digest then raise exception 'stale result cursor' using errcode='PT409';end if;
  after_page:=cursor_row.next_page;
 end if;
 if job.state='SUCCEEDED' then
  select coalesce(jsonb_agg(item order by page_number),'[]'),coalesce(max(page_number)+1,after_page) into items,result_after from (
   select p.page_number,jsonb_build_object('id',s.id,'version',s.version,'content',substring(s.text from p.char_start+1 for p.char_end-p.char_start),
    'char_start',p.char_start,'char_end',p.char_end,'original_length',length(s.text),'source_kind',s.kind,'language',s.language,'root_section_id',case when job.kind='BuildOutline' then public.lifetime_collection_root_section(job.id,p.page_number) else null end) item
   from public.user_lifetime_collection_job_page p join public.user_narrator_source s on s.id=p.source_id
    and s.user_id=job.user_id and s.project_id=job.project_id and s.version=p.source_version
   where p.job_id=job.id and p.page_number>=after_page order by p.page_number limit p_limit) bounded;
  complete:=result_after>=job.source_pages;
  if not complete then
   insert into public.user_lifetime_collection_job_cursor(job_id,user_id,root_digest,next_page) values(job.id,job.user_id,job.root_digest,result_after)
    on conflict(job_id,root_digest,next_page) do update set expires_at=clock_timestamp()+interval '1 hour' returning id into next_cursor;
  end if;
  result:=jsonb_build_object('schema_version',1,'kind',job.kind,'title',job.title,'sources',items,
   'coverage',jsonb_build_object('complete',true,'scope','selected_sources','source_count',job.source_count,'source_pages',job.source_pages,
    'manifest_digest',job.manifest_digest,'root_digest',job.root_digest),'proposed',job.kind='BuildOutline');
  if job.kind='BuildOutline' then
   result:=result||jsonb_build_object('sections',(select metadata->'sections' from public.user_lifetime_collection_job_node where job_id=job.id and parent_id is null),
    'suggested_title',(select metadata->>'title' from public.user_lifetime_collection_job_node where job_id=job.id and parent_id is null),
    'source_references_paginated',true,'provenance','derived_proposal','publication_approved',false);
  end if;
  if job.kind='BuildFreePreview' then result:=result||jsonb_build_object('blocks',coalesce((select jsonb_agg(jsonb_build_object(
   'type','narrative','text',v->>'content','source_memory_ids',jsonb_build_array(v->>'id'),'char_start',v->'char_start','char_end',v->'char_end')) from jsonb_array_elements(items)v),'[]'));end if;
 else complete:=false;end if;
 return jsonb_build_object('id',job.id,'project_id',job.project_id,'kind',job.kind,'status',job.state,'attempts',job.attempts,
  'created_at',job.created_at,'result',result,'error',job.error,'root_digest',job.root_digest,'complete',complete,'next_cursor',next_cursor,
  'progress',jsonb_build_object('completed_pages',job.next_page,'source_pages',job.source_pages));
end $$;

CREATE FUNCTION public.read_lifetime_collection_job_page(p_job_id uuid, p_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare job public.user_lifetime_collection_job%rowtype; selected public.user_lifetime_collection_job_source%rowtype;
 source public.user_narrator_source%rowtype; lo integer; hi integer; preferences jsonb; payload jsonb; previous_owner text;
 children jsonb:='[]'; child record; source_items jsonb:='[]'; phase text:='leaf';
begin
 -- Successful final page is a stable completion receipt; it contains no source bytes.
 select * into job from public.user_lifetime_collection_job where id=p_job_id;
 if job.state='SUCCEEDED' and job.token=p_token then
  perform public.lock_lifetime_collection_job(p_job_id);return jsonb_build_object('complete',true,'job_id',job.id,'root_digest',job.root_digest);end if;
 job:=public.lock_lifetime_collection_job(p_job_id,p_token);
 if job.next_page<job.source_pages then
 select * into selected from public.user_lifetime_collection_job_source where job_id=job.id and job.next_page>=first_page and job.next_page<first_page+page_count;
 select * into source from public.user_narrator_source where user_id=job.user_id and project_id=job.project_id and id=selected.source_id;
 lo:=(job.next_page-selected.first_page)*2048;hi:=least(lo+2048,selected.original_length);
 source_items:=jsonb_build_array(jsonb_build_object('id',source.id,'project_id',source.project_id,'version',source.version,'sequence',source.sequence,
   'text',substring(source.text from lo+1 for hi-lo),'char_start',lo,'char_end',hi,'original_length',selected.original_length,
   'kind',source.kind,'language',source.language,'status',source.status,'author_role','storyteller'));
 else
  phase:='merge';
  for child in select metadata from public.user_lifetime_collection_job_node where job_id=job.id and parent_id is null order by level,ordinal limit 2 loop
   children:=children||jsonb_build_array(child.metadata);
  end loop;
  if jsonb_array_length(children)<2 then raise exception 'outline merge budget requires maintenance' using errcode='54000';end if;
 end if;
 previous_owner:=current_setting('request.jwt.claim.sub',true);perform set_config('request.jwt.claim.sub',job.user_id::text,true);
 preferences:=public.read_lifetime_pinned(job.conversation_id);
 preferences:=jsonb_set(preferences,'{known_continuity}',coalesce((select jsonb_agg(jsonb_build_object('schema_version',1)||record||jsonb_build_object('data',
  jsonb_build_object('schema_version',1,'uncertainty',null)||(record->'data')||jsonb_build_object('source_refs',
   (select jsonb_agg(jsonb_build_object('schema_version',1)||ref) from jsonb_array_elements(record->'data'->'source_refs')ref))))
  from jsonb_array_elements(preferences->'known_continuity')record),'[]'));
 perform set_config('request.jwt.claim.sub',coalesce(previous_owner,''),true);
 payload:=jsonb_build_object('schema_version',1,'protocol','lifetime_collection_jobs','job_id',job.id,'token',job.token,
  'snapshot_id',job.snapshot_id,'user_id',job.user_id,'project_id',job.project_id,'conversation_id',job.conversation_id,
  'kind',job.kind,'locale',job.locale,'policy_epoch',job.policy_epoch,'preference_revision',job.preference_revision,
  'collection_revision',job.collection_revision,'root_digest',job.root_digest,'page_number',job.next_page,'preferences',preferences,
  'phase',phase,'sources',source_items,'child_groups',children);
 return payload||jsonb_build_object('page_digest',encode(sha256(convert_to(payload::text,'UTF8')),'hex'),'complete',false);
end $$;

CREATE FUNCTION public.read_lifetime_collection_job_scope(p_job_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
 select jsonb_build_object('id',id,'project_id',project_id) from public.user_lifetime_collection_job where id=p_job_id and user_id=auth.uid();
$$;

CREATE FUNCTION public.read_lifetime_collection_page(p_project_id text, p_kind text, p_after uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 8, p_event_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb;
begin
 result:=public.read_lifetime_collection_page_before_attribution(p_project_id,p_kind,p_after,p_limit,p_event_id);
 if p_kind='sources' and exists(select 1 from public.lifetime_two_lane_rollout where singleton and enabled) then
   result:=jsonb_set(result,'{sources}',coalesce((select jsonb_agg(s||jsonb_build_object('attribution',
     public.lifetime_source_attribution_summary(auth.uid(),p_project_id,(s->>'id')::uuid))) from jsonb_array_elements(result->'sources') s),'[]'));
 end if;
 return result;
end $$;

CREATE FUNCTION public.read_lifetime_collection_page_before_attribution(p_project_id text, p_kind text, p_after uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 8, p_event_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare owner uuid:=auth.uid(); identity public.user_lifetime_conversation%rowtype; project public.user_memoir_project%rowtype;
 cursor_row public.user_lifetime_read_cursor%rowtype; records jsonb; extra boolean; cursor_id uuid;
 boundary_sequence bigint:=0; boundary_key text:=''; row_key text; row_sequence bigint;
 source_key text; event_record public.user_memory_event%rowtype; evidence_page jsonb;
begin
 if owner is null or p_limit is null or p_limit not between 1 and 8 or p_kind not in ('sources','events','event_sources','event_details') or
   (p_kind in ('event_sources','event_details') and (p_event_id is null or length(p_event_id)>128)) or (p_kind not in ('event_sources','event_details') and p_event_id is not null)
   then raise exception 'invalid canonical page' using errcode='22023';end if;
 select * into identity from public.user_lifetime_conversation where user_id=owner and project_id=p_project_id;
 if not found then raise exception 'canonical conversation unavailable' using errcode='42501';end if;
 select * into project from public.user_memoir_project where user_id=owner and project_id=p_project_id for share;
 perform 1 from public.user_profile where user_id=owner for share;
 select * into identity from public.user_lifetime_conversation where conversation_id=identity.conversation_id for share;
 if p_after is not null then
   select * into cursor_row from public.user_lifetime_read_cursor where id=p_after and user_id=owner and project_id=p_project_id
     and conversation_id=identity.conversation_id and kind=p_kind and event_id is not distinct from p_event_id;
   if not found then raise exception 'page cursor scope mismatch' using errcode='22023';end if;
   if cursor_row.policy_epoch<>project.policy_epoch or cursor_row.preference_revision<>identity.preference_revision or
     cursor_row.source_revision<>project.source_sequence or cursor_row.event_revision<>project.event_sequence then
     raise exception 'page changed; restart from the first page' using errcode='PT409';end if;
   boundary_sequence:=cursor_row.after_sequence;boundary_key:=cursor_row.after_key;
 end if;
 if p_kind='sources' then
   select coalesce(jsonb_agg(public.narrator_source_record(s) order by s.sequence,s.id),'[]') into records from
     (select n.* from public.user_narrator_source n where user_id=owner and project_id=p_project_id and status='active'
       and sequence>boundary_sequence order by sequence,id limit p_limit+1) s;
 elsif p_kind='event_details' then
   select * into event_record from public.user_memory_event where user_id=owner and project_id=p_project_id and id=p_event_id and status<>'withdrawn';
   if not found then raise exception 'event unavailable' using errcode='42501';end if;
   select coalesce(jsonb_agg(item order by key),'[]') into records from (
     select kind||':'||lpad(ordinal::text,20,'0') key,jsonb_build_object('detail_key',kind||':'||lpad(ordinal::text,20,'0'),
       'kind',kind,'value',case kind when 'temporal_accounts' then (value->'temporal')-'basis'
         when 'relations' then value-'source_refs' else value end,'evidence_available_separately',true) item
     from unnest(array['temporal_accounts','relations','candidate_ids','supersedes','contradicts']) kind,
       lateral jsonb_array_elements(case when jsonb_typeof(event_record.data->kind)='array' then event_record.data->kind else '[]'::jsonb end)
         with ordinality detail(value,ordinal)
     where kind||':'||lpad(ordinal::text,20,'0')>boundary_key order by key limit p_limit+1) selected;
 elsif p_kind='event_sources' then
   if not exists(select 1 from public.user_memory_event where user_id=owner and project_id=p_project_id and id=p_event_id and status<>'withdrawn')
     then raise exception 'event unavailable' using errcode='42501';end if;
   select coalesce(jsonb_agg(item order by key),'[]') into records from (
     select s.source_id::text||':'||s.source_version::text||':'||s.evidence_hash key,
       s.evidence||jsonb_build_object('evidence_key',s.source_id::text||':'||s.source_version::text||':'||s.evidence_hash) item
     from public.user_memory_event_source s join public.user_narrator_source n
       on n.user_id=s.user_id and n.project_id=s.project_id and n.id=s.source_id and n.version=s.source_version and n.status='active'
     where s.user_id=owner and s.project_id=p_project_id and s.event_id=p_event_id
       and s.source_id::text||':'||s.source_version::text||':'||s.evidence_hash>boundary_key
     order by key limit p_limit+1) selected;
 else
   records:='[]';
   for event_record in select e.* from public.user_memory_event e where user_id=owner and project_id=p_project_id and status<>'withdrawn'
     and (change_sequence,id)>(boundary_sequence,boundary_key) order by change_sequence,id limit p_limit+1 loop
     -- The complete evidence set is separately paginated; never aggregate all
     -- source_refs or embed accumulated relationship/basis arrays in a list.
     evidence_page:=public.read_lifetime_collection_page(p_project_id,'event_sources',null,1,event_record.id);
     records:=records||jsonb_build_array(jsonb_build_object('id',event_record.id,'revision',event_record.revision,
       'kind',event_record.kind,'life_stage',event_record.life_stage,'status',event_record.status,
       'change_sequence',event_record.change_sequence,'title',event_record.data->'title',
       'temporal',jsonb_build_object('expression',event_record.data->'temporal'->'expression',
         'precision',event_record.data->'temporal'->'precision','year_start',event_record.data->'temporal'->'year_start',
         'year_end',event_record.data->'temporal'->'year_end'),
       'uncertainty',event_record.data->'uncertainty','assertion',event_record.data->'assertion',
       'locationConfidenceScore',event_record.data->'locationConfidenceScore','yearConfidenceScore',event_record.data->'yearConfidenceScore',
       'timing_conflict',coalesce(event_record.data->'timing_conflict','false'),
       'details_complete',not exists(select 1 from unnest(array['temporal_accounts','relations','candidate_ids','supersedes','contradicts']) k
         where jsonb_typeof(event_record.data->k)='array' and jsonb_array_length(event_record.data->k)>0),
       'visibility',event_record.data->'visibility',
       'include_in_print',event_record.data->'include_in_print','source_refs',evidence_page->'source_refs',
       'evidence_complete',evidence_page->'complete','evidence_next_cursor',evidence_page->'next_cursor'));
   end loop;
 end if;
 extra:=jsonb_array_length(records)>p_limit;
 if extra then
   records:=records-p_limit;
   row_key:=case p_kind when 'event_details' then records->-1->>'detail_key' when 'event_sources' then records->-1->>'evidence_key' when 'events' then records->-1->>'id' else '' end;
   row_sequence:=case p_kind when 'sources' then (records->-1->>'sequence')::bigint when 'events' then (records->-1->>'change_sequence')::bigint else 0 end;
   insert into public.user_lifetime_read_cursor(user_id,project_id,conversation_id,kind,event_id,policy_epoch,preference_revision,
     source_revision,event_revision,after_sequence,after_key) values(owner,p_project_id,identity.conversation_id,p_kind,p_event_id,
     project.policy_epoch,identity.preference_revision,project.source_sequence,project.event_sequence,row_sequence,row_key) returning id into cursor_id;
 end if;
 return jsonb_build_object('schema_version',1,'project_id',p_project_id,'conversation_id',identity.conversation_id,
   'source_revision',project.source_sequence,'event_revision',project.event_sequence,'policy_epoch',project.policy_epoch,
   'coverage_scope','current_revision_page','complete',not extra,'next_cursor',cursor_id,
   case p_kind when 'event_details' then 'details' when 'event_sources' then 'source_refs' else p_kind end,records,
   'processing',jsonb_build_object('extracted_through',project.extraction_cursor,'pending_inputs',
     (select count(*) from public.user_narrator_source where user_id=owner and project_id=p_project_id and status='active' and processing_status<>'succeeded')));
end $$;

CREATE FUNCTION public.read_lifetime_collection_selection(p_project_id text, p_after uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 8) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare owner uuid:=auth.uid(); doc public.user_lifetime_collection%rowtype; tasks jsonb;
 anchor public.user_lifetime_collection_job%rowtype; more boolean; next_cursor uuid;
begin
 if owner is null or not exists(select 1 from public.user_lifetime_conversation where user_id=owner and project_id=p_project_id) then
  raise exception 'collection unavailable' using errcode='42501';end if;
 if p_limit is null or p_limit<1 or p_limit>8 then raise exception 'invalid page bound' using errcode='22023';end if;
 if p_after is not null then
  select * into anchor from public.user_lifetime_collection_job where id=p_after and user_id=owner and project_id=p_project_id;
  if not found then raise exception 'task cursor unavailable' using errcode='42501';end if;
 end if;
 select * into doc from public.user_lifetime_collection where user_id=owner and project_id=p_project_id;
 with bounded as materialized (
  select id,created_at,jsonb_build_object('id',id,'project_id',project_id,'kind',kind,'status',state,'attempts',attempts,
   'result',null,'error',error,'created_at',created_at) item from public.user_lifetime_collection_job
  where user_id=owner and project_id=p_project_id and (p_after is null or (created_at,id)<(anchor.created_at,anchor.id))
  order by created_at desc,id desc limit p_limit+1
 ), visible as (select * from bounded order by created_at desc,id desc limit p_limit)
 select coalesce((select jsonb_agg(item order by created_at desc,id desc) from visible),'[]'),
  (select count(*)>p_limit from bounded),(select id from visible order by created_at,id limit 1)
 into tasks,more,next_cursor;
 return jsonb_build_object('revision',coalesce(doc.revision,0),'periods',coalesce(doc.periods,'{}'),'ready',
  coalesce(doc.ready,false) and exists(select 1 from public.user_memoir_project p join public.user_lifetime_conversation i using(user_id,project_id)
   where p.user_id=owner and p.project_id=p_project_id and p.source_sequence=doc.source_revision
    and p.policy_epoch=doc.policy_epoch and i.preference_revision=doc.preference_revision),
  'source_fingerprint',doc.source_fingerprint,'tasks',tasks,'tasks_complete',not more,
  'tasks_next_cursor',case when more then next_cursor else null end,
  'workflow','canonical_selected_jobs','legacy_jobs_supported',false);
end $$;

CREATE FUNCTION public.read_lifetime_continuity(p_conversation_id uuid, p_policy_epoch bigint, p_after text DEFAULT ''::text, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare owner uuid:=auth.uid(); project text; epoch bigint; records jsonb; has_more boolean;
begin
  select project_id into project from public.user_lifetime_conversation where user_id=owner and conversation_id=p_conversation_id;
  if not found then raise exception 'conversation unavailable'; end if;
  select policy_epoch into epoch from public.user_memoir_project where user_id=owner and project_id=project for share;
  if epoch is distinct from p_policy_epoch then raise exception 'stale policy' using errcode='PT409'; end if;
  if p_limit is null or p_limit not between 1 and 100 or p_after is null then raise exception 'invalid page'; end if;
  select coalesce(jsonb_agg(to_jsonb(r)-'user_id'-'conversation_id'-'last_source_sequence' order by r.record_id),'[]') into records from (
    select c.* from public.user_lifetime_continuity c where c.user_id=owner and c.conversation_id=p_conversation_id
      and c.policy_epoch=epoch and c.record_id>p_after
      and not exists(select 1 from jsonb_array_elements(c.data->'source_refs') ref where not exists(
        select 1 from public.user_narrator_source s where s.user_id=owner and s.project_id=project
          and s.id=(ref->>'source_id')::uuid and s.version=(ref->>'version')::bigint and s.status='active'))
    order by c.record_id limit p_limit+1) r;
  has_more:=jsonb_array_length(records)>p_limit;
  if has_more then records:=records-p_limit; end if;
  return jsonb_build_object('schema_version',1,'records',records,'complete',not has_more,
    'next_cursor',case when has_more then records->-1->>'record_id' else null end);
end;
$$;

CREATE FUNCTION public.read_lifetime_current_mode(p_project_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare outcome public.user_lifetime_strategy_outcome%rowtype; result jsonb;
begin
 perform 1 from public.user_memoir_project where user_id=auth.uid() and project_id=p_project_id for share;
 if not found then raise exception 'owned project required' using errcode='42501';end if;
 if public.lifetime_interview_strategy_rollout(auth.uid())<>'active'
   then return null;end if;
 select * into outcome from public.user_lifetime_strategy_outcome where user_id=auth.uid() and project_id=p_project_id
   and delivered order by source_sequence desc limit 1;
 select jsonb_build_object('project_id',p_project_id,'mode',outcome.used_strategy,'client_turn_id',outcome.client_turn_id,'reply_id',outcome.reply_id,
   'source_id',outcome.source_id,'source_sequence',outcome.source_sequence,'plan_revision_seen',outcome.plan_revision_seen,
   'policy_epoch',r.policy_epoch,'preference_revision',r.preference_revision,'execution_generation',r.execution_generation)
 into result from public.user_lifetime_reply r
 join public.user_lifetime_conversation c on c.user_id=r.user_id and c.conversation_id=r.conversation_id
 join public.user_memoir_project p on p.user_id=c.user_id and p.project_id=c.project_id
 join public.user_narrator_source s on s.user_id=p.user_id and s.project_id=p.project_id and s.id=outcome.source_id
 where r.user_id=auth.uid() and r.memory_id=outcome.reply_id and c.project_id=p_project_id
   and outcome.used_strategy in ('comfort','explore','shape') and s.status='active' and s.sequence=outcome.source_sequence
   and s.sequence=p.source_sequence and r.policy_epoch=p.policy_epoch and r.preference_revision=c.preference_revision
   and r.execution_generation=c.execution_generation;
 return result;
end $$;

CREATE FUNCTION public.read_lifetime_event_places(p_project_id text, p_event_id text, p_after uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 8) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner uuid:=auth.uid(); project public.user_memoir_project%rowtype; identity public.user_lifetime_conversation%rowtype;
 cursor_row public.user_lifetime_read_cursor%rowtype; records jsonb; last_key text:=''; more boolean; cursor_id uuid; conflicts text[];
begin
 if p_limit is null or p_limit not between 1 and 8 then raise exception 'bounded event place page required' using errcode='22023';end if;
 select * into project from public.user_memoir_project where user_id=owner and project_id=p_project_id for share;
 select * into identity from public.user_lifetime_conversation where user_id=owner and project_id=p_project_id;
 if not found or not exists(select 1 from public.user_memory_event where user_id=owner and project_id=p_project_id and id=p_event_id and status='active') then
   raise exception 'owned active event required' using errcode='42501';end if;
 if p_after is not null then
   select * into cursor_row from public.user_lifetime_read_cursor where id=p_after and user_id=owner and project_id=p_project_id
     and kind='event_places' and event_id=p_event_id;
   if not found then raise exception 'event place cursor scope mismatch' using errcode='22023';end if;
   if cursor_row.policy_epoch<>project.policy_epoch or cursor_row.source_revision<>project.source_sequence
     or cursor_row.event_revision<>project.event_sequence or cursor_row.attribution_revision<>project.attribution_revision
     or cursor_row.preference_revision<>identity.preference_revision then raise exception 'event place page changed' using errcode='40001';end if;
   last_key:=cursor_row.after_key;
 end if;
 conflicts:=public.lifetime_event_place_conflicts(owner,p_project_id,p_event_id);
 select coalesce(jsonb_agg(item order by key),'[]') into records from (
   select source_id::text||':'||source_version||':'||lpad(char_start::text,8,'0')||':'||lpad(char_end::text,8,'0')||':'||role||':'||place_key key,
     to_jsonb(p)-array['user_id','project_id']||jsonb_build_object('status',case when role=any(conflicts) then 'conflicted' else 'supported' end,
       'key',source_id::text||':'||source_version||':'||
       lpad(char_start::text,8,'0')||':'||lpad(char_end::text,8,'0')||':'||role||':'||place_key) item
   from public.lifetime_event_place_rows(owner,p_project_id,p_event_id) p
   where source_id::text||':'||source_version||':'||lpad(char_start::text,8,'0')||':'||lpad(char_end::text,8,'0')||':'||role||':'||place_key>last_key
   order by key limit p_limit+1) bounded;
 more:=jsonb_array_length(records)>p_limit;
 if more then
   records:=records-p_limit;
   insert into public.user_lifetime_read_cursor(user_id,project_id,conversation_id,kind,event_id,policy_epoch,
     preference_revision,source_revision,event_revision,attribution_revision,after_key)
   values(owner,p_project_id,identity.conversation_id,'event_places',p_event_id,project.policy_epoch,identity.preference_revision,
     project.source_sequence,project.event_sequence,project.attribution_revision,records->-1->>'key') returning id into cursor_id;
 end if;
 return jsonb_build_object('event_id',p_event_id,'items',records,'next_cursor',cursor_id,'complete',not more);
end $$;

CREATE FUNCTION public.read_lifetime_interview_context(p_conversation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare owner uuid:=auth.uid(); project text; plan jsonb; events jsonb; coverage jsonb; dialogue jsonb;
begin
 select project_id into project from public.user_lifetime_conversation where user_id=owner and conversation_id=p_conversation_id;
 if not found then raise exception 'conversation unavailable'; end if;
 perform 1 from public.user_memoir_project where user_id=owner and project_id=project for share;
 select p.plan into plan from public.user_interview_plan p where user_id=owner and project_id=project;
 -- Derived titles and uncertainty are not original evidence. Give Mira the
 -- bounded coordinates and authorized original passages behind saved events.
 select coalesce(jsonb_agg(
   jsonb_set(public.bounded_lifetime_event_record(e),'{temporal,expression}','null')||
   '{"title":null,"title_complete":false,"uncertainty":null,"uncertainty_complete":false,"temporal_complete":false}'::jsonb||
   jsonb_build_object('original_passages',coalesce((select jsonb_agg(passage) from (
     select w passage from public.user_memory_event_source r cross join lateral
       public.lifetime_guidance_source_windows(r.user_id,r.project_id,r.source_id,r.source_version,
         coalesce((r.evidence->>'char_start')::integer,0),
         least(coalesce((r.evidence->>'char_end')::integer,2147483647),
           coalesce((r.evidence->>'char_start')::integer,0)+500)) w
     where r.user_id=e.user_id and r.project_id=e.project_id and r.event_id=e.id
     order by r.source_id,r.source_version,r.evidence_hash limit 2
   ) originals),'[]'::jsonb))),'[]') into events from (select e.* from public.user_memory_event e
 where e.user_id=owner and e.project_id=project and e.status='active'
 and not exists(select 1 from public.user_memory_event_source r where r.user_id=owner and r.project_id=project and r.event_id=e.id
   and not exists(select 1 from public.user_narrator_source s where s.user_id=owner and s.project_id=project and s.id=r.source_id
     and s.version=r.source_version and s.status='active'
     and not exists(select 1 from public.user_memory_attribution_window w where w.user_id=s.user_id and w.project_id=s.project_id
       and w.source_id=s.id and w.source_version=s.version and w.disposition in ('withheld','non_story')
       and w.char_start<coalesce((r.evidence->>'char_end')::integer,length(s.text))
       and w.char_end>coalesce((r.evidence->>'char_start')::integer,0)))) order by e.change_sequence desc,e.id limit 8) e;
 -- Count canonical events with current original evidence, never raw turns or word volume.
 with grounded as (
   select e.id,e.life_stage,max(s.sequence) last_sequence
   from public.user_memory_event e
   join public.user_memory_event_source r on r.user_id=e.user_id and r.project_id=e.project_id and r.event_id=e.id
   join public.user_narrator_source s on s.user_id=r.user_id and s.project_id=r.project_id and s.id=r.source_id
     and s.version=r.source_version and s.status='active'
   where e.user_id=owner and e.project_id=project and e.status='active' and e.kind='event'
     and e.life_stage<>'unplaced' and length(btrim(coalesce(e.data->>'title','')))>0
     and r.stage_progress_role in ('primary','stage','legacy_primary','legacy_stage')
     and not exists(select 1 from public.user_memory_event_source bad
       where bad.user_id=e.user_id and bad.project_id=e.project_id and bad.event_id=e.id
         and not exists(select 1 from public.user_narrator_source original
           where original.user_id=bad.user_id and original.project_id=bad.project_id and original.id=bad.source_id
             and original.version=bad.source_version and original.status='active'))
     and not exists(select 1 from public.user_memory_event_source_exclusion x
       where x.user_id=e.user_id and x.project_id=e.project_id and x.event_id=e.id)
   group by e.id,e.life_stage
 ) select coalesce(jsonb_agg(row),'[]') into coverage from (
   select life_stage,count(*) grounded_events,max(last_sequence) last_source_sequence
   from grounded group by life_stage order by life_stage) row;
 -- Mira reads current authorized conversation and saved results directly.
 dialogue:=public.lifetime_question_dialogue(owner,project);
 return jsonb_build_object('plan',plan,'events',events,'stage_coverage',coverage,'photos','[]'::jsonb,'photo_associations','[]'::jsonb,
   'recent_dialogue',dialogue,
   'historical_context_complete',false,'historical_news',public.read_user_historical_news(project),
   'has_accepted_narration',public.conversation_has_narration(owner,project));
end $$;

CREATE FUNCTION public.read_lifetime_lane_policy_source(p_lane_id uuid, p_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare page jsonb; original public.user_narrator_source%rowtype;
begin
 page:=public.read_lifetime_memoir_lane_page(p_lane_id,p_token);
 if page->>'skill'<>'timeline' or (page->>'complete')::boolean then raise exception 'timeline source page required';end if;
 select * into original from public.user_narrator_source where user_id=(page->>'user_id')::uuid and project_id=page->>'project_id'
   and id=(page->'source'->>'id')::uuid and version=(page->'source'->>'version')::bigint and status='active';
 if not found then raise exception 'stale source policy original';end if;
 return public.narrator_source_record(original);
end $$;

CREATE FUNCTION public.lifetime_timeline_context(p_owner uuid,p_project text,p_source uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
declare current_source public.user_narrator_source%rowtype; prior public.user_narrator_source%rowtype;
 identity public.user_lifetime_conversation%rowtype; history jsonb:='[]'; original jsonb; reply text; last_event jsonb;
 previous_owner text; entry jsonb; trimmed jsonb:='[]'; fragment jsonb;
begin
 select * into current_source from public.user_narrator_source where user_id=p_owner and project_id=p_project
   and id=p_source and status='active';
 if not found then raise exception 'timeline source unavailable' using errcode='42501';end if;
 select * into identity from public.user_lifetime_conversation where user_id=p_owner and project_id=p_project;
 previous_owner:=current_setting('request.jwt.claim.sub',true);
 perform set_config('request.jwt.claim.sub',p_owner::text,true);
 for prior in select * from public.user_narrator_source where user_id=p_owner and project_id=p_project
   and status='active' and sequence<current_source.sequence order by sequence desc limit 20 loop
   select w into original from public.lifetime_guidance_source_windows(p_owner,p_project,prior.id,prior.version,0,least(length(prior.text),320)) w limit 1;
   reply:=case when original is not null then public.read_lifetime_history_reply(identity.conversation_id,prior.client_turn_id)->>'reply' end;
   if exists(select 1 from public.user_memory_attribution_window w where w.user_id=p_owner and w.project_id=p_project
       and w.source_id=prior.id and w.source_version=prior.version and w.disposition='withheld') then reply:=null;end if;
   history:=jsonb_build_array(jsonb_build_object('sequence',prior.sequence,'source',original,
     'source_complete',original->>'char_start'='0' and (original->>'char_end')::integer=length(prior.text),
     'assistant',case when reply is null then null else jsonb_build_object('role','assistant','personal_testimony',false,
       'text',left(reply,96),'complete',length(reply)<=96) end))||history;
 end loop;
 perform set_config('request.jwt.claim.sub',coalesce(previous_owner,''),true);
 if octet_length(history::text)>40000 then
   for entry in select value from jsonb_array_elements(history) loop
     if jsonb_typeof(entry->'source')='object' then
       fragment:=entry->'source';
       fragment:=fragment||jsonb_build_object('text',left(fragment->>'text',64),
         'char_end',(fragment->>'char_start')::integer+length(left(fragment->>'text',64)));
       entry:=entry||jsonb_build_object('source',fragment,'source_complete',false);
     end if;
     if jsonb_typeof(entry->'assistant')='object' then
       entry:=jsonb_set(entry,'{assistant}',(entry->'assistant')||jsonb_build_object('text',left(entry->'assistant'->>'text',32),'complete',false));
     end if;
     trimmed:=trimmed||jsonb_build_array(entry);
   end loop;
   history:=trimmed;
 end if;
 select public.bounded_lifetime_event_record(e)||coalesce(public.lifetime_attribution_event_context(p_owner,p_project,e.id),'{}')||
   jsonb_build_object('original_passages',coalesce((select jsonb_agg(w) from (
     select w from public.user_memory_event_source r cross join lateral public.lifetime_guidance_source_windows(
       r.user_id,r.project_id,r.source_id,r.source_version,coalesce((r.evidence->>'char_start')::integer,0),
       least(coalesce((r.evidence->>'char_end')::integer,2147483647),coalesce((r.evidence->>'char_start')::integer,0)+500)) w
     where r.user_id=p_owner and r.project_id=p_project and r.event_id=e.id
     order by r.source_id,r.evidence_hash limit 2) originals),'[]')) into last_event
 from public.user_memory_event e where e.user_id=p_owner and e.project_id=p_project and e.status='active'
   and exists(select 1 from public.user_memory_event_source r join public.user_narrator_source s
     on s.user_id=r.user_id and s.project_id=r.project_id and s.id=r.source_id and s.version=r.source_version and s.status='active'
     where r.user_id=e.user_id and r.project_id=e.project_id and r.event_id=e.id and s.sequence<current_source.sequence)
   and not exists(select 1 from public.user_memory_event_source r left join public.user_narrator_source s
     on s.user_id=r.user_id and s.project_id=r.project_id and s.id=r.source_id
     where r.user_id=e.user_id and r.project_id=e.project_id and r.event_id=e.id
       and (s.id is null or s.status<>'active' or s.version<>r.source_version or s.sequence>=current_source.sequence))
   and not exists(select 1 from public.user_memory_event_source r join public.user_memory_attribution_window w
     on w.user_id=r.user_id and w.project_id=r.project_id and w.source_id=r.source_id and w.source_version=r.source_version
     where r.user_id=e.user_id and r.project_id=e.project_id and r.event_id=e.id and w.disposition in ('withheld','non_story')
       and w.char_start<coalesce((r.evidence->>'char_end')::integer,2147483647)
       and w.char_end>coalesce((r.evidence->>'char_start')::integer,0))
 order by e.change_sequence desc,e.id limit 1;
 return jsonb_build_object('conversation_history',history,'last_event',last_event);
end $$;
REVOKE ALL ON FUNCTION public.lifetime_timeline_context(uuid,text,uuid) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION public.read_lifetime_memoir_lane_page(p_lane_id uuid, p_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare page jsonb; source public.user_narrator_source%rowtype; context jsonb; inputs jsonb; coverage jsonb; events jsonb; decision jsonb;
begin
 if exists(select 1 from public.user_memoir_lane where id=p_lane_id and skill='guidance') then
   return public.read_lifetime_interview_guidance_page(p_lane_id,p_token);end if;
 page:=public.read_lifetime_memoir_lane_page_before_attribution(p_lane_id,p_token);
 if page->>'skill'='timeline' and page ? 'two_lane' and page->'source'<>'null'::jsonb then
   select * into source from public.user_narrator_source where user_id=(page->>'user_id')::uuid
     and project_id=page->>'project_id' and id=(page->'source'->>'id')::uuid;
   context:=public.lifetime_attribution_decision(source.text,null)||jsonb_build_object('delivered_event',
     public.lifetime_source_context(source.user_id,source.project_id,source.id),
     'recent_dialogue',public.lifetime_question_dialogue(source.user_id,source.project_id,source.id,
       (page->>'source_high_water')::bigint));
   page:=page||jsonb_build_object('attribution_context',context);
   if not(page ? 'profile_context') and coalesce(page->'memory_summary','null')='null' then
     inputs:=public.lifetime_timeline_context(source.user_id,source.project_id,source.id);
     page:=page||jsonb_build_object('timeline_context',inputs);
     if inputs->'last_event'<>'null'::jsonb and not exists(select 1 from jsonb_array_elements(page->'events') e
         where e->>'id'=inputs->'last_event'->>'id') then
       events:=jsonb_build_array(inputs->'last_event')||page->'events';
       page:=jsonb_set(page,'{events}',case when jsonb_array_length(events)>8 then events-8 else events end);
     end if;
   end if;
   page:=jsonb_set(page,'{events}',coalesce((select jsonb_agg(candidate||coalesce(ctx,'{}'))
     from jsonb_array_elements(page->'events') candidate cross join lateral (select public.lifetime_attribution_event_context(
       source.user_id,source.project_id,candidate->>'id') ctx) bounded),'[]'));
   if coalesce(page->'memory_summary','null')='null' then
     select source_decision into decision from public.user_lifetime_lane_snapshot where id=(page->>'snapshot_id')::uuid;
     if decision is not null then
       if decision->'source'=jsonb_build_object('id',page->'source'->'id','version',page->'source'->'version',
           'char_start',page->'source'->'char_start','char_end',page->'source'->'char_end') then
         page:=jsonb_set(page,'{two_lane,selected_skills}',decision->'skills');
         if decision->'skills' ? 'memoir-memory-context' then
           page:=jsonb_set(page,'{two_lane,profile_complete}',to_jsonb(
             exists(select 1 from public.user_lifetime_profile_coverage c where c.user_id=source.user_id
               and c.project_id=source.project_id and c.source_id=source.id and c.source_version=source.version
               and c.next_offset>=(page->'source'->>'char_end')::integer)
             or exists(select 1 from public.user_lifetime_profile_authority a where a.user_id=source.user_id
               and (not a.auto_enabled or a.manual_complete or a.field_locks ?& array[
                 'name','birth_year','birth_date_expression','birth_place','childhood_place','avatar_style']))));
         end if;
         page:=jsonb_set(page,'{two_lane,work_mode}',to_jsonb(case when decision->'skills' ?| array[
           'memoir-author-timeline','memoir-place-journey'] then 'extract' else 'reply_only' end));
       else
         page:=jsonb_set(page,'{two_lane,work_mode}',to_jsonb('pending'::text));
       end if;
     end if;
   end if;
   if exists(select 1 from public.user_lifetime_reply r join public.user_interview_turn t
       on t.user_id=r.user_id and t.project_id=source.project_id and t.client_turn_id=r.client_turn_id
       where r.user_id=source.user_id and t.source_id=source.id and t.source_version=source.version
         and r.conversation_id=(page->>'conversation_id')::uuid and r.prompt_version='reply-v2') then
     page:=jsonb_set(page,'{two_lane,reply_contract}',to_jsonb('reply-v2'::text));
   end if;
   page:=page-'input_digest'-'page_digest';
   page:=page||jsonb_build_object('input_digest',encode(sha256(convert_to((page-'token')::text,'UTF8')),'hex'));
   page:=page||jsonb_build_object('page_digest',encode(sha256(convert_to(page::text,'UTF8')),'hex'));
 elsif page->>'skill'='composer' and exists(select 1 from public.lifetime_two_lane_rollout where singleton and enabled) then
   inputs:=case when page ? 'batch' then coalesce(page->'batch'->'sources','[]')||coalesce(page->'batch'->'new_messages','[]')
     when page->'source'<>'null'::jsonb then jsonb_build_array(page->'source') else '[]' end;
   select coalesce(jsonb_agg(public.lifetime_source_attribution_summary((page->>'user_id')::uuid,page->>'project_id',id)),'[]')
     into coverage from (select distinct (s->>'id')::uuid id from jsonb_array_elements(inputs) s limit 21) bounded;
   select coalesce(jsonb_agg(public.lifetime_attribution_event_context((page->>'user_id')::uuid,page->>'project_id',e->>'id')),'[]')
     into events from (select e from jsonb_array_elements(case when page ? 'batch' then page->'batch'->'events'
       else jsonb_build_array(page->'partition') end) e limit 8) bounded;
   page:=page||jsonb_build_object('attribution_coverage',jsonb_build_object('scope','bounded_sources','lifetime_complete',false,
     'sources',coverage,'events',events,'authority','canonical_context_only_not_additional_testimony'));
   page:=page-'input_digest'-'page_digest';
   page:=page||jsonb_build_object('input_digest',encode(sha256(convert_to((page-'token')::text,'UTF8')),'hex'));
   page:=page||jsonb_build_object('page_digest',encode(sha256(convert_to(page::text,'UTF8')),'hex'));
 end if;
 return page;
end $$;

CREATE FUNCTION public.read_lifetime_memoir_lane_page_before_attribution(p_lane_id uuid, p_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare page jsonb;
begin
 page:=public.read_lifetime_memoir_lane_page_before_background_profile(p_lane_id,p_token);
 if page->>'skill'='timeline' and exists(select 1 from public.lifetime_two_lane_rollout where singleton and enabled)
   and exists(select 1 from public.user_lifetime_profile_progress where user_id=(page->>'user_id')::uuid
     and project_id=page->>'project_id' and (active_round>0 or requested_round>greatest(covered_round,skipped_round))) then
   page:=(page-'input_digest'-'page_digest')||jsonb_build_object('two_lane_maintenance_required',true);
   page:=page||jsonb_build_object('input_digest',encode(sha256(convert_to((page-'token')::text,'UTF8')),'hex'));
   page:=page||jsonb_build_object('page_digest',encode(sha256(convert_to(page::text,'UTF8')),'hex'));
 end if;
 return page;
end $$;

CREATE FUNCTION public.read_lifetime_memoir_lane_page_before_background_profile(p_lane_id uuid, p_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare page jsonb; snap public.user_lifetime_lane_snapshot%rowtype; proof public.user_lifetime_compaction%rowtype;
 prior public.user_lifetime_checkpoint%rowtype; identity public.user_lifetime_conversation%rowtype; next_item record; source jsonb; work text;
begin
 page:=public.read_lifetime_memoir_lane_page_before_semantic(p_lane_id,p_token);
 if page->>'skill'<>'timeline' or page->'complete' is distinct from 'true'::jsonb or not(page ? 'two_lane_maintenance_required') then return page;end if;
 snap:=public.lock_lifetime_memoir_lane(p_lane_id,p_token);
 select * into identity from public.user_lifetime_conversation where user_id=snap.user_id and conversation_id=snap.conversation_id;
 select * into proof from public.user_lifetime_compaction p where p.user_id=snap.user_id and p.conversation_id=snap.conversation_id
   and p.complete and p.summary_required and p.predecessor_id is not distinct from identity.checkpoint_id
   and p.through_sequence=snap.source_high_water-1
   and p.through_sequence>=coalesce((select c.coverage_end from public.user_lifetime_checkpoint c where c.id=identity.checkpoint_id),0)
   and p.pinned-'active_question'-'known_continuity'-'known_continuity_complete'
     =(page->'preferences')-'active_question'-'known_continuity'-'known_continuity_complete'
   and p.fence->>'policy_epoch'=page->>'policy_epoch' and p.fence->>'execution_generation'=identity.execution_generation::text
   order by p.summary_windows desc,p.id limit 1 for update;
 if not found then return page;end if;
 if not proof.summary_initialized then
   select * into prior from public.user_lifetime_checkpoint where id=proof.predecessor_id;
   update public.user_lifetime_compaction set summary_initialized=true,
     summary_data=case when prior.memory_summary is not null then jsonb_build_object('items',prior.memory_summary->'items') else '{"items":[]}' end,
     summary_sequence=case when prior.memory_summary is not null then prior.coverage_end else 0 end,
     summary_offset=case when prior.memory_summary is not null then 2147483647 else -1 end,
     summary_windows=case when prior.memory_summary is not null then (prior.memory_summary->>'processed_windows')::bigint else 0 end
     where id=proof.id returning * into proof;
 end if;
 select pos.sequence,pos.source_id,pos.version,part as char_start,
   case when src.version=pos.version and src.status='active' then least(part+2000,length(src.text)) else 0 end as char_end,
   src as original,case when src.version=pos.version and src.status='active' then 'active' else 'tombstone' end as status
 into next_item from public.user_lifetime_source_position pos left join public.user_narrator_source src
   on src.user_id=pos.user_id and src.project_id=pos.project_id and src.id=pos.source_id
 cross join lateral generate_series(0,case when src.version=pos.version and src.status='active' then greatest(length(src.text)-1,0) else 0 end,2000) part
 where pos.user_id=snap.user_id and pos.project_id=snap.project_id and pos.sequence<=proof.through_sequence
   and (pos.sequence>proof.summary_sequence or (pos.sequence=proof.summary_sequence and part>proof.summary_offset))
 order by pos.sequence,part limit 1;
 if not found then
   update public.user_lifetime_compaction set summary_complete=true where id=proof.id;
   perform public.publish_lifetime_semantic_checkpoint(p_lane_id,p_token,proof.id);
   return page;
 end if;
 source:=null;work:='reply_only';
 if next_item.status='active' then
   source:=public.narrator_source_record(next_item.original)||jsonb_build_object('text',substring((next_item.original).text from next_item.char_start+1 for next_item.char_end-next_item.char_start),
     'char_start',next_item.char_start,'char_end',next_item.char_end,'original_length',length((next_item.original).text));
   select coalesce((select case when t.collector->'plan'->'work'->>'mode'='reply_only' then 'reply_only' else 'extract' end
     from public.user_interview_turn t where t.user_id=snap.user_id and t.project_id=snap.project_id and t.source_id=next_item.source_id and t.source_version=next_item.version),'extract') into work;
 end if;
 page:=(page-'input_digest'-'page_digest')||jsonb_build_object('complete',false,'source',source,'partition',null,'events','[]'::jsonb,
   'two_lane',jsonb_build_object('schema_version',1,'task_version','two-lane-v1','execution_generation',identity.execution_generation,
     'phase_revision',proof.fence->'phase_revision','work_mode',work,'strategy_mode',null,'strategy_revision',0),
   'memory_summary',jsonb_build_object('schema_version',1,'maintenance_id',proof.id,'revision',proof.summary_revision,
     'through_sequence',proof.through_sequence,'sequence',next_item.sequence,'char_start',next_item.char_start,'char_end',next_item.char_end,
     'status',next_item.status,'work_mode',work,'prior',proof.summary_data));
 page:=page||jsonb_build_object('input_digest',encode(sha256(convert_to((page-'token')::text,'UTF8')),'hex'));
 page:=page||jsonb_build_object('page_digest',encode(sha256(convert_to(page::text,'UTF8')),'hex'));
 return page;
end $$;

CREATE FUNCTION public.read_lifetime_memoir_lane_page_before_batches(p_lane_id uuid, p_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare page jsonb; request public.user_workspace_section_rework%rowtype;
 snap public.user_lifetime_lane_snapshot%rowtype;
begin
 snap:=public.lock_lifetime_memoir_lane(p_lane_id,p_token);
 -- Editorial partitions can predate the predecessor's canonical watermark.
 -- Start the cursor before those explicit tasks, retaining base_event so only
 -- canonical deltas and the selected editorial partitions are visited.
 if snap.page_number=0 and exists(select 1 from public.user_memoir_lane where id=p_lane_id and skill='composer')
   and exists(select 1 from public.user_workspace_section_rework
   where user_id=snap.user_id and project_id=snap.project_id and locale=snap.locale and status='pending' and partition_key not like 'progressive:%') then
   update public.user_lifetime_lane_snapshot set last_event=0,last_event_id='',last_ref='' where id=snap.id;
 end if;
 page:=public.read_lifetime_memoir_lane_page_before_rework(p_lane_id,p_token);
 select * into request from public.user_workspace_section_rework where user_id=(page->>'user_id')::uuid
   and project_id=page->>'project_id' and locale=page->>'locale' and partition_key=page->>'partition_key'
   and event_revision=(page->'partition'->>'revision')::bigint and source_version=(page->'source'->>'version')::bigint and status='pending';
 page:=page-'input_digest'-'page_digest';
 if found then
   page:=page||jsonb_build_object('reuse',false,'editorial_request',jsonb_build_object('schema_version',1,'request_id',request.request_id,'instruction',request.instruction,'original_preview',request.original_preview));
 else page:=page||jsonb_build_object('editorial_request',null);end if;
 page:=page||jsonb_build_object('input_digest',encode(sha256(convert_to((page-'token')::text,'UTF8')),'hex'));
 return page||jsonb_build_object('page_digest',encode(sha256(convert_to(page::text,'UTF8')),'hex'));
end $$;

CREATE FUNCTION public.read_lifetime_memoir_lane_page_before_progressive_rework(p_lane_id uuid, p_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare page jsonb; snap public.user_lifetime_lane_snapshot%rowtype;
  predecessor public.user_lifetime_lane_snapshot%rowtype; summary_after bigint;
  starting_source bigint; messages jsonb:='[]'; source public.user_narrator_source%rowtype;
  lo integer; hi integer;
begin
  page:=public.read_lifetime_memoir_lane_page_before_summary_windows(p_lane_id,p_token);
  if not (page ? 'batch') then return page;end if;
  select * into snap from public.user_lifetime_lane_snapshot where id=(page->>'snapshot_id')::uuid;
  select * into predecessor from public.user_lifetime_lane_snapshot where id=snap.predecessor;
  summary_after:=greatest(coalesce(predecessor.milestone,0),snap.milestone-5);
  select coalesce(max(s.sequence),0) into starting_source from public.user_completed_round r
    join public.user_narrator_source s on s.user_id=r.user_id and s.project_id=r.project_id and s.client_turn_id=r.turn_id
    where r.user_id=snap.user_id and r.project_id=snap.project_id and r.ordinal<=summary_after;
  if snap.summary_source=0 and snap.summary_offset=0 then
    update public.user_lifetime_lane_snapshot set summary_source=starting_source,summary_offset=100000
      where id=snap.id returning * into snap;
  end if;
  if snap.milestone>summary_after then
    for source in select s.* from public.user_completed_round r join public.user_narrator_source s
      on s.user_id=r.user_id and s.project_id=r.project_id and s.client_turn_id=r.turn_id
      where r.user_id=snap.user_id and r.project_id=snap.project_id and r.ordinal>summary_after
        and r.ordinal<=snap.milestone and s.sequence<=snap.source_high_water and s.status='active'
        and (s.sequence>snap.summary_source or s.sequence=snap.summary_source and snap.summary_offset<length(s.text))
      order by r.ordinal limit 5 loop
      lo:=case when source.sequence=snap.summary_source then snap.summary_offset else 0 end;
      hi:=least(lo+2000,length(source.text));
      if hi>lo then
        messages:=messages||jsonb_build_array(public.lifetime_composer_source(snap.user_id,snap.project_id,
          source.id,source.version,lo,hi));
      end if;
      if hi<length(source.text) then exit;end if;
    end loop;
  end if;
  -- Writing revisions and message summaries advance independently.
  page:=jsonb_set(jsonb_set(page,'{batch,new_messages}',messages),'{batch,starting_after}',to_jsonb(starting_source));
  page:=jsonb_set(page,'{complete}',to_jsonb((page->>'complete')::boolean and jsonb_array_length(messages)=0));
  if page->'source'='null'::jsonb and jsonb_array_length(messages)>0 then
    page:=jsonb_set(page,'{source}',messages->0);
  end if;
  if octet_length((page->'batch')::text)>45000 then
    raise exception 'progressive batch resource budget exceeded' using errcode='22023';
  end if;
  page:=page-'input_digest'-'page_digest';
  page:=page||jsonb_build_object('input_digest',encode(sha256(convert_to((page-'token')::text,'UTF8')),'hex'));
  return page||jsonb_build_object('page_digest',encode(sha256(convert_to(page::text,'UTF8')),'hex'));
end $$;

CREATE FUNCTION public.read_lifetime_memoir_lane_page_before_rework(p_lane_id uuid, p_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare result jsonb;
begin
 result:=public.read_lifetime_memoir_lane_page_body(p_lane_id,p_token);
 -- The input identity survives lease renewal; the admission digest additionally
 -- binds the current token. Keep both authoritative and exactly compared.
 result:=result||jsonb_build_object('input_digest',encode(sha256(convert_to((result-'token')::text,'UTF8')),'hex'));
 return result||jsonb_build_object('page_digest',encode(sha256(convert_to(result::text,'UTF8')),'hex'));
end $$;

CREATE FUNCTION public.read_lifetime_memoir_lane_page_before_semantic(p_lane_id uuid, p_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare page jsonb; planning text; revision bigint;
begin
 page:=public.read_lifetime_memoir_lane_page_before_strategy(p_lane_id,p_token);
 if page ? 'two_lane' then
   planning:=public.lifetime_interview_strategy_rollout((page->>'user_id')::uuid);
   select f.revision into revision from public.user_lifetime_strategy_frontier f
     where f.user_id=(page->>'user_id')::uuid and f.project_id=page->>'project_id';
   if planning<>'disabled' then
     page:=jsonb_set(page,'{two_lane}',page->'two_lane'||jsonb_build_object('strategy_mode',planning,'strategy_revision',coalesce(revision,0)));
     page:=page-'input_digest'-'page_digest';
     page:=page||jsonb_build_object('input_digest',encode(sha256(convert_to((page-'token')::text,'UTF8')),'hex'));
     page:=page||jsonb_build_object('page_digest',encode(sha256(convert_to(page::text,'UTF8')),'hex'));
   end if;
 end if;
 return page;
end $$;

CREATE FUNCTION public.read_lifetime_memoir_lane_page_before_strategy(p_lane_id uuid, p_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare page jsonb; descriptor jsonb;
begin
 page:=public.read_lifetime_memoir_lane_page_before_two_lanes(p_lane_id,p_token);
 if exists(select 1 from public.lifetime_two_lane_rollout where singleton and enabled)
   and exists(select 1 from public.user_lifetime_two_lane_source where user_id=(page->>'user_id')::uuid and project_id=page->>'project_id') then
   page:=page||jsonb_build_object('two_lane_maintenance_required',true);
 end if;
 if page->>'skill'='timeline' and exists(select 1 from public.lifetime_two_lane_rollout where singleton and enabled) and exists(select 1 from public.user_lifetime_two_lane_source m
   where m.user_id=(page->>'user_id')::uuid and m.project_id=page->>'project_id' and m.source_id=(page->'source'->>'id')::uuid) then
   select jsonb_build_object('schema_version',1,'task_version','two-lane-v1','execution_generation',c.execution_generation,
     'phase_revision',0,'work_mode','extract') into descriptor
   from public.user_lifetime_conversation c
   left join public.user_interview_turn t on t.user_id=c.user_id and t.project_id=c.project_id and t.source_id=(page->'source'->>'id')::uuid
   where c.user_id=(page->>'user_id')::uuid and c.conversation_id=(page->>'conversation_id')::uuid;
   page:=(page-'input_digest'-'page_digest')||jsonb_build_object('two_lane',descriptor);
   page:=page||jsonb_build_object('input_digest',encode(sha256(convert_to((page-'token')::text,'UTF8')),'hex'));
   page:=page||jsonb_build_object('page_digest',encode(sha256(convert_to(page::text,'UTF8')),'hex'));
 end if;
 if page ? 'two_lane_maintenance_required' then
   page:=page-'input_digest'-'page_digest';
   page:=page||jsonb_build_object('input_digest',encode(sha256(convert_to((page-'token')::text,'UTF8')),'hex'));
   page:=page||jsonb_build_object('page_digest',encode(sha256(convert_to(page::text,'UTF8')),'hex'));
 end if;
 return page;
end $$;

CREATE FUNCTION public.read_lifetime_memoir_lane_page_before_summary_windows(p_lane_id uuid, p_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $memoir$
declare snap public.user_lifetime_lane_snapshot%rowtype; lane public.user_memoir_lane%rowtype; predecessor public.user_lifetime_lane_snapshot%rowtype;
 page jsonb; batch jsonb; link record; src jsonb; old_src jsonb; ev jsonb; sources jsonb:='[]'; events jsonb:='[]'; messages jsonb:='[]';
 s public.user_narrator_source%rowtype; prior record; previous jsonb; previous_sections jsonb:='[]'; previous_events jsonb:='[]';
 cursor_seq bigint; cursor_event text; cursor_ref text; start_source bigint; end_source bigint; end_offset integer;
  lo integer; hi integer; i integer; event_index integer; source_index integer; ref jsonb; reference_key text; summary jsonb; prior_ref jsonb; support record; supported boolean;
begin
 snap:=public.lock_lifetime_memoir_lane(p_lane_id,p_token);
 select * into lane from public.user_memoir_lane where id=p_lane_id;
 page:=public.read_lifetime_memoir_lane_page_before_batches(p_lane_id,p_token);
 if lane.skill<>'composer' then return page;end if;
 select * into snap from public.user_lifetime_lane_snapshot where id=snap.id;
 select * into predecessor from public.user_lifetime_lane_snapshot where id=snap.predecessor;
 if snap.page_number=0 and snap.last_source=0 and snap.next_offset=0 then
  update public.user_lifetime_lane_snapshot set last_source=coalesce(predecessor.source_high_water,0),next_offset=100000 where id=snap.id returning * into snap;
 end if;
 start_source:=snap.last_source;end_source:=start_source;end_offset:=snap.next_offset;
 for s in select * from public.user_narrator_source where user_id=snap.user_id and project_id=snap.project_id and status='active'
   and sequence<=snap.source_high_water and (sequence>snap.last_source or sequence=snap.last_source and snap.next_offset<length(text)) order by sequence limit 5 loop
  lo:=case when s.sequence=snap.last_source then snap.next_offset else 0 end;hi:=least(lo+2000,length(s.text));
  if hi>lo then messages:=messages||jsonb_build_array(public.lifetime_composer_source(snap.user_id,snap.project_id,s.id,s.version,lo,hi));end if;
  end_source:=s.sequence;end_offset:=case when hi=length(s.text) then 100000 else hi end;
  if hi<length(s.text) then exit;end if;
 end loop;
 cursor_seq:=snap.last_event;cursor_event:=snap.last_event_id;cursor_ref:=snap.last_ref;
 for link in select e.*,r.source_id,r.source_version,r.evidence_hash,r.evidence,
   coalesce(r.source_id::text||':'||r.source_version::text||':'||r.evidence_hash||':','') reference_key
   from public.user_memory_event e left join public.user_memory_event_source r on r.user_id=e.user_id and r.project_id=e.project_id and r.event_id=e.id
   where e.user_id=snap.user_id and e.project_id=snap.project_id and (e.change_sequence>snap.base_event or exists(select 1 from public.user_workspace_section_rework request
     where request.user_id=snap.user_id and request.project_id=snap.project_id and request.locale=snap.locale and request.event_id=e.id and request.status='pending' and request.partition_key not like 'progressive:%')) and e.change_sequence<=snap.event_high_water
   and (e.change_sequence,e.id,coalesce(r.source_id::text||':'||r.source_version::text||':'||r.evidence_hash||':',''))>(snap.last_event,snap.last_event_id,snap.last_ref)
   order by e.change_sequence,e.id,reference_key limit 64 loop
  select ordinality::integer-1 into event_index from jsonb_array_elements(events) with ordinality where value->>'id'=link.id;
  if event_index is null and jsonb_array_length(events)>=8 then exit;end if;
  ref:=null;
  if link.status='active' and link.source_id is not null then
   lo:=coalesce((link.evidence->>'char_start')::integer,(select strpos(text,link.evidence->>'quote')-1 from public.user_narrator_source
     where user_id=snap.user_id and project_id=snap.project_id and id=link.source_id and version=link.source_version and status='active'));
   hi:=coalesce((link.evidence->>'char_end')::integer,lo+length(link.evidence->>'quote'));
   src:=public.lifetime_composer_source(snap.user_id,snap.project_id,link.source_id,link.source_version,lo,hi);
   if src->>'text' is distinct from link.evidence->>'quote' then raise exception 'progressive original evidence mismatch';end if;
   if not link.evidence ? 'char_start' and exists(select 1 from public.user_narrator_source where user_id=snap.user_id and project_id=snap.project_id and id=link.source_id
    and strpos(substring(text from lo+2),link.evidence->>'quote')>0) then raise exception 'ambiguous progressive original evidence';end if;
   ref:=link.evidence||jsonb_build_object('char_start',lo,'char_end',hi);
   select ordinality::integer-1,value into source_index,old_src from jsonb_array_elements(sources) with ordinality where value->>'id'=link.source_id::text;
   if source_index is not null then
    lo:=least(lo,(old_src->>'char_start')::integer);hi:=greatest(hi,(old_src->>'char_end')::integer);
    if hi-lo>2304 then exit;end if;
    src:=public.lifetime_composer_source(snap.user_id,snap.project_id,link.source_id,link.source_version,lo,hi);
    sources:=jsonb_set(sources,array[source_index::text],src);
   else
    if jsonb_array_length(sources)>=16 then exit;end if;
    sources:=sources||jsonb_build_array(src);
   end if;
  end if;
  if event_index is null then
   ev:=jsonb_build_object('id',link.id,'revision',link.revision,'kind',link.kind,'life_stage',link.life_stage,'status',link.status,
    'change_sequence',link.change_sequence,'title',left(link.data->>'title',300),'temporal',coalesce(link.data->'temporal','{}'),
    'source_refs',case when ref is null then '[]'::jsonb else jsonb_build_array(ref) end);
   events:=events||jsonb_build_array(ev);
  elsif ref is not null then
   events:=jsonb_set(events,array[event_index::text,'source_refs'],events->event_index->'source_refs'||jsonb_build_array(ref));
  end if;
  cursor_seq:=link.change_sequence;cursor_event:=link.id;cursor_ref:=link.reference_key;
  if octet_length(jsonb_build_object('sources',sources,'events',events)::text)>24000 then exit;end if;
 end loop;
 -- Biographical profile updates advance preferences without changing privacy.
 -- Only affected, independently supported prior passages enter the model.
 for prior in select distinct on (section.partition_key) section.* from public.user_lifetime_memoir_section section
  join public.user_lifetime_lane_snapshot root on root.id=section.snapshot_id
  where section.user_id=snap.user_id and section.project_id=snap.project_id and section.locale=snap.locale and not section.retired
   and (root.state='completed' or root.id=snap.id) and root.policy_epoch=snap.policy_epoch and root.privacy_digest=snap.privacy_digest
   and root.created_at<=snap.created_at and (section.event_id in (select value->>'id' from jsonb_array_elements(events))
     or exists(select 1 from jsonb_array_elements(section.event_dependencies) dependency,jsonb_array_elements(events) changed where dependency->>'id'=changed->>'id'))
  order by section.partition_key,root.created_at desc limit 8 loop
  if prior.bundle ? 'sections' then
   supported:=true;
   for prior_ref in select value from jsonb_path_query(prior.bundle->'sections','$.** ? (exists(@.source_id) && exists(@.version))') refs(value) loop
    select e.*,l.evidence into support from public.user_memory_event e join public.user_memory_event_source l
      on l.user_id=e.user_id and l.project_id=e.project_id and l.event_id=e.id
     where e.user_id=snap.user_id and e.project_id=snap.project_id and e.status='active' and e.change_sequence<=snap.event_high_water
      and l.source_id::text=prior_ref->>'source_id' and l.source_version::text=prior_ref->>'version'
      and coalesce((l.evidence->>'char_start')::integer,0)<=(prior_ref->>'char_start')::integer
      and coalesce((l.evidence->>'char_end')::integer,length(l.evidence->>'quote'))>=(prior_ref->>'char_end')::integer limit 1;
    if not found then supported:=false;exit;end if;
    select ordinality::integer-1,value into source_index,old_src from jsonb_array_elements(sources) with ordinality where value->>'id'=prior_ref->>'source_id';
    lo:=(prior_ref->>'char_start')::integer;hi:=(prior_ref->>'char_end')::integer;
    if source_index is not null then lo:=least(lo,(old_src->>'char_start')::integer);hi:=greatest(hi,(old_src->>'char_end')::integer);end if;
    if hi-lo>2304 or source_index is null and jsonb_array_length(sources)>=16 then supported:=false;exit;end if;
    src:=public.lifetime_composer_source(snap.user_id,snap.project_id,(prior_ref->>'source_id')::uuid,(prior_ref->>'version')::bigint,lo,hi);
    if source_index is null then sources:=sources||jsonb_build_array(src);else sources:=jsonb_set(sources,array[source_index::text],src);end if;
    if not exists(select 1 from jsonb_array_elements(events) where value->>'id'=support.id) then
     if jsonb_array_length(events)>=8 then supported:=false;exit;end if;
     events:=events||jsonb_build_array(jsonb_build_object('id',support.id,'revision',support.revision,'kind',support.kind,'status',support.status,'life_stage',support.life_stage,
       'change_sequence',support.change_sequence,'title',left(support.data->>'title',300),'temporal',coalesce(support.data->'temporal','{}'),
       'source_refs',jsonb_build_array(support.evidence||jsonb_build_object('char_start',(prior_ref->>'char_start')::integer,'char_end',(prior_ref->>'char_end')::integer))));
    end if;
   end loop;
   -- A prior passage is usable only when all its evidence is in this bounded packet.
   if supported and not exists(select 1 from jsonb_path_query(prior.bundle->'sections','$.** ? (exists(@.source_id) && exists(@.version))') r
     where not exists(select 1 from jsonb_array_elements(sources) a where a->>'id'=r->>'source_id' and a->>'version'=r->>'version'
       and (r->>'char_start')::integer>=(a->>'char_start')::integer and (r->>'char_end')::integer<=(a->>'char_end')::integer)) then
    previous_sections:=previous_sections||(prior.bundle->'sections');
    previous_events:=previous_events||coalesce(nullif(prior.event_dependencies,'[]'),jsonb_build_array(jsonb_build_object('id',prior.event_id,'revision',prior.event_revision)));
    previous:=jsonb_build_object('kind',coalesce(prior.bundle->>'kind',prior.bundle->'manuscript'->>'kind'),'content_config',prior.composition_config,
      'photo_association_manifest',coalesce(prior.bundle->'photo_association_manifest','{}'::jsonb));
   end if;
  end if;
 end loop;
 -- Keep confirmed photograph associations grounded in these original spans.
 select coalesce(jsonb_agg(event || jsonb_build_object('photo_associations',(
   select coalesce(jsonb_agg(jsonb_build_object('id',photo.id,'photo_id',photo.photo_id,'event_id',photo.event_id,
     'source_id',photo.source_id,'source_version',photo.source_version,'quote',photo.quote,'description',photo.description,
     'status','confirmed','provenance','narrator_metadata') order by photo.id),'[]')
   from public.user_interview_photo_link photo where photo.user_id=snap.user_id and photo.project_id=snap.project_id
    and photo.event_id=event->>'id' and photo.status='confirmed' and photo.provenance='narrator_metadata'
    and public.interview_photo_available(snap.user_id,snap.project_id,photo.photo_id)
    and exists(select 1 from jsonb_array_elements(event->'source_refs') evidence where evidence->>'source_id'=photo.source_id::text
      and evidence->>'version'=photo.source_version::text and strpos(evidence->>'quote',photo.quote)>0)
 ))),'[]') into events from jsonb_array_elements(events) event;
 if previous is not null then previous:=previous||jsonb_build_object('sections',previous_sections,'event_manifest',previous_events);end if;
 select value into summary from public.user_memoir_checkpoint c join public.user_lifetime_lane_snapshot root on root.id=c.lifetime_snapshot_id
  where c.lane_id=lane.id and c.kind='prepare' and root.policy_epoch=snap.policy_epoch and root.privacy_digest=snap.privacy_digest
   and root.created_at<=snap.created_at and (root.id<>snap.id or c.lifetime_page<snap.page_number)
   and c.value->>'event_id' like '%-messages-%' order by c.created_at desc limit 1;
 batch:=jsonb_build_object('schema_version',1,'starting_after',start_source,'through_source',end_source,'next_offset',end_offset,
  'cursor',jsonb_build_array(cursor_seq,cursor_event,cursor_ref),'sources',sources,'events',events,'new_messages',messages,'previous',previous,'previous_summary',summary);
 if octet_length(batch::text)>45000 then raise exception 'progressive batch resource budget exceeded' using errcode='22023';end if;
 page:=page-'input_digest'-'page_digest';
 page:=page||jsonb_build_object('batch',batch,'complete',jsonb_array_length(events)=0 and jsonb_array_length(messages)=0,
   'source',case when page->'source'='null'::jsonb and jsonb_array_length(messages)>0 then messages->0 else page->'source' end);
 page:=page||jsonb_build_object('input_digest',encode(sha256(convert_to((page-'token')::text,'UTF8')),'hex'));
 return page||jsonb_build_object('page_digest',encode(sha256(convert_to(page::text,'UTF8')),'hex'));
end $memoir$;

CREATE FUNCTION public.read_lifetime_memoir_lane_page_before_two_lanes(p_lane_id uuid, p_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare page jsonb; snap public.user_lifetime_lane_snapshot%rowtype; request public.user_workspace_section_rework%rowtype;
 section public.user_lifetime_memoir_section%rowtype; ref jsonb; evidence record; s jsonb; ev jsonb;
 sources jsonb:='[]'; events jsonb:='[]'; refs jsonb; previous jsonb; lo integer; hi integer; old jsonb; idx integer;
begin
 page:=public.read_lifetime_memoir_lane_page_before_progressive_rework(p_lane_id,p_token);
 if not(page ? 'batch') then return page;end if;
 snap:=public.lock_lifetime_memoir_lane(p_lane_id,p_token);
 -- Recover tasks stranded before an invalidation trigger was installed. An
 -- old instruction is never rebound to a newer privacy/preference authority.
 delete from public.user_workspace_section_rework obsolete where obsolete.user_id=snap.user_id
   and obsolete.project_id=snap.project_id and obsolete.locale=snap.locale and obsolete.status='pending'
   and obsolete.partition_key like 'progressive:%' and (not exists(
     select 1 from public.workspace_progressive_rework_section(obsolete) selected
       where public.workspace_progressive_section_current(selected)) or not exists(
       select 1 from public.user_lifetime_lane_snapshot original where original.id=obsolete.snapshot_id
        and original.policy_epoch=snap.policy_epoch and original.preference_revision=snap.preference_revision));
 select * into request from public.user_workspace_section_rework where user_id=snap.user_id and project_id=snap.project_id
   and locale=snap.locale and status='pending' and partition_key like 'progressive:%'
   and composed_snapshot_id is distinct from snap.id
   order by (select change_sequence from public.user_memory_event e where e.user_id=snap.user_id and e.project_id=snap.project_id and e.id=event_id),event_id,partition_key,request_id limit 1;
 if not found then return page;end if;
 select * into section from public.workspace_progressive_rework_section(request);
 if not found or not public.workspace_progressive_section_current(section) then
   raise exception 'selected writing evidence changed' using errcode='PT409';end if;
 -- Include only references actually used by the selected writing and its
 -- heading. Each must still be contained in current canonical event evidence.
 for ref in select distinct r from jsonb_array_elements(section.bundle->'sections') item,
   jsonb_array_elements(item->'source_refs') r loop
   lo:=(ref->>'char_start')::integer;hi:=(ref->>'char_end')::integer;
   if lo is null or hi is null then raise exception 'selected writing requires exact evidence spans';end if;
   s:=public.lifetime_composer_source(snap.user_id,snap.project_id,(ref->>'source_id')::uuid,(ref->>'version')::bigint,lo,hi);
   select ordinality::integer-1,value into idx,old from jsonb_array_elements(sources) with ordinality where value->>'id'=s->>'id';
   if idx is null then sources:=sources||jsonb_build_array(s);
   else
     s:=public.lifetime_composer_source(snap.user_id,snap.project_id,(ref->>'source_id')::uuid,(ref->>'version')::bigint,
       least(lo,(old->>'char_start')::integer),greatest(hi,(old->>'char_end')::integer));
     sources:=jsonb_set(sources,array[idx::text],s);
   end if;
 end loop;
 for evidence in select e.* from public.user_memory_event e where e.user_id=snap.user_id and e.project_id=snap.project_id
   and exists(select 1 from jsonb_array_elements(section.event_dependencies) d where d->>'id'=e.id and d->>'revision'=e.revision::text) loop
   select coalesce(jsonb_agg(r),'[]') into refs from (select distinct r from jsonb_array_elements(section.bundle->'sections') item,
     jsonb_array_elements(item->'source_refs') r where item->'event_ids' ? evidence.id) selected;
   if exists(select 1 from jsonb_array_elements(refs) r where not exists(select 1 from public.user_memory_event_source original
      where original.user_id=snap.user_id and original.project_id=snap.project_id and original.event_id=evidence.id
       and original.source_id::text=r->>'source_id' and original.source_version::text=r->>'version'
       and coalesce((original.evidence->>'char_start')::integer,(select strpos(text,original.evidence->>'quote')-1 from public.user_narrator_source where user_id=snap.user_id and project_id=snap.project_id and id=original.source_id))<=(r->>'char_start')::integer
       and coalesce((original.evidence->>'char_end')::integer,(select strpos(text,original.evidence->>'quote')-1+length(original.evidence->>'quote') from public.user_narrator_source where user_id=snap.user_id and project_id=snap.project_id and id=original.source_id))>=(r->>'char_end')::integer
       and substring((select text from public.user_narrator_source where user_id=snap.user_id and project_id=snap.project_id and id=original.source_id)
         from (r->>'char_start')::integer+1 for (r->>'char_end')::integer-(r->>'char_start')::integer)<>''
       and strpos(original.evidence->>'quote',substring((select text from public.user_narrator_source where user_id=snap.user_id and project_id=snap.project_id and id=original.source_id)
         from (r->>'char_start')::integer+1 for (r->>'char_end')::integer-(r->>'char_start')::integer))>0)) then
      raise exception 'selected writing outside canonical evidence' using errcode='PT409';end if;
   -- Match the normal batch event shape; references retain their exact quote.
   select jsonb_agg(r||jsonb_build_object('quote',substring(n.text from (r->>'char_start')::integer+1 for (r->>'char_end')::integer-(r->>'char_start')::integer)))
     into refs from jsonb_array_elements(refs) r join public.user_narrator_source n on n.user_id=snap.user_id and n.project_id=snap.project_id and n.id::text=r->>'source_id';
   ev:=jsonb_build_object('id',evidence.id,'revision',evidence.revision,'kind',evidence.kind,'status',evidence.status,'life_stage',evidence.life_stage,
     'change_sequence',evidence.change_sequence,'title',left(evidence.data->>'title',300),'temporal',coalesce(evidence.data->'temporal','{}'),'source_refs',refs,'photo_associations','[]'::jsonb);
   events:=events||jsonb_build_array(ev);
 end loop;
 if jsonb_array_length(sources) not between 1 and 16 or jsonb_array_length(events) not between 1 and 8 then
   raise exception 'selected writing exceeds bounded editorial context' using errcode='22023';end if;
 previous:=jsonb_build_object('kind',section.bundle->>'kind','sections',section.bundle->'sections',
   'event_manifest',section.event_dependencies,'content_config',section.composition_config,
   'photo_association_manifest',coalesce(section.bundle->'photo_association_manifest','{}'::jsonb));
 page:=jsonb_set(page,'{batch,new_messages}','[]'::jsonb);
 page:=jsonb_set(page,'{batch,starting_after}',to_jsonb(snap.last_source));
 page:=jsonb_set(page,'{batch,through_source}',to_jsonb(snap.last_source));
 page:=jsonb_set(page,'{batch,next_offset}',to_jsonb(snap.next_offset));
 page:=jsonb_set(page,'{batch,cursor}',jsonb_build_array(snap.last_event,snap.last_event_id,snap.last_ref));
 page:=jsonb_set(page,'{batch,sources}',sources);page:=jsonb_set(page,'{batch,events}',events);
 page:=jsonb_set(page,'{batch,previous}',previous);
 page:=page||jsonb_build_object('complete',false,'reuse',false,'partition_key',request.partition_key,
   'partition',(select value from jsonb_array_elements(events) where value->>'id'=section.event_id),
   'source',sources->0,'editorial_request',jsonb_build_object('schema_version',1,'request_id',request.request_id,
      'instruction',request.instruction,'original_preview',request.original_preview));
 if octet_length((page->'batch')::text)>45000 then raise exception 'selected writing exceeds bounded editorial context' using errcode='22023';end if;
 page:=page-'input_digest'-'page_digest';
 page:=page||jsonb_build_object('input_digest',encode(sha256(convert_to((page-'token')::text,'UTF8')),'hex'));
 return page||jsonb_build_object('page_digest',encode(sha256(convert_to(page::text,'UTF8')),'hex'));
end $$;

CREATE FUNCTION public.read_lifetime_memoir_lane_page_body(p_lane_id uuid, p_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare snap public.user_lifetime_lane_snapshot%rowtype; lane public.user_memoir_lane%rowtype;
 source public.user_narrator_source%rowtype; event public.user_memory_event%rowtype; link record;
 payload jsonb; source_data jsonb; event_data jsonb; candidates jsonb:='[]'; preferences jsonb; ref jsonb;
 core integer; lo integer; hi integer; key text; reusable boolean:=false; previous_owner text;
begin
 snap:=public.lock_lifetime_memoir_lane(p_lane_id,p_token);
 select * into lane from public.user_memoir_lane where id=p_lane_id;
 previous_owner:=current_setting('request.jwt.claim.sub',true);
 perform set_config('request.jwt.claim.sub',snap.user_id::text,true);
 preferences:=public.read_lifetime_pinned(snap.conversation_id);
 -- Make optional transport defaults explicit without changing authoritative data.
 preferences:=jsonb_set(preferences,'{known_continuity}',coalesce((select jsonb_agg(
   jsonb_build_object('schema_version',1)||record||jsonb_build_object('data',
     jsonb_build_object('schema_version',1,'uncertainty',null)||(record->'data')||jsonb_build_object('source_refs',
       (select jsonb_agg(jsonb_build_object('schema_version',1)||continuity_ref) from jsonb_array_elements(record->'data'->'source_refs') continuity_ref))))
   from jsonb_array_elements(preferences->'known_continuity') record),'[]'));
 perform set_config('request.jwt.claim.sub',coalesce(previous_owner,''),true);
 payload:=jsonb_build_object('schema_version',1,'protocol','lifetime_composer_pages','lane_id',lane.id,'token',p_token,
   'snapshot_id',snap.id,'user_id',snap.user_id,'project_id',snap.project_id,'conversation_id',snap.conversation_id,
   'skill',lane.skill,'locale',snap.locale,'policy_epoch',snap.policy_epoch,'preference_revision',snap.preference_revision,
   'source_high_water',snap.source_high_water,'event_high_water',snap.event_high_water,'page_number',snap.page_number,
   'root_digest',snap.root_digest,'coverage_round',snap.round_high_water,'base_revision',snap.base_revision,
   'preferences',preferences,'previous',null,'reuse',false,'complete',false);
 if lane.skill='timeline' then
   select * into source from public.user_narrator_source where user_id=snap.user_id and project_id=snap.project_id
     and status='active' and processing_status<>'succeeded' and sequence<=snap.source_high_water
     and (sequence>snap.last_source or (sequence=snap.last_source and snap.next_offset<length(text)))
     order by sequence limit 1;
   if not found then return payload||jsonb_build_object('complete',true,'source',null,'events','[]'::jsonb,'partition',null);end if;
   core:=greatest(case when source.sequence=snap.last_source then snap.next_offset else 0 end,
     coalesce((select next_offset from public.user_lifetime_source_extraction where user_id=snap.user_id and project_id=snap.project_id
       and source_id=source.id and source_version=source.version),0));
   if core>=length(source.text) then core:=0;end if;
   lo:=greatest(core-256,0);hi:=least(core+2048,length(source.text));
   -- Indexed, bounded candidate pools. Preserve the current interview identity
   -- even when it is older than the recent tail; no full-event history sort.
   with active as (
     select e.id,0 priority from public.user_interview_plan p join public.user_memory_event e
       on e.user_id=p.user_id and e.project_id=p.project_id and e.id=p.plan->>'active_event_id'
     where p.user_id=snap.user_id and p.project_id=snap.project_id and e.status='active' and e.change_sequence<=snap.event_high_water
   ), same_source as (
     select e.id,1 priority from public.user_memory_event_source r join public.user_memory_event e
       on e.user_id=r.user_id and e.project_id=r.project_id and e.id=r.event_id
     where r.user_id=snap.user_id and r.project_id=snap.project_id and r.source_id=source.id
       and e.status<>'withdrawn' and e.change_sequence<=snap.event_high_water order by r.event_id limit 8
   ), recent as (
     select id,2 priority from public.user_memory_event where user_id=snap.user_id and project_id=snap.project_id
       and status<>'withdrawn' and change_sequence<=snap.event_high_water order by change_sequence desc,id desc limit 8
   ), selected as (
     select id,min(priority) priority from (select * from active union all select * from same_source union all select * from recent) pool group by id
   )
   select coalesce(jsonb_agg(item order by priority,change_sequence desc,id),'[]') into candidates from (
     select e.id,e.change_sequence,c.priority,jsonb_build_object('id',e.id,'revision',e.revision,'kind',e.kind,
       'title',left(e.data->>'title',300),'life_stage',e.life_stage,'status',e.status,'source_refs','[]'::jsonb,
       'identity_context_only',true,'active_interview_context',c.priority=0) item
     from selected c join public.user_memory_event e on e.user_id=snap.user_id and e.project_id=snap.project_id and e.id=c.id
     order by c.priority,e.change_sequence desc,e.id limit 8) bounded;
   source_data:=jsonb_build_object('id',source.id,'project_id',source.project_id,'version',source.version,'sequence',source.sequence,
     'text',substring(source.text from lo+1 for hi-lo),'char_start',lo,'char_end',hi,'original_length',length(source.text),
     'kind',source.kind,'language',source.language,'status',source.status,'author_role','storyteller');
   return payload||jsonb_build_object('source',source_data,'events',candidates,'partition',null,'core_start',core,'core_end',hi);
 end if;
 -- Keyset over event revisions and exact evidence rows, including unsupported
 -- or withdrawn events as explicit coverage dispositions. No aggregate manifest.
 select e.*,r.source_id,r.source_version,r.evidence_hash,r.evidence, p.id as photo_link_id,p.photo_id,p.quote as photo_quote,p.description as photo_description into link
   from public.user_memory_event e left join public.user_memory_event_source r
     on r.user_id=e.user_id and r.project_id=e.project_id and r.event_id=e.id
   left join public.user_interview_photo_link p on p.user_id=e.user_id and p.project_id=e.project_id and p.event_id=e.id
     and p.source_id=r.source_id and p.source_version=r.source_version and p.status='confirmed' and p.provenance='narrator_metadata'
     and strpos(r.evidence->>'quote',p.quote)>0 and public.interview_photo_available(e.user_id,e.project_id,p.photo_id)
   where e.user_id=snap.user_id and e.project_id=snap.project_id
     and (e.change_sequence>snap.base_event or exists(select 1 from public.user_workspace_section_rework request
       where request.user_id=snap.user_id and request.project_id=snap.project_id and request.locale=snap.locale
         and request.status='pending' and request.event_id=e.id and request.event_revision=e.revision
         and request.partition_key=e.id||':'||r.source_id::text||':'||r.source_version::text||':'||r.evidence_hash||':'||coalesce(p.id::text,'')))
     and e.change_sequence<=snap.event_high_water
     and (e.change_sequence,e.id,coalesce(r.source_id::text||':'||r.source_version::text||':'||r.evidence_hash||':'||coalesce(p.id::text,''),''))>
       (snap.last_event,snap.last_event_id,snap.last_ref)
   order by e.change_sequence,e.id,coalesce(r.source_id::text||':'||r.source_version::text||':'||r.evidence_hash||':'||coalesce(p.id::text,''),'') limit 1;
 if not found then return payload||jsonb_build_object('complete',true,'source',null,'events','[]'::jsonb,'partition',null);end if;
 key:=coalesce(link.source_id::text||':'||link.source_version::text||':'||link.evidence_hash||':'||coalesce(link.photo_link_id::text,''),'');
 event_data:=jsonb_build_object('id',link.id,'revision',link.revision,'kind',link.kind,'life_stage',link.life_stage,
   'status',link.status,'change_sequence',link.change_sequence,'title',left(link.data->>'title',300),
   'uncertainty',left(link.data->>'uncertainty',2000),
   'temporal',jsonb_build_object('expression',left(link.data->'temporal'->>'expression',500),'precision','unknown'),
   'source_refs','[]'::jsonb);
 if link.status='active' and link.source_id is not null then
   select * into source from public.user_narrator_source where user_id=snap.user_id and project_id=snap.project_id
     and id=link.source_id and version=link.source_version and status='active';
   if found then
     ref:=link.evidence;lo:=coalesce((ref->>'char_start')::integer,strpos(source.text,ref->>'quote')-1);
     hi:=coalesce((ref->>'char_end')::integer,lo+length(ref->>'quote'));
     if lo<0 or hi<=lo or hi>length(source.text) or hi-lo>2000 or
       substring(source.text from lo+1 for hi-lo) is distinct from ref->>'quote' or
       (not ref ? 'char_start' and strpos(substring(source.text from lo+2),ref->>'quote')>0) then
       raise exception 'canonical evidence requires an exact unambiguous span' using errcode='22023';
     end if;
     ref:=ref||jsonb_build_object('char_start',lo,'char_end',hi);
     source_data:=jsonb_build_object('id',source.id,'project_id',source.project_id,'version',source.version,'sequence',source.sequence,
       'text',substring(source.text from lo+1 for hi-lo),'char_start',lo,'char_end',hi,'original_length',length(source.text),
       'kind',source.kind,'language',source.language,'status',source.status,'author_role','storyteller');
     event_data:=event_data||jsonb_build_object('source_refs',jsonb_build_array(ref),
       'photo_associations',case when link.photo_link_id is null then '[]'::jsonb else jsonb_build_array(jsonb_build_object(
         'id',link.photo_link_id,'photo_id',link.photo_id,'event_id',link.id,'source_id',source.id,'source_version',source.version,
         'quote',link.photo_quote,'description',link.photo_description,'status','confirmed','provenance','narrator_metadata')) end);
     select exists(select 1 from public.user_lifetime_memoir_section s join public.user_lifetime_lane_snapshot ss on ss.id=s.snapshot_id
       where s.user_id=snap.user_id and s.project_id=snap.project_id and s.locale=snap.locale
       and s.partition_key=link.id||':'||key and s.event_revision=link.revision and s.source_version=source.version
       and ss.state='completed' and ss.preference_revision=snap.preference_revision and ss.policy_epoch=snap.policy_epoch)
       into reusable;
   end if;
 end if;
 return payload||jsonb_build_object('source',source_data,'partition',event_data,'events','[]'::jsonb,
   'partition_key',link.id||':'||key,'ref_key',key,'reuse',reusable);
end $$;

CREATE FUNCTION public.read_lifetime_memory_obligations(p_conversation_id uuid, p_after uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 32) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare records jsonb; more boolean; cursor_time timestamptz;
begin
  if not exists(select 1 from public.user_lifetime_conversation where user_id=auth.uid() and conversation_id=p_conversation_id) then raise exception 'conversation unavailable'; end if;
  if p_limit is null or p_limit not between 1 and 32 then raise exception 'invalid inspection bounds'; end if;
  if p_after is not null and not exists(select 1 from public.user_lifetime_memory_obligation where user_id=auth.uid()
    and conversation_id=p_conversation_id and id=p_after) then raise exception 'invalid inspection cursor'; end if;
  if p_after is not null then select created_at into cursor_time from public.user_lifetime_memory_obligation where id=p_after; end if;
  select coalesce(jsonb_agg(public.lifetime_obligation_record(o) order by o.created_at,o.id),'[]') into records from
    (select * from public.user_lifetime_memory_obligation where user_id=auth.uid() and conversation_id=p_conversation_id
      and (p_after is null or (created_at,id)>(cursor_time,p_after)) order by created_at,id limit p_limit+1) o;
  more:=jsonb_array_length(records)>p_limit;
  if more then records:=records-p_limit; end if;
  return jsonb_build_object('schema_version',1,'records',records,'complete',not more,'next_cursor',case when more then records->-1->>'id' else null end,'backup_complete',false);
end $$;

CREATE FUNCTION public.read_lifetime_pinned(p_conversation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare owner uuid:=auth.uid(); identity public.user_lifetime_conversation%rowtype; profile jsonb;
  question text; plan jsonb; continuity jsonb; epoch bigint; record jsonb; selected_bytes integer:=0; omitted boolean:=false; policy_record record; policy_bytes integer:=0; privacy_complete boolean:=true; paused jsonb; excluded jsonb; unresolved jsonb;
begin
  select * into identity from public.user_lifetime_conversation where user_id=owner and conversation_id=p_conversation_id;
  if not found then raise exception 'conversation unavailable'; end if;
  select policy_epoch into epoch from public.user_memoir_project where user_id=owner and project_id=identity.project_id for share;
  select p.profile into profile from public.user_profile p where p.user_id=owner for share;
  select * into identity from public.user_lifetime_conversation where user_id=owner and conversation_id=p_conversation_id;
  select p.plan into plan from public.user_interview_plan p where user_id=owner and project_id=identity.project_id;
  select c->>'question' into question from jsonb_array_elements(coalesce(plan->'candidates','[]')) c where c->>'id'=plan->>'chosen_id';
  -- Only a bounded recent working set belongs in the prompt. Historical typed
  -- records remain available via the explicit paginated retrieval RPC. Privacy,
  -- language, exclusions and active question below are authoritative pins
  -- and are never selected by lexical relevance.
  continuity:='[]'::jsonb;
  for record in select to_jsonb(c)-'user_id'-'conversation_id'-'last_source_sequence' from public.user_lifetime_continuity c
    where c.user_id=owner and c.conversation_id=p_conversation_id and c.policy_epoch=epoch
      and not exists(select 1 from jsonb_array_elements(c.data->'source_refs') ref where not exists(
        select 1 from public.user_narrator_source s where s.user_id=owner and s.project_id=identity.project_id
          and s.id=(ref->>'source_id')::uuid and s.version=(ref->>'version')::bigint and s.status='active'))
    order by case c.kind when 'unresolved_reference' then 0 when 'commitment' then 1 else 2 end,
      c.last_source_sequence desc,c.record_id
    limit 9
  loop
    if jsonb_array_length(continuity)>=8 or selected_bytes+octet_length(record::text)>8000 then omitted:=true;
    else continuity:=continuity||jsonb_build_array(record);selected_bytes:=selected_bytes+octet_length(record::text); end if;
  end loop;
  paused:=coalesce(profile->'memory_preferences'->'paused_topics','[]');
  excluded:=coalesce(profile->'memory_preferences'->'excluded_topics','[]');
  unresolved:=coalesce(profile->'memory_preferences'->'unresolved_references','[]');
  policy_bytes:=octet_length(paused::text)+octet_length(excluded::text)+octet_length(unresolved::text);
  privacy_complete:=policy_bytes<=16384;
  if privacy_complete then
    for policy_record in select kind,data->>'text' as text from public.user_lifetime_continuity
      where user_id=owner and conversation_id=p_conversation_id and policy_epoch=epoch and kind in ('paused_topic','excluded_topic')
      order by record_id limit 16385 loop
      policy_bytes:=policy_bytes+octet_length(to_jsonb(policy_record.text)::text)+1;
      if policy_bytes>16384 then privacy_complete:=false;exit;end if;
      if policy_record.kind='paused_topic' then paused:=paused||to_jsonb(policy_record.text);
      else excluded:=excluded||to_jsonb(policy_record.text);end if;
    end loop;
  end if;
  -- Never send a partial policy to a model. The coordinator returns an accepted
  -- maintenance receipt when this active configuration exceeds one request.
  if not privacy_complete then paused:='[]';excluded:='[]';unresolved:='[]';end if;
  return jsonb_build_object('schema_version',1,'known_continuity',continuity,'known_continuity_complete',not omitted,
    'continuity_retrieval','read_lifetime_continuity','preference_revision',identity.preference_revision,
    'chosen_name',profile->>'name','language',case when profile->>'preferred_language' in ('en-AU','zh-CN') then profile->>'preferred_language' else 'en-AU' end,
    'active_question',question,'privacy_complete',privacy_complete,'unresolved_references',unresolved,
    'paused_topics',paused,'excluded_topics',excluded);
end $$;

CREATE FUNCTION public.read_lifetime_place_journeys(p_project_id text, p_source_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner uuid:=auth.uid(); result jsonb; pins jsonb; privacy_hash text;
begin
 if not exists(select 1 from public.user_lifetime_conversation where user_id=owner and project_id=p_project_id)
   then raise exception 'canonical conversation required'; end if;
 perform 1 from public.user_memoir_project where user_id=owner and project_id=p_project_id for share;
 pins:=public.read_lifetime_pinned((select conversation_id from public.user_lifetime_conversation where user_id=owner and project_id=p_project_id));
 privacy_hash:=encode(sha256(convert_to(jsonb_build_object('excluded_topics',pins->'excluded_topics',
   'paused_topics',pins->'paused_topics','privacy_complete',pins->'privacy_complete')::text,'UTF8')),'hex');
 select coalesce(jsonb_agg(journey||jsonb_build_object('source_sequence',sequence,
   'status','active','revision',version,'updated_at',created_at) order by sequence,ordinal),'[]') into result
 from (
   select distinct on (journey->'hierarchy',journey->>'granularity') journey,s.sequence,s.version,s.created_at,ordinal
   from public.user_lifetime_place_journey p join public.user_narrator_source s
     on s.user_id=p.user_id and s.project_id=p.project_id and s.id=p.source_id
       and s.version=p.source_version and s.status='active'
   cross join lateral jsonb_array_elements(p.journeys) with ordinality as items(journey,ordinal)
   where p.user_id=owner and p.project_id=p_project_id
     and (p.derived_fence is null or exists(select 1 from public.user_lifetime_conversation c join public.user_memoir_project m
       on m.user_id=c.user_id and m.project_id=c.project_id where c.user_id=p.user_id and c.project_id=p.project_id
       and p.derived_fence->>'policy_epoch'=m.policy_epoch::text
       and p.derived_fence->>'privacy_digest'=privacy_hash
       and p.derived_fence->>'execution_generation'=c.execution_generation::text)) and (p_source_id is null or p.source_id=p_source_id)
   order by journey->'hierarchy',journey->>'granularity',s.sequence desc,ordinal
   limit 1000
 ) places;
 return result;
end $$;

CREATE FUNCTION public.read_lifetime_policy_status(p_conversation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner uuid:=auth.uid(); project text; pending public.user_lifetime_pending_policy%rowtype; is_pending boolean; opening jsonb;
begin
 select project_id into project from public.user_lifetime_conversation where user_id=owner and conversation_id=p_conversation_id;
 if not found then raise exception 'conversation unavailable' using errcode='42501';end if;
 perform 1 from public.user_memoir_project where user_id=owner and project_id=project for share;
 select * into pending from public.user_lifetime_pending_policy where user_id=owner and conversation_id=p_conversation_id order by source_id limit 1;
 is_pending:=found or exists(select 1 from public.user_lifetime_policy_inventory_pending where user_id=owner and project_id=project);
 if not is_pending then
   select jsonb_build_object('source_id',s.id,'source_version',s.version,
     'language',r.review#>>'{receipt,acknowledgement_language}','text',r.review#>>'{receipt,acknowledgement}') into opening
   from public.user_narrator_source s join public.user_lifetime_source_policy_receipt r
     on r.user_id=s.user_id and r.project_id=s.project_id and r.source_id=s.id and r.source_version=s.version
   join public.user_memoir_project p on p.user_id=s.user_id and p.project_id=s.project_id and p.source_sequence=s.sequence
   where s.user_id=owner and s.project_id=project and s.status='active'
     and jsonb_typeof(r.review#>'{receipt,acknowledgement}')='string';
 end if;
 return jsonb_build_object('pending',is_pending,'reviewed_acknowledgement',opening,'pending_source_id',pending.source_id,'pending_source_version',pending.source_version,
   'pending_client_turn_id',pending.client_turn_id,'parser_version','semantic-v1');
end $$;

CREATE FUNCTION public.read_lifetime_prepared_questions_live(p_conversation_id uuid) RETURNS jsonb
 LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
declare identity public.user_lifetime_conversation%rowtype; pins jsonb; result jsonb;
begin
 pins:=public.read_lifetime_pinned(p_conversation_id);
 if not exists(select 1 from public.lifetime_two_lane_rollout where singleton and enabled) then return '[]'::jsonb;end if;
 select * into identity from public.user_lifetime_conversation where user_id=auth.uid() and conversation_id=p_conversation_id;
 with consumed as materialized (select * from public.lifetime_consumed_question_ids(auth.uid(),identity.project_id))
 select coalesce(jsonb_agg(item),'[]') into result from (
   select q||jsonb_build_object('id',public.lifetime_question_id(d.source_id,d.source_version,q),
     'source_id',d.source_id,'source_version',d.source_version,'creation_revision',d.source_revision,'based_on_sequence',s.sequence,
     'snapshot_id',d.snapshot_id,'policy_epoch',d.policy_epoch,'task_version','two-lane-v1',
     'invalidation',case when q->'requires_confirmation'='true'::jsonb then 'source/policy/preference/generation/delivered question'
       else 'source/policy/preference/generation/recent coverage/delivered question' end) item
   from public.user_lifetime_prepared_question d join public.user_narrator_source s on s.user_id=d.user_id and s.project_id=d.project_id
     and s.id=d.source_id and s.version=d.source_version and s.status='active'
   join public.user_memoir_project p on p.user_id=d.user_id and p.project_id=d.project_id
   cross join lateral jsonb_array_elements(d.questions) with ordinality hints(q,position)
   where d.user_id=auth.uid() and d.project_id=identity.project_id and d.policy_epoch=p.policy_epoch
     and d.preference_revision=identity.preference_revision and d.execution_generation=identity.execution_generation
     and (q->'requires_confirmation'='true'::jsonb or d.source_revision>=p.source_sequence-1)
     -- Defense against delayed B publication; only actual delivery consumes a question.
     and not exists(select 1 from consumed
       where consumed.question_id=public.lifetime_question_id(d.source_id,d.source_version,q))
     and public.lifetime_guidance_question_current(d.user_id,d.project_id,q)
     and (q->>'historical_clue_id' is null or exists(select 1 from public.user_historical_news_clue c
       where c.user_id=d.user_id and c.project_id=d.project_id and c.id=q->>'historical_clue_id' and c.status='ready'
         and c.context_revision=public.historical_news_revision(d.user_id,d.project_id)
         and not exists(select 1 from public.user_historical_news_state n where n.user_id=d.user_id and n.project_id=d.project_id and not n.enabled)))
   order by public.lifetime_guidance_priority(q),
     case when q->'requires_confirmation'='true'::jsonb then s.sequence end,
     s.sequence desc,d.source_id,position limit 3
 ) hints;
 return result;
end $$;
REVOKE ALL ON FUNCTION public.read_lifetime_prepared_questions_live(uuid) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION public.read_lifetime_prepared_questions(p_conversation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare identity public.user_lifetime_conversation%rowtype; pins jsonb; result jsonb; current_turn public.user_interview_turn%rowtype; lease uuid; context_fence jsonb;
begin
 -- Reuse the existing content access/policy guard before selecting any bytes.
 pins:=public.read_lifetime_pinned(p_conversation_id);
 if not exists(select 1 from public.lifetime_two_lane_rollout where singleton and enabled) then return '[]'::jsonb;end if;
 select * into identity from public.user_lifetime_conversation where user_id=auth.uid() and conversation_id=p_conversation_id;
 select lease_token into lease from public.user_agent_turn_lease where user_id=auth.uid() and expires_at>clock_timestamp();
 if lease is not null then
   select * into current_turn from public.user_interview_turn where user_id=auth.uid() and project_id=identity.project_id
     and collector is null order by sequence desc limit 1;
   context_fence:=jsonb_build_object('lease_digest',encode(sha256(convert_to(lease::text,'UTF8')),'hex'),
     'policy_epoch',(select policy_epoch from public.user_memoir_project where user_id=auth.uid() and project_id=identity.project_id),
     'preference_revision',identity.preference_revision,'execution_generation',identity.execution_generation,
     'source_id',current_turn.source_id,'source_version',current_turn.source_version);
   if current_turn.interview_guidance_snapshot->'fence'=context_fence and current_turn.interview_guidance_snapshot ? 'questions' then
     -- Ranking/replacement by B is not revocation of A's captured read set.
     -- Real evidence or policy changes still invalidate the selected question.
     with consumed as materialized(select * from public.lifetime_consumed_question_ids(auth.uid(),identity.project_id))
     select coalesce(jsonb_agg(q order by position),'[]') into result
       from jsonb_array_elements(current_turn.interview_guidance_snapshot->'questions') with ordinality items(q,position)
       where public.lifetime_guidance_question_current(auth.uid(),identity.project_id,q)
         and exists(select 1 from public.user_narrator_source n where n.user_id=auth.uid() and n.project_id=identity.project_id
           and n.id=(q->>'source_id')::uuid and n.version=(q->>'source_version')::bigint and n.status='active')
         and not exists(select 1 from consumed where question_id=q->>'id');
     return result;
   end if;
 end if;
 result:=public.read_lifetime_prepared_questions_live(p_conversation_id);
 if current_turn.client_turn_id is not null then
   update public.user_interview_turn set interview_guidance_snapshot=jsonb_set(
     case when interview_guidance_snapshot->'fence'=context_fence then interview_guidance_snapshot else jsonb_build_object('fence',context_fence) end,
     '{questions}',result) where user_id=auth.uid() and project_id=identity.project_id and client_turn_id=current_turn.client_turn_id;
 end if;
 return result;
end $$;

CREATE FUNCTION public.read_lifetime_private_draft_head(p_project_id text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
 select public.read_lifetime_private_draft_head(p_project_id,null)
$$;

CREATE FUNCTION public.read_lifetime_private_draft_head(p_project_id text, p_locale text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare result jsonb; lane public.user_memoir_lane%rowtype; extraction jsonb; pending bigint; extracted bigint;
begin
 result:=public.read_lifetime_private_draft_head_before_extraction_progress(p_project_id,p_locale);
 if result is null or result->>'project_id' is distinct from p_project_id then return result;end if;
 select * into lane from public.user_memoir_lane where user_id=auth.uid() and project_id=p_project_id and skill='timeline';
 select count(*) into pending from public.user_narrator_source where user_id=auth.uid() and project_id=p_project_id
  and status='active' and processing_status<>'succeeded';
 select extraction_cursor into extracted from public.user_memoir_project where user_id=auth.uid() and project_id=p_project_id;
 extraction:=public.memoir_lane_progress(lane)||jsonb_build_object('pending_inputs',pending,'extracted_through',coalesce(extracted,0));
 if pending>0 and extraction->>'state'='finished' then
  extraction:=extraction||jsonb_build_object('state','pending','pending',true);
 end if;
 result:=result||jsonb_build_object('progress',coalesce(result->'progress','{}')||jsonb_build_object('extraction',extraction));
 if coalesce((result->'background_progress'->>'target_milestone')::bigint,0)<5 then return result;end if;
 if pending>0 and extraction->>'state'='retry_required' then
  return result||jsonb_build_object('updating',false,'error',coalesce(extraction->>'error','MEMOIR_UNAVAILABLE'),
   'background_progress',coalesce(result->'background_progress','{}')||jsonb_build_object('state','retry_required','phase','extracting'));
 end if;
 if pending>0 and coalesce(result->'progress'->'composition'->>'state','pending') in ('pending','finished') then
  result:=result||jsonb_build_object('updating',true,'background_progress',
   coalesce(result->'background_progress','{}')||jsonb_build_object('state',extraction->>'state','phase','extracting'));
 end if;
 return result;
end $$;

CREATE FUNCTION public.read_lifetime_private_draft_head_before_extraction_progress(p_project_id text, p_locale text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare result jsonb;lane public.user_memoir_lane%rowtype;progress jsonb;phase text;target bigint;rounds bigint;state text;
begin
 result:=public.read_lifetime_private_draft_head_before_progress(p_project_id,p_locale);
 if result is null then return null;end if;
 select * into lane from public.user_memoir_lane where user_id=auth.uid() and project_id=p_project_id and skill='composer';
 select coalesce(max(ordinal),0) into rounds from public.user_completed_round where user_id=auth.uid() and project_id=p_project_id;
 target:=greatest(coalesce(lane.target_milestone,0),(rounds/5)*5);
 if target<5 then return result;end if;
 progress:=public.memoir_lane_progress(lane);state:=progress->>'state';
 if state='finished' and coalesce((result->>'coverage_round')::bigint,0)<target then state:='pending';end if;
 select c.value->>'phase' into phase from public.user_memoir_checkpoint c join public.user_lifetime_lane_snapshot root on root.id=c.lifetime_snapshot_id
  where c.lane_id=lane.id and c.kind='compose' and root.state='pending' and root.locale=coalesce(p_locale,result->>'locale')
  order by c.created_at desc limit 1;
 if phase not in ('summarizing','drafting','reviewing','saving') then phase:=null;end if;
 progress:=progress||jsonb_build_object('state',state,'target_milestone',target);
 return result||jsonb_build_object('background_progress',jsonb_build_object('state',state,'phase',phase,'target_milestone',target),
  'progress',jsonb_build_object('composition',progress),'updating',state in ('pending','running'));
end $$;

CREATE FUNCTION public.read_lifetime_private_draft_head_before_progress(p_project_id text, p_locale text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare identity public.user_lifetime_conversation%rowtype; project public.user_memoir_project%rowtype;
 root public.user_lifetime_lane_snapshot%rowtype; lane public.user_memoir_lane%rowtype; page jsonb; output_locale text;
begin
 if auth.uid() is null then raise exception 'authenticated owner required';end if;
 if p_locale is not null and p_locale not in ('en-AU','zh-CN') then raise exception 'invalid memoir edition' using errcode='22023';end if;
 select * into identity from public.user_lifetime_conversation where user_id=auth.uid();
 if not found then return null;end if;
 if identity.project_id is distinct from p_project_id then
   return jsonb_build_object('schema_version',1,'owner_id',auth.uid(),'conversation_id',identity.conversation_id,
     'project_id',identity.project_id,'status','pending','preview',null,'updating',false,'retrieval_complete',false,'error','LIFETIME_PROJECT_REQUIRED');
 end if;
 select * into project from public.user_memoir_project where user_id=auth.uid() and project_id=p_project_id for share;
 perform 1 from public.user_profile where user_id=auth.uid() for share;
 select * into identity from public.user_lifetime_conversation where conversation_id=identity.conversation_id for share;
 select case when profile->>'preferred_language'='zh-CN' then 'zh-CN' else 'en-AU' end into output_locale from public.user_profile where user_id=auth.uid();
 output_locale:=coalesce(p_locale,output_locale,'en-AU');
 select * into lane from public.user_memoir_lane where user_id=auth.uid() and project_id=p_project_id and skill='composer';
 select * into root from public.user_lifetime_lane_snapshot where lane_id=lane.id and state in ('completed','proposed') and policy_epoch=project.policy_epoch
   and preference_revision=identity.preference_revision and user_lifetime_lane_snapshot.locale=output_locale order by created_at desc limit 1;
 if root.id is not null then page:=public.read_lifetime_private_draft_page(p_project_id,root.id,null,1);end if;
 return jsonb_build_object('schema_version',1,'owner_id',auth.uid(),'conversation_id',identity.conversation_id,
   'project_id',p_project_id,'locale',output_locale,'policy_epoch',project.policy_epoch,
   'source_revision',coalesce(root.source_high_water,project.source_sequence),'event_revision',root.event_high_water,
   'current_source_revision',project.source_sequence,'current_event_revision',project.event_sequence,'coverage_scope','frozen_root',
   'status',case when root.id is not null then case when jsonb_array_length(page->'records')>0 then 'ready' else 'insufficient_context' end else 'pending' end,
   'first_record',page->'records'->0,'preview',page->'records'->0->'preview','proposed_preview',page->'records'->0->'proposed_preview',
   'snapshot_state',root.state,'approval_required',root.state='proposed','original_withheld',page->'records'->0->'original_withheld','updating',coalesce(lane.pending or lane.token is not null,false),
   'retrieval_complete',root.id is not null,'snapshot_id',root.id,'root_digest',root.root_digest,
   'page_complete',page->'complete','next_cursor',page->'next_cursor','coverage_round',root.round_high_water,
   'revision',root.base_revision+case when root.state='completed' then 1 else 0 end,'publication_approved',false,
   'error',case when root.id is null then coalesce(lane.error,'LIFETIME_COMPOSITION_PENDING') else null end);
end $$;

CREATE FUNCTION public.read_lifetime_private_draft_page(p_project_id text, p_snapshot_id uuid, p_after text DEFAULT NULL::text, p_limit integer DEFAULT 8) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare owner uuid:=auth.uid(); identity public.user_lifetime_conversation%rowtype; project public.user_memoir_project%rowtype;
 root public.user_lifetime_lane_snapshot%rowtype; records jsonb; has_more boolean; next_key text; after_key text:=''; next_cursor uuid;
begin
 if owner is null or p_limit is null or p_limit not between 1 and 8 or length(coalesce(p_after,''))>512 then raise exception 'invalid memoir page';end if;
 select * into identity from public.user_lifetime_conversation where user_id=owner and project_id=p_project_id;
 if not found then raise exception 'canonical conversation unavailable';end if;
 select * into project from public.user_memoir_project where user_id=owner and project_id=p_project_id for share;
 perform 1 from public.user_profile where user_id=owner for share;
 select * into identity from public.user_lifetime_conversation where conversation_id=identity.conversation_id for share;
 select s.* into root from public.user_lifetime_lane_snapshot s join public.user_memoir_lane l on l.id=s.lane_id
   where s.id=p_snapshot_id and s.user_id=owner and s.project_id=p_project_id and s.conversation_id=identity.conversation_id
     and s.state in ('completed','proposed') and l.skill='composer' and s.policy_epoch=project.policy_epoch and s.preference_revision=identity.preference_revision;
 if not found then raise exception 'stale memoir root' using errcode='PT409';end if;
 if p_after is not null then
   select last_partition into after_key from public.user_lifetime_memoir_cursor where id=p_after::uuid
     and snapshot_id=root.id and user_id=owner and project_id=p_project_id and root_digest=root.root_digest;
   if not found then raise exception 'memoir page cursor scope mismatch';end if;
 end if;
 select coalesce(jsonb_agg(item order by partition_key),'[]') into records from (
   select s.partition_key,jsonb_build_object('id',s.partition_key,'event_id',s.event_id,'event_revision',s.event_revision,
     'source_refs',coalesce(s.bundle->'source_refs',jsonb_build_array(jsonb_build_object('source_id',s.source_id,'version',s.source_version,'char_start',s.char_start,'char_end',s.char_end))),
     'preview',case when root.state='proposed' and s.snapshot_id=root.id and s.proposal is null and not(s.approved or s.human_locked) then null
       when validity.all_current or s.approved or s.human_locked then s.bundle->'preview'
       else jsonb_set(s.bundle->'preview','{title}',to_jsonb(e.data->>'title')) end,
     'proposed_preview',case when root.state='proposed' and s.snapshot_id=root.id and s.proposal is null and not(s.approved or s.human_locked) then s.bundle->'preview' else s.proposal->'preview' end,
     'proposal_digest',case when s.proposal is not null then encode(sha256(convert_to(s.proposal::text,'UTF8')),'hex') else null end,
     'original_withheld',s.proposal is not null and not(s.bundle ? 'preview'),'approval_required',root.state='proposed',
     'approved',s.approved,'human_locked',s.human_locked) item
   from public.user_lifetime_memoir_section s join public.user_lifetime_lane_snapshot ss on ss.id=s.snapshot_id
     join public.user_memory_event e on e.user_id=s.user_id and e.project_id=s.project_id and e.id=s.event_id and e.revision=s.event_revision and e.status='active'
     join public.user_narrator_source n on n.user_id=s.user_id and n.project_id=s.project_id and n.id=s.source_id and n.version=s.source_version and n.status='active'
   cross join lateral (select
     not exists(select 1 from jsonb_array_elements(s.event_dependencies) dependency where not exists(
       select 1 from public.user_memory_event original where original.user_id=s.user_id and original.project_id=s.project_id
         and original.id=dependency->>'id' and original.revision::text=dependency->>'revision' and original.status='active')) all_current,
     exists(select 1 from jsonb_array_elements(s.bundle->'sections') body where body ? 'block'
       and body->>'id'=s.bundle->'preview'->>'id' and body->'event_ids' ? s.event_id
       and not exists(select 1 from jsonb_array_elements_text(body->'event_ids') id where not exists(
         select 1 from jsonb_array_elements(s.event_dependencies) dependency join public.user_memory_event original
           on original.user_id=s.user_id and original.project_id=s.project_id and original.id=dependency->>'id'
             and original.revision::text=dependency->>'revision' and original.status='active'
         where dependency->>'id'=id))) body_current) validity
   where s.user_id=owner and s.project_id=p_project_id and s.locale=root.locale and s.partition_key>after_key and not s.retired
     and not exists(select 1 from jsonb_array_elements(s.source_dependencies) dependency where not exists(
       select 1 from public.user_narrator_source original where original.user_id=s.user_id and original.project_id=s.project_id
        and original.id::text=dependency->>'id' and original.version::text=dependency->>'version' and original.status='active'))
     -- A changed chapter heading must not hide an independently unchanged body.
     and (validity.all_current or validity.body_current)
     and (ss.state='completed' or ss.id=root.id and ss.state='proposed') and ss.privacy_digest=root.privacy_digest and ss.policy_epoch=root.policy_epoch and ss.created_at<=root.created_at
     and not exists(select 1 from public.user_lifetime_memoir_section newer join public.user_lifetime_lane_snapshot ns on ns.id=newer.snapshot_id
       where newer.user_id=s.user_id and newer.project_id=s.project_id and newer.locale=s.locale and newer.partition_key=s.partition_key
         and (ns.state='completed' or ns.id=root.id and ns.state='proposed') and ns.created_at>ss.created_at and ns.created_at<=root.created_at)
   order by s.partition_key limit p_limit+1) selected;
 has_more:=jsonb_array_length(records)>p_limit;
 if has_more then
   records:=records-p_limit;next_key:=records->-1->>'id';
   insert into public.user_lifetime_memoir_cursor(snapshot_id,user_id,project_id,last_partition,root_digest) values(root.id,owner,p_project_id,next_key,root.root_digest)
     on conflict(snapshot_id,last_partition,root_digest) do update set last_partition=excluded.last_partition returning id into next_cursor;
 end if;
 return jsonb_build_object('schema_version',1,'owner_id',owner,'conversation_id',identity.conversation_id,'project_id',p_project_id,
   'snapshot_id',root.id,'root_digest',root.root_digest,'locale',root.locale,'source_revision',root.source_high_water,'event_revision',root.event_high_water,
   'policy_epoch',root.policy_epoch,'preference_revision',root.preference_revision,'snapshot_complete',true,
   'snapshot_state',root.state,'approval_required',root.state='proposed',
   'records',records,'complete',not has_more,'next_cursor',next_cursor,'publication_approved',false);
end $$;

CREATE FUNCTION public.read_lifetime_profile_automation() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare identity public.user_lifetime_conversation%rowtype; automation jsonb; progress jsonb; dirty boolean;
begin
 select * into identity from public.user_lifetime_conversation where user_id=auth.uid() and product='memoir';
 if not found then raise exception 'mapped conversation required' using errcode='42501';end if;
 perform 1 from public.user_memoir_project where user_id=identity.user_id and project_id=identity.project_id for share;
 perform 1 from public.user_profile where user_id=identity.user_id for share;
 automation:=coalesce(public.lifetime_profile_automation(identity.user_id),jsonb_build_object('schema_version',1,
   'revision',0,'auto_enabled',true,'stopped',false,'manual_complete',false,'field_locks','{}'::jsonb));
 select to_jsonb(p)-'user_id'-'project_id'||jsonb_build_object('status',case
   when p.active_round>0 or p.requested_round>greatest(p.covered_round,p.skipped_round) then 'pending'
   when p.skipped_round>p.covered_round then 'skipped' when p.covered_round>0 then 'covered' else 'idle' end)
 into progress from public.user_lifetime_profile_progress p
 where p.user_id=identity.user_id and p.project_id=identity.project_id;
 select exists(select 1 from public.user_narrator_source s where s.user_id=identity.user_id and s.project_id=identity.project_id
   and s.status='active' and (s.sequence<=coalesce((progress->>'covered_frontier')::bigint,0)
     or exists(select 1 from public.user_lifetime_profile_coverage old where old.user_id=s.user_id
       and old.project_id=s.project_id and old.source_id=s.id and old.source_version<>s.version))
   and not exists(select 1 from public.user_lifetime_profile_coverage current where current.user_id=s.user_id
     and current.project_id=s.project_id and current.source_id=s.id and current.source_version=s.version
     and current.next_offset>=length(s.text))) into dirty;
 if dirty and progress->>'status'='covered' then progress:=jsonb_set(progress,'{status}','"awaiting_checkpoint"');end if;
 return automation||jsonb_build_object('progress',coalesce(progress,jsonb_build_object('requested_round',0,
   'requested_frontier',0,'active_round',0,'source_frontier',0,'covered_round',0,'covered_frontier',0,'skipped_round',0,'status','idle'))
   ||jsonb_build_object('pending_source_changes',dirty));
end $$;

CREATE FUNCTION public.read_lifetime_profile_page(p_lane_id uuid, p_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
#variable_conflict use_column
declare snap public.user_lifetime_lane_snapshot%rowtype; job public.user_lifetime_profile_progress%rowtype;
 authority public.user_lifetime_profile_authority%rowtype; source public.user_narrator_source%rowtype;
 page jsonb; profile jsonb; facts jsonb; targets jsonb; mode text; core integer; lo integer; hi integer; due bigint; frontier bigint;
 chosen boolean:=false;
begin
 if not exists(select 1 from public.lifetime_two_lane_rollout where singleton and enabled) then return null;end if;
 snap:=public.lock_lifetime_memoir_lane(p_lane_id,p_token);
 if not exists(select 1 from public.user_memoir_lane where id=p_lane_id and skill='timeline') then return null;end if;
 page:=public.read_lifetime_memoir_lane_page_before_background_profile(p_lane_id,p_token);
 if snap.source_decision is not null then
   chosen:=snap.source_decision->'skills' ? 'memoir-memory-context'
     and snap.source_decision->'source'=jsonb_build_object('id',page->'source'->'id','version',page->'source'->'version',
       'char_start',page->'source'->'char_start','char_end',page->'source'->'char_end');
   if not coalesce(chosen,false) or exists(select 1 from public.user_lifetime_profile_coverage c
       where c.user_id=snap.user_id and c.project_id=snap.project_id and c.source_id=(page->'source'->>'id')::uuid
         and c.source_version=(page->'source'->>'version')::bigint and c.next_offset>=(page->'source'->>'char_end')::integer) then return null;end if;
 end if;
 perform 1 from public.user_agent_turn_lease where user_id=snap.user_id for share;
 if exists(select 1 from public.user_agent_turn_lease where user_id=snap.user_id and expires_at>clock_timestamp()) then return null;end if;
 perform public.ensure_lifetime_profile_authority(snap.user_id);
 select * into authority from public.user_lifetime_profile_authority where user_id=snap.user_id;
 -- Older sessions coalesce to their newest milestone; no historical job replay.
 select public.lifetime_profile_due_round(coalesce(max(ordinal),0)) into due from public.user_completed_round
 where user_id=snap.user_id and project_id=snap.project_id;
 select coalesce(max(pos.sequence),0) into frontier from public.user_completed_round r
 join public.user_narrator_source s on s.user_id=r.user_id and s.project_id=r.project_id and s.client_turn_id=r.turn_id
 join public.user_lifetime_source_position pos on pos.user_id=s.user_id and pos.project_id=s.project_id and pos.source_id=s.id
 where r.user_id=snap.user_id and r.project_id=snap.project_id and r.ordinal<=due;
 if chosen then due:=greatest(snap.round_high_water,1);frontier:=(page->'source'->>'sequence')::bigint;end if;
 insert into public.user_lifetime_profile_progress(user_id,project_id,requested_round,requested_frontier)
 values(snap.user_id,snap.project_id,due,frontier) on conflict(user_id,project_id) do update set
   requested_round=excluded.requested_round,requested_frontier=excluded.requested_frontier
   where excluded.requested_round>user_lifetime_profile_progress.requested_round;
 select * into job from public.user_lifetime_profile_progress where user_id=snap.user_id and project_id=snap.project_id for update;
 if chosen then
   update public.user_lifetime_profile_progress set active_round=due,source_frontier=frontier
     where user_id=snap.user_id and project_id=snap.project_id returning * into job;
 end if;
 if not chosen and job.active_round=0 and job.requested_round<=greatest(job.covered_round,job.skipped_round) then return null;end if;
 if job.active_round=0 then
   update public.user_lifetime_profile_progress set active_round=requested_round,source_frontier=requested_frontier
   where user_id=snap.user_id and project_id=snap.project_id returning * into job;
 end if;
 select p.profile into profile from public.user_profile p where p.user_id=snap.user_id;
 select coalesce(jsonb_agg(f),'[]') into targets
 from unnest(array['name','birth_year','birth_date_expression','birth_place','childhood_place','avatar_style']) f
 where not(authority.field_locks ? f);
 -- Reference includes protected values, without leaking unrelated application state.
 select coalesce(jsonb_object_agg(f,jsonb_build_object('value',case when length(profile->>f)<=160
   and jsonb_typeof(profile->f) in ('string','number','null') then profile->f else null end,'authority',coalesce(authority.field_locks->>f,
   case when f='name' then (select n.authority from public.user_lifetime_chosen_name n where n.user_id=snap.user_id) end,'automatic'))),'{}')
 into facts from unnest(array['name','birth_year','birth_date_expression','birth_place','childhood_place','avatar_style']) f;
 mode:='extract';
 if not authority.auto_enabled or authority.manual_complete or jsonb_array_length(targets)=0 then mode:='skip';end if;
 select s.* into source from public.user_narrator_source s left join public.user_lifetime_profile_coverage c
 on c.user_id=s.user_id and c.project_id=s.project_id and c.source_id=s.id and c.source_version=s.version
 where s.user_id=snap.user_id and s.project_id=snap.project_id and s.status='active' and s.sequence<=job.source_frontier
   and (not chosen or s.id=(page->'source'->>'id')::uuid)
   and coalesce(c.next_offset,0)<length(s.text) order by s.sequence limit 1;
 if source.id is null and mode<>'skip' then mode:='reply_only';end if;
 if source.id is not null then
   select coalesce((select next_offset from public.user_lifetime_profile_coverage where user_id=snap.user_id
     and project_id=snap.project_id and source_id=source.id and source_version=source.version),0) into core;
   hi:=least(core+2048,length(source.text));
   lo:=greatest(core-256,0);
   if chosen then lo:=(page->'source'->>'char_start')::integer;hi:=(page->'source'->>'char_end')::integer;end if;
 end if;
 -- Read the base without recursively calling the profile-aware wrapper below.
 page:=public.read_lifetime_memoir_lane_page_before_background_profile(p_lane_id,p_token);
 page:=(page-array['input_digest','page_digest','memory_summary','batch'])||jsonb_build_object('complete',false,
   'two_lane',null,'base_revision',coalesce((page->>'base_revision')::bigint,0),
   'events','[]'::jsonb,'partition',null,'source',case when source.id is null or mode='skip' then null else
     jsonb_build_object('id',source.id,'project_id',source.project_id,'version',source.version,'sequence',source.sequence,
       'text',substring(source.text from lo+1 for hi-lo),'char_start',lo,'char_end',hi,'original_length',length(source.text),
       'kind',source.kind,'language',source.language,'status',source.status,'author_role','storyteller') end,
   'profile_context',jsonb_build_object('schema_version',1,'revision',authority.revision,'target_round',job.active_round,
     'covered_round',job.covered_round,'source_frontier',job.source_frontier,'targets',targets,'reference',facts,'work_mode',mode,
     'execution_generation',(select execution_generation from public.user_lifetime_conversation where user_id=snap.user_id
       and conversation_id=snap.conversation_id),'phase_revision',0,
     'cursor',jsonb_build_object('source_id',source.id,'version',source.version,
         'char_start',core,'char_end',hi)));
 page:=page||jsonb_build_object('input_digest',encode(sha256(convert_to((page-'token')::text,'UTF8')),'hex'));
 return page||jsonb_build_object('page_digest',encode(sha256(convert_to(page::text,'UTF8')),'hex'));
end $$;

CREATE FUNCTION public.read_lifetime_project_identity(p_project_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is null then raise exception 'authenticated owner required' using errcode='42501'; end if;
  return (select jsonb_build_object('schema_version',1,'owner_id',user_id,
    'conversation_id',conversation_id,'product',product,'project_id',project_id)
    from public.user_lifetime_conversation where user_id=auth.uid() and (p_project_id is null or project_id=p_project_id) and product='memoir');
end $$;

CREATE FUNCTION public.read_lifetime_history_reply(p_conversation_id uuid, p_client_turn_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare owner uuid:=auth.uid(); identity public.user_lifetime_conversation%rowtype;
 saved public.user_lifetime_reply%rowtype; source public.user_narrator_source%rowtype;
 interview public.user_interview_turn%rowtype; epoch bigint; pins jsonb; privacy_hash text; valid boolean;
begin
 select * into identity from public.user_lifetime_conversation where user_id=owner and conversation_id=p_conversation_id;
 if not found then raise exception 'conversation unavailable'; end if;
 select policy_epoch into epoch from public.user_memoir_project where user_id=owner and project_id=identity.project_id for share;
 pins:=public.read_lifetime_pinned(p_conversation_id);
 select * into identity from public.user_lifetime_conversation where user_id=owner and conversation_id=p_conversation_id;
 select * into saved from public.user_lifetime_reply where user_id=owner and conversation_id=p_conversation_id and client_turn_id=p_client_turn_id;
 if not found then return null; end if;
 select * into interview from public.user_interview_turn where user_id=owner and project_id=identity.project_id and client_turn_id=p_client_turn_id;
 select * into source from public.user_narrator_source where user_id=owner and project_id=identity.project_id and id=interview.source_id;
 privacy_hash:=encode(sha256(convert_to(jsonb_build_object('excluded_topics',pins->'excluded_topics','paused_topics',pins->'paused_topics',
   'privacy_complete',pins->'privacy_complete')::text,'UTF8')),'hex');
 -- Profile enrichment changes execution context, not the saved conversation.
 valid:=source.status='active' and source.version=interview.source_version
   and saved.policy_epoch=epoch and saved.execution_generation=identity.execution_generation
   and pins->'privacy_complete'='true'::jsonb
   and (saved.preference_revision=identity.preference_revision or interview.collector->>'history_privacy_digest'=privacy_hash
     or (not (interview.collector ? 'history_privacy_digest') and pins->'excluded_topics'='[]'::jsonb and pins->'paused_topics'='[]'::jsonb));
 return jsonb_build_object('reply',case when valid then interview.collector->>'reply' else null end);
end $$;

CREATE FUNCTION public.read_lifetime_reply(p_conversation_id uuid, p_client_turn_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare owner uuid:=auth.uid(); identity public.user_lifetime_conversation%rowtype; saved public.user_lifetime_reply%rowtype;
 epoch bigint; source public.user_narrator_source%rowtype; interview jsonb; valid boolean;
begin
 select * into identity from public.user_lifetime_conversation where user_id=owner and conversation_id=p_conversation_id;
 if not found then raise exception 'conversation unavailable'; end if;
 select policy_epoch into epoch from public.user_memoir_project where user_id=owner and project_id=identity.project_id for share;
 select * into saved from public.user_lifetime_reply where user_id=owner and conversation_id=p_conversation_id and client_turn_id=p_client_turn_id;
 if not found then return null; end if;
 select * into source from public.user_narrator_source where user_id=owner and project_id=identity.project_id and client_turn_id=p_client_turn_id;
 interview:=public.read_user_interview_turn(identity.project_id,p_client_turn_id);
 valid:=source.status='active' and saved.policy_epoch=epoch and saved.execution_generation=identity.execution_generation
   and saved.preference_revision=identity.preference_revision;
 return jsonb_build_object('conversation_saved',true,'accepted_source_id',source.id,'project_id',identity.project_id,
   'client_turn_id',p_client_turn_id,'reply',case when valid then interview->>'reply' else null end,
   'context_rebuild_required',not coalesce(valid,false));
end $$;

CREATE FUNCTION public.read_lifetime_skill_progress(p_project_id text, p_cursor text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare records jsonb; queued jsonb; cursor jsonb; next_cursor text; more boolean;
begin
 perform 1 from public.user_memoir_project where user_id=auth.uid() and project_id=p_project_id for share;
 if not found then raise exception 'owned project required' using errcode='42501';end if;
 if p_cursor is not null then
   begin cursor:=convert_from(decode(p_cursor,'base64'),'UTF8')::jsonb;
   exception when others then raise exception 'invalid progress cursor' using errcode='22023';end;
   if cursor->>'owner' is distinct from auth.uid()::text or cursor->>'project' is distinct from p_project_id then
     raise exception 'progress cursor scope changed' using errcode='42501';end if;
 end if;
 select coalesce(jsonb_agg(to_jsonb(w)-array['user_id','lane_id','snapshot_id','page_digest','invocation_id','lease_token']||'{"lane":"B"}'::jsonb
   ||case when w.status in ('running','completed') and ((w.lane_id is null and w.status='running' and w.updated_at<clock_timestamp()-interval '5 minutes')
     or (w.lane_id is not null and not exists(select 1 from public.user_memoir_lane l
     where l.id=w.lane_id and l.token=w.lease_token and l.lease_until>clock_timestamp() and l.run_deadline>clock_timestamp()
       and exists(select 1 from public.user_lifetime_lane_snapshot s where s.id=w.snapshot_id and s.state='pending'))))
     then '{"status":"failed","reason":"interrupted"}'::jsonb else '{}'::jsonb end
   order by w.updated_at,w.id),'[]') into records from (select * from public.user_background_skill_work
   where user_id=auth.uid() and project_id=p_project_id
     and (p_cursor is null or (updated_at,id)<((cursor->>'at')::timestamptz,cursor->>'id'))
   order by updated_at desc,id desc limit 32) w;
 select exists(select 1 from public.user_background_skill_work
   where user_id=auth.uid() and project_id=p_project_id
     and (p_cursor is null or (updated_at,id)<((cursor->>'at')::timestamptz,cursor->>'id')) offset 32 limit 1) into more;
 if more then
   next_cursor:=encode(convert_to(jsonb_build_object('owner',auth.uid(),'project',p_project_id,
     'at',records->0->>'updated_at','id',records->0->>'id')::text,'UTF8'),'base64');
 end if;
 -- A real pending lane is queued, not proof that any phase/model has run.
 select coalesce(jsonb_agg(jsonb_build_object('id','queue:'||id||':'||target_source,'skill',case when skill='composer' then 'memoir-composer' when skill='guidance' then 'memoir-interview-guidance' else 'memoir-author-timeline' end,
   'lane','B','phase','queue','execution','model','status','queued','model_invoked',false,
   'coverage_start',successful_source+1,'coverage_end',target_source,'project_id',project_id,
   'client_turn_id',(select s.client_turn_id from public.user_narrator_source s where s.user_id=auth.uid() and s.project_id=p_project_id
     and s.sequence=l.target_source and s.status='active'))),'[]') into queued
 from public.user_memoir_lane l where p_cursor is null and user_id=auth.uid() and project_id=p_project_id and pending
   and attempts<3 and (token is null or lease_until<=clock_timestamp() or run_deadline<=clock_timestamp());
 return jsonb_build_object('project_id',p_project_id,'items',queued||records,'recent_limit',32,
   'continuation',p_cursor is not null,'truncated',more,'next_cursor',next_cursor,
   'pending',exists(select 1 from public.user_memoir_lane where user_id=auth.uid() and project_id=p_project_id
     and attempts<3 and (pending or (token is not null and lease_until>clock_timestamp() and run_deadline>clock_timestamp()))));
end $$;

CREATE FUNCTION public.read_lifetime_source_attribution(p_project_id text, p_source_id uuid, p_after uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 8) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner uuid:=auth.uid(); project public.user_memoir_project%rowtype; source public.user_narrator_source%rowtype;
 identity public.user_lifetime_conversation%rowtype; cursor_row public.user_lifetime_read_cursor%rowtype;
 records jsonb; last_key text:=''; cursor_id uuid; more boolean; attempted boolean; resolved boolean;
begin
 if owner is null or p_limit is null or p_limit not between 1 and 8 then raise exception 'invalid attribution page' using errcode='22023';end if;
 select * into project from public.user_memoir_project where user_id=owner and project_id=p_project_id for share;
 select * into identity from public.user_lifetime_conversation where user_id=owner and project_id=p_project_id;
 if not found then raise exception 'owned conversation required' using errcode='42501';end if;
 select * into source from public.user_narrator_source where user_id=owner and project_id=p_project_id and id=p_source_id and status='active';
 if not found then raise exception 'current owned source required' using errcode='42501';end if;
 if p_after is not null then
   select * into cursor_row from public.user_lifetime_read_cursor where id=p_after and user_id=owner
     and project_id=p_project_id and kind='attribution' and source_id=p_source_id;
   if not found then raise exception 'attribution cursor scope mismatch' using errcode='22023';end if;
   if cursor_row.source_revision<>project.source_sequence or cursor_row.event_revision<>project.event_sequence
     or cursor_row.policy_epoch<>project.policy_epoch or cursor_row.attribution_revision<>project.attribution_revision
     or cursor_row.preference_revision<>identity.preference_revision then raise exception 'attribution page changed' using errcode='40001';end if;
   last_key:=cursor_row.after_key;
 end if;
 select coalesce(jsonb_agg(item order by key),'[]') into records from (
   select lpad(a.char_start::text,8,'0')||':'||coalesce(a.event_id,'') key,
     jsonb_build_object('key',lpad(a.char_start::text,8,'0')||':'||coalesce(a.event_id,''),
       'char_start',a.char_start,'char_end',a.char_end,'disposition',a.disposition,'reason',a.reason,
       'context_event',case when a.disposition in ('unresolved','non_story') then public.lifetime_source_context(owner,p_project_id,p_source_id) else null end,
       'event',public.lifetime_attribution_event_context(owner,p_project_id,e.id)) item
   from public.lifetime_source_attribution_rows(owner,p_project_id,p_source_id) a
   left join public.user_memory_event e on e.user_id=owner and e.project_id=p_project_id and e.id=a.event_id
   where lpad(a.char_start::text,8,'0')||':'||coalesce(a.event_id,'')>last_key
   order by key limit p_limit+1) bounded;
 more:=jsonb_array_length(records)>p_limit;
 if more then
   records:=records-p_limit;
   insert into public.user_lifetime_read_cursor(user_id,project_id,conversation_id,kind,source_id,policy_epoch,
     preference_revision,source_revision,event_revision,attribution_revision,after_key)
   values(owner,p_project_id,identity.conversation_id,'attribution',p_source_id,project.policy_epoch,
     identity.preference_revision,project.source_sequence,project.event_sequence,project.attribution_revision,records->-1->>'key') returning id into cursor_id;
 end if;
 select bool_and(disposition<>'pending'),bool_and(disposition in ('linked','non_story')) into attempted,resolved
   from public.lifetime_source_attribution_rows(owner,p_project_id,p_source_id);
 return jsonb_build_object('source_id',source.id,'source_version',source.version,'policy_epoch',project.policy_epoch,
   'attribution_revision',project.attribution_revision,'complete',coalesce(attempted,false),'resolved',coalesce(resolved,false),
   'items',records,'next_cursor',cursor_id,'page_complete',not more);
end $$;

CREATE FUNCTION public.read_lifetime_source_page(p_conversation_id uuid, p_policy_epoch bigint, p_cursor uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 32, p_query text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare owner uuid:=auth.uid(); project text; epoch bigint; high_water bigint; last_sequence bigint:=0;
  last_offset integer:=-1; cursor_row public.user_lifetime_source_cursor%rowtype;
  records jsonb; has_more boolean; next_cursor uuid; last_row jsonb;
begin
  if owner is null then raise exception 'authenticated owner required'; end if;
  if p_limit is null or p_limit not between 1 and 32 or p_query is null or length(p_query)>128 then raise exception 'invalid page bounds'; end if;
  select project_id into project from public.user_lifetime_conversation where user_id=owner and conversation_id=p_conversation_id;
  if not found then raise exception 'conversation unavailable'; end if;
  select policy_epoch,source_sequence into epoch,high_water from public.user_memoir_project
    where user_id=owner and project_id=project for share;
  if epoch is distinct from p_policy_epoch then raise exception 'stale source policy' using errcode='PT409'; end if;
  if high_water>0 and not exists(select 1 from public.user_lifetime_source_inventory where user_id=owner and project_id=project
    and record_count=high_water and max_sequence=high_water) then
    raise exception 'LIFETIME_INVENTORY_REQUIRED: historical source positions are incomplete' using errcode='PT409';
  end if;
  if p_cursor is not null then
    select * into cursor_row from public.user_lifetime_source_cursor where id=p_cursor
      and user_id=owner and conversation_id=p_conversation_id and policy_epoch=epoch
      and query=p_query and expires_at>clock_timestamp();
    if not found then raise exception 'invalid or stale source cursor'; end if;
    high_water:=cursor_row.high_water;last_sequence:=cursor_row.last_sequence;last_offset:=cursor_row.last_offset;
  end if;
  select coalesce(jsonb_agg(r.data order by r.sequence,r.chunk_start),'[]') into records from (
    select s.sequence,chunk_start,jsonb_build_object('source_id',s.id,'version',s.version,'sequence',s.sequence,
      'char_start',chunk_start,'char_end',case when s.status='active' then least(chunk_start+2048,length(s.text)) else 0 end,
      'text',case when s.status='active' then substring(s.text from chunk_start+1 for 2048) else null end,
      'kind',s.kind,'language',s.language,'status',s.status) as data
    from (select pos.user_id,pos.project_id,pos.sequence,pos.source_id as id,pos.version,src.kind,src.language,
        case when src.id is null then 'withdrawn' when src.version<>pos.version then 'superseded' else src.status end as status,
        case when src.version=pos.version and src.status='active' then src.text else null end as text
      from public.user_lifetime_source_position pos left join public.user_narrator_source src
        on src.user_id=pos.user_id and src.project_id=pos.project_id and src.id=pos.source_id) s
    cross join lateral generate_series(case when p_query<>'' then greatest(position(lower(p_query) in lower(s.text))-257,0) else 0 end,
      case when p_query<>'' then greatest(position(lower(p_query) in lower(s.text))-257,0)
        when s.status='active' then greatest(length(s.text)-1,0) else 0 end,2048) chunk_start
    where s.user_id=owner and s.project_id=project and s.sequence<=high_water
      and (s.sequence>last_sequence or (s.sequence=last_sequence and chunk_start>last_offset))
      and (p_query='' or (s.status='active' and position(lower(p_query) in lower(s.text))>0))
    order by s.sequence,chunk_start limit p_limit+1) r;
  has_more:=jsonb_array_length(records)>p_limit;
  if has_more then
    records:=records-p_limit;last_row:=records->-1;
    insert into public.user_lifetime_source_cursor(user_id,conversation_id,policy_epoch,high_water,last_sequence,last_offset,query)
      values(owner,p_conversation_id,epoch,high_water,(last_row->>'sequence')::bigint,(last_row->>'char_start')::integer,p_query)
      on conflict on constraint lifetime_cursor_scope
      do update set expires_at=greatest(public.user_lifetime_source_cursor.expires_at,excluded.expires_at)
      returning id into next_cursor;
  end if;
  return jsonb_build_object('schema_version',1,'owner_id',owner,'conversation_id',p_conversation_id,
    'policy_epoch',epoch,'source_revision',high_water,'records',records,'complete',not has_more,'next_cursor',next_cursor);
end $$;

CREATE FUNCTION public.read_lifetime_stage_readiness(p_project_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb;
begin
 if auth.uid() is null or not (
   exists(select 1 from public.user_memoir_project where user_id=auth.uid() and project_id=p_project_id)
   or exists(select 1 from public.user_memory where user_id=auth.uid() and project_id=p_project_id)
   or exists(select 1 from public.user_conversation_attachment where user_id=auth.uid() and project_id=p_project_id))
   then raise exception 'owned conversation unavailable' using errcode='42501';end if;
 with transferred_memories as materialized (
   select m.id from public.user_shared_memoir_transfer t
   join public.user_conversation_attachment a on a.id=t.conversation_id and a.user_id=t.user_id and a.project_id=t.project_id
   cross join lateral jsonb_each_text(a.workspace->'memory_id_map') imported
   join public.user_memory m on m.id::text=imported.value and m.user_id=t.user_id and m.project_id=t.project_id
   where t.user_id=auth.uid() and t.project_id=p_project_id
     and public.lifetime_narrator_word_equivalents(m.kind,m.content)>0
 ), saved_sources as materialized (
   select n.* from public.user_narrator_source n
   where n.user_id=auth.uid() and n.project_id=p_project_id and n.status='active'
     and exists(select 1 from public.user_memory m
       where m.user_id=n.user_id and m.project_id=n.project_id and m.client_turn_id=n.client_turn_id
         and (exists(select 1 from public.user_lifetime_reply r where r.user_id=m.user_id and r.memory_id=m.id)
           or exists(select 1 from transferred_memories t where t.id=m.id)))
 ), spans as (
   select n.id,n.text,e.life_stage,s.evidence->>'quote' quote,
     coalesce((s.evidence->>'char_start')::integer,strpos(n.text,s.evidence->>'quote')-1) lo,
     coalesce((s.evidence->>'char_end')::integer,
       coalesce((s.evidence->>'char_start')::integer,strpos(n.text,s.evidence->>'quote')-1)+length(s.evidence->>'quote')) hi,
     s.evidence ? 'char_start' explicit_span
   from saved_sources n join public.user_memory_event_source s
     on s.user_id=n.user_id and s.project_id=n.project_id and s.source_id=n.id and s.source_version=n.version
   join public.user_memory_event e on e.user_id=s.user_id and e.project_id=s.project_id and e.id=s.event_id
   where e.status='active' and e.life_stage<>'unplaced'
     and s.stage_progress_role in ('primary','stage','legacy_primary','legacy_stage')
     and not exists(select 1 from public.user_memory_event_source_exclusion x
       where x.user_id=s.user_id and x.project_id=s.project_id and x.event_id=s.event_id and x.source_id=s.source_id)
 ), merged as (
   select id,life_stage,range_agg(int4range(lo,hi)) ranges from spans
   where lo>=0 and hi>lo and hi<=length(text) and substring(text from lo+1 for hi-lo)=quote
     and (explicit_span or strpos(substring(text from lo+2),quote)=0)
   group by id,life_stage
 ), volumes as (
   select m.life_stage,sum(public.lifetime_narrator_word_equivalents('agent',
     'Storyteller: '||substring(n.text from lower(piece)+1 for upper(piece)-lower(piece))||E'\nMemory Spark: saved')) words
   from merged m join saved_sources n on n.id=m.id cross join lateral unnest(m.ranges) piece group by m.life_stage
   union all
   select v.life_stage,sum(v.word_equivalents) from public.user_lifetime_stage_volume v
   where v.user_id=auth.uid() and v.project_id=p_project_id
     and not exists(select 1 from public.user_lifetime_reply r where r.user_id=v.user_id and r.memory_id=v.memory_id)
     and not exists(select 1 from saved_sources n join spans s on s.id=n.id where n.client_turn_id=v.client_turn_id)
     and not exists(select 1 from public.user_narrator_source n where n.user_id=v.user_id and n.project_id=v.project_id
       and n.client_turn_id=v.client_turn_id and n.status='withdrawn') group by v.life_stage
 ), counts as (
   select stage,coalesce(sum(v.words),0) words
   from unnest(array['baby','childhood','adolescence','young_adulthood','midlife','later_life']) stage
   left join volumes v on v.life_stage=stage group by stage
 )
 select jsonb_build_object('stages',jsonb_object_agg(stage,jsonb_build_object('word_equivalents',words,
   'percent',round(least(case when words<=300 then words::numeric/10 else 30+least(words-300,700)::numeric*20/700 end,50),1),
   'color',case when words<300 then 'red' when words<1000 then 'amber' else 'green' end)),
   'pending',exists(select 1 from saved_sources where processing_status<>'succeeded')) into result from counts;
 return result || jsonb_build_object('project_id',p_project_id,'heuristic','narrator_context_volume_v1',
   'maximum_percent',50,'complete',true);
end $$;

CREATE FUNCTION public.read_lifetime_strategy_context(p_conversation_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
 select public.read_lifetime_strategy_context_at(p_conversation_id,null);
$$;

CREATE FUNCTION public.read_lifetime_strategy_context_at(p_conversation_id uuid, p_plan_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare pins jsonb; identity public.user_lifetime_conversation%rowtype; planned public.user_lifetime_interview_strategy%rowtype;
 rollout text; data jsonb; candidates jsonb; hint text; delivery jsonb;
begin
 pins:=public.read_lifetime_pinned(p_conversation_id);
 select * into identity from public.user_lifetime_conversation where user_id=auth.uid() and conversation_id=p_conversation_id;
 rollout:=public.lifetime_interview_strategy_rollout(auth.uid());
 if rollout<>'active' then return jsonb_build_object('mode',rollout,'plan',null);end if;
 select jsonb_build_object('prior_delivered_question',o.question_delivered,'prior_delivered_sequence',o.source_sequence) into delivery
   from public.user_lifetime_strategy_outcome o join public.user_interview_turn t
     on t.user_id=o.user_id and t.project_id=o.project_id and t.client_turn_id=o.client_turn_id
   join public.user_narrator_source s on s.user_id=t.user_id and s.project_id=t.project_id and s.id=t.source_id
     and s.version=t.source_version and s.status='active'
   join public.user_lifetime_reply r on r.user_id=o.user_id and r.conversation_id=p_conversation_id and r.client_turn_id=o.client_turn_id
   where o.user_id=auth.uid() and o.project_id=identity.project_id and o.delivered and o.question_delivered is not null
     and r.policy_epoch=(select p.policy_epoch from public.user_memoir_project p where p.user_id=auth.uid() and p.project_id=identity.project_id) and r.execution_generation=identity.execution_generation
     and r.preference_revision=identity.preference_revision order by o.source_sequence desc limit 1;
 delivery:=coalesce(delivery,jsonb_build_object('prior_delivered_question',null,'prior_delivered_sequence',null));
 select active_strategy into hint from public.user_lifetime_strategy_frontier where user_id=auth.uid() and project_id=identity.project_id;
 select * into planned from public.user_lifetime_interview_strategy where user_id=auth.uid() and project_id=identity.project_id and not shadow
   and (p_plan_revision is null or plan_revision=p_plan_revision) order by plan_revision desc limit 1;
 data:=planned.data-'guidance';
 if planned.plan_revision is null or not exists(select 1 from public.user_memoir_project p join public.user_narrator_source s
   on s.user_id=p.user_id and s.project_id=p.project_id and s.id=planned.source_id and s.version=planned.source_version and s.status='active'
   where p.user_id=auth.uid() and p.project_id=identity.project_id and p.policy_epoch=planned.policy_epoch
     and planned.preference_revision=identity.preference_revision and planned.execution_generation=identity.execution_generation
     and planned.based_on_sequence between p.source_sequence-3 and p.source_sequence)
   or exists(select 1 from jsonb_array_elements(planned.event_manifest) e where not exists(select 1 from public.user_memory_event m
     where m.user_id=auth.uid() and m.project_id=identity.project_id and m.id=e->>'id' and m.revision::text=e->>'revision' and m.status='active')) then
   return jsonb_build_object('mode',rollout,'plan',null,'planned_strategy_hint',hint,'invalid_plan_revision',planned.plan_revision)||delivery;
 end if;
 with consumed as materialized (select * from public.lifetime_consumed_question_ids(auth.uid(),identity.project_id))
 select coalesce(jsonb_agg(q order by hint_position),'[]') into candidates
 from jsonb_array_elements(data->'candidates') with ordinality hints(q,hint_position)
   where public.lifetime_guidance_question_current(auth.uid(),identity.project_id,q)
     and not exists(select 1 from consumed
     where consumed.question_id=q->>'id');
 data:=jsonb_set(data,'{candidates}',candidates);
 return jsonb_build_object('mode',rollout,'plan',data,'planned_strategy_hint',hint)||delivery;
end $$;

CREATE FUNCTION public.read_lifetime_tail(p_conversation_id uuid, p_policy_epoch bigint, p_after_sequence bigint, p_through_sequence bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare owner uuid:=auth.uid(); project text; epoch bigint; high_water bigint; row record;
 records jsonb:='[]'; tombstones jsonb:='[]'; item jsonb; reply_row record; bytes integer:=0; seen bigint:=0; complete boolean:=true;
begin
 select project_id into project from public.user_lifetime_conversation where user_id=owner and conversation_id=p_conversation_id;
 if not found then raise exception 'conversation unavailable'; end if;
 select policy_epoch,source_sequence into epoch,high_water from public.user_memoir_project where user_id=owner and project_id=project for share;
 if p_policy_epoch is distinct from epoch then raise exception 'stale tail epoch'; end if;
 if p_after_sequence<0 or p_through_sequence<p_after_sequence or p_through_sequence>high_water then raise exception 'invalid tail range'; end if;
 for row in select p.sequence as position_sequence,p.version as position_version,s as source from public.user_lifetime_source_position p
 join public.user_narrator_source s on s.user_id=p.user_id and s.project_id=p.project_id and s.id=p.source_id
 where p.user_id=owner and p.project_id=project and p.sequence>p_after_sequence and p.sequence<=p_through_sequence
 order by p.sequence limit 17 loop
   seen:=seen+1;
   if seen>16 or bytes+octet_length((row.source).text)>32768 then complete:=false;exit;end if;
   if (row.source).status<>'active' or row.position_version<>(row.source).version then
     tombstones:=tombstones||to_jsonb(row.position_sequence);
   else
     item:=public.narrator_source_record(row.source);
     select r.policy_epoch,r.preference_revision,r.execution_generation,t.collector->>'reply' as reply into reply_row
       from public.user_lifetime_reply r join public.user_interview_turn t on t.user_id=r.user_id and t.project_id=project and t.client_turn_id=r.client_turn_id
       join public.user_lifetime_conversation l on l.user_id=r.user_id and l.conversation_id=r.conversation_id
       where r.user_id=owner and r.conversation_id=p_conversation_id and r.client_turn_id=(row.source).client_turn_id
         and r.policy_epoch=epoch and r.preference_revision=l.preference_revision and r.execution_generation=l.execution_generation;
     if found then item:=item||jsonb_build_object('conversation_saved',true,'assistant_reply',reply_row.reply,'reply_policy_epoch',epoch); end if;
     bytes:=bytes+octet_length(item::text);
     if bytes>32768 then complete:=false;exit;end if;
     records:=records||jsonb_build_array(item);
   end if;
 end loop;
 complete:=complete and seen=p_through_sequence-p_after_sequence;
 return jsonb_build_object('records',records,'tombstones',tombstones,'complete',complete,
   'after_sequence',p_after_sequence,'through_sequence',p_through_sequence);
end $$;

CREATE FUNCTION public.read_lifetime_two_lane_checkpoint(p_conversation_id uuid, p_policy_epoch bigint, p_model text, p_prompt_version text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare result jsonb;
begin
 result:=public.read_lifetime_checkpoint(p_conversation_id,p_policy_epoch,p_model,p_prompt_version);
 if result is not null and not exists(select 1 from public.user_lifetime_checkpoint c where c.user_id=auth.uid()
   and c.id=(result->>'checkpoint_id')::uuid and (c.lossless or c.memory_summary is not null)) then return null;end if;
 return result;
end $$;

CREATE FUNCTION public.read_lifetime_two_lane_reply(p_conversation_id uuid, p_client_turn_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare result jsonb; reply uuid;
begin
 result:=public.read_lifetime_reply(p_conversation_id,p_client_turn_id);
 if result is null then return null;end if;
 select memory_id into reply from public.user_lifetime_reply where user_id=auth.uid()
   and conversation_id=p_conversation_id and client_turn_id=p_client_turn_id;
 return result||jsonb_build_object('reply_id',reply);
end $$;

CREATE FUNCTION public.read_lifetime_two_lane_tail(p_conversation_id uuid, p_policy_epoch bigint, p_after_sequence bigint, p_through_sequence bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare result jsonb; page jsonb; cursor_seq bigint:=p_after_sequence; hi bigint;
begin
 -- Use canonical policy/access guards for every page; only exact originals and
 -- tombstones are joined. Never silently truncate an oversized required tail.
 result:=jsonb_build_object('records','[]'::jsonb,'tombstones','[]'::jsonb,'complete',true,
   'after_sequence',p_after_sequence,'through_sequence',p_through_sequence);
 if p_through_sequence-p_after_sequence>256 then
   perform public.read_lifetime_tail(p_conversation_id,p_policy_epoch,p_after_sequence,p_after_sequence);
   return result||jsonb_build_object('complete',false);
 end if;
 loop
   hi:=least(cursor_seq+16,p_through_sequence);
   page:=public.read_lifetime_tail(p_conversation_id,p_policy_epoch,cursor_seq,hi);
   if page->'complete' is distinct from 'true'::jsonb then return result||jsonb_build_object('complete',false);end if;
   result:=jsonb_set(jsonb_set(result,'{records}',(result->'records')||(page->'records')),'{tombstones}',(result->'tombstones')||(page->'tombstones'));
   if octet_length(result::text)>32768 then return result||jsonb_build_object('complete',false);end if;
   cursor_seq:=hi;
   exit when cursor_seq>=p_through_sequence;
 end loop;
 return result;
end $$;

CREATE FUNCTION public.read_memoir_checkpoint(p_lane_id uuid, p_token uuid, p_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb; page jsonb;
begin
 result:=public.read_memoir_checkpoint_before_skills(p_lane_id,p_token,p_key);
 if result is not null and exists(select 1 from public.user_memoir_lane l join public.user_lifetime_conversation c
   on c.user_id=l.user_id and c.project_id=l.project_id where l.id=p_lane_id and l.skill='composer') then
   page:=public.read_lifetime_memoir_lane_page(p_lane_id,p_token);
   perform public.background_skill_receipt(page,'checkpoint','memoir-composer','cache','cached');
 end if;
 return result;
end $$;

CREATE FUNCTION public.read_memoir_checkpoint_before_lifetime_pages(p_lane_id uuid, p_token uuid, p_key text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select c.value from public.user_memoir_checkpoint c join public.user_memoir_lane l on l.id=c.lane_id
    join public.user_memoir_project p on p.user_id=l.user_id and p.project_id=l.project_id
    where l.id=p_lane_id and l.token=p_token and l.lease_until>clock_timestamp() and l.run_deadline>clock_timestamp()
      and l.active_policy=p.policy_epoch and c.key=p_key and c.created_at>clock_timestamp()-interval '7 days'
$$;

CREATE FUNCTION public.read_memoir_checkpoint_before_skills(p_lane_id uuid, p_token uuid, p_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare page jsonb;
begin
 if not exists(select 1 from public.user_memoir_lane l join public.user_lifetime_conversation c
   on c.user_id=l.user_id and c.project_id=l.project_id where l.id=p_lane_id) then
   return public.read_memoir_checkpoint_before_lifetime_pages(p_lane_id,p_token,p_key);
 end if;
 page:=public.read_lifetime_memoir_lane_page(p_lane_id,p_token);
 return (select value from public.user_memoir_checkpoint where lane_id=p_lane_id and key=p_key
   and lifetime_snapshot_id=(page->>'snapshot_id')::uuid and lifetime_page=(page->>'page_number')::bigint
   and lifetime_policy=(page->>'policy_epoch')::bigint and lifetime_preference=(page->>'preference_revision')::bigint
   and lifetime_input_digest=(page->>'input_digest')
   and created_at>clock_timestamp()-interval '7 days');
end $$;

CREATE FUNCTION public.read_memoir_lane_state(p_lane_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select public.memoir_lane_progress(l) from public.user_memoir_lane l where id=p_lane_id
$$;

CREATE FUNCTION public.read_memoir_receipt_scope(p_receipt_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select pg_catalog.jsonb_build_object('user_id',r.user_id,'project_id',r.project_id,'change_kind',r.change_kind)
   || case when c.conversation_id is null then '{}'::jsonb else
      pg_catalog.jsonb_build_object('conversation_id',c.conversation_id) end
 from public.user_private_draft_outbox r left join public.user_lifetime_conversation c
   on c.user_id=r.user_id and c.project_id=r.project_id where r.id=p_receipt_id and not r.delivered
$$;

CREATE FUNCTION public.read_story_game_eligibility(p_project_id text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare result jsonb; reasons jsonb; mode jsonb;
begin
 result:=public.read_story_game_eligibility_before_skills(p_project_id);
 reasons:=(result->'reasons')-'runtime_unavailable';
 mode:=public.read_lifetime_current_mode(p_project_id);
 if mode is null then reasons:=reasons||'"current_decision_required"'::jsonb;
 elsif mode->>'mode'<>'shape' then reasons:=reasons||'"shape_required"'::jsonb;end if;
 return result||jsonb_build_object('reasons',reasons,'available',jsonb_array_length(reasons)=0,
   'authority_eligible',jsonb_array_length(reasons)=0);
end $$;

CREATE FUNCTION public.read_story_game_eligibility_before_skills(p_project_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner uuid:=auth.uid(); edition public.user_formal_memoir_edition%rowtype; head public.user_formal_memoir_head%rowtype;
 reasons jsonb:='[]'; context jsonb; authority boolean; code text;
begin
 if owner is null or not exists(select 1 from public.user_lifetime_conversation where user_id=owner and project_id=p_project_id) then
   raise exception 'FORMAL_OWNER_REQUIRED' using errcode='42501';end if;
 perform 1 from public.user_memoir_project where user_id=owner and project_id=p_project_id for update;
 select * into head from public.user_formal_memoir_head where user_id=owner and project_id=p_project_id;
 select * into edition from public.user_formal_memoir_edition where id=head.edition_id;
 begin
   context:=public.lock_formal_memoir_context(owner,p_project_id);
   if edition.id is null then reasons:=reasons||'"completion_required"'::jsonb;
   elsif not edition.active then reasons:=reasons||'"completion_stale"'::jsonb;
   else perform public.lock_formal_memoir_run(edition.run_id,null,false);
   end if;
 exception when sqlstate '40001' or sqlstate 'PT409' or sqlstate '55000' then
   code:=case SQLERRM when 'FORMAL_SHAPE_REQUIRED' then 'shape_required'
     when 'FORMAL_PRIVACY_REVIEW_REQUIRED' then 'privacy_review_required'
     when 'LIFETIME_POLICY_PENDING' then 'policy_pending' else 'completion_stale' end;
   reasons:=reasons||to_jsonb(code);
 end;
 if not exists(select 1 from public.user_story_game_consent c where c.edition_id=edition.id and c.user_id=owner
   and c.project_id=p_project_id and c.status='active' and c.revision=head.consent_revision
   and c.policy_epoch=(select policy_epoch from public.user_memoir_project where user_id=owner and project_id=p_project_id)) then
   reasons:=reasons||'"adaptation_consent_required"'::jsonb;
 end if;
 authority:=jsonb_array_length(reasons)=0;
 -- Persisted authority is not executable availability. Model binding, grounding
 -- review, game jobs and guarded private browser delivery remain unimplemented.
 return jsonb_build_object('schema_version',1,'authority_eligible',authority,'available',false,
   'reasons',reasons||'"runtime_unavailable"'::jsonb,'edition_id',edition.id,'revision',edition.revision,
   'manuscript_digest',edition.digest,'consent_revision',coalesce(head.consent_revision,0));
end $$;

CREATE FUNCTION public.read_ui_locale_preference(p_expected_viewer uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_owner uuid := auth.uid();
  v_preference public.user_ui_locale_preference%rowtype;
  v_legacy text;
begin
  if v_owner is null or p_expected_viewer is null or v_owner <> p_expected_viewer then
    raise exception 'authenticated user required' using errcode = '42501';
  end if;
  select u.raw_user_meta_data->>'ui_locale' into v_legacy
    from auth.users u where u.id = v_owner;
  if not found then
    raise exception 'authenticated user required' using errcode = '42501';
  end if;
  select * into v_preference from public.user_ui_locale_preference
    where user_id = v_owner;
  if found then
    return jsonb_build_object('locale', v_preference.locale,
      'source', v_preference.source, 'revision', v_preference.revision);
  end if;
  -- Source-less legacy preferences are established choices. An inference must
  -- never silently replace one. Revision 0 denotes this read-only fallback.
  if v_legacy in ('en-AU', 'zh-CN') then
    return jsonb_build_object('locale', v_legacy, 'source', 'manual', 'revision', 0);
  end if;
  return 'null'::jsonb;
end;
$$;

CREATE FUNCTION public.read_user_historical_news(p_project_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $memoir$
declare rev text; enabled boolean;
begin
 if auth.uid() is null then raise exception 'authenticated user required' using errcode='42501'; end if;
 rev:=public.historical_news_revision(auth.uid(),p_project_id);
 enabled:=coalesce((select s.enabled from public.user_historical_news_state s where user_id=auth.uid() and project_id=p_project_id),true);
 return jsonb_build_object('enabled',enabled,'project_id',p_project_id,'context_revision',rev,
 'needs_revalidation',enabled and exists(select 1 from public.user_historical_news_clue
   where user_id=auth.uid() and project_id=p_project_id and status='ready' and context_revision<>rev
   and regexp_replace(context_revision,':[^:]+$','')=regexp_replace(rev,':[^:]+$','')),
 'clues',coalesce((select jsonb_agg(evidence || jsonb_build_object('id',id,'status',status,'project_id',project_id,
   'context_revision',context_revision,'relevance',relevance)) from public.user_historical_news_clue
   where user_id=auth.uid() and project_id=p_project_id and status='ready' and context_revision=rev and enabled),'[]'));
end $memoir$;

CREATE FUNCTION public.read_user_historical_news_basis(p_project_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare p public.user_memoir_project%rowtype;
begin
 if auth.uid() is null then raise exception 'authenticated user required' using errcode='42501'; end if;
 select * into p from public.user_memoir_project where user_id=auth.uid() and project_id=p_project_id for share;
 if not found then return null; end if;
 return public.read_user_memory_events(p_project_id) || jsonb_build_object('news_snapshot',jsonb_build_object(
 'source_sequence',p.source_sequence,'context_revision',public.historical_news_revision(auth.uid(),p_project_id)));
end $$;

CREATE FUNCTION public.read_user_interview_context(p_project_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if auth.uid() is null then raise exception 'authenticated owner required' using errcode='42501';end if;
 perform 1 from public.user_memoir_project where user_id=auth.uid() and project_id=p_project_id for share;
 if not found then raise exception 'project unavailable' using errcode='42501';end if;
 return public.read_user_interview_context_before_phase(p_project_id) ||
   jsonb_build_object('has_accepted_narration',public.conversation_has_narration(auth.uid(),p_project_id));
end $$;

CREATE FUNCTION public.read_user_interview_context_before_news(p_project_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb;
begin
  if auth.uid() is null then raise exception 'authenticated user required' using errcode='42501'; end if;
  return jsonb_build_object('plan',(select plan from public.user_interview_plan where user_id=auth.uid() and project_id=p_project_id),
    'photo_associations',public.interview_photo_links(auth.uid(),p_project_id),
    'photos',coalesce((select jsonb_agg(p) from (select distinct p from public.user_interview_turn t,
      jsonb_array_elements(t.photo_context) p where t.user_id=auth.uid() and t.project_id=p_project_id
        and public.interview_photo_available(auth.uid(),p_project_id,p->>'photo_id')
        and (public.interview_photo_available(auth.uid(),p_project_id,p->>'photo_id',true) or exists(
          select 1 from public.user_interview_photo_link l join public.user_narrator_source original
            on original.user_id=l.user_id and original.project_id=l.project_id and original.id=l.source_id
          where l.user_id=auth.uid() and l.project_id=p_project_id and l.photo_id=p->>'photo_id'
            and l.status='confirmed' and original.status='active' and original.version=l.source_version))) photos),'[]'));
end $$;

CREATE FUNCTION public.read_user_interview_context_before_phase(p_project_id text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select public.read_user_interview_context_before_news(p_project_id) || jsonb_build_object('historical_news',public.read_user_historical_news(p_project_id))
$$;

CREATE FUNCTION public.read_user_interview_photo(p_project_id text, p_photo_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select to_jsonb(p)-'user_id' from public.user_interview_photo p
    where user_id=auth.uid() and project_id=p_project_id and id=p_photo_id and status='ready'
$$;

CREATE FUNCTION public.read_user_interview_turn(p_project_id text, p_client_turn_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select public.read_user_interview_turn_before_recordings(p_project_id,p_client_turn_id) || jsonb_build_object(
   -- Accepted request identity survives audio-only deletion. Readable
   -- descriptors remain independently filtered by current access/lifecycle.
   'recording_ids',(select coalesce(jsonb_agg(recording_id::text order by position),'[]')
     from public.user_source_recording where user_id=auth.uid() and project_id=p_project_id and client_turn_id=p_client_turn_id),
   'recordings',
   public.read_user_source_recordings(p_project_id,(select source_id from public.user_interview_turn
     where user_id=auth.uid() and project_id=p_project_id and client_turn_id=p_client_turn_id)))
$$;

CREATE FUNCTION public.read_user_interview_turn_before_phase(p_project_id text, p_client_turn_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select public.interview_turn_record(t) from public.user_interview_turn t
    where user_id=auth.uid() and project_id=p_project_id and client_turn_id=p_client_turn_id
$$;

CREATE FUNCTION public.read_user_interview_turn_before_recordings(p_project_id text, p_client_turn_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 return public.read_user_interview_turn_before_phase(p_project_id,p_client_turn_id);
end
$$;

CREATE FUNCTION public.read_user_memory_events(p_project_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if current_setting('memoir.bounded_correction',true)='true' and exists(select 1 from public.user_lifetime_conversation where user_id=auth.uid() and project_id=p_project_id)
   then return jsonb_build_object('changed',true);end if;
 return public.read_user_memory_events_before_lifetime_read_api(p_project_id);
end $$;

CREATE FUNCTION public.read_user_memory_events_before_lifetime_lane(p_project_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner_id uuid:=auth.uid(); project public.user_memoir_project%rowtype;
begin
  if owner_id is null then raise exception 'authenticated user required' using errcode='42501'; end if;
  select * into project from public.user_memoir_project where user_id=owner_id and project_id=p_project_id;
  return pg_catalog.jsonb_build_object('schema_version',1,'project_id',p_project_id,
    'events',coalesce((select pg_catalog.jsonb_agg(public.memory_event_record(e) order by change_sequence,id)
      from public.user_memory_event e where user_id=owner_id and project_id=p_project_id and status<>'withdrawn'),'[]'::jsonb),
    'sources',coalesce((select pg_catalog.jsonb_agg(public.narrator_source_record(s) order by sequence)
      from public.user_narrator_source s where user_id=owner_id and project_id=p_project_id),'[]'::jsonb),
    'completed_rounds',(select count(*) from public.user_completed_round where user_id=owner_id and project_id=p_project_id),
    'processing',pg_catalog.jsonb_build_object('extracted_through',coalesce(project.extraction_cursor,0),
      'pending_inputs',(select count(*) from public.user_narrator_source where user_id=owner_id and project_id=p_project_id and processing_status<>'succeeded')));
end $$;

CREATE FUNCTION public.read_user_memory_events_before_lifetime_read_api(p_project_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
begin
 if exists(select 1 from public.user_memoir_lane l join public.user_lifetime_conversation c
   on c.user_id=l.user_id and c.project_id=l.project_id where l.user_id=auth.uid() and l.project_id=p_project_id
     and l.id::text=current_setting('memoir.lifetime_lane',true) and l.token is not null and l.lease_until>clock_timestamp()) then
   return jsonb_build_object('schema_version',1,'project_id',p_project_id,'processing',jsonb_build_object('extracted_through',
     (select extraction_cursor from public.user_memoir_project where user_id=auth.uid() and project_id=p_project_id)));
 end if;
 return public.read_user_memory_events_before_lifetime_lane(p_project_id);
end $$;

CREATE FUNCTION public.read_user_source_recordings(p_project_id text, p_source_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select coalesce(jsonb_agg(public.original_recording_descriptor(r) order by l.position),'[]')
 from public.user_source_recording l join public.user_original_recording r on r.id=l.recording_id
 where l.user_id=auth.uid() and l.project_id=p_project_id and l.source_id=p_source_id
 and public.original_recording_visible(r,auth.uid()) and r.storage_status='ready'
$$;

CREATE FUNCTION public.read_workspace_draft_section(p_project_id text, p_snapshot_id uuid, p_partition_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare root public.user_lifetime_lane_snapshot%rowtype; after_key text; cursor_id uuid; page jsonb;
begin
 select * into root from public.user_lifetime_lane_snapshot where id=p_snapshot_id and user_id=auth.uid() and project_id=p_project_id;
 if not found or p_partition_id is null or length(p_partition_id)>512 then raise exception 'section unavailable' using errcode='42501';end if;
 select coalesce(max(partition_key),'') into after_key from public.user_lifetime_memoir_section where user_id=auth.uid()
   and project_id=p_project_id and locale=root.locale and partition_key<p_partition_id;
 insert into public.user_lifetime_memoir_cursor(snapshot_id,user_id,project_id,last_partition,root_digest)
   values(root.id,auth.uid(),p_project_id,after_key,root.root_digest)
   on conflict(snapshot_id,last_partition,root_digest) do update set last_partition=excluded.last_partition returning id into cursor_id;
 -- Reuse the canonical page reader's ownership, policy, evidence and root fences.
 page:=public.read_lifetime_private_draft_page(p_project_id,p_snapshot_id,cursor_id::text,1);
 if page->'records'->0->>'id' is distinct from p_partition_id then raise exception 'section changed' using errcode='PT409';end if;
 return page->'records'->0;
end $$;

CREATE FUNCTION public.read_workspace_memory_focus(p_project_id text, p_focus jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare e public.user_memory_event%rowtype; stage text; owner uuid:=auth.uid();
begin
 perform 1 from public.user_memoir_project where user_id=owner and project_id=p_project_id for share;
 if not found then raise exception 'workspace unavailable' using errcode='42501';end if;
 if jsonb_typeof(p_focus)<>'object' then raise exception 'invalid workspace task' using errcode='22023';end if;
 if p_focus->>'kind'='add_memory' then
   stage:=p_focus->>'life_stage';
   if stage is null or stage not in ('baby','childhood','adolescence','young_adulthood','midlife','later_life','unplaced')
     or (select count(*) from jsonb_object_keys(p_focus))<>2 then raise exception 'invalid life stage' using errcode='22023';end if;
   return jsonb_build_object('kind','add_memory','life_stage',stage);
 elsif p_focus->>'kind'='explore_memory' then
   if (select count(*) from jsonb_object_keys(p_focus))<>3 then raise exception 'invalid memory focus' using errcode='22023';end if;
   select * into e from public.user_memory_event where user_id=owner and project_id=p_project_id
     and id=p_focus->>'event_id' and revision=(p_focus->>'event_revision')::bigint and status='active';
   if not found or not exists(select 1 from public.user_memory_event_source r join public.user_narrator_source s
     on s.user_id=r.user_id and s.project_id=r.project_id and s.id=r.source_id and s.version=r.source_version and s.status='active'
     where r.user_id=owner and r.project_id=p_project_id and r.event_id=e.id) or
     exists(select 1 from public.user_memory_event_source r where r.user_id=owner and r.project_id=p_project_id and r.event_id=e.id
       and not exists(select 1 from public.user_narrator_source s where s.user_id=owner and s.project_id=p_project_id
         and s.id=r.source_id and s.version=r.source_version and s.status='active')) then
     raise exception 'memory changed or unavailable' using errcode='PT409';end if;
   return jsonb_build_object('kind','explore_memory','event_id',e.id,'event_revision',e.revision,
     'event',public.bounded_lifetime_event_record(e));
 end if;
 raise exception 'unknown workspace task' using errcode='22023';
end $$;

CREATE FUNCTION public.reconcile_interview_photo_links(p_owner uuid, p_project_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare link public.user_interview_photo_link%rowtype; matches text[]; resolved text; changed boolean:=false;
begin
  for link in select * from public.user_interview_photo_link where user_id=p_owner and project_id=p_project_id and status in ('pending','confirmed') loop
    select array_agg(distinct e.event_id) into matches from public.user_memory_event_source e
      join public.user_memory_event event on event.user_id=e.user_id and event.project_id=e.project_id and event.id=e.event_id
      join public.user_narrator_source s on s.user_id=e.user_id and s.project_id=e.project_id and s.id=e.source_id
      where e.user_id=p_owner and e.project_id=p_project_id and e.source_id=link.source_id and e.source_version=link.source_version
        and s.status='active' and s.version=link.source_version and event.status='active'
        and strpos(e.evidence->>'quote',link.quote)>0
        and strpos(substr(s.text,strpos(s.text,link.quote)+1),link.quote)=0
        and (link.intended_event_id is null or e.event_id=link.intended_event_id)
        and not exists(select 1 from public.user_memory_event_source_exclusion x where x.user_id=p_owner and x.project_id=p_project_id
          and x.event_id=e.event_id and x.source_id=link.source_id);
    resolved:=case when array_length(matches,1)=1 then matches[1] else null end;
    if link.event_id is distinct from resolved then
      update public.user_interview_photo_link set event_id=resolved,status=case when resolved is null then 'pending' else 'confirmed' end
        where user_id=p_owner and project_id=p_project_id and id=link.id;
      changed:=true;
    end if;
  end loop;
  if changed then perform public.invalidate_interview_photo_projection(p_owner,p_project_id,false); end if;
end $$;

CREATE FUNCTION public.reconcile_lifetime_source_continuity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.version is distinct from new.version or old.status is distinct from new.status then
    delete from public.user_lifetime_continuity c using public.user_lifetime_conversation l
      where c.user_id=l.user_id and c.conversation_id=l.conversation_id and l.user_id=new.user_id and l.project_id=new.project_id
        and exists(select 1 from jsonb_array_elements(c.data->'source_refs') ref where ref->>'source_id'=new.id::text);
  end if;
  return new;
end $$;

CREATE FUNCTION public.record_background_service_work(p_user_id uuid, p_project_id text, p_step jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $memoir$
declare source public.user_narrator_source%rowtype;
begin
 if p_step->>'skill' not in ('memoir-place-groups','memoir-place-photo-research','memoir-historical-news-research')
   or p_step->>'status' not in ('running','completed','saved','failed','cached')
   or p_step->>'execution' not in ('deterministic','provider','cache')
   or p_step->>'id' !~ '^[a-f0-9]{64}$' then raise exception 'invalid service receipt' using errcode='22023';end if;
 if p_step->>'skill'='memoir-historical-news-research' then
   select s.* into source from public.user_historical_news_job j join public.user_narrator_source s
     on s.user_id=j.user_id and s.project_id=j.project_id and s.sequence=j.source_sequence
   where j.user_id=p_user_id and j.project_id=p_project_id and j.id=(p_step->>'research_job_id')::uuid and s.status='active';
   if not found then raise exception 'owned research claim required' using errcode='42501';end if;
 elsif p_step->>'client_turn_id' is not null then
   select * into source from public.user_narrator_source where user_id=p_user_id and project_id=p_project_id
     and client_turn_id=(p_step->>'client_turn_id')::uuid and status='active';
   if not found then raise exception 'owned turn reference required' using errcode='42501';end if;
 end if;
 insert into public.user_background_skill_work(user_id,project_id,id,phase,skill,execution,coverage_start,coverage_end,status,
   client_turn_id,source_id,source_version,model_invoked,model_attempts)
 values(p_user_id,p_project_id,p_step->>'id',p_step->>'phase',p_step->>'skill',p_step->>'execution',coalesce(source.sequence,0),coalesce(source.sequence,0),p_step->>'status',
   source.client_turn_id,source.id,source.version,(p_step->>'model_invoked')::boolean,
   case when p_step->>'model_invoked'='false' then 0 else null end)
 on conflict(user_id,project_id,id) do update set status=excluded.status,execution=excluded.execution,
   model_invoked=excluded.model_invoked,model_attempts=excluded.model_attempts,updated_at=clock_timestamp();
end $memoir$;

CREATE FUNCTION public.record_lifetime_lane_output(p_lane_id uuid, p_token uuid, p_page_number bigint, p_phase text, p_digest text, p_page_digest text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare page jsonb;
begin
 page:=public.read_lifetime_memoir_lane_page(p_lane_id,p_token);
 if (page->>'page_number')::bigint is distinct from p_page_number or p_page_digest is distinct from page->>'page_digest' then
   raise exception 'stale derived lane output input' using errcode='PT409';end if;
 insert into public.user_lifetime_lane_output(snapshot_id,page_number,phase,digest,input_digest)
 values((page->>'snapshot_id')::uuid,p_page_number,p_phase,p_digest,
   (page->>'input_digest')) on conflict do nothing;
 return true;
end $$;

CREATE FUNCTION public.record_lifetime_skill_phase(p_fence jsonb, p_phase text, p_status text, p_invocation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare page jsonb;
begin
  perform public.record_lifetime_skill_phase_before_place_progress(
    p_fence,p_phase,p_status,p_invocation_id);
  if p_phase='extract' and p_status='running' then
    page:=public.read_lifetime_memoir_lane_page(
      (p_fence->>'lane_id')::uuid,(p_fence->>'token')::uuid);
    if page ? 'two_lane' and page->'two_lane'->>'work_mode'='extract'
      and (not(page->'two_lane' ? 'selected_skills') or page->'two_lane'->'selected_skills' ?& array['memoir-author-timeline','memoir-place-journey']) then
      perform public.background_skill_receipt(
        page,'place','memoir-place-journey','embedded','running');
    end if;
  end if;
end $$;

CREATE FUNCTION public.record_lifetime_skill_phase_before_place_progress(p_fence jsonb, p_phase text, p_status text, p_invocation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare page jsonb; source public.user_narrator_source%rowtype; skill text; first_source bigint;last_source bigint;
begin
 if p_phase not in ('extract','profile','summarize','prepare','draft','review','index','guidance') or p_status not in ('running','completed','failed')
   or p_invocation_id is null then raise exception 'bounded skill phase required' using errcode='22023';end if;
 perform public.lock_lifetime_memoir_lane_publication(p_fence);
 if p_phase='profile' then
   page:=public.read_lifetime_profile_page((p_fence->>'lane_id')::uuid,(p_fence->>'token')::uuid);
   if page->'profile_context'->>'work_mode'<>'extract' then raise exception 'profile model not admitted' using errcode='42501';end if;
   skill:='memoir-memory-context';
 else
   page:=public.read_lifetime_memoir_lane_page((p_fence->>'lane_id')::uuid,(p_fence->>'token')::uuid);
   skill:=case when page->>'skill'='composer' then 'memoir-composer' when page->>'skill'='guidance' then 'memoir-interview-guidance' else 'memoir-author-timeline' end;
   if p_phase='extract' and page->'two_lane' ? 'selected_skills'
     and not(page->'two_lane'->'selected_skills' ? 'memoir-author-timeline') then skill:='memoir-place-journey';end if;
   if (page->>'skill'='timeline' and p_phase not in ('extract','summarize'))
     or (page->>'skill'='composer' and p_phase not in ('prepare','draft','review','index','guidance')) then
     raise exception 'skill phase mismatch' using errcode='42501';end if;
   if p_phase='extract' and page->'two_lane'->>'work_mode'<>'extract' then raise exception 'timeline model not admitted' using errcode='42501';end if;
 end if;
 if page->>'page_digest' is distinct from p_fence->>'page_digest' then raise exception 'skill page changed' using errcode='40001';end if;
 first_source:=coalesce((page->'source'->>'sequence')::bigint,0);last_source:=first_source;
 if page ? 'batch' then
   select min((s->>'sequence')::bigint),max((s->>'sequence')::bigint) into first_source,last_source
     from jsonb_array_elements(coalesce(page->'batch'->'sources','[]')||coalesce(page->'batch'->'new_messages','[]')) s;
 end if;
 select * into source from public.user_narrator_source where user_id=(page->>'user_id')::uuid
   and project_id=page->>'project_id' and sequence=last_source and status='active';
 insert into public.user_background_skill_work(user_id,project_id,id,lane_id,snapshot_id,page_digest,phase,skill,execution,
   source_id,source_version,client_turn_id,coverage_start,coverage_end,status,model_invoked,model_attempts,invocation_id,lease_token)
 values((page->>'user_id')::uuid,page->>'project_id',public.background_skill_id(page,p_phase),
   (page->>'lane_id')::uuid,(page->>'snapshot_id')::uuid,page->>'page_digest',p_phase,skill,'model',
   source.id,source.version,source.client_turn_id,coalesce(first_source,0),coalesce(last_source,0),p_status,p_status='completed',1,p_invocation_id,(page->>'token')::uuid)
 on conflict(user_id,project_id,id) do update set status=excluded.status,
   page_digest=excluded.page_digest,lease_token=excluded.lease_token,
   model_attempts=public.user_background_skill_work.model_attempts+case when public.user_background_skill_work.invocation_id<>p_invocation_id then 1 else 0 end,
   model_invoked=public.user_background_skill_work.model_invoked or excluded.model_invoked,
   invocation_id=p_invocation_id,updated_at=clock_timestamp()
 where public.user_background_skill_work.status<>'saved';
end $$;

CREATE FUNCTION public.record_lifetime_source_position() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op='UPDATE' then
    insert into public.user_lifetime_source_position values(old.user_id,old.project_id,old.sequence,old.id,old.version) on conflict do nothing;
  end if;
  insert into public.user_lifetime_source_position values(new.user_id,new.project_id,new.sequence,new.id,new.version) on conflict do nothing;
  return new;
end $$;

CREATE FUNCTION public.record_memory_event_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if TG_OP='UPDATE' and new.revision=old.revision then return new; end if;
  insert into public.user_memory_event_change(user_id,project_id,sequence,event_id,old_group,new_group,revision)
    values(new.user_id,new.project_id,new.change_sequence,new.id,
      case when TG_OP='UPDATE' then public.memory_event_group(old) else null end,public.memory_event_group(new),new.revision)
    on conflict(user_id,project_id,sequence) do nothing;
  return new;
end $$;

CREATE FUNCTION public.record_private_draft_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare m public.user_memory%rowtype; next_round bigint; inserted integer;
begin
  if TG_OP='DELETE' then m:=old; else m:=new; end if;
  if m.kind <> 'agent' or m.project_id is null then return null; end if;
  if TG_OP='INSERT' or (TG_OP='UPDATE' and old.project_id is null) then
    -- A durable assistant-only greeting or incomplete exchange is not a round.
    if m.content !~ '^Storyteller: ' or
       pg_catalog.strpos(m.content,E'\nMemory Spark: ')=0 or
       pg_catalog.btrim(pg_catalog.regexp_replace(pg_catalog.split_part(m.content,E'\nMemory Spark: ',1),'^Storyteller: ',''))='' or
       pg_catalog.btrim(pg_catalog.split_part(m.content,E'\nMemory Spark: ',2))='' then return null; end if;
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(m.user_id::text||':'||m.project_id,0));
    select coalesce(max(ordinal),0)+1 into next_round from public.user_completed_round
      where user_id=m.user_id and project_id=m.project_id;
    insert into public.user_completed_round(user_id,project_id,memory_id,turn_id,ordinal)
      values(m.user_id,m.project_id,m.id,coalesce(m.client_turn_id,m.id),next_round)
      on conflict do nothing;
    get diagnostics inserted=ROW_COUNT;
    if inserted=0 then return null; end if;
    insert into public.user_private_draft_outbox(user_id,project_id,memory_id,change_kind)
      values(m.user_id,m.project_id,m.id,'round');
  elsif TG_OP='DELETE' then
    insert into public.user_private_draft_outbox(user_id,project_id,memory_id,change_kind)
      values(m.user_id,m.project_id,m.id,'delete');
  elsif old.content is distinct from new.content or old.life_stage is distinct from new.life_stage or
        old.project_id is distinct from new.project_id then
    insert into public.user_private_draft_outbox(user_id,project_id,memory_id,change_kind)
      values(m.user_id,m.project_id,m.id,case when old.content is distinct from new.content then 'edit' else 'assignment' end);
  end if;
  return null;
end $$;

CREATE FUNCTION public.recording_server_operation(p_owner uuid, p_operation text, p_recording_id uuid, p_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.user_original_recording%rowtype; identifier uuid; project text:=p_data->>'project_id';
begin
 if p_operation in ('consent_status','consent_grant','consent_revoke') then
   return public.recording_consent_operation(p_owner,p_operation,p_data);
 end if;
 perform 1 from auth.users where id=p_owner for share;
 if not found then raise exception 'recording owner unavailable' using errcode='42501';end if;
 if p_operation='find_upload' then
   select * into r from public.user_original_recording where user_id=p_owner and upload_key=(p_data->>'upload_key')::uuid;
   return case when found then to_jsonb(r) else null end;
 end if;
 if p_operation='cancel_upload' then
   perform pg_advisory_xact_lock(hashtextextended(p_owner::text||':'||(p_data->>'upload_key'),0));
   select * into r from public.user_original_recording where user_id=p_owner and upload_key=(p_data->>'upload_key')::uuid for update;
   if found and r.lifecycle='attached' then
     return jsonb_build_object('cancelled',true,'recording_id',r.id,'already_attached',true);
   end if;
   insert into public.user_original_recording_cancel(user_id,upload_key) values(p_owner,(p_data->>'upload_key')::uuid) on conflict do nothing;
   if r.id is not null then
     update public.user_original_recording set lifecycle='deleted',storage_status='deleted',asr_result=null,
       cleanup_status=case when cleanup_status='complete' then 'complete' else 'pending' end where id=r.id;
   end if;
   return jsonb_build_object('cancelled',true,'recording_id',r.id,'already_attached',false);
 end if;
 if p_operation in ('read','begin_upload','finalize','asr_failed','asr_succeeded') then
   -- Disable is a committed revocation boundary: it waits for admitted reads/
   -- provider work, and no later guard can admit after it commits.
   perform 1 from public.original_recording_rollout where enabled for share;
   if not found then raise exception 'recording unavailable' using errcode='42501';end if;
 end if;
 if p_operation in ('authorize','reserve') then
   perform 1 from public.original_recording_rollout where enabled for share;
   if not found or not public.original_recording_authorized(p_owner,project) then
     raise exception 'recording authority required' using errcode='42501';end if;
   if project is not null then
     perform 1 from public.user_memoir_project where user_id=p_owner and project_id=project for share;
     if not found then raise exception 'recording project unavailable' using errcode='42501';end if;
   end if;
   if p_operation='authorize' then return '{}'::jsonb;end if;
   perform pg_advisory_xact_lock(hashtextextended(p_owner::text||':'||(p_data->>'upload_key'),0));
   if exists(select 1 from public.user_original_recording_cancel where user_id=p_owner and upload_key=(p_data->>'upload_key')::uuid) then
     raise exception 'upload was cancelled' using errcode='40001';end if;
   select * into r from public.user_original_recording where user_id=p_owner and upload_key=(p_data->>'upload_key')::uuid for update;
   if found then
     if r.lifecycle='deleted' or r.upload_project_id is distinct from project
       or r.content_sha256 is distinct from p_data->>'content_sha256'
       or r.content_type is distinct from p_data->>'content_type'
       or r.codec is distinct from p_data->>'codec'
       or r.byte_size is distinct from (p_data->>'byte_size')::bigint
       or r.duration_seconds is distinct from (p_data->>'duration_seconds')::double precision then
       raise exception 'upload retry identity conflict' using errcode='40001';end if;
     return to_jsonb(r);end if;
   identifier:=gen_random_uuid();
   insert into public.user_original_recording(id,user_id,project_id,upload_project_id,upload_key,object_path,content_type,codec,byte_size,duration_seconds,content_sha256)
   values(identifier,p_owner,project,project,(p_data->>'upload_key')::uuid,'originals/'||identifier::text,
     p_data->>'content_type',p_data->>'codec',(p_data->>'byte_size')::bigint,
     (p_data->>'duration_seconds')::double precision,p_data->>'content_sha256') returning * into r;
   return to_jsonb(r);
 end if;
 if p_operation='read' then
   select project_id into project from public.user_original_recording where user_id=p_owner and id=p_recording_id;
   if project is not null then
     perform 1 from public.user_memoir_project where user_id=p_owner and project_id=project for share;
   end if;
 end if;
 select * into r from public.user_original_recording where user_id=p_owner and id=p_recording_id for update;
 if not found then raise exception 'recording unavailable' using errcode='42501';end if;
 -- Withdrawal must never prevent an owner from requesting cleanup.
 if p_operation='read' then
   if r.project_id is distinct from project then raise exception 'recording scope changed' using errcode='40001';end if;
   if not public.original_recording_visible(r,p_owner) then raise exception 'recording unavailable' using errcode='42501';end if;
   return to_jsonb(r);
 elsif p_operation='delete' then
   if (p_data->>'draft_only')::boolean is true and r.lifecycle='attached' then
     raise exception 'recording already attached; reconcile acceptance' using errcode='40001';end if;
   update public.user_original_recording set lifecycle='deleted',storage_status='deleted',
     cleanup_status=case when cleanup_status='complete' then 'complete' else 'pending' end,asr_result=null
     where id=r.id returning * into r;
 elsif p_operation='finish_upload' then
   update public.user_original_recording_upload set finished_at=clock_timestamp()
     where id=(p_data->>'attempt_id')::uuid and recording_id=r.id and finished_at is null;
   if found then
     -- A completed writer invalidates every DELETE receipt taken before it
     -- stopped, even if that DELETE's HTTP response was delayed until later.
     update public.user_original_recording set write_revision=write_revision+1,
       cleanup_status=case when lifecycle='deleted' then 'pending' else cleanup_status end
       where id=r.id returning * into r;
   end if;
 elsif p_operation='cleanup_complete' and r.lifecycle='deleted' then
   if r.write_revision=(p_data->>'write_revision')::bigint
     and not exists(select 1 from public.user_original_recording_upload where recording_id=r.id and finished_at is null) then
     update public.user_original_recording set cleanup_status='complete' where id=r.id returning * into r;
   end if;
 else
   if not public.original_recording_visible(r,p_owner) then raise exception 'recording unavailable' using errcode='42501';end if;
   if p_operation='begin_upload' then
     update public.user_original_recording set write_revision=write_revision+1 where id=r.id returning * into r;
     insert into public.user_original_recording_upload(recording_id) values(r.id) returning id into identifier;
     return to_jsonb(r)||jsonb_build_object('upload_attempt_id',identifier);
   elsif p_operation='finalize' then
     if r.content_sha256 is distinct from p_data->>'content_sha256'
       or r.byte_size is distinct from (p_data->>'byte_size')::bigint then
       raise exception 'original readback conflict' using errcode='40001';end if;
     update public.user_original_recording set storage_status='ready' where id=r.id returning * into r;
   elsif p_operation in ('asr_failed','asr_succeeded') and r.storage_status='ready' then
     if p_operation='asr_succeeded' and (jsonb_typeof(p_data->'result')<>'object' or length(btrim(coalesce(p_data->'result'->>'text','')))=0
       or octet_length((p_data->'result')::text)>262144) then raise exception 'invalid transcription';end if;
     -- A racing failed attempt cannot overwrite a persisted successful result.
     if r.transcription_status<>'succeeded' then
       update public.user_original_recording set transcription_status=case when p_operation='asr_succeeded' then 'succeeded' else 'failed' end,
         asr_result=case when p_operation='asr_succeeded' then p_data->'result' else null end where id=r.id returning * into r;
     end if;
   else raise exception 'invalid recording transition';end if;
 end if;
 return to_jsonb(r);
end $$;

CREATE FUNCTION public.release_formal_memoir(p_run_id uuid, p_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare run public.user_formal_memoir_run%rowtype; next_ordinal integer;
begin
 run:=public.lock_formal_memoir_run(p_run_id,p_token);
 update public.user_formal_memoir_run set state='pending',token=null,lease_until=null,fence=fence+1 where id=run.id;
 select coalesce(min(p.ordinal),run.chapter_count+1) into next_ordinal from public.user_formal_memoir_plan p
 where p.run_id=run.id and not exists(select 1 from public.user_formal_memoir_chapter c where c.run_id=p.run_id and c.ordinal=p.ordinal);
 return jsonb_build_object('status','pending','run_id',run.id,'next_ordinal',next_ordinal);
end $$;

CREATE FUNCTION public.release_lifetime_collection_job(p_job_id uuid, p_token uuid, p_error text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare job public.user_lifetime_collection_job%rowtype;
begin
 if p_error is not null and p_error<>'BOUNDED_JOB_RETRY' then raise exception 'invalid collection error code';end if;
 job:=public.lock_lifetime_collection_job(p_job_id,p_token);
 update public.user_lifetime_collection_job set state=case when p_error is not null and attempts>=3 then 'FAILED' else 'QUEUED' end,
  token=null,lease_until=null,error=p_error,attempts=case when p_error is null then 0 else attempts end where id=job.id;
 return true;
end $$;

CREATE FUNCTION public.release_user_agent_turn_lease(p_lease_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare
  current_user_id uuid := auth.uid();
  released boolean := false;
begin
  if current_user_id is null then
    raise exception 'authenticated user required';
  end if;

  delete from public.user_agent_turn_lease
   where user_id = current_user_id
     and lease_token = p_lease_token;
  released := found;
  update public.user_interview_turn set interview_guidance_snapshot=null where user_id=current_user_id
    and interview_guidance_snapshot->'fence'->>'lease_digest'=encode(sha256(convert_to(p_lease_token::text,'UTF8')),'hex');
  return released;
end;
$$;

CREATE FUNCTION public.renew_user_agent_turn_lease(p_lease_token uuid, p_lease_seconds integer DEFAULT 300) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare
  current_user_id uuid := auth.uid();
  renewed boolean := false;
  duration_seconds integer := greatest(30, least(coalesce(p_lease_seconds, 300), 900));
begin
  if current_user_id is null then
    raise exception 'authenticated user required';
  end if;

  update public.user_agent_turn_lease
     set expires_at = now() + make_interval(secs => duration_seconds),
         updated_at = now()
   where user_id = current_user_id
     and lease_token = p_lease_token
     and expires_at > now()
  returning true into renewed;

  return coalesce(renewed, false);
end;
$$;

CREATE FUNCTION public.request_workspace_section_rework(p_project_id text, p_request_id uuid, p_snapshot_id uuid, p_root_digest text, p_partition_id text, p_instruction text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare owner uuid:=auth.uid(); project public.user_memoir_project%rowtype;
 root public.user_lifetime_lane_snapshot%rowtype; section public.user_lifetime_memoir_section%rowtype;
 prior public.user_workspace_section_rework%rowtype; lane public.user_memoir_lane%rowtype;
begin
 select * into project from public.user_memoir_project where user_id=owner and project_id=p_project_id for update;
 if not found then raise exception 'workspace unavailable' using errcode='42501';end if;
 if p_request_id is null or p_instruction is null or length(btrim(p_instruction)) not between 1 and 1000 then
   raise exception 'bounded revision request required' using errcode='22023';end if;
 select * into prior from public.user_workspace_section_rework where user_id=owner and project_id=p_project_id and request_id=p_request_id;
 if found then
   if prior.snapshot_id is distinct from p_snapshot_id or prior.root_digest is distinct from p_root_digest
     or prior.partition_key is distinct from p_partition_id or prior.instruction is distinct from btrim(p_instruction) then
     raise exception 'revision request replay conflict' using errcode='PT409';end if;
   -- A lost acknowledgement may be retried after another edition ran. Recover
   -- the pending task without changing its identity or interrupting a lease.
   if prior.status='pending' then
     select l.* into lane from public.user_memoir_lane l join public.user_lifetime_lane_snapshot s on s.lane_id=l.id
       where s.id=prior.snapshot_id and l.user_id=owner and l.project_id=p_project_id and l.skill='composer' for update of l;
     if found and not(lane.token is not null and lane.lease_until>clock_timestamp() and lane.run_deadline>clock_timestamp()) then
       if not exists(select 1 from public.user_lifetime_lane_snapshot where lane_id=lane.id and state='pending') then
         update public.user_memoir_lane set locale=prior.locale where id=lane.id;
       end if;
       perform public.retry_user_memoir_lane(p_project_id,'composer');
     end if;
   end if;
   return jsonb_build_object('request_id',prior.request_id,'status',prior.status);
 end if;
 select * into root from public.user_lifetime_lane_snapshot r where r.id=p_snapshot_id and r.user_id=owner and r.project_id=p_project_id
   and r.root_digest=p_root_digest and r.state in ('completed','proposed') and r.policy_epoch=project.policy_epoch
   and r.preference_revision=(select preference_revision from public.user_lifetime_conversation where user_id=owner and project_id=p_project_id);
 if not found or exists(select 1 from public.user_lifetime_lane_snapshot newer where newer.lane_id=root.lane_id
   and newer.locale=root.locale and newer.state in ('completed','proposed') and newer.created_at>root.created_at) then
   raise exception 'section root changed' using errcode='PT409';end if;
 select * into lane from public.user_memoir_lane where id=root.lane_id and skill='composer' for update;
 if not found or (lane.token is not null and lane.lease_until>clock_timestamp() and lane.run_deadline>clock_timestamp()) then
   raise exception 'section is already changing' using errcode='PT409';end if;
 select s.* into section from public.user_lifetime_memoir_section s join public.user_lifetime_lane_snapshot r on r.id=s.snapshot_id
   where s.user_id=owner and s.project_id=p_project_id and s.locale=root.locale and s.partition_key=p_partition_id
     and r.state in ('completed','proposed') and r.created_at<=root.created_at and r.policy_epoch=root.policy_epoch
     and r.preference_revision=root.preference_revision order by r.created_at desc limit 1 for update of s;
 if not found or section.proposal is not null or not(section.bundle ? 'preview') or
   not exists(select 1 from public.user_memory_event where user_id=owner and project_id=p_project_id and id=section.event_id
     and revision=section.event_revision and status='active') or
   not exists(select 1 from public.user_narrator_source where user_id=owner and project_id=p_project_id and id=section.source_id
     and version=section.source_version and status='active') or
   not public.workspace_rework_partition_current(owner,p_project_id,section.event_id,p_partition_id)
   then raise exception 'section changed' using errcode='PT409';end if;
 if exists(select 1 from public.user_workspace_section_rework where user_id=owner and project_id=p_project_id
   and locale=root.locale and partition_key=p_partition_id and status='pending') then raise exception 'revision already queued' using errcode='PT409';end if;
 if octet_length((section.bundle->'preview')::text)>12288 then raise exception 'section exceeds revision context budget' using errcode='22023';end if;
 insert into public.user_workspace_section_rework(user_id,project_id,request_id,snapshot_id,root_digest,partition_key,locale,event_id,event_revision,source_id,source_version,instruction,original_preview)
 values(owner,p_project_id,p_request_id,root.id,root.root_digest,p_partition_id,root.locale,section.event_id,section.event_revision,section.source_id,section.source_version,btrim(p_instruction),
   jsonb_build_object('schema_version',1,'title',section.bundle->'preview'->>'title','text',section.bundle->'preview'->>'text'));
 -- Protect the current text so the normal commit path creates a review proposal.
 update public.user_lifetime_memoir_section set human_locked=true where user_id=owner and project_id=p_project_id
   and locale=root.locale and partition_key=p_partition_id and snapshot_id=section.snapshot_id;
 -- An editorial request is independent of canonical evidence authority. Retire
 -- an unfinished root for this edition so a newly selected older partition
 -- cannot fall behind its cursor; another edition remains resumable. Admission
 -- above forbids changing a live lease, and retry clears expired tokens.
 update public.user_lifetime_lane_snapshot set state='stale'
   where lane_id=lane.id and locale=root.locale and state='pending';
 -- Keep an unfinished edition resumable; the completion wrapper drains the
 -- other editions after this root has become available for review.
 if not exists(select 1 from public.user_lifetime_lane_snapshot where lane_id=lane.id and state='pending') then
   update public.user_memoir_lane set locale=root.locale where id=lane.id;
 end if;
 perform public.retry_user_memoir_lane(p_project_id,'composer');
 return jsonb_build_object('request_id',p_request_id,'status','pending');
end $$;

CREATE FUNCTION public.require_lifetime_draft_receipt_coverage() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if new.delivered and not old.delivered then perform public.assert_lifetime_draft_receipt_scope(new.id);end if;
 return new;
end $$;

CREATE FUNCTION public.require_lifetime_policy_ready(p_owner uuid, p_project text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if exists(select 1 from public.user_lifetime_pending_policy where user_id=p_owner and project_id=p_project)
   or exists(select 1 from public.user_lifetime_policy_inventory_pending where user_id=p_owner and project_id=p_project) then
   raise exception 'LIFETIME_POLICY_PENDING' using errcode='55000';end if;
end $$;

CREATE FUNCTION public.resolve_lifetime_conversation(p_project_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  owner uuid:=auth.uid();
  identity public.user_lifetime_conversation%rowtype;
  projects jsonb;
  new_project text;
  guest boolean;
  unscoped boolean;
  empty_guest_project boolean:=false;
begin
  if owner is null then raise exception 'authenticated owner required'; end if;
  select is_anonymous into guest from auth.users where id=owner for update;
  if not found then raise exception 'authenticated owner required'; end if;
  select * into identity from public.user_lifetime_conversation where user_id=owner and product='memoir';
  if found then
    if p_project_id is not null and p_project_id<>identity.project_id then
      raise exception 'project does not match canonical conversation';
    end if;
  else
    select coalesce(pg_catalog.jsonb_agg(project_id order by project_id),'[]'::jsonb) into projects from (
      select project_id from public.user_memoir_project where user_id=owner
      union select project_id from public.user_memory where user_id=owner and project_id is not null
      union select project_id from public.user_conversation_attachment where user_id=owner
    ) owned;
    if p_project_id is not null and not (projects ? p_project_id) then
      raise exception 'owned project required';
    end if;
    select exists(select 1 from public.user_memory where user_id=owner and project_id is null) into unscoped;
    -- Older guest onboarding created an empty project before the first answer.
    -- Preserve that server-owned ID only when no testimony was ever accepted.
    if guest and not unscoped and pg_catalog.jsonb_array_length(projects)=1 then
      new_project:=projects->>0;
      select exists(select 1 from public.user_memoir_project
        where user_id=owner and project_id=new_project and source_sequence=0 and event_sequence=0)
        and not exists(select 1 from public.user_narrator_source where user_id=owner)
        and not exists(select 1 from public.user_memory where user_id=owner)
        and not exists(select 1 from public.user_conversation_attachment where user_id=owner)
        and not exists(select 1 from public.user_completed_round where user_id=owner)
        into empty_guest_project;
    end if;
    if (pg_catalog.jsonb_array_length(projects)>0 or unscoped) and not empty_guest_project then
      return pg_catalog.jsonb_build_object('schema_version',1,'outcome','mapping_required','project_ids',projects)
        || case when unscoped then pg_catalog.jsonb_build_object('unscoped_history',true) else '{}'::jsonb end;
    end if;
    if not empty_guest_project then
      new_project:='lifetime-' || pg_catalog.gen_random_uuid()::text;
      insert into public.user_memoir_project(user_id,project_id) values(owner,new_project);
    end if;
    insert into public.user_lifetime_conversation(user_id,project_id) values(owner,new_project) returning * into identity;
  end if;
  return pg_catalog.jsonb_build_object('schema_version',1,'outcome','resolved','owner_id',owner,
    'conversation_id',identity.conversation_id,'product',identity.product,'project_id',identity.project_id);
end $$;

CREATE FUNCTION public.retry_user_memoir_lane(p_project_id text, p_skill text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare queued boolean;
begin
  if auth.uid() is null then raise exception 'authenticated user required' using errcode='42501'; end if;
  update public.user_memoir_lane set attempts=0,error=null,available_at=clock_timestamp(),pending=true,token=null,lease_until=null,run_deadline=null
    where user_id=auth.uid() and project_id=p_project_id and skill=p_skill and
      (token is null or lease_until<=clock_timestamp() or run_deadline<=clock_timestamp());
  queued:=found;
  if queued then
    -- A coordinator failure pauses the project's required work together.
    update public.user_memoir_lane set attempts=0,error=null,available_at=clock_timestamp(),
      pending=true,token=null,lease_until=null,run_deadline=null
    where user_id=auth.uid() and project_id=p_project_id and pending and attempts>=3
      and (token is null or lease_until<=clock_timestamp() or run_deadline<=clock_timestamp())
      and exists(select 1 from public.user_memoir_background_agent a where a.user_id=auth.uid()
        and a.project_id=p_project_id and a.pending and a.attempts>=3);
    update public.user_memoir_background_agent set attempts=0,pending=true,available_at=clock_timestamp()
      where user_id=auth.uid() and project_id=p_project_id and
        (token is null or lease_until<=clock_timestamp() or run_deadline<=clock_timestamp());
  end if;
  return pg_catalog.jsonb_build_object('queued',queued);
end $$;

CREATE FUNCTION public.revalidate_user_historical_news(p_project_id text, p_hypothesis jsonb, p_snapshot jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $memoir$
declare project public.user_memoir_project%rowtype; rev text;
begin
 if auth.uid() is null then raise exception 'authenticated user required' using errcode='42501'; end if;
 select * into project from public.user_memoir_project where user_id=auth.uid() and project_id=p_project_id for update;
 if not found then return null; end if;
 rev:=public.historical_news_revision(auth.uid(),p_project_id);
 if p_snapshot->>'context_revision' is distinct from rev or (p_snapshot->>'source_sequence')::bigint is distinct from project.source_sequence
   or jsonb_typeof(p_hypothesis) is distinct from 'object' or octet_length(p_hypothesis::text)>2000 then return null; end if;
 update public.user_historical_news_clue set context_revision=rev
   where user_id=auth.uid() and project_id=p_project_id and status='ready' and relevance=p_hypothesis
   and regexp_replace(context_revision,':[^:]+$','')=regexp_replace(rev,':[^:]+$','');
 return public.read_user_historical_news(p_project_id);
end $memoir$;

CREATE FUNCTION public.rewrite_merged_context(p_value jsonb, guest_id uuid, owner_id uuid, id_map jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare result jsonb; item record; text_value text;
begin
  if jsonb_typeof(p_value) = 'string' then
    text_value := p_value #>> '{}';
    return to_jsonb(coalesce(id_map->>text_value, public.import_memoir_path(text_value, guest_id, owner_id)));
  elsif jsonb_typeof(p_value) = 'object' then
    result := '{}'::jsonb;
    for item in select key, value as content from jsonb_each(p_value) loop
      result := result || jsonb_build_object(item.key, public.rewrite_merged_context(item.content, guest_id, owner_id, id_map));
    end loop;
    return result;
  elsif jsonb_typeof(p_value) = 'array' then
    select coalesce(jsonb_agg(public.rewrite_merged_context(content, guest_id, owner_id, id_map) order by position), '[]'::jsonb)
      into result from jsonb_array_elements(p_value) with ordinality e(content, position);
    return result;
  end if;
  return p_value;
end;
$$;

CREATE FUNCTION public.save_lifetime_continuity(p_conversation_id uuid, p_record_id text, p_kind text, p_expected_revision bigint, p_policy_epoch bigint, p_lease_token uuid, p_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $memoir$
declare owner uuid:=auth.uid(); project text; epoch bigint; ref jsonb; source public.user_narrator_source%rowtype;
  saved public.user_lifetime_continuity%rowtype; last_sequence bigint:=0;
begin
  if owner is null then raise exception 'authenticated owner required'; end if;
  select project_id into project from public.user_lifetime_conversation where user_id=owner and conversation_id=p_conversation_id;
  if not found then raise exception 'conversation unavailable'; end if;
  select policy_epoch into epoch from public.user_memoir_project where user_id=owner and project_id=project for update;
  if epoch is distinct from p_policy_epoch then raise exception 'stale policy' using errcode='PT409'; end if;
  perform 1 from public.user_agent_turn_lease where user_id=owner and lease_token=p_lease_token and expires_at>clock_timestamp() for update;
  if not found then raise exception 'valid turn lease required' using errcode='PT409'; end if;
  if p_data is null or jsonb_typeof(p_data)<>'object'
     or exists(select 1 from jsonb_object_keys(p_data) k where k not in ('text','assertion','uncertainty','source_refs'))
     or jsonb_typeof(p_data->'text') is distinct from 'string' or length(p_data->>'text') not between 1 and 2000
     or coalesce(p_data->>'assertion','') not in ('asserted','inferred')
     or (p_data->'uncertainty' is not null and p_data->'uncertainty'<>'null'::jsonb and
         (jsonb_typeof(p_data->'uncertainty')<>'string' or length(p_data->>'uncertainty')>2000))
     or jsonb_typeof(p_data->'source_refs') is distinct from 'array' then raise exception 'invalid continuity'; end if;
  if jsonb_array_length(p_data->'source_refs') not between 1 and 32 then raise exception 'bounded evidence required'; end if;
  for ref in select value from jsonb_array_elements(p_data->'source_refs') loop
    if jsonb_typeof(ref) is distinct from 'object' then raise exception 'evidence object required'; end if;
    if not (ref ?& array['source_id','version','char_start','char_end','quote'])
      or exists(select 1 from jsonb_object_keys(ref) k where k not in ('source_id','version','char_start','char_end','quote'))
      or jsonb_typeof(ref->'source_id') is distinct from 'string'
      or jsonb_typeof(ref->'version') is distinct from 'number' or coalesce(ref->>'version','') !~ '^[1-9][0-9]*$'
      or jsonb_typeof(ref->'char_start') is distinct from 'number' or coalesce(ref->>'char_start','') !~ '^[0-9]+$'
      or jsonb_typeof(ref->'char_end') is distinct from 'number' or coalesce(ref->>'char_end','') !~ '^[1-9][0-9]*$'
      or jsonb_typeof(ref->'quote') is distinct from 'string' or length(ref->>'quote') not between 1 and 100000
      then raise exception 'typed exact evidence required'; end if;
    select * into source from public.user_narrator_source where user_id=owner and project_id=project
      and id=(ref->>'source_id')::uuid and version=(ref->>'version')::bigint and status='active';
    if not found or (ref->>'char_start')::integer<0 or (ref->>'char_end')::integer<=(ref->>'char_start')::integer
      or (ref->>'char_end')::integer>length(source.text)
      or substring(source.text from (ref->>'char_start')::integer+1 for (ref->>'char_end')::integer-(ref->>'char_start')::integer)
         is distinct from ref->>'quote' then raise exception 'invalid source evidence'; end if;
    if p_kind in ('excluded_topic','paused_topic') and not exists(
      select 1 from public.user_lifetime_source_policy_receipt r
      cross join lateral jsonb_array_elements(r.review->'output'->'restrictions') item
      where r.user_id=owner and r.project_id=project and r.source_id=source.id and r.source_version=source.version
        and item->>'kind'=p_kind and item->>'quote'=ref->>'quote'
        and item->'char_start'=ref->'char_start' and item->'char_end'=ref->'char_end'
        and p_data->>'assertion'='asserted' and p_data->>'text'=ref->>'quote') then
      raise exception 'completed restrictive policy review required' using errcode='42501';
    end if;
    last_sequence:=greatest(last_sequence,source.sequence);
    if not (ref ?& array['source_id','version','char_start','char_end','quote']) then raise exception 'complete evidence required'; end if;
  end loop;
  if p_expected_revision is null or p_expected_revision<0 then raise exception 'revision required'; end if;
  insert into public.user_lifetime_continuity(user_id,conversation_id,record_id,kind,revision,policy_epoch,data,last_source_sequence)
    select owner,p_conversation_id,p_record_id,p_kind,1,epoch,p_data,last_sequence where p_expected_revision=0
    on conflict do nothing returning * into saved;
  if not found then
    update public.user_lifetime_continuity set kind=p_kind,revision=revision+1,policy_epoch=epoch,data=p_data,last_source_sequence=last_sequence
      where user_id=owner and conversation_id=p_conversation_id and record_id=p_record_id and revision=p_expected_revision returning * into saved;
    if not found then raise exception 'continuity revision conflict' using errcode='PT409'; end if;
  end if;
  return to_jsonb(saved)-'user_id'-'conversation_id'-'last_source_sequence';
end;
$memoir$;

CREATE FUNCTION public.save_lifetime_interview_plan(p_snapshot_fence jsonb, p_project_id text, p_client_turn_id uuid, p_plan jsonb, p_associations jsonb, p_lease_token uuid, p_reply text DEFAULT NULL::text, p_response_photo_ids jsonb DEFAULT '[]'::jsonb, p_thread_id text DEFAULT NULL::text, p_plan_revision bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 return public.save_lifetime_interview_plan_core(p_snapshot_fence,p_project_id,p_client_turn_id,p_plan,
   p_associations,p_lease_token,p_reply,p_response_photo_ids,p_thread_id,p_plan_revision);
end
$$;

CREATE FUNCTION public.save_lifetime_interview_plan_core(p_snapshot_fence jsonb, p_project_id text, p_client_turn_id uuid, p_plan jsonb, p_associations jsonb, p_lease_token uuid, p_reply text DEFAULT NULL::text, p_response_photo_ids jsonb DEFAULT '[]'::jsonb, p_thread_id text DEFAULT NULL::text, p_plan_revision bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_owner uuid:=auth.uid(); project public.user_memoir_project%rowtype; turn public.user_interview_turn%rowtype;
  candidate jsonb; context jsonb; proposal jsonb; evidence jsonb; current_source public.user_narrator_source%rowtype;
  inserted integer; changed boolean:=false; response_cards jsonb:='[]'; photo_identifier text; resolution jsonb; conversation uuid;
  disposition_name text;
begin
  if v_owner is null then raise exception 'authenticated user required' using errcode='42501'; end if;
  select * into project from public.user_memoir_project where user_id=v_owner and project_id=p_project_id for update;
  if p_snapshot_fence is not null then
    if p_snapshot_fence->'identity'->>'project_id' is distinct from p_project_id
      or p_snapshot_fence->'identity'->>'owner_id' is distinct from v_owner::text
      or p_snapshot_fence->>'lease_token' is distinct from p_lease_token::text then
      raise exception 'canonical reply scope mismatch' using errcode='42501';end if;
    perform public.lock_lifetime_publication(p_snapshot_fence);
  end if;

  perform 1 from public.user_agent_turn_lease where user_id=v_owner and lease_token=p_lease_token and expires_at>clock_timestamp() for update;
  if not found then raise exception 'agent turn lease lost' using errcode='PT409'; end if;
  select * into turn from public.user_interview_turn where user_id=v_owner and project_id=p_project_id and client_turn_id=p_client_turn_id;
  if not found or turn.sequence is distinct from project.interview_sequence or (p_snapshot_fence is null and turn.source_sequence is distinct from project.source_sequence) or
    (p_snapshot_fence is null and turn.policy_epoch is distinct from project.policy_epoch) then raise exception 'stale interview turn' using errcode='PT409'; end if;
  if turn.source_id is not null and not exists(select 1 from public.user_narrator_source where user_id=v_owner and project_id=p_project_id
      and id=turn.source_id and version=turn.source_version and status='active') then raise exception 'stale interview turn' using errcode='PT409'; end if;
  if turn.collector is not null then
    return public.interview_turn_record(turn) || public.read_user_interview_context(p_project_id);
  end if;
  if p_reply is not null and (length(btrim(p_reply)) not between 1 and 100000 or length(coalesce(p_thread_id,'')) not between 1 and 1000) then
    raise exception 'invalid saved collector reply' using errcode='22023'; end if;
  if jsonb_typeof(p_response_photo_ids) is distinct from 'array' or jsonb_array_length(p_response_photo_ids)>5 then
    raise exception 'invalid response photo selection' using errcode='22023'; end if;
  for photo_identifier in select distinct value from jsonb_array_elements_text(p_response_photo_ids) loop
    if not public.interview_photo_available(v_owner,p_project_id,photo_identifier) then
      raise exception 'response photo unavailable' using errcode='42501'; end if;
    response_cards:=response_cards || (select jsonb_build_array(p) from public.user_interview_turn t,
      jsonb_array_elements(t.photo_context) p where t.user_id=v_owner and t.project_id=p_project_id and p->>'photo_id'=photo_identifier
      order by t.sequence desc limit 1);
  end loop;
  if jsonb_typeof(p_plan) is distinct from 'object' or octet_length(p_plan::text)>32000 or
    jsonb_typeof(p_plan->'candidates') is distinct from 'array' or jsonb_array_length(p_plan->'candidates')>5 or
    exists(select 1 from jsonb_object_keys(p_plan) k where k not in ('candidates','chosen_id','active_event_id','work','resolved_questions','deferred_questions')) or
    jsonb_typeof(p_associations) is distinct from 'array' or jsonb_array_length(p_associations)>20 or
    octet_length(p_associations::text)>32000 then raise exception 'invalid interview plan' using errcode='22023'; end if;
  for disposition_name in select unnest(array['resolved_questions','deferred_questions']) loop
  if p_plan ? disposition_name then
    if jsonb_typeof(p_plan->disposition_name) is distinct from 'array' or jsonb_array_length(p_plan->disposition_name)>5
      or (select count(*)<>count(distinct r->>'question_id') from jsonb_array_elements(p_plan->disposition_name) r) then
      raise exception 'invalid question resolutions' using errcode='22023';end if;
    select conversation_id into conversation from public.user_lifetime_conversation where user_id=v_owner and project_id=p_project_id;
    context:=public.read_lifetime_interview_context(conversation);
    for resolution in select * from jsonb_array_elements(p_plan->disposition_name) loop
      if jsonb_typeof(resolution) is distinct from 'object' or not(resolution ?& array[
          'question_id','source_id','source_version','char_start','char_end','quote'])
        or jsonb_typeof(resolution->'question_id') is distinct from 'string'
        or jsonb_typeof(resolution->'source_id') is distinct from 'string'
        or jsonb_typeof(resolution->'quote') is distinct from 'string'
        or jsonb_typeof(resolution->'source_version') is distinct from 'number'
        or jsonb_typeof(resolution->'char_start') is distinct from 'number'
        or jsonb_typeof(resolution->'char_end') is distinct from 'number'
        or exists(select 1 from jsonb_object_keys(resolution) k where k not in (
          'question_id','source_id','source_version','char_start','char_end','quote'))
        or resolution->>'question_id' is not distinct from p_plan->>'chosen_id'
        or (disposition_name='deferred_questions' and exists(select 1
          from jsonb_array_elements(coalesce(p_plan->'resolved_questions','[]')) answered
          where answered->>'question_id'=resolution->>'question_id'))
        or not exists(select 1 from (
          select q->>'id' id from jsonb_array_elements(public.read_lifetime_prepared_questions(conversation)) q
          union all
          select q->>'id' from jsonb_array_elements(coalesce(public.read_lifetime_strategy_context_at(conversation,p_plan_revision)->'plan'->'candidates','[]')) q
        ) queued where queued.id=resolution->>'question_id') then
        raise exception 'question resolution requires a current queued question' using errcode='22023';end if;
      select * into current_source from public.user_narrator_source where user_id=v_owner and project_id=p_project_id
        and id=(resolution->>'source_id')::uuid and version=(resolution->>'source_version')::bigint and status='active'
        and kind in ('narrator_chat','narrator_transcript');
      if not found or length(coalesce(resolution->>'quote','')) not between 1 and 512
        or (disposition_name='deferred_questions' and current_source.id is distinct from turn.source_id)
        or (resolution->>'char_start')::integer<0 or (resolution->>'char_end')::integer>length(current_source.text)
        or (resolution->>'char_end')::integer-(resolution->>'char_start')::integer<>length(resolution->>'quote')
        or substring(current_source.text from (resolution->>'char_start')::integer+1
          for (resolution->>'char_end')::integer-(resolution->>'char_start')::integer) is distinct from resolution->>'quote'
        or (current_source.id is distinct from turn.source_id and not exists(select 1 from jsonb_array_elements(
          context->'recent_dialogue') pair where pair->'response'->>'id'=current_source.id::text
          and pair->'response'->>'complete'='true')) then
        raise exception 'question resolution requires an exact narrator answer span' using errcode='22023';end if;
    end loop;
  end if;
  end loop;
  if p_plan ? 'work' then
    if jsonb_typeof(p_plan->'work') is distinct from 'object' or
      (p_plan->'work'->>'mode') is null or (p_plan->'work'->>'mode') not in ('reply_only','extract') or
      exists(select 1 from jsonb_object_keys(p_plan->'work') k where k not in ('mode','name')) or
      not (p_plan->'work' ? 'name') or jsonb_typeof(p_plan->'work'->'name') not in ('string','null') or
      length(coalesce(p_plan->'work'->>'name',''))>120 then
      raise exception 'invalid interview work plan' using errcode='22023'; end if;
    if p_plan->'work'->>'mode'='reply_only' then
      -- Prior narrator history determines opening_turn in collector validation.
      -- A project's first turn can belong to a returning storyteller.
      if jsonb_array_length(p_associations)>0 or jsonb_array_length(p_response_photo_ids)>0 or
        jsonb_array_length(turn.photo_context)>0 then
        raise exception 'reply-only work cannot discard accepted photo context' using errcode='22023'; end if;
      if p_plan->'work'->>'name' is not null then
        select * into current_source from public.user_narrator_source where user_id=v_owner and project_id=p_project_id
          and id=turn.source_id and version=turn.source_version and status='active';
        if not found or length(btrim(p_plan->'work'->>'name'))=0 or
          position((p_plan->'work'->>'name') in current_source.text)=0 then
          raise exception 'opening name requires exact narrator wording' using errcode='22023'; end if;
      end if;
    elsif p_plan->'work'->>'name' is not null then
      raise exception 'story profile clues belong to normal extraction' using errcode='22023'; end if;
  end if;

  if (select count(*)<>count(distinct c->>'id') from jsonb_array_elements(p_plan->'candidates') c) or
    (jsonb_array_length(p_plan->'candidates')>0 and not exists(select 1 from jsonb_array_elements(p_plan->'candidates') c where c->>'id'=p_plan->>'chosen_id')) or
    (jsonb_array_length(p_plan->'candidates')=0 and p_plan->>'chosen_id' is not null) then
    raise exception 'invalid interview plan selection' using errcode='22023'; end if;
  if p_plan->>'active_event_id' is not null and not exists(select 1 from public.user_memory_event
    where user_id=v_owner and project_id=p_project_id and id=p_plan->>'active_event_id' and status='active') then
    raise exception 'active event unavailable' using errcode='42501'; end if;
  for candidate in select value from jsonb_array_elements(p_plan->'candidates') loop
    context:=coalesce(candidate->'context','{}');
    if jsonb_typeof(candidate) is distinct from 'object' or
      jsonb_typeof(candidate->'order') is distinct from 'number' or
      jsonb_typeof(candidate->'question') is distinct from 'string' or
      exists(select 1 from jsonb_object_keys(candidate) k where k not in ('id','question','context','order','bridge')) or length(coalesce(candidate->>'id','')) not between 1 and 128 or
      length(public.lifetime_question_text(coalesce(candidate->>'question',''))) not between 1 and 2000 or jsonb_typeof(context) is distinct from 'object' or
      length(coalesce(candidate->>'bridge',''))>2000 or
      exists(select 1 from jsonb_object_keys(context) k where k not in ('event_id','photo_id','life_stage','year','historical_clue_id','evidence')) or (candidate->>'order')::integer not between 0 and 100 then
      raise exception 'invalid interview plan candidate' using errcode='22023'; end if;
    if coalesce(context->'evidence','null')<>'null'::jsonb then
      evidence:=context->'evidence';
      if jsonb_typeof(evidence) is distinct from 'object'
        or exists(select 1 from jsonb_object_keys(evidence) k where k not in ('source_id','version','quote','char_start','char_end','attribution'))
        or jsonb_typeof(evidence->'source_id') is distinct from 'string' or jsonb_typeof(evidence->'version') is distinct from 'number'
        or jsonb_typeof(evidence->'quote') is distinct from 'string' or length(evidence->>'quote') not between 1 and 2000
        or jsonb_typeof(evidence->'char_start') is distinct from 'number' or jsonb_typeof(evidence->'char_end') is distinct from 'number'
        or (evidence ? 'attribution' and jsonb_typeof(evidence->'attribution') not in ('string','null'))
        or length(coalesce(evidence->>'attribution',''))>200 then
        raise exception 'typed question evidence required' using errcode='22023';end if;
      select * into current_source from public.user_narrator_source where user_id=v_owner and project_id=p_project_id
        and id=(evidence->>'source_id')::uuid and version=(evidence->>'version')::bigint and status='active'
        and kind in ('narrator_chat','narrator_transcript');
      if not found or (evidence->>'char_start')::integer<0 or (evidence->>'char_end')::integer>length(current_source.text)
        or (evidence->>'char_end')::integer-(evidence->>'char_start')::integer<>length(evidence->>'quote')
        or substring(current_source.text from (evidence->>'char_start')::integer+1
          for (evidence->>'char_end')::integer-(evidence->>'char_start')::integer) is distinct from evidence->>'quote' then
        raise exception 'question evidence span must match the referenced passage' using errcode='22023';end if;
      if current_source.id is distinct from turn.source_id or candidate->>'id' ~ '^bq-[0-9a-f]{64}$' then
        select conversation_id into conversation from public.user_lifetime_conversation where user_id=v_owner and project_id=p_project_id;
        if not exists(select 1 from (
          select q->>'source_id' source_id,q->>'source_version' version,q from jsonb_array_elements(public.read_lifetime_prepared_questions(conversation)) q
          union all
          -- Match the same revision A used; a newer optional B plan is not revocation.
          select plan->>'source_id',plan->>'source_version',q from (select public.read_lifetime_strategy_context_at(conversation,p_plan_revision)->'plan' plan) state
            cross join lateral jsonb_array_elements(coalesce(plan->'candidates','[]')) q
        ) supplied where supplied.source_id=evidence->>'source_id' and supplied.version=evidence->>'version'
          and supplied.q->>'quote'=evidence->>'quote' and supplied.q->'char_start'=evidence->'char_start'
          and supplied.q->'char_end'=evidence->'char_end'
          and (candidate->>'id' !~ '^bq-[0-9a-f]{64}$' or supplied.q->>'id'=candidate->>'id')) then
          raise exception 'question candidate cannot change its referenced passage' using errcode='22023';end if;
      end if;
    end if;
    if candidate->>'id' ~ '^bq-[0-9a-f]{64}$' and coalesce(context->'evidence','null')='null'::jsonb then
      select conversation_id into conversation from public.user_lifetime_conversation where user_id=v_owner and project_id=p_project_id;
      if context->>'historical_clue_id' is null or not exists(select 1 from jsonb_array_elements(public.read_lifetime_prepared_questions(conversation)) q
        where q->>'id'=candidate->>'id' and q->>'trigger'='historical_news' and q->>'historical_clue_id'=context->>'historical_clue_id') then
        raise exception 'queued question requires its referenced passage' using errcode='22023';end if;
    end if;
    if context->>'historical_clue_id' is not null then
      if coalesce(context->'evidence','null')<>'null'::jsonb then raise exception 'public context cannot be personal evidence' using errcode='22023';end if;
      if context->>'year' is not null or context->>'life_stage' is not null or context->>'event_id' is not null or context->>'photo_id' is not null
        or (select count(*) from jsonb_array_elements(p_plan->'candidates') c where c->'context'->>'historical_clue_id' is not null)>1
        or (candidate->>'id'=p_plan->>'chosen_id' and p_plan->>'active_event_id' is not null)
        or not exists(select 1 from jsonb_array_elements(public.read_user_historical_news(p_project_id)->'clues') c
          where c->>'id'=context->>'historical_clue_id') then
        raise exception 'historical clue unavailable' using errcode='42501'; end if;
    end if;
    if context->>'event_id' is not null and not exists(select 1 from public.user_memory_event
      where user_id=v_owner and project_id=p_project_id and id=context->>'event_id' and status='active') then
      raise exception 'candidate event unavailable' using errcode='42501'; end if;
    if context->>'life_stage' is not null and not exists(select 1 from public.user_memory_event e where
      e.user_id=v_owner and e.project_id=p_project_id and e.status='active' and e.life_stage=context->>'life_stage') then
      raise exception 'unsupported candidate life stage' using errcode='22023'; end if;
    if context->>'year' is not null and not (
      exists(select 1 from public.user_memory_event e where e.user_id=v_owner and e.project_id=p_project_id and e.status='active'
        and (e.data->'temporal'->>'year_start'=context->>'year' or e.data->'temporal'->>'year_end'=context->>'year'))) then
      raise exception 'unsupported candidate year' using errcode='22023'; end if;
    if context->>'photo_id' is not null and not public.interview_photo_available(v_owner,p_project_id,context->>'photo_id') then
      raise exception 'candidate photo unavailable' using errcode='42501'; end if;
  end loop;
  for proposal in select value from jsonb_array_elements(p_associations) loop
    if turn.source_id is null or proposal->>'source_id' is distinct from turn.source_id::text or
      (proposal->>'source_version')::bigint is distinct from turn.source_version then
      raise exception 'photo evidence must belong to this accepted source' using errcode='42501'; end if;
    if not public.interview_photo_available(v_owner,p_project_id,proposal->>'photo_id') then
      raise exception 'photo unavailable' using errcode='42501'; end if;
    -- A deferred cue may gain its FIRST link from a later accepted source.
    -- Cue authority is scoped, lifecycle-current and fenced by any explicit
    -- unlink. Uploading alone or retaining a withdrawn snapshot is not enough.
    if not public.interview_photo_available(v_owner,p_project_id,proposal->>'photo_id',true) and
      not exists(select 1 from public.user_interview_photo_link l join public.user_narrator_source original
        on original.user_id=l.user_id and original.project_id=l.project_id and original.id=l.source_id
        where l.user_id=v_owner and l.project_id=p_project_id and l.photo_id=proposal->>'photo_id'
          and l.status='confirmed' and l.event_id=proposal->>'event_id'
          and original.status='active' and original.version=l.source_version) then
      raise exception 'photo is not accepted or supported active event context' using errcode='42501'; end if;
    evidence:=jsonb_build_object('source_id',proposal->>'source_id','version',proposal->'source_version','quote',proposal->>'quote');
    perform public.validate_memory_evidence(v_owner,p_project_id,evidence);
    if proposal->>'event_id' is not null and not exists(select 1 from public.user_memory_event where user_id=v_owner and project_id=p_project_id
      and id=proposal->>'event_id' and status='active') then raise exception 'photo event unavailable' using errcode='42501'; end if;
    -- visual_derived requires a future verified image-inspection path. Current
    -- collector sees metadata, never pixels: fail closed on claimed sight.
    if proposal->>'provenance' is null or proposal->>'provenance' not in ('narrator','narrator_metadata') then
      raise exception 'unsupported photo description provenance' using errcode='22023'; end if;
    insert into public.user_interview_photo_link(user_id,project_id,photo_id,intended_event_id,source_id,source_version,quote,description,provenance)
      values(v_owner,p_project_id,proposal->>'photo_id',proposal->>'event_id',turn.source_id,turn.source_version,
        proposal->>'quote',proposal->>'description',proposal->>'provenance') on conflict do nothing;
    get diagnostics inserted=row_count; changed:=changed or inserted>0;
  end loop;
  if changed then perform public.invalidate_interview_photo_projection(v_owner,p_project_id,false); end if;
  perform public.reconcile_interview_photo_links(v_owner,p_project_id);
  insert into public.user_interview_plan(user_id,project_id,client_turn_id,sequence,plan)
    values(v_owner,p_project_id,p_client_turn_id,turn.sequence,p_plan)
    on conflict(user_id,project_id) do update set client_turn_id=excluded.client_turn_id,sequence=excluded.sequence,
      revision=public.user_interview_plan.revision+1,plan=excluded.plan;
  update public.user_interview_turn set collector=case when p_reply is null then null else jsonb_build_object(
    'plan',p_plan,'reply',p_reply,'thread_id',p_thread_id,'response_photos',response_cards,
    'historical_context',(select public.historical_news_public(c.evidence)
       from public.user_historical_news_clue c, jsonb_array_elements(p_plan->'candidates') q
       where c.user_id=v_owner and c.project_id=p_project_id and c.id=q->'context'->>'historical_clue_id' and q->>'id'=p_plan->>'chosen_id')) end, policy_epoch=(select policy_epoch from public.user_memoir_project where user_id=v_owner and project_id=p_project_id)
    where user_id=v_owner and project_id=p_project_id and client_turn_id=p_client_turn_id;
  -- Once presented, do not ask this cue again. Its immutable cited reply
  -- remains replayable; later narration stays exact original testimony.
  update public.user_historical_news_clue set status='used' where user_id=v_owner and project_id=p_project_id and id=(
    select c->'context'->>'historical_clue_id' from jsonb_array_elements(p_plan->'candidates') c where c->>'id'=p_plan->>'chosen_id');
  if not exists(select 1 from public.user_agent_turn_lease where user_id=v_owner and lease_token=p_lease_token and expires_at>clock_timestamp()) then
    raise exception 'agent turn lease lost' using errcode='PT409'; end if;
  return public.read_user_interview_turn(p_project_id,p_client_turn_id) || public.read_user_interview_context(p_project_id);
end $$;

CREATE FUNCTION public.save_memoir_checkpoint(p_lane_id uuid, p_token uuid, p_key text, p_kind text, p_value jsonb, p_page_digest text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare page jsonb; sources jsonb;events jsonb; result boolean;
begin
 page:=public.read_lifetime_memoir_lane_page(p_lane_id,p_token);
 result:=public.save_memoir_checkpoint_before_batches(p_lane_id,p_token,p_key,p_kind,p_value,p_page_digest);
 if page->'batch' is not null then
  select coalesce(jsonb_agg(distinct jsonb_build_object('id',s->'id','version',s->'version')),'[]') into sources
   from jsonb_array_elements((page->'batch'->'sources')||(page->'batch'->'new_messages')) s;
  select coalesce(jsonb_agg(jsonb_build_object('id',e->'id','revision',e->'revision')),'[]') into events from jsonb_array_elements(page->'batch'->'events') e;
  update public.user_memoir_checkpoint set source_manifest=sources,event_manifest=events where lane_id=p_lane_id and key=p_key;
 end if;
 return result;
end $$;

CREATE FUNCTION public.save_memoir_checkpoint_before_batches(p_lane_id uuid, p_token uuid, p_key text, p_kind text, p_value jsonb, p_page_digest text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $memoir$
declare page jsonb; sources jsonb; events jsonb;
begin
 if not exists(select 1 from public.user_memoir_lane l join public.user_lifetime_conversation c
   on c.user_id=l.user_id and c.project_id=l.project_id where l.id=p_lane_id) then
   return public.save_memoir_checkpoint_before_lifetime_pages(p_lane_id,p_token,p_key,p_kind,p_value);
 end if;
 page:=public.read_lifetime_memoir_lane_page(p_lane_id,p_token);
 if p_page_digest is distinct from page->>'page_digest' then raise exception 'stale phase checkpoint input' using errcode='PT409';end if;
 if page->>'skill'<>'composer' or (page->>'complete')::boolean or page->'source'='null'::jsonb
   or p_key !~ '^[a-f0-9]{64}$' or p_kind not in ('prepare','compose') or jsonb_typeof(p_value) is distinct from 'object'
   or octet_length(p_value::text)>500000 then raise exception 'invalid bounded phase checkpoint' using errcode='22023';end if;
 sources:=jsonb_build_array(jsonb_build_object('id',page->'source'->>'id','version',page->'source'->'version'));
 events:=jsonb_build_array(jsonb_build_object('id',page->'partition'->>'id','revision',page->'partition'->'revision'));
 insert into public.user_memoir_checkpoint(lane_id,key,kind,value,source_manifest,event_manifest,
   lifetime_snapshot_id,lifetime_page,lifetime_policy,lifetime_preference,lifetime_input_digest)
 values(p_lane_id,p_key,p_kind,p_value,sources,events,(page->>'snapshot_id')::uuid,(page->>'page_number')::bigint,
   (page->>'policy_epoch')::bigint,(page->>'preference_revision')::bigint,(page->>'input_digest'))
 on conflict(lane_id,key) do update set value=excluded.value,source_manifest=excluded.source_manifest,event_manifest=excluded.event_manifest,
   lifetime_snapshot_id=excluded.lifetime_snapshot_id,lifetime_page=excluded.lifetime_page,lifetime_policy=excluded.lifetime_policy,
   lifetime_preference=excluded.lifetime_preference,lifetime_input_digest=excluded.lifetime_input_digest,created_at=clock_timestamp();
 return true;
end $memoir$;

CREATE FUNCTION public.save_memoir_checkpoint_before_lifetime_pages(p_lane_id uuid, p_token uuid, p_key text, p_kind text, p_value jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $memoir$
declare lane public.user_memoir_lane%rowtype;
begin
  select * into lane from public.user_memoir_lane where id=p_lane_id for update;
  if not found or lane.token is null or lane.token is distinct from p_token or lane.lease_until<=clock_timestamp() or lane.run_deadline<=clock_timestamp()
     or lane.active_policy is distinct from (select policy_epoch from public.user_memoir_project where user_id=lane.user_id and project_id=lane.project_id) then return false; end if;
  if p_key !~ '^[a-f0-9]{64}$' or p_kind not in ('prepare','compose') or pg_catalog.jsonb_typeof(p_value) is distinct from 'object'
    or length(p_value::text)>500000 then raise exception 'invalid execution checkpoint' using errcode='22023'; end if;
  insert into public.user_memoir_checkpoint(lane_id,key,kind,value,source_manifest,event_manifest)
    values(p_lane_id,p_key,p_kind,p_value,lane.active_manifest,lane.active_events)
    on conflict(lane_id,key) do update set value=excluded.value,source_manifest=excluded.source_manifest,event_manifest=excluded.event_manifest,created_at=clock_timestamp();
  return true;
end $memoir$;

CREATE FUNCTION public.save_user_interview_plan(p_project_id text, p_client_turn_id uuid, p_plan jsonb, p_associations jsonb, p_lease_token uuid, p_reply text DEFAULT NULL::text, p_response_photo_ids jsonb DEFAULT '[]'::jsonb, p_thread_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select public.save_lifetime_interview_plan(null,p_project_id,p_client_turn_id,p_plan,p_associations,p_lease_token,p_reply,p_response_photo_ids,p_thread_id);
$$;

CREATE FUNCTION public.schedule_lifetime_profile_round() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare frontier bigint;
begin
 if public.lifetime_profile_due_round(new.ordinal)<>new.ordinal or not exists(
   select 1 from public.user_lifetime_conversation where user_id=new.user_id and project_id=new.project_id) then return new;end if;
 select source_sequence into frontier from public.user_memoir_project where user_id=new.user_id and project_id=new.project_id for update;
 insert into public.user_lifetime_profile_progress(user_id,project_id,requested_round,requested_frontier)
 values(new.user_id,new.project_id,new.ordinal,frontier)
 on conflict(user_id,project_id) do update set
   requested_frontier=case when excluded.requested_round>user_lifetime_profile_progress.requested_round
     then excluded.requested_frontier else user_lifetime_profile_progress.requested_frontier end,
   requested_round=greatest(user_lifetime_profile_progress.requested_round,excluded.requested_round);
 insert into public.user_memoir_lane(user_id,project_id,skill,pending,target_source,target_event)
 select new.user_id,new.project_id,'timeline',true,source_sequence,event_sequence from public.user_memoir_project
 where user_id=new.user_id and project_id=new.project_id
 on conflict(user_id,project_id,skill) do update set pending=true,attempts=0,error=null,available_at=clock_timestamp(),
   target_source=greatest(user_memoir_lane.target_source,excluded.target_source);
 return new;
end $$;

CREATE FUNCTION public.set_lifetime_collection(p_project_id text, p_expected_revision bigint, p_periods jsonb, p_ready boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare owner uuid:=auth.uid(); project public.user_memoir_project%rowtype; identity public.user_lifetime_conversation%rowtype;
 doc public.user_lifetime_collection%rowtype; item record; ids uuid[]; manifest jsonb; fingerprint text;
begin
 if owner is null then raise exception 'authenticated owner required' using errcode='42501';end if;
 select * into project from public.user_memoir_project where user_id=owner and project_id=p_project_id for update;
 perform 1 from public.user_profile where user_id=owner for share;
 select * into identity from public.user_lifetime_conversation where user_id=owner and project_id=p_project_id for share;
 if not found then raise exception 'collection unavailable' using errcode='42501';end if;
 select * into doc from public.user_lifetime_collection where user_id=owner and project_id=p_project_id for update;
 if p_expected_revision is null or coalesce(doc.revision,0)<>p_expected_revision then raise exception 'collection revision conflict' using errcode='PT409';end if;
 if p_ready is null or jsonb_typeof(p_periods) is distinct from 'object' or octet_length(p_periods::text)>200000 then raise exception 'invalid collection periods';end if;
 for item in select key,value from jsonb_each(p_periods) loop
  if item.key not in ('baby','childhood','adolescence','young_adulthood','midlife','later_life')
   or jsonb_typeof(item.value) is distinct from 'object' or item.value- array['status','memory_ids','note']<>'{}'::jsonb
   or jsonb_typeof(item.value->'status') is distinct from 'string' or item.value->>'status' not in ('recorded','skipped','not_applicable')
   or jsonb_typeof(item.value->'memory_ids') is distinct from 'array' or jsonb_array_length(item.value->'memory_ids')>1000
   or jsonb_typeof(item.value->'note') is distinct from 'string' or length(item.value->>'note')>500
   or (item.value->>'status'='recorded' and jsonb_array_length(item.value->'memory_ids')=0)
   or (item.value->>'status'<>'recorded' and (length(trim(item.value->>'note'))=0 or jsonb_array_length(item.value->'memory_ids')<>0)) then
   raise exception 'invalid collection period';end if;
 end loop;
 select coalesce(array_agg(selected order by first_position),'{}') into ids from (
  select v.value::uuid selected,min(array_position(array['baby','childhood','adolescence','young_adulthood','midlife','later_life'],p.key)*1001+v.n) first_position
  from jsonb_each(p_periods)p cross join lateral jsonb_array_elements_text(p.value->'memory_ids') with ordinality v(value,n)
  group by v.value::uuid) ordered_selection;
 if cardinality(ids)>1000 or (p_ready and ((select count(*) from jsonb_each(p_periods))<>6 or cardinality(ids)=0)) then
  raise exception 'collection selection limit or readiness incomplete';end if;
 if exists(select 1 from unnest(ids) selected where not exists(select 1 from public.user_narrator_source s
   where s.user_id=owner and s.project_id=p_project_id and s.id=selected and s.status='active' and s.kind in ('narrator_chat','narrator_transcript'))) then
  raise exception 'collection references unavailable narrator evidence' using errcode='PT409';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'version',s.version,'hash',encode(sha256(convert_to(s.text,'UTF8')),'hex')) order by n),'[]')
  into manifest from unnest(ids) with ordinality a(id,n) join public.user_narrator_source s on s.id=a.id and s.user_id=owner and s.project_id=p_project_id;
 fingerprint:=encode(sha256(convert_to(jsonb_build_object('sources',manifest,'source_revision',project.source_sequence)::text,'UTF8')),'hex');
 insert into public.user_lifetime_collection(user_id,project_id,revision,periods,ready,source_revision,policy_epoch,preference_revision,source_fingerprint)
 values(owner,p_project_id,p_expected_revision+1,p_periods,p_ready,project.source_sequence,project.policy_epoch,identity.preference_revision,fingerprint)
 on conflict(user_id,project_id) do update set revision=excluded.revision,periods=excluded.periods,ready=excluded.ready,
 source_revision=excluded.source_revision,policy_epoch=excluded.policy_epoch,preference_revision=excluded.preference_revision,source_fingerprint=excluded.source_fingerprint;
 delete from public.user_lifetime_collection_selection where user_id=owner and project_id=p_project_id;
 insert into public.user_lifetime_collection_selection(user_id,project_id,source_id,source_version,source_hash,ordinal)
 select owner,p_project_id,(v->>'id')::uuid,(v->>'version')::bigint,v->>'hash',n::integer
 from jsonb_array_elements(manifest) with ordinality m(v,n);
 return public.read_lifetime_collection_selection(p_project_id);
end $$;

CREATE FUNCTION public.set_lifetime_collection_job_retry(p_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare job public.user_lifetime_collection_job%rowtype;
begin
 select * into job from public.user_lifetime_collection_job where id=p_job_id and user_id=auth.uid();
 if not found then raise exception 'collection job unavailable' using errcode='42501';end if;
 if job.kind='BuildOutline' then perform 1 from auth.users where id=job.user_id for share;end if;
 perform 1 from public.user_memoir_project where user_id=job.user_id and project_id=job.project_id for share;
 perform 1 from public.user_profile where user_id=job.user_id for share;
 if not found then perform pg_advisory_xact_lock_shared(hashtextextended('memoir-profile:'||job.user_id::text,0));end if;
 perform 1 from public.user_lifetime_conversation where user_id=job.user_id and project_id=job.project_id for share;
 perform 1 from public.user_lifetime_collection where user_id=job.user_id and project_id=job.project_id for share;
 if job.kind='BuildOutline' then
  perform 1 from public.story_entitlement where user_id=job.user_id for share;
 end if;
 select * into job from public.user_lifetime_collection_job where id=p_job_id for update;
 if job.state='FAILED' and job.error='BOUNDED_JOB_RETRY' then
  update public.user_lifetime_collection_job set state='QUEUED',attempts=0,error=null,token=null,lease_until=null where id=job.id;
 end if;
 -- Invalid source/privacy/payment authority rolls back the retry, too.
 perform public.lock_lifetime_collection_job(job.id);
 return public.read_lifetime_collection_job(job.id,null,8);
end $$;

CREATE FUNCTION public.set_lifetime_draft_edition(p_project_id text, p_locale text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare owner uuid:=auth.uid(); lane public.user_memoir_lane%rowtype;
begin
 if owner is null then raise exception 'authenticated owner required' using errcode='42501';end if;
 if p_locale is null or p_locale not in ('en-AU','zh-CN') then raise exception 'invalid memoir edition' using errcode='22023';end if;
 perform 1 from public.user_memoir_project where user_id=owner and project_id=p_project_id for update;
 perform 1 from public.user_profile where user_id=owner for share;
 perform 1 from public.user_lifetime_conversation where user_id=owner and project_id=p_project_id for share;
 if not found then raise exception 'canonical conversation unavailable' using errcode='42501';end if;
 select * into lane from public.user_memoir_lane where user_id=owner and project_id=p_project_id and skill='composer' for update;
 if lane.id is null then return jsonb_build_object('status','pending','locale',p_locale,'error','LIFETIME_DRAFT_NOT_ELIGIBLE');end if;
 if lane.token is not null and lane.lease_until>clock_timestamp() and lane.run_deadline>clock_timestamp() then
   raise exception 'composer edition currently running' using errcode='PT409';end if;
 update public.user_lifetime_lane_snapshot set state='stale' where lane_id=lane.id and state='pending' and locale<>p_locale;
 update public.user_memoir_lane set locale=p_locale,pending=true,attempts=0,error=null,available_at=clock_timestamp(),
   token=null,lease_until=null,run_deadline=null,active_manifest='[]',active_events='[]' where id=lane.id;
 update public.user_memoir_project set draft_revision=draft_revision+1 where user_id=owner and project_id=p_project_id;
 return jsonb_build_object('status','pending','locale',p_locale,'publication_approved',false);
end $$;

CREATE FUNCTION public.set_lifetime_event_correction(p_project_id text, p_event_id text, p_expected_revision bigint, p_patch jsonb, p_statement text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare previous text;
begin
 if not exists(select 1 from public.user_lifetime_conversation where user_id=auth.uid() and project_id=p_project_id)
   then raise exception 'canonical conversation unavailable' using errcode='42501';end if;
 previous:=current_setting('memoir.bounded_correction',true);
 perform set_config('memoir.bounded_correction','true',true);
 perform public.correct_user_memory_event(p_project_id,p_event_id,p_expected_revision,p_patch,p_statement);
 perform set_config('memoir.bounded_correction',coalesce(previous,''),true);
 return jsonb_build_object('changed',true);
end $$;

CREATE FUNCTION public.set_lifetime_language(p_fence jsonb, p_language text, p_explicit boolean DEFAULT false) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare owner uuid:=auth.uid(); project text; selected text;
begin
 select project_id into project from public.user_lifetime_conversation where user_id=owner and conversation_id=(p_fence->'identity'->>'conversation_id')::uuid;
 if not found then raise exception 'conversation unavailable'; end if;
 perform 1 from public.user_memoir_project where user_id=owner and project_id=project for update;
 -- Language metadata is selected before starting concurrent source review.
 if exists(select 1 from public.user_lifetime_pending_policy where user_id=owner and project_id=project) then
   perform public.lock_lifetime_draft_reply(p_fence);
 else perform public.lock_lifetime_publication(p_fence);end if;
 if p_language not in ('en-AU','zh-CN') or p_explicit is null then raise exception 'invalid language selection'; end if;
 select profile->>'preferred_language' into selected from public.user_profile where user_id=owner for update;
 if p_explicit or selected is null or selected not in ('en-AU','zh-CN') then
   update public.user_profile set profile=jsonb_set(profile,'{preferred_language}',to_jsonb(p_language)) where user_id=owner;
   selected:=p_language;
 end if;
 return selected;
end $$;

CREATE FUNCTION public.set_lifetime_private_draft_proposal(p_project_id text, p_snapshot_id uuid, p_root_digest text, p_partition_id text, p_expected_proposal_digest text, p_accept boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $memoir$
declare owner uuid:=auth.uid(); project public.user_memoir_project%rowtype; identity public.user_lifetime_conversation%rowtype;
 root public.user_lifetime_lane_snapshot%rowtype; section public.user_lifetime_memoir_section%rowtype;
 pins jsonb; still_pending boolean; next_digest text; current_revision bigint;
begin
 if owner is null or p_accept is null or length(p_partition_id) not between 1 and 512
   or p_root_digest !~ '^[0-9a-f]{64}$' or p_expected_proposal_digest !~ '^[0-9a-f]{64}$' then
   raise exception 'bounded owner proposal decision required' using errcode='22023';end if;
 select * into project from public.user_memoir_project where user_id=owner and project_id=p_project_id for update;
 perform 1 from public.user_profile where user_id=owner for share;
 select * into identity from public.user_lifetime_conversation where user_id=owner and project_id=p_project_id for share;
 if identity.conversation_id is null then raise exception 'canonical conversation unavailable' using errcode='42501';end if;
 select * into root from public.user_lifetime_lane_snapshot where id=p_snapshot_id and user_id=owner and project_id=p_project_id for update;
 if root.id is null or root.state<>'proposed' or root.root_digest is distinct from p_root_digest
   or root.policy_epoch<>project.policy_epoch or root.preference_revision<>identity.preference_revision
   or exists(select 1 from public.user_lifetime_lane_snapshot newer where newer.lane_id=root.lane_id and newer.locale=root.locale
      and newer.state in ('completed','proposed') and newer.created_at>root.created_at) then
   raise exception 'stale memoir proposal root' using errcode='PT409';end if;
 pins:=public.read_lifetime_pinned(identity.conversation_id);
 if (pins->>'privacy_complete')::boolean is distinct from true then raise exception 'privacy maintenance required' using errcode='PT409';end if;
 select * into section from public.user_lifetime_memoir_section where user_id=owner and project_id=p_project_id
   and snapshot_id=root.id and partition_key=p_partition_id for update;
 if section.snapshot_id is null or section.proposal is null
   or encode(sha256(convert_to(section.proposal::text,'UTF8')),'hex') is distinct from p_expected_proposal_digest
   or not exists(select 1 from public.user_memory_event e where e.user_id=owner and e.project_id=p_project_id
      and e.id=section.event_id and e.revision=section.event_revision and e.status='active')
   or not exists(select 1 from public.user_narrator_source n where n.user_id=owner and n.project_id=p_project_id
      and n.id=section.source_id and n.version=section.source_version and n.status='active') then
   raise exception 'stale memoir section proposal' using errcode='PT409';end if;
 select revision into current_revision from public.user_memoir_edition where user_id=owner and project_id=p_project_id and locale=root.locale for update;
 if current_revision is distinct from root.base_revision then raise exception 'manuscript revision changed' using errcode='PT409';end if;
 update public.user_lifetime_memoir_section set bundle=case when p_accept then proposal else bundle end,proposal=null
   where user_id=owner and project_id=p_project_id and snapshot_id=root.id and partition_key=p_partition_id;
 next_digest:=encode(sha256(convert_to(jsonb_build_object('predecessor_digest',root.root_digest,'partition_id',p_partition_id,
   'proposal_digest',p_expected_proposal_digest,'accepted',p_accept)::text,'UTF8')),'hex');
 select exists(select 1 from public.user_lifetime_memoir_section where snapshot_id=root.id and proposal is not null) into still_pending;
 update public.user_lifetime_lane_snapshot set root_digest=next_digest,state=case when still_pending then 'proposed' else 'completed' end where id=root.id;
 if not still_pending then
   update public.user_memoir_edition set revision=revision+1,covered_round=root.round_high_water,source_sequence=root.source_high_water,
     event_sequence=root.event_high_water,completed_milestone=root.milestone where user_id=owner and project_id=p_project_id and locale=root.locale;
   update public.user_memoir_milestone set state='completed',manuscript_revision=root.base_revision+1
     where user_id=owner and project_id=p_project_id and locale=root.locale and milestone<=root.milestone and state='proposed';
 end if;
 return jsonb_build_object('schema_version',1,'status',case when p_accept then 'accepted' else 'rejected' end,'snapshot_id',root.id,
   'root_digest',next_digest,'locale',root.locale,'approval_required',still_pending,'revision',root.base_revision+case when still_pending then 0 else 1 end,
   'publication_approved',false);
end $memoir$;

CREATE FUNCTION public.set_lifetime_profile_settings(p_patch jsonb, p_lease_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
#variable_conflict use_column
declare owner uuid:=auth.uid(); project text; result jsonb; k text; val jsonb; locks jsonb;
 fields text[]:=array['name','birth_year','birth_date_expression','birth_place','childhood_place','avatar_style'];
begin
 select project_id into project from public.user_lifetime_conversation where user_id=owner and product='memoir';
 if not found then raise exception 'mapped conversation required' using errcode='42501';end if;
 if jsonb_typeof(p_patch) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_patch) k
   where k<>all(fields||array['preferred_language','profile_confirm_all','profile_auto_enabled','profile_release_fields']))
   or octet_length(p_patch::text)>4096 then raise exception 'invalid profile settings patch' using errcode='22023';end if;
 perform 1 from public.user_memoir_project where user_id=owner and project_id=project for update;
 insert into public.user_profile(user_id,profile) values(owner,'{}') on conflict do nothing;
 perform 1 from public.user_profile where user_id=owner for update;
 perform 1 from public.user_agent_turn_lease where user_id=owner and lease_token=p_lease_token
   and expires_at>clock_timestamp() for share;
 if not found then raise exception 'valid turn lease required' using errcode='40001';end if;
 foreach k in array array['profile_confirm_all','profile_auto_enabled'] loop
   if p_patch ? k and jsonb_typeof(p_patch->k) is distinct from 'boolean' then
     raise exception 'boolean profile control required' using errcode='22023';end if;
 end loop;
 if p_patch ? 'profile_release_fields' then
   if jsonb_typeof(p_patch->'profile_release_fields') is distinct from 'array'
     or jsonb_array_length(p_patch->'profile_release_fields')>6
     or exists(select 1 from jsonb_array_elements(p_patch->'profile_release_fields') f
       where jsonb_typeof(f)<>'string' or (f#>>'{}')<>all(fields)) then
     raise exception 'invalid profile release fields' using errcode='22023';end if;
 end if;
 foreach k in array fields loop
   if p_patch ? k then update public.user_lifetime_profile_authority set invalidated_fields=array_remove(invalidated_fields,k)
     where user_id=owner;end if;
 end loop;
 result:=public.set_lifetime_profile_settings_before_background_profile(p_patch-array[
   'birth_date_expression','avatar_style','profile_confirm_all','profile_auto_enabled','profile_release_fields'],p_lease_token);
 foreach k in array array['birth_date_expression','avatar_style'] loop
   if not(p_patch ? k) then continue;end if;
   val:=p_patch->k;
   if val<>'null'::jsonb then
     if jsonb_typeof(val)<>'string' or length(btrim(val#>>'{}'))>(case when k='birth_date_expression' then 120 else 160 end) then
       raise exception 'invalid profile text setting' using errcode='22023';end if;
     val:=to_jsonb(btrim(val#>>'{}'));
     if val='""'::jsonb then val:='null';end if;
     if k='avatar_style' and val<>'null'::jsonb and val#>>'{}' not in ('male','female') then
       raise exception 'invalid avatar style' using errcode='22023';end if;
   end if;
   if val='null'::jsonb then result:=result-k;else result:=jsonb_set(result,array[k],val);end if;
 end loop;
 select field_locks into locks from public.user_lifetime_profile_authority where user_id=owner for update;
 for k in select jsonb_array_elements_text(coalesce(p_patch->'profile_release_fields','[]')) loop
   locks:=locks-k;
   if k='name' then update public.user_lifetime_profile_authority set name_released=true where user_id=owner;end if;
 end loop;
 foreach k in array fields loop
   if p_patch ? k or p_patch->'profile_confirm_all'='true'::jsonb then
     locks:=jsonb_set(locks,array[k],'"manual"');
     delete from public.user_lifetime_profile_dependency where user_id=owner and field=k;
     if k='name' then update public.user_lifetime_profile_authority set name_released=false where user_id=owner;end if;
   end if;
 end loop;
 if p_patch->'profile_confirm_all'='true'::jsonb then
   insert into public.user_lifetime_chosen_name(user_id,conversation_id,project_id,chosen_name,authority)
   select owner,c.conversation_id,project,result->>'name','explicit' from public.user_lifetime_conversation c
   where c.user_id=owner and c.project_id=project
   on conflict(user_id) do update set authority='explicit',chosen_name=excluded.chosen_name,source_id=null,source_version=null;
 end if;
 update public.user_lifetime_profile_authority set field_locks=locks,revision=revision+1,
   auto_enabled=coalesce((p_patch->>'profile_auto_enabled')::boolean,auto_enabled),
   manual_complete=case when p_patch->'profile_confirm_all'='true'::jsonb then true
     when p_patch->'profile_auto_enabled'='true'::jsonb then false
     when (select bool_and(coalesce(locks->>f='manual',false)) from unnest(fields) f) then true
     else manual_complete end
 where user_id=owner;
 if p_patch->'profile_auto_enabled'='true'::jsonb then
   update public.user_lifetime_profile_progress set skipped_round=0,active_round=0 where user_id=owner;
 end if;
 update public.user_profile set profile=result where user_id=owner returning profile into result;
 -- Explicit controls may resume already due work, using the same timeline owner.
 update public.user_memoir_lane set pending=true,attempts=0,error=null,available_at=clock_timestamp()
 where user_id=owner and project_id=project and skill='timeline' and exists(
   select 1 from public.user_lifetime_profile_progress where user_id=owner and project_id=project
     and requested_round>greatest(covered_round,skipped_round));
 return result;
end $$;

CREATE FUNCTION public.set_lifetime_profile_settings_before_background_profile(p_patch jsonb, p_lease_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $memoir$
declare owner uuid:=auth.uid(); project text; current_profile jsonb; item record; value jsonb; locale text;
 previous jsonb; next_language jsonb; revision bigint;
begin
 select project_id into project from public.user_lifetime_conversation where user_id=owner and product='memoir';
 if not found then raise exception 'mapped conversation required' using errcode='42501'; end if;
 if pg_catalog.jsonb_typeof(p_patch) is distinct from 'object' or exists(select 1 from pg_catalog.jsonb_object_keys(p_patch) key
   where key not in ('name','preferred_language','birth_year','birth_place','childhood_place')) then
   raise exception 'invalid profile settings patch' using errcode='22023';
 end if;
 perform 1 from public.user_memoir_project where user_id=owner and project_id=project for update;
 insert into public.user_profile(user_id,profile) values(owner,'{}') on conflict do nothing;
 select profile into current_profile from public.user_profile where user_id=owner for update;
 perform 1 from public.user_agent_turn_lease where user_id=owner and lease_token=p_lease_token
   and expires_at>clock_timestamp() for share;
 if not found then raise exception 'valid turn lease required' using errcode='PT409'; end if;
 for item in select * from pg_catalog.jsonb_each(p_patch) loop
   value:=item.value;
   if value<>'null'::jsonb then
     if item.key='birth_year' then
       if pg_catalog.jsonb_typeof(value)<>'number' or value::text !~ '^[0-9]+$'
         or value::text::numeric not between 1800 and extract(year from current_date) then
         raise exception 'invalid birth year' using errcode='22023'; end if;
     else
       if pg_catalog.jsonb_typeof(value)<>'string' then raise exception 'invalid text setting' using errcode='22023'; end if;
       value:=pg_catalog.to_jsonb(pg_catalog.btrim(value#>>'{}'));
       if length(value#>>'{}')>(case when item.key='name' then 120 else 160 end) then
         raise exception 'text setting exceeds limit' using errcode='22023'; end if;
       if value='""'::jsonb then value:='null'::jsonb; end if;
     end if;
   end if;
   if item.key='preferred_language' then
     locale:=value#>>'{}';
     if locale is not null and locale not in ('en-AU','zh-CN') then raise exception 'invalid language setting' using errcode='22023'; end if;
     previous:=current_profile->'conversation_language';
     if pg_catalog.jsonb_typeof(previous) is distinct from 'object' or previous->'version' is distinct from '1'::jsonb
       or previous->'initialized' is distinct from 'true'::jsonb then previous:=null; end if;
     revision:=case when coalesce(previous->>'revision','') ~ '^[0-9]{1,16}$' then (previous->>'revision')::bigint else 0 end;
     if locale is not null then
       next_language:=pg_catalog.jsonb_build_object('version',1,'initialized',true,'revision',revision+1,'locale',locale,'source','explicit',
         'first_reply_locale',previous->'first_reply_locale','first_reply_fallback',previous->'first_reply_fallback','first_reply_id',previous->'first_reply_id');
       current_profile:=pg_catalog.jsonb_set(current_profile,'{conversation_language}',next_language);
     elsif previous is not null then
       next_language:=previous||pg_catalog.jsonb_build_object('revision',revision+1,
         'locale',coalesce(nullif(previous->'first_reply_locale','null'::jsonb),previous->'first_reply_fallback'),'source','first_reply');
       current_profile:=pg_catalog.jsonb_set(current_profile,'{conversation_language}',next_language);
     end if;
   end if;
   if value='null'::jsonb then current_profile:=current_profile-item.key;
   else current_profile:=pg_catalog.jsonb_set(current_profile,array[item.key],value); end if;
 end loop;
 if p_patch ? 'name' then
   insert into public.user_lifetime_chosen_name(user_id,conversation_id,project_id,chosen_name,authority)
   select owner,conversation_id,project,current_profile->>'name','explicit' from public.user_lifetime_conversation where user_id=owner and product='memoir'
   on conflict(user_id) do update set authority='explicit',chosen_name=excluded.chosen_name,source_id=null,source_version=null;
 end if;
 update public.user_profile set profile=current_profile where user_id=owner;
 return current_profile;
end $memoir$;

CREATE FUNCTION public.set_story_game_consent(p_project_id text, p_edition_id uuid, p_expected_digest text, p_expected_revision bigint, p_action text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner uuid:=auth.uid(); edition public.user_formal_memoir_edition%rowtype; head public.user_formal_memoir_head%rowtype;
 epoch bigint; result_status text;
begin
 if owner is null then raise exception 'FORMAL_OWNER_REQUIRED' using errcode='42501';end if;
 select policy_epoch into epoch from public.user_memoir_project where user_id=owner and project_id=p_project_id for update;
 if not found then raise exception 'FORMAL_OWNER_REQUIRED' using errcode='42501';end if;
 if p_action is null or p_action not in ('grant','revoke') then raise exception 'ADAPTATION_ACTION_INVALID' using errcode='22023';end if;
 select * into edition from public.user_formal_memoir_edition where id=p_edition_id and user_id=owner and project_id=p_project_id;
 if not found or edition.digest is distinct from p_expected_digest then
   raise exception 'ADAPTATION_EDITION_MISMATCH' using errcode='PT409';end if;
 select * into head from public.user_formal_memoir_head where user_id=owner and project_id=p_project_id for update;
 if head.consent_revision is distinct from p_expected_revision then raise exception 'ADAPTATION_CONSENT_CHANGED' using errcode='PT409';end if;
 if p_action='grant' then
   if not edition.active or head.edition_id is distinct from edition.id then raise exception 'ADAPTATION_EDITION_STALE' using errcode='PT409';end if;
   perform public.lock_formal_memoir_run(edition.run_id,null,false);
 end if;
 -- Withdrawal is always possible, including after a phase exit or invalidation.
 result_status:=case when p_action='grant' then 'active' else 'revoked' end;
 update public.user_formal_memoir_head set consent_revision=consent_revision+1 where user_id=owner and project_id=p_project_id returning * into head;
 insert into public.user_story_game_consent(edition_id,user_id,project_id,revision,status,policy_epoch)
 values(edition.id,owner,p_project_id,head.consent_revision,result_status,epoch)
 on conflict(edition_id) do update set revision=excluded.revision,status=excluded.status,policy_epoch=excluded.policy_epoch;
 return jsonb_build_object('revision',head.consent_revision,'status',result_status,'edition_id',edition.id);
end $$;

CREATE FUNCTION public.set_ui_locale_preference(p_locale text, p_source text, p_expected_viewer uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_owner uuid := auth.uid();
  v_preference public.user_ui_locale_preference%rowtype;
  v_legacy text;
begin
  if v_owner is null or p_expected_viewer is null or v_owner <> p_expected_viewer then
    raise exception 'authenticated user required' using errcode = '42501';
  end if;
  if p_locale is null or p_locale not in ('en-AU', 'zh-CN') or
     p_source is null or p_source not in ('manual', 'first_reply') then
    raise exception 'invalid UI locale preference' using errcode = '22023';
  end if;

  -- The account row exists even before the first preference. Locking it makes
  -- competing initializations and legacy fallback atomic, without a caller
  -- owner target or advisory-lock collisions. The expected viewer is only
  -- an equality guard against a client session changing before RPC dispatch. Every writer locks this row
  -- first, including manual choices; authenticated anonymous users also have
  -- an auth.users row and use exactly the same path.
  select u.raw_user_meta_data->>'ui_locale' into v_legacy
    from auth.users u where u.id = v_owner for update;
  if not found then
    raise exception 'authenticated user required' using errcode = '42501';
  end if;

  select * into v_preference from public.user_ui_locale_preference
    where user_id = v_owner;
  if found then
    -- All detections after the first established preference are no-ops, even
    -- when their locale differs. A manual choice always has priority.
    if p_source = 'manual' and
       (v_preference.locale is distinct from p_locale or v_preference.source <> 'manual') then
      update public.user_ui_locale_preference
        set locale = p_locale, source = 'manual', revision = revision + 1
        where user_id = v_owner returning * into v_preference;
    end if;
  else
    -- Materialize valid legacy preferences as manual before considering an
    -- inference; explicit UI choices are free to replace the legacy value.
    insert into public.user_ui_locale_preference(user_id, locale, source)
      values (v_owner,
        case when p_source = 'first_reply' and v_legacy in ('en-AU', 'zh-CN')
          then v_legacy else p_locale end,
        case when p_source = 'first_reply' and v_legacy in ('en-AU', 'zh-CN')
          then 'manual' else p_source end)
      returning * into v_preference;
  end if;
  -- Return the effective record, including a winning manual choice, rather
  -- than echoing a detection request that lost the race.
  return jsonb_build_object('locale', v_preference.locale,
    'source', v_preference.source, 'revision', v_preference.revision);
end;
$$;

CREATE FUNCTION public.set_user_historical_news(p_project_id text, p_enabled boolean, p_reject_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if auth.uid() is null or (p_enabled is null and p_reject_id is null) then raise exception 'authenticated preference required' using errcode='42501'; end if;
 perform 1 from public.user_memoir_project where user_id=auth.uid() and project_id=p_project_id for update;
 if not found then raise exception 'project unavailable' using errcode='42501'; end if;
 insert into public.user_historical_news_state(user_id,project_id,enabled) values(auth.uid(),p_project_id,coalesce(p_enabled,(select enabled from public.user_historical_news_state where user_id=auth.uid() and project_id=p_project_id),true))
 on conflict(user_id,project_id) do update set enabled=excluded.enabled,revision=public.user_historical_news_state.revision+1;
 if p_reject_id is not null then
   update public.user_historical_news_clue set status='rejected' where user_id=auth.uid() and project_id=p_project_id and id=p_reject_id;
 end if;
 update public.user_historical_news_job set status='cancelled' where user_id=auth.uid() and project_id=p_project_id and status='running';
 -- Preference/exclusion changes fence work without modifying narrator evidence.
 update public.user_interview_plan set plan=jsonb_set(jsonb_set(plan,'{candidates}',
   coalesce((select jsonb_agg(c) from jsonb_array_elements(plan->'candidates') c where c->'context'->>'historical_clue_id' is null),'[]')),
   '{chosen_id}',case when exists(select 1 from jsonb_array_elements(plan->'candidates') c
      where c->>'id'=plan->>'chosen_id' and c->'context'->>'historical_clue_id' is null) then plan->'chosen_id' else coalesce((select c->'id' from jsonb_array_elements(plan->'candidates') c
        where c->'context'->>'historical_clue_id' is null limit 1),'null') end)
   where user_id=auth.uid() and project_id=p_project_id;
 return public.read_user_historical_news(p_project_id);
end $$;

CREATE FUNCTION public.stage_formal_memoir_chapter(p_run_id uuid, p_token uuid, p_ordinal integer, p_chapter jsonb, p_validation jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare run public.user_formal_memoir_run%rowtype; plan public.user_formal_memoir_plan%rowtype; expected jsonb; validation jsonb;
 saved public.user_formal_memoir_chapter%rowtype; chapter_digest text;
begin
 run:=public.lock_formal_memoir_run(p_run_id,p_token);
 select * into plan from public.user_formal_memoir_plan where run_id=run.id and ordinal=p_ordinal;
 if not found then raise exception 'FORMAL_CHAPTER_UNAVAILABLE' using errcode='22023';end if;
 expected:=jsonb_build_object('schema_version',1,'chapter_id',plan.chapter_id,'title',plan.title,'blocks',
   (select jsonb_agg((e-'quote')||jsonb_build_object('text',e->>'quote') order by n) from jsonb_array_elements(plan.evidence) with ordinality a(e,n)));
 validation:=jsonb_build_object('schema_version',1,'validator','formal-extractive-v1','chapter_plan_digest',plan.digest,
   'provenance','deterministic-extractive','blocking_count',0);
 if p_chapter is distinct from expected or p_validation is distinct from validation then
   raise exception 'FORMAL_CHAPTER_VALIDATION_FAILED' using errcode='22023';end if;
 chapter_digest:=public.formal_memoir_digest(expected);
 select * into saved from public.user_formal_memoir_chapter where run_id=run.id and ordinal=p_ordinal;
 if found and (saved.digest<>chapter_digest or saved.validation is distinct from validation) then
   raise exception 'FORMAL_CHAPTER_REPLAY_CONFLICT' using errcode='PT409';end if;
 insert into public.user_formal_memoir_chapter(run_id,ordinal,chapter,digest,validation,validation_digest)
 values(run.id,p_ordinal,expected,chapter_digest,validation,public.formal_memoir_digest(validation)) on conflict do nothing;
 return jsonb_build_object('status','staged','chapter_id',plan.chapter_id,'digest',chapter_digest);
end $$;

CREATE FUNCTION public.step_lifetime_compaction(p_id uuid, p_fence jsonb, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare owner uuid:=auth.uid(); saved public.user_lifetime_compaction%rowtype; project text; item record;
  processed integer:=0; fingerprint text; count_items bigint; chain text; last_seq bigint; last_start integer;
begin
  select * into saved from public.user_lifetime_compaction where id=p_id and user_id=owner;
  if not found then raise exception 'maintenance unavailable'; end if;
  select project_id into project from public.user_lifetime_conversation where user_id=owner and conversation_id=saved.conversation_id;
  perform 1 from public.user_memoir_project where user_id=owner and project_id=project for update;
  perform public.lock_lifetime_publication(p_fence);
  select * into saved from public.user_lifetime_compaction where id=p_id and user_id=owner for update;
  if saved.fence is distinct from p_fence or saved.revision is distinct from p_expected_revision
    or saved.pinned is distinct from public.read_lifetime_pinned(saved.conversation_id) then raise exception 'stale maintenance' using errcode='PT409'; end if;
  if saved.complete then return to_jsonb(saved)-'user_id'-'pinned'; end if;
  chain:=saved.digest;count_items:=saved.item_count;last_seq:=saved.last_sequence;last_start:=saved.last_offset;
  for item in
    select pos.sequence,pos.source_id,pos.version,chunk_start,
      case when src.version=pos.version and src.status='active' then least(chunk_start+2000,length(src.text)) else 0 end as chunk_end,
      case when src.id is null then 'withdrawn' when src.version<>pos.version then 'superseded' else src.status end as status,
      case when src.version=pos.version and src.status='active' then substring(src.text from chunk_start+1 for 2000) else null end as content
    from public.user_lifetime_source_position pos left join public.user_narrator_source src
      on src.user_id=pos.user_id and src.project_id=pos.project_id and src.id=pos.source_id
    cross join lateral generate_series(0,case when src.version=pos.version and src.status='active' then greatest(length(src.text)-1,0) else 0 end,2000) chunk_start
    where pos.user_id=owner and pos.project_id=project and pos.sequence>saved.starting_after and pos.sequence<=saved.through_sequence
      and (pos.sequence>saved.last_sequence or (pos.sequence=saved.last_sequence and chunk_start>saved.last_offset))
    order by pos.sequence,chunk_start limit 32
  loop
    fingerprint:=case when item.content is not null then encode(sha256(convert_to(item.content,'UTF8')),'hex') else null end;
    insert into public.user_lifetime_covered_evidence(maintenance_id,sequence,source_id,version,char_start,char_end,status,content_sha256)
      values(p_id,item.sequence,item.source_id,item.version,item.chunk_start,item.chunk_end,item.status,fingerprint);
    chain:=encode(sha256(convert_to(chain||':'||item.sequence||':'||item.source_id||':'||item.version||':'||item.chunk_start||':'||item.chunk_end||':'||item.status||':'||coalesce(fingerprint,''),'UTF8')),'hex');
    processed:=processed+1;count_items:=count_items+1;last_seq:=item.sequence;last_start:=item.chunk_start;
  end loop;
  update public.user_lifetime_compaction set revision=revision+1,item_count=count_items,digest=chain,last_sequence=last_seq,last_offset=last_start,
    complete=processed<32 where id=p_id returning * into saved;
  return to_jsonb(saved)-'user_id'-'pinned';
end $$;

CREATE FUNCTION public.strip_historical_interview_photo_context() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  new.record:=new.record-'photo_associations';
  return new;
end $$;

CREATE FUNCTION public.synchronize_narrator_memory_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $memoir$
declare source public.user_narrator_source%rowtype; original_text text; previous_owner text;
begin
  if pg_catalog.current_setting('memoir.sync_source',true)='true' or old.kind<>'agent' or old.project_id is null then return null; end if;
  if TG_OP='UPDATE' and old.content is not distinct from new.content then return null; end if;
  select * into source from public.user_narrator_source where user_id=old.user_id and project_id=old.project_id and
    client_turn_id=old.client_turn_id;
  if not found or source.status<>'active' then return null; end if;
  previous_owner:=pg_catalog.current_setting('request.jwt.claim.sub',true);
  perform pg_catalog.set_config('request.jwt.claim.sub',old.user_id::text,true);
  if TG_OP='DELETE' or new.content not like 'Storyteller: %' or
     (TG_OP='UPDATE' and new.project_id is distinct from old.project_id) then
    perform public.change_user_narrator_source(old.project_id,source.id,source.version,'withdraw');
  else
    original_text:=pg_catalog.regexp_replace(pg_catalog.substr(new.content,14),E'\\nMemory Spark:[\\s\\S]*$','');
    if pg_catalog.btrim(original_text)='' then
      perform public.change_user_narrator_source(old.project_id,source.id,source.version,'withdraw');
    elsif original_text is distinct from source.text then
      perform public.change_user_narrator_source(old.project_id,source.id,source.version,'edit',original_text);
    end if;
  end if;
  perform pg_catalog.set_config('request.jwt.claim.sub',coalesce(previous_owner,''),true);
  return null;
end $memoir$;

CREATE FUNCTION public.tombstone_account_recordings() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 update public.user_original_recording set lifecycle='deleted',storage_status='deleted',cleanup_status='pending',asr_result=null where user_id=old.id and lifecycle<>'deleted';
 return old;
end $$;

CREATE FUNCTION public.tombstone_project_recordings() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 update public.user_original_recording set lifecycle='deleted',storage_status='deleted',cleanup_status='pending',asr_result=null
 where user_id=old.user_id and project_id=old.project_id and lifecycle<>'deleted';
 return old;
end $$;

CREATE FUNCTION public.tombstone_source_recordings() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 update public.user_original_recording set lifecycle='deleted',storage_status='deleted',cleanup_status='pending',asr_result=null
 where lifecycle<>'deleted' and id in (select recording_id from public.user_source_recording where user_id=old.user_id and project_id=old.project_id and source_id=old.id);
 return old;
end $$;

CREATE FUNCTION public.track_lifetime_source_inventory() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if tg_op='INSERT' then
   insert into public.user_lifetime_source_inventory values(new.user_id,new.project_id,1,new.sequence)
   on conflict(user_id,project_id) do update set record_count=public.user_lifetime_source_inventory.record_count+1,
     max_sequence=greatest(public.user_lifetime_source_inventory.max_sequence,excluded.max_sequence);
 else
   update public.user_lifetime_source_inventory set record_count=record_count-1,
     max_sequence=case when max_sequence=old.sequence then coalesce((select max(sequence) from public.user_lifetime_source_position
       where user_id=old.user_id and project_id=old.project_id),0) else max_sequence end
     where user_id=old.user_id and project_id=old.project_id;
 end if;
 return coalesce(new,old);
end $$;

CREATE FUNCTION public.transfer_recall_usage() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare guest_usage bigint; imported bigint;
begin
  if old.target_user_id is null and new.target_user_id is not null then
    select rounds_completed into guest_usage from public.user_recall_usage where user_id = old.guest_user_id;
    select count(*) into imported from jsonb_array_elements(old.memories) m where m->>'kind' = 'agent';
    insert into public.user_recall_usage(user_id, rounds_completed)
      values(new.target_user_id, greatest(0, coalesce(guest_usage, 0) - imported))
      on conflict(user_id) do update set rounds_completed = public.user_recall_usage.rounds_completed + excluded.rounds_completed;
  end if;
  return new;
end;
$$;

CREATE FUNCTION public.unlink_user_interview_photo(p_project_id text, p_association_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare link public.user_interview_photo_link%rowtype; latest_sequence bigint;
begin
  select interview_sequence into latest_sequence from public.user_memoir_project
    where user_id=auth.uid() and project_id=p_project_id for update;
  select * into link from public.user_interview_photo_link where user_id=auth.uid() and project_id=p_project_id and id=p_association_id for update;
  if not found then raise exception 'photo association unavailable' using errcode='42501'; end if;
  -- Uncertain retries cannot move the fence past an explicitly reselected cue.
  if link.status='unlinked' then return jsonb_build_object('unlinked',true); end if;
  update public.user_interview_photo_link set status='unlinked',retired_through_sequence=latest_sequence
    where user_id=auth.uid() and project_id=p_project_id and id=p_association_id;
  perform public.invalidate_interview_photo_projection(auth.uid(),p_project_id);
  return jsonb_build_object('unlinked',true);
end $$;

CREATE FUNCTION public.update_lifetime_stage_volume() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if tg_op='DELETE' then delete from public.user_lifetime_stage_volume where memory_id=old.id;return old;end if;
 if new.kind='agent' and new.project_id is not null then
   insert into public.user_lifetime_stage_volume(memory_id,user_id,project_id,client_turn_id,life_stage,word_equivalents)
     values(new.id,new.user_id,new.project_id,new.client_turn_id,new.life_stage,public.lifetime_narrator_word_equivalents(new.kind,new.content))
     on conflict(memory_id) do update set user_id=excluded.user_id,project_id=excluded.project_id,client_turn_id=excluded.client_turn_id,
       life_stage=excluded.life_stage,word_equivalents=excluded.word_equivalents;
 else delete from public.user_lifetime_stage_volume where memory_id=new.id;end if;
 return new;
end $$;

CREATE FUNCTION public.upsert_user_family_context(p_project_id text, p_document jsonb, p_expected_revision bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  current_row public.user_family_context%rowtype;
  next_revision bigint;
  next_document jsonb;
begin
  if auth.uid() is null then
    raise exception 'authenticated user required';
  end if;
  if p_project_id is null or char_length(p_project_id) < 1 or char_length(p_project_id) > 128 then
    raise exception 'invalid project id';
  end if;
  if p_document is null or jsonb_typeof(p_document) <> 'object' then
    raise exception 'family document must be a JSON object';
  end if;

  select * into current_row
    from public.user_family_context
   where user_id = auth.uid() and project_id = p_project_id
   for update;

  if found then
    if p_expected_revision is not null and current_row.revision <> p_expected_revision then
      raise exception 'family context revision conflict';
    end if;

    -- Ignore transport metadata when deciding whether a retry changed the
    -- canonical records. This makes a retried Codex turn idempotent.
    if (current_row.document - 'revision' - 'updated_at') = (p_document - 'revision' - 'updated_at') then
      return jsonb_build_object(
        'changed', false,
        'document', current_row.document,
        'revision', current_row.revision,
        'updated_at', current_row.updated_at
      );
    end if;

    next_revision := current_row.revision + 1;
    next_document := p_document || jsonb_build_object('revision', next_revision, 'updated_at', now());
    update public.user_family_context
       set document = next_document,
           revision = next_revision,
           updated_at = now()
     where user_id = auth.uid() and project_id = p_project_id;
  else
    if p_expected_revision is not null and p_expected_revision <> 0 then
      raise exception 'family context revision conflict';
    end if;
    next_revision := 1;
    next_document := p_document || jsonb_build_object('revision', next_revision, 'updated_at', now());
    insert into public.user_family_context(user_id, project_id, document, revision)
    values (auth.uid(), p_project_id, next_document, next_revision);
  end if;

  return jsonb_build_object(
    'changed', true,
    'document', next_document,
    'revision', next_revision,
    'updated_at', now()
  );
end;
$$;

CREATE FUNCTION public.upsert_user_place_journey(p_lease_token uuid, p_journey jsonb, p_source_sequence bigint DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  owner_id uuid := auth.uid();
  held public.user_agent_turn_lease%rowtype;
  saved public.user_place_journey%rowtype;
begin
  if owner_id is null then
    raise exception 'authenticated user required' using errcode = '42501';
  end if;
  select * into held from public.user_agent_turn_lease
    where user_id = owner_id for update;
  if not found or held.lease_token is distinct from p_lease_token
      or held.expires_at <= pg_catalog.clock_timestamp() then
    raise exception 'Codex turn lease lost' using errcode = '42501';
  end if;
  if p_journey is null or pg_catalog.jsonb_typeof(p_journey) <> 'object' then
    raise exception 'place journey object required' using errcode = '22023';
  end if;

  insert into public.user_place_journey(
    user_id, schema_version, status, revision, source_sequence, place,
    hierarchy, granularity, latitude, longitude, duration_ms, created_at, updated_at
  ) values (
    owner_id,
    coalesce(nullif(p_journey->>'schema_version', '')::integer, 1),
    'active',
    1,
    greatest(coalesce(p_source_sequence, 0), 0),
    pg_catalog.btrim(p_journey->>'place'),
    p_journey->'hierarchy',
    pg_catalog.lower(pg_catalog.btrim(p_journey->>'granularity')),
    case when p_journey ? 'latitude' then (p_journey->>'latitude')::double precision else null end,
    case when p_journey ? 'longitude' then (p_journey->>'longitude')::double precision else null end,
    coalesce(nullif(p_journey->>'duration_ms', '')::integer, 5200),
    pg_catalog.clock_timestamp(),
    pg_catalog.clock_timestamp()
  )
  on conflict (user_id) do update set
    schema_version = excluded.schema_version,
    status = excluded.status,
    revision = case when excluded.source_sequence >= public.user_place_journey.source_sequence
      then public.user_place_journey.revision + 1 else public.user_place_journey.revision end,
    source_sequence = greatest(public.user_place_journey.source_sequence, excluded.source_sequence),
    place = case when excluded.source_sequence >= public.user_place_journey.source_sequence
      then excluded.place else public.user_place_journey.place end,
    hierarchy = case when excluded.source_sequence >= public.user_place_journey.source_sequence
      then excluded.hierarchy else public.user_place_journey.hierarchy end,
    granularity = case when excluded.source_sequence >= public.user_place_journey.source_sequence
      then excluded.granularity else public.user_place_journey.granularity end,
    latitude = case when excluded.source_sequence >= public.user_place_journey.source_sequence
      then excluded.latitude else public.user_place_journey.latitude end,
    longitude = case when excluded.source_sequence >= public.user_place_journey.source_sequence
      then excluded.longitude else public.user_place_journey.longitude end,
    duration_ms = case when excluded.source_sequence >= public.user_place_journey.source_sequence
      then excluded.duration_ms else public.user_place_journey.duration_ms end,
    updated_at = case when excluded.source_sequence >= public.user_place_journey.source_sequence
      then pg_catalog.clock_timestamp() else public.user_place_journey.updated_at end
  returning * into saved;

  return pg_catalog.to_jsonb(saved);
end;
$$;

CREATE FUNCTION public.validate_lifetime_replay_before_recordings(p_conversation_id uuid, p_client_turn_id uuid, p_text text, p_kind text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare project text; accepted public.user_interview_turn%rowtype; kind text;
begin
 select project_id into project from public.user_lifetime_conversation where user_id=auth.uid() and conversation_id=p_conversation_id;
 if not found then raise exception 'conversation unavailable'; end if;
 select * into accepted from public.user_interview_turn where user_id=auth.uid() and project_id=project and client_turn_id=p_client_turn_id;
 if not found then return false; end if;
 select s.kind into kind from public.user_narrator_source s where s.user_id=auth.uid() and s.project_id=project and s.id=accepted.source_id;
 if accepted.input_hash is distinct from md5(p_text) or kind is distinct from p_kind then
   raise exception 'input revision conflict; retry the original accepted input' using errcode='PT409'; end if;
 return true;
end $$;

CREATE FUNCTION public.validate_lifetime_replay_input(p_conversation_id uuid, p_client_turn_id uuid, p_text text, p_kind text, p_recording_ids jsonb DEFAULT '[]'::jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare accepted boolean; saved jsonb;
begin
 accepted:=public.validate_lifetime_replay_before_recordings(p_conversation_id,p_client_turn_id,p_text,p_kind);
 if accepted then
   select coalesce(jsonb_agg(l.recording_id::text order by l.position),'[]') into saved
   from public.user_source_recording l join public.user_lifetime_conversation c on c.user_id=l.user_id and c.project_id=l.project_id
   where c.user_id=auth.uid() and c.conversation_id=p_conversation_id and l.client_turn_id=p_client_turn_id;
   if saved is distinct from p_recording_ids then raise exception 'recording replay conflict' using errcode='PT409';end if;
 end if;
 return accepted;
end $$;

CREATE FUNCTION public.validate_memory_evidence(p_owner uuid, p_project_id text, p_ref jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare original public.user_narrator_source%rowtype; start_offset integer; end_offset integer;
begin
  select * into original from public.user_narrator_source where user_id=p_owner and project_id=p_project_id and id=(p_ref->>'source_id')::uuid;
  if not found then raise exception 'evidence source unavailable' using errcode='42501'; end if;
  if original.status<>'active' or original.version is distinct from (p_ref->>'version')::bigint then
    raise exception 'evidence revision conflict' using errcode='PT409'; end if;
  if length(coalesce(p_ref->>'quote','')) not between 1 and 2000 or pg_catalog.strpos(original.text,p_ref->>'quote')=0 then
    raise exception 'evidence quote must match original testimony' using errcode='22023'; end if;
  start_offset:=(p_ref->>'char_start')::integer; end_offset:=(p_ref->>'char_end')::integer;
  if (start_offset is null)<>(end_offset is null) or (start_offset is not null and
    (start_offset<0 or end_offset<=start_offset or pg_catalog.substr(original.text,start_offset+1,end_offset-start_offset) is distinct from p_ref->>'quote')) then
    raise exception 'evidence span must match original testimony' using errcode='22023'; end if;
end $$;

CREATE FUNCTION public.validate_memory_temporal(p_owner uuid, p_project_id text, p_temporal jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare proof jsonb:=p_temporal; basis jsonb; filtered jsonb;
begin
 if auth.uid() is distinct from p_owner then raise exception 'owned temporal evidence required' using errcode='42501';end if;
 if p_temporal->>'precision'='age' and (p_temporal->>'year_start' is not null or p_temporal->>'year_end' is not null) then
   if (p_temporal->>'year_end')::integer>(p_temporal->>'year_start')::integer+1 then
     raise exception 'age interval exceeds supported precision' using errcode='22023';end if;
   for basis in select value from jsonb_array_elements(coalesce(p_temporal->'basis','[]')) loop
     perform public.validate_memory_evidence(p_owner,p_project_id,basis);
   end loop;
   select coalesce(jsonb_agg(b),'[]') into filtered from jsonb_array_elements(coalesce(p_temporal->'basis','[]')) b
   where lower(coalesce(b->>'attribution','narrator')) in ('narrator','storyteller','self','我','本人')
     and (b->>'quote' !~* '(born|birth|出生|生于)' or public.lifetime_narrator_birth_basis(p_owner,p_project_id,b));
   proof:=jsonb_set(proof,'{basis}',filtered);
   if p_temporal->>'year_start' is not null and (p_temporal->>'year_end')::integer=(p_temporal->>'year_start')::integer+1 then
     proof:=jsonb_set(proof,'{year_end}',p_temporal->'year_start');
   end if;
 end if;
 perform public.validate_memory_temporal_before_attribution(p_owner,p_project_id,proof);
end $$;

CREATE FUNCTION public.validate_memory_temporal_before_attribution(p_owner uuid, p_project_id text, p_temporal jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $memoir$
declare basis jsonb; birth_basis jsonb; target_year integer; age_number integer; birth_match text[]; supported boolean;
begin
  if pg_catalog.jsonb_typeof(p_temporal) is distinct from 'object' or
     p_temporal->>'precision' is null or p_temporal->>'precision' not in ('unknown','day','month','year','range','approximate','age','season') or
     length(coalesce(p_temporal->>'expression','')) not between 1 and 500 then
    raise exception 'invalid temporal placement' using errcode='22023'; end if;
  if (p_temporal->>'year_start')::integer>(p_temporal->>'year_end')::integer then
    raise exception 'invalid temporal range' using errcode='22023'; end if;
  for basis in select value from pg_catalog.jsonb_array_elements(coalesce(p_temporal->'basis','[]')) loop
    perform public.validate_memory_evidence(p_owner,p_project_id,basis);
  end loop;
  for target_year in select (p_temporal->>'year_start')::integer union select (p_temporal->>'year_end')::integer loop
    if target_year is null then continue; end if;
    if target_year not between 1 and 9999 or p_temporal->>'precision'='unknown' then
      raise exception 'unsupported numeric date' using errcode='22023'; end if;
    supported:=false;
    if p_temporal->>'precision'='age' then
      for basis in select value from pg_catalog.jsonb_array_elements(coalesce(p_temporal->'basis','[]')) loop
        age_number:=public.memory_age_number(basis->>'quote');
        if age_number is not null then
          for birth_basis in select value from pg_catalog.jsonb_array_elements(p_temporal->'basis') loop
            if birth_basis->>'quote' ~* '(born|birth|出生|生于)' then
              birth_match:=coalesce(
                pg_catalog.regexp_match(birth_basis->>'quote','(?i)(?:\mi\M\s+(?:was\s+)?born\s+(?:in\s+)?|\mmy\s+(?:birth year|year of birth)\s+(?:was|is)?\s*)([0-9]{4})'),
                pg_catalog.regexp_match(birth_basis->>'quote','我(?:是|于|在)?([0-9]{4})年?(?:出生|生于)'),
                pg_catalog.regexp_match(birth_basis->>'quote','我(?:是)?(?:出生|生于)(?:于|在)?([0-9]{4})'));
              if birth_match is not null and birth_match[1]::integer+age_number=target_year then supported:=true; end if;
            end if;
          end loop;
        end if;
      end loop;
    else
      select exists(select 1 from pg_catalog.jsonb_array_elements(coalesce(p_temporal->'basis','[]')) b
        where b->>'quote' ~ ('(^|[^0-9])'||target_year::text||'([^0-9]|$)')
           or pg_catalog.strpos(b->>'quote',pg_catalog.translate(target_year::text,'0123456789','〇一二三四五六七八九'))>0
           or pg_catalog.strpos(b->>'quote',pg_catalog.replace(pg_catalog.translate(target_year::text,'0123456789','〇一二三四五六七八九'),'〇','零'))>0) into supported;
    end if;
    if not supported then raise exception 'numeric date requires supported original evidence' using errcode='22023'; end if;
  end loop;
  if p_temporal->>'expression'<>'unknown' and not exists
      (select 1 from pg_catalog.jsonb_array_elements(coalesce(p_temporal->'basis','[]')) b where pg_catalog.strpos(b->>'quote',p_temporal->>'expression')>0) then
    raise exception 'date expression requires its original evidence' using errcode='22023'; end if;
end $memoir$;

CREATE FUNCTION public.validate_place_research_window(p_text text, w jsonb, p_source_offset integer DEFAULT 0) RETURNS void
 LANGUAGE plpgsql SET search_path TO '' AS $$
begin
 if jsonb_typeof(w) is distinct from 'object'
 or not w ?& array['year_start','year_end','anchor_year','basis','quote','char_start','char_end']
 or exists(select 1 from jsonb_object_keys(w) k where k not in ('year_start','year_end','anchor_year','basis','quote','char_start','char_end'))
 or coalesce(w->>'basis','') not in ('explicit_period','birth_decade')
 or jsonb_typeof(w->'quote') is distinct from 'string' or length(w->>'quote') not between 1 and 2000
 or jsonb_typeof(w->'year_start') is distinct from 'number' or jsonb_typeof(w->'year_end') is distinct from 'number'
 or jsonb_typeof(w->'char_start') is distinct from 'number' or jsonb_typeof(w->'char_end') is distinct from 'number'
 or coalesce(w->>'year_start','') !~ '^[0-9]{4}$' or coalesce(w->>'year_end','') !~ '^[0-9]{4}$'
 or coalesce(w->>'char_start','') !~ '^[0-9]{1,8}$' or coalesce(w->>'char_end','') !~ '^[0-9]{1,8}$'
 then raise exception 'typed place research evidence required' using errcode='22023'; end if;
 if (w->>'year_start')::int not between 1800 and 2100 or (w->>'year_end')::int not between (w->>'year_start')::int and least(2100,(w->>'year_start')::int+15)
 or (w->>'char_start')::int<p_source_offset or (w->>'char_end')::int>p_source_offset+length(p_text) or (w->>'char_end')::int<=(w->>'char_start')::int
 or substring(p_text from (w->>'char_start')::int-p_source_offset+1 for (w->>'char_end')::int-(w->>'char_start')::int) is distinct from w->>'quote'
 then raise exception 'exact place research evidence required' using errcode='22023'; end if;
 if w->'anchor_year'<>'null'::jsonb then
   if jsonb_typeof(w->'anchor_year') is distinct from 'number' or coalesce(w->>'anchor_year','') !~ '^[0-9]{4}$' then raise exception 'typed research anchor required' using errcode='22023'; end if;
   if (w->>'anchor_year')::int not between (w->>'year_start')::int and (w->>'year_end')::int then
     raise exception 'research anchor outside window' using errcode='22023'; end if;
 end if;
end $$;
revoke all on function public.validate_place_research_window(text,jsonb,integer) from public,anon,authenticated,service_role;

CREATE FUNCTION public.validate_two_lane_places(p_source_text text, p_journeys jsonb, p_source_offset integer DEFAULT 0) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare journey jsonb;
begin
 if jsonb_typeof(p_journeys) is distinct from 'array' or jsonb_array_length(p_journeys)>8
   or octet_length(p_journeys::text)>8192 then raise exception 'bounded place journeys required' using errcode='22023'; end if;
 for journey in select * from jsonb_array_elements(p_journeys) loop
   if jsonb_typeof(journey) is distinct from 'object'
     or exists(select 1 from jsonb_object_keys(journey) k where k not in ('schema_version','place','hierarchy','granularity','duration_ms','latitude','longitude','research'))
     or journey->'schema_version' is distinct from '1'::jsonb
     or jsonb_typeof(journey->'place') is distinct from 'string'
     or length(journey->>'place') not between 1 and 120
     or strpos(lower(p_source_text),lower(journey->>'place'))=0
     or jsonb_typeof(journey->'hierarchy') is distinct from 'array'
     or jsonb_array_length(journey->'hierarchy') not between 2 and 6
     or journey->'hierarchy'->>0 is distinct from 'Earth'
     or journey->'hierarchy'->>-1 is distinct from journey->>'place'
     or exists(select 1 from jsonb_array_elements(journey->'hierarchy') label
       where jsonb_typeof(label) is distinct from 'string' or length(label#>>'{}') not between 1 and 120)
     or coalesce(journey->>'granularity','') not in ('country','region','city','suburb')
     then raise exception 'grounded coarse place journey required' using errcode='22023'; end if;
   if (journey ? 'latitude') is distinct from (journey ? 'longitude')
     or (journey ? 'latitude' and (jsonb_typeof(journey->'latitude') is distinct from 'number'
       or jsonb_typeof(journey->'longitude') is distinct from 'number'
       or (journey->>'latitude')::numeric not between -90 and 90
       or (journey->>'longitude')::numeric not between -180 and 180))
     then raise exception 'valid public place centre required' using errcode='22023'; end if;
   if journey ? 'research' and journey->'research'<>'null'::jsonb then
     perform public.validate_place_research_window(p_source_text,journey->'research',p_source_offset);
   end if;
 end loop;
end $$;

CREATE FUNCTION public.verify_lifetime_chosen_name_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare dependency public.user_lifetime_chosen_name%rowtype;
begin
 select * into dependency from public.user_lifetime_chosen_name where user_id=new.user_id;
 if found and new.profile->>'name' is distinct from dependency.chosen_name then
   raise exception 'chosen-name authority changed; retry profile write' using errcode='PT409';
 end if;
 return new;
end $$;

CREATE FUNCTION public.workspace_progressive_rework_section(p_request public.user_workspace_section_rework) RETURNS SETOF public.user_lifetime_memoir_section
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
 select s.* from public.user_lifetime_memoir_section s
 join public.user_lifetime_lane_snapshot root on root.id=s.snapshot_id
 join public.user_lifetime_lane_snapshot requested on requested.id=p_request.snapshot_id
 where s.user_id=p_request.user_id and s.project_id=p_request.project_id
   and s.locale=p_request.locale and s.partition_key=p_request.partition_key and s.event_id=p_request.event_id
   and requested.user_id=p_request.user_id and requested.project_id=p_request.project_id
   and requested.locale=p_request.locale and requested.root_digest=p_request.root_digest
   and requested.state in ('completed','proposed') and root.state in ('completed','proposed')
   and root.created_at<=requested.created_at and root.policy_epoch=requested.policy_epoch
   and root.preference_revision=requested.preference_revision
 order by root.created_at desc limit 1
$$;

CREATE FUNCTION public.workspace_progressive_section_current(s public.user_lifetime_memoir_section) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
 select s.partition_key like 'progressive:%' and not s.retired and s.bundle ? 'preview'
 and jsonb_array_length(s.source_dependencies)>0 and jsonb_array_length(s.event_dependencies)>0
 and exists(select 1 from public.user_lifetime_lane_snapshot root
   join public.user_memoir_project p on p.user_id=root.user_id and p.project_id=root.project_id
   join public.user_lifetime_conversation c on c.user_id=p.user_id and c.project_id=p.project_id
   where root.id=s.snapshot_id and root.state in ('completed','proposed')
     and root.policy_epoch=p.policy_epoch and root.preference_revision=c.preference_revision)
 and not exists(select 1 from jsonb_array_elements(s.source_dependencies) d where not exists(
   select 1 from public.user_narrator_source n where n.user_id=s.user_id and n.project_id=s.project_id
     and n.id::text=d->>'id' and n.version::text=d->>'version' and n.status='active'))
 and not exists(select 1 from jsonb_array_elements(s.event_dependencies) d where not exists(
   select 1 from public.user_memory_event e where e.user_id=s.user_id and e.project_id=s.project_id
     and e.id=d->>'id' and e.revision::text=d->>'revision' and e.status='active'))
$$;

CREATE FUNCTION public.workspace_rework_partition_current(p_owner uuid, p_project_id text, p_event_id text, p_partition_key text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
 select case when p_partition_key like 'progressive:%' then exists(
   select 1 from public.user_lifetime_memoir_section s where s.user_id=p_owner and s.project_id=p_project_id
     and s.event_id=p_event_id and s.partition_key=p_partition_key and public.workspace_progressive_section_current(s))
 else public.workspace_rework_partition_current_before_progressive(p_owner,p_project_id,p_event_id,p_partition_key) end
$$;

CREATE FUNCTION public.workspace_rework_partition_current_before_progressive(p_owner uuid, p_project_id text, p_event_id text, p_partition_key text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
 select exists(select 1 from public.user_memory_event_source r
   left join public.user_interview_photo_link photo on photo.user_id=r.user_id and photo.project_id=r.project_id
     and photo.event_id=r.event_id and photo.source_id=r.source_id and photo.source_version=r.source_version
     and photo.status='confirmed' and photo.provenance='narrator_metadata' and strpos(r.evidence->>'quote',photo.quote)>0
     and public.interview_photo_available(r.user_id,r.project_id,photo.photo_id)
   where r.user_id=p_owner and r.project_id=p_project_id and r.event_id=p_event_id
     and p_partition_key=r.event_id||':'||r.source_id::text||':'||r.source_version::text||':'||r.evidence_hash||':'||coalesce(photo.id::text,''))
$$;

CREATE FUNCTION public.yield_lifetime_memoir_lane(p_lane_id uuid, p_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare snap public.user_lifetime_lane_snapshot%rowtype;
begin
 snap:=public.lock_lifetime_memoir_lane(p_lane_id,p_token);
 update public.user_memoir_lane set token=null,lease_until=null,run_deadline=null,pending=true,attempts=0,error=null,
   available_at=clock_timestamp() where id=p_lane_id;
 return jsonb_build_object('status','pending','snapshot_id',snap.id,'pages',snap.page_number,'retrieval_complete',false);
end $$;

CREATE FUNCTION public.yield_lifetime_memoir_lane_metadata(p_lane_id uuid, p_token uuid, p_user_id uuid, p_project_id text, p_conversation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare lane public.user_memoir_lane%rowtype;
begin
 select * into lane from public.user_memoir_lane
   where id=p_lane_id and user_id=p_user_id and project_id=p_project_id;
 if not found then raise exception 'canonical lane metadata authority unavailable' using errcode='42501';end if;
 perform 1 from public.user_memoir_project where user_id=p_user_id and project_id=p_project_id for update;
 if not found then raise exception 'canonical lane metadata authority unavailable' using errcode='42501';end if;
 perform 1 from public.user_profile where user_id=p_user_id for share;
 perform 1 from public.user_lifetime_conversation where user_id=p_user_id and project_id=p_project_id
   and conversation_id=p_conversation_id for share;
 if not found then raise exception 'canonical lane metadata authority unavailable' using errcode='42501';end if;
 select * into lane from public.user_memoir_lane where id=p_lane_id for update;
 if lane.id is null or lane.user_id is distinct from p_user_id or lane.project_id is distinct from p_project_id
   or lane.token is null or lane.token is distinct from p_token or lane.lease_until is null or lane.run_deadline is null
   or lane.lease_until<=clock_timestamp() or lane.run_deadline<=clock_timestamp() then
   raise exception 'stale canonical lane metadata lease' using errcode='40001';end if;
 -- The page may already be stale and its contents remain inaccessible. This
 -- current owner/token can only relinquish its own lease and request a retry.
 update public.user_memoir_lane set token=null,lease_until=null,run_deadline=null,pending=true,attempts=0,
   error=null,available_at=clock_timestamp() where id=p_lane_id;
 return jsonb_build_object('status','pending','retrieval_complete',false);
end $$;



CREATE FUNCTION public.read_user_memory_event_changes(p_project_id text, p_after_sequence bigint DEFAULT 0)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('sequence',sequence,'event_id',event_id,
    'revision',revision,'old_group',old_group,'new_group',new_group) order by sequence),'[]'::jsonb)
  from public.user_memory_event_change where user_id=auth.uid() and project_id=p_project_id and sequence>p_after_sequence
$function$
;

CREATE FUNCTION public.unlink_user_memory_event_source(p_project_id text, p_event_id text, p_expected_revision bigint, p_source_id uuid, p_statement text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare owner_id uuid:=auth.uid(); saved public.user_memory_event%rowtype; next_change bigint;
begin
  if owner_id is null then raise exception 'authenticated user required' using errcode='42501'; end if;
  if length(pg_catalog.btrim(coalesce(p_statement,''))) not between 1 and 2000 then raise exception 'source removal requires a statement' using errcode='22023'; end if;
  perform 1 from public.user_memoir_project where user_id=owner_id and project_id=p_project_id for update;
  select * into saved from public.user_memory_event where user_id=owner_id and project_id=p_project_id and id=p_event_id for update;
  if not found then raise exception 'event unavailable' using errcode='42501'; end if;
  if saved.revision is distinct from p_expected_revision then raise exception 'event revision conflict; reload the event' using errcode='PT409'; end if;
  if not exists(select 1 from public.user_memory_event_source where user_id=owner_id and project_id=p_project_id and event_id=p_event_id and source_id=p_source_id) then
    raise exception 'source link unavailable' using errcode='42501'; end if;
  insert into public.user_memory_event_source_exclusion values(owner_id,p_project_id,p_event_id,p_source_id,owner_id,p_statement,p_expected_revision) on conflict do nothing;
  delete from public.user_memory_event_source where user_id=owner_id and project_id=p_project_id and event_id=p_event_id and source_id=p_source_id;
  delete from public.user_memoir_checkpoint c using public.user_memoir_lane l where c.lane_id=l.id and l.user_id=owner_id and l.project_id=p_project_id and
    exists(select 1 from pg_catalog.jsonb_array_elements(c.event_manifest) e where e->>'id'=p_event_id);
  update public.user_memoir_project set event_sequence=event_sequence+1,policy_epoch=policy_epoch+1 where user_id=owner_id and project_id=p_project_id returning event_sequence into next_change;
  update public.user_memory_event e set revision=revision+1,change_sequence=next_change,
    life_stage=case when saved.data->'user_overrides' ? 'life_stage' and saved.data->'user_overrides'->'life_stage'->>'source_id' is distinct from p_source_id::text then saved.life_stage else 'unplaced' end,
    status=case when exists(select 1 from public.user_memory_event_source where user_id=owner_id and project_id=p_project_id and event_id=p_event_id) then 'unresolved' else 'withdrawn' end,
    data=pg_catalog.jsonb_build_object('title','Evidence changed; awaiting extraction','temporal',
      case when saved.data->'user_overrides' ? 'temporal' and saved.data->'user_overrides'->'temporal'->>'source_id' is distinct from p_source_id::text
        then saved.data->'temporal' else pg_catalog.jsonb_build_object('expression','unknown','precision','unknown') end,
      'stage_evidence',case when saved.data->'user_overrides' ? 'life_stage' and saved.data->'user_overrides'->'life_stage'->>'source_id' is distinct from p_source_id::text
        then coalesce(saved.data->'stage_evidence','[]') else '[]'::jsonb end,
      'user_overrides',coalesce((select pg_catalog.jsonb_object_agg(key,value) from pg_catalog.jsonb_each(coalesce(saved.data->'user_overrides','{}'))
        where value->>'source_id' is distinct from p_source_id::text),'{}'),
      'visibility',saved.data->'visibility','include_in_print',saved.data->'include_in_print')
    where user_id=owner_id and project_id=p_project_id and id=p_event_id returning * into saved;
  update public.user_narrator_source set processing_status='pending' where user_id=owner_id and project_id=p_project_id and status='active' and id in
    (select source_id from public.user_memory_event_source where user_id=owner_id and project_id=p_project_id and event_id=p_event_id);
  update public.user_memoir_project set extraction_cursor=coalesce((select min(sequence)-1 from public.user_narrator_source where user_id=owner_id and project_id=p_project_id and status='active' and processing_status<>'succeeded'),source_sequence)
    where user_id=owner_id and project_id=p_project_id;
  insert into public.user_private_draft_outbox(user_id,project_id,change_kind) values(owner_id,p_project_id,'edit');
  return public.memory_event_record(saved);
end $function$
;

CREATE FUNCTION public.read_lifetime_admission(p_project_id text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if auth.uid() is null or not exists(select 1 from auth.users where id=auth.uid()) then
   raise exception 'authenticated owner required' using errcode='42501';
 end if;
 return 'governed';
end $function$
;

CREATE FUNCTION public.read_formal_memoir_edition_chapter(p_project_id text, p_edition_id uuid, p_ordinal integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare edition public.user_formal_memoir_edition%rowtype; run public.user_formal_memoir_run%rowtype; chapter public.user_formal_memoir_chapter%rowtype;
begin
 select * into edition from public.user_formal_memoir_edition where id=p_edition_id and project_id=p_project_id and active;
 if not found then raise exception 'FORMAL_EDITION_UNAVAILABLE' using errcode='42501';end if;
 run:=public.lock_formal_memoir_run(edition.run_id,null,false);
 select * into chapter from public.user_formal_memoir_chapter where run_id=run.id and ordinal=p_ordinal;
 if not found then raise exception 'FORMAL_CHAPTER_UNAVAILABLE' using errcode='22023';end if;
 return jsonb_build_object('edition_id',edition.id,'revision',edition.revision,'ordinal',p_ordinal,'chapter',chapter.chapter,'digest',chapter.digest);
end $function$
;

CREATE FUNCTION public.read_user_original_recording(p_recording_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select public.original_recording_descriptor(r) || jsonb_build_object('asr_result',r.asr_result) from public.user_original_recording r
 where r.id=p_recording_id and public.original_recording_visible(r,auth.uid())
$function$
;

revoke all on function public.read_user_memory_event_changes(text, bigint) from public,anon,authenticated,service_role;

grant execute on function public.read_user_memory_event_changes(text, bigint) to authenticated;

revoke all on function public.unlink_user_memory_event_source(text, text, bigint, uuid, text) from public,anon,authenticated,service_role;

grant execute on function public.unlink_user_memory_event_source(text, text, bigint, uuid, text) to authenticated;

revoke all on function public.read_lifetime_admission(text) from public,anon,authenticated,service_role;

grant execute on function public.read_lifetime_admission(text) to authenticated;

revoke all on function public.read_formal_memoir_edition_chapter(text, uuid, integer) from public,anon,authenticated,service_role;

grant execute on function public.read_formal_memoir_edition_chapter(text, uuid, integer) to service_role;

revoke all on function public.read_user_original_recording(uuid) from public,anon,authenticated,service_role;

grant execute on function public.read_user_original_recording(uuid) to authenticated;

