insert into storage.buckets(id,name,public,file_size_limit) values ('memory-spark','memory-spark',false,52428800) on conflict (id) do nothing;

insert into storage.buckets(id,name,public,file_size_limit) values ('memoir-private-photos','memoir-private-photos',false,10485760) on conflict (id) do nothing;

-- Original bytes are accessed only by the guarded backend, never a browser JWT.
insert into storage.buckets(id,name,public,file_size_limit) values ('memoir-original-recordings','memoir-original-recordings',false,10485760) on conflict (id) do nothing;

create policy memory_spark_owner on storage.objects as permissive for all to authenticated
  using (((bucket_id = 'memory-spark'::text) AND ((storage.foldername(name))[1] = (( SELECT auth.uid() AS uid))::text)))
  with check (((bucket_id = 'memory-spark'::text) AND ((storage.foldername(name))[1] = (( SELECT auth.uid() AS uid))::text) AND ((storage.foldername(name))[2] = ANY (ARRAY['attachment'::text, 'agent'::text]))));

create policy merged_guest_asset_read on storage.objects as permissive for select to authenticated
  using (((bucket_id = 'memory-spark'::text) AND (EXISTS ( SELECT 1
   FROM public.guest_merge_asset_access g
  WHERE ((g.user_id = ( SELECT auth.uid() AS uid)) AND (g.source_name = objects.name))))));

create policy interview_photo_bytes_read on storage.objects as permissive for select to authenticated
  using (((bucket_id = 'memoir-private-photos'::text) AND (EXISTS ( SELECT 1
   FROM public.user_interview_photo p
  WHERE ((p.user_id = auth.uid()) AND (p.object_path = objects.name) AND (((p.status = 'ready'::text) AND public.interview_storage_operation_allowed(ARRAY['object.get_authenticated'::text, 'object.get_authenticated_info'::text, 'object.head_authenticated_info'::text])) OR ((p.status = ANY (ARRAY['pending'::text, 'deleted'::text])) AND public.interview_storage_operation_allowed(ARRAY['object.delete'::text, 'object.delete_many'::text]))))))));

create policy interview_photo_bytes_insert on storage.objects as permissive for insert to authenticated
  with check (((bucket_id = 'memoir-private-photos'::text) AND public.interview_storage_operation_allowed(ARRAY['object.upload'::text]) AND (EXISTS ( SELECT 1
   FROM public.user_interview_photo p
  WHERE ((p.user_id = auth.uid()) AND (p.object_path = objects.name) AND (p.status = 'pending'::text))))));

create policy interview_photo_bytes_delete on storage.objects as permissive for delete to authenticated
  using (((bucket_id = 'memoir-private-photos'::text) AND public.interview_storage_operation_allowed(ARRAY['object.delete'::text, 'object.delete_many'::text]) AND (EXISTS ( SELECT 1
   FROM public.user_interview_photo p
  WHERE ((p.user_id = auth.uid()) AND (p.object_path = objects.name) AND (p.status = ANY (ARRAY['pending'::text, 'deleted'::text])))))));

