-- Private game storage and authorized publication

-- Private adaptation jobs are bound to immutable formal editions and consent.
create table public.user_story_game (
 id uuid primary key default gen_random_uuid(),
 user_id uuid not null references auth.users(id) on delete cascade,
 project_id text not null,
 edition_id uuid not null references public.user_formal_memoir_edition(id) on delete cascade,
 request_id uuid not null,
 authority jsonb not null,
 state text not null default 'pending' check(state in ('pending','running','selection_required','review_required','published','failed','stale')),
 phase text not null default 'scenes' check(phase in ('scenes','build')),
 scene_pool jsonb, pool_digest text, selection jsonb, selection_digest text, brief jsonb,
 token uuid, lease_until timestamptz, attempts integer not null default 0,
 candidate jsonb, candidate_digest text, review jsonb, model_receipt jsonb,
 created_at timestamptz not null default clock_timestamp(), updated_at timestamptz not null default clock_timestamp(),
 foreign key(user_id,project_id) references public.user_memoir_project(user_id,project_id) on delete cascade,
 unique(user_id,project_id,request_id),
 check(candidate is null or octet_length(candidate::text)<=1048576)
);
create unique index one_current_story_game on public.user_story_game(user_id,project_id)
 where state in ('pending','running','selection_required','review_required','published');
alter table public.user_story_game enable row level security;
revoke all on public.user_story_game from public,anon,authenticated,service_role;

create function public.story_game_composer(p_owner uuid,p_project text,p_material boolean default false) returns jsonb
language plpgsql security definer set search_path='' as $$
declare previous_owner text; head jsonb; page jsonb; item jsonb; chapters jsonb:='[]'; timeline jsonb;
 cursor_id text; event_ids jsonb; steps integer:=0;
begin
 previous_owner:=current_setting('request.jwt.claim.sub',true);
 perform set_config('request.jwt.claim.sub',p_owner::text,true);
 head:=public.read_lifetime_private_draft_head(p_project);
 if head->>'status' is distinct from 'ready' or head->>'snapshot_state' is distinct from 'completed'
   or head->'event_revision' is distinct from head->'current_event_revision' then
   raise exception 'GAME_COMPOSER_REQUIRED' using errcode='PT409';end if;
 if p_material then
   loop
     page:=public.read_lifetime_private_draft_page(p_project,(head->>'snapshot_id')::uuid,cursor_id,8);
     for item in select value from jsonb_array_elements(page->'records') loop
       if coalesce(length(item->'preview'->>'text'),0)=0 then continue;end if;
       event_ids:=jsonb_build_array(item->>'event_id');
       chapters:=chapters||jsonb_build_array(jsonb_build_object('chapter_id',item->>'id',
         'title',coalesce(item->'preview'->>'title','Memory'),'event_ids',event_ids,
         'blocks',jsonb_build_array(jsonb_build_object('text',item->'preview'->>'text','source_refs',item->'source_refs'))));
     end loop;
     steps:=steps+1;
     exit when (page->>'complete')::boolean;
     if steps>=16 then raise exception 'GAME_MANUSCRIPT_CAPACITY' using errcode='55000';end if;
     cursor_id:=page->>'next_cursor';
   end loop;
   select coalesce(jsonb_agg(public.memory_event_record(e) order by e.change_sequence,e.id),'[]') into timeline
     from public.user_memory_event e where e.user_id=p_owner and e.project_id=p_project and e.status='active';
 end if;
 perform set_config('request.jwt.claim.sub',coalesce(previous_owner,''),true);
 return jsonb_build_object('composer_snapshot_id',head->'snapshot_id','composer_root_digest',head->'root_digest',
   'composer_revision',head->'revision')||case when p_material then jsonb_build_object('chapters',chapters,'timeline',timeline) else '{}' end;
end $$;

create function public.story_game_context(p_owner uuid,p_project text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare context jsonb; edition public.user_formal_memoir_edition%rowtype;
 head public.user_formal_memoir_head%rowtype; mode jsonb; previous_owner text;
begin
 context:=public.lock_formal_memoir_context(p_owner,p_project);
 select * into head from public.user_formal_memoir_head where user_id=p_owner and project_id=p_project;
 select * into edition from public.user_formal_memoir_edition where id=head.edition_id and active;
 if not found then raise exception 'GAME_COMPLETION_REQUIRED' using errcode='PT409';end if;
 perform public.lock_formal_memoir_run(edition.run_id,null,false);
 if not exists(select 1 from public.user_story_game_consent where user_id=p_owner and project_id=p_project
   and edition_id=edition.id and revision=head.consent_revision and status='active'
   and policy_epoch=(context->>'policy_epoch')::bigint) then
   raise exception 'GAME_CONSENT_REQUIRED' using errcode='PT409';end if;
 previous_owner:=current_setting('request.jwt.claim.sub',true);
 perform set_config('request.jwt.claim.sub',p_owner::text,true);
 mode:=public.read_lifetime_current_mode(p_project);
 perform set_config('request.jwt.claim.sub',coalesce(previous_owner,''),true);
 if mode is null or mode->>'mode'<>'shape' or mode->>'reply_id' is null then
   raise exception 'GAME_CURRENT_SHAPE_REQUIRED' using errcode='PT409';end if;
 return context||public.story_game_composer(p_owner,p_project)||jsonb_build_object('edition_id',edition.id,'manuscript_digest',edition.digest,
   'consent_revision',head.consent_revision,'reply_id',mode->>'reply_id');
end $$;

create function public.lock_story_game(p_id uuid,p_token uuid default null,p_require_token boolean default false)
returns public.user_story_game language plpgsql security definer set search_path='' as $$
declare game public.user_story_game%rowtype; context jsonb;
begin
 select * into game from public.user_story_game where id=p_id;
 if not found then raise exception 'GAME_UNAVAILABLE' using errcode='42501';end if;
 context:=public.story_game_context(game.user_id,game.project_id);
 select * into game from public.user_story_game where id=p_id for update;
 if game.state='stale' or game.authority is distinct from context then
   raise exception 'GAME_AUTHORITY_CHANGED' using errcode='PT409';end if;
 if p_require_token and (game.state<>'running' or p_token is null or game.token is distinct from p_token
   or game.lease_until<=clock_timestamp()) then raise exception 'GAME_LEASE_CHANGED' using errcode='PT409';end if;
 return game;
end $$;

create function public.story_game_status_record(p_game public.user_story_game) returns jsonb
language sql stable security definer set search_path='' as $$
 select jsonb_build_object('game_id',p_game.id,'edition_id',p_game.edition_id,'status',p_game.state,
   'candidate_digest',p_game.candidate_digest,'attempts',p_game.attempts,'phase',p_game.phase,
   'pool_digest',p_game.pool_digest,'selected_count',jsonb_array_length(p_game.selection->'scene_ids'),
   'retryable',p_game.state='running' and p_game.lease_until<=clock_timestamp())
$$;

CREATE FUNCTION public.begin_story_game(p_project_id text,p_request_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare owner uuid:=auth.uid(); context jsonb; game public.user_story_game%rowtype;
begin
 if owner is null or p_request_id is null then raise exception 'GAME_OWNER_REQUIRED' using errcode='42501';end if;
 context:=public.story_game_context(owner,p_project_id);
 select * into game from public.user_story_game where user_id=owner and project_id=p_project_id and request_id=p_request_id;
 if found then
   game:=public.lock_story_game(game.id);return public.story_game_status_record(game);
 end if;
 update public.user_story_game set state='stale',candidate=null,review=null,scene_pool=null,pool_digest=null,selection=null,selection_digest=null,brief=null,token=null,lease_until=null,
   updated_at=clock_timestamp() where user_id=owner and project_id=p_project_id and authority is distinct from context
   and state in ('pending','running','selection_required','review_required','published');
 select * into game from public.user_story_game where user_id=owner and project_id=p_project_id
   and state in ('pending','running','selection_required','review_required','published');
 if found then game:=public.lock_story_game(game.id);return public.story_game_status_record(game);end if;
 insert into public.user_story_game(user_id,project_id,edition_id,request_id,authority)
 values(owner,p_project_id,(context->>'edition_id')::uuid,p_request_id,context) returning * into game;
 return public.story_game_status_record(game);
end $$;

create function public.claim_story_game(p_game_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare game public.user_story_game%rowtype;
begin
 game:=public.lock_story_game(p_game_id);
 if game.state in ('selection_required','review_required','published') then return public.story_game_status_record(game);end if;
 if game.phase='build' and (game.selection is null or game.selection_digest is null) then
   raise exception 'GAME_HUMAN_SELECTION_REQUIRED' using errcode='PT409';end if;
 if game.state='running' and game.lease_until>clock_timestamp() then
   return public.story_game_status_record(game)||jsonb_build_object('status','busy');end if;
 if game.attempts>=3 then raise exception 'GAME_ATTEMPT_LIMIT' using errcode='55000';end if;
 update public.user_story_game set state='running',token=gen_random_uuid(),lease_until=clock_timestamp()+
   case when phase='build' then interval '3600 seconds' else interval '900 seconds' end,
   attempts=attempts+1,updated_at=clock_timestamp() where id=p_game_id returning * into game;
 return public.story_game_status_record(game)||jsonb_build_object('token',game.token,'authority',game.authority);
end $$;

create table public.user_story_game_stage (
 game_id uuid not null references public.user_story_game(id) on delete cascade,
 stage text not null check(stage in ('analyze','concept','design','whitebox','art','production')),
 request_sha256 text not null check(request_sha256~'^[a-f0-9]{64}$'),
 result jsonb not null check(octet_length(result::text)<=524288),
 primary key(game_id,stage,request_sha256)
);
alter table public.user_story_game_stage enable row level security;
revoke all on public.user_story_game_stage from public,anon,authenticated,service_role;

create function public.read_story_game_stage(p_game_id uuid,p_token uuid,p_stage text,p_sha256 text) returns jsonb
language plpgsql security definer set search_path='' as $$
begin
 perform public.lock_story_game(p_game_id,p_token,true);
 return (select result from public.user_story_game_stage where game_id=p_game_id and stage=p_stage and request_sha256=p_sha256);
end $$;

create function public.save_story_game_stage(p_game_id uuid,p_token uuid,p_stage text,p_sha256 text,p_result jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare existing jsonb;
begin
 perform public.lock_story_game(p_game_id,p_token,true);
 if p_result->'receipt'->>'status' is distinct from 'completed'
   or jsonb_typeof(p_result->'receipt'->'requested_model') is distinct from 'string'
   or coalesce(length(btrim(p_result->'receipt'->>'requested_model')),0) not between 1 and 256
   or p_result->'receipt'->>'model' is distinct from p_result->'receipt'->>'requested_model'
   or not coalesce(p_result->'receipt'->>'reasoning_effort' in ('none','minimal','low','medium','high','xhigh','max'),false)
   or p_result->'receipt'->>'stage' is distinct from p_stage
   or p_result->'receipt'->>'request_sha256' is distinct from p_sha256 then
   raise exception 'GAME_STAGE_RECEIPT_INVALID' using errcode='22023';end if;
 select result into existing from public.user_story_game_stage where game_id=p_game_id and stage=p_stage and request_sha256=p_sha256;
 if existing is not null and existing is distinct from p_result then raise exception 'GAME_STAGE_CHANGED' using errcode='PT409';end if;
 insert into public.user_story_game_stage values(p_game_id,p_stage,p_sha256,p_result) on conflict do nothing;
 return p_result;
end $$;
revoke all on function public.read_story_game_stage(uuid,uuid,text,text),public.save_story_game_stage(uuid,uuid,text,text,jsonb)
 from public,anon,authenticated,service_role;
grant execute on function public.read_story_game_stage(uuid,uuid,text,text),public.save_story_game_stage(uuid,uuid,text,text,jsonb) to service_role;

create function public.read_story_game_input(p_game_id uuid,p_token uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare game public.user_story_game%rowtype; material jsonb;
begin
 game:=public.lock_story_game(p_game_id,p_token,true);
 material:=public.story_game_composer(game.user_id,game.project_id,true);
 if jsonb_array_length(material->'chapters')=0 or octet_length(material::text)>200000 then
   raise exception 'GAME_MANUSCRIPT_CAPACITY' using errcode='55000';end if;
 return jsonb_build_object('game_id',game.id,'authority',game.authority,
   'chapters',material->'chapters','timeline',material->'timeline','phase',game.phase,
   'scene_pool',game.scene_pool,'selection',game.selection,'selection_digest',game.selection_digest,'brief',game.brief);
end $$;

create function public.validate_story_game_scenes(p_material jsonb,p_scenes jsonb,p_coverage boolean) returns void
language plpgsql set search_path='' as $$
declare item jsonb; chapter jsonb; block jsonb; quote_text text; label text; start_at integer; covered jsonb:='[]';
begin
 if jsonb_typeof(p_scenes) is distinct from 'array' or jsonb_array_length(p_scenes) not between 1 and 128 then
   raise exception 'GAME_SCENE_INVALID' using errcode='22023';end if;
 for item in select value from jsonb_array_elements(p_scenes) loop
   if jsonb_typeof(item)<>'object' or (select count(*) from jsonb_object_keys(item))<>6
     or not (item ?& array['chapter_id','block_index','title','person','quote','event_ids'])
     or exists(select 1 from unnest(array['chapter_id','title','quote']) k where jsonb_typeof(item->k) is distinct from 'string')
     or jsonb_typeof(item->'person') not in ('string','null')
     or jsonb_typeof(item->'block_index') is distinct from 'number' or item->>'block_index' !~ '^[0-7]$'
     or jsonb_typeof(item->'event_ids') is distinct from 'array' or jsonb_array_length(item->'event_ids') not between 1 and 128
     or exists(select 1 from jsonb_array_elements(item->'event_ids') e where jsonb_typeof(e)<>'string') then
     raise exception 'GAME_SCENE_INVALID' using errcode='22023';end if;
   select c into chapter from jsonb_array_elements(p_material->'chapters') c where c->>'chapter_id'=item->>'chapter_id';
   block:=chapter->'blocks'->(item->>'block_index')::integer;
   quote_text:=item->>'quote';label:=item->>'person';
   if chapter is null or block is null or length(quote_text) not between 1 and 400
     or (label is not null and length(label) not between 2 and 80) or length(item->>'title') not between 1 and 100
     or quote_text~'[<>[:cntrl:]]' or label~'[<>[:cntrl:]]'
     or (label is not null and strpos(quote_text,label)=0) or strpos(quote_text,item->>'title')=0
     or not ((chapter->'event_ids') @> (item->'event_ids'))
     or (select count(distinct value) from jsonb_array_elements(item->'event_ids'))<>jsonb_array_length(item->'event_ids')
     or exists(select 1 from jsonb_array_elements_text(item->'event_ids') id where not exists(
       select 1 from jsonb_array_elements(p_material->'timeline') e where e->>'id'=id)) then
     raise exception 'GAME_GROUNDING_INVALID' using errcode='22023';end if;
   start_at:=strpos(block->>'text',quote_text)-1;
   if start_at<0 or strpos(substring(block->>'text' from start_at+2),quote_text)>0 then
     raise exception 'GAME_EXACT_QUOTE_REQUIRED' using errcode='22023';end if;
   covered:=covered||(item->'event_ids');
 end loop;
 if p_coverage and exists(select 1 from jsonb_array_elements(p_material->'timeline') e where not covered ? (e->>'id')) then
   raise exception 'GAME_TIMELINE_COVERAGE_REQUIRED' using errcode='22023';end if;
end $$;

create function public.save_story_game_pool(p_game_id uuid,p_token uuid,p_pool jsonb,p_model_receipt jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare game public.user_story_game%rowtype; material jsonb; bare jsonb; item jsonb; stages text[];
 options jsonb:='[]'; prepared jsonb; i integer:=0;
begin
 game:=public.lock_story_game(p_game_id,p_token,true);
 if game.phase<>'scenes' or game.selection is not null or jsonb_typeof(p_pool) is distinct from 'object'
   or (select count(*) from jsonb_object_keys(p_pool))<>1 or jsonb_typeof(p_pool->'scenes') is distinct from 'array'
   or p_model_receipt->>'status' is distinct from 'completed' or coalesce(length(p_model_receipt->>'response_id'),0)=0
   or coalesce(length(p_model_receipt->>'model'),0)=0 then
   raise exception 'GAME_POOL_INVALID' using errcode='22023';end if;
 material:=public.read_story_game_input(p_game_id,p_token);
 select jsonb_agg(value-'recommended'-'reason') into bare from jsonb_array_elements(p_pool->'scenes');
 perform public.validate_story_game_scenes(material,bare,true);
 for item in select value from jsonb_array_elements(p_pool->'scenes') loop
   if (select count(*) from jsonb_object_keys(item))<>8 or jsonb_typeof(item->'recommended') is distinct from 'boolean'
     or jsonb_typeof(item->'reason') is distinct from 'string' or length(item->>'reason') not between 1 and 240
     or exists(select 1 from jsonb_array_elements(options) o where o->>'chapter_id'=item->>'chapter_id'
       and o->'block_index'=item->'block_index' and o->>'quote'=item->>'quote') then
     raise exception 'GAME_POOL_INVALID' using errcode='22023';end if;
   select array_agg(distinct coalesce(nullif(e->>'life_stage',''),'unplaced')) into stages
     from jsonb_array_elements(material->'timeline') e where item->'event_ids' ? (e->>'id');
   if cardinality(stages)<>1 then raise exception 'GAME_POOL_MIXED_STAGE' using errcode='22023';end if;
   i:=i+1;
   options:=options||jsonb_build_array(item||jsonb_build_object('id','scene-'||i,'life_stage',stages[1]));
 end loop;
 if exists(select 1 from jsonb_array_elements(options) o where not exists(select 1 from jsonb_array_elements(options) r
   where r->>'life_stage'=o->>'life_stage' and r->'recommended'='true')) then
   raise exception 'GAME_STAGE_RECOMMENDATION_REQUIRED' using errcode='22023';end if;
 prepared:=jsonb_build_object('scenes',options);
 update public.user_story_game set scene_pool=prepared,pool_digest=public.formal_memoir_digest(prepared),
   state='selection_required',token=null,lease_until=null,attempts=0,
   model_receipt=jsonb_build_object('steps',jsonb_build_object('scenes',p_model_receipt)),updated_at=clock_timestamp()
   where id=game.id returning * into game;
 return public.story_game_status_record(game);
end $$;

create function public.confirm_story_game_scenes(p_project_id text,p_game_id uuid,p_expected_digest text,p_scene_ids jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare game public.user_story_game%rowtype; chosen jsonb; confirmed jsonb;
begin
 if not exists(select 1 from public.user_story_game where id=p_game_id and user_id=auth.uid() and project_id=p_project_id) then
   raise exception 'GAME_OWNER_REQUIRED' using errcode='42501';end if;
 game:=public.lock_story_game(p_game_id);
 if game.pool_digest is null or game.pool_digest is distinct from p_expected_digest then
   raise exception 'GAME_POOL_CHANGED' using errcode='PT409';end if;
 if jsonb_typeof(p_scene_ids) is distinct from 'array' or jsonb_array_length(p_scene_ids) not between 1 and 128
   or exists(select 1 from jsonb_array_elements(p_scene_ids) id where jsonb_typeof(id)<>'string')
   or (select count(distinct value) from jsonb_array_elements(p_scene_ids))<>jsonb_array_length(p_scene_ids) then
   raise exception 'GAME_SELECTION_INVALID' using errcode='22023';end if;
 select jsonb_agg(o->'id' order by position) into chosen
   from jsonb_array_elements(game.scene_pool->'scenes') with ordinality as option(o,position) where p_scene_ids ? (o->>'id');
 if chosen is null or jsonb_array_length(chosen)<>jsonb_array_length(p_scene_ids) then
   raise exception 'GAME_SELECTION_INVALID' using errcode='22023';end if;
 if game.selection is not null then
   if game.selection->'scene_ids' is distinct from chosen then raise exception 'GAME_SELECTION_CHANGED' using errcode='PT409';end if;
   return public.story_game_status_record(game);
 end if;
 if game.state<>'selection_required' then raise exception 'GAME_SELECTION_NOT_READY' using errcode='PT409';end if;
 confirmed:=jsonb_build_object('scene_ids',chosen,'pool_digest',game.pool_digest);
 update public.user_story_game set selection=confirmed||jsonb_build_object('confirmed_by',auth.uid(),'confirmed_at',clock_timestamp()),
   selection_digest=public.formal_memoir_digest(confirmed),phase='build',state='pending',attempts=0,updated_at=clock_timestamp()
   where id=game.id returning * into game;
 return public.story_game_status_record(game);
end $$;

create function public.save_story_game_brief(p_game_id uuid,p_token uuid,p_brief jsonb,p_model_receipt jsonb) returns void
language plpgsql security definer set search_path='' as $$
declare game public.user_story_game%rowtype; expected jsonb;
begin
 game:=public.lock_story_game(p_game_id,p_token,true);
 select jsonb_agg(i) into expected from generate_series(0,jsonb_array_length(game.selection->'scene_ids')-1) i;
 if game.phase<>'build' or game.selection is null or jsonb_typeof(p_brief) is distinct from 'object'
   or (select count(*) from jsonb_object_keys(p_brief))<>2 or p_brief->'scene_indices' is distinct from expected
   or jsonb_typeof(p_brief->'design_brief') is distinct from 'string' or length(p_brief->>'design_brief') not between 1 and 6000
   or p_model_receipt->>'status' is distinct from 'completed' or coalesce(length(p_model_receipt->>'response_id'),0)=0
   or coalesce(length(p_model_receipt->>'model'),0)=0 then raise exception 'GAME_BRIEF_INVALID' using errcode='22023';end if;
 if game.brief is not null and game.brief is distinct from p_brief then raise exception 'GAME_BRIEF_CHANGED' using errcode='PT409';end if;
 update public.user_story_game set brief=p_brief,model_receipt=jsonb_set(model_receipt,'{steps,brief}',p_model_receipt),
   updated_at=clock_timestamp() where id=game.id;
end $$;

-- A project URL publishes a game artifact, never its underlying memoir sources.
create table public.user_story_game_page (
 project_id text primary key, user_id uuid not null,
 game_id uuid references public.user_story_game(id) on delete cascade,
 example jsonb,
 visibility text not null default 'private' check(visibility in ('private','friends','public')),
 revision bigint not null default 1, content_revision bigint not null default 1,
 updated_at timestamptz not null default clock_timestamp(),
 foreign key(user_id,project_id) references public.user_memoir_project(user_id,project_id) on delete cascade,
 check(num_nonnulls(game_id,example)=1),
 check(example is null or octet_length(example::text)<=262144)
);
create table public.user_story_game_invitation (
 id uuid primary key default gen_random_uuid(),
 project_id text not null references public.user_story_game_page(project_id) on delete cascade,
 content_revision bigint not null, email text not null check(length(email) between 3 and 254),
 token_digest text not null unique, expires_at timestamptz not null,
 accepted_by uuid references auth.users(id) on delete cascade,
 revoked_at timestamptz,
 unique(project_id,content_revision,email)
);
alter table public.user_story_game_page enable row level security;
alter table public.user_story_game_invitation enable row level security;
revoke all on public.user_story_game_page,public.user_story_game_invitation from public,anon,authenticated,service_role;

create function public.link_story_game_page(p_game_id uuid) returns void
language plpgsql security definer set search_path='' as $$
declare game public.user_story_game%rowtype;
begin
 select * into strict game from public.user_story_game where id=p_game_id and state='published';
 insert into public.user_story_game_page as page(project_id,user_id,game_id)
 values(game.project_id,game.user_id,game.id)
 on conflict(project_id) do update set game_id=excluded.game_id,example=null,visibility='private',
   revision=page.revision+1,content_revision=page.content_revision+1,updated_at=clock_timestamp()
 where page.user_id=excluded.user_id;
 if not found then raise exception 'GAME_OWNER_REQUIRED' using errcode='42501';end if;
end $$;

create function public.story_game_page_allowed(p_page public.user_story_game_page) returns boolean
language sql stable security definer set search_path='' as $$
 select p_page.user_id=auth.uid() or p_page.visibility='public' or
   (p_page.visibility='friends' and exists(select 1 from public.user_story_game_invitation invitation
     where invitation.project_id=p_page.project_id and invitation.content_revision=p_page.content_revision
       and invitation.accepted_by=auth.uid() and invitation.revoked_at is null))
$$;

create function public.read_story_game_page(p_project_id text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare page public.user_story_game_page%rowtype; locked public.user_story_game_page%rowtype;
 game public.user_story_game%rowtype; content jsonb;
begin
 select * into page from public.user_story_game_page where project_id=p_project_id;
 if not found or not coalesce(public.story_game_page_allowed(page),false) then
   raise exception 'GAME_UNAVAILABLE' using errcode='PT404';end if;
 -- Canonical source locks precede the page lock, matching generation's order.
 if page.game_id is not null then
   game:=public.lock_story_game(page.game_id);
   if game.state<>'published' then raise exception 'GAME_UNAVAILABLE' using errcode='PT404';end if;
 end if;
 select * into locked from public.user_story_game_page where project_id=p_project_id for update;
 if not found or locked.content_revision<>page.content_revision then
   raise exception 'GAME_CHANGED' using errcode='PT409';end if;
 if not coalesce(public.story_game_page_allowed(locked),false) then
   raise exception 'GAME_UNAVAILABLE' using errcode='PT404';end if;
 content:=case when page.game_id is not null then game.candidate->'game' else locked.example->'game' end;
 return jsonb_build_object('project_id',locked.project_id,'status','published','game',content,
   'visibility',locked.visibility,'revision',locked.revision,'example',locked.example is not null,
   'can_manage',coalesce(locked.user_id=auth.uid(),false),
   'invitations',case when locked.user_id=auth.uid() then coalesce((select jsonb_agg(jsonb_build_object(
     'id',invitation.id,'email',invitation.email,'accepted',invitation.accepted_by is not null,
     'expires_at',invitation.expires_at) order by invitation.email)
     from public.user_story_game_invitation invitation where invitation.project_id=p_project_id
       and invitation.content_revision=locked.content_revision and invitation.revoked_at is null),'[]') else '[]' end);
end $$;

create function public.set_story_game_visibility(p_project_id text,p_visibility text,p_expected_revision bigint) returns jsonb
language plpgsql security definer set search_path='' as $$
declare page public.user_story_game_page%rowtype;
begin
 select * into page from public.user_story_game_page where project_id=p_project_id and user_id=auth.uid() for update;
 if not found then raise exception 'GAME_OWNER_REQUIRED' using errcode='42501';end if;
 if page.revision<>p_expected_revision then raise exception 'GAME_CHANGED' using errcode='PT409';end if;
 if p_visibility not in ('private','friends','public') or p_visibility is null then
   raise exception 'GAME_VISIBILITY_INVALID' using errcode='22023';end if;
 update public.user_story_game_page set visibility=p_visibility,revision=revision+1,updated_at=clock_timestamp()
   where project_id=p_project_id returning * into page;
 return jsonb_build_object('visibility',page.visibility,'revision',page.revision);
end $$;

create function public.invite_story_game_viewer(p_project_id text,p_email text,p_expected_revision bigint) returns jsonb
language plpgsql security definer set search_path='' as $$
declare page public.user_story_game_page%rowtype; invitation public.user_story_game_invitation%rowtype;
 token text:=replace(gen_random_uuid()::text||gen_random_uuid()::text,'-',''); invite_email text:=lower(btrim(p_email));
begin
 select * into page from public.user_story_game_page where project_id=p_project_id and user_id=auth.uid() for update;
 if not found then raise exception 'GAME_OWNER_REQUIRED' using errcode='42501';end if;
 if page.revision<>p_expected_revision or page.visibility<>'friends' then
   raise exception 'GAME_CHANGED' using errcode='PT409';end if;
 if invite_email is null or length(invite_email)>254 or invite_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
   raise exception 'GAME_EMAIL_INVALID' using errcode='22023';end if;
 insert into public.user_story_game_invitation as old(project_id,content_revision,email,token_digest,expires_at)
 values(p_project_id,page.content_revision,invite_email,public.formal_memoir_digest(to_jsonb(token)),clock_timestamp()+interval '7 days')
 on conflict(project_id,content_revision,email) do update set token_digest=excluded.token_digest,
   expires_at=excluded.expires_at,accepted_by=null,revoked_at=null
 where old.accepted_by is null or old.revoked_at is not null returning * into invitation;
 if not found then raise exception 'GAME_ALREADY_INVITED' using errcode='PT409';end if;
 update public.user_story_game_page set revision=revision+1,updated_at=clock_timestamp() where project_id=p_project_id;
 return jsonb_build_object('invitation_id',invitation.id,'email',invite_email,'token',token,'expires_at',invitation.expires_at);
end $$;

create function public.accept_story_game_invitation(p_project_id text,p_token text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare page public.user_story_game_page%rowtype; invitation public.user_story_game_invitation%rowtype; email text;
begin
 if auth.uid() is null then raise exception 'GAME_SIGN_IN_REQUIRED' using errcode='42501';end if;
 select * into page from public.user_story_game_page where project_id=p_project_id for update;
 select * into invitation from public.user_story_game_invitation where project_id=p_project_id
   and token_digest=public.formal_memoir_digest(to_jsonb(p_token)) and revoked_at is null;
 if page.project_id is null or invitation.id is null or page.visibility<>'friends'
   or invitation.content_revision<>page.content_revision then
   raise exception 'GAME_INVITATION_UNAVAILABLE' using errcode='PT404';end if;
 if invitation.accepted_by=auth.uid() then return jsonb_build_object('accepted',true);end if;
 select lower(u.email) into email from auth.users u where u.id=auth.uid() and u.email_confirmed_at is not null and not u.is_anonymous;
 if email is null or email<>invitation.email or invitation.expires_at<=clock_timestamp()
   or invitation.accepted_by is not null then
   raise exception 'GAME_INVITATION_UNAVAILABLE' using errcode='PT404';end if;
 update public.user_story_game_invitation set accepted_by=auth.uid() where id=invitation.id;
 return jsonb_build_object('accepted',true);
end $$;

create function public.revoke_story_game_invitation(p_project_id text,p_invitation_id uuid,p_expected_revision bigint) returns jsonb
language plpgsql security definer set search_path='' as $$
declare page public.user_story_game_page%rowtype;
begin
 select * into page from public.user_story_game_page where project_id=p_project_id and user_id=auth.uid() for update;
 if not found then raise exception 'GAME_OWNER_REQUIRED' using errcode='42501';end if;
 if page.revision<>p_expected_revision then raise exception 'GAME_CHANGED' using errcode='PT409';end if;
 update public.user_story_game_invitation set revoked_at=clock_timestamp()
   where id=p_invitation_id and project_id=p_project_id and revoked_at is null;
 update public.user_story_game_page set revision=revision+1,updated_at=clock_timestamp() where project_id=p_project_id;
 return jsonb_build_object('revoked',true);
end $$;

-- Only the trusted live-example runner can attach a labelled fictional artifact.
create function public.save_story_game_example(p_owner uuid,p_project_id text,p_result jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare payload jsonb;
begin
 if p_result->'synthetic' is distinct from 'true'::jsonb
   or p_result->'steps'->'scenes'->>'status' is distinct from 'completed'
   or p_result->'steps'->'webpage'->>'status' is distinct from 'completed'
   or p_result->'steps'->'webpage'->>'requested_model' is distinct from 'gpt-6-astra'
   or octet_length(p_result->>'html') not between 100 and 150000
   or jsonb_typeof(p_result->'scenes') is distinct from 'array' then
   raise exception 'GAME_EXAMPLE_INVALID' using errcode='22023';end if;
 payload:=jsonb_build_object('game',public.story_game_package(p_result->'scenes',p_result->>'html',p_result->>'locale'),
   'receipt',p_result->'steps','input_sha256',p_result->'input_sha256');
 insert into public.user_story_game_page as page(project_id,user_id,example) values(p_project_id,p_owner,payload)
 on conflict(project_id) do update set game_id=null,example=excluded.example,visibility='private',
   revision=page.revision+1,content_revision=page.content_revision+1,updated_at=clock_timestamp()
 where page.user_id=excluded.user_id;
 if not found then raise exception 'GAME_OWNER_REQUIRED' using errcode='42501';end if;
 return jsonb_build_object('project_id',p_project_id,'visibility','private','example',true);
end $$;

revoke all on function public.link_story_game_page(uuid),public.story_game_page_allowed(public.user_story_game_page),
 public.read_story_game_page(text),public.set_story_game_visibility(text,text,bigint),
 public.invite_story_game_viewer(text,text,bigint),public.accept_story_game_invitation(text,text),
 public.revoke_story_game_invitation(text,uuid,bigint),public.save_story_game_example(uuid,text,jsonb)
 from public,anon,authenticated,service_role;
grant execute on function public.read_story_game_page(text) to anon,authenticated;
grant execute on function public.set_story_game_visibility(text,text,bigint),public.invite_story_game_viewer(text,text,bigint),
 public.accept_story_game_invitation(text,text),public.revoke_story_game_invitation(text,uuid,bigint) to authenticated;
grant execute on function public.save_story_game_example(uuid,text,jsonb) to service_role;

create function public.story_game_package(p_plan jsonb,p_html text,p_locale text) returns jsonb
language plpgsql set search_path='' as $$
declare scene_ids uuid[]; title_ids uuid[]; alias_ids uuid[]; line_ids uuid[];
 author_id uuid:=gen_random_uuid(); texts jsonb:='[]'; scenes jsonb:='[]'; npcs jsonb:='[]';
 item jsonb; i integer:=0; total integer:=jsonb_array_length(p_plan);
begin
 if total not between 1 and 128 then raise exception 'GAME_SCENE_INVALID' using errcode='22023';end if;
 select array_agg(gen_random_uuid()),array_agg(gen_random_uuid()),array_agg(gen_random_uuid()),array_agg(gen_random_uuid())
   into scene_ids,title_ids,alias_ids,line_ids from generate_series(1,total);
 for item in select value from jsonb_array_elements(p_plan) loop
   i:=i+1;
   texts:=texts||jsonb_build_array(jsonb_build_object('id',title_ids[i],'text',item->>'title'),
     jsonb_build_object('id',alias_ids[i],'text',coalesce(item->>'person',
       case when p_locale='zh-CN' then '回忆 ' else 'Memory ' end||i)),
     jsonb_build_object('id',line_ids[i],'text',item->>'quote'));
   scenes:=scenes||jsonb_build_array(jsonb_build_object('id',scene_ids[i],'title_text_id',title_ids[i],
     'asset_key','generic-garden','width',1280,'spawn_x',80,
     'left',case when i=1 then null else jsonb_build_object('scene_id',scene_ids[i-1],'spawn_x',1100) end,
     'right',case when i=total then null else jsonb_build_object('scene_id',scene_ids[i+1],'spawn_x',80) end));
   npcs:=npcs||jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'scene_id',scene_ids[i],'x',640,
     'alias_text_id',alias_ids[i],'asset_key','generic-adult','dialogue_text_ids',jsonb_build_array(line_ids[i])));
 end loop;
 texts:=texts||jsonb_build_array(jsonb_build_object('id',author_id,'text',case when p_locale='zh-CN' then '我' else 'Me' end));
 return jsonb_build_object('schema_version','memoir-story-game-play/1','package_id',gen_random_uuid(),
   'renderer','fixed-side-scroll-v1','audience','private','title_text_id',title_ids[1],'texts',texts,
   'protagonist',jsonb_build_object('id',gen_random_uuid(),'alias_text_id',author_id,'asset_key','generic-author'),
   'start_scene_id',scene_ids[1],'scenes',scenes,'npcs',npcs,
   'controls',jsonb_build_object('keyboard',true,'touch',true,'text_equivalent',true,'reduced_motion',true),
   'webpage',p_html);
end $$;
revoke all on function public.story_game_package(jsonb,text,text) from public,anon,authenticated,service_role;

create function public.stage_story_game(p_game_id uuid,p_token uuid,p_proposal jsonb,p_model_receipt jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare game public.user_story_game%rowtype; material jsonb; expected jsonb; package jsonb; prepared jsonb;
 novel boolean:=p_model_receipt->>'skill'='novel-to-game'; item jsonb; memory_index integer;
begin
 game:=public.lock_story_game(p_game_id,p_token,true);
 if game.phase<>'build' or game.selection is null or game.brief is null
   or p_model_receipt->>'selection_digest' is distinct from game.selection_digest
   or p_model_receipt->>'status' is distinct from 'completed'
   or coalesce(length(p_model_receipt->>'response_id'),0)=0
   or coalesce(length(p_model_receipt->>'model'),0)=0
   or jsonb_typeof(p_model_receipt->'requested_model') is distinct from 'string'
   or coalesce(length(btrim(p_model_receipt->>'requested_model')),0) not between 1 and 256
   or p_model_receipt->>'model' is distinct from p_model_receipt->>'requested_model'
   or not coalesce(p_model_receipt->>'reasoning_effort' in ('none','minimal','low','medium','high','xhigh','max'),false)
   or not coalesce(case when novel then p_model_receipt->'qa'->'desktop'->>'status'='PASS'
       and p_model_receipt->'qa'->'touch'->>'status'='PASS'
       and p_model_receipt->'qa'->'desktop'->'checks'='{"launch":"PASS","render":"PASS","input":"PASS","coreLoop":"PASS","outcome":"PASS","restart":"PASS"}'::jsonb
       and p_model_receipt->'qa'->'touch'->'checks'='{"launch":"PASS","render":"PASS","input":"PASS","coreLoop":"PASS","outcome":"PASS","restart":"PASS"}'::jsonb
       and jsonb_array_length(p_model_receipt->'stages')=6
       else p_model_receipt->>'skill'='higgsfield-websites' end,false)
   or p_model_receipt->>'skill_sha256' !~ '^[a-f0-9]{64}$'
   or p_model_receipt->>'skill_sha256' is null
   or jsonb_typeof(p_proposal) is distinct from 'object' or (select count(*) from jsonb_object_keys(p_proposal))<>2
   or (not novel and (jsonb_typeof(p_proposal->'html') is distinct from 'string' or octet_length(p_proposal->>'html') not between 100 and 150000
     or p_proposal->>'html'~*'<[[:space:]]*(script|iframe|object|embed|base|link|form)([[:space:]>])')) then
   raise exception 'GAME_PROPOSAL_INVALID' using errcode='22023';end if;
 select jsonb_agg(o-'id'-'life_stage'-'recommended'-'reason' order by position) into expected
   from jsonb_array_elements(game.scene_pool->'scenes') with ordinality as option(o,position)
   where game.selection->'scene_ids' ? (o->>'id');
 if p_proposal->'scenes' is distinct from expected then raise exception 'GAME_SELECTION_CHANGED' using errcode='PT409';end if;
 material:=public.read_story_game_input(p_game_id,p_token);
 perform public.validate_story_game_scenes(material,expected,false);
 package:=public.story_game_package(expected,p_proposal->>'html',game.authority->>'locale');
 if novel then
   if jsonb_typeof(p_proposal->'novel_game') is distinct from 'object'
     or not coalesce((p_proposal->'novel_game'->>'version'='1' and (select count(*) from jsonb_object_keys(p_proposal->'novel_game'))=5)
       or (p_proposal->'novel_game'->>'version'='2' and (select count(*) from jsonb_object_keys(p_proposal->'novel_game'))=6
         and jsonb_typeof(p_proposal->'novel_game'->'illustrations')='array'
         and jsonb_array_length(p_proposal->'novel_game'->'illustrations') between 1 and 24),false)
     or octet_length((p_proposal->'novel_game')::text)>262144
     or jsonb_typeof(p_proposal->'novel_game'->'source'->'chapters') is distinct from 'array'
     or jsonb_array_length(p_proposal->'novel_game'->'source'->'chapters')<>jsonb_array_length(expected)
     or jsonb_typeof(p_proposal->'novel_game'->'css') is distinct from 'string'
     or length(p_proposal->'novel_game'->>'css')>24000
     or p_proposal->'novel_game'->>'css'~*'(<|url[[:space:]]*\(|@import|expression[[:space:]]*\()' then
     raise exception 'GAME_JOURNEY_INVALID' using errcode='22023';end if;
   for item in select value from jsonb_array_elements(coalesce(p_proposal->'novel_game'->'illustrations','[]')) loop
     if jsonb_typeof(item) is distinct from 'object' or (select count(*) from jsonb_object_keys(item))<>5
       or not (item ?& array['cache_key','sha256','width','height','scenes'])
       or jsonb_typeof(item->'cache_key') is distinct from 'string' or jsonb_typeof(item->'sha256') is distinct from 'string'
       or jsonb_typeof(item->'width') is distinct from 'number' or jsonb_typeof(item->'height') is distinct from 'number'
       or item->>'cache_key' !~ '^[a-f0-9]{64}/[a-f0-9]{64}$'
       or item->>'sha256' !~ '^[a-f0-9]{64}$'
       or item->>'width' !~ '^[0-9]{3,4}$' or item->>'height' !~ '^[0-9]{3,4}$'
       or (item->>'width')::integer not between 256 and 3840 or (item->>'height')::integer not between 256 and 3840
       or (item->>'width')::integer*(item->>'height')::integer>8294400
       or jsonb_typeof(item->'scenes') is distinct from 'array' or jsonb_array_length(item->'scenes') not between 1 and 128
       or exists(select 1 from jsonb_array_elements(item->'scenes') s where jsonb_typeof(s)<>'string' or s#>>'{}' !~ '^[a-z][a-z0-9-]{0,47}$') then
       raise exception 'GAME_JOURNEY_INVALID' using errcode='22023';end if;
   end loop;
   memory_index:=0;
   for item in select value from jsonb_array_elements(expected) loop
     if p_proposal->'novel_game'->'source'->'chapters'->memory_index is distinct from
       jsonb_build_object('id','C'||(memory_index+1),'title',item->>'title','text',item->>'quote') then
       raise exception 'GAME_SELECTION_CHANGED' using errcode='PT409';end if;
     memory_index:=memory_index+1;
   end loop;
   package:=(package-'webpage')||jsonb_build_object('renderer','memoir-linear-v2','novel_game',p_proposal->'novel_game');
 end if;
 prepared:=jsonb_build_object('game',package,'scene_plan',p_proposal-'html'-'novel_game');
 update public.user_story_game set candidate=prepared,candidate_digest=public.formal_memoir_digest(prepared),
   model_receipt=jsonb_set(game.model_receipt,case when novel then '{steps,novel-to-game}'::text[] else '{steps,higgsfield}'::text[] end,p_model_receipt),state='published',
   review=null,token=null,lease_until=null,updated_at=clock_timestamp() where id=game.id returning * into game;
 perform public.link_story_game_page(game.id);
 return public.story_game_status_record(game);
end $$;

CREATE FUNCTION public.read_story_game(p_project_id text,p_game_id uuid,p_review boolean default false) returns jsonb
language plpgsql security definer set search_path='' as $$
declare game public.user_story_game%rowtype;
begin
 if not exists(select 1 from public.user_story_game where id=p_game_id and user_id=auth.uid() and project_id=p_project_id) then
   raise exception 'GAME_OWNER_REQUIRED' using errcode='42501';end if;
 game:=public.lock_story_game(p_game_id);
 if game.state='published' then return jsonb_build_object('game_id',game.id,'status','published','game',game.candidate->'game');end if;
 if game.scene_pool is not null then
   return public.story_game_status_record(game)||jsonb_build_object('pool',jsonb_build_object('scenes',
     (select jsonb_agg(o-'chapter_id'-'block_index'-'event_ids' order by position)
      from jsonb_array_elements(game.scene_pool->'scenes') with ordinality as option(o,position))),
     'selected_scene_ids',game.selection->'scene_ids');
 end if;
 if p_review and game.state='review_required' then
   return public.story_game_status_record(game)||jsonb_build_object('preview',game.candidate->'game','people',
     (select jsonb_agg(person-'chapter_id'-'source_id'-'source_version'-'char_start'-'char_end') from jsonb_array_elements(game.candidate->'people') person));
 end if;
 return public.story_game_status_record(game);
end $$;

create function public.publish_story_game(p_project_id text,p_game_id uuid,p_expected_digest text,p_permissions jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare game public.user_story_game%rowtype; person jsonb; permission jsonb;
begin
 if not exists(select 1 from public.user_story_game where id=p_game_id and user_id=auth.uid() and project_id=p_project_id) then
   raise exception 'GAME_OWNER_REQUIRED' using errcode='42501';end if;
 game:=public.lock_story_game(p_game_id);
 if p_expected_digest is distinct from game.candidate_digest or game.state not in ('review_required','published') then
   raise exception 'GAME_REVIEW_CHANGED' using errcode='PT409';end if;
 if jsonb_typeof(p_permissions) is distinct from 'array' or jsonb_array_length(p_permissions)<>2 then
   raise exception 'GAME_PERSON_PERMISSION_REQUIRED' using errcode='22023';end if;
 for person in select value from jsonb_array_elements(game.candidate->'people') loop
   select value into permission from jsonb_array_elements(p_permissions) where value->>'person_id'=person->>'person_id';
   if permission is null or (select count(*) from jsonb_object_keys(permission))<>4
     or permission->'adult' is distinct from 'true'::jsonb or permission->'permitted' is distinct from 'true'::jsonb
     or permission->'distinct_person' is distinct from 'true'::jsonb then
     raise exception 'GAME_PERSON_PERMISSION_REQUIRED' using errcode='22023';end if;
 end loop;
 if game.state='published' then return public.story_game_status_record(game);end if;
 update public.user_story_game set state='published',review=jsonb_build_object('reviewer_id',auth.uid(),
   'candidate_digest',p_expected_digest,'permissions',p_permissions,'purpose','game_adaptation','audience','private',
   'authority',game.authority,'approved_at',clock_timestamp()),updated_at=clock_timestamp()
   where id=game.id returning * into game;
 return public.story_game_status_record(game);
end $$;

create function public.fail_story_game(p_game_id uuid,p_token uuid) returns void
language plpgsql security definer set search_path='' as $$
begin
 perform public.lock_story_game(p_game_id,p_token,true);
 update public.user_story_game set state='failed',token=null,lease_until=null,updated_at=clock_timestamp() where id=p_game_id;
end $$;



create function public.read_story_game_status(p_project_id text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare game public.user_story_game%rowtype; eligibility jsonb; composer jsonb;
begin
 eligibility:=public.read_story_game_eligibility(p_project_id);
 composer:=public.read_lifetime_private_draft_head(p_project_id);
 select * into game from public.user_story_game where user_id=auth.uid() and project_id=p_project_id
   order by created_at desc,id desc limit 1;
 if game.id is not null and game.state<>'stale' and
   (game.authority->'composer_snapshot_id' is distinct from composer->'snapshot_id'
    or game.authority->'composer_root_digest' is distinct from composer->'root_digest'
    or game.authority->'composer_revision' is distinct from composer->'revision') then
   update public.user_story_game set state='stale',candidate=null,review=null,scene_pool=null,pool_digest=null,selection=null,selection_digest=null,brief=null,token=null,lease_until=null,
     updated_at=clock_timestamp() where id=game.id returning * into game;
 end if;
 return jsonb_build_object('eligibility',eligibility,'formal',public.read_formal_memoir_status(p_project_id),
   'composer_ready',coalesce(composer->>'status'='ready' and composer->>'snapshot_state'='completed'
     and composer->'event_revision'=composer->'current_event_revision',false),
   'adaptation',case when game.id is not null then public.story_game_status_record(game) end);
end $$;

create function public.invalidate_story_games() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 update public.user_story_game set state='stale',candidate=null,review=null,scene_pool=null,pool_digest=null,selection=null,selection_digest=null,brief=null,token=null,lease_until=null,updated_at=clock_timestamp()
   where user_id=new.user_id and project_id=new.project_id and state<>'stale';
 return new;
end $$;
create trigger story_game_edition_invalidation after update of active on public.user_formal_memoir_edition
 for each row when(old.active and not new.active) execute function public.invalidate_story_games();
create trigger story_game_consent_invalidation after update of consent_revision on public.user_formal_memoir_head
 for each row when(old.consent_revision is distinct from new.consent_revision) execute function public.invalidate_story_games();

revoke all on function public.story_game_composer(uuid,text,boolean),public.story_game_context(uuid,text),public.lock_story_game(uuid,uuid,boolean),
 public.story_game_status_record(public.user_story_game),public.begin_story_game(text,uuid),
 public.claim_story_game(uuid),public.read_story_game_input(uuid,uuid),public.stage_story_game(uuid,uuid,jsonb,jsonb),
 public.read_story_game(text,uuid,boolean),public.publish_story_game(text,uuid,text,jsonb),public.fail_story_game(uuid,uuid),
 public.read_story_game_status(text),public.invalidate_story_games(),public.validate_story_game_scenes(jsonb,jsonb,boolean),
 public.save_story_game_pool(uuid,uuid,jsonb,jsonb),public.confirm_story_game_scenes(text,uuid,text,jsonb),
 public.save_story_game_brief(uuid,uuid,jsonb,jsonb) from public,anon,authenticated,service_role;
 grant execute on function public.confirm_story_game_scenes(text,uuid,text,jsonb) to authenticated;
 grant execute on function public.save_story_game_pool(uuid,uuid,jsonb,jsonb),public.save_story_game_brief(uuid,uuid,jsonb,jsonb) to service_role;
grant execute on function public.begin_story_game(text,uuid),public.read_story_game(text,uuid,boolean),
 public.publish_story_game(text,uuid,text,jsonb),public.read_story_game_status(text) to authenticated;
grant execute on function public.claim_story_game(uuid),public.read_story_game_input(uuid,uuid),
 public.stage_story_game(uuid,uuid,jsonb,jsonb),public.fail_story_game(uuid,uuid),public.lock_story_game(uuid,uuid,boolean) to service_role;









-- Operator-scoped strategy rollout

-- Operator-selected owners can exercise the active strategy during a shadow rollout.
-- No owner is enrolled by this migration. Existing global kill switches still apply.
create table public.lifetime_strategy_active_owner (
 user_id uuid primary key references auth.users(id) on delete cascade,
 enabled boolean not null default true,
 created_at timestamptz not null default clock_timestamp()
);
alter table public.lifetime_strategy_active_owner enable row level security;
revoke all on public.lifetime_strategy_active_owner from public, anon, authenticated, service_role;
grant select, insert, update, delete on public.lifetime_strategy_active_owner to service_role;

create function public.lifetime_interview_strategy_rollout(p_owner uuid)
returns text language sql stable security definer set search_path='' as $$
 select coalesce((select case when not enabled or not strategy_enabled then 'disabled'
   when not strategy_shadow or exists(select 1 from public.lifetime_strategy_active_owner a
     where a.user_id=p_owner and a.enabled) then 'active' else 'shadow' end
   from public.lifetime_two_lane_rollout where singleton),'disabled');
$$;
revoke all on function public.lifetime_interview_strategy_rollout(uuid) from public, anon, authenticated, service_role;
grant execute on function public.lifetime_interview_strategy_rollout(uuid) to service_role;

CREATE INDEX user_story_game_edition_id_idx ON public.user_story_game(edition_id);

-- Search derived canonical evidence, never an all-history transcript prompt.
-- English stemming and Chinese bigrams keep dates out of retrieval identity.
CREATE FUNCTION public.lifetime_memory_search_terms(p_text text) RETURNS text[]
 LANGUAGE sql IMMUTABLE PARALLEL SAFE SET search_path='' AS $$
 select coalesce(array_agg(term order by term),'{}'::text[]) from (
   select distinct term from (
     select unnest(tsvector_to_array(to_tsvector('pg_catalog.english',regexp_replace(left(coalesce(p_text,''),8192),'[^A-Za-z ]',' ','g')))) term
     union all
     select substring(match[1] from position for 2) from regexp_matches(left(coalesce(p_text,''),8192),'[一-龥]{2,}','g') match
       cross join lateral generate_series(1,length(match[1])-1) position
   ) terms where length(term)>1 and term not in ('remember','memori','later','time','something','thing','also','时候','记得','后来','当时','我们','但是','自己')
   order by term
 ) bounded
$$;
CREATE INDEX user_memory_event_source_guidance_search_idx ON public.user_memory_event_source
 USING gin (public.lifetime_memory_search_terms(evidence->>'quote'));

-- Guidance receives only contiguous authorized originals. Subtract the union
-- of unavailable spans before taking a substring, retaining canonical Unicode
-- offsets on each side of a gap. Never concatenate words across a private span.
CREATE FUNCTION public.lifetime_guidance_source_windows(p_owner uuid,p_project text,p_source uuid,p_version bigint,p_lo integer,p_hi integer,p_tail boolean DEFAULT false)
 RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 with original as materialized (
   select s.*,greatest(0,p_lo) lo,least(length(s.text),p_hi) hi from public.user_narrator_source s
   where s.user_id=p_owner and s.project_id=p_project and s.id=p_source and s.version=p_version and s.status='active'
 ), authorized as (
   select s.*,int4multirange(int4range(s.lo,s.hi,'[)'))-coalesce((
     select range_agg(int4range(greatest(s.lo,w.char_start),least(s.hi,w.char_end),'[)'))
     from public.user_memory_attribution_window w where w.user_id=s.user_id and w.project_id=s.project_id
       and w.source_id=s.id and w.source_version=s.version and w.disposition in ('withheld','non_story')
       and w.char_start<s.hi and w.char_end>s.lo),'{}'::int4multirange) spans
   from original s where s.hi>s.lo
 )
 select jsonb_build_object('id',s.id,'project_id',s.project_id,'version',s.version,'sequence',s.sequence,
   'text',substring(s.text from bounds.lo+1 for bounds.hi-bounds.lo),
   'char_start',bounds.lo,'char_end',bounds.hi,'original_length',length(s.text),
   'kind',s.kind,'language',s.language,'status',s.status,'author_role','storyteller')
 from authorized s cross join lateral unnest(s.spans) span cross join lateral (
   select case when p_tail then greatest(lower(span),upper(span)-2304) else lower(span) end lo,
     case when p_tail then upper(span) else least(upper(span),lower(span)+2304) end hi
 ) bounds order by bounds.lo
$$;
REVOKE ALL ON FUNCTION public.lifetime_guidance_source_windows(uuid,text,uuid,bigint,integer,integer,boolean)
 FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION public.retrieve_lifetime_guidance_events(p_owner uuid,p_project text,p_source uuid,p_version bigint)
 RETURNS TABLE(event_id text,source_id uuid,version bigint,char_start integer,char_end integer,score bigint)
 LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 with current_original as materialized (
   select s.*,array(select term from unnest(public.lifetime_memory_search_terms((
       select string_agg(w->>'text',' ') from (
         select w from public.lifetime_guidance_source_windows(p_owner,p_project,s.id,s.version,0,least(length(s.text),2304)) w
         union all
         select w from public.lifetime_guidance_source_windows(p_owner,p_project,s.id,s.version,greatest(0,length(s.text)-2304),length(s.text)) w
       ) safe))) term
       order by length(term) desc,term limit 64) terms
   from public.user_narrator_source s where s.user_id=p_owner and s.project_id=p_project and s.id=p_source and s.version=p_version and s.status='active'
 ), matches as materialized (
   select hit.*,term from current_original current cross join lateral unnest(current.terms) term
   cross join lateral (
     select r.event_id,r.source_id,r.source_version,r.evidence_hash,r.evidence,n.sequence
     from public.user_memory_event_source r
     join public.user_memory_event e on e.user_id=r.user_id and e.project_id=r.project_id and e.id=r.event_id and e.status in ('active','unresolved')
     join public.user_narrator_source n on n.user_id=r.user_id and n.project_id=r.project_id and n.id=r.source_id and n.version=r.source_version and n.status='active'
     where r.user_id=p_owner and r.project_id=p_project and n.sequence<current.sequence
       and public.lifetime_memory_search_terms(r.evidence->>'quote') @> array[term]
       and not exists(select 1 from public.user_memory_attribution_window w where w.user_id=p_owner and w.project_id=p_project
         and w.source_id=n.id and w.source_version=n.version and w.disposition in ('withheld','non_story')
         and w.char_start<coalesce((r.evidence->>'char_end')::integer,length(n.text)) and w.char_end>coalesce((r.evidence->>'char_start')::integer,0))
     order by n.sequence desc,r.event_id,r.evidence_hash limit 8
   ) hit
 ), scored as (
   select m.event_id,m.source_id,m.source_version,m.evidence_hash,m.evidence,m.sequence,count(distinct term) score
   from matches m group by m.event_id,m.source_id,m.source_version,m.evidence_hash,m.evidence,m.sequence
   having count(distinct term)>=1
 ), selected as (
   select event_id,max(score) score,max(sequence) sequence from scored group by event_id order by score desc,sequence desc,event_id limit 4
 ), ranked as (
   select s.*,row_number() over(partition by s.event_id order by s.score desc,s.sequence,s.evidence_hash) position
   from scored s join selected chosen using(event_id)
 )
 select r.event_id,r.source_id,r.source_version,(r.evidence->>'char_start')::integer,(r.evidence->>'char_end')::integer,r.score
 from ranked r where position<=2 order by r.score desc,r.sequence,r.event_id,r.position limit 8
$$;
REVOKE ALL ON FUNCTION public.lifetime_memory_search_terms(text),public.retrieve_lifetime_guidance_events(uuid,text,uuid,bigint)
 FROM PUBLIC,anon,authenticated,service_role;

-- Interviewing guidance owns a separate, coalesced Lane B job. Timeline
-- extraction never waits for this model or writes its question/strategy output.
CREATE FUNCTION public.enqueue_lifetime_interview_guidance() RETURNS trigger
 LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
declare owner uuid; project text; p public.user_memoir_project%rowtype; locale text;
begin
 if tg_table_name='user_narrator_source' then
   if new.status<>'active' or new.processing_status<>'succeeded'
     or old.processing_status='succeeded' then return new;end if;
   if exists(select 1 from public.user_interview_turn t where t.user_id=new.user_id and t.project_id=new.project_id
     and t.source_id=new.id and t.source_version=new.version and t.collector->'plan'->'work'->>'mode'='reply_only') then return new;end if;
 else
   if new.status<>'ready' then return new;end if;
   if tg_op='UPDATE' and row(old.context_revision,old.status,old.evidence,old.relevance)
     is not distinct from row(new.context_revision,new.status,new.evidence,new.relevance) then return new;end if;
 end if;
 owner:=new.user_id;project:=new.project_id;
 if not exists(select 1 from public.lifetime_two_lane_rollout where singleton and enabled)
   or not exists(select 1 from public.user_lifetime_conversation where user_id=owner and project_id=project) then return new;end if;
 select * into p from public.user_memoir_project where user_id=owner and project_id=project for update;
 select case when profile->>'preferred_language'='zh-CN' then 'zh-CN' else 'en-AU' end into locale
   from public.user_profile where user_id=owner;
 insert into public.user_memoir_lane(user_id,project_id,skill,pending,target_source,target_event,locale,guidance_revision)
 values(owner,project,'guidance',true,p.source_sequence,p.event_sequence,coalesce(locale,'en-AU'),1)
 on conflict(user_id,project_id,skill) do update set pending=true,target_source=excluded.target_source,
   target_event=excluded.target_event,locale=excluded.locale,guidance_revision=public.user_memoir_lane.guidance_revision+1,
   attempts=0,error=null,available_at=clock_timestamp();
 return new;
end $$;

CREATE FUNCTION public.read_lifetime_interview_guidance_page(p_lane_id uuid,p_token uuid) RETURNS jsonb
 LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
declare snap public.user_lifetime_lane_snapshot%rowtype; lane public.user_memoir_lane%rowtype;
 page jsonb; pins jsonb; windows jsonb; events jsonb; news jsonb; context jsonb; dialogue jsonb; previous_owner text; planning text; revision bigint; matches jsonb; evidence record; lo integer; hi integer; fragment jsonb; unavailable jsonb; private_policy boolean;
begin
 snap:=public.lock_lifetime_memoir_lane(p_lane_id,p_token);
 select * into lane from public.user_memoir_lane where id=p_lane_id;
 if lane.skill<>'guidance' or not exists(select 1 from public.lifetime_two_lane_rollout where singleton and enabled) then
   raise exception 'guidance lane unavailable' using errcode='PT409';end if;
 previous_owner:=current_setting('request.jwt.claim.sub',true);
 perform set_config('request.jwt.claim.sub',snap.user_id::text,true);
 pins:=public.read_lifetime_pinned(snap.conversation_id);
 -- Optional continuity can contain another verbatim copy of private evidence.
 select coalesce(jsonb_agg(record),'[]') into unavailable from jsonb_array_elements(pins->'known_continuity') record
 where exists(select 1 from jsonb_array_elements(record->'data'->'source_refs') ref
   join public.user_memory_attribution_window w on w.user_id=snap.user_id and w.project_id=snap.project_id
     and w.source_id=(ref->>'source_id')::uuid and w.source_version=(ref->>'version')::bigint
   where w.disposition in ('withheld','non_story') and w.char_start<(ref->>'char_end')::integer and w.char_end>(ref->>'char_start')::integer);
 if jsonb_array_length(unavailable)>0 then pins:=jsonb_set(pins,'{known_continuity_complete}','false');end if;
 -- A safe citation authorizes its original words, never adjacent derived prose.
 -- Rebuild optional continuity text extractively and omit free-form uncertainty.
 if exists(select 1 from jsonb_array_elements(pins->'known_continuity') r where
   r->'data'->>'text' is distinct from left(r->'data'->'source_refs'->0->>'quote',2000)
   or coalesce(r->'data'->'uncertainty','null')<>'null'::jsonb) then
   pins:=jsonb_set(pins,'{known_continuity_complete}','false');
 end if;
 pins:=jsonb_set(pins,'{known_continuity}',coalesce((select jsonb_agg(
   jsonb_build_object('schema_version',1)||record||jsonb_build_object(
     'record_id','ct-'||encode(sha256(convert_to(jsonb_build_array(snap.user_id,snap.conversation_id,
       record->'record_id')::text,'UTF8')),'hex'),'data',
     (record->'data')||jsonb_build_object('schema_version',1,'text',left(record->'data'->'source_refs'->0->>'quote',2000),
       'uncertainty',null,'source_refs',
       (select jsonb_agg(jsonb_build_object('schema_version',1)||ref) from jsonb_array_elements(record->'data'->'source_refs') ref))))
   from jsonb_array_elements(pins->'known_continuity') record where not exists(
     select 1 from jsonb_array_elements(unavailable) u where u->>'record_id'=record->>'record_id')),'[]'));
 -- Opaque identities and typed fields count against the existing working-set
 -- budget too. Omit optional records after projection, keeping the guard intact.
 while octet_length((pins->'known_continuity')::text)>8000 loop
   pins:=jsonb_set(pins,'{known_continuity}',(pins->'known_continuity')-(jsonb_array_length(pins->'known_continuity')-1));
   pins:=jsonb_set(pins,'{known_continuity_complete}','false');
 end loop;
 -- Question prose and optional unresolved-reference labels are also derived;
 -- their citations cannot certify the contents of these free-form strings.
 pins:=pins||'{"active_question":null,"unresolved_references":[]}'::jsonb;
 -- Mandatory restrictions must not be weakened or copied as private prose.
 -- If their exact evidence is withheld, skip optional guidance for this page.
 select exists(select 1 from public.user_lifetime_continuity c
   cross join lateral jsonb_array_elements(c.data->'source_refs') ref join public.user_memory_attribution_window w
     on w.user_id=c.user_id and w.project_id=snap.project_id and w.source_id=(ref->>'source_id')::uuid
       and w.source_version=(ref->>'version')::bigint and w.disposition in ('withheld','non_story')
   where c.user_id=snap.user_id and c.conversation_id=snap.conversation_id and c.policy_epoch=snap.policy_epoch
     and c.kind in ('paused_topic','excluded_topic') and w.char_start<(ref->>'char_end')::integer
     and w.char_end>(ref->>'char_start')::integer) into private_policy;
 if private_policy then
   pins:=pins||'{"known_continuity":[],"known_continuity_complete":false,"active_question":null,"privacy_complete":false,"paused_topics":[],"excluded_topics":[],"unresolved_references":[]}'::jsonb;
 end if;

 if snap.guidance_news->>'settings_revision' is distinct from coalesce((select n.revision::text from public.user_historical_news_state n
   where n.user_id=snap.user_id and n.project_id=snap.project_id),'1') then raise exception 'guidance news settings changed' using errcode='PT409';end if;
 news:=jsonb_build_object('context_revision',snap.guidance_news->>'context_revision','clues',coalesce((
   select jsonb_agg(c.evidence||jsonb_build_object('id',c.id,'status',c.status,'project_id',c.project_id,
     'context_revision',snap.guidance_news->>'context_revision','relevance',c.relevance))
   from jsonb_array_elements(coalesce(snap.guidance_news->'clues','[]')) m join public.user_historical_news_clue c
     on c.user_id=snap.user_id and c.project_id=snap.project_id and c.id=m->>'id' and c.status='ready'
   where encode(sha256(convert_to((c.evidence||jsonb_build_object('id',c.id,'status',c.status,'project_id',c.project_id,
      'context_revision',snap.guidance_news->>'context_revision','relevance',c.relevance))::text,'UTF8')),'hex')=m->>'digest'),'[]'::jsonb));
 planning:=public.lifetime_interview_strategy_rollout(snap.user_id);
 select f.revision into revision from public.user_lifetime_strategy_frontier f where f.user_id=snap.user_id and f.project_id=snap.project_id;
 -- These bounded originals are evidence; canonical titles and dialogue are context.
 select coalesce(jsonb_agg(item order by position),'[]') into windows from (
   select allowed.item,allowed.position from (
   select s.* from public.user_narrator_source s where s.user_id=snap.user_id and s.project_id=snap.project_id
     and s.status='active' and s.processing_status='succeeded' and s.sequence<=snap.source_high_water
     and exists(select 1 from public.lifetime_guidance_source_windows(s.user_id,s.project_id,s.id,s.version,0,length(s.text)))
     and not exists(select 1 from public.user_interview_turn t where t.user_id=s.user_id and t.project_id=s.project_id
       and t.source_id=s.id and t.source_version=s.version and t.collector->'plan'->'work'->>'mode'='reply_only')
   order by s.sequence desc limit 1) s cross join lateral
     public.lifetime_guidance_source_windows(s.user_id,s.project_id,s.id,s.version,0,length(s.text))
       with ordinality allowed(item,position)
   order by position limit 8) bounded;
 select coalesce(jsonb_agg(to_jsonb(r)),'[]') into matches from public.retrieve_lifetime_guidance_events(
   snap.user_id,snap.project_id,(windows->0->>'id')::uuid,(windows->0->>'version')::bigint) r;
 select coalesce(jsonb_agg(item order by priority,change_sequence desc,id),'[]') into events from (
   select e.id,e.change_sequence,case when exists(select 1 from jsonb_array_elements(matches) m where m->>'event_id'=e.id) then 0
     when e.id=(select plan->>'active_event_id' from public.user_interview_plan where user_id=snap.user_id and project_id=snap.project_id) then 1 else 2 end priority,
     jsonb_set(public.bounded_lifetime_event_record(e),'{temporal,expression}','null')||
       '{"title":null,"title_complete":false,"uncertainty":null,"uncertainty_complete":false,"temporal_complete":false}'::jsonb item
   from public.user_memory_event e
   where e.user_id=snap.user_id and e.project_id=snap.project_id and e.status='active' and e.change_sequence<=snap.event_high_water
     and not exists(select 1 from public.user_memory_event_source r where r.user_id=e.user_id and r.project_id=e.project_id and r.event_id=e.id
       and not exists(select 1 from public.user_narrator_source s where s.user_id=r.user_id and s.project_id=r.project_id and s.id=r.source_id
         and s.version=r.source_version and s.status='active'
         and not exists(select 1 from public.user_memory_attribution_window w where w.user_id=s.user_id and w.project_id=s.project_id
           and w.source_id=s.id and w.source_version=s.version and w.disposition in ('withheld','non_story')
           and w.char_start<coalesce((r.evidence->>'char_end')::integer,length(s.text))
           and w.char_end>coalesce((r.evidence->>'char_start')::integer,0))))
   order by priority,e.change_sequence desc,e.id limit 8) bounded;
 -- Keep the latest tail as well as its beginning when one accepted message
 -- is long; recall limits often follow an otherwise detailed account.
 if (windows->0->>'original_length')::integer>2304 then
   for fragment in select w from public.lifetime_guidance_source_windows(snap.user_id,snap.project_id,
     (windows->0->>'id')::uuid,(windows->0->>'version')::bigint,
     0,(windows->0->>'original_length')::integer,true) w
     order by (w->>'char_end')::integer desc limit 1 loop
     -- Reserve a slot before older/head fragments consume the entire budget.
     -- Promote an already-present tail as well: source must support recall quotes.
     select coalesce(jsonb_agg(w order by position),'[]') into windows
       from jsonb_array_elements(windows) with ordinality items(w,position) where w<>fragment;
     windows:=jsonb_build_array(fragment)||windows;
     if jsonb_array_length(windows)>8 then windows:=windows-(jsonb_array_length(windows)-1);end if;
   end loop;
 end if;
 -- Recover older original passages behind the bounded canonical events. This
 -- lets the model compare an old account without treating an event title as testimony.
 for evidence in select n.*,r.char_start,r.char_end from (
   select (m->>'source_id')::uuid source_id,(m->>'version')::bigint version,(m->>'char_start')::integer char_start,
     (m->>'char_end')::integer char_end,0 priority from jsonb_array_elements(matches) m
   union all
   select r.source_id,r.version,r.char_start,r.char_end,1 from jsonb_array_elements(events) e
     cross join lateral jsonb_to_recordset(e->'source_refs') r(source_id uuid,version bigint,char_start integer,char_end integer)
 ) r join public.user_narrator_source n on n.user_id=snap.user_id and n.project_id=snap.project_id
     and n.id=r.source_id and n.version=r.version and n.status='active'
   where n.processing_status='succeeded' and n.sequence<=snap.source_high_water
     and r.char_start is not null and r.char_end>r.char_start
   order by r.priority,n.sequence,r.char_start limit 12 loop
   exit when jsonb_array_length(windows)>=8;
   if exists(select 1 from jsonb_array_elements(windows) w where w->>'id'=evidence.id::text
      and (w->>'char_start')::integer<=evidence.char_start and (w->>'char_end')::integer>=evidence.char_end) then continue;end if;
   lo:=greatest(0,evidence.char_start-128);hi:=least(length(evidence.text),lo+2304);
   for fragment in select w from public.lifetime_guidance_source_windows(snap.user_id,snap.project_id,evidence.id,evidence.version,lo,hi) w loop
     exit when jsonb_array_length(windows)>=8;
     if not exists(select 1 from jsonb_array_elements(windows) w where w->>'id'=fragment->>'id'
       and (w->>'char_start')::integer<=(fragment->>'char_start')::integer
       and (w->>'char_end')::integer>=(fragment->>'char_end')::integer) then
       windows:=windows||jsonb_build_array(fragment);
     end if;
   end loop;
 end loop;
 for evidence in select n.* from public.user_narrator_source n where n.user_id=snap.user_id and n.project_id=snap.project_id
   and n.status='active' and n.processing_status='succeeded' and n.sequence<=snap.source_high_water
   and not exists(select 1 from jsonb_array_elements(windows) w where w->>'id'=n.id::text)
   and exists(select 1 from public.lifetime_guidance_source_windows(n.user_id,n.project_id,n.id,n.version,0,length(n.text)))
   order by n.sequence desc limit 3 loop
   exit when jsonb_array_length(windows)>=8;
   for fragment in select w from public.lifetime_guidance_source_windows(snap.user_id,snap.project_id,evidence.id,evidence.version,0,length(evidence.text)) w loop
     exit when jsonb_array_length(windows)>=8;
     windows:=windows||jsonb_build_array(fragment);
   end loop;
 end loop;
 dialogue:=public.lifetime_question_dialogue(snap.user_id,snap.project_id,null,snap.source_high_water);
 -- Dialogue responses are another copy of narration, not an authorization to
 -- send a withheld passage. Keep the delivered question IDs and one safe slice;
 -- a partial response must never claim to be complete.
 select coalesce(jsonb_agg(jsonb_set(d,'{response}',coalesce((
   select (d->'response')||jsonb_build_object('text',w->'text','char_start',w->'char_start','char_end',w->'char_end',
     'complete',(w->>'char_start')::integer=0 and w->>'char_end'=w->>'original_length')
   from public.lifetime_guidance_source_windows(snap.user_id,snap.project_id,(d->'response'->>'id')::uuid,
     (d->'response'->>'version')::bigint,(d->'response'->>'char_start')::integer,(d->'response'->>'char_end')::integer) w limit 1
 ),'null'::jsonb)) order by position),'[]') into dialogue from jsonb_array_elements(dialogue) with ordinality entries(d,position);
 -- Collector IDs are arbitrary strings too. Bind an opaque cadence identity
 -- to the actual delivery; retries and reads of that delivery reuse the alias.
 -- Stored question prose/attribution is not original evidence even with a cite.
 select coalesce(jsonb_agg(jsonb_set(d,'{question}',(d->'question')||jsonb_build_object('text',null,'evidence',null,
   'id','dq-'||encode(sha256(convert_to(jsonb_build_array(snap.user_id,snap.project_id,
     d->'question'->'source_id',d->'question'->'source_version',d->'question'->'client_turn_id',
     d->'question'->'reply_id',d->'question'->'id')::text,'UTF8')),'hex'))) order by position),'[]')
 into dialogue from jsonb_array_elements(dialogue) with ordinality entries(d,position);
 if private_policy then windows:='[]';events:='[]';dialogue:='[]';end if;
 context:=jsonb_build_object('source_windows',windows,'recent_dialogue',dialogue,'minimum_detail_rounds',3,
   'news_clues',coalesce((select jsonb_agg(public.historical_news_public(c)||jsonb_build_object('status','ready','evidence_status','inspected'))
      from (select c from jsonb_array_elements(news->'clues') c limit 5) bounded),'[]'::jsonb),
   'news_revision',news->>'context_revision','generation',snap.guidance_revision,
   'retrieved_event_ids',(select coalesce(jsonb_agg(distinct m->>'event_id'),'[]') from jsonb_array_elements(matches) m));
 -- Do not raise request budgets when narration or public references are long.
 while octet_length(context::text)>32768 or octet_length(context::text)+octet_length(pins::text)+octet_length(events::text)
   +coalesce(octet_length((context->'source_windows'->0)::text),0)>48000 loop
   if jsonb_array_length(events)>2 then
     events:=events-(jsonb_array_length(events)-1);
   elsif jsonb_array_length(context->'source_windows')>1 then
     context:=jsonb_set(context,'{source_windows}',(context->'source_windows')-(jsonb_array_length(context->'source_windows')-1));
   elsif jsonb_array_length(context->'recent_dialogue')>0 then
     context:=jsonb_set(context,'{recent_dialogue}',(context->'recent_dialogue')-0);
   elsif jsonb_array_length(context->'news_clues')>0 then
     context:=jsonb_set(context,'{news_clues}',(context->'news_clues')-(jsonb_array_length(context->'news_clues')-1));
   elsif jsonb_array_length(events)>0 then events:=events-(jsonb_array_length(events)-1);
   elsif length(context->'source_windows'->0->>'text')>1600 then
     -- Retain the latest end of a tail window, or the start of a head window.
     if context->'source_windows'->0->>'char_end'=context->'source_windows'->0->>'original_length' then
       context:=jsonb_set(context,'{source_windows,0,char_start}',to_jsonb((context->'source_windows'->0->>'char_end')::integer-1600));
       context:=jsonb_set(context,'{source_windows,0,text}',to_jsonb(right(context->'source_windows'->0->>'text',1600)));
     else
       context:=jsonb_set(context,'{source_windows,0,char_end}',to_jsonb((context->'source_windows'->0->>'char_start')::integer+1600));
       context:=jsonb_set(context,'{source_windows,0,text}',to_jsonb(left(context->'source_windows'->0->>'text',1600)));
     end if;
   else raise exception 'guidance context exceeds budget' using errcode='22023';end if;
 end loop;
 perform set_config('request.jwt.claim.sub',coalesce(previous_owner,''),true);
 page:=jsonb_build_object('schema_version',1,'protocol','lifetime_composer_pages','lane_id',lane.id,'token',p_token,
   'snapshot_id',snap.id,'user_id',snap.user_id,'project_id',snap.project_id,'conversation_id',snap.conversation_id,
   'skill','guidance','locale',snap.locale,'policy_epoch',snap.policy_epoch,'preference_revision',snap.preference_revision,
   'source_high_water',snap.source_high_water,'event_high_water',snap.event_high_water,'page_number',0,
   'root_digest',snap.root_digest,'coverage_round',snap.round_high_water,'base_revision',snap.base_revision,
   'preferences',pins,'editorial_request',null,'previous',null,'reuse',false,'complete',false,'partition',null,
   'source',context->'source_windows'->0,'events',events,'guidance_context',context,
   'two_lane',jsonb_strip_nulls(jsonb_build_object('schema_version',1,'task_version','two-lane-v1','execution_generation',
      (select execution_generation from public.user_lifetime_conversation where user_id=snap.user_id and conversation_id=snap.conversation_id),
      'phase_revision',0,'work_mode','extract','strategy_mode',case when planning<>'disabled' then planning end,'strategy_revision',coalesce(revision,0))));
 page:=page||jsonb_build_object('input_digest',encode(sha256(convert_to((page-'token')::text,'UTF8')),'hex'));
 return page||jsonb_build_object('page_digest',encode(sha256(convert_to(page::text,'UTF8')),'hex'));
end $$;

-- Defense in depth at the writer, independent of provider/Python validation.
CREATE FUNCTION public.lifetime_guidance_ref(p_page jsonb,p_ref jsonb) RETURNS jsonb
 LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
declare s jsonb; lo integer; hi integer; original public.user_narrator_source%rowtype;
begin
 if jsonb_typeof(p_ref) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_ref) k
   where k not in ('source_id','version','quote','char_start','char_end','attribution'))
   or jsonb_typeof(p_ref->'version') is distinct from 'number'
   or jsonb_typeof(p_ref->'quote') is distinct from 'string' or length(p_ref->>'quote') not between 1 and 2000 then
   raise exception 'grounded guidance reference required' using errcode='22023';end if;
 for s in select value from jsonb_array_elements(p_page->'guidance_context'->'source_windows') loop
   if s->>'id'=p_ref->>'source_id' and s->>'version'=p_ref->>'version' then
     lo:=(p_ref->>'char_start')::integer;hi:=(p_ref->>'char_end')::integer;
     if lo is null or hi is null or lo<(s->>'char_start')::integer or hi>(s->>'char_end')::integer or hi-lo<>length(p_ref->>'quote')
       or substring(s->>'text' from lo-(s->>'char_start')::integer+1 for hi-lo) is distinct from p_ref->>'quote' then continue;end if;
     select * into original from public.user_narrator_source where user_id=(p_page->>'user_id')::uuid and project_id=p_page->>'project_id'
       and id=(s->>'id')::uuid and version=(s->>'version')::bigint and status='active';
     if not found or substring(original.text from lo+1 for hi-lo) is distinct from p_ref->>'quote'
       or exists(select 1 from public.user_memory_attribution_window w where w.user_id=original.user_id and w.project_id=original.project_id
         and w.source_id=original.id and w.source_version=original.version and w.disposition in ('withheld','non_story') and w.char_start<hi and w.char_end>lo) then
       raise exception 'guidance reference unavailable' using errcode='PT409';end if;
     return p_ref;
   end if;
 end loop;
 raise exception 'guidance reference outside authorized window' using errcode='22023';
end $$;

CREATE FUNCTION public.lifetime_guidance_question_current(p_owner uuid,p_project text,p_question jsonb) RETURNS boolean
 LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 select not exists(select 1 from jsonb_array_elements(coalesce(p_question->'trigger_source_refs','[]')) r
   where not exists(select 1 from public.user_narrator_source n where n.user_id=p_owner and n.project_id=p_project
     and n.id=(r->>'source_id')::uuid and n.version=(r->>'version')::bigint and n.status='active'
     and case when r ? 'quote_sha256' then encode(sha256(convert_to(substring(n.text from (r->>'char_start')::integer+1
       for (r->>'char_end')::integer-(r->>'char_start')::integer),'UTF8')),'hex')=r->>'quote_sha256'
       else substring(n.text from (r->>'char_start')::integer+1 for (r->>'char_end')::integer-(r->>'char_start')::integer)=r->>'quote' end))
$$;
REVOKE ALL ON FUNCTION public.lifetime_guidance_question_current(uuid,text,jsonb) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION public.lifetime_guidance_priority(p_question jsonb) RETURNS integer
 LANGUAGE sql IMMUTABLE SET search_path='' AS $$
 select case p_question->>'trigger' when 'conflict' then 0 when 'clarification' then 1 when 'historical_news' then 2
   when 'topic_transition' then 3 when 'life_essence' then 4 when 'follow_up' then 5
   else case when p_question->'requires_confirmation'='true'::jsonb then 1 else 6 end end
$$;

CREATE FUNCTION public.commit_lifetime_interview_guidance(p_lane_id uuid,p_token uuid,p_page_digest text,p_result jsonb) RETURNS jsonb
 LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
declare snap public.user_lifetime_lane_snapshot%rowtype; page jsonb; signal jsonb; ref jsonb; question jsonb;
 normalized jsonb; source jsonb; questions jsonb:='[]'; kinds text[]:=array[]::text[]; kind text; priority text;
 ack jsonb; proposal jsonb; current_revision bigint; next_revision bigint; shadow_mode boolean; manifest jsonb; fingerprint text; anchor record;
begin
 fingerprint:=encode(sha256(convert_to(p_result::text,'UTF8')),'hex');
 if exists(select 1 from public.user_background_skill_work w join public.user_lifetime_strategy_page_receipt r on r.snapshot_id=w.snapshot_id
   where w.lane_id=p_lane_id and w.lease_token=p_token and w.page_digest=p_page_digest and w.phase='guidance'
     and w.status in ('saved','skipped') and r.page_digest=p_page_digest and r.result_digest=fingerprint) then
   return jsonb_build_object('status','finished','replayed',true);end if;
 snap:=public.lock_lifetime_memoir_lane(p_lane_id,p_token);
 page:=public.read_lifetime_interview_guidance_page(p_lane_id,p_token);
 if p_page_digest is distinct from page->>'page_digest' then raise exception 'guidance inputs changed' using errcode='PT409';end if;
 if jsonb_typeof(p_result) is distinct from 'object' or octet_length(p_result::text)>16000
   or exists(select 1 from jsonb_object_keys(p_result) k where k not in ('signals','prepared_questions','acknowledgement_guidance','strategy_proposal'))
   or jsonb_typeof(p_result->'signals') is distinct from 'array' or jsonb_array_length(p_result->'signals')>6
   or jsonb_typeof(p_result->'prepared_questions') is distinct from 'array' or jsonb_array_length(p_result->'prepared_questions')>5 then
   raise exception 'bounded guidance result required' using errcode='22023';end if;
 for signal in select value from jsonb_array_elements(p_result->'signals') loop
   kind:=signal->>'kind';
   if jsonb_typeof(signal) is distinct from 'object' or exists(select 1 from jsonb_object_keys(signal) k
     where k not in ('kind','source_refs','detail_question_ids','recall_limit_quote'))
     or coalesce(kind,'') not in ('conflict','clarification','historical_news','topic_transition','life_essence','follow_up') or kind=any(kinds)
     or jsonb_typeof(signal->'source_refs') is distinct from 'array' or jsonb_array_length(signal->'source_refs') not between 1 and 4
     or jsonb_typeof(signal->'detail_question_ids') is distinct from 'array' or jsonb_array_length(signal->'detail_question_ids')>8 then
     raise exception 'invalid guidance signal' using errcode='22023';end if;
   kinds:=array_append(kinds,kind);
   for ref in select value from jsonb_array_elements(signal->'source_refs') loop perform public.lifetime_guidance_ref(page,ref);end loop;
   if kind='conflict' and (select count(distinct (r->>'source_id',r->>'version',r->>'char_start',r->>'char_end'))
     from jsonb_array_elements(signal->'source_refs') r)<2 then raise exception 'conflict requires both assertions' using errcode='22023';end if;
   if kind='topic_transition' then
     if coalesce(signal->'recall_limit_quote','null')<>'null'::jsonb then
       if jsonb_typeof(signal->'recall_limit_quote') is distinct from 'string' or length(signal->>'recall_limit_quote') not between 1 and 500 then
         raise exception 'current recall limit required' using errcode='22023';end if;
       perform public.lifetime_question_hint(page->'source',jsonb_build_object('question','Recall?', 'topic','recall', 'quote',signal->>'recall_limit_quote'));
     elsif (select count(distinct id) from jsonb_array_elements_text(signal->'detail_question_ids') id)<3
       or exists(select 1 from jsonb_array_elements_text(signal->'detail_question_ids') id where not exists(
         select 1 from jsonb_array_elements(page->'guidance_context'->'recent_dialogue') d where d->'question'->>'id'=id and d->'question'->'delivered'='true'::jsonb)) then
       raise exception 'transition requires delivered questions' using errcode='22023';end if;
   elsif coalesce(signal->'recall_limit_quote','null')<>'null'::jsonb then raise exception 'invalid recall signal' using errcode='22023';end if;
 end loop;
 for question in select value from jsonb_array_elements(p_result->'prepared_questions') loop
   kind:=question->>'trigger';
   if jsonb_typeof(question) is distinct from 'object' or exists(select 1 from jsonb_object_keys(question) k where k not in
      ('question','topic','quote','char_start','char_end','requires_confirmation','scope','source_id','source_version','trigger','historical_clue_id','bridge'))
     or not coalesce(kind=any(kinds),false) or jsonb_typeof(question->'source_version') is distinct from 'number'
     or question->'requires_confirmation' is distinct from to_jsonb(kind in ('conflict','clarification'))
     or (kind in ('historical_news','topic_transition','life_essence') and question->>'scope'<>'broader')
     or jsonb_typeof(question->'bridge') is distinct from 'string' or length(question->>'bridge')>500 then
     raise exception 'invalid guidance question' using errcode='22023';end if;
   ref:=jsonb_build_object('source_id',question->>'source_id','version',question->'source_version','quote',question->>'quote',
     'char_start',question->'char_start','char_end',question->'char_end','attribution',null);
   perform public.lifetime_guidance_ref(page,ref);
   select value into source from jsonb_array_elements(page->'guidance_context'->'source_windows') s(value)
     where value->>'id'=question->>'source_id' and value->>'version'=question->>'source_version'
       and (value->>'char_start')::integer<=(question->>'char_start')::integer and (value->>'char_end')::integer>=(question->>'char_end')::integer limit 1;
   normalized:=public.lifetime_question_hint(source,question-array['source_id','source_version','trigger','historical_clue_id','bridge']);
   if kind='historical_news' then
     if not exists(select 1 from jsonb_array_elements(page->'guidance_context'->'news_clues') c where c->>'id'=question->>'historical_clue_id') then
       raise exception 'historical guidance clue unavailable' using errcode='PT409';end if;
   elsif coalesce(question->'historical_clue_id','null')<>'null'::jsonb then raise exception 'unexpected historical clue' using errcode='22023';end if;
   normalized:=normalized||jsonb_build_object('source_id',question->>'source_id','source_version',question->'source_version','trigger',kind,
      'historical_clue_id',question->'historical_clue_id','bridge',question->>'bridge',
      'trigger_source_refs',(select jsonb_agg(jsonb_build_object('source_id',r->>'source_id','version',r->'version',
        'char_start',r->'char_start','char_end',r->'char_end','quote_sha256',encode(sha256(convert_to(r->>'quote','UTF8')),'hex')))
        from jsonb_array_elements(p_result->'signals') signal_item cross join lateral jsonb_array_elements(signal_item->'source_refs') r where signal_item->>'kind'=kind),
      'id',public.lifetime_question_id((question->>'source_id')::uuid,(question->>'source_version')::bigint,normalized));
   if exists(select 1 from jsonb_array_elements(questions) q where q->>'id'=normalized->>'id') then raise exception 'duplicate guidance question' using errcode='22023';end if;
   questions:=questions||jsonb_build_array(normalized);
 end loop;
 select k into priority from unnest(kinds) k order by public.lifetime_guidance_priority(jsonb_build_object('trigger',k)) limit 1;
 if priority is not null and priority<>'life_essence' and not exists(select 1 from jsonb_array_elements(questions) q where q->>'trigger'=priority) then
   raise exception 'highest priority guidance requires a question' using errcode='22023';end if;
 ack:=p_result->'acknowledgement_guidance';
 if coalesce(ack,'null')<>'null'::jsonb then
   if not('life_essence'=any(kinds)) or jsonb_typeof(ack) is distinct from 'object' or exists(select 1 from jsonb_object_keys(ack) k where k not in ('text','source_refs'))
     or jsonb_typeof(ack->'text') is distinct from 'string' or length(ack->>'text') not between 1 and 700 or ack->>'text' ~ '[?？]'
     or jsonb_typeof(ack->'source_refs') is distinct from 'array' or jsonb_array_length(ack->'source_refs') not between 1 and 4 then
     raise exception 'grounded acknowledgement required' using errcode='22023';end if;
   for ref in select value from jsonb_array_elements(ack->'source_refs') loop
     perform public.lifetime_guidance_ref(page,ref);
     if coalesce(ref->'attribution','null')<>'null'::jsonb or exists(select 1 from public.user_memory_attribution_window w
       where w.user_id=snap.user_id and w.project_id=snap.project_id and w.source_id=(ref->>'source_id')::uuid and w.source_version=(ref->>'version')::bigint
         and w.char_start<(ref->>'char_end')::integer and w.char_end>(ref->>'char_start')::integer
         and w.reason<>'no_supported_event')
       or exists(select 1 from public.user_memory_event_source r join public.user_memory_event e on e.user_id=r.user_id and e.project_id=r.project_id and e.id=r.event_id
         where r.user_id=snap.user_id and r.project_id=snap.project_id and r.source_id=(ref->>'source_id')::uuid and r.source_version=(ref->>'version')::bigint
           and coalesce(nullif(r.evidence->>'attribution',''),nullif(e.data->>'attribution','')) not in
             ('narrator','storyteller','self','我','本人',snap.user_id::text)
           and (r.evidence->>'char_start')::integer<(ref->>'char_end')::integer and (r.evidence->>'char_end')::integer>(ref->>'char_start')::integer) then
       raise exception 'reflection requires narrator testimony' using errcode='22023';end if;
   end loop;
 end if;
 proposal:=p_result->'strategy_proposal';
 if coalesce(proposal,'null')='null'::jsonb then proposal:=jsonb_build_object('strategy','explore','objective','follow_story','focus_event_ids','[]'::jsonb);end if;
 if jsonb_typeof(proposal) is distinct from 'object' or exists(select 1 from jsonb_object_keys(proposal) k where k not in ('strategy','objective','focus_event_ids'))
   or coalesce(proposal->>'strategy','') not in ('comfort','explore','shape')
   or coalesce(proposal->>'objective','') not in ('gentle_entry','follow_story','clarify_order','clarify_identity','link_stories','broaden_scope')
   or jsonb_typeof(proposal->'focus_event_ids') is distinct from 'array' or jsonb_array_length(proposal->'focus_event_ids')>8
   or (proposal->>'strategy'='shape' and proposal->>'objective' not in ('clarify_order','clarify_identity','link_stories'))
   or exists(select 1 from jsonb_array_elements_text(proposal->'focus_event_ids') id where not exists(select 1 from jsonb_array_elements(page->'events') e where e->>'id'=id)) then
   raise exception 'invalid guidance strategy proposal' using errcode='22023';end if;
 with consumed as materialized (select * from public.lifetime_consumed_question_ids(snap.user_id,snap.project_id))
 select coalesce(jsonb_agg(q order by public.lifetime_guidance_priority(q),position),'[]') into questions
 from jsonb_array_elements(questions) with ordinality items(q,position) where not exists(select 1 from consumed where question_id=q->>'id');
 shadow_mode:=page->'two_lane'->>'strategy_mode'='shadow';
 -- Keep only pending confirmations across runs; never requeue consumed IDs.
 for anchor in select (q->>'source_id')::uuid id,(q->>'source_version')::bigint version,jsonb_agg(q-'id' order by position) hints
   from jsonb_array_elements(questions) with ordinality items(q,position) where not coalesce(shadow_mode,false) or q->'requires_confirmation'='true'::jsonb
   group by q->>'source_id',q->>'source_version' loop
   insert into public.user_lifetime_prepared_question values(snap.user_id,snap.project_id,anchor.id,anchor.version,(select source_sequence from public.user_memoir_project where user_id=snap.user_id and project_id=snap.project_id),
     snap.policy_epoch,snap.preference_revision,(page->'two_lane'->>'execution_generation')::bigint,0,snap.id,p_page_digest,anchor.hints)
   on conflict(user_id,project_id,source_id) do update set source_version=excluded.source_version,source_revision=excluded.source_revision,
     policy_epoch=excluded.policy_epoch,preference_revision=excluded.preference_revision,execution_generation=excluded.execution_generation,
     phase_revision=excluded.phase_revision,snapshot_id=excluded.snapshot_id,page_digest=excluded.page_digest,
     questions=(select coalesce(jsonb_agg(q order by position),'[]') from (select distinct on (public.lifetime_question_id(excluded.source_id,excluded.source_version,q)) q,position from jsonb_array_elements(excluded.questions||
       case when user_lifetime_prepared_question.source_version=excluded.source_version and user_lifetime_prepared_question.policy_epoch=excluded.policy_epoch
         and user_lifetime_prepared_question.preference_revision=excluded.preference_revision and user_lifetime_prepared_question.execution_generation=excluded.execution_generation
       then jsonb_path_query_array(user_lifetime_prepared_question.questions,'$[*] ? (@.requires_confirmation == true)') else '[]'::jsonb end) with ordinality items(q,position)
       order by public.lifetime_question_id(excluded.source_id,excluded.source_version,q),position) unique_questions);
   perform public.prune_lifetime_question_pool(snap.user_id,snap.project_id,anchor.id);
 end loop;
 if jsonb_array_length(p_result->'signals')>0 or jsonb_array_length(questions)>0 or coalesce(ack,'null')<>'null'::jsonb
   or coalesce(p_result->'strategy_proposal','null')<>'null'::jsonb then
   insert into public.user_lifetime_strategy_frontier(user_id,project_id) values(snap.user_id,snap.project_id) on conflict do nothing;
   select f.revision into current_revision from public.user_lifetime_strategy_frontier f where user_id=snap.user_id and project_id=snap.project_id for update;
   if current_revision is distinct from (page->'two_lane'->>'strategy_revision')::bigint then raise exception 'guidance strategy changed' using errcode='PT409';end if;
   next_revision:=current_revision+1;
   select coalesce(jsonb_agg(jsonb_build_object('id',e->>'id','revision',e->'revision')),'[]') into manifest from jsonb_array_elements(page->'events') e;
   insert into public.user_lifetime_interview_strategy(user_id,project_id,plan_revision,shadow,source_id,source_version,based_on_sequence,
     policy_epoch,preference_revision,execution_generation,phase_revision,event_manifest,data)
   values(snap.user_id,snap.project_id,next_revision,coalesce(shadow_mode,false),(page->'source'->>'id')::uuid,(page->'source'->>'version')::bigint,
     (page->'source'->>'sequence')::bigint,snap.policy_epoch,snap.preference_revision,(page->'two_lane'->>'execution_generation')::bigint,0,manifest,
     jsonb_build_object('schema_version',1,'project_id',snap.project_id,'plan_revision',next_revision,'based_on_sequence',(page->'source'->>'sequence')::bigint,
       'source_id',page->'source'->>'id','source_version',page->'source'->'version','source_revision',snap.source_high_water,'policy_epoch',snap.policy_epoch,
       'preference_revision',snap.preference_revision,'execution_generation',page->'two_lane'->'execution_generation','phase_revision',0,'snapshot_id',snap.id,
       'checkpoint_id',(select checkpoint_id from public.user_lifetime_conversation where user_id=snap.user_id and conversation_id=snap.conversation_id),
       'strategy',coalesce(proposal->>'strategy',(select active_strategy from public.user_lifetime_strategy_frontier where user_id=snap.user_id and project_id=snap.project_id),'explore'),
       'objective',coalesce(proposal->>'objective','follow_story'),'focus_event_ids',coalesce(proposal->'focus_event_ids','[]'::jsonb),'candidates',questions,
       'background_lag_ms',0,'guidance',jsonb_build_object('signals',p_result->'signals','acknowledgement_guidance',ack,
          'generation',snap.guidance_revision,'published_source_sequence',(select source_sequence from public.user_memoir_project where user_id=snap.user_id and project_id=snap.project_id),
          'news_revision',page->'guidance_context'->>'news_revision','event_sequence',snap.event_high_water)));
   update public.user_lifetime_strategy_frontier set revision=next_revision,
     active_strategy=case when coalesce(shadow_mode,false) then active_strategy else coalesce(proposal->>'strategy',active_strategy) end,
     shadow_strategy=case when coalesce(shadow_mode,false) then coalesce(proposal->>'strategy',shadow_strategy) else shadow_strategy end
   where user_id=snap.user_id and project_id=snap.project_id and public.user_lifetime_strategy_frontier.revision=current_revision;
 end if;
 insert into public.user_lifetime_strategy_page_receipt values(snap.id,0,p_page_digest,fingerprint);
 update public.user_background_skill_work set status='saved',reason=null,updated_at=clock_timestamp()
   where lane_id=p_lane_id and snapshot_id=snap.id and phase='guidance' and page_digest=p_page_digest and model_invoked;
 if not found then perform public.background_skill_receipt(page,'guidance','memoir-interview-guidance','model',
   case when jsonb_array_length(page->'guidance_context'->'source_windows')=0 then 'skipped' else 'saved' end,'invocation_receipt_unavailable');end if;
 update public.user_lifetime_lane_snapshot set state='completed' where id=snap.id;
 update public.user_memoir_lane set successful_source=snap.source_high_water,successful_event=snap.event_high_water,successful_round=snap.round_high_water,
   token=null,lease_until=null,run_deadline=null,pending=guidance_revision>snap.guidance_revision,attempts=0,error=null where id=p_lane_id;
 return jsonb_build_object('status','finished','questions',jsonb_array_length(questions));
end $$;

CREATE FUNCTION public.read_lifetime_interview_guidance_live(p_conversation_id uuid) RETURNS jsonb
 LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
declare pins jsonb; identity public.user_lifetime_conversation%rowtype; planned public.user_lifetime_interview_strategy%rowtype;
 p public.user_memoir_project%rowtype; g jsonb;
begin
 pins:=public.read_lifetime_pinned(p_conversation_id);
 select * into identity from public.user_lifetime_conversation where user_id=auth.uid() and conversation_id=p_conversation_id;
 if not exists(select 1 from public.lifetime_two_lane_rollout where singleton and enabled)
   or public.lifetime_interview_strategy_rollout(auth.uid())='shadow' then return null;end if;
 select * into p from public.user_memoir_project where user_id=auth.uid() and project_id=identity.project_id;
 select * into planned from public.user_lifetime_interview_strategy where user_id=auth.uid() and project_id=identity.project_id and not shadow
   order by plan_revision desc limit 1;
 g:=planned.data->'guidance';
 if g is null or planned.policy_epoch<>p.policy_epoch or planned.preference_revision<>identity.preference_revision
   or planned.execution_generation<>identity.execution_generation or p.source_sequence not between coalesce((g->>'published_source_sequence')::bigint,planned.based_on_sequence) and coalesce((g->>'published_source_sequence')::bigint,planned.based_on_sequence)+1
   or not exists(select 1 from public.user_narrator_source s where s.user_id=auth.uid() and s.project_id=identity.project_id and s.id=planned.source_id
     and s.version=planned.source_version and s.status='active')
   or exists(select 1 from public.user_interview_turn seen join public.user_lifetime_reply r
     on r.user_id=seen.user_id and r.client_turn_id=seen.client_turn_id and r.conversation_id=p_conversation_id
     where seen.user_id=auth.uid() and seen.project_id=identity.project_id and seen.guidance_plan_revision_seen=planned.plan_revision
       and r.policy_epoch=p.policy_epoch and r.preference_revision=identity.preference_revision and r.execution_generation=identity.execution_generation)
   or split_part(g->>'news_revision',':',3) is distinct from coalesce((select revision::text from public.user_historical_news_state
     where user_id=auth.uid() and project_id=identity.project_id),'1')
   or exists(select 1 from jsonb_array_elements(coalesce(g->'acknowledgement_guidance'->'source_refs','[]')) r
      where not exists(select 1 from public.user_narrator_source s where s.user_id=auth.uid() and s.project_id=identity.project_id
        and s.id=(r->>'source_id')::uuid and s.version=(r->>'version')::bigint and s.status='active')) then return null;end if;
 return g||jsonb_build_object('plan_revision',planned.plan_revision);
end $$;

CREATE FUNCTION public.read_lifetime_interview_guidance(p_conversation_id uuid) RETURNS jsonb
 LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
declare pins jsonb; identity public.user_lifetime_conversation%rowtype; current_turn public.user_interview_turn%rowtype;
 lease uuid; context_fence jsonb; guidance jsonb;
begin
 pins:=public.read_lifetime_pinned(p_conversation_id);
 select * into identity from public.user_lifetime_conversation where user_id=auth.uid() and conversation_id=p_conversation_id;
 select lease_token into lease from public.user_agent_turn_lease where user_id=auth.uid() and expires_at>clock_timestamp();
 if lease is not null then
   select * into current_turn from public.user_interview_turn where user_id=auth.uid() and project_id=identity.project_id
     and collector is null order by sequence desc limit 1;
   context_fence:=jsonb_build_object('lease_digest',encode(sha256(convert_to(lease::text,'UTF8')),'hex'),
     'policy_epoch',(select policy_epoch from public.user_memoir_project where user_id=auth.uid() and project_id=identity.project_id),
     'preference_revision',identity.preference_revision,'execution_generation',identity.execution_generation,
     'source_id',current_turn.source_id,'source_version',current_turn.source_version);
   if current_turn.interview_guidance_snapshot->'fence'=context_fence and current_turn.interview_guidance_snapshot ? 'guidance' then
     guidance:=current_turn.interview_guidance_snapshot->'guidance';
     if guidance='null'::jsonb then return null;end if;
     if not public.lifetime_guidance_question_current(auth.uid(),identity.project_id,
       jsonb_build_object('trigger_source_refs',coalesce(guidance->'acknowledgement_guidance'->'source_refs','[]'))) then return null;end if;
     return guidance;
   end if;
 end if;
 guidance:=public.read_lifetime_interview_guidance_live(p_conversation_id);
 if current_turn.client_turn_id is not null then
   update public.user_interview_turn set interview_guidance_snapshot=jsonb_set(
     case when interview_guidance_snapshot->'fence'=context_fence then interview_guidance_snapshot else jsonb_build_object('fence',context_fence) end,
     '{guidance}',coalesce(guidance,'null'::jsonb)),
     guidance_plan_revision_seen=case when coalesce(guidance->'acknowledgement_guidance','null')<>'null'::jsonb then (guidance->>'plan_revision')::bigint end
   where user_id=auth.uid() and project_id=identity.project_id and client_turn_id=current_turn.client_turn_id;
 end if;
 return guidance;
end $$;
REVOKE ALL ON FUNCTION public.read_lifetime_interview_guidance_live(uuid) FROM PUBLIC,anon,authenticated,service_role;


-- Mira owns interviewing; extraction and news do not enqueue a guidance model.

REVOKE ALL ON FUNCTION public.enqueue_lifetime_interview_guidance(),public.read_lifetime_interview_guidance_page(uuid,uuid),
 public.lifetime_guidance_ref(jsonb,jsonb),public.lifetime_guidance_priority(jsonb),public.commit_lifetime_interview_guidance(uuid,uuid,text,jsonb),
 public.read_lifetime_interview_guidance(uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.read_lifetime_interview_guidance_page(uuid,uuid),public.commit_lifetime_interview_guidance(uuid,uuid,text,jsonb) TO service_role;
GRANT EXECUTE ON FUNCTION public.read_lifetime_interview_guidance(uuid) TO authenticated,service_role;

CREATE TABLE public.user_memoir_background_agent (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 user_id uuid NOT NULL,
 project_id text NOT NULL,
 pending boolean NOT NULL DEFAULT true,
 token uuid,
 lease_until timestamptz,
 run_deadline timestamptz,
 source_high_water bigint NOT NULL DEFAULT 0,
 policy_epoch bigint NOT NULL DEFAULT 0,
 preference_revision bigint NOT NULL DEFAULT 0,
 target_source bigint NOT NULL DEFAULT 0,
 attempts integer NOT NULL DEFAULT 0,
 available_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 selection jsonb,
 UNIQUE(user_id,project_id),
 FOREIGN KEY(user_id,project_id) REFERENCES public.user_memoir_project(user_id,project_id) ON DELETE CASCADE
);
ALTER TABLE public.user_memoir_background_agent ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.user_memoir_background_agent FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION public.queue_user_memoir_background_agent(p_project_id text,p_selection jsonb DEFAULT NULL) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$
declare project public.user_memoir_project%rowtype; result uuid;
begin
 select * into project from public.user_memoir_project where user_id=auth.uid() and project_id=p_project_id for share;
 if not found then raise exception 'background project unavailable' using errcode='42501';end if;
 if p_selection is not null and (jsonb_typeof(p_selection)<>'object' or
   exists(select 1 from jsonb_object_keys(p_selection) k where k not in ('place','period')) or
   jsonb_typeof(p_selection->'place') is distinct from 'string' or length(p_selection->>'place') not between 1 and 120 or
   jsonb_typeof(p_selection->'period') is distinct from 'string' or length(p_selection->>'period') not between 1 and 160) then
   raise exception 'invalid background place selection';end if;
 insert into public.user_memoir_background_agent(user_id,project_id,target_source,selection)
 values(project.user_id,project.project_id,project.source_sequence,p_selection)
 on conflict(user_id,project_id) do update set pending=true,
   attempts=case when excluded.target_source>public.user_memoir_background_agent.target_source or p_selection is not null then 0
     else public.user_memoir_background_agent.attempts end,
   target_source=greatest(excluded.target_source,public.user_memoir_background_agent.target_source),
   selection=coalesce(p_selection,public.user_memoir_background_agent.selection),available_at=clock_timestamp()
 returning id into result;
 return result;
end $$;

CREATE FUNCTION public.pending_memoir_background_agents(p_limit integer DEFAULT 50) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$
begin
 insert into public.user_memoir_background_agent(user_id,project_id,target_source)
 select distinct l.user_id,l.project_id,p.source_sequence from public.user_memoir_lane l
 join public.user_memoir_project p on p.user_id=l.user_id and p.project_id=l.project_id
 join public.user_lifetime_conversation c on c.user_id=l.user_id and c.project_id=l.project_id
 where l.skill in ('timeline','composer') and l.attempts<3 and l.available_at<=clock_timestamp() and (l.pending or
   l.token is not null and (l.lease_until<=clock_timestamp() or l.run_deadline<=clock_timestamp()))
 on conflict(user_id,project_id) do update set pending=public.user_memoir_background_agent.pending
     or public.user_memoir_background_agent.token is null
     or excluded.target_source>public.user_memoir_background_agent.target_source,
   attempts=case when excluded.target_source>public.user_memoir_background_agent.target_source then 0
     else public.user_memoir_background_agent.attempts end,
   target_source=greatest(excluded.target_source,public.user_memoir_background_agent.target_source);
 return (select coalesce(jsonb_agg(id),'[]') from (select a.id from public.user_memoir_background_agent a
   where (a.pending or a.token is not null and (a.lease_until<=clock_timestamp() or a.run_deadline<=clock_timestamp()))
   and a.attempts<3 and a.available_at<=clock_timestamp()
   and exists(select 1 from public.user_lifetime_conversation c where c.user_id=a.user_id and c.project_id=a.project_id)
   and (a.token is null or a.lease_until<=clock_timestamp() or a.run_deadline<=clock_timestamp())
   and not exists(select 1 from public.user_lifetime_pending_policy p where p.user_id=a.user_id and p.project_id=a.project_id)
   and not exists(select 1 from public.user_lifetime_policy_inventory_pending p where p.user_id=a.user_id and p.project_id=a.project_id)
   order by a.available_at,a.id limit least(greatest(p_limit,1),100)) ready);
end $$;

CREATE FUNCTION public.claim_memoir_background_agent(p_id uuid,p_run_seconds integer DEFAULT 900) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$
declare a public.user_memoir_background_agent%rowtype; p public.user_memoir_project%rowtype;
 c public.user_lifetime_conversation%rowtype;
begin
 if p_run_seconds is null or p_run_seconds not between 1 and 1800 then raise exception 'invalid background run duration';end if;
 select * into a from public.user_memoir_background_agent where id=p_id;
 if not found then return null;end if;
 select * into p from public.user_memoir_project where user_id=a.user_id and project_id=a.project_id for share;
 select * into c from public.user_lifetime_conversation where user_id=a.user_id and project_id=a.project_id for share;
 if not found then return null;end if;
 select * into a from public.user_memoir_background_agent where id=p_id for update;
 if (not a.pending and (a.token is null or a.lease_until>clock_timestamp() and a.run_deadline>clock_timestamp()))
   or a.attempts>=3 or a.available_at>clock_timestamp() or
   a.token is not null and a.lease_until>clock_timestamp() and a.run_deadline>clock_timestamp() or
   exists(select 1 from public.user_lifetime_pending_policy q where q.user_id=a.user_id and q.project_id=a.project_id) or
   exists(select 1 from public.user_lifetime_policy_inventory_pending q where q.user_id=a.user_id and q.project_id=a.project_id) then return null;end if;
 update public.user_memoir_background_agent set token=gen_random_uuid(),pending=false,attempts=attempts+1,
   source_high_water=p.source_sequence,policy_epoch=p.policy_epoch,preference_revision=c.preference_revision,
   run_deadline=clock_timestamp()+make_interval(secs=>p_run_seconds),
   lease_until=least(clock_timestamp()+interval '60 seconds',clock_timestamp()+make_interval(secs=>p_run_seconds))
 where id=p_id returning * into a;
 return jsonb_build_object('id',a.id,'token',a.token,'user_id',a.user_id,'project_id',a.project_id,
   'source_high_water',a.source_high_water,'policy_epoch',a.policy_epoch,'preference_revision',a.preference_revision,
   'locale',coalesce((select case when profile->>'preferred_language'='zh-CN' then 'zh-CN' else 'en-AU' end
      from public.user_profile where user_id=a.user_id),'en-AU'),
   'selection',a.selection);
end $$;

CREATE FUNCTION public.lock_memoir_background_agent(p_fence jsonb) RETURNS numeric
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$
declare a public.user_memoir_background_agent%rowtype; p public.user_memoir_project%rowtype;
 c public.user_lifetime_conversation%rowtype;
begin
 select * into a from public.user_memoir_background_agent where id=(p_fence->>'id')::uuid;
 if not found then raise exception 'background agent unavailable' using errcode='42501';end if;
 select * into p from public.user_memoir_project where user_id=a.user_id and project_id=a.project_id for share;
 select * into c from public.user_lifetime_conversation where user_id=a.user_id and project_id=a.project_id for share;
 if not found then raise exception 'background conversation unavailable' using errcode='42501';end if;
 select * into a from public.user_memoir_background_agent where id=a.id for share;
 if a.token is null or a.token is distinct from (p_fence->>'token')::uuid or a.lease_until<=clock_timestamp() or
   a.run_deadline<=clock_timestamp() or a.user_id::text is distinct from p_fence->>'user_id' or
   a.project_id is distinct from p_fence->>'project_id' or p.source_sequence<>a.source_high_water or
   p.policy_epoch<>a.policy_epoch or c.preference_revision<>a.preference_revision or
   a.source_high_water is distinct from (p_fence->>'source_high_water')::bigint or
   a.policy_epoch is distinct from (p_fence->>'policy_epoch')::bigint or
   a.preference_revision is distinct from (p_fence->>'preference_revision')::bigint or
   coalesce(a.selection,'null'::jsonb) is distinct from coalesce(p_fence->'selection','null'::jsonb) or
   exists(select 1 from public.user_lifetime_pending_policy q where q.user_id=a.user_id and q.project_id=a.project_id) or
   exists(select 1 from public.user_lifetime_policy_inventory_pending q where q.user_id=a.user_id and q.project_id=a.project_id) then
   raise exception 'stale background agent' using errcode='42501';end if;
 return extract(epoch from least(a.lease_until,a.run_deadline)-clock_timestamp());
end $$;

CREATE FUNCTION public.read_memoir_background_work(p_fence jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$
declare a public.user_memoir_background_agent%rowtype; source public.user_narrator_source%rowtype;
 authority public.user_lifetime_profile_authority%rowtype; source_work jsonb; targets jsonb; reference jsonb;
 core integer; lo integer; hi integer; names jsonb:='["memoir-author-timeline","memoir-place-journey"]';
begin
 perform public.lock_memoir_background_agent(p_fence);
 select * into a from public.user_memoir_background_agent where id=(p_fence->>'id')::uuid;
 if exists(select 1 from public.user_memoir_lane where user_id=a.user_id and project_id=a.project_id
     and skill='timeline' and (pending or token is not null and (lease_until<=clock_timestamp() or run_deadline<=clock_timestamp()))
     and attempts<3 and available_at<=clock_timestamp()
     and (token is null or lease_until<=clock_timestamp() or run_deadline<=clock_timestamp())) then
   select * into source from public.user_narrator_source where user_id=a.user_id and project_id=a.project_id
     and status='active' and processing_status<>'succeeded' and sequence<=a.source_high_water order by sequence limit 1;
   if found then
     select coalesce((select next_offset from public.user_lifetime_source_extraction where user_id=a.user_id
       and project_id=a.project_id and source_id=source.id and source_version=source.version),0) into core;
     if core>=length(source.text) then core:=0;end if;
     lo:=greatest(core-256,0);hi:=least(core+2048,length(source.text));
     perform public.ensure_lifetime_profile_authority(a.user_id);
     select * into authority from public.user_lifetime_profile_authority where user_id=a.user_id;
     select coalesce(jsonb_agg(f),'[]') into targets from unnest(array['name','birth_year','birth_date_expression',
       'birth_place','childhood_place','avatar_style']) f where not(authority.field_locks ? f);
     select coalesce(jsonb_object_agg(f,p.profile->f),'{}') into reference from public.user_profile p,
       unnest(array['name','birth_year','birth_date_expression','birth_place','childhood_place','avatar_style']) f
       where p.user_id=a.user_id and octet_length(coalesce((p.profile->f)::text,''))<=1024;
     if authority.auto_enabled and not authority.manual_complete and jsonb_array_length(targets)>0 then
       names:=names||'"memoir-memory-context"'::jsonb;
     else targets:='[]';end if;
     source_work:=jsonb_build_object('source',jsonb_build_object('id',source.id,'project_id',source.project_id,
       'version',source.version,'sequence',source.sequence,'text',substring(source.text from lo+1 for hi-lo),
       'char_start',lo,'char_end',hi,'original_length',length(source.text),'kind',source.kind,
       'language',source.language,'status',source.status,'author_role','storyteller'),
       'available_skills',names,'profile_reference',reference,'profile_targets',targets,
       'recent_dialogue',public.lifetime_question_dialogue(a.user_id,a.project_id,source.id,a.source_high_water))
       ||public.lifetime_timeline_context(a.user_id,a.project_id,source.id);
   end if;
 end if;
 return jsonb_build_object('lanes',coalesce((select jsonb_agg(jsonb_build_object('id',id,'skill',skill))
   from public.user_memoir_lane where user_id=a.user_id and project_id=a.project_id and skill in ('timeline','composer') and attempts<3
   and (pending or token is not null and (lease_until<=clock_timestamp() or run_deadline<=clock_timestamp()))
   and available_at<=clock_timestamp() and (token is null or lease_until<=clock_timestamp() or run_deadline<=clock_timestamp())),'[]'),
   'selection',a.selection,'source_work',source_work);
end $$;

CREATE FUNCTION public.select_lifetime_source_skills(p_lane_id uuid,p_token uuid,p_source jsonb,p_skills jsonb) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$
declare snap public.user_lifetime_lane_snapshot%rowtype; page jsonb; source_key jsonb;
begin
 snap:=public.lock_lifetime_memoir_lane(p_lane_id,p_token);
 page:=public.read_lifetime_memoir_lane_page(p_lane_id,p_token);
 if page->>'skill'<>'timeline' then return false;end if;
 if p_source is null or p_source='null'::jsonb then
   if p_skills<>'[]'::jsonb or (page->'source'<>'null'::jsonb and not(page ? 'memory_summary')) then return false;end if;
 else
   if page->'complete'<>'false'::jsonb or page ? 'memory_summary'
     or page->'source' is distinct from p_source then return false;end if;
 end if;
 if jsonb_typeof(p_skills) is distinct from 'array' or jsonb_array_length(p_skills)>3
   or exists(select 1 from jsonb_array_elements(p_skills) s where jsonb_typeof(s)<>'string'
     or s#>>'{}' not in ('memoir-author-timeline','memoir-place-journey','memoir-memory-context'))
   or (select count(*)<>count(distinct s) from jsonb_array_elements(p_skills) s) then
   raise exception 'valid source skill selection required' using errcode='22023';end if;
 source_key:=jsonb_build_object('id',p_source->'id','version',p_source->'version',
   'char_start',p_source->'char_start','char_end',p_source->'char_end');
 -- A retry resumes the saved choice for this exact source window.
 if snap.source_decision->'source'=source_key then return true;end if;
 update public.user_lifetime_lane_snapshot set source_decision=jsonb_build_object(
   'source',source_key,'skills',p_skills) where id=snap.id;
 if not(p_skills ? 'memoir-memory-context') then
   update public.user_lifetime_profile_progress set skipped_round=greatest(skipped_round,requested_round),active_round=0
     where user_id=snap.user_id and project_id=snap.project_id;
 end if;
 return true;
end $$;
REVOKE ALL ON FUNCTION public.select_lifetime_source_skills(uuid,uuid,jsonb,jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.select_lifetime_source_skills(uuid,uuid,jsonb,jsonb) TO service_role;

CREATE FUNCTION public.advance_memoir_background_profile(p_fence jsonb,p_lane_id uuid,p_page_digest text) RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$
declare revision bigint;
begin
 update public.user_memoir_background_agent a set preference_revision=c.preference_revision
 from public.user_lifetime_conversation c,public.user_memoir_project p
 where a.id=(p_fence->>'id')::uuid and a.token=(p_fence->>'token')::uuid
   and a.user_id::text=p_fence->>'user_id' and a.project_id=p_fence->>'project_id'
   and a.preference_revision=(p_fence->>'preference_revision')::bigint
   and a.lease_until>clock_timestamp() and a.run_deadline>clock_timestamp()
   and c.user_id=a.user_id and c.project_id=a.project_id
   and p.user_id=a.user_id and p.project_id=a.project_id
   and p.source_sequence=a.source_high_water and p.policy_epoch=a.policy_epoch
   and exists(select 1 from public.user_lifetime_profile_receipt r
     join public.user_lifetime_lane_snapshot s on s.id=r.snapshot_id
     where r.user_id=a.user_id and r.project_id=a.project_id and r.page_digest=p_page_digest
       and s.lane_id=p_lane_id and s.preference_revision=c.preference_revision)
 returning a.preference_revision into revision;
 if revision is null then raise exception 'profile write changed background scope' using errcode='PT409';end if;
 return revision;
end $$;
REVOKE ALL ON FUNCTION public.advance_memoir_background_profile(jsonb,uuid,text) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.advance_memoir_background_profile(jsonb,uuid,text) TO service_role;

CREATE FUNCTION public.heartbeat_memoir_background_agent(p_id uuid,p_token uuid) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$
begin
 update public.user_memoir_background_agent set lease_until=least(clock_timestamp()+interval '60 seconds',run_deadline)
 where id=p_id and token=p_token and lease_until>clock_timestamp() and run_deadline>clock_timestamp();
 return found;
end $$;

CREATE FUNCTION public.finish_memoir_background_agent(p_id uuid,p_token uuid,p_success boolean) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$
declare a public.user_memoir_background_agent%rowtype; remaining boolean; blocked boolean; changed boolean;
begin
 select * into a from public.user_memoir_background_agent where id=p_id;
 if not found then return jsonb_build_object('status','stale','pending',true);end if;
 perform 1 from public.user_memoir_project where user_id=a.user_id and project_id=a.project_id for share;
 perform 1 from public.user_lifetime_conversation where user_id=a.user_id and project_id=a.project_id for share;
 select * into a from public.user_memoir_background_agent where id=p_id for update;
 if not found or a.token is null or a.token is distinct from p_token then return jsonb_build_object('status','stale','pending',true);end if;
 changed:=a.pending or
   exists(select 1 from public.user_memoir_project p where p.user_id=a.user_id and p.project_id=a.project_id
     and (p.source_sequence<>a.source_high_water or p.policy_epoch<>a.policy_epoch)) or
   exists(select 1 from public.user_lifetime_conversation c where c.user_id=a.user_id and c.project_id=a.project_id
     and c.preference_revision<>a.preference_revision);
 remaining:=p_success is not true or changed or exists(select 1 from public.user_memoir_lane l
   where l.user_id=a.user_id and l.project_id=a.project_id and l.skill in ('timeline','composer') and (l.pending or l.token is not null));
 if not changed and p_success is not true and a.attempts>=3 then
   update public.user_memoir_lane set attempts=3,error='MEMOIR_UNAVAILABLE',pending=true,
     token=null,lease_until=null,run_deadline=null
   where user_id=a.user_id and project_id=a.project_id and skill in ('timeline','composer') and (pending or token is not null)
     and (token is null or lease_until<=clock_timestamp() or run_deadline<=clock_timestamp());
 end if;
 blocked:=exists(select 1 from public.user_memoir_lane l where l.user_id=a.user_id and l.project_id=a.project_id and l.skill in ('timeline','composer')
   and (l.pending or l.token is not null) and l.attempts>=3);
 update public.user_memoir_background_agent set token=null,lease_until=null,run_deadline=null,
   attempts=case when blocked then 3 when changed or p_success then 0 else attempts end,
   pending=remaining,available_at=clock_timestamp()+interval '5 seconds',selection=case when remaining then selection end
 where id=p_id;
 return jsonb_build_object('status',case when remaining and (blocked or not changed and p_success is not true and a.attempts>=3) then 'retry_required'
   when remaining then 'pending' else 'finished' end,'pending',remaining);
end $$;

REVOKE ALL ON FUNCTION public.queue_user_memoir_background_agent(text,jsonb),public.pending_memoir_background_agents(integer),
 public.claim_memoir_background_agent(uuid,integer),public.lock_memoir_background_agent(jsonb),
 public.read_memoir_background_work(jsonb),public.heartbeat_memoir_background_agent(uuid,uuid),
 public.finish_memoir_background_agent(uuid,uuid,boolean) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.queue_user_memoir_background_agent(text,jsonb) TO authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.pending_memoir_background_agents(integer),public.claim_memoir_background_agent(uuid,integer),
 public.lock_memoir_background_agent(jsonb),public.read_memoir_background_work(jsonb),
 public.heartbeat_memoir_background_agent(uuid,uuid),public.finish_memoir_background_agent(uuid,uuid,boolean) TO service_role;

notify pgrst, 'reload schema';
commit;
